function Utils.now()
    return os.clock()
end

function Utils.json(gb)
    local hb, ib = pcall(HttpService.JSONEncode, HttpService, gb)
    return hb and ib or "{}"
end

function Utils.unjson(jb)
    local kb, mb = pcall(HttpService.JSONDecode, HttpService, jb)
    return kb and mb or nil
end

function Utils.readJson(nb)
    local ob, pb = pcall(function()
        return isfile(nb) and readfile(nb) or nil
    end)
    return ob and pb and Utils.unjson(pb) or nil
end

function Utils.writeJson(qb, rb)
    pcall(function()
        if not isfolder(Core.FOLDER) then
            makefolder(Core.FOLDER)
        end
    end)
    pcall(writefile, qb, Utils.json(rb))
end

function Utils.fmt(sb)
    sb = tonumber(sb) or 0
    if sb >= 1e6 then
        return string.format("%.2fM", sb / 1e6)
    end
    if sb >= 1e4 then
        return string.format("%.1fk", sb / 1e3)
    end
    return tostring(math.floor(sb + 0.5))
end

function Utils.clamp(tb, ub, vb)
    return math.max(ub, math.min(vb, tb))
end

function Utils.count(wb)
    local xb = 0
    for yb in pairs(wb or {
    }) do
        xb = xb + 1
    end
    return xb
end

function Utils.list(zb)
    if type(zb) ~= "table" then
        return {
        }
    end
    if # zb > 0 then
        return zb
    end
    local Ab = {
    }
    for Bb in pairs(zb) do
        table.insert(Ab, Bb)
    end
    table.sort(Ab, function(Cb, Db)
        return (tonumber(Cb) or 0) < (tonumber(Db) or 0)
    end)
    local Eb = {
    }
    for Fb, Gb in ipairs(Ab) do
        table.insert(Eb, zb [Gb])
    end
    return Eb
end

function Utils.flat(Hb)
    return Vector3.new(Hb.X, 0, Hb.Z)
end

function Utils.plain(Ib, Jb)
    local Kb = type(Ib)
    if Kb == "number" or Kb == "string" or Kb == "boolean" then
        return Ib
    end
    if Kb ~= "table" or (Jb or 0) > 6 then
        return nil
    end
    local Lb = {
    }
    for Mb, Nb in pairs(Ib) do
        if type(Mb) == "number" or type(Mb) == "string" then
            Lb [Mb] = Utils.plain(Nb, (Jb or 0) + 1)
        end
    end
    return Lb
end

function App.log(Ob, Pb, Qb)
    if Ob > (Config.logLevel or 1) then
        return
    end
    local Rb = string.format("[%s] %-7s %s", os.date("%H:%M:%S"), Pb, tostring(Qb))
    table.insert(LogBuffer.lines, Rb)
    if GUI.activityLog then
        pcall(function()
            GUI.activityLog:Push(GUI.escape(Rb), Ob == 0 and "Error" or nil)
        end)
    end
    if # LogBuffer.lines > 250 then
        table.remove(LogBuffer.lines, 1)
    end
    table.insert(LogBuffer.pending, Rb)
    local Sb = tostring(Qb):lower()
    if Sb:find("refused") or Sb:find("error") or Sb:find("timeout") or Pb == "FATAL" then
        LogBuffer.problems = LogBuffer.problems or {
        }
        table.insert(LogBuffer.problems, Rb)
        if # LogBuffer.problems > 30 then
            table.remove(LogBuffer.problems, 1)
        end
    end
    if Config.logConsole then
        print("[AA] " .. Rb)
    end
end

function App.status(Tb, Ub)
    Status [Tb] = Ub
end

function App.flush()
    if # LogBuffer.pending == 0 then
        return
    end
    local Vb = table.concat(LogBuffer.pending, "\n") .. "\n"
    table.clear(LogBuffer.pending)
    pcall(function()
        if not isfolder(Core.FOLDER) then
            makefolder(Core.FOLDER)
        end
        if appendfile and isfile(Core.LOGFILE) then
            appendfile(Core.LOGFILE, Vb)
        else
            writefile(Core.LOGFILE, Vb)
        end
    end)
end
task.spawn(function()
    while App.alive do
        task.wait(3)
        App.flush()
    end
end)
do
    local Wb = Utils.readJson(Core.SETTINGS) or {
    }
    if Wb.shareChosen ~= true then
        Wb.shareStats = nil
    end
    if Wb.autoTeamChosen ~= true then
        Wb.autoTeam = nil
    end
    for Xb, Yb in pairs(Core.DEFAULTS) do
        if Wb [Xb] ~= nil and type(Wb [Xb]) == type(Yb) then
            Config [Xb] = Wb [Xb]
        else
            Config [Xb] = Yb
        end
    end
    Config.seenVersion = type(Wb.seenVersion) == "string" and Wb.seenVersion or nil
    if Wb.griffinWatch == true and Wb.snipeUnit == nil then
        Config.snipeOn, Config.snipeUnit = true, "griffith"
    end
    if Config.pickPortal == "off" then
        Config.portals, Config.pickPortal = false, "smart"
    end
    Config.useHive, Config.shareStats = false, false
    Config.cfgv = 1
    if not Config.simpleGui then
        Config.simpleGui = true
        if not Config.play then
            Config.master = false
        end
        Config.play = true
        for Zb, _b in ipairs({
            "dailyChallenge",
            "challenge",
            "firstClears",
            "raids",
            "event",
            "farm",
            "infinite",
            "dungeon"
        }) do
            Config [_b] = true
        end
    end
end

function App.saveSoon()
    App.saveAt = Utils.now() + 1.5
end

function App.saveNow()
    Utils.writeJson(Core.SETTINGS, Config)
    Utils.writeJson(Core.BRAIN, Brain)
    App.flush()
end
