        500,
        550,
        650
    }
    local wc = {
        1,
        1.0447,
        1.09139809,
        1.1401835846,
        1.1911497909,
        1.3366844723
    }
    local xc = {
        hxhant = 0.5,
        magnolia = 0.6,
        jjk = 0.7
    }
    local yc = {
    }
    function yc.calculate_level_diff_scale(zc, Ac, Bc)
        if Bc and (Bc._use_max or Bc._is_daily_challenge or Bc._is_event_challenge) then
            return wc [6]
        end
        if Ac == "story" or Ac == "challenge" then
            return wc [zc or 6] or wc [6]
        end
        return wc [6]
    end
    function yc.calculate_world_diff_scale(Cc, Dc, Ec, Fc, Gc)
        local Hc = vc [# vc] * 1.5
        if Gc and Gc._is_event_challenge then
            return 0.5 * Hc
        end
        if Gc and (Gc._use_max or Gc._is_daily_challenge) then
            return Hc
        end
        local Ic = vc [Cc or # vc] or vc [# vc]
        if Dc == "story" or Dc == "raid" then
            Ic = Ic * ((Cc or # vc) < 12 and 0.6 or 0.7)
        end
        return Ic * 1.5 * (xc [Fc] or 1)
    end
    function yc.calculate_world_resource_scale(Jc, Kc)
        local Lc = 1.7411011266
        if Jc and Jc <= 5 and (Kc == "story" or Kc == "infinite" or Kc == "challenge") then
            Lc = ({
                1,
                1.148698355,
                1.3195079108,
                1.5157165665,
                1.7411011266
            }) [Jc]
        end
        return Lc * 1.5
    end
    function yc.calculate_multiplayer_diff_scale(Mc, Nc, Oc)
        if Oc._event_contract then
            return 1
        end
        if Oc._override_multiplayer_diff_scale then
            return 1 + (Nc - 1) * Oc._override_multiplayer_diff_scale
        end
        if Oc._is_daily_challenge then
            return 4
        end
        if Oc._is_event_challenge or Oc._no_multiplayer_scale then
            return 1
        end
        if Mc == "story" or Mc == "challenge" or Mc == "infinite" or Mc == "infinite_tower" then
            return 1 + (Nc - 1) * (Oc.world == "bleach_legend" and 1 / 6 or (Oc.world == "jojo_legend" and 0.3 or 0.6))
        end
        if Mc == "raid" then
            if Oc.id == "jojo_portal_pucci" then
                return 0.3
            end
            if Oc.portal_group or Oc._raid_multiplayer_scale then
                return 1 + (Nc - 1) * 0.3
            end
            return Oc.id ~= "namek_anniversary" and 8 or 8 * (1 + (Nc - 1) * 0.5)
        end
        return 1
    end
    local Pc = {
        opm_infinite = 0.8,
        jojo_infinite = 0.7,
        sao_infinite = 0.7,
        berserk_infinite = 0.7,
        overlord_infinite = 0.7,
        fate_infinite = 0.7
    }
    yc.Infinite = {
        infinite_max_unit_wave = 100,
        initial_wave_template = {
            wave_reward = 1500,
            wave_diff_scale = 1
        },
        infinite_diff_scale = function(Qc,
            Rc)
            local Sc
            if Qc <= 20 then
                Sc = math.exp(0.165 * Qc) * 0.257116 + 0.187431
            elseif Qc <= 50 then
                if Rc == "april2_event" then
                    Sc = math.pow(Qc - 1,
                    2.9) / 500 + 2
                elseif Rc == "halloween2_event" or Rc == "christmas_event" then
                    Sc = math.pow(Qc - 1,
                    2.4) / 400 + 4.2
                else
                    Sc = math.pow(Qc - 1,
                    2.48) / 400 + 4.2
                end
            else
                Sc = math.max(32,
                math.pow(Qc - 1,
                2.8) / 400 - 92)
            end
            if Pc [Rc] then
                return Sc * Pc [Rc]
            end
            if Rc == "halloween2_event" or Rc == "christmas_event" or Rc == "april2_event" then
                Sc = Sc * 0.85
                if Rc == "christmas_event" then
                    Sc = Sc * 0.75
                end
            end
            return Sc
        end,
        infinite_amt_scale = function(Tc,
            Uc)
            local Vc
            if Tc <= 1 then
                Vc = 3
            elseif Tc < 9 then
                Vc = math.pow(Tc - 1,
                2) / 5 + 5
            else
                Vc = math.pow(Tc - 1,
                1.4) / 5 + 15
            end
            if Uc and Uc._tournament and Uc._tournament.tournament_id == "3" then
                Vc = math.min(Vc / 3,
                5)
            end
            return math.min(Vc,
            60)
        end,
        infinite_get_normal_unit_chance = function(Wc,
            Xc)
            if Wc.min_inf_wave and Xc < Wc.min_inf_wave then
                return 0
            end
            local Yc = Wc.spawn_tier_normal
            if not Yc then
                return 0
            end
            local Zc = math.min(Xc - 1,
            100) / 100
            local _c,
            bd
            if Yc <= 2 then
                _c,
                bd = 5,
                5
            elseif Yc == 3 then
                _c,
                bd = 3,
                6
            elseif Yc == 4 then
                _c,
                bd = 1,
                6
            elseif Yc <= 7 then
                _c,
                bd = 0,
                5
            else
                _c,
                bd = 0,
                2
            end
            return _c + (bd - _c) * Zc
        end,
        infinite_get_boss_unit_chance = function(dd,
            ed)
            if dd.min_inf_wave and ed < dd.min_inf_wave then
                return 0
            end
            if ed <= 10 then
                return dd.spawn_tier_boss == 1 and 1 or 0
            end
            return dd.spawn_tier_boss and 1 or 0
        end
    }
    local fd = Core.core("LevelUtilCore")
    yc.xp_items_order = fd and fd.xp_items_order
    return yc
end)()
