function Core.cur(kd)
    local md = LocalPlayer:FindFirstChild("_stats")
    local od = md and ((kd == "gems" and md:FindFirstChild("gem_amount")) or (kd == "gold" and md:FindFirstChild("gold_amount")) or md:FindFirstChild("_resource" .. kd))
    if od then
        return tonumber(od.Value) or 0
    end
    local pd = Core.prof()
    if kd == "gems" then
        return tonumber(pd and pd.gem_amount) or 0
    end
    if kd == "gold" then
        return tonumber(pd and pd.gold_amount) or 0
    end
    return tonumber(pd and pd.resources and pd.resources [kd]) or 0
end
