    back = {
    },
    fails = {
    },
    calls = {
    }
}
App.BUDGET = {
    upg = 30,
    place = 15
}

function App.request(qd, sd, ...)
    local td = App.req
    local ud = Utils.now()
    if td.back [qd] and ud < td.back [qd] then
        return false, "waiting"
    end
    local vd = td.calls [qd] or {
    }
    td.calls [qd] = vd
    while vd [1] and ud - vd [1] > 10 do
        table.remove(vd, 1)
    end
    if # vd >= (App.BUDGET [qd] or 8) then
        td.back [qd] = ud + 3
        return false, "slowing down"
    end
    table.insert(vd, ud)
    if not (ReplicatedStorage:FindFirstChild("endpoints") and ReplicatedStorage.endpoints.client_to_server:FindFirstChild(sd)) then
        return false, "no remote " .. sd
    end
    local wd = table.pack(...)
    local xd, yd, zd, Ad = false, false, nil, nil
    task.spawn(function()
        yd, zd, Ad = pcall(function()
            return Core.EP.invoke_server(sd, table.unpack(wd, 1, wd.n))
        end)
        xd = true
    end)
    local Bd = Utils.now()
    while not xd and Utils.now() - Bd < 15 do
        task.wait(0.05)
    end
    if not xd then
        td.fails [qd] = (td.fails [qd] or 0) + 1
        td.back [qd] = Utils.now() + 30
        App.log(1, "NET", sd .. " timeout (no answer in 15s)")
        return false, "timeout"
    end
    if not yd then
        td.fails [qd] = (td.fails [qd] or 0) + 1
        td.back [qd] = Utils.now() + math.min(60, 2 ^ td.fails [qd])
        App.log(1, "NET", sd .. " error: " .. tostring(zd))
        return false, tostring(zd)
    end
    td.fails [qd] = 0
    return true, zd, Ad
end

function App.backoff(Cd, Dd)
    App.req.back [Cd] = Utils.now() + Dd
end

function App.listenGame()
    if App.heard then
        return
    end
    local Ed = ReplicatedStorage:FindFirstChild("endpoints") and ReplicatedStorage.endpoints:FindFirstChild("server_to_client")
    local Fd = Ed and Ed:FindFirstChild("show_message")
    if not Fd then
        return
    end
    App.heard = true
    table.insert(App.conns, Fd.OnClientEvent:Connect(function(Gd, Hd)
        if tostring(Hd) == "Error" then
            App.gameError = {
                msg = tostring(Gd),
                at = Utils.now()
            }
        end
    end))
    for Id, Jd in ipairs({
        "hatch_refresh_remaining_time_changed",
        "hatch_banner_changed"
    }) do
        local Kd = Ed:FindFirstChild(Jd)
        if Kd then
            table.insert(App.conns, Kd.OnClientEvent:Connect(function(...)
                pcall(FarmHub.snipeHeard, Jd, ...)
            end))
        end
    end
end

function App.gameSaid(Ld)
    local Md = App.gameError
    return Md and Md.at >= Ld and Md.msg or nil
end

function Spending.add(Nd, Od, Pd, Qd)
    table.insert(Brain.spend, 1, {
        at = os.time(),
        what = Nd,
        cost = Od,
        cur = Pd,
        why = Qd
    })
    while # Brain.spend > 60 do
        table.remove(Brain.spend)
    end
    App.log(1, "SPEND", string.format("%s for %s %s — %s", Nd, Utils.fmt(Od), Pd, Qd))
    App.saveSoon()
end

function Spending.text()
    if # Brain.spend == 0 then
        return "nothing spent yet"
    end
    local Rd = {
    }
    for Sd = 1, math.min(15, # Brain.spend) do
        local Td = Brain.spend [Sd]
        table.insert(Rd, string.format("%s  %s — %s %s (%s)", os.date("%b %d %H:%M", Td.at), Td.what, Utils.fmt(Td.cost), Td.cur, Td.why or ""))
    end
    return table.concat(Rd, "\n")
end
