function Units.field(Ud, Vd)
    local Wd = Core.Units [Ud]
    if type(Wd) == "table" and Wd [Vd] ~= nil then
        return Wd [Vd]
    end
    local Xd = Brain.unitData [Ud]
    if Xd then
        return Xd [Vd]
    end
    local Yd, Zd = pcall(Reports.hiveStat, Ud)
    if Yd and Zd and Zd [Vd] ~= nil then
        return Zd [Vd]
    end
    local ae = Core.FILL_UNITS [Ud]
    return ae and ae [Vd]
end

function Units.hidden(be)
    local ce = Core.Units [be]
    if not (type(ce) == "table" and ce.upgrade == nil and (tonumber(ce.cost) or 0) > 0) then
        return false
    end
    if (Brain.unitData [be] and Brain.unitData [be].upgrade) or Core.FILL_UNITS [be] then
        return false
    end
    local de, ee = pcall(Reports.hiveStat, be)
    return not (de and ee and ee.upgrade)
end

function Units.markHidden()
    local fe = 0
    for ge, he in pairs(Core.Units) do
        if type(he) == "table" and he.upgrade == nil and (tonumber(he.cost) or 0) > 0 then
            Brain.hidden [ge] = true
            fe = fe + 1
        end
    end
    return fe
end

function Units.capture()
    local ie = {
    }
    for je in pairs(Brain.hidden) do
        local ke = Core.Units [je]
        if type(ke) == "table" and type(ke.upgrade) == "table" then
            local le = {
            }
            for me, ne in ipairs(Units.KEEP) do
                if ke [ne] ~= nil then
                    le [ne] = Utils.plain(ke [ne])
                end
            end
            if not Brain.unitData [je] then
                table.insert(ie, Units.name(je))
            end
            Brain.unitData [je] = le
            Units._rows [je] = nil
        end
    end
    if # ie > 0 then
        App.log(1, "UNITS", "learned the hidden upgrade stats of " .. table.concat(ie, ", ") .. " (the game only sends them in a match)")
        App.saveSoon()
    end
end
