function Units.summonShare(oe)
    if Units.SUMMONER [oe] or (Units.DRONES and Units.DRONES [oe]) then
        return 0
    end
    local pe = Brain.str and type(Brain.str.summon) == "table" and Brain.str.summon [oe]
    return type(pe) == "table" and Utils.clamp(tonumber(pe.s) or 0, 0, 1) or 0
