function Units.rows(qe)
    if Units._rows [qe] then
        return Units._rows [qe]
    end
    local re = Core.Units [qe]
    if type(re) ~= "table" then
        return nil
    end
    local se = Units.SUMMONER [qe] and Units.SUMMONER [qe].rate or 1
    local te = {
        cost = re.cost or 0,
        damage = re.damage or 0,
        cd = (re.attack_cooldown or 0) * se,
        range = re.range or 0,
        farm = Units.field(qe,
        "farm_amount") or 0,
        atk = Units.field(qe,
        "primary_attack_no_upgrades") or Units.field(qe,
        "primary_attack"),
        active = Units.field(qe,
        "active_attack")
    }
    local ue = Units.field(qe, "active_attack_stats")
    te.activeCd = type(ue) == "table" and tonumber(ue.attack_cooldown) or nil
    local ve = {
        [0] = table.clone(te)
    }
    local we = Units.field(qe, "upgrade") or {
    }
    for xe, ye in ipairs(we) do
        te = table.clone(te)
        te.cost = ye.cost or 0
        if ye.damage then
            te.damage = ye.damage
        end
        if ye.attack_cooldown then
            te.cd = ye.attack_cooldown * se
        end
        if ye.range then
            te.range = ye.range
        end
        if ye.farm_amount then
            te.farm = ye.farm_amount
        end
        if ye.primary_attack then
            te.atk = ye.primary_attack
        end
        if ye.active_attack then
            te.active = ye.active_attack
        end
        if type(ye.active_attack_stats) == "table" and tonumber(ye.active_attack_stats.attack_cooldown) then
            te.activeCd = tonumber(ye.active_attack_stats.attack_cooldown)
        end
        ve [xe] = te
    end
    ve.max = # we
    local ze = Units.SUMMONER [qe] and Units.SUMMONER [qe].atk
    if ze then
        for Ae = 0, ve.max do
            ve [Ae].atk = ze
        end
    end
    Units._rows [qe] = ve
    return ve
end

