function Units.fillAlias(Ce)
    local De, Ee = tostring(Ce):match("^(.-):([^:]+)$")
    if not De or De:find("|", 1, true) then
        return nil
    end
    local Fe
    for Ge, He in pairs(Core.FILL_ATTACKS) do
        if Ge:match(":([^:]+)$") == Ee then
            if Ge:sub(1, # De + 1) == De .. "|" then
                return He
            end
            if Ge:sub(1, # De + 1) == De .. "_" and Ge:find("|", # De + 2, true) then
                Fe = Fe or He
            end
        end
    end
    return Fe
end

function Units.fillAttack(Ie)
    if Units._fill [Ie] ~= nil then
        return Units._fill [Ie]
    end
    local Je = Core.FILL_ATTACKS [Ie] or Units.fillAlias(Ie)
    local Ke = false
    if Je then
        local Le = Je.k == "c" and {
            type = "circle",
            radius = Je.r
        } or Je.k == "n" and {
            type = "cone",
            angle = Je.r
        } or Je.k == "f" and {
            type = "full_aoe"
        } or Je.k == "l" and {
            type = "straight"
        } or {
        }
        local Me = {
        }
        if Je.slow then
            table.insert(Me, {
                name = "slow",
                time = Je.t,
                params = {
                    slow_percent = Je.slow
                }
            })
        end
        if Je.stun then
            table.insert(Me, {
                name = "stun",
                time = Je.stun,
                params = {
                }
            })
        end
        if Je.freeze then
            table.insert(Me, {
                name = "freeze",
                time = Je.freeze,
                params = {
                }
            })
        end
        if Je.knock then
            table.insert(Me, {
                name = "knockback",
                time = Je.knock,
                params = {
                }
            })
        end
        if Je.amp then
            table.insert(Me, {
                name = "amplify",
                time = 1,
                params = {
                    amplification = Je.amp,
                    persistent = Je.keep
                }
            })
        end
        if Je.dot then
            table.insert(Me, {
                name = Je.dot,
                time = Je.ticks,
                params = {
                    damage_rate = Je.rate
                }
            })
        end
        local Ne = Je.h or 1
        local Oe = {
        }
        for Pe = 1, Ne do
            Oe [Pe] = {
                aoe_type = Le,
                hit = {
                    damage = 1 / Ne,
                    buffs = Pe == 1 and Me or nil
                }
            }
        end
        Ke = {
            aoe = Oe
        }
    end
    Units._fill [Ie] = Ke
    return Ke
end

function Units.attackInfo(Qe, Re)
    local Se = tostring(Qe) .. ":" .. tostring(Re and math.floor(Re) or "")
    if Units._atk [Se] then
        return Units._atk [Se]
    end
    local Te = {
        n = 1,
        dot = 0,
        slow = 0,
        stun = 0,
        amp = 0,
        ampPersist = false,
        hits = 0,
        bleed = false,
        slowPct = 0,
        slowTime = 0
    }
    local Ue = Qe and (Core.Attacks [Qe] or Units.fillAttack(Qe))
    if type(Ue) ~= "table" then
        Te.hits = 1
        Units._atk [Se] = Te
        return Te
    end
    local Ve = 0
    local function We(Xe, Ye)
        if type(Xe) ~= "table" then
            return
        end
        local Ze = type(Xe.aoe_type) == "table" and Xe.aoe_type or {
        }
        local _e = type(Xe.hit) == "table" and Xe.hit or {
        }
        local af = tonumber(_e.damage) or 1
        if _e.break_shields then
            Te.breakShields = true
        end
        local bf = 1
        if Ze.type == "target_aoe_circ" or Ze.type == "circle" or Ze.type == "circ" then
            bf = 1 + (tonumber(Ze.radius) or 4) / 5
        elseif Ze.type == "cone" then
            bf = 1 + (tonumber(Ze.angle) or 45) / 60
        elseif Ze.type == "full_aoe" or Ze.type == "full" then
            bf = 3
            if not Xe.hit_allies then
                Te.full = true
            end
        elseif Ze.type == "straight" or Ze.type == "line" then
            bf = 1 + (tonumber(Ze.length) or tonumber(Re) or 10) / 15
        end
        if not Xe.hit_allies then
            Ve = Ve + af * Ye * math.min(bf, 4)
            Te.hits = Te.hits + Ye
        end
        for cf, df in pairs(_e.buffs or {
        }) do
            if type(df) == "table" and type(df.name) == "string" then
                local ef = type(df.params) == "table" and df.params or {
                }
                local ff = tonumber(df.time) or 0
                if Xe.hit_allies then
                    if df.name:find("^damage_buff__") and type(ef.damage_types) == "table" then
                        local gf = {
                        }
                        for hf, jf in pairs(ef.damage_types) do
                            gf [hf] = type(jf) == "table" and tonumber(jf.rate) or 0
                        end
                        Te.ally = {
                            types = gf,
                            time = ff
                        }
                    elseif df.name == "attack_cooldown_buff" then
                        Te.allyCd = {
                            reduce = tonumber(ef.attack_cooldown_reduce) or 0,
                            time = ff
                        }
                    elseif df.name == "range_buff" then
                        Te.allyRange = {
                            add = tonumber(ef.range_add) or 0,
                            time = ff
                        }
                    end
                else
                    if tonumber(ef.damage_rate) then
                        Te.dot = Te.dot + tonumber(ef.damage_rate) * math.max(1, ff)
                    end
                    if df.name:find("bleed") or df.name:find("wither") or df.name:find("decay") then
                        Te.bleed = true
                    end
                    if df.name == "slow" then
                        Te.slow = math.max(Te.slow, (tonumber(ef.slow_percent) or 0.3) * ff)
                        Te.slowPct, Te.slowTime = math.max(Te.slowPct, tonumber(ef.slow_percent) or 0.3), math.max(Te.slowTime, ff)
                    elseif df.name == "stun" or df.name == "freeze" or df.name == "haki_stun" then
                        Te.stun = math.max(Te.stun, ff)
                    elseif df.name == "knockback" or df.name == "walk_back" or df.name == "walk_back_time" then
                        Te.stun = math.max(Te.stun, ff * 0.5)
                    elseif tonumber(ef.amplification) then
                        Te.amp = math.max(Te.amp, tonumber(ef.amplification))
                        if ef.persistent then
                            Te.ampPersist = true
                        end
                    end
                    if Units.CC_COOLDOWN [df.name] then
                        Te.ccCd = math.max(Te.ccCd or 0, Units.CC_COOLDOWN [df.name])
                    end
                end
            end
        end
    end
    for kf, lf in pairs(type(Ue.aoe) == "table" and Ue.aoe or {
    }) do
        We(lf, 1)
    end
    for mf, of in pairs(type(Ue.aoe_dot) == "table" and Ue.aoe_dot or {
    }) do
        if type(of) == "table" and type(of.aoe) == "table" then
            We(of.aoe, (tonumber(of.time) or 1) / math.max(0.1, tonumber(of.interval) or 1))
            if type(of.first_aoe) == "table" then
                We(of.first_aoe, 0)
            end
        end
    end
    for pf, qf in pairs(type(Ue.hit) == "table" and Ue.hit or {
    }) do
        if type(qf) == "table" and qf.damage then
            Te.hits = Te.hits + 1
        end
    end
    Te.globalCd = Ue.global_cooldown and true or false
    for rf, sf in pairs(type(Ue.global_hit) == "table" and Ue.global_hit or {
    }) do
        if type(sf) == "table" then
            Te.wholeMap = true
            We({
                hit = sf,
                hit_allies = sf.hit_allies,
                aoe_type = {
                    type = "full_aoe"
                }
            }, 0)
        end
    end
    for tf, uf in pairs(type(Ue.buff) == "table" and Ue.buff or {
    }) do
        for vf, wf in pairs(type(uf) == "table" and uf or {
        }) do
            local xf = type(wf) == "table" and wf.buff_config
            local yf = type(xf) == "table" and type(xf.params) == "table" and xf.params or {
            }
            if tonumber(yf.damage_add) and not yf.persistent then
                Te.selfDmg = {
                    add = tonumber(yf.damage_add),
                    time = tonumber(xf.time) or 0
                }
            end
        end
    end
    if type(Ue.on_base_hit) == "table" and Ue.on_base_hit.prevent_hit then
        Te.baseSafe = tonumber(Ue.on_base_hit.time) or 0
    end
    Te.n = math.max(0.3, Ve > 0 and Ve or (Te.ally and 0.3 or 1))
    Te.dot = math.min(1.5, Te.dot)
    Te.hits = math.max(1, Te.hits)
    Units._atk [Se] = Te
    return Te
end

function Units.aoe(zf, Af)
    local Bf = Units.attackInfo(zf, Af)
    return Bf.n * (1 + Bf.dot)
end

function Units.teamEffect(Cf, Df, Ef, Ff)
    local Gf = Units.attackInfo(Cf, Df)
    local Hf = math.max(Ef or 1, Gf.ccCd or 0, 0.5)
    local If = math.min(1, Gf.n / 4)
    local Jf = Ff and 0 or math.min(1, (Gf.slow + Gf.stun) / Hf) * If
    local Kf = Gf.amp * (Gf.ampPersist and 1 or math.min(1, 5 / Hf)) * If
    return Jf * 0.5 + Kf
end
Units._pas = {
}

function Units.passive(Lf)
    if Units._pas [Lf] then
        return Units._pas [Lf]
    end
    local Mf = {
    }
    local Nf = Core.Units [Lf]
    for Of, Pf in pairs(type(Nf) == "table" and type(Nf.passives) == "table" and Nf.passives or {
    }) do
        if type(Pf) == "table" then
            local Qf = tostring(Pf.description or ""):gsub("<[^>]+>", "")
            if Pf.name == "Pact of Frailty" then
                Mf.mark = Mf.mark or {
                    amp = 0,
                    max = 1,
                    dot = 0
                }
                Mf.mark.amp = (tonumber(Qf:match("(%d+)%%")) or 0) / 100
                Mf.mark.max = tonumber(Qf:match("up to (%d+)")) or 1
            elseif Pf.name == "Pact of Relevation" or Pf.name == "Pact of Revelation" then
                Mf.mark = Mf.mark or {
                    amp = 0,
                    max = 1,
                    dot = 0
                }
                local Rf, Sf = Qf:match("(%d+)%%.-every ([%d%.]+)")
                Mf.mark.dot = (tonumber(Rf) or 0) / 100 / math.max(0.1, tonumber(Sf) or 1)
            end
        end
    end
    Units._pas [Lf] = Mf
    return Mf
end
