Units._bleeds = {
}

function Units.bleeds(Vf)
    local Wf = Units._bleeds [Vf]
    if Wf ~= nil then
        return Wf or nil
    end
    local Xf = Units.rows(Vf)
    local Yf = false
    if Xf then
        for Zf = 0, Xf.max do
            local ag = Xf [Zf]
            if ag and ag.atk then
                local cg, eg = pcall(Units.attackInfo, ag.atk, ag.range)
                if cg and eg and eg.bleed then
                    Yf = Zf
                    break
                end
            end
        end
    end
    Units._bleeds [Vf] = Yf
    return Yf or nil
end

function Units.bestBleeder(fg)
    local gg = Core.session()
    if not gg then
        return nil
    end
    local hg = {
    }
    for ig, jg in ipairs(fg or {
    }) do
        hg [jg.unit_id] = true
    end
    local kg, lg
    for mg, ng in pairs(gg.profile_data.collection.owned_units) do
        local og = Core.Units [ng.unit_id]
        if og and not hg [ng.unit_id] and Units.rows(ng.unit_id) and not Units.hidden(ng.unit_id) and Units.bleeds(ng.unit_id) then
            local pg, qg = pcall(Core.USC.calculate_level, ng.unit_id, tonumber(ng.xp) or 0)
            if pg and (tonumber(qg) or 0) >= 50 then
                local rg = gg.collection:get_unit_by_uuid(mg) or ng
                local sg, tg = pcall(Units.score, rg)
                if sg and (not lg or tg > lg) then
                    kg, lg = rg, tg
                end
            end
        end
    end
    return kg
end

function Units.allyBuff(ug)
    local vg = Core.Units [ug]
    if type(vg) ~= "table" or not vg.active_attack then
        return nil
    end
    local wg = Units.attackInfo(vg.active_attack)
    if not wg.ally then
        return nil
    end
    local xg = tonumber(vg.active_attack_stats and vg.active_attack_stats.attack_cooldown) or 60
    return {
        types = wg.ally.types,
        time = wg.ally.time,
        cd = xg,
        uptime = math.min(1,
        (wg.ally.time or 0) / math.max(1,
        xg)),
        attack = vg.active_attack
    }
end

function Units.buffCopies(yg)
    local zg = math.max(1, math.ceil((tonumber(yg.cd) or 60) / math.max(1, tonumber(yg.time) or 30) - 0.001))
    local Ag = Brain.stack [yg.attack]
    if Ag and Ag.stacks then
        local Bg = 0
        for Cg, Dg in pairs(yg.types or {
        }) do
            Bg = math.max(Bg, tonumber(Dg) or 0)
        end
        if Bg > 0 and yg.uptime > 0 then
            zg = math.max(zg, math.ceil((tonumber(Ag.cap) or 1) / (Bg * yg.uptime) - 0.001))
        end
    end
    return zg
end

function Units.idol(Eg)
    local Fg = Core.Units [Eg]
    if type(Fg) ~= "table" or not (Fg._NO_ATTACKS_UNIT and Fg._show_as_buff_unit) then
        return false
    end
    for Gg, Hg in pairs(Fg.passives or {
    }) do
        local Ig = type(Hg) == "table" and tostring(Hg.description or ""):lower() or ""
        if Ig:find("upgrade") and Ig:find("cost") then
            return true
        end
    end
    return false
end

function Units.mult(Jg, Kg)
    local Lg = tostring(Jg.uuid) .. Kg
    local Mg = Units._mult [Lg]
    if Mg and Utils.now() - Mg.t < 60 then
        return Mg.v
    end
    local Ng, Og = pcall(Core.USC.calculate_static_stat_multiplier, Jg, Jg.xp, Kg, Core.session())
    Og = Ng and tonumber(Og) or 1
    Units._mult [Lg] = {
        v = Og,
        t = Utils.now()
    }
    return Og
end

function Units.types(Pg)
    local Qg = Core.Units [Pg] or {
    }
    local Rg = {
        [Qg._base_damage_type or "physical"] = true
    }
    for Sg in pairs(Qg._secondary_damage_types or {
    }) do
        Rg [Sg] = true
    end
    return Rg, Qg._base_damage_type or "physical"
end

function Units.elem(Tg, Ug)
    if not Ug then
        return 1
    end
    local Vg, Wg = Units.types(Tg)
    local Xg = 1
    for Yg in pairs(Vg) do
        if Ug.weak [Yg] then
            Xg = math.max(Xg, Ug.weak [Yg])
        end
    end
    if Ug.strong [Wg] then
        Xg = Xg * 0.5
    end
    if Ug.res and Ug.res [Wg] then
        Xg = Xg * Ug.res [Wg]
    end
    return Xg
end

function Units.relic(Zg)
    local _g = Core.session()
    if not (_g and Zg._equipped_relic) then
        return 1
    end
    local ah, bh = pcall(function()
        return _g.inventory:get_item_by_uuid(Zg._equipped_relic)
    end)
    local dh = ah and bh and bh._unique_item_data and bh._unique_item_data._unique_relic_data
    if not (dh and dh._core_damage_type_buffs) then
        return 1
    end
    local eh = Units.types(Zg.unit_id)
    local gh = 1
    for hh, ih in pairs(dh._core_damage_type_buffs) do
        if type(ih) == "table" and eh [ih.damage_type] and tonumber(ih.mul) then
            gh = gh + ih.mul
        end
    end
    return gh
end

function Units.relicName(jh)
    local kh = Core.session()
    if not (kh and jh._equipped_relic) then
        return nil
    end
    local lh, mh = pcall(function()
        return kh.inventory:get_item_by_uuid(jh._equipped_relic)
    end)
    local nh = lh and mh and Core.Items [mh.item_id]
    return nh and nh.name or (lh and mh and mh.item_id) or nil
end

function Units.nudge(oh)
    local ph = Brain.learn [oh]
    if not (ph and ph.n and ph.n >= 3) then
        local qh = Reports.hiveUnit(oh)
        return qh and Utils.clamp(math.sqrt(qh.eff), 0.8, 1.35) or 1
    end
    return Utils.clamp(math.sqrt(ph.eff or 1), 0.8, 1.35)
end

function Units.trait(rh)
    for th, uh in pairs(rh.traits or {
    }) do
        if type(uh) == "table" then
            return uh.trait, uh.tier
        end
    end
    return nil
end

function Units.cap(vh)
    local wh = tonumber(Units.field(vh.unit_id, "spawn_cap")) or 1
    if Units.trait(vh) == "unique" then
        wh = 1
    end
    local xh = tonumber(Brain.caps [vh.uuid])
    if xh then
        wh = math.min(wh, xh)
    end
    return math.max(1, wh)
end
Units.GALE = {
    rukia_bankai_evolved = {
        from = 1,
        tick = 1 / 3,
        duty = 1 / 3,
        targets = 3,
        freezeEvery = 13,
        freeze = 2,
        chill = 3,
        immune = 10
    }
}
Units._galeOf = {
}

function Units.galeOf(yh)
    local zh = Units.GALE [yh]
    if not zh then
        return nil
    end
    local Ah = Brain.toggles and Brain.toggles [yh]
    if not (Ah and (Ah.nf or 0) >= 5 and (Ah.nd or 0) >= 5 and (Ah.fill or 0) > 0 and (Ah.drain or 0) > 0) then
        return zh
    end
    local Bh = Ah.fill / (Ah.fill + Ah.drain)
    local Ch = Units._galeOf [yh]
    if not (Ch and math.abs(Ch.duty - Bh) < 0.01) then
        Ch = table.clone(zh)
        Ch.duty = Bh
        Units._galeOf [yh] = Ch
    end
    return Ch
end

function Units.toggleOf(Dh)
    if Units.GALE [Dh] then
        return {
            from = Units.GALE [Dh].from,
            known = true
        }
    end
    local Eh = Brain.toggles and Brain.toggles [Dh]
    if Eh then
        return Eh
    end
    local Fh, Gh = pcall(Reports.hiveToggle, Dh)
    return Fh and Gh or nil
end

function Units.galeDps(Hh, Ih)
    local Jh = Units.galeOf(Hh)
    if not Jh or (Ih or 0) < Jh.from then
        return 0
    end
    return Jh.duty * Jh.targets * (Jh.tick + 1 / Jh.freezeEvery)
end

function Units.dps(Kh, Lh, Mh, Nh)
    local Oh = Units.rows(Kh.unit_id)
    local Ph = Oh and Oh [math.min(Lh, Oh.max)]
    if not Ph or (Ph.cd or 0) <= 0 then
        return 0
    end
    local Qh = Ph.damage * Units.mult(Kh, "damage")
    local Rh = Nh and 0 or Qh * Units.galeDps(Kh.unit_id, Lh)
    return (Qh / (Ph.cd * math.max(0.1, Units.mult(Kh, "attack_cooldown"))) * Units.aoe(Ph.atk, Ph.range) * Units.critMul(Kh.unit_id) + Rh) * Units.elem(Kh.unit_id, Mh) * Units.relic(Kh) * Units.nudge(Kh.unit_id)
end
Units._skinMul = {
}

function Units.skinMul(Sh, Th)
    local Uh = Th and Sh.skin and Sh.skin._skin_id
    local Vh = Uh and (Core.data("Skins") or {
    }) [Uh]
    if not (Vh and Vh._skin_set == Th) then
        return 1
    end
    local Wh = tonumber(Vh._damage_boost) or 0
    if Wh <= 0 then
        return 1
    end
    local Xh = tostring(Sh.uuid or Uh) .. ":" .. tostring(Th) .. ":" .. tostring(App.where)
    local Yh = Units._skinMul [Xh]
    if Yh and Utils.now() - Yh.t < 60 then
        return Yh.v
    end
    local Zh = 1 + Wh
    local _h, ai = pcall(table.clone, Sh)
    if _h and type(ai) == "table" then
        ai.skin = nil
        local bi = Core.session()
        local ci, di = pcall(Core.USC.calculate_static_stat_multiplier, Sh, Sh.xp, "damage", bi)
        local ei, fi = pcall(Core.USC.calculate_static_stat_multiplier, ai, Sh.xp, "damage", bi)
        di, fi = ci and tonumber(di), ei and tonumber(fi)
        if di and fi and fi > 0 and di / fi > 1 + Wh * 0.5 then
            Zh = 1
        end
    end
    Units._skinMul [Xh] = {
        v = Zh,
        t = Utils.now()
    }
    return Zh
end

function Units.range(gi, hi)
    local ii = Units.rows(gi.unit_id)
    local ji = ii and ii [math.min(hi, ii.max)]
    return (ji and ji.range or 10) * Units.mult(gi, "range")
end

function Units.farm(ki, li)
    local mi = Units.rows(ki.unit_id)
    local ni = mi and mi [math.min(li, mi.max)]
    return (ni and ni.farm or 0) * Units.mult(ki, "farm_amount")
end

function Units.score(oi, qi)
    local ri = Units.rows(oi.unit_id)
    if not ri then
        return 0
    end
    local si = ri.max
    return Units.dps(oi, si, qi) * math.sqrt(math.max(1, Units.range(oi, si)) / 20) * math.sqrt(Units.cap(oi))
end

function Units.name(ti)
    local ui = Core.Units [ti]
    return ui and ui.name or tostring(ti)
end

function Units.isEvolvedForm(vi)
    if not Units._evolvedForms then
        Units._evolvedForms = {
        }
        for wi, xi in pairs(Core.Units) do
            if type(xi) == "table" and type(xi.evolve) == "table" and xi.evolve.evolve_unit then
                Units._evolvedForms [xi.evolve.evolve_unit] = true
            end
        end
    end
    return Units._evolvedForms [vi] == true
end

function Units.equipped()
    local yi = Core.session()
    local zi = {
    }
    if not yi then
        return zi
    end
    for Ai, Bi in pairs(yi.profile_data.collection.equipped_units or {
    }) do
        local Ci = yi.collection:get_unit_by_uuid(Bi)
        if Ci and Core.Units [Ci.unit_id] then
            table.insert(zi, {
                slot = tonumber(Ai) or 0,
                uuid = Bi,
                u = Ci,
                id = Ci.unit_id,
                data = Core.Units [Ci.unit_id]
            })
        end
    end
    table.sort(zi, function(Di, Ei)
        return Di.slot < Ei.slot
    end)
    return zi
end

function Units.owns(Fi)
    local Gi = Core.session()
    if not Gi then
        return false
    end
    for Hi, Ii in pairs(Gi.profile_data.collection.owned_units or {
    }) do
        if Ii.unit_id == Fi or (Core.Units [Ii.unit_id] and Core.Units [Ii.unit_id].evolved and Core.Units [Ii.unit_id].evolved.from == Fi) then
            return true
        end
    end
    return false
end
