function Modes.levelMod(Ji)
    if Ji == nil then
        return nil
    end
    if Modes._levelMod [Ji] ~= nil then
        return Modes._levelMod [Ji] or nil
    end
    Modes._levelMod [Ji] = false
    local Ki = Core.Levels [Ji]
    local Li = type(Ki) == "table" and Core.Waves [Ki.waves or Ji]
    local Mi = type(Li) == "table" and Li.initial_unit_configs
    if type(Mi) ~= "table" then
        return nil
    end
    local Ni, Oi, Pi = {
    }, {
    }, 0
    for Qi, Ri in pairs(Mi) do
        local Si = type(Ri) == "table" and type(Ri.override_stats) == "table" and (Ri.override_stats [1] or Ri.override_stats ["1"]) or nil
        if type(Si) == "table" then
            local Ti = tonumber(Si.health) or 20
            Pi = Pi + Ti
            table.insert(Ni, {
                hp = Ti,
                st = Si
            })
            for Ui in pairs(Si) do
                local Vi = tostring(Ui):match("^_dmg_amp_(.+)$") or tostring(Ui):match("^_dmg_res_(.+)$")
                if Vi then
                    Oi [Vi] = true
                end
            end
        end
    end
    if not next(Oi) or Pi <= 0 then
        return nil
    end
    local Wi = {
        weak = {
        },
        strong = {
        },
        res = {
        }
    }
    for Xi in pairs(Oi) do
        local Yi = 0
        for Zi, _i in ipairs(Ni) do
            local aj = (1 + (tonumber(_i.st ["_dmg_amp_" .. Xi]) or 0)) * 100 / (100 + math.max(0, tonumber(_i.st ["_dmg_res_" .. Xi]) or 0))
            Yi = Yi + _i.hp / math.max(0.05, aj)
        end
        local bj = Pi / math.max(1, Yi)
        if bj > 1.02 then
            Wi.weak [Xi] = bj
        elseif bj < 0.98 then
            Wi.res [Xi] = bj
        end
    end
    if not (next(Wi.weak) or next(Wi.res)) then
        return nil
    end
    Modes._levelMod [Ji] = Wi
    return Wi
end

function Modes.dailyMod(cj, dj, ej)
    cj = tonumber(cj)
    local fj = cj and Random.new(cj) or nil
    local gj = {
        weak = {
        },
        strong = {
        },
        res = {
        }
    }
    for hj, ij in pairs(dj or {
    }) do
        gj.weak [ij] = fj and 1 + fj:NextNumber(0.5, 0.7) or 1.5
    end
    for jj, kj in pairs(ej or {
    }) do
        if fj then
            gj.res [kj] = 100 / (100 + fj:NextNumber(100, 150))
        else
            gj.strong [kj] = true
        end
    end
    return gj
end

