function Modes.itemValue(nj, oj)
    if Brain.goalItems [nj] then
        local pj = oj or 1
        local qj = math.min(pj, tonumber(Brain.goalNeed [nj]) or pj)
        return Brain.goalItems [nj] * qj + (Core.ITEM_VALUE [nj] or Core.ITEM_DEFAULT) * math.max(0, pj - qj)
    end
    if Config.team and Strategy.itemWorth then
        local rj, sj = pcall(Strategy.itemWorth, nj)
        if rj and sj then
            return sj * (oj or 1)
        end
    end
    local tj = Core.GS.ITEM_CAPS and Core.GS.ITEM_CAPS [nj]
    local uj = Core.session()
    local vj = 0
    pcall(function()
        vj = uj.inventory:get_number_of_owned_item(nj)
    end)
    if tj and vj >= tj then
        return 0
    end
    return (Core.ITEM_VALUE [nj] or Core.ITEM_DEFAULT) * (oj or 1)
end

function Modes.rewardValue(wj)
    local xj = 0
    for yj, zj in pairs((wj and wj._rewards) or {
    }) do
        if type(zj) == "table" then
            xj = xj + (tonumber(zj.gem_reward) or 0) + (tonumber(zj.gold_reward) or 0) * Core.GOLD_VALUE
            local Aj = Utils.list(zj.item)
            local Bj = 1
            if zj._item_multichoice and # Aj > 0 then
                Bj = math.min(1, (tonumber(zj._item_multichoice.min) or # Aj) / # Aj)
            end
            for Cj, Dj in ipairs(Aj) do
                local Ej = tonumber(Dj.amount) or ((tonumber(Dj.min_amount) or 1) + (tonumber(Dj.max_amount) or tonumber(Dj.min_amount) or 1)) / 2
                local Fj = (tonumber(Dj.chance) or 1) * (1 - (tonumber(Dj._zero_chance) or 0))
                xj = xj + Modes.itemValue(Dj.item_id, Ej) * Fj * Bj
            end
        end
    end
    return xj
end

function Modes.done(Gj, Hj, Ij)
    if Brain.cleared [Hj .. ":" .. tostring(Ij or "Normal")] then
        return true
    end
    local Jj = Gj.completed_story_levels and Gj.completed_story_levels [Hj]
    if not Jj then
        return false
    end
    if Ij and Jj.difficulty_completed_data then
        local Kj = Jj.difficulty_completed_data [Ij]
        return Kj and (Kj.times_completed or 0) > 0 or false
    end
    return (Jj.times_completed or 0) > 0
end

