function Modes.artifactLeft(Qj)
    local Rj, Sj, Tj = Core.Levels [Qj], Brain.live.artifact or {
    }, Core.prof()
    local Uj = Tj and Tj.artifact_data
    if not (type(Uj) == "table" and Uj._interval == Sj.interval) and type(Sj.ad) == "table" then
        Uj = Sj.ad
    end
    local Vj = type(Uj) == "table" and Sj.interval ~= nil and Uj._interval == Sj.interval
    local Wj = Vj and type(Uj._completed) == "table" and Uj._completed [Qj]
    local Xj = type(Wj) == "table" and type(Wj.difficulty_completed_data) == "table" and Wj.difficulty_completed_data.Hard
    local Yj = type(Xj) == "table" and tonumber(Xj.times_completed) or 0
    local Zj = Vj and type(Uj._clear_rewards) == "table" and type(Uj._clear_rewards [Qj]) == "table" and Uj._clear_rewards [Qj].Hard or {
    }
    local _j, ak = 0, 0
    for bk, ck in pairs(Rj and Rj.clear_rewards and Rj.clear_rewards.Hard or {
    }) do
        local dk = tonumber(ck.clears) or 0
        if dk > ak then
            ak = dk
        end
        if dk > Yj and not Zj [ck._id] then
            local ek = ck.reward or {
            }
            _j = _j + (tonumber(ek.gem_reward) or 0)
            for fk, gk in ipairs(Utils.list(ek.item)) do
                if type(gk) == "table" and gk.item_id then
                    _j = _j + Modes.itemValue(gk.item_id, tonumber(gk.amount) or 1)
                end
            end
        end
    end
    return Yj, _j, ak, Zj
end

