function Modes.infDaily(wk, xk, yk)
    local zk = wk.daily_infinite_reward_claims and wk.daily_infinite_reward_claims [xk]
    local Ak = tonumber(Core.GS.DAILY_INFINITE_REWARD_PERIOD) or 82800
    local Bk = (type(zk) == "table" and os.time() - (tonumber(zk.highest_claim_time) or 0) < Ak) and (tonumber(zk.highest_claimed_wave) or 0) or 0
    local Ck, Dk = 0, 0
    for Ek, Fk in ipairs(Utils.list(Core.GS.DAILY_INFINITE_REWARDS)) do
        local Gk = tonumber(Fk.wave) or 0
        if Gk > Bk and Gk <= (yk or 0) then
            Ck, Dk = Ck + (tonumber(Fk.gem_reward) or 0), math.max(Dk, Gk)
        end
    end
    return Ck, Dk, Bk
end

function Modes.infTier(Hk)
    local Ik = 0
    for Jk, Kk in ipairs(Utils.list(Core.GS.DAILY_INFINITE_REWARDS)) do
        if (tonumber(Kk.wave) or 0) <= Hk then
            Ik = math.max(Ik, tonumber(Kk.wave) or 0)
        end
    end
    return Ik
end

