function Modes.onlyOn()
    return Config.onlyRaids or Config.onlyStory or Config.onlyChallenges or (Config.onlyCoins and Modes.eventNow() ~= nil) or Config.onlyDungeons or Config.onlyLegend or Config.onlyInfinite or Config.onlyPortals or Config.onlyArtifact
end

function Modes.allowed(Pk)
    if Config.dailyLoop and Pk.kind == "daily" then
        return true
    end
    if not Modes.onlyOn() then
        return true
    end
    if Brain.nextMode and Brain.nextMode == Pk.key then
        return true
    end
    if Pk.kind == "daily" and Config.team then
        return true
    end
    if Pk.kind == "raid" then
        return Config.onlyRaids
    end
    if Pk.legend then
        return Config.onlyLegend
    end
    if Pk.kind == "story" then
        return Config.onlyStory and (Pk.picked or (Pk.first and Pk.diff == "Normal"))
    end
    if Pk.kind == "daily" or Pk.kind == "challenge" then
        return Config.onlyChallenges
    end
    if Pk.kind == "event" then
        return Config.onlyCoins
    end
    if Pk.kind == "dungeon" then
        return Config.onlyDungeons
    end
    if Pk.kind == "infinite" then
        return Config.onlyInfinite
    end
    if Pk.kind == "artifact" then
        return Config.onlyArtifact
    end
    if Pk.kind == "portal" then
        if Pk.picked or Config.onlyPortals then
            return true
        end
        for Qk, Rk in pairs(Modes.PORTALS) do
            if Rk.level == Pk.level then
                return Config.onlyInfinite and (Config.pickInfinite == "" or Config.pickInfinite == "inf:" .. Rk.from)
            end
        end
    end
    return false
end

