function Hunt.fx(ll)
    local ml = {
        dmg = 1,
        cd = 1,
        range = 1,
        cost = 1,
        hp = 1,
        speed = 1,
        regen = 0,
        crit = 0,
        kinds = {
        },
        shield = 0,
        fly = 0,
        ice = 0
    }
    if ll == "rain" then
        ml.speed = 1.2
    elseif ll == "windy" then
        ml.fly, ml.speed = 0.2, 1.25
    elseif ll == "snow" then
        ml.ice = 0.5
    elseif ll == "downpour" then
        ml.range, ml.dmg = 0.7, 0.85
    elseif ll == "mana" then
        ml.kinds.physical, ml.kinds.magic = 100 / 250 - 1, 0.25
    elseif ll == "fire" then
        ml.speed, ml.noCC = 1.5, true
    elseif ll == "underwater" then
        ml.speed = 1.25
    elseif ll == "sandstorm" then
        ml.kinds.magic, ml.kinds.physical, ml.shroud = 100 / 175 - 1, 0.25, 0.2
    elseif ll == "meteor_shower" then
        ml.starfall = Hunt.starfall()
    end
    return ml
end

function Hunt.starfall()
    local nl = type(Brain.hunt) == "table" and Brain.hunt.starfall
    if type(nl) ~= "table" or (tonumber(nl.runs) or 0) < 1 or not tonumber(nl.perWave) then
        return nil
    end
    return nl
end

function Match.noteStar(ol, pl)
    Match.stars = Match.stars or setmetatable({
    }, {
        __mode = "k"
    })
    if Match.stars [ol] then
        return
    end
    Match.stars [ol] = true
    local ql = Match.wave()
    Match.starRun = Match.starRun or {
        n = 0,
        waves = {
        },
        hpK = {
        }
    }
    local rl = Match.starRun
    rl.n = rl.n + 1
    rl.waves [ql] = (rl.waves [ql] or 0) + 1
    local sl = Match.info and Match.info.cfgById and Match.info.cfgById.star_golem_1
    local tl, ul = pcall(Simulator.enemy, Match.info, sl, ql)
    local vl = pl and tonumber(pl.MaxHealth) or 0
    if sl and tl and ul and (ul.hp or 0) > 0 and vl > 0 then
        table.insert(rl.hpK, vl / ul.hp)
    end
end

function Hunt.starfallRecord()
    local wl = Match.starRun
    if not (wl and wl.n > 0) then
        return
    end
    local xl = math.max(1, Match.wave())
    local yl = wl.n / xl
    local zl
    if # wl.hpK > 0 then
        local Al = table.clone(wl.hpK)
        table.sort(Al)
        zl = Al [math.floor(# Al / 2) + 1]
    end
    local Bl = type(Brain.hunt.starfall) == "table" and Brain.hunt.starfall or {
    }
    local Cl = (tonumber(Bl.runs) or 0) + 1
    local Dl = 1 / math.min(Cl, 5)
    Brain.hunt.starfall = {
        runs = Cl,
        perWave = Bl.perWave and (Bl.perWave + (yl - Bl.perWave) * Dl) or yl,
        hpK = zl and (Bl.hpK and (Bl.hpK + (zl - Bl.hpK) * Dl) or zl) or Bl.hpK,
        at = os.time()
    }
    local El, Fl
    for Gl in pairs(wl.waves) do
        El = math.min(El or Gl, Gl)
        Fl = math.max(Fl or Gl, Gl)
    end
    App.log(1, "STARFALL", string.format("%d Star Golems over %d waves (about %.2f a wave, from wave %s to %s), their HP ×%.2f the simulator's for a Star Golem · the simulator plays Starfall with them from now on", wl.n, xl, yl, tostring(El), tostring(Fl), zl or 0))
    return {
        n = wl.n,
        waves = xl,
        hpK = zl and math.floor(zl * 100 + 0.5) / 100 or nil
    }
end

function Hunt.perWave(Hl)
    local Il = Core.Levels [Hunt.ID]
    local Jl = Il and Il.infinite_resource_rewards and Il.infinite_resource_rewards.SummerPearls
    for Kl, Ll in ipairs(Jl or {
    }) do
        if Hl <= (tonumber(Ll.wave_up_to) or 0) then
            return tonumber(Ll.reward) or 0
        end
    end
    return 0
end

function Hunt.pearlsFrom(Ml, Nl)
    local Ol = 0
    for Pl = Ml, Nl do
        Ol = Ol + Hunt.perWave(Pl)
    end
    return Ol
end

function Hunt.board()
    local Ql = Core.core("Summer2MapBoardCore")
    local Rl = Core.prof()
    if not (Ql and Rl) then
        return nil
    end
    local Sl = Ql.get_board(LocalPlayer.UserId)
    if not Sl then
        return nil
    end
    local Tl = type(Rl._summer2_hunt_wins) == "table" and Rl._summer2_hunt_wins or {
    }
    local Ul, Vl, Wl = Tl.maps or {
    }, Tl.weathers or {
    }, Rl._summer2_map_board_claimed_lines or {
    }
    local Xl, Yl, Zl = 0, 0, 0
    for am, bm in ipairs(Sl) do
        if Ul [bm] then
            Xl = Xl + 1
        end
    end
    for cm in pairs(Ql.get_completed_lines(Sl, Ul)) do
        Yl = Yl + 1
    end
    for dm in pairs(Vl) do
        Zl = Zl + 1
    end
    return {
        core = Ql,
        board = Sl,
        maps = Ul,
        weathers = Vl,
        claimed = Wl,
        squares = Xl,
        lines = Yl,
        weathersWon = Zl,
        total = # Ql.LINES,
        claimable = Ql.get_claimable_lines(Sl,
        Ul,
        Wl)
    }
end

function Hunt.lineGems()
    return 2000 * Config.pearlValue + 10 * (Core.ITEM_VALUE.star_remnant_limited or 25)
end

function Hunt.firstValue(em, fm)
    local hm = Hunt.board()
    if not hm then
        return 0, {
        }
    end
    local im, jm = 0, {
    }
    local km = em and table.find(hm.board, em)
    if km and not hm.maps [em] then
        local lm = 0
        for mm, nm in ipairs(hm.core.LINES) do
            if table.find(nm.cells, km) then
                lm = lm + 1
            end
        end
        im = im + lm * Hunt.lineGems() / hm.core.SIZE
        table.insert(jm, "a new bingo square")
    end
    if fm and fm ~= "clear" and not hm.weathers [fm] then
        im = im + (1000 + 5000 * Config.pearlValue + 50 * (Core.ITEM_VALUE.star_remnant_limited or 25)) / Hunt.WEATHERS
        table.insert(jm, "a new weather for the quest")
    end
    if not next(hm.maps) then
        im = im + 500 + 4500 * Config.pearlValue + 200
        table.insert(jm, "the first Explosion Mage")
    end
    return im, jm
end

function Hunt.row(om)
    local pm = Brain.live.event
    local qm = Brain.simRes ["ev:" .. tostring(pm.level)]
    local rm = qm and (qm.won and 50 or tonumber(qm.wave)) or 50
    local sm = om.runs > 0 and om.coins / om.runs or Hunt.pearlsFrom(1, rm) * Hunt.MULT_GUESS
    local tm, um = Hunt.firstValue(pm.map, pm.weather)
    local vm = Core.data("Weather") or {
    }
    local wm = {
        key = "ev:" .. tostring(pm.level),
        kind = "event",
        level = pm.level,
        diff = "Hard",
        value = sm * Config.pearlValue,
        coins = sm,
        p0 = 0.5,
        rec = om,
        label = "Summer Hunt"
    }
    local xm = 1
    if tm > 0 then
        local ym, zm = pcall(Modes.winP, wm)
        xm = ym and Utils.clamp(tonumber(zm) or 0.5, 0, 1) or 0.5
        wm.value = wm.value + tm * xm
    end
    wm.why = string.format("≈%d Summer Pearls a run%s%s", math.floor(sm), pm.weather and vm [pm.weather] and (" · " .. vm [pm.weather].name) or "", # um > 0 and (" · a win adds " .. table.concat(um, ", ") .. string.format(" (win ≈%d%%)", math.floor(xm * 100 + 0.5))) or "")
    return wm
end

function Hunt.floor()
    return tonumber(Brain.hunt.pmin) or 1
end

function Hunt.claim()
    local Am = Hunt.board()
    if not (Am and # Am.claimable > 0) then
        return
    end
    local Bm = App.request("bingo", "claim_summer2_map_board_lines")
    if Bm then
        App.log(1, "LOBBY", string.format("Summer Bingo: claimed %d line%s, each 2,000 Summer Pearls and 10 Limited Star Remnants", # Am.claimable, # Am.claimable == 1 and "" or "s"))
    end
end

function Hunt.write(Cm, Dm)
    local Em = Core.FOLDER .. "/" .. Cm
    local Fm, Gm = pcall(readfile, Em)
    pcall(writefile, Em, (Fm and type(Gm) == "string" and Gm or "") .. Dm .. "\n")
end

function Hunt.plain(Hm, Im)
    Im = Im or 0
    if type(Hm) == "table" then
        if Im > 5 then
            return "..."
        end
        local Jm = {
        }
        for Km, Lm in pairs(Hm) do
            Jm [tostring(Km)] = Hunt.plain(Lm, Im + 1)
        end
        return Jm
    end
    if type(Hm) == "number" or type(Hm) == "string" or type(Hm) == "boolean" then
        return Hm
    end
    return tostring(Hm)
end

function Hunt.shopLook()
    local Mm, Nm = App.request("bsd", "request_current_bsd_shop")
    if Mm and type(Nm) == "table" then
        local Om, Pm = pcall(HttpService.JSONEncode, HttpService, Nm)
        if Om then
            pcall(writefile, Core.FOLDER .. "/hunt_shop.txt", os.date("%m-%d %H:%M ") .. Pm)
        end
    end
    local Qm, Rm = App.request("live_e", "get_event_challenges")
    if Qm and type(Rm) == "table" and type(Rm [Hunt.ID]) == "table" then
        local Sm = {
        }
        for Tm, Um in pairs(Rm [Hunt.ID]) do
            if Tm ~= "current_level_data" then
                Sm [Tm] = Um
            end
        end
        local Vm, Wm = pcall(HttpService.JSONEncode, HttpService, Sm)
        if Vm then
            pcall(writefile, Core.FOLDER .. "/hunt_board.txt", os.date("%m-%d %H:%M ") .. Wm)
        end
    end
end

function Hunt.charmApplies(Xm)
    if not Xm then
        return false
    end
    if Xm.kind == "event" and Hunt.is(Xm.level) then
        return true
    end
    return Xm.kind == "portal" and tostring(Xm.level):find("skypiea", 1, true) ~= nil
end

function Hunt.charms()
    local Ym = Core.prof()
    local Zm = {
    }
    for _m, an in pairs((Ym and Ym.inventory and Ym.inventory.unique_items) or {
    }) do
        local bn = type(an) == "table" and Core.Items [an.item_id]
        if type(bn) == "table" and bn.item_group == "Charms" then
            local cn = {
                uuid = an.uuid or _m,
                id = an.item_id,
                tier = tonumber(bn.tier) or 0,
                rolls = {
                }
            }
            local dn = type(an._unique_item_data) == "table" and type(an._unique_item_data._unique_charm_data) == "table" and an._unique_item_data._unique_charm_data._d
            for en, fn in pairs(type(dn) == "table" and dn or {
            }) do
                if type(fn) == "table" and fn._t then
                    cn.rolls [tostring(fn._t)] = (cn.rolls [tostring(fn._t)] or 0) + (tonumber(fn._d) or 0)
                end
            end
            table.insert(Zm, cn)
        end
    end
    return Zm
end

function Hunt.charmOn()
    local gn = Core.prof()
    local hn = gn and gn.equipped_charms
    if type(hn) ~= "table" then
        return nil
    end
    for jn, kn in pairs(hn) do
        return type(kn) == "table" and (kn.uuid or kn [1]) or kn
    end
    return nil
end

function Hunt.charmScore(ln, mn)
    local nn = (mn and tonumber(mn.p)) or 0.5
    local pn, qn, rn = ln.rolls.unit_damage or 0, ln.rolls.reward_mul or 0, 0
    for sn, tn in pairs(ln.rolls) do
        if sn ~= "unit_damage" and sn ~= "reward_mul" then
            rn = rn + tn
        end
    end
    if nn >= 0.92 then
        return qn * 3 + pn + rn * 0.5
    end
    return pn * 3 + qn + rn * 0.5
end

function Hunt.charmWords(un)
    local vn = {
    }
    for wn, xn in pairs(un.rolls) do
        table.insert(vn, string.format("%s +%d%%", wn == "unit_damage" and "damage" or (wn == "reward_mul" and "rewards" or wn), math.floor(xn * 100 + 0.5)))
    end
    table.sort(vn)
    return string.format("Tier %d: %s", un.tier, # vn > 0 and table.concat(vn, ", ") or "no bonus read")
end

function Hunt.charmDmg(yn)
    if type(yn) ~= "table" or not (Hunt.is(yn.id) or yn.portal_group == "summer2" or tostring(yn.id):find("skypiea_portal", 1, true)) then
        return 0
    end
    local zn, An = Hunt.charmOn(), 0
    for Bn, Cn in ipairs(Hunt.charms()) do
        local Dn = Cn.rolls.unit_damage or 0
        if zn and Cn.uuid == zn then
            return Dn
        end
        if Config.smartCharm and Dn > An then
            An = Dn
        end
    end
    return zn and 0 or An
end

function Hunt.charmWant(En)
    if not Config.smartCharm or not Hunt.charmApplies(En) then
        return nil
    end
    Brain.charm = type(Brain.charm) == "table" and Brain.charm or {
    }
    if os.time() - (tonumber(Brain.charm.failAt) or 0) < 1800 then
        return nil
    end
    local Fn, Gn
    for Hn, In in ipairs(Hunt.charms()) do
        local Jn = Hunt.charmScore(In, En)
        if not Gn or Jn > Gn then
            Fn, Gn = In, Jn
        end
    end
    if not Fn then
        return nil
    end
    local Kn = Hunt.charmOn() or (App.where == "match" and Brain.charm.uuid) or nil
    if Kn == Fn.uuid then
        return nil
    end
    return Fn, Kn
end

function Hunt.charmTick(Ln)
    local Mn, Nn = Hunt.charmWant(Ln)
    if not Mn then
        return
    end
    Nn = Hunt.charmOn()
    if Nn then
        App.request("charm", "request_unequip_charm", Nn)
        task.wait(1)
    end
    App.request("charm", "use_unique_item", Mn.uuid)
    local On = Utils.now()
    while Utils.now() - On < 4 and Hunt.charmOn() ~= Mn.uuid do
        task.wait(0.5)
    end
    if Hunt.charmOn() == Mn.uuid then
        Brain.charm.uuid, Brain.charm.at, Brain.charm.failAt = Mn.uuid, os.time(), nil
        App.saveSoon()
        App.log(1, "CHARM", string.format("wearing the Summer Charm (%s) for %s (win %d%%: %s first)", Hunt.charmWords(Mn), tostring(Ln.label), math.floor((tonumber(Ln.p) or 0) * 100 + 0.5), (tonumber(Ln.p) or 0) >= 0.92 and "rewards" or "damage"))
    else
        Brain.charm.failAt = os.time()
        App.saveSoon()
        App.log(1, "CHARM", string.format("the game didn't put on the Summer Charm (%s): trying again in 30 min", Hunt.charmWords(Mn)))
    end
end

function Hunt.weatherStrength(Pn)
    local Qn = Hunt.fx(Pn)
    local Rn = Qn.dmg / Qn.cd / Qn.hp / Qn.speed * (1 + (Qn.range - 1) / 2)
    for Sn, Tn in pairs(Qn.kinds) do
        Rn = Rn * (1 + Match.rogueShare(Sn) * Tn)
    end
    if Qn.ice > 0 then
        local Un = Match.rogueShare("fire")
        Rn = Rn * (Un + (1 - Un) / (1 - Qn.ice + Qn.ice / Simulator.modFactor("Ice@snow")))
    end
    if Qn.fly > 0 then
        Rn = Rn * (1 - Qn.fly * 0.5)
    end
    if Qn.noCC then
        Rn = Rn * 0.95
    end
    if Qn.shroud then
        Rn = Rn * 0.9
    end
    return Rn
end

function Hunt.cardGems(Vn, Wn)
    local Xn = 0
    local Yn = Hunt.pearlsFrom(Wn + 1, 50)
    for Zn, ao in pairs(type(Vn.effects) == "table" and Vn.effects or {
    }) do
        if type(ao) == "table" then
            local bo = tonumber(ao.amount) or 0
            if ao.type == "candy_multiplier" then
                Xn = Xn + math.abs(bo) * Yn * Config.pearlValue
            elseif ao.type == "add_reward" then
                local co, eo = pcall(Modes.rewardValue, ao.reward)
                if co then
                    Xn = Xn + (tonumber(eo) or 0)
                end
            elseif ao.type == "golem_chance" then
                Xn = Xn + bo * Hunt.STARFALL_GEMS
            elseif ao.type == "secret_drop" then
                Xn = Xn + bo * 100
            end
        end
    end
    if Vn.option_type == "Bad" then
        Xn = Xn + Hunt.HARD_GEMS
    end
    if Vn.weather then
        local fo = Vn.weather ~= Hunt.weatherNow()
        if fo and Vn.weather == "meteor_shower" then
            Xn = Xn + Hunt.STARFALL_GEMS
        end
        local go = Hunt.board()
        if fo and go and Vn.weather ~= "clear" and not go.weathers [Vn.weather] then
            Xn = Xn + (1000 + 5000 * Config.pearlValue + 50 * (Core.ITEM_VALUE.star_remnant_limited or 25)) / Hunt.WEATHERS
        end
    end
    return Xn
end

function Hunt.text()
    local ho = Brain.live.event
    if not (ho and Hunt.is(ho.level)) then
        return "The Summer Hunt isn't on the board right now."
    end
    local io, jo = Core.data("Weather") or {
    }, Core.data("Maps") or {
    }
    local ko = {
    }
    local function mo(no)
        return no and jo [no] and jo [no].name or no or "?"
    end
    table.insert(ko, string.format("This hour: %s, %s.", mo(ho.map), ho.weather and io [ho.weather] and io [ho.weather].name or "weather unknown"))
    if type(ho.forecast) == "table" then
        table.insert(ko, string.format("Next hour: %s, %s.", ho.forecast.map and mo(ho.forecast.map) or (ho.forecast.map_hint or "map hidden"), ho.forecast.weather and io [ho.forecast.weather] and io [ho.forecast.weather].name or (ho.forecast.weather_hint or "weather hidden")))
    end
    local oo = Modes.rec("ev:" .. tostring(ho.level))
    if oo.runs > 0 then
        table.insert(ko, string.format("%d runs so far, %d won, ≈%d Summer Pearls a run.", oo.runs, oo.wins, math.floor(oo.coins / oo.runs)))
    else
        table.insert(ko, string.format("Not played yet. A full run should pay about %d Summer Pearls.", math.floor(Hunt.pearlsFrom(1, 50) * Hunt.MULT_GUESS)))
    end
    local po = Hunt.board()
    if po then
        table.insert(ko, string.format("Bingo: %d of %d squares, %d of %d lines. Weathers won: %d of %d.", po.squares, # po.board, po.lines, po.total, po.weathersWon, Hunt.WEATHERS))
    end
    local qo = table.find(Hunt.CARD_PICKS, Config.huntCards) and Config.huntCards or "Smart"
    table.insert(ko, "Cards: " .. (({
        ["Secret Luck"] = "the most secret luck, then the most pay. Secret luck only comes on the harder cards, so one is skipped when it would leave your team too weak to win.",
        ["Gems"] = "the one that pays the most in gems and pearls, skipping any that would leave your team too weak to win.",
        ["Easiest Win"] = "the one that makes your team strongest, whatever it pays.",
        ["Smart"] = "what each pays weighed against how much weaker it leaves your team."
    }) [qo]))
    table.insert(ko, string.format("You hold %s Summer Pearls. The farm never trades gems for them, and spends them only on Sunny Stars, only with Open Sunny Stars on.", Utils.fmt(tonumber(Core.cur("SummerPearls")) or 0)))
    return table.concat(ko, "\n")
end
Hunt.SKIN_SET, Hunt.STAR = "summer2", "capsule_summer2"
Hunt.SKIN_PRICE = {
    Rare = 10,
    Epic = 40,
    Legendary = 75,
    Mythic = 300
}
Hunt.SKIN_DROP = {
    Rare = 0.02,
    Epic = 0.05,
    Legendary = 0.25,
    Mythic = 0.4
}
Hunt.STAR_COST = 150

function Hunt.skinSet(ro)
    local so = type(ro) == "table" and ro.id
    return (so == Hunt.ID or so == "summer2_portal_final" or (type(ro) == "table" and ro.portal_group == "summer2")) and Hunt.SKIN_SET or nil
end

function Hunt.skinFits(uo, vo)
    local wo = Core.Units [uo]
    local xo = wo and wo.evolved and wo.evolved.from or uo
    return vo.for_unit == uo or vo.for_unit == xo or (vo.for_units ~= nil and (vo.for_units [uo] or vo.for_units [xo]) and true) or false
end

function Hunt.team()
    local yo = Brain.simTeam and Brain.simTeam ["ev:" .. tostring(Hunt.ID)]
    local zo = Core.session()
    local Ao = {
    }
    for Bo, Co in ipairs(yo and yo.uuids or Brain.savedTeam or {
    }) do
        local Do = zo.collection:get_unit_by_uuid(Co)
        if Do then
            table.insert(Ao, Do)
        end
    end
    return Ao
end

function Hunt.skinPlan()
    local Eo, Fo = Core.session(), Core.prof()
    local Go = Core.data("Skins") or {
    }
    local Ho = (Fo.inventory and Fo.inventory.unique_items) or Fo.unique_items or {
    }
    local Io, Jo = {
    }, {
        kinds = {
        },
        sell = {
        },
        wear = {
        },
        pearls = 0,
        missing = {
        }
    }
    for Ko, Lo in pairs(Ho) do
        local Mo = type(Lo) == "table" and Core.Items [Lo.item_id]
        if Mo and Mo.item_group == "Skins" and Mo._skin_set == Hunt.SKIN_SET and Mo.usage and Go [Mo.usage.skin_id] then
            local No = Io [Lo.item_id]
            if not No then
                No = {
                    id = Lo.item_id,
                    name = Mo.name,
                    rarity = Mo.rarity,
                    skinId = Mo.usage.skin_id,
                    skin = Go [Mo.usage.skin_id],
                    uuids = {
                    }
                }
                Io [Lo.item_id] = No
                table.insert(Jo.kinds, No)
            end
            table.insert(No.uuids, Lo.uuid or Ko)
        end
    end
    table.sort(Jo.kinds, function(Oo, Po)
        return Oo.name < Po.name
    end)
    local Qo = Hunt.team()
    local Ro = Eo.profile_data.collection.owned_units
    for So, To in ipairs(Jo.kinds) do
        for Uo, Vo in pairs(Ro) do
            if Hunt.skinFits(Vo.unit_id, To.skin) then
                To.fits = true
                break
            end
        end
        local Wo = To.rarity == "Legendary" or To.rarity == "Mythic"
        To.keep = (To.fits or Wo) and 1 or 0
        for Xo = To.keep + 1, # To.uuids do
            table.insert(Jo.sell, {
                uuid = To.uuids [Xo],
                name = To.name,
                pearls = Hunt.SKIN_PRICE [To.rarity] or 0
            })
            Jo.pearls = Jo.pearls + (Hunt.SKIN_PRICE [To.rarity] or 0)
        end
    end
    for Yo, Zo in ipairs(Qo) do
        local _o = Zo.skin and Zo.skin._skin_id and Go [Zo.skin._skin_id]
        if not (_o and _o._skin_set == Hunt.SKIN_SET) then
            for ap, bp in pairs(Go) do
                if type(bp) == "table" and bp._skin_set == Hunt.SKIN_SET and Hunt.skinFits(Zo.unit_id, bp) then
                    local cp = ap .. "_skin"
                    if Io [cp] then
                        table.insert(Jo.wear, {
                            uuid = Io [cp].uuids [1],
                            unit = Zo.uuid,
                            unitName = Units.name(Zo.unit_id),
                            name = Io [cp].name
                        })
                    else
                        table.insert(Jo.missing, {
                            item = cp,
                            unitName = Units.name(Zo.unit_id),
                            name = bp.name,
                            boost = tonumber(bp._damage_boost) or 0,
                            drop = Hunt.SKIN_DROP [bp._skin_rarity] or 0
                        })
                    end
                end
            end
        end
    end
    return Jo
end

function Hunt.starPlan(dp)
    dp = dp or Hunt.skinPlan()
    local ep = Core.Items [Hunt.STAR] or {
    }
    local fp = tonumber(ep._mythic_unit_pity) or 400
    local gp = (Core.prof().capsule_pity_data or {
    }) [Hunt.STAR] or {
    }
    local ip = tonumber(gp.opens_since_mythic_unit) or 0
    local jp = {
        opened = tonumber(gp.total_opens) or 0,
        left = math.max(1,
        fp - ip),
        units = {
        }
    }
    local kp = tonumber(Core.cur("SummerPearls")) or 0
    jp.can = math.max(0, math.floor((kp - (tonumber(Config.pearlFloor) or 0)) / Hunt.STAR_COST))
    local lp = {
    }
    for mp, np in pairs(Core.session().profile_data.collection.owned_units) do
        lp [np.unit_id] = true
        local op = Core.Units [np.unit_id]
        if op and op.evolved and op.evolved.from then
            lp [op.evolved.from] = true
        end
    end
    for pp, qp in pairs(ep.usage and ep.usage.possible_rewards or {
    }) do
        local rp = qp.unit or qp.item
        if rp and Core.Units [rp] and Core.Units [rp].rarity == "Mythic" and not lp [rp] then
            table.insert(jp.units, Units.name(rp))
        end
    end
    table.sort(jp.units)
    local tp = {
    }
    if # dp.missing > 0 then
        local up = dp.missing [1]
        table.insert(tp, string.format("%s to go on %s", up.name, up.unitName))
    end
    if # jp.units > 0 then
        table.insert(tp, string.format("a Mythic unit you don't have (%s)", table.concat(jp.units, ", ")))
    end
    jp.why = table.concat(tp, " and ")
    jp.open = # tp > 0 and math.min(jp.can, # jp.units > 0 and jp.left or 100) or 0
    return jp
end

function Hunt.skinText()
    local vp, wp = pcall(Hunt.skinPlan)
    if not vp then
        return "Reading your skins: " .. tostring(wp)
    end
    local yp = {
    }
    local zp = {
    }
    for Ap, Bp in ipairs(wp.kinds) do
        table.insert(zp, string.format("%s%s (+%d%% damage%s)", Bp.name, # Bp.uuids > 1 and (" ×" .. # Bp.uuids) or "", (tonumber(Bp.skin._damage_boost) or 0) * 100, Bp.fits and "" or ", no unit of yours fits"))
    end
    table.insert(yp, "A skin counts only in the Hunt, on the unit wearing it. You hold: " .. (# zp > 0 and table.concat(zp, ", ") or "none") .. ".")
    if # wp.wear > 0 then
        local Cp = {
        }
        for Dp, Ep in ipairs(wp.wear) do
            table.insert(Cp, Ep.name .. " on " .. Ep.unitName)
        end
        table.insert(yp, "Would wear: " .. table.concat(Cp, ", ") .. ".")
    end
    for Fp, Gp in ipairs(wp.missing) do
        table.insert(yp, string.format("Your Hunt team could use %s on %s: +%d%% damage, +%d%% Secret Portal drop.", Gp.name, Gp.unitName, Gp.boost * 100, Gp.drop * 100))
    end
    if # wp.sell > 0 then
        local Hp = {
        }
        for Ip, Jp in ipairs(wp.sell) do
            Hp [Jp.name] = (Hp [Jp.name] or 0) + 1
        end
        local Kp = {
        }
        for Lp, Mp in pairs(Hp) do
            table.insert(Kp, Mp .. "× " .. Lp)
        end
        table.sort(Kp)
        table.insert(yp, string.format("Would sell %s for %s pearls. It can't be undone.", table.concat(Kp, ", "), Utils.fmt(wp.pearls)))
    else
        table.insert(yp, "Nothing to sell.")
    end
    local Np, Op = pcall(Hunt.starPlan, wp)
    if Np then
        table.insert(yp, string.format("Sunny Stars: %d opened. A sure Mythic unit in %d more (%s pearls).", Op.opened, Op.left, Utils.fmt(Op.left * Hunt.STAR_COST)))
        if Op.open > 0 then
            table.insert(yp, string.format("Would open %d (%s pearls) for %s, keeping %s pearls.", Op.open, Utils.fmt(Op.open * Hunt.STAR_COST), Op.why, Utils.fmt(Config.pearlFloor)))
        elseif Op.why ~= "" then
            table.insert(yp, string.format("Wants %s, but that would go under the %s pearls you keep.", Op.why, Utils.fmt(Config.pearlFloor)))
        else
            table.insert(yp, "No need for more stars.")
        end
    end
    if FarmHub.pickNote.skins then
        table.insert(yp, FarmHub.pickNote.skins)
    end
    return table.concat(yp, "\n")
end

function Hunt.skinTick()
    if not (Config.skinSmart or Config.starOpen) or not (Brain.live.event and Hunt.is(Brain.live.event.level)) then
        return
    end
    if (App.req.back.skins or 0) > Utils.now() then
        return
    end
    local Pp = Core.session()
    local function Qp(Rp, Sp, Tp)
        local Up = App.gameSaid(Sp)
        FarmHub.pickNote.skins = string.format("%s: the game said no (%s). Trying again in 30 min.", Rp, tostring(Up or Tp or "no answer"))
        App.log(1, "LOBBY", FarmHub.pickNote.skins)
        App.backoff("skins", 1800)
    end
    local Vp = Hunt.skinPlan()
    if Config.skinSmart then
        local Wp = Vp.wear [1]
        if Wp and (App.req.back.skinWear or 0) <= Utils.now() then
            local Xp = Strategy.slotOf(Wp.unit)
            if Xp then
                Brain.str.reequip = {
                    uuid = Wp.unit,
                    slot = Xp
                }
                App.saveNow()
                App.request("uneq", "unequip_unit", Wp.unit)
                local Yp = Utils.now()
                while Utils.now() - Yp < 4 and Strategy.slotOf(Wp.unit) do
                    task.wait(0.25)
                end
            end
            local Zp = Utils.now()
            local _p, aq = App.request("skinWear", "use_unique_item", Wp.uuid, {
                unit_uuid = Wp.unit
            })
            local function bq()
                local cq = Pp.collection:get_unit_by_uuid(Wp.unit)
                return cq and cq.skin ~= nil
            end
            while Utils.now() - Zp < 5 and not bq() do
                task.wait(0.25)
            end
            if Xp then
                Strategy.reequip()
            end
            if bq() then
                App.log(1, "LOBBY", string.format("Summer skins: %s on %s", Wp.name, Wp.unitName))
                FarmHub.pickNote.skins = nil
                Vp = Hunt.skinPlan()
            else
                local dq = App.gameSaid(Zp)
                FarmHub.pickNote.skins = string.format("Wearing %s: the game said no (%s). Trying again in 30 min.", Wp.name, tostring(dq or aq or "no answer"))
                App.log(1, "LOBBY", FarmHub.pickNote.skins)
                App.backoff("skinWear", 1800)
            end
        end
        if # Vp.sell > 0 then
            local eq, fq = {
            }, 0
            for gq = 1, math.min(50, # Vp.sell) do
                table.insert(eq, Vp.sell [gq].uuid)
                fq = fq + Vp.sell [gq].pearls
            end
            local hq = tonumber(Core.cur("SummerPearls")) or 0
            local iq = Utils.now()
            local jq, kq = App.request("skinSell", "delete_unique_items", eq)
            while Utils.now() - iq < 5 and (tonumber(Core.cur("SummerPearls")) or 0) <= hq do
                task.wait(0.25)
            end
            local lq = (tonumber(Core.cur("SummerPearls")) or 0) - hq
            if lq <= 0 then
                return Qp("Selling skins", iq, kq)
            end
            Spending.add(string.format("sold %d spare Summer skins", # eq), # eq, "skins", string.format("Smart Skins: +%s pearls", Utils.fmt(lq)))
            FarmHub.pickNote.skins = nil
        end
    end
    if Config.starOpen then
        local mq = Pp.inventory
        local function nq()
            local oq, pq = pcall(mq.get_number_of_owned_item, mq, Hunt.STAR)
            return oq and tonumber(pq) or 0
        end
        local qq = Utils.now()
        for rq = 1, 8 do
            if Utils.now() - qq > 15 or not App.alive or App.where ~= "lobby" then
                break
            end
            local sq = nq()
            local tq = Hunt.starPlan(Hunt.skinPlan())
            local uq = Utils.now()
            if sq > 0 then
                local vq, wq = App.request("starOpen", "use_item", Hunt.STAR, {
                    use10 = sq >= 10,
                    use_all = false
                })
                while Utils.now() - uq < 6 and nq() >= sq do
                    task.wait(0.25)
                end
                if nq() >= sq then
                    return Qp("Opening a Sunny Star", uq, wq)
                end
                App.log(1, "LOBBY", string.format("Sunny Stars: opened %d · %d opened in all", sq - nq(), (tonumber(((Core.prof().capsule_pity_data or {
                }) [Hunt.STAR] or {
                }).total_opens) or 0)))
                FarmHub.pickNote.skins = nil
            elseif tq.open > 0 then
                local xq = tq.open >= 10 and 10 or 1
                local yq = tonumber(Core.cur("SummerPearls")) or 0
                local zq, Aq = App.request("starBuy", "buy_item_generic", Hunt.STAR, "event", "event_shop", tostring(xq))
                while Utils.now() - uq < 5 and nq() <= 0 do
                    task.wait(0.25)
                end
                if nq() <= 0 then
                    return Qp("Buying a Sunny Star", uq, Aq)
                end
                Spending.add(string.format("%d Sunny Stars", nq()), yq - (tonumber(Core.cur("SummerPearls")) or 0), "Summer Pearls", "Open Sunny Stars: for " .. tq.why)
                FarmHub.pickNote.skins = nil
            else
                break
            end
        end
    end
end

function Modes.list()
    local Bq = Core.prof()
    if not Bq then
        return {
        }
    end
    local Cq = Bq.level_data
    local Dq = {
    }
    local Eq = os.time()
    local function Fq(Gq)
        Gq.rec = Modes.rec(Gq.key)
        local Hq = (Gq.rec.restUntil or 0) > Eq and Gq.kind ~= "portal"
        if Hq and Gq.kind == "daily" and Config.dailyLoop and (Gq.rec.restWhy == "losses" or (Gq.rec.restWhy == nil and math.abs(Gq.rec.restUntil - (tonumber(Gq.rec.last) or 0) - 6 * 3600) <= 5)) then
            Hq = false
        end
        if Hq or not Modes.allowed(Gq) then
            return
        end
        if Gq.kind == "daily" and not Config.dailyMatch and not Config.dailyLoop then
            local Iq, Jq = pcall(Modes.needsHelp, Gq)
            if Iq and Jq then
                Modes.skipped [Gq.key] = Gq.label .. ": the simulator says your team can't win it alone, and Matchmake The Daily is off"
                return
            end
        end
        Gq.mod = Gq.mod or Modes.levelMod(Gq.level)
        if (Gq.kind == "daily" or Gq.kind == "challenge") and not (Gq.kind == "daily" and Config.dailyLoop) then
            local Kq, Lq = Modes.chOk(Gq)
            Modes.skipped [Gq.key] = not Kq and (Gq.label .. ": " .. Lq) or nil
            if not Kq then
                return
            end
        end
        table.insert(Dq, Gq)
    end
    local Mq = Brain.live or {
    }
    if (Config.dailyChallenge or Config.onlyChallenges or Config.dailyLoop) and Mq.daily and Mq.daily.uuid and Mq.daily.uuid ~= Bq.last_completed_daily_challenge_uuid and Mq.daily.uuid ~= Mq.daily.doneUuid and ((Mq.daily.lost or 0) < 2 or Config.dailyLoop) then
        Fq({
            key = "dc",
            kind = "daily",
            level = "__DAILY_CHALLENGE",
            diff = "Hard",
            value = Mq.daily.value or 300,
            label = "Daily Challenge",
            why = string.format("daily reward ≈%s gems of gems + items",
            Utils.fmt(Mq.daily.value or 0)),
            mod = Mq.daily.mod
        })
    end
    if (Config.challenge or Config.onlyChallenges) and Mq.normal and Mq.normal.uuid and Mq.normal.uuid ~= Bq.last_completed_challenge_uuid and Mq.normal.uuid ~= Mq.normal.doneUuid and (Mq.normal.expires or 0) > Eq + 360 and (Mq.normal.lost or 0) < 2 then
        Fq({
            key = "ch",
            kind = "challenge",
            level = Mq.normal.level,
            diff = "Hard",
            value = Mq.normal.value or 100,
            label = "Challenge · " .. Modes.levelName(Mq.normal.level),
            why = "new challenge every 30 min",
            challenge = Mq.normal.challenge
        })
    end
    local Nq = Utils.list(Core.WLO.WORLD_ORDER)
    local Oq = Config.pickStory or ""
    local function Pq(Qq, Rq, Sq, Tq)
        if not Modes.done(Cq, Qq, Rq) then
            return {
                key = "st:" .. Qq .. ":" .. Rq,
                kind = "story",
                first = true,
                level = Qq,
                diff = Rq,
                rank = Sq,
                picked = Tq,
                value = (Core.GS.GEM_REWARD_STORY_FIRST or 60) + Config.unlockValue,
                p0 = Sq >= 16 and Modes.PRIOR_WIN.new or (Rq == "Hard" and Modes.PRIOR_WIN.hard or Modes.PRIOR_WIN.story),
                label = Modes.levelName(Qq) .. " (" .. Rq .. ")",
                why = (Tq and "your pick · " or "") .. "first clear: " .. (Core.GS.GEM_REWARD_STORY_FIRST or 60) .. " gems + unlocks the next act"
            }
        end
        return {
            key = "st:" .. Qq .. ":" .. Rq,
            kind = "story",
            level = Qq,
            diff = Rq,
            rank = Sq,
            picked = Tq,
            value = (Core.GS.GEM_REWARD_STORY or 20),
            p0 = Rq == "Hard" and Modes.PRIOR_WIN.hard or Modes.PRIOR_WIN.story,
            label = Modes.levelName(Qq) .. " (" .. (Tq and Rq or "farm") .. ")",
            why = (Tq and "your pick · " or "") .. (Core.GS.GEM_REWARD_STORY or 20) .. " gems a clear"
        }
    end
    local function Uq(Vq)
        for Wq, Xq in ipairs(Nq) do
            local Yq = Core.Worlds [Xq]
            if Yq and not Yq.legend_stage and not Yq.raid_world then
                for Zq, _q in ipairs(Utils.list(Yq.levels)) do
                    if Modes.open(_q.id) and Vq(_q.id, Wq) then
                        return
                    end
                end
            end
        end
    end
    if not (Config.firstClears or Config.farm or Config.onlyStory) then
    elseif Oq == "progress" then
        for ar, br in ipairs({
            "Normal",
            "Hard"
        }) do
            local cr
            Uq(function(dr, er)
                if Modes.diffOpen(dr, br) and not Modes.done(Cq, dr, br) then
                    cr = Pq(dr, br, er, true)
                    return true
                end
            end)
            if cr then
                Fq(cr)
                break
            end
        end
    elseif Oq ~= "" then
        local fr, gr = Oq:match("^st:(.+):(%a+)$")
        if fr and Modes.open(fr) and Modes.diffOpen(fr, gr) then
            Fq(Pq(fr, gr, 1, true))
        end
    else
        Uq(function(hr, ir)
            for jr, kr in ipairs({
                "Normal",
                "Hard"
            }) do
                if Modes.diffOpen(hr, kr) and not Modes.done(Cq, hr, kr) and (Config.firstClears or Config.onlyStory) then
                    Fq(Pq(hr, kr, ir, false))
                    break
                end
            end
            if Config.farm and ir <= 3 and Modes.done(Cq, hr, "Normal") then
                Fq(Pq(hr, "Normal", ir, false))
            end
        end)
    end
    local lr = Config.pickRaid or ""
    if Config.raids or Config.onlyRaids then
        for mr, nr in ipairs(Utils.list(Core.WLO.RAID_WORLD_ORDER)) do
            local pr = Core.Worlds [nr]
            for qr, rr in ipairs(Utils.list(pr and pr.levels)) do
                local sr = Core.Levels [rr.id]
                if sr and Modes.open(rr.id) and (lr == "" or lr == "rd:" .. rr.id) then
                    local ur = tonumber(sr._raid_daily_tries)
                    local vr = (Bq.raid_tries and Bq.raid_tries.levels and tonumber(Bq.raid_tries.levels [rr.id])) or 0
                    if not ur or vr < ur then
                        local wr, xr = 0, nil
                        for yr, zr in ipairs(Adventure.levelItems(sr)) do
                            wr = wr + Modes.itemValue(zr.item, zr.per)
                            if Brain.goalItems [zr.item] then
                                xr = string.format("≈%.0f %s a run toward your goal", zr.per, (Core.Items [zr.item] or {
                                }).name or zr.item)
                            end
                        end
                        local Ar = not Modes.done(Cq, rr.id)
                        local Br = tonumber(sr._override_gem_reward) or (Core.GS.GEM_REWARD_RAID or 75)
                        Fq({
                            key = "rd:" .. rr.id,
                            kind = "raid",
                            level = rr.id,
                            diff = "Hard",
                            first = Ar,
                            picked = lr ~= "",
                            value = Br + wr + (Ar and Config.unlockValue or 0),
                            p0 = Modes.PRIOR_WIN.raid,
                            label = Modes.levelName(rr.id),
                            why = (lr ~= "" and "your pick · " or "") .. (xr and (xr .. " · ") or "") .. string.format("raid: %d gems + items%s",
                            Br,
                            ur and string.format(" · %d/%d tries left",
                            ur - vr,
                            ur) or "")
                        })
                    end
                end
            end
        end
    end
    if (Config.artifact or Config.onlyArtifact) and Brain.live.artifact then
        for Cr, Dr in ipairs(Brain.live.artifact.list or {
        }) do
            local Er = Core.Levels [Dr.level]
            if Er and Modes.open(Dr.level) then
                local Fr, Gr, Hr = Modes.artifactLeft(Dr.level)
                if Fr < Hr then
                    local Ir = 0
                    for Jr, Kr in ipairs(Adventure.levelItems(Er)) do
                        Ir = Ir + Modes.itemValue(Kr.item, Kr.per)
                    end
                    local Lr = tonumber(Er._override_gem_reward) or 30
                    Fq({
                        key = "ar:" .. Dr.level,
                        kind = "artifact",
                        level = Dr.level,
                        world = Dr.world,
                        diff = "Hard",
                        value = Lr + Ir + Gr / math.max(1,
                        Hr - Fr),
                        label = (Core.Worlds [Dr.world] or {
                        }).name or Modes.levelName(Dr.level),
                        why = string.format("Artifact Stage, alone: %d/%d clears this rotation · %d gems a clear + %s gems of milestones to come",
                        Fr,
                        Hr,
                        Lr,
                        Utils.fmt(Gr))
                    })
                end
            end
        end
    end
    local Mr = Config.pickLegend or ""
    local Nr = Mr ~= "progress" and Mr ~= "" and Mr or nil
    if Mr == "progress" then
        for Or, Pr in ipairs(Utils.list(Core.WLO.LEGEND_WORLD_ORDER)) do
            local Qr = Core.Worlds [Pr]
            for Rr, Sr in ipairs(Utils.list(Qr and Qr.levels)) do
                if not Nr and Core.Levels [Sr.id] and Modes.open(Sr.id) and not Modes.done(Cq, Sr.id, "Hard") then
                    Nr = "st:" .. Sr.id .. ":Hard"
                end
            end
        end
    end
    if (Config.goals and next(Brain.goalItems)) or Config.onlyLegend or Mr ~= "" then
        for Tr, Ur in ipairs(Utils.list(Core.WLO.LEGEND_WORLD_ORDER)) do
            local Vr = Core.Worlds [Ur]
            for Wr, Xr in ipairs(Utils.list(Vr and Vr.levels)) do
                local Yr = Core.Levels [Xr.id]
                local Zr = "st:" .. Xr.id .. ":Hard"
                if Yr and Modes.open(Xr.id) and (Mr == "" or Mr == "progress" or Mr == Zr) then
                    local as = Config.onlyLegend or (Mr ~= "" and Mr ~= "progress")
                    local bs, cs, ds = 0, nil, 0
                    for es, fs in ipairs(Adventure.levelItems(Yr)) do
                        if Brain.goalItems [fs.item] then
                            bs = bs + Modes.itemValue(fs.item, fs.per)
                            cs = string.format("≈%.1f %s a run toward your goal", fs.per, (Core.Items [fs.item] or {
                            }).name or fs.item)
                        elseif as then
                            bs = bs + Modes.itemValue(fs.item, fs.per)
                            ds = ds + 1
                        end
                    end
                    if bs > 0 or Nr == Zr then
                        local gs = not Modes.done(Cq, Xr.id, "Hard")
                        Fq({
                            key = Zr,
                            kind = "story",
                            legend = true,
                            picked = Nr == Zr,
                            level = Xr.id,
                            diff = "Hard",
                            first = gs,
                            value = bs + (gs and ((Core.GS.GEM_REWARD_STORY_FIRST or 60) + Config.unlockValue) or 0),
                            p0 = Modes.PRIOR_WIN.hard,
                            label = Modes.levelName(Xr.id),
                            why = (Nr == Zr and (Mr == "progress" and "the next legend stage you haven't beaten · " or "your pick · ") or "") .. (cs or string.format("legend stage: %d kinds of drops",
                            ds))
                        })
                    end
                end
            end
        end
    end
    local hs = Config.pickInfinite or ""
    if Config.infinite or Config.onlyInfinite then
        for js, ks in ipairs(Modes.infIds()) do
            if Modes.open(ks) and (hs == "" or hs == "inf:" .. ks) then
                local ls = "inf:" .. ks
                local ms, ns = Modes.infReach(ls)
                local ps, qs, rs = Modes.infDaily(Bq, ks, ms)
                local ss, ts, us = pcall(Modes.portalBonus, ks)
                local vs, ws, xs = pcall(Modes.missionValue, ks)
                ts, ws = ss and ts or 0, vs and ws or 0
                local ys = (ts > 0 and us and (" · " .. us) or "") .. (ws > 0 and xs and (" · " .. xs) or "")
                Fq({
                    key = ls,
                    kind = "infinite",
                    level = ks,
                    diff = "Hard",
                    value = ps + ts + ws,
                    p0 = 1,
                    reach = ms,
                    picked = hs ~= "",
                    portalMap = ts > 0 or nil,
                    extra = ys,
                    label = Modes.levelName(ks),
                    why = (hs ~= "" and "your pick · " or "") .. string.format("until the base falls (≈wave %d%s) · %s",
                    math.floor(ms + 0.5),
                    ns and "" or ", not played yet",
                    ps > 0 and string.format("daily gems: %d up to wave %d",
                    ps,
                    qs) or (rs > 0 and "today's gems claimed" or "no daily gems in reach")) .. ys
                })
            end
        end
    end
    local zs, As = pcall(Modes.portalRows)
    for Bs, Cs in ipairs(zs and As or {
    }) do
        Fq(Cs)
    end
    if Config.dungeon or Config.onlyDungeons then
        local Ds = Dungeon.data()
        if Ds and (Ds._started or Config.dungeonStart or Config.onlyDungeons) then
            local Es, Fs = pcall(Dungeon.pick, Ds)
            Fs = Es and Fs or nil
            local Gs, Hs, Is = Dungeon.res(Ds)
            local Js, Ks = pcall(Dungeon.payValue)
            Fq({
                key = "dg",
                kind = "dungeon",
                level = "dungeon",
                diff = "Hard",
                value = (Js and Ks) or Config.dungeonValue,
                p0 = Fs and Fs.p or Modes.PRIOR_WIN.dungeon,
                started = Ds._started or nil,
                label = Ds._started and string.format("Dungeon room %d/%d",
                Fs and Fs.d or (Dungeon.depth(Ds) or 1),
                Dungeon.ROOMS) or "Dungeon (new run)",
                why = Ds._started and string.format("%s · %d lives · %d coins · chests %d + %d rare",
                Fs and Dungeon.roomName(Fs) or "between rooms",
                Dungeon.lives(Ds),
                Gs,
                Hs,
                Is) or "a new run: 20 rooms with chests, shops and shrines"
            })
        end
    end
    if (Config.event or Config.onlyCoins or Brain.nextMode) and Mq.event and Hunt.is(Mq.event.level) then
        Fq(Hunt.row(Modes.rec("ev:" .. tostring(Mq.event.level))))
    elseif (Config.event or Config.onlyCoins) and Mq.event and Mq.event.level then
        local Ls = Modes.rec("ev:" .. Mq.event.level)
        local Ms = Ls.runs > 0 and (Ls.coins / Ls.runs) or 400
        local Ns = Adventure.pullGoal()
        local Os = Ns and Ns.needCoins > 0 and math.max(Config.aprilValue, Config.goalCoinValue) or Config.aprilValue
        Fq({
            key = "ev:" .. Mq.event.level,
            kind = "event",
            level = Mq.event.level,
            diff = "Hard",
            value = Ms * Os,
            coins = Ms,
            p0 = Modes.PRIOR_WIN.event,
            label = Mq.event.name or "Event",
            why = string.format("≈%d %s a run (×%.2f gems each%s)",
            math.floor(Ms),
            Modes.coinName(),
            Os,
            Ns and Ns.needCoins > 0 and (", for " .. Units.name(Ns.to)) or "")
        })
    end
    return Dq
end

function Modes.teamSig()
    if Modes._sigAt and Utils.now() - Modes._sigAt < 20 then
        return Modes._sig
    end
    local Ps = {
    }
    for Qs, Rs in ipairs(Units.equipped()) do
        table.insert(Ps, Rs.u)
    end
    Modes._sig, Modes._sigAt = Simulator.sig(Ps), Utils.now()
    return Modes._sig
end

function Modes.sim(Ss)
    local Ts = Config.sim and Brain.simRes [Ss.key]
    if Ts and Ts.p and os.time() - (Ts.at or 0) < 6 * 3600 and (Ts.sig == Modes.teamSig() or Ts.sig == Modes.ownSig()) then
        return Ts
    end
    return nil
end

function Modes.ownSig()
    local Us = (type(Brain.savedTeam) == "table" and # Brain.savedTeam > 0 and Brain.savedTeam) or (Brain.train.on and Brain.train.on.base)
    if type(Us) ~= "table" or # Us == 0 then
        return nil
    end
    if Modes._ownAt and Utils.now() - Modes._ownAt < 20 then
        return Modes._own
    end
    local Vs = Core.session()
    local Ws = {
    }
    for Xs, Ys in ipairs(Us) do
        local Zs = Vs and Vs.collection:get_unit_by_uuid(Ys)
        if Zs then
            table.insert(Ws, Zs)
        end
    end
    Modes._own, Modes._ownAt = # Ws > 0 and Simulator.sig(Ws) or nil, Utils.now()
    return Modes._own
end

function Modes.nextAct(_s)
    Modes._next = Modes._next or {
    }
    local bt = Modes._next [_s]
    if bt == nil then
        local ct, dt = pcall(Core.PSC.get_next_story_level, _s)
        bt = ct and dt or false
        Modes._next [_s] = bt
    end
    return bt or nil
end

function Modes.needsHelp(et)
    local ft, gt = pcall(Modes.sim, et)
    if ft and type(gt) == "table" and tonumber(gt.p) ~= nil then
        return tonumber(gt.p) < 0.5
    end
    local ht, jt = pcall(Modes.rec, et.key)
    return ht and type(jt) == "table" and (tonumber(jt.streak) or 0) >= 2 or false
end
Modes.MATCHED_DAILY_P = 0.7

function Modes.winP(kt)
    if kt.kind == "daily" and Config.dailyMatch and not Config.dailyLoop then
        local lt, mt = pcall(Modes.needsHelp, kt)
        if lt and mt then
            return Modes.MATCHED_DAILY_P
        end
    end
    local nt = kt.rec
    local ot = kt.p0 or Modes.PRIOR_WIN [kt.kind] or 0.7
    local pt = Modes.sim(kt)
    if pt and not (pt.trust and not pt.trust.ok) then
        local qt = pt.calibrated or nt.runs > 0
        local rt = (pt.trust and pt.trust.ok) and 6 or (qt and 3 or 1.5)
        local tt = (qt or pt.hopeless) and 0 or 2
        return (nt.wins + ot * tt + pt.p * rt) / (nt.runs + tt + rt)
    end
    return (nt.wins + ot * 2) / (nt.runs + 2)
end

function Modes.minutes(ut)
    local vt = ut.rec
    local wt = tonumber(vt.timed) or 0
    local xt = ut.kind == "infinite" and Brain.simRes [ut.key]
    local yt = (wt > 0 and vt.sec > 0) and (vt.sec / wt / 60) or (xt and tonumber(xt.minutes)) or Modes.PRIOR_MIN [ut.kind] or 6
    return yt + Modes.OVERHEAD
end

function Modes.score(zt)
    local At, Bt = ((zt.kind == "event" and zt.rec.runs > 0) or zt.kind == "infinite") and 1 or (zt.kind == "dungeon" and zt.p0) or Modes.winP(zt), Modes.minutes(zt)
    local Ct, Dt, Et = pcall(Strategy.modeBonus, zt)
    if Ct and (Dt or 0) > 0 then
        zt.teamBonus = Dt
        if not tostring(zt.why):find("for your team", 1, true) then
            zt.why = (zt.why or "") .. " · " .. Et
        end
    end
    local Ft = At * (zt.value + (zt.teamBonus or 0)) / Bt
    zt.baseScore = Ft
    local Gt, Ht, It = pcall(Training.valueFor, zt)
    if Gt and Ht > 0 then
        local Jt = At * (zt.value + Ht) / (Bt * It)
        if Jt > Ft then
            Ft, zt.train = Jt, Ht
        end
    end
    if zt.rec.runs < 2 then
        Ft = Ft * (1 + Config.exploreBonus)
    end
    return Ft
end

function Modes.trialRow()
    local Kt = Brain.trial
    if type(Kt) ~= "table" or type(Kt.list) ~= "table" then
        return nil
    end
    local Lt = Kt.list [tonumber(Kt.i) or 1]
    if not Lt then
        return nil
    end
    return {
        key = Kt.key,
        kind = Kt.kind or "story",
        level = Kt.level,
        diff = Kt.diff,
        label = Kt.label,
        rec = Modes.rec(Kt.key),
        value = 0,
        p0 = 1,
        p = 1,
        score = 0,
        why = string.format("%s %d of %d: %s",
        Kt.study and "study run" or "trial",
        tonumber(Kt.i) or 1,
        # Kt.list,
        Units.name(Lt))
    }
end

function Modes.trialTeam()
    local Mt = Brain.trial
    local Nt = Mt.list [tonumber(Mt.i) or 1]
    if Brain.train.on then
        Training.home()
    end
    local Ot = Core.session()
    local Pt, Qt
    for Rt, St in pairs(Ot.profile_data.collection.owned_units) do
        if St.unit_id == Nt then
            local Tt = Ot.collection:get_unit_by_uuid(St.uuid) or St
            local Ut, Vt = pcall(Units.score, Tt)
            Vt = Ut and Vt or 0
            if not Qt or Vt > Qt then
                Pt, Qt = Tt, Vt
            end
        end
    end
    local Wt = Mt.study and Brain.study and Brain.study.id == Nt and Brain.study or nil
    if Wt and Ot.collection:get_unit_by_uuid(Wt.uuid) then
        Pt = Ot.collection:get_unit_by_uuid(Wt.uuid)
    end
    if not Pt then
        App.log(1, "TRIAL", Units.name(Nt) .. ": no copy of it any more, skipped")
        Mt.i = (tonumber(Mt.i) or 1) + 1
        return false
    end
    local Xt = table.clone(Brain.savedTeam or Training.team())
    local Yt = table.find(Xt, Pt.uuid) ~= nil
    if not Yt then
        local Zt, au
        for bu, cu in ipairs(Xt) do
            local du = Ot.collection:get_unit_by_uuid(cu)
            if du and not Units.isFarm(du.unit_id) and not Units.allyBuff(du.unit_id) then
                local eu, fu = pcall(Units.score, du)
                fu = eu and fu or 0
                if not au or fu < au then
                    Zt, au = bu, fu
                end
            end
        end
        if Zt then
            Xt [Zt] = Pt.uuid
        else
            table.insert(Xt, Pt.uuid)
        end
    end
    for gu, hu in ipairs(Wt and Wt.summoners or {
    }) do
        if not table.find(Xt, hu) and Ot.collection:get_unit_by_uuid(hu) then
            local iu, ju
            for ku, lu in ipairs(Xt) do
                local mu = Ot.collection:get_unit_by_uuid(lu)
                if mu and lu ~= Pt.uuid and not table.find(Wt.summoners, lu) and not Units.isFarm(mu.unit_id) and not Units.allyBuff(mu.unit_id) then
                    local nu, ou = pcall(Units.score, mu)
                    ou = nu and ou or 0
                    if not ju or ou < ju then
                        iu, ju = ku, ou
                    end
                end
            end
            if iu then
                Xt [iu] = hu
            elseif # Xt < 6 then
                table.insert(Xt, hu)
            end
        end
    end
    if not Training.same(Training.team(), Xt) then
        FarmHub.equipTeam(Xt, (Wt and "study run for " or "trial run for ") .. Units.name(Nt))
    end
    return true
end

function Match.trialDone(pu, qu)
    local ru = Brain.trial
    local su = Match.trialId
    if type(ru) ~= "table" or not su then
        return
    end
    local tu, uu = Match.damageShares()
    uu = uu or 0
    local vu = tu and (tu [su] or 0) * uu or 0
    local wu = Units.rows(su)
    local xu, yu, zu = 0, 0, 0
    for Au, Bu in pairs(Match.ownDealt or {
    }) do
        if Bu.id == su then
            xu = xu + 1
            yu = math.max(yu, Bu.lvl or 0)
            zu = zu + (tonumber(wu and wu [0] and wu [0].cost) or 0)
            for Cu = 1, Bu.lvl or 0 do
                zu = zu + (tonumber(wu and wu [Cu] and wu [Cu].cost) or 0)
            end
        end
    end
    local Du = {
    }
    for Eu, Fu in pairs(tu or {
    }) do
        if Eu ~= su and Fu >= 0.005 then
            table.insert(Du, {
                n = Eu == "helpers" and Eu or Units.name(Eu),
                v = Fu
            })
        end
    end
    table.sort(Du, function(Gu, Hu)
        return Gu.v > Hu.v
    end)
    local Iu = {
    }
    for Ju, Ku in ipairs(Du) do
        table.insert(Iu, string.format("%s %d%%", (Ku.n:gsub(" %(.+%)", "")), math.floor(Ku.v * 100 + 0.5)))
    end
    local Lu = Match.trialSim
    local Mu = Lu and string.format("the sim expected %s alone: %s at wave %d, %s damage, upgrade %s", (Units.name(su):gsub(" %(.+%)", "")), Lu.won and "wins" or "falls", Lu.wave, Utils.fmt(Lu.dealt or 0), tostring(Lu.lvl or "?")) or "no sim reading"
    local Nu = string.format("%s · %s at wave %d of %d in %.1f min · dealt %s, %d%% of %s · %d copies, top upgrade %d of %d, about ¥%s · ability cast %d times · stood by: %s · %s", Units.name(su), pu and "won" or "lost", Match.wave(), Match.total or 0, (qu or 0) / 60, Utils.fmt(vu), math.floor((tu and tu [su] or 0) * 100 + 0.5), Utils.fmt(uu), xu, yu, wu and wu.max or 0, Utils.fmt(zu), Match.casts and Match.casts [su] or 0, # Iu > 0 and table.concat(Iu, ", ") or "nobody", Mu)
    App.log(1, "TRIAL", Nu)
    local Ou = "AA_SmartFarm/trials.txt"
    local Pu, Qu = pcall(readfile, Ou)
    pcall(writefile, Ou, (Pu and type(Qu) == "string" and Qu or "") .. os.date("%H:%M ") .. Nu .. "\n")
    do
        local Ru = Match.calRun or {
        }
        local Su = {
        }
        if (Ru.potSum or 0) > 0 then
            table.insert(Su, string.format("real/listed damage %.2f", (Ru.dealtSum or 0) / Ru.potSum))
        end
        local Tu = "AA_SmartFarm/trial_trace.txt"
        local Uu, Vu = pcall(readfile, Tu)
        pcall(writefile, Tu, (Uu and type(Vu) == "string" and Vu or "") .. os.date("%H:%M ") .. Units.name(su) .. " " .. table.concat(Su, " ") .. "\n" .. table.concat(Match.trialTrace or {
        }, "\n") .. "\n\n")
    end
    ru.results = type(ru.results) == "table" and ru.results or {
    }
    table.insert(ru.results, {
        id = su,
        won = pu and true or false,
        wave = Match.wave(),
        sec = qu,
        dealt = vu,
        share = tu and tu [su] or 0,
        sum = uu,
        copies = xu,
        lvl = yu,
        yen = zu,
        casts = Match.casts and Match.casts [su] or 0,
        sim = Lu
    })
    if ru.study and Brain.study and Brain.study.id == su then
        local Wu, Xu = pcall(Reports.studyRecord, su, ru.results [# ru.results])
        if Wu and Xu then
            Brain.study.records = type(Brain.study.records) == "table" and Brain.study.records or {
            }
            table.insert(Brain.study.records, Xu.run)
            local Yu, Zu = pcall(Reports.studyFit, Xu)
            if Yu and Zu then
                table.insert(Brain.studyQ, Zu)
                while # Brain.studyQ > 10 do
                    table.remove(Brain.studyQ, 1)
                end
                task.spawn(function()
                    pcall(Reports.sendStudy, 3)
                end)
                local _u, av = pcall(readfile, Core.FOLDER .. "/studies.txt")
                pcall(writefile, Core.FOLDER .. "/studies.txt", (_u and type(av) == "string" and av or "") .. os.date("%m-%d %H:%M ") .. Zu .. "\n")
            end
            App.log(1, "STUDY", Reports.studyLine(Xu))
        else
            App.log(1, "ERROR", "study record: " .. tostring(Xu))
        end
        local bv = type(Brain.studied [su]) == "table" and Brain.studied [su] or {
        }
        Brain.studied [su] = {
            runs = (tonumber(bv.runs) or 0) + 1,
            trials = bv.trials,
            at = os.time()
        }
    elseif su then
        local cv = type(Brain.studied [su]) == "table" and Brain.studied [su] or {
        }
        Brain.studied [su] = {
            runs = cv.runs,
            trials = (tonumber(cv.trials) or 0) + 1,
            at = os.time()
        }
    end
    ru.i = (tonumber(ru.i) or 1) + 1
    if not ru.list [ru.i] then
        App.log(1, "TRIAL", "all trial runs done: your own team goes back in")
        Brain.trial = nil
        if ru.study and Brain.study then
            Brain.study.done = os.time()
            App.log(1, "STUDY", Units.name(Brain.study.id) .. ": study done, " .. # (Brain.study.records or {
            }) .. " runs")
            if Brain.study.smart then
                local dv, fv, gv = pcall(FarmHub.studyStart)
                if dv then
                    App.log(1, "STUDY", "Smart Study, next: " .. tostring(gv))
                else
                    App.log(1, "ERROR", "Smart Study: " .. tostring(fv))
                end
            elseif Brain.study.holdAfter then
                Brain.holdLobby = {
                    why = "the study is done",
                    at = os.time()
                }
            end
        end
    end
    App.saveNow()
end
