    "summon",
    "spawn",
    "minion",
    "takedown",
    "kill",
    "dead",
    "revive",
    "raise",
    "buff",
    "ally",
    "allies",
    "aura",
    "slow",
    "stun",
    "freeze",
    "burn",
    "bleed",
    "poison",
    "wither",
    "range",
    "cooldown",
    "spa",
    "crit",
    "yen",
    "money",
    "shield",
    "heal",
    "stack",
    "boss",
    "flying",
    "hill",
    "mark",
