    "chance"
}

function Reports.r3(hv)
    hv = tonumber(hv)
    return hv and math.floor(hv * 1000 + 0.5) / 1000 or nil
end

function Reports.atkBrief(iv)
    if type(iv) ~= "table" then
        return nil
    end
    local jv = {
        n = Reports.r3(iv.n),
        hits = iv.hits
    }
    if (iv.slow or 0) > 0 then
        jv.slow = Reports.r3(iv.slowPct)
        jv.slowTime = Reports.r3(iv.slowTime)
    end
    if (iv.stun or 0) > 0 then
        jv.stun = Reports.r3(iv.stun)
    end
    if (iv.dot or 0) > 0 then
        jv.dot = Reports.r3(iv.dot)
    end
    if iv.bleed then
        jv.bleed = true
    end
    if (iv.amp or 0) > 0 then
        jv.amp = Reports.r3(iv.amp)
    end
    if iv.full then
        jv.full = true
    end
    if iv.wholeMap then
        jv.wholeMap = true
    end
    if iv.breakShields then
        jv.breakShields = true
    end
    if iv.ally then
        jv.allyBuff = iv.ally.types
        jv.allyTime = iv.ally.time
    end
    if iv.allyCd then
        jv.allyCd = iv.allyCd
    end
    if iv.allyRange then
        jv.allyRange = iv.allyRange
    end
    if iv.selfDmg then
        jv.selfDmg = iv.selfDmg
    end
    if iv.baseSafe then
        jv.baseSafe = iv.baseSafe
    end
    return jv
end

function Reports.readPassives(kv)
    local lv = Units.field(kv, "passives")
    local mv = {
    }
    for nv, ov in pairs(type(lv) == "table" and lv or {
    }) do
        if type(ov) == "table" then
            local pv = tostring(ov.description or ""):gsub("<[^>]+>", ""):gsub("%s+", " ")
            local qv = pv:lower()
            local rv = {
                name = tostring(ov.name or nv),
                text = pv:sub(1,
                400)
            }
            local sv = {
            }
            for tv in qv:gmatch("([%d%.]+)%%") do
                if tonumber(tv) then
                    table.insert(sv, tonumber(tv))
                end
            end
            if # sv > 0 then
                rv.pct = sv
            end
            rv.every = tonumber(qv:match("every (%d+) attacks?")) or tonumber(qv:match("every (%d+) hits?")) or tonumber(qv:match("every (%d+) takedowns?"))
            rv.sec = tonumber(qv:match("([%d%.]+) ?sec"))
            rv.upTo = tonumber(qv:match("up to (%d+)"))
            local uv = {
            }
            for vv, wv in ipairs(Reports.STUDY_WORDS) do
                if qv:find(wv, 1, true) then
                    table.insert(uv, wv)
                end
            end
            if # uv > 0 then
                rv.tags = uv
            end
            table.insert(mv, rv)
        end
    end
    table.sort(mv, function(xv, yv)
        return xv.name < yv.name
    end)
    return mv
end

function Reports.readAbility(zv)
    local Av = Units.rows(zv)
    local Bv, Cv = Units.field(zv, "active_attack"), nil
    for Dv = 0, Av and Av.max or - 1 do
        if Av [Dv] and Av [Dv].active then
            Bv, Cv = Bv or Av [Dv].active, Cv or Dv
        end
    end
    if not Bv then
        return nil
    end
    local Ev = Core.Attacks [Bv] or Units.fillAttack(Bv)
    local Fv, Gv = pcall(Units.attackInfo, Bv)
    local Hv = type(Ev) == "table" and type(Ev.active_description) == "string" and Ev.active_description:gsub("<[^>]+>", ""):sub(1, 300) or nil
    local Iv = Units.field(zv, "active_attack_stats")
    return {
        id = Bv,
        name = type(Ev) == "table" and type(Ev.name) == "string" and Ev.name or nil,
        text = Hv,
        from = Cv,
        cd = type(Iv) == "table" and tonumber(Iv.attack_cooldown) or (Av and Cv and Av [Cv] and Av [Cv].activeCd) or nil,
        does = Fv and Reports.atkBrief(Gv) or nil
    }
end

function Reports.readAttacks(Jv)
    local Kv = Units.rows(Jv)
    local Lv, Mv = {
    }, nil
    for Nv = 0, Kv and Kv.max or - 1 do
        local Ov = Kv [Nv]
        if Ov and Ov.atk and Ov.atk ~= Mv then
            Mv = Ov.atk
            local Pv, Qv = pcall(Units.attackInfo, Ov.atk, Ov.range)
            table.insert(Lv, {
                from = Nv,
                id = Ov.atk,
                does = Pv and Reports.atkBrief(Qv) or nil
            })
            if # Lv >= 6 then
                break
            end
        end
    end
    return Lv
end

function Reports.studyProfile(Rv)
    local Sv = Core.Units [Rv] or {
    }
    local Tv = Units.rows(Rv)
    local Uv = {
        id = Rv,
        name = Units.name(Rv),
        rarity = Sv.rarity,
        cost = tonumber(Sv.cost),
        type = Sv._base_damage_type,
        cap = tonumber(Units.field(Rv,
        "spawn_cap")),
        crit = tonumber(Sv.physical_crit_chance),
        farm = Units.isFarm(Rv) or nil,
        hill = Sv.hill_unit or nil,
        hidden = Brain.hidden [Rv] or nil,
        known = Tv ~= nil and (Tv.max or 0) > 0,
        ups = Tv and Tv.max or 0
    }
    if Uv.known then
        local Vv, Wv = Tv [0], Tv [Tv.max]
        local Xv = 0
        for Yv = 0, Tv.max do
            Xv = Xv + (tonumber(Tv [Yv].cost) or 0)
        end
        Uv.first = {
            dmg = Vv.damage,
            cd = Reports.r3(Vv.cd),
            range = Vv.range,
            cost = Vv.cost
        }
        Uv.last = {
            dmg = Wv.damage,
            cd = Reports.r3(Wv.cd),
            range = Wv.range,
            farm = (tonumber(Wv.farm) or 0) > 0 and Wv.farm or nil
        }
        Uv.totalCost = Xv
    end
    Uv.passives = Reports.readPassives(Rv)
    Uv.ability = Reports.readAbility(Rv)
    Uv.attacks = Reports.readAttacks(Rv)
    return Uv
end

function FarmHub.studyRole(Zv, _v)
    local aw = {
        kinds = {
        }
    }
    local bw = ""
    for cw, dw in ipairs(_v.passives or {
    }) do
        bw = bw .. " " .. tostring(dw.text):lower()
    end
    if _v.ability and _v.ability.text then
        bw = bw .. " " .. _v.ability.text:lower()
    end
    local function ew(fw)
        table.insert(aw.kinds, fw)
    end
    if Units.isFarm(Zv) then
        ew("farm")
    end
    if Units.BLESS.by [Zv] or (bw:find("minion", 1, true) and bw:find("summon", 1, true)) then
        ew("summon buffer")
        aw.team, aw.summoners = true, true
    elseif Units.SUMMONER [Zv] or (Units.DRONES and Units.DRONES [Zv]) or bw:find("summon", 1, true) or bw:find("spawn", 1, true) then
        ew("summoner")
    end
    if Units.allyBuff(Zv) or Units.idol(Zv) or (_v.ability and _v.ability.does and _v.ability.does.allyBuff) then
        ew("buffer")
        aw.team = true
    end
    if Units.ENTRY [Zv] or bw:find("dead", 1, true) or bw:find("raise", 1, true) or bw:find("revive", 1, true) then
        ew("needs kills")
        aw.entry = true
    end
    if not _v.known then
        ew("not read yet")
        aw.team, aw.first = true, true
    end
    if # aw.kinds == 0 then
        ew("attacker")
    end
    return aw
end

function FarmHub.studySummoners(gw)
    local hw = Core.session()
    local iw = {
    }
    for jw, kw in pairs(hw.profile_data.collection.owned_units) do
        local lw = kw.unit_id
        if lw ~= gw and (Units.SUMMONER [lw] or (Units.DRONES and Units.DRONES [lw]) or (Units.summonShare and Units.summonShare(lw) >= 0.3)) then
            local mw = hw.collection:get_unit_by_uuid(jw) or kw
            local nw, ow = pcall(Units.score, mw)
            ow = nw and ow or 0
            if not iw [lw] or ow > iw [lw].sc then
                iw [lw] = {
                    uuid = jw,
                    sc = ow
                }
            end
        end
    end
    local pw = {
    }
    for qw, rw in pairs(iw) do
        table.insert(pw, {
            id = qw,
            uuid = rw.uuid,
            sc = rw.sc
        })
    end
    table.sort(pw, function(sw, tw)
        return sw.sc > tw.sc
    end)
    local uw = {
    }
    for vw = 1, math.min(2, # pw) do
        table.insert(uw, pw [vw].uuid)
    end
    return uw
end

function FarmHub.studyMap()
    local ww, xw
    for yw, zw in pairs(Brain.modes or {
    }) do
        local Aw = tostring(yw):match("^st:(.+):Normal$")
        if Aw and (tonumber(zw.wins) or 0) > 0 and (not xw or zw.wins > xw) then
            ww, xw = Aw, zw.wins
        end
    end
    ww = ww or "namek_level_1"
    return "st:" .. ww .. ":Normal", ww, "Normal", Modes.levelName(ww) .. " (Normal)"
end

function FarmHub.studyPlanText(Bw, Cw, Dw)
    local Ew = {
    }
    local Fw = {
    }
    for Gw, Hw in ipairs(Cw.passives or {
    }) do
        table.insert(Fw, Hw.name)
    end
    table.insert(Ew, string.format("%s: read as %s.", Units.name(Bw), table.concat(Dw.kinds, ", ")))
    if Dw.first then
        table.insert(Ew, "The game hides this unit's upgrades, ability and passives until it plays, and no match has sent them yet: the first run reads them, with your whole team fighting.")
    else
        table.insert(Ew, (# Fw > 0 and ("Passives: " .. table.concat(Fw, ", ") .. ".") or (Cw.hidden and "Passives: the game sends them only in a match, so the first run reads them." or "Passives: none.")) .. " " .. (Cw.ability and string.format("Ability: %s%s.", tostring(Cw.ability.name or Cw.ability.id), Cw.ability.cd and string.format(", every %ds", math.floor(Cw.ability.cd + 0.5)) or "") or "No ability."))
    end
    local Iw = Dw.team and "with your whole team fighting" or "alone with the yen, the rest of your team standing by"
    if Dw.summoners then
        local Jw = {
        }
        local Kw = Core.session()
        for Lw, Mw in ipairs(FarmHub.studySummoners(Bw)) do
            local Nw = Kw and Kw.collection:get_unit_by_uuid(Mw)
            if Nw then
                table.insert(Jw, Units.name(Nw.unit_id))
            end
        end
        Iw = Iw .. (# Jw > 0 and (", with your summoners " .. table.concat(Jw, " and ")) or ", but you have no summoner to buff")
    end
    if Dw.entry then
        Iw = Iw .. ", at the road's entrance (it needs kills)"
    end
    local Ow, Pw, Qw, Rw = FarmHub.studyMap()
    table.insert(Ew, string.format("Test: %s, on %s.", Iw, Rw))
    return table.concat(Ew, "\n")
end

function FarmHub.studySeed()
    if Brain.studiedSeeded then
        return
    end
    Brain.studiedSeeded = true
    local Sw, Tw = pcall(readfile, Core.FOLDER .. "/trials.txt")
    if not (Sw and type(Tw) == "string") then
        return
    end
    local Uw = {
    }
    for Vw, Ww in pairs(Core.Units) do
        if type(Ww) == "table" then
            Uw [Units.name(Vw)] = Uw [Units.name(Vw)] or Vw
        end
    end
    local Xw = 0
    for Yw in Tw:gmatch("[^\n]+") do
        local Zw = Yw:match("^%d%d:%d%d (.-) · ")
        local _w = Zw and Uw [Zw]
        if _w then
            local ax = type(Brain.studied [_w]) == "table" and Brain.studied [_w] or {
            }
            Brain.studied [_w] = {
                runs = ax.runs,
                trials = (tonumber(ax.trials) or 0) + 1,
                at = ax.at or 0
            }
            Xw = Xw + 1
        end
    end
    if Xw > 0 then
        App.log(1, "STUDY", string.format("%d trial runs from before count as trained (trials.txt)", Xw))
    end
    App.saveSoon()
end

function FarmHub.studyNext()
    FarmHub.studySeed()
    local bx = Core.session()
    local cx = {
    }
    for dx, ex in pairs(bx and bx.profile_data.collection.owned_units or {
    }) do
        local gx = ex.unit_id
        if Core.Units [gx] and not Brain.studied [gx] then
            local hx = bx.collection:get_unit_by_uuid(dx) or ex
            local ix, jx = pcall(Units.score, hx)
            jx = ix and tonumber(jx) or 0
            if not cx [gx] or jx > cx [gx].sc then
                cx [gx] = {
                    u = hx,
                    sc = jx
                }
            end
        end
    end
    local kx
    for lx, mx in pairs(cx) do
        if not kx or mx.sc > kx.sc then
            kx = mx
        end
    end
    return kx and kx.u or nil
end

function FarmHub.studyStart()
    local nx = Core.session()
    local ox = Config.studyUnit == "smart"
    local px
    if ox then
        px = FarmHub.studyNext()
    else
        px = nx and Config.studyUnit ~= "" and nx.collection:get_unit_by_uuid(Config.studyUnit)
    end
    if not px then
        if ox and Brain.study then
            Brain.study.smart = nil
        end
        return false, ox and "every unit you own has been studied" or "pick a unit to study first"
    end
    if Brain.trial and not Brain.trial.study then
        return false, "trial runs are going: start the study after them"
    end
    local qx = px.unit_id
    local rx = Reports.studyProfile(qx)
    local sx = FarmHub.studyRole(qx, rx)
    local tx, ux, vx, wx = FarmHub.studyMap()
    local xx = math.clamp(math.floor(tonumber(Config.studyRuns) or 2), 1, 5)
    local yx = {
    }
    for zx = 1, xx do
        yx [zx] = qx
    end
    Brain.study = {
        uuid = px.uuid,
        id = qx,
        n = xx,
        role = sx,
        summoners = sx.summoners and FarmHub.studySummoners(qx) or nil,
        key = tx,
        label = wx,
        at = os.time(),
        records = {
        },
        smart = ox or nil
    }
    Brain.trial = {
        key = tx,
        kind = "story",
        level = ux,
        diff = vx,
        label = wx,
        list = yx,
        i = 1,
        study = true
    }
    FarmHub.studyCache = nil
    App.log(1, "STUDY", string.format("%s: %d run%s · %s", Units.name(qx), xx, xx == 1 and "" or "s", FarmHub.studyPlanText(qx, rx, sx):gsub("\n", " ")))
    App.saveNow()
    return true, string.format("%s: %d run%s on %s%s", Units.name(qx), xx, xx == 1 and "" or "s", wx, Config.master and (Brain.holdLobby and " once you press Start Farming Again" or "") or " once the Auto Farm is on")
end

function FarmHub.studyStop()
    local Ax = (Brain.trial and Brain.trial.study) or (Brain.study and not Brain.study.done)
    if Brain.trial and Brain.trial.study then
        Brain.trial = nil
    end
    if Brain.study and not Brain.study.done then
        Brain.study.done, Brain.study.stopped = os.time(), true
        App.log(1, "STUDY", Units.name(Brain.study.id) .. ": study stopped (you pressed Stop Study)")
    end
    FarmHub.studyCache = nil
    App.saveNow()
    return Ax
end

function FarmHub.studyText()
    local Bx = Brain.study
    local Cx = Bx and not Bx.done and Brain.trial and Brain.trial.study
    if not Cx then
        local Dx = ""
        if Bx and Bx.done then
            local Ex = Bx.records and Bx.records [# Bx.records]
            Dx = string.format("Last study: %s, %d run%s%s.%s\n", Units.name(Bx.id), # (Bx.records or {
            }), # (Bx.records or {
            }) == 1 and "" or "s", Bx.stopped and " (stopped)" or "", Ex and string.format(" Last run: %s at wave %d, dealt %s (%d%%), ability cast %d times.", Ex.won and "won" or "lost", Ex.wave or 0, Utils.fmt(Ex.dealt or 0), math.floor((Ex.share or 0) * 100 + 0.5), Ex.casts or 0) or "")
        end
        local Fx = 0
        for Gx in pairs(Brain.studied) do
            Fx = Fx + 1
        end
        if Fx > 0 then
            Dx = Dx .. string.format("%d kind%s of unit studied so far (✓ in the list).\n", Fx, Fx == 1 and "" or "s")
        end
        if Config.studyUnit == "" then
            return Dx .. "Pick a unit, or Smart. The farm reads its passives and ability, plays real matches with it, and saves what it learned locally."
        end
        local Hx = Core.session()
        local Ix
        if Config.studyUnit == "smart" then
            Ix = FarmHub.studyNext()
            if not Ix then
                return Dx .. "Smart Study: every unit you own has been studied."
            end
            Dx = Dx .. "Smart Study goes down your units from the strongest not studied yet. Next up:\n"
        else
            Ix = Hx and Hx.collection:get_unit_by_uuid(Config.studyUnit)
        end
        if not Ix then
            return Dx .. "That unit is gone: pick another."
        end
        local Jx = FarmHub.studyCache
        if not (Jx and Jx.uuid == Ix.uuid and Utils.now() - Jx.at < 30) then
            local Lx, Mx = pcall(function()
                local Kx = Reports.studyProfile(Ix.unit_id)
                return FarmHub.studyPlanText(Ix.unit_id, Kx, FarmHub.studyRole(Ix.unit_id, Kx))
            end)
            Jx = {
                uuid = Ix.uuid,
                at = Utils.now(),
                text = Lx and Mx or ("Couldn't read it: " .. tostring(Mx))
            }
            FarmHub.studyCache = Jx
        end
        return Dx .. Jx.text .. "\nPress Start Study to begin."
    end
    local Nx = tonumber(Brain.trial.i) or 1
    local Ox = (tonumber(Brain.studySent) or 0)
    return string.format("Studying %s: run %d of %d on %s, %s.%s%s", Units.name(Bx.id), math.min(Nx, Bx.n), Bx.n, tostring(Bx.label), Bx.role and Bx.role.team and "with your team fighting" or "alone with the yen", Bx.smart and " Smart Study: then the next strongest unit not studied yet." or "", Config.master and (Brain.holdLobby and " Waiting: press Start Farming Again." or "") or " Waiting: switch the Auto Farm on.")
end

function Reports.studyRecord(Px, Qx)
    Qx = type(Qx) == "table" and Qx or {
    }
    local Rx = Reports.studyProfile(Px)
    local Sx, Tx = pcall(Match.summonSplit)
    local Ux = Sx and type(Tx) == "table" and Tx [Px]
    local Vx = 0
    for Wx, Xx in ipairs(Match.mine or {
    }) do
        local Yx = Xx._stats
        local Zx = Yx:FindFirstChild("takedown_count")
        if Yx.id.Value == Px and Zx then
            Vx = Vx + (tonumber(Zx.Value) or 0)
        end
    end
    local _x = Brain.toggles [Px]
    local ay = Match.calRun or {
    }
    local cy = {
    }
    for dy, ey in ipairs(Match.team or {
    }) do
        if ey.id ~= Px then
            table.insert(cy, ey.id)
        end
    end
    local fy, gy = pcall(Match.damageShares)
    local hy = {
    }
    if fy and type(gy) == "table" then
        for iy, jy in pairs(gy) do
            if (tonumber(jy) or 0) >= 0.005 then
                hy [iy] = Reports.r3(jy)
            end
        end
    end
    local ky = 0
    for ly in pairs(Match.helperDealt or {
    }) do
        ky = ky + 1
    end
    local my = {
        map = Match.ld.map,
        level = Match.ld.id,
        mode = Match.key,
        how = (Brain.study and Brain.study.role and Brain.study.role.team) and "team" or "solo",
        won = Qx.won,
        wave = Qx.wave,
        total = Match.total,
        sec = math.floor(tonumber(Qx.sec) or 0),
        dealt = math.floor(tonumber(Qx.dealt) or 0),
        share = Reports.r3(Qx.share),
        copies = Qx.copies,
        top = Qx.lvl,
        yen = Qx.yen,
        casts = Qx.casts,
        summons = Ux and Reports.r3(Ux.share) or nil,
        takedowns = Vx,
        realVsListed = (ay.potSum or 0) > 0 and Reports.r3((ay.dealtSum or 0) / ay.potSum) or nil,
        toggle = type(_x) == "table" and {
            from = _x.from,
            fill = Reports.r3(_x.fill),
            drain = Reports.r3(_x.drain)
        } or nil,
        sim = type(Qx.sim) == "table" and {
            won = Qx.sim.won,
            wave = Qx.sim.wave,
            dealt = math.floor(tonumber(Qx.sim.dealt) or 0)
        } or nil,
        mates = cy,
        teamShares = next(hy) and hy or nil,
        teamDealt = math.floor(tonumber(Qx.sum) or 0),
        helpers = ky
    }
    return {
        v = VERSION,
        id = Brain.anonId,
        at = os.time(),
        unit = Rx,
        role = Brain.study and Brain.study.role and Brain.study.role.kinds or nil,
        run = my
    }
end

function Reports.studyFit(ny)
    local oy = Utils.json(ny)
    if # oy <= 3900 then
        return oy
    end
    for py, qy in ipairs({
        200,
        100
    }) do
        for ry, sy in ipairs(ny.unit.passives or {
        }) do
            sy.text = tostring(sy.text):sub(1, qy)
        end
        oy = Utils.json(ny)
        if # oy <= 3900 then
            return oy
        end
    end
    for ty, uy in ipairs(ny.unit.attacks or {
    }) do
        uy.does = nil
    end
    if ny.unit.ability then
        ny.unit.ability.text = ny.unit.ability.text and ny.unit.ability.text:sub(1, 120)
    end
    ny.run.mates = nil
    oy = Utils.json(ny)
    if # oy <= 3900 then
        return oy
    end
    ny.unit.attacks = nil
    return Utils.json(ny):sub(1, 3900)
end

function Reports.sendStudy(vy)
    if not (Config.shareStats and Core.WEBHOOK_URL ~= "") then
        return
    end
    for wy = 1, math.max(1, tonumber(vy) or 1) do
        if # Brain.studyQ == 0 then
            return
        end
        local xy = Utils.now()
        while Reports.sending and Utils.now() - xy < 8 do
            task.wait(0.25)
        end
        if Reports.sending then
            return
        end
        Reports.sending = true
        local yy, zy = pcall(Reports.postEmbed, string.format("🎌 AA · study · %s · v%s", tostring(Brain.anonId), VERSION), "```json\n" .. Brain.studyQ [1] .. "\n```")
        Reports.sending = nil
        if not (yy and zy) then
            return
        end
        table.remove(Brain.studyQ, 1)
        Brain.studySent = (tonumber(Brain.studySent) or 0) + 1
        pcall(App.saveNow)
        if # Brain.studyQ > 0 then
            task.wait(1.5)
        end
    end
end

function Reports.studyLine(Ay)
    local By, Cy = Ay.unit or {
    }, Ay.run or {
    }
    local Dy = {
    }
    for Ey, Fy in ipairs(By.passives or {
    }) do
        table.insert(Dy, Fy.name .. (Fy.every and (" (every " .. Fy.every .. ")") or "") .. (Fy.pct and (" " .. table.concat(Fy.pct, "/") .. "%") or ""))
    end
    local Gy = By.ability and string.format("%s%s", tostring(By.ability.name or By.ability.id), By.ability.cd and string.format(" every %ds", math.floor(By.ability.cd + 0.5)) or "") or "none"
    return string.format("%s · %s at wave %s in %.1f min, %s · dealt %s (%d%%)%s · %d takedowns · ability %s, cast %d · passives: %s%s · read %d upgrades, %d attacks", tostring(By.name), Cy.won and "won" or "lost", tostring(Cy.wave), (Cy.sec or 0) / 60, Cy.how == "team" and "team fighting" or "alone with the yen", Utils.fmt(Cy.dealt or 0), math.floor((Cy.share or 0) * 100 + 0.5), Cy.summons and string.format(", %d%% of it from summons", math.floor(Cy.summons * 100 + 0.5)) or "", Cy.takedowns or 0, Gy, Cy.casts or 0, # Dy > 0 and table.concat(Dy, ", ") or "none", Cy.toggle and string.format(" · switch ability from upgrade %s", tostring(Cy.toggle.from)) or "", By.ups or 0, # (By.attacks or {
    }))
end

function Modes.pick()
    local Hy = Modes.trialRow()
    if Hy then
        Modes.lastScored = {
            Hy
        }
        return Hy
    end
    local Iy = Modes.list()
    for Jy, Ky in ipairs(Iy) do
        Ky.score = Modes.score(Ky)
        Ky.p = Modes.winP(Ky)
        local Ly = Modes.sim(Ky)
        if Ly and not tostring(Ky.why):find("sim:") then
            local My = Ly.trust and not Ly.trust.ok
            Ky.why = (Ky.why or "") .. " · sim: " .. (My and string.format(Ly.trust.ratio < 0.1 and "not trusted here (off ×%.2f vs real runs)" or "not trusted here (off ×%.1f vs real runs)", Ly.trust.ratio) or tostring(Ly.playing or Ly.margin))
        end
        if Ky.train then
            Ky.why = (Ky.why or "") .. string.format(" · takedown training ≈%d gems of progress", math.floor(Ky.train + 0.5))
        end
    end
    table.sort(Iy, function(Ny, Oy)
        return Ny.score > Oy.score
    end)
    for Py, Qy in ipairs(Iy) do
        if Qy.kind == "dungeon" and Qy.started then
            if Py > 1 and Iy [1].kind ~= "daily" then
                table.remove(Iy, Py)
                table.insert(Iy, 1, Qy)
                Qy.why = "finishing the run · " .. (Qy.why or "")
            end
            break
        end
    end
    if Config.autoEvolve and Config.evolveUnit ~= "" then
        local Ry = Iy [1] and Iy [1].kind == "daily" and Iy [1] or nil
        local Sy, Ty = {
        }, {
        }
        for Uy, Vy in ipairs(Iy) do
            if Vy ~= Ry then
                if Modes.dropsGoal(Vy) or Vy.train then
                    Vy.why = "for your focus unit · " .. (Vy.why or "")
                    table.insert(Sy, Vy)
                else
                    table.insert(Ty, Vy)
                end
            end
        end
        if # Sy > 0 then
            Iy = {
            }
            if Ry then
                table.insert(Iy, Ry)
            end
            for Wy, Xy in ipairs(Sy) do
                table.insert(Iy, Xy)
            end
            for Yy, Zy in ipairs(Ty) do
                table.insert(Iy, Zy)
            end
        end
    end
    for _y, az in ipairs(Iy) do
        local bz, cz = pcall(Modes.sim, az)
        local dz = Config.portalsAny or (bz and cz and (tonumber(cz.p) or 0) >= 0.25) or ((az.rec and tonumber(az.rec.wins)) or 0) > 0
        if az.kind == "portal" and dz then
            local ez = Iy [1]
            if _y > 1 and ez.kind ~= "daily" and not (ez.kind == "dungeon" and ez.started) then
                table.remove(Iy, _y)
                table.insert(Iy, 1, az)
                az.why = "your portal first · " .. (az.why or "")
            end
            break
        end
    end
    for fz, gz in ipairs(Iy) do
        if gz.kind == "artifact" then
            local hz = Iy [1]
            if fz > 1 and (gz.p or 0) >= 0.25 and hz.kind ~= "daily" and hz.kind ~= "portal" and not (hz.kind == "dungeon" and hz.started) and not tostring(hz.why):find("for your focus unit", 1, true) then
                table.remove(Iy, fz)
                table.insert(Iy, 1, gz)
                gz.why = "this rotation's clears · " .. (gz.why or "")
            end
            break
        end
    end
    local iz = Iy [1]
    if iz and iz.kind == "story" and iz.first then
        local jz, kz = iz, (iz.baseScore or iz.score) * Modes.CHAIN_MIN
        for lz = 1, 6 do
            local mz
            for nz, oz in ipairs(Iy) do
                if oz.kind == "story" and oz.first and oz.diff == jz.diff and (oz.baseScore or oz.score) >= kz and Modes.nextAct(oz.level) == jz.level then
                    mz = oz
                    break
                end
            end
            if not mz then
                break
            end
            jz = mz
        end
        if jz ~= iz then
            table.remove(Iy, table.find(Iy, jz))
            table.insert(Iy, 1, jz)
            jz.why = "the first of these acts in a row · " .. (jz.why or "")
        end
    end
    local pz = Brain.testTeam
    if pz and (pz.left or 0) > 0 then
        for qz, rz in ipairs(Iy) do
            if rz.key == pz.key then
                if qz > 1 and Iy [1].kind ~= "daily" and (pz.first or not (Iy [1].kind == "dungeon" and Iy [1].started)) then
                    table.remove(Iy, qz)
                    table.insert(Iy, 1, rz)
                end
                rz.why = string.format("team test, run %d of %d: %s · ", (tonumber(pz.n) or 0) - pz.left + 1, tonumber(pz.n) or 0, tostring(pz.label)) .. (rz.why or "")
                break
            end
        end
    end
    if Brain.nextMode then
        for sz, tz in ipairs(Iy) do
            if tz.key == Brain.nextMode then
                table.remove(Iy, sz)
                table.insert(Iy, 1, tz)
                tz.why = "asked for once · " .. (tz.why or "")
                break
            end
        end
    end
    if Config.dailyLoop then
        for uz, vz in ipairs(Iy) do
            if vz.kind == "daily" then
                table.remove(Iy, uz)
                table.insert(Iy, 1, vz)
                vz.why = "you asked to keep playing it · " .. (vz.why or "")
                break
            end
        end
    end
    Modes.lastScored = Iy
    return Iy [1]
end

function Modes.fromLevelData(wz)
    if not wz then
        return nil
    end
    local xz = wz.id
    if xz == "__DAILY_CHALLENGE" then
        return "dc", "daily"
    end
    if wz._dungeon then
        return "dg", "dungeon"
    end
    if wz._challenge then
        return "ch", "challenge"
    end
    local yz = Core.Levels [xz] and Core.Levels [xz].world
    if yz and Core.Worlds [yz] and Core.Worlds [yz]._artifact_stage then
        return "ar:" .. xz, "artifact"
    end
    if Core.Levels [xz] and Core.Levels [xz]._portal_only_level then
        local zz = tonumber(wz.portal_depth) or tonumber(wz._portal_depth)
        if zz and zz > 0 then
            return "pt:" .. xz .. ":t" .. math.floor(zz), "portal"
        end
        local Az = Brain.pending and Brain.pending.kind == "portal" and type(Brain.pending.key) == "string" and Brain.pending.key or ""
        local Bz = "pt:" .. xz .. ":t"
        if Az:sub(1, # Bz) == Bz and os.time() - (tonumber(Brain.pending.at) or 0) < 1200 then
            return Az, "portal"
        end
        return "pt:" .. xz, "portal"
    end
    if wz._gamemode == "infinite" or wz.infinite then
        return "inf:" .. xz, "infinite"
    end
    if wz._gamemode == "raid" and Brain.live.event and Brain.live.event.level == xz then
        return "ev:" .. xz, "event"
    end
    if wz._gamemode == "raid" or (Core.Levels [xz] and Core.Levels [xz].is_raid) then
        return "rd:" .. xz, "raid"
    end
    if wz._gamemode == "story" then
        return "st:" .. xz .. ":" .. tostring(wz._difficulty or "Normal"), "story"
    end
    return tostring(wz._gamemode) .. ":" .. tostring(xz), tostring(wz._gamemode)
end

function Adventure.levelItems(Cz, Dz)
    local Ez = {
    }
    if type(Cz) ~= "table" then
        return Ez
    end
    Dz = Dz or Cz.id
    local Fz = Cz.rewards
    if type(Fz) == "table" and Fz.item then
        Fz = {
            Fz
        }
    end
    local Gz = false
    for Hz, Iz in pairs(type(Fz) == "table" and Fz or {
    }) do
        if type(Iz) == "table" then
            local Jz = Utils.list(Iz.item)
            local Kz = 1
            if Iz._item_multichoice and # Jz > 0 then
                Kz = math.min(1, (tonumber(Iz._item_multichoice.min) or # Jz) / # Jz)
            end
            for Lz, Mz in ipairs(Jz) do
                if type(Mz) == "table" and Mz.item_id then
                    local Nz = tonumber(Mz.amount) or ((tonumber(Mz.min_amount) or 1) + (tonumber(Mz.max_amount) or tonumber(Mz.min_amount) or 1)) / 2
                    table.insert(Ez, {
                        item = Mz.item_id,
                        per = Nz * (tonumber(Mz.chance) or 1) * Kz
                    })
                    Gz = true
                end
            end
        end
    end
    if not Gz then
        for Oz, Pz in pairs(type(Cz._show_rewards) == "table" and Cz._show_rewards or {
        }) do
            if type(Pz) == "table" and Pz.type == "item" and Pz.params and Pz.params.item_id then
                table.insert(Ez, {
                    item = Pz.params.item_id,
                    per = 1
                })
            end
        end
    end
    local Qz, Rz = pcall(Reports.hiveDrops, Dz)
    if Qz and Rz then
        local Sz = {
        }
        for Tz, Uz in ipairs(Ez) do
            Sz [Uz.item] = Tz
        end
        for Vz, Wz in pairs(Rz) do
            if Sz [Vz] then
                Ez [Sz [Vz]].per = Wz
            else
                table.insert(Ez, {
                    item = Vz,
                    per = Wz
                })
            end
        end
    end
    return Ez
end

function Adventure.sources()
    if Adventure._src then
        return Adventure._src
    end
    local Xz = {
    }
    for Yz, Zz in pairs(Core.Levels) do
        for _z, aA in ipairs(Adventure.levelItems(Zz, Yz)) do
            Xz [aA.item] = Xz [aA.item] or {
            }
            table.insert(Xz [aA.item], {
                level = Yz,
                per = aA.per
            })
        end
    end
    for bA, cA in pairs(Xz) do
        table.sort(cA, function(dA, eA)
            return dA.per > eA.per
        end)
    end
    Adventure._src = Xz
    return Xz
end

function Adventure.have(fA)
    local gA = Core.session()
    local hA = 0
    pcall(function()
        hA = gA.inventory:get_number_of_owned_item(fA)
    end)
    return hA
end

function Adventure.killsShort(iA, jA)
    if not jA then
        return nil
    end
    local kA = tonumber(jA._takedown_requirement)
    if kA and (tonumber(iA.total_takedowns) or 0) < kA then
        return {
            what = "takedowns",
            have = tonumber(iA.total_takedowns) or 0,
            need = kA
        }
    end
    local lA = tonumber(jA._kill_requirement)
    if lA and (tonumber(iA.total_kills) or 0) < lA then
        return {
            what = "kills",
            have = tonumber(iA.total_kills) or 0,
            need = lA
        }
    end
    return nil
end
Adventure.TIER_RANK = {
    SS = 6,
    S = 5,
    A = 4,
    B = 3,
    C = 2,
    D = 1
}

function Adventure.tiers()
    if Adventure._tiers then
        return Adventure._tiers
    end
    local mA = {
    }
    for nA, oA in pairs(Core.Units) do
        if type(oA) == "table" and type(oA.name) == "string" then
            local pA = oA.name:lower()
            if not mA [pA] or (oA.rarity and not Core.Units [mA [pA]].rarity) then
                mA [pA] = nA
            end
        end
    end
    local qA = {
    }
    local function rA(sA, tA)
        return not tA or (Adventure.TIER_RANK [sA] or 0) > (Adventure.TIER_RANK [tA] or 0)
    end
    local function uA(vA, wA, xA, yA)
        qA [vA] = qA [vA] or {
            base = {
            }
        }
        if rA(xA, qA [vA] [wA]) then
            qA [vA] [wA] = xA
        end
        if yA and rA(xA, qA [vA].base [wA]) then
            qA [vA].base [wA] = xA
        end
    end
    for zA, AA in ipairs({
        {
            Core.TIERS,
            true
        },
        {
            Core.TIERS_USER,
            true
        },
        {
            Core.TIERS_EXTRA,
            false
        }
    }) do
        for BA, CA in pairs(AA [1]) do
            for DA, EA in pairs(CA) do
                for FA in EA:gmatch("[^|]+") do
                    local GA = Core.TIER_ALIAS [FA] or mA [FA:lower()]
                    if GA and Core.Units [GA] then
                        uA(GA, BA, DA, AA [2])
                    end
                end
            end
        end
    end
    Adventure._tiers = qA
    return qA
end

function Adventure.tier(HA, IA)
    if not Config.community then
        return nil, nil, 0
    end
    local JA = Adventure.tiers() [HA]
    if IA and JA then
        JA = JA.base
    end
    if not JA then
        return nil, nil, 0
    end
    local KA, LA = Adventure.TIER_RANK [JA.story or ""] or 0, Adventure.TIER_RANK [JA.overall or ""] or 0
    local MA = KA >= LA and JA.story or JA.overall
    if not MA then
        return nil, nil, 0
    end
    return MA, JA, math.max(KA, LA)
end

function Adventure.tierText(NA)
    local OA, PA = Adventure.tier(NA)
    if not OA then
        return nil
    end
    local QA = {
    }
    if PA.story then
        table.insert(QA, "Story " .. PA.story)
    end
    if PA.overall then
        table.insert(QA, "overall " .. PA.overall)
    end
    if PA.infinite then
        table.insert(QA, "Infinite " .. PA.infinite)
    end
    if PA.castle then
        table.insert(QA, "Infinity Castle " .. PA.castle)
    end
    return "tier " .. table.concat(QA, ", ")
end

function Adventure.tierBest(RA, SA)
    local TA = Core.Units [RA]
    local UA = TA and TA.evolve and TA.evolve.evolve_unit
    local VA, WA, XA = Adventure.tier(RA, SA)
    local YA, ZA, _A = Adventure.tier(UA, SA)
    if UA and _A > XA then
        return UA, _A
    end
    return RA, XA
end

function Adventure.role(aB)
    if not Adventure._roles then
        Adventure._roles = {
        }
        for bB, cB in pairs(Core.KEEP_ROLES) do
            for dB, eB in ipairs(cB) do
                Adventure._roles [eB] = bB
            end
        end
    end
    return Adventure._roles [aB]
end

function Adventure.fodderOrder(fB)
    local gB, hB, iB = 0, {
    }, fB
    while iB and Core.Units [iB] and not hB [iB] do
        hB [iB] = true
        if Adventure.role(iB) then
            return nil
        end
        local jB, kB, lB = Adventure.tier(iB)
        gB = math.max(gB, lB)
        local mB = Core.Units [iB]
        iB = mB.evolve and mB.evolve.evolve_unit
    end
    if gB >= Adventure.TIER_RANK.A then
        return nil
    end
    local nB, oB = Adventure.tier(fB)
    if (oB and oB.overall == "D") or gB == Adventure.TIER_RANK.D then
        return 1
    end
    return 2 + gB
end

function Adventure.strongest(pB)
    if Adventure._strong and Adventure._strongN == pB and Utils.now() - Adventure._strongAt < 60 then
        return Adventure._strong
    end
    local qB = Core.session()
    local rB = {
    }
    for sB, tB in pairs(qB.profile_data.collection.owned_units) do
        local uB, vB = pcall(Units.score, qB.collection:get_unit_by_uuid(sB) or tB)
        if uB and tonumber(vB) then
            table.insert(rB, {
                uuid = sB,
                sc = vB
            })
        end
    end
    table.sort(rB, function(wB, xB)
        return wB.sc > xB.sc
    end)
    local yB = {
    }
    for zB = 1, math.min(pB, # rB) do
        yB [rB [zB].uuid] = true
    end
    Adventure._strong, Adventure._strongN, Adventure._strongAt = yB, pB, Utils.now()
    return yB
end

function Adventure.communityText()
    if not Config.community then
        return "Off (Settings → Community tips)."
    end
    local AB = Core.prof()
    if not AB then
        return "…"
    end
    local BB = {
    }
    local function CB(DB, EB, FB)
        local GB = Core.Banners [EB]
        local HB = {
        }
        for IB, JB in pairs(GB and GB.rateup_units or {
        }) do
            if type(JB) == "table" and type(JB.possible_units_set) == "table" then
                for KB in pairs(JB.possible_units_set) do
                    table.insert(HB, KB)
                end
            end
        end
        local LB = {
        }
        for MB, NB in ipairs(HB) do
            local OB, PB = Adventure.tierBest(NB)
            table.insert(LB, {
                r = PB,
                text = string.format("%s %s%s",
                Units.name(OB),
                (Adventure.tier(OB)) or "unrated",
                Units.owns(NB) and " (you have it)" or "")
            })
        end
        table.sort(LB, function(QB, RB)
            return QB.r > RB.r
        end)
        local SB = {
        }
        for TB, UB in ipairs(LB) do
            table.insert(SB, UB.text)
        end
        if # SB > 0 then
            table.insert(BB, string.format("%s (%s): %s", DB, FB, table.concat(SB, " · ")))
        end
    end
    CB("April banner", "April2025", "150 AprilCoins a pull")
    CB("Sakamoto banner", "SakamotoEvent", "10 Assassin Tokens a pull")
    CB("Gem banner", "EventClover", "50 gems a pull")
    local VB = {
    }
    for WB, XB in ipairs(Units.equipped()) do
        if not Units.isFarm(XB.id) and not Units.allyBuff(XB.id) then
            local YB, ZB = Units.types(XB.id)
            if ZB then
                VB [ZB] = true
            end
        end
    end
    local _B, aC = {
    }, {
    }
    for bC, cC in pairs(AB.collection.owned_units) do
        local dC, eC = Adventure.tierBest(cC.unit_id)
        if eC >= 4 and not aC [dC] then
            aC [dC] = true
            local fC = ""
            local gC = Units.allyBuff(dC)
            if gC then
                local hC = false
                for iC in pairs(gC.types or {
                }) do
                    if VB [iC] then
                        hC = true
                    end
                end
                if not hC then
                    for jC in pairs(gC.types or {
                    }) do
                        fC = string.format(" (buffs %s units: your damage dealers aren't)", jC)
                    end
                end
            end
            if dC ~= cC.unit_id then
                fC = fC .. " (evolve " .. Units.name(cC.unit_id) .. ")"
            end
            table.insert(_B, {
                r = eC,
                text = Units.name(dC) .. " " .. ((Adventure.tier(dC)) or "") .. fC
            })
        end
    end
    table.sort(_B, function(kC, lC)
        return kC.r > lC.r
    end)
    local mC = {
    }
    for nC, oC in ipairs(_B) do
        if nC <= 8 then
            table.insert(mC, oC.text)
        end
    end
    if # mC > 0 then
        table.insert(BB, "Yours rated A or better: " .. table.concat(mC, " · "))
    end
    table.insert(BB, "The guides rank evolved, fully upgraded units and ignore traits (a strong trait can move a unit a whole tier). " .. "Their advice: save gems and commit to one banner.")
    return table.concat(BB, "\n")
end

function Adventure.pullGoal()
    local pC = Config.pullGoal
    if type(pC) ~= "string" or pC == "" or type(Core.Units [pC]) ~= "table" then
        return nil
    end
    local qC = Core.prof()
    if not qC then
        return nil
    end
    local rC = Core.Units [pC]
    local sC = rC.evolve and rC.evolve.evolve_unit or pC
    local tC = {
        id = pC,
        to = sC,
        coins = Core.cur("AprilCoins"),
        itemCost = 0,
        needCoins = 0
    }
    for uC, vC in pairs(rC.evolve and rC.evolve.normal and rC.evolve.normal.item_requirement or {
    }) do
        local wC = Core.SaleEvent [vC.item_id]
        if wC and type(wC.resource_cost) == "table" and wC.resource_cost.id == "AprilCoins" then
            tC.item, tC.itemCost = vC.item_id, tonumber(wC.resource_cost.amount) or 0
        end
    end
    tC.haveItem = tC.item ~= nil and Adventure.have(tC.item) > 0
    local xC, yC = FarmHub.hatched [pC] or false, false
    for zC, AC in pairs(qC.collection.owned_units) do
        if AC.unit_id == pC then
            xC = true
        end
        if AC.unit_id == sC then
            yC = true
        end
    end
    if yC then
        tC.step = "done"
    elseif not xC then
        tC.step, tC.needCoins = "pull", 1
    elseif tC.item and not tC.haveItem then
        tC.step, tC.needCoins = "item", math.max(0, tC.itemCost - tC.coins)
    else
        tC.step = "evolve"
    end
    return tC
end

function Adventure.goalText()
    local BC = Adventure.pullGoal()
    if not BC then
        return "No main goal set (Settings: pull goal)."
    end
    local CC = Core.prof()
    local DC = string.format("%s%s · ", Units.name(BC.to), (Adventure.tier(BC.to)) and (" (tier " .. Adventure.tier(BC.to) .. ")") or "")
    if BC.step == "pull" then
        if not Core.Banners.April2025 then
            return DC .. string.format("the April banner isn't in the game right now, so there's nothing to pull %s from. This waits until it comes back.", Units.name(BC.id))
        end
        local EC = math.max(Config.aprilFloor, BC.haveItem and 0 or BC.itemCost)
        local FC = CC and CC.pity_data and CC.pity_data.April2025
        local GC = FC and tonumber(FC.opens_since_mythic)
        return DC .. string.format("step 1 of 3: pull %s from the April banner. You have %s AprilCoins: %d ten-pulls above the %s kept for its evolve item. " .. "Each Mythic from this banner is one of 3 limited units (1 in 3 is %s), and one is guaranteed every 200 pulls%s. " .. "The farm plays Fool's Hunt for AprilCoins (worth %.2f gems each to the ranking while this goal needs them)%s.", Units.name(BC.id), Utils.fmt(BC.coins), math.max(0, math.floor((BC.coins - EC) / 1500)), Utils.fmt(EC), Units.name(BC.id), GC and string.format(" (%d pulls since the last Mythic)", GC) or "", math.max(Config.aprilValue, Config.goalCoinValue), Config.summonApril and " and pulls 10 at a time" or "; April pulls are off (Units → Summon)")
    elseif BC.step == "item" then
        return DC .. string.format("step 2 of 3: you have %s! Its evolve item costs %s AprilCoins in the event shop; you have %s. The farm buys it when the coins are in.", Units.name(BC.id), Utils.fmt(BC.itemCost), Utils.fmt(BC.coins))
    elseif BC.step == "evolve" then
        return DC .. "step 3 of 3: its takedowns come from training (it joins easy runs), then smart evolve evolves it."
    end
    return DC .. "done, it's yours!"
end

function FarmHub.eventShop()
    local HC = Adventure.pullGoal()
    if not (Config.summonApril and HC and HC.step == "item" and HC.coins >= HC.itemCost and HC.itemCost > 0) then
        return
    end
    if App.req.back.eshop and Utils.now() < App.req.back.eshop then
        return
    end
    local IC, JC = App.request("eshop", "buy_item_generic", HC.item, "event", "event_shop", "1")
    local KC = Utils.now()
    while Utils.now() - KC < 4 and Adventure.have(HC.item) < 1 do
        task.wait(0.25)
    end
    local LC = (Core.Items [HC.item] or {
    }).name or HC.item
    if Adventure.have(HC.item) > 0 then
        Spending.add(LC, HC.itemCost, "AprilCoins", "evolve item for " .. Units.name(HC.to))
        if App.notify then
            App.notify("Main goal", "Bought " .. LC .. " for " .. Units.name(HC.id), "success")
        end
        pcall(Adventure.refresh)
    else
        App.log(1, "SHOP", "event shop refused " .. tostring(HC.item) .. " (" .. tostring(IC and JC or "no answer") .. ")")
        App.backoff("eshop", 900)
    end
end

function FarmHub.codes()
    if not Config.codes then
        return App.status("Codes", "off (Settings)")
    end
    local MC = Core.prof()
    if not MC then
        return
    end
    local NC = MC.redeemed_codes or {
    }
    local OC, QC = {
    }, {
    }
    for RC, SC in ipairs(Core.CODES) do
        local TC = tonumber(Brain.codes [SC])
        if NC [SC] then
            if TC and TC > 0 then
                table.insert(QC, SC)
                Brain.codes [SC] = - 1
            end
        elseif os.time() - (TC or 0) > 86400 and (TC or 0) >= 0 then
            Brain.codes [SC] = os.time()
            local UC = App.request("code", "redeem_code", SC)
            if UC then
                table.insert(OC, SC)
            end
            task.wait(1)
        end
    end
    if # QC > 0 then
        App.log(1, "CODES", "the game confirms " .. table.concat(QC, ", "))
    end
    if # OC > 0 then
        App.log(1, "CODES", "sent " .. table.concat(OC, ", ") .. " (the game confirms a code after the next teleport; one it refuses is tried again tomorrow)")
    end
    App.saveSoon()
    local VC = 0
    for WC, XC in ipairs(Core.CODES) do
        if not NC [XC] then
            VC = VC + 1
        end
    end
    App.status("Codes", # OC > 0 and ("sent " .. table.concat(OC, ", ")) or (VC == 0 and "every known code is redeemed ✓" or (VC .. " codes not taken yet, trying again tomorrow")))
end

function Adventure.copies(YC, ZC, _C)
    local aD = Core.session()
    local bD = {
    }
    for cD, dD in pairs(aD and aD.profile_data.collection.owned_units or {
    }) do
        if dD.unit_id == YC and dD.uuid ~= _C and not dD._locked and (not ZC or dD.shiny) then
            table.insert(bD, dD)
        end
    end
    return bD
end

function Adventure.bestSource(eD)
    if not (Modes.lastScored and Modes.lastScored [1]) then
        pcall(Modes.pick)
    end
    local fD = {
    }
    for gD, hD in ipairs(Modes.lastScored or {
    }) do
        if hD.level then
            fD [hD.level] = hD
        end
    end
    local iD, jD
    for kD, lD in ipairs(eD or {
    }) do
        local mD = fD [lD.level]
        local nD, oD = pcall(function()
            return mD and Modes.minutes(mD) or 10
        end)
        local pD = lD.per * (mD and (mD.p or 0.5) or 0.5) / math.max(1, nD and oD or 10)
        if not jD or pD > jD then
            iD, jD = lD, pD
        end
    end
    return iD
end

function Adventure.planItem(qD, rD)
    local sD = Adventure.have(qD)
    if sD >= rD then
        return {
            item = qD,
            done = true
        }
    end
    local tD = Adventure.sources() [qD]
    if tD and tD [1] then
        return {
            item = qD,
            need = rD,
            have = sD,
            farm = qD,
            farmNeed = rD - sD,
            levels = tD
        }
    end
    local uD = Core.SaleEvent [qD]
    if uD and type(uD.resource_cost) == "table" then
        return {
            item = qD,
            need = rD,
            have = sD,
            eventShop = true,
            cost = tonumber(uD.resource_cost.amount) or 0,
            currency = uD.resource_cost.id,
            farmNeed = 0
        }
    end
    for vD, wD in pairs(Brain.raidShop) do
        if wD.id == qD and wD.costItem and (wD.stock == "inf" or (tonumber(wD.stock) or 0) > 0) then
            local xD = Adventure.sources() [wD.costItem]
            local yD = wD.cost * (rD - sD)
            local zD = Adventure.have(wD.costItem)
            return {
                item = qD,
                need = rD,
                have = sD,
                shopKey = vD,
                costItem = wD.costItem,
                cost = wD.cost,
                farm = wD.costItem,
                farmNeed = math.max(0,
                yD - zD),
                levels = xD or {
                }
            }
        end
    end
    for AD, BD in pairs(Modes.PORTALS) do
        if BD.item == qD then
            return {
                item = qD,
                need = rD,
                have = sD,
                farm = qD,
                farmNeed = rD - sD,
                portal = AD,
                levels = {
                    {
                        level = BD.level,
                        per = Modes.portalPer(AD)
                    }
                }
            }
        end
    end
    return {
        item = qD,
        need = rD,
        have = sD,
        unknown = true
    }
end
Modes.PORTALS = {
    portal_item__shibuya = {
        level = "shibuya_portal",
        item = "shibuya_wheel",
        from = "shibuya_infinite",
        per = 10,
        drops = 1
    }
}

function Modes.portalPer(CD)
    local DD = Brain.portalPay [CD]
    if DD and (tonumber(DD.n) or 0) > 0 then
        return tonumber(DD.per), true
    end
    local ED = Modes.PORTALS [CD]
    local FD, GD = pcall(Reports.hiveDrops, ED.level)
    if FD and GD and GD [ED.item] then
        return GD [ED.item], true
    end
    return ED.per, false
end

function Modes.portalDrops(HD)
    local JD = Brain.portalPay ["drop:" .. HD]
    if JD and (tonumber(JD.n) or 0) > 0 then
        return tonumber(JD.per), true
    end
    local KD = Modes.PORTALS [HD]
    local LD, MD = pcall(Reports.hiveDrops, KD.from)
    if LD and MD and MD [HD] then
        return MD [HD], true
    end
    return KD.drops, false
end

function Modes.portalsHeld(ND)
    local OD = Core.prof()
