    }
    local QD = {
    }
    for RD, SD in pairs(PD) do
        if type(SD) == "table" and SD.item_id == ND then
            table.insert(QD, SD.uuid or RD)
        end
    end
    table.sort(QD)
    return QD
end
Modes._spawns = {
}

function Modes.levelSpawns(TD, UD)
    local VD = tostring(TD)
    local WD = Modes._spawns [VD]
    if WD and os.time() - WD.at < 3600 then
        return WD.n
    end
    local XD = 0
    pcall(function()
        local YD = Core.Levels [TD]
        local ZD = Simulator.info(Simulator.slim and Simulator.slim(YD) or YD, "count:" .. VD)
        local _D = false
        for aE, bE in pairs(ZD.configs or {
        }) do
            if UD [aE] or (type(bE) == "table" and UD [bE.unit_id or ""]) then
                _D = true
                break
            end
        end
        if not _D then
            return
        end
        local cE = ZD.infinite and math.floor(Modes.infReach("inf:" .. VD) + 0.5) or ZD.total
        local function dE(eE)
            local fE = ZD.configs [eE]
            return UD [eE] or (type(fE) == "table" and UD [fE.unit_id or ""])
        end
        for gE = 1, math.min(cE or 30, 200) do
            if ZD.infinite then
                local hE, iE = pcall(Core.LU.Infinite.infinite_amt_scale, gE, ZD.ld)
                local jE, kE = 0, 0
                for lE, mE in pairs(ZD.configs) do
                    if type(mE) == "table" and mE.spawn_tier_normal then
                        local nE, oE = pcall(Core.LU.Infinite.infinite_get_normal_unit_chance, mE, gE)
                        oE = nE and tonumber(oE) or 0
                        jE = jE + oE
                        if dE(lE) then
                            kE = kE + oE
                        end
                    end
                end
                if jE > 0 then
                    XD = XD + (hE and tonumber(iE) or 10) * kE / jE
                end
            else
                local pE = ZD.list [gE]
                for qE, rE in ipairs(Utils.list(pE and pE.wave)) do
                    if dE(rE.unit) then
                        XD = XD + (tonumber(rE.amount) or 1)
                    end
                end
            end
        end
        XD = math.floor(XD + 0.5)
    end)
    Modes._spawns [VD] = {
        n = XD,
        at = os.time()
    }
    return XD
end

function Modes.missionValue(sE)
    local tE = Core.session()
    local uE, vE = 0, nil
    for wE, xE in pairs(tE and tE.quest_handler.quest_profile_data.quests or {
    }) do
        local yE = xE.quest_info
        local zE = yE and yE.quest_class
        if zE and zE.class == "kill_unit_multi" and type(zE.unit_ids) == "table" then
            local AE = tonumber(zE.amount) or 0
            local BE = AE - (tonumber(xE.quest_progress and xE.quest_progress.amount) or 0)
            if BE > 0 then
                local CE = Modes.levelSpawns(sE, zE.unit_ids)
                if CE > 0 then
                    local DE = tonumber(yE.quest_reward and yE.quest_reward.gem_reward) or 0
                    for EE, FE in pairs(yE.quest_reward and yE.quest_reward.item or {
                    }) do
                        if type(FE) == "table" and FE.item_id then
                            DE = DE + Modes.itemValue(FE.item_id, tonumber(FE.max_amount or FE.amount or FE.min_amount) or 1)
                        end
                    end
                    uE = uE + DE * math.min(1, CE / BE)
                    vE = string.format("%s: %s/%s, ≈%s a run", tostring(yE.quest_name), Utils.fmt(AE - BE), Utils.fmt(AE), Utils.fmt(math.min(CE, BE)))
                end
            end
        end
    end
    return uE, vE
end

function Modes.portalKinds()
    if Modes._kinds then
        return Modes._kinds
    end
    local GE = {
    }
    for HE, IE in pairs(Core.Items) do
        if type(IE) == "table" and type(IE.usage) == "table" and IE.usage.type == "open_portal" then
            local JE = {
            }
            if IE.usage.level_id then
                table.insert(JE, IE.usage.level_id)
            end
            if type(IE._unique_portal_levels) == "table" then
                for KE in pairs(IE._unique_portal_levels) do
                    table.insert(JE, KE)
                end
            end
            table.sort(JE)
            local LE = {
            }
            local function ME(NE, OE)
                if type(NE) ~= "table" or OE > 4 then
                    return
                end
                if type(NE.item_id) == "string" then
                    LE [NE.item_id] = true
                end
                for PE, QE in pairs(NE) do
                    ME(QE, OE + 1)
                end
            end
            for RE, SE in ipairs(JE) do
                ME((Core.Levels [SE] or {
                }).rewards, 0)
            end
            if Modes.PORTALS [HE] then
                LE [Modes.PORTALS [HE].item] = true
            end
            table.insert(GE, {
                pid = HE,
                name = IE.name or HE,
                rarity = IE.rarity,
                levels = JE,
                drops = LE
            })
        end
    end
    table.sort(GE, function(TE, UE)
        if TE.name ~= UE.name then
            return TE.name < UE.name
        end
        return TE.pid < UE.pid
    end)
    Modes._kinds = GE
    return GE
end

function Modes.portalLevel(VE)
    local WE = Core.prof()
    local XE = (WE.inventory and WE.inventory.unique_items) or WE.unique_items or {
    }
    for YE, ZE in pairs(XE) do
        if type(ZE) == "table" and (ZE.uuid or YE) == VE then
            local _E = type(ZE._unique_item_data) == "table" and ZE._unique_item_data._unique_portal_data
            return type(_E) == "table" and _E.level_id or nil
        end
    end
end

function Modes.portalsHeldData(aF)
    local bF = Core.prof()
    local cF = (bF.inventory and bF.inventory.unique_items) or bF.unique_items or {
    }
    local dF = {
    }
    for eF, fF in pairs(cF) do
        if type(fF) == "table" and fF.item_id == aF then
            local gF = type(fF._unique_item_data) == "table" and fF._unique_item_data._unique_portal_data or {
            }
            local hF = type(gF._ctl) == "table" and gF._ctl or {
            }
            local iF = {
            }
            for jF, kF in pairs(type(hF._levelmodifiers) == "table" and hF._levelmodifiers or {
            }) do
                if type(kF) == "table" and kF.id then
                    table.insert(iF, tostring(kF.id))
                end
            end
            table.insert(dF, {
                uuid = fF.uuid or eF,
                pid = aF,
                level = gF.level_id,
                tier = tonumber(gF.portal_depth) or 0,
                diff = tonumber(gF.difficulty_scale) or 1,
                reward = tonumber(gF._portal_reward_scale) or 1,
                lanes = tonumber(gF._lanes),
                host = tonumber(gF._host_star_remnants) or 0,
                map = gF._override_map,
                weak = hF._weak_against or gF._weak_against,
                strong = hF._strong_against or gF._strong_against,
                mods = iF
            })
        end
    end
    table.sort(dF, function(lF, mF)
        return lF.uuid < mF.uuid
    end)
    return dF
end

function Modes.portalMod(nF)
    local oF, pF = {
        weak = {
        },
        strong = {
        },
        res = {
        }
    }, false
    for qF, rF in pairs(type(nF.weak) == "table" and nF.weak or {
    }) do
        local sF = type(rF) == "table" and rF.damage_type or (type(rF) == "string" and rF) or nil
        if sF and sF ~= "" then
            pF = true
            oF.weak [sF] = Modes.weakAmp(type(rF) == "table" and rF.amplification)
        end
    end
    for tF, uF in pairs(type(nF.strong) == "table" and nF.strong or {
    }) do
        local vF = type(uF) == "table" and uF.damage_type or (type(uF) == "string" and uF) or nil
        local wF = type(uF) == "table" and tonumber(uF.amplification)
        if vF and vF ~= "" then
            pF = true
            if wF and wF < 1 then
                oF.res [vF] = wF
            else
                oF.strong [vF] = true
            end
        end
    end
    return pF and oF or nil
end

function Modes.weakAmp(xF)
    xF = tonumber(xF)
    if not xF then
        return 1.5
    end
    return xF < 1 and 1 + xF or xF
end

function Modes.portalFit(yF, zF)
    local AF = Modes.portalMod(yF)
    if not AF then
        return 1
    end
    local BF, CF = 0, 0
    for DF, EF in ipairs(zF or {
    }) do
        if not Units.isFarm(EF.id) and not Units.allyBuff(EF.id) then
            local FF, GF = pcall(Units.score, EF.u)
            GF = FF and tonumber(GF) or 0
            BF = BF + GF
            CF = CF + GF * Units.elem(EF.id, AF)
        end
    end
    return BF > 0 and CF / BF or 1
end

function Modes.portalRows()
    local HF = {
    }
    local IF = Config.pickPortal or "smart"
    if IF == "off" or Config.portals == false then
        return HF
    end
    local JF = FarmHub.badPortal or {
    }
    local KF = Brain.testTeam
    local function LF(MF)
        for NF, OF in ipairs(Modes.portalKinds()) do
            local PF = MF or IF == OF.pid or (KF and (KF.left or 0) > 0 and KF.pid == OF.pid)
            if PF or IF == "smart" then
                local QF = Modes.portalsHeld(OF.pid)
                local RF = {
                }
                for SF in pairs(OF.drops) do
                    if (Brain.goalNeed [SF] or 0) > 0 then
                        table.insert(RF, SF)
                    end
                end
                table.sort(RF)
                if # QF > 0 and (PF or # RF > 0) then
                    local TF = Units.equipped()
                    local UF, VF = {
                    }, {
                    }
                    for WF, XF in ipairs(Modes.portalsHeldData(OF.pid)) do
                        VF [XF.tier] = (VF [XF.tier] or 0) + 1
                        XF.fit = Modes.portalFit(XF, TF)
                        local YF = UF [XF.tier]
                        local ZF = not YF or (JF [XF.uuid] or 0) < (JF [YF.uuid] or 0) or ((JF [XF.uuid] or 0) == (JF [YF.uuid] or 0) and XF.fit > YF.fit)
                        if ZF then
                            UF [XF.tier] = XF
                        end
                    end
                    for _F, aG in pairs(UF) do
                        local bG = aG.level or Modes.portalLevel(aG.uuid) or OF.levels [1]
                        if bG and Core.Levels [bG] and Modes.open(bG) then
                            local cG = tonumber(Core.Levels [bG]._override_gem_reward) or 0
                            local dG, eG = cG, {
                            }
                            local fG = Modes.PORTALS [OF.pid]
                            for gG, hG in ipairs(RF) do
                                local iG, jG = 1, true
                                if fG and fG.item == hG then
                                    iG, jG = Modes.portalPer(OF.pid)
                                end
                                dG = dG + Modes.itemValue(hG, iG)
                                table.insert(eG, string.format("≈%s %s a run%s", Utils.fmt(iG), (Core.Items [hG] or {
                                }).name or hG, jG and "" or " (a guess until one is played)"))
                            end
                            local kG, lG = pcall(Reports.hiveDrops, bG)
                            for mG, nG in pairs(kG and type(lG) == "table" and lG or {
                            }) do
                                if not table.find(RF, mG) then
                                    dG = dG + Modes.itemValue(mG, tonumber(nG) or 0)
                                end
                            end
                            dG = dG * aG.reward + aG.host * Modes.itemValue("star_remnant_limited", 1)
                            local oG = {
                                key = _F > 0 and ("pt:" .. bG .. ":t" .. _F) or ("pt:" .. bG),
                                kind = "portal",
                                level = bG,
                                diff = "Hard",
                                portal = aG.uuid,
                                first = false,
                                picked = PF or nil,
                                value = dG,
                                p0 = Modes.PRIOR_WIN.hard,
                                label = Modes.levelName(bG) .. (_F > 0 and string.format(" (Tier %d)",
                                _F) or ""),
                                tier = _F,
                                mod = Modes.portalMod(aG),
                                why = string.format("%s%s: %s%s · you hold %d%s",
                                MF and "none left of your pick, so your other portals · " or (PF and "your pick · " or ""),
                                OF.name,
                                # eG > 0 and table.concat(eG,
                                ", ") or (cG .. " gems a run"),
                                _F > 0 and string.format(" · Tier %d%s, enemies ×%.1f, rewards ×%.1f",
                                _F,
                                aG.lanes and string.format(" (%d lane%s)",
                                aG.lanes,
                                aG.lanes == 1 and "" or "s") or "",
                                aG.diff,
                                aG.reward) or "",
                                VF [_F],
                                aG.host > 0 and string.format(" · the host gets %d Limited Star Remnant%s",
                                aG.host,
                                aG.host == 1 and "" or "s") or "")
                            }
                            if aG.diff ~= 1 or aG.map or aG.lanes then
                                local pG = table.clone(Core.Levels [bG])
                                pG._lobby_difficulty_scale = aG.diff
                                if aG.map then
                                    pG.map = aG.map
                                end
                                if aG.lanes then
                                    pG._portal_lanes = aG.lanes
                                end
                                oG.ldOverride = pG
                            end
                            if # aG.mods > 0 then
                                oG.why = oG.why .. " · modifiers: " .. table.concat(aG.mods, ", ")
                            end
                            table.insert(HF, oG)
                        end
                    end
                end
            end
        end
    end
    LF(false)
    if # HF == 0 and ((IF ~= "smart" and # Modes.portalsHeld(IF) == 0) or Config.onlyPortals) then
        LF(true)
    end
    return HF
end

function Modes.portalBonus(qG)
    if Config.pickPortal == "off" or Config.portals == false then
        return 0, nil
    end
    for rG, sG in pairs(Modes.PORTALS) do
        if sG.from == qG and (Brain.goalNeed [sG.item] or 0) > 0 then
            local tG, uG = Modes.portalDrops(rG)
            local vG = Modes.portalPer(rG)
            return tG * Modes.itemValue(sG.item, vG), string.format("≈%s %s a run%s, for %s", Utils.fmt(tG), (Core.Items [rG] or {
            }).name or rG, uG and "" or " (a guess)", (Core.Items [sG.item] or {
            }).name or sG.item)
        end
    end
    return 0, nil
end

function Adventure.goals()
    local wG = Core.session()
    if not wG then
        return {
        }
    end
    local xG = Units.equipped()
    local yG = math.huge
    for zG, AG in ipairs(xG) do
        if not Units.isFarm(AG.id) and not Units.allyBuff(AG.id) then
            local BG, CG = pcall(Units.score, AG.u)
            if BG then
                yG = math.min(yG, CG)
            end
        end
    end
    local EG = {
    }
    for FG, GG in ipairs(xG) do
        EG [GG.uuid] = true
    end
    local HG = Config.autoEvolve and Config.evolveUnit ~= "" and Config.evolveUnit or nil
    local IG = {
    }
    for JG, KG in pairs(wG.profile_data.collection.owned_units) do
        local LG = Core.Units [KG.unit_id]
        if LG and LG.evolve and LG.evolve.evolve_unit and not LG.evolve.hide_from_ui and Core.Units [LG.evolve.evolve_unit] then
            local MG, NG = pcall(Units.score, wG.collection:get_unit_by_uuid(KG.uuid) or KG)
            NG = (MG and NG or 0) + (EG [KG.uuid] and 0.5 or 0) + (KG.uuid == HG and 1e30 or 0)
            if not IG [KG.unit_id] or NG > IG [KG.unit_id].sc then
                IG [KG.unit_id] = {
                    u0 = KG,
                    sc = NG
                }
            end
        end
    end
    local OG = {
    }
    local PG = {
    }
    for QG, RG in pairs(wG.profile_data.collection.owned_units) do
        PG [RG.unit_id] = true
    end
    for SG, TG in pairs(IG) do
        local UG = TG.u0
        local VG = Core.Units [UG.unit_id]
        if not PG [VG.evolve.evolve_unit] or UG.uuid == HG then
            local WG = UG.shiny and VG.evolve.shiny or VG.evolve.normal
            local XG, YG, ZG = true, {
            }, {
            }
            for aH, bH in pairs(WG and WG.unit_requirement or {
            }) do
                local cH = (tonumber(bH.amount) or 1) - (bH.unit_id == UG.unit_id and 1 or 0)
                if cH > 0 then
                    local dH = # Adventure.copies(bH.unit_id, bH.shiny, UG.uuid)
                    if dH < cH then
                        XG = false
                        table.insert(ZG, {
                            copies = bH.unit_id,
                            have = dH,
                            need = cH
                        })
                    end
                    table.insert(YG, {
                        id = bH.unit_id,
                        amount = cH,
                        shiny = bH.shiny and true or nil
                    })
                end
            end
            local eH = {
            }
            for fH, gH in pairs(WG and WG.item_requirement or {
            }) do
                table.insert(eH, {
                    id = gH.item_id,
                    amount = tonumber(gH.amount) or 1
                })
            end
            local hH = UG.uuid == HG or nil
            if WG and (XG or hH) then
                local iH = wG.collection:get_unit_by_uuid(UG.uuid) or UG
                local jH = {
                    unit_id = VG.evolve.evolve_unit,
                    uuid = "evo:" .. tostring(iH.uuid),
                    xp = iH.xp,
                    traits = iH.traits,
                    trait_stats = iH.trait_stats,
                    further_modifiers = iH.further_modifiers
                }
                local kH, lH = pcall(Units.score, iH)
                local mH, nH = pcall(Units.score, jH)
                lH, nH = kH and lH or 0, mH and nH or 0
                local oH, pH = pcall(Core.USC.calculate_xp, VG.evolve.evolve_unit, 100)
                local qH, rH = pcall(Units.score, {
                    unit_id = VG.evolve.evolve_unit,
                    uuid = "evo100:" .. tostring(iH.uuid),
                    xp = math.max(tonumber(iH.xp) or 0,
                    oH and tonumber(pH) or 0),
                    traits = iH.traits,
                    trait_stats = iH.trait_stats,
                    further_modifiers = iH.further_modifiers
                })
                rH = qH and tonumber(rH) or nH
                local sH = Units.hidden(UG.unit_id) or Units.hidden(VG.evolve.evolve_unit)
                local tH, uH, vH, wH = {
                }, 0, false, true
                local xH = Adventure.killsShort(iH, WG)
                if xH then
                    wH = false
                    table.insert(tH, {
                        takedown = true,
                        what = xH.what,
                        have = xH.have,
                        need = xH.need
                    })
                end
                for yH, zH in ipairs(ZG) do
                    wH = false
                    table.insert(tH, zH)
                end
                for AH, BH in pairs(WG.item_requirement or {
                }) do
                    local CH = Adventure.planItem(BH.item_id, BH.amount or 1)
                    if not CH.done then
                        wH = false
                        table.insert(tH, CH)
                        if CH.unknown then
                            vH = true
                        elseif CH.farmNeed > 0 then
                            CH.best = Adventure.bestSource(CH.levels)
                            uH = uH + CH.farmNeed / math.max(0.1, CH.best and CH.best.per or 1)
                        end
                    end
                end
                local DH, EH, FH = Adventure.tier(VG.evolve.evolve_unit)
                if nH > lH or sH or hH then
                    table.insert(OG, {
                        uuid = UG.uuid,
                        from = UG.unit_id,
                        to = VG.evolve.evolve_unit,
                        scoreFrom = lH,
                        scoreTo = nH,
                        scoreFull = rH,
                        gain = sH and 0 or nH - lH,
                        pinned = hH,
                        intoTeam = hH or (not sH and nH > yG) or (sH and FH >= Adventure.TIER_RANK.S),
                        ready = wH,
                        unknown = vH,
                        hidden = sH or nil,
                        rating = Adventure.tierText(VG.evolve.evolve_unit),
                        tierRank = FH,
                        plans = tH,
                        runs = uH,
                        items = eH,
                        eats = YG
                    })
                end
            end
        end
    end
    table.sort(OG, function(GH, HH)
        if (GH.pinned or false) ~= (HH.pinned or false) then
            return GH.pinned or false
        end
        local IH, JH = (GH.hidden and not GH.intoTeam) or false, (HH.hidden and not HH.intoTeam) or false
        if IH ~= JH then
            return not IH
        end
        if GH.ready ~= HH.ready then
            return GH.ready
        end
        if GH.unknown ~= HH.unknown then
            return not GH.unknown
        end
        if GH.intoTeam ~= HH.intoTeam then
            return GH.intoTeam
        end
        return GH.gain / math.max(1, GH.runs) > HH.gain / math.max(1, HH.runs)
    end)
    return OG
end

function Adventure.text(KH)
    local LH = {
    }
    for MH, NH in ipairs(KH.plans) do
        local OH = (Core.Items [NH.item] or {
        }).name or NH.item
        if NH.takedown then
            table.insert(LH, string.format("%s %s/%s (it earns them on your team)", NH.what, Utils.fmt(NH.have), Utils.fmt(NH.need)))
        elseif NH.copies then
            table.insert(LH, string.format("spare copies of %s %d/%d (unlocked, from summons)", Units.name(NH.copies), NH.have, NH.need))
        elseif NH.unknown then
            table.insert(LH, OH .. ": source unknown (event/portal)")
        elseif NH.portal then
            local PH = Modes.PORTALS [NH.portal]
            table.insert(LH, string.format("%s %d/%d from %s (you hold %d; %s drops them)", OH, NH.have, NH.need, (Core.Items [NH.portal] or {
            }).name or NH.portal, # Modes.portalsHeld(NH.portal), Modes.levelName(PH.from)))
        elseif NH.eventShop then
            table.insert(LH, string.format("%s from the event shop: %s/%s %s", OH, Utils.fmt(Core.cur(NH.currency)), Utils.fmt(NH.cost), tostring(NH.currency)))
        elseif NH.shopKey then
            table.insert(LH, string.format("%s from the raid shop: %d/%d %s", OH, Adventure.have(NH.costItem), NH.cost * (NH.need - NH.have), (Core.Items [NH.costItem] or {
            }).name or NH.costItem))
        else
            table.insert(LH, string.format("%s %d/%d", OH, NH.have, NH.need))
        end
    end
    local QH = ""
    local RH
    for SH, TH in ipairs(KH.plans) do
        if TH.levels and TH.levels [1] then
            RH = TH
            break
        end
    end
    local UH = RH and (RH.best or RH.levels [1])
    if UH then
        QH = string.format(" · farm %s (≈%.0f a run, ≈%d runs)", Modes.levelName(UH.level), UH.per, math.ceil(KH.runs))
    end
    local VH = KH.hidden and "strength unknown (the game shows its upgrades only in a match)" or string.format("score %s → %s", Utils.fmt(KH.scoreFrom), Utils.fmt(KH.scoreTo))
    return string.format("%s → %s · %s%s%s · %s%s", Units.name(KH.from), Units.name(KH.to), VH, KH.intoTeam and " (joins your team)" or "", KH.rating and (" · " .. KH.rating) or "", KH.ready and "ready to evolve" or table.concat(LH, "; "), KH.ready and "" or QH)
end

function Adventure.refresh()
    local WH = Adventure.goals()
    local XH = table.clone(WH)
    table.sort(XH, function(YH, ZH)
        local _H, aI = tonumber(YH.tierRank) or 0, tonumber(ZH.tierRank) or 0
        if _H ~= aI then
            return _H > aI
        end
        local bI, cI = tonumber(YH.scoreFull) or 0, tonumber(ZH.scoreFull) or 0
        if bI ~= cI then
            return bI > cI
        end
        return tostring(YH.uuid) < tostring(ZH.uuid)
    end)
    Brain.goalsTop = {
    }
    for dI, eI in ipairs(XH) do
        if dI <= 10 or eI.pinned then
            table.insert(Brain.goalsTop, {
                uuid = eI.uuid,
                from = eI.from,
                to = eI.to,
                ready = eI.ready,
                intoTeam = eI.intoTeam,
                unknown = eI.unknown,
                hidden = eI.hidden,
                pinned = eI.pinned,
                text = Adventure.text(eI)
            })
        end
    end
    Brain.goals = {
    }
    table.clear(Brain.goalItems)
    table.clear(Brain.goalNeed)
    local fI = 0
    local gI = WH [1] and WH [1].pinned
    for hI, iI in ipairs(WH) do
        table.insert(Brain.goals, {
            uuid = iI.uuid,
            from = iI.from,
            to = iI.to,
            ready = iI.ready,
            intoTeam = iI.intoTeam,
            unknown = iI.unknown,
            hidden = iI.hidden,
            tierRank = iI.tierRank,
            text = Adventure.text(iI),
            gain = iI.gain,
            runs = iI.runs,
            plans = iI.plans,
            items = iI.items,
            eats = iI.eats,
            scoreFrom = iI.scoreFrom,
            scoreTo = iI.scoreTo,
            pinned = iI.pinned
        })
        if not iI.ready and (iI.pinned or (not gI and Config.goals and not iI.unknown and (not iI.hidden or iI.intoTeam) and (iI.intoTeam or fI == 0) and fI < 2)) then
            fI = fI + 1
            for jI, kI in ipairs(iI.plans) do
                if kI.farm and kI.farmNeed > 0 then
                    local lI = Config.goalValue * (iI.intoTeam and 1 or 0.4) / (fI == 1 and 1 or 2) / math.max(1, kI.farmNeed)
                    Brain.goalItems [kI.farm] = math.max(Brain.goalItems [kI.farm] or 0, lI)
                    Brain.goalNeed [kI.farm] = math.max(Brain.goalNeed [kI.farm] or 0, kI.farmNeed)
                end
            end
        end
        if # Brain.goals >= 12 then
            break
        end
    end
    App.saveSoon()
    return WH
end

function Adventure.buyShopGoals()
    if not Config.raidShopGoals then
        return
    end
    for mI, nI in ipairs(Brain.goals) do
        for oI, pI in ipairs(nI.plans or {
        }) do
            if pI.shopKey and pI.costItem and Adventure.have(pI.item) < pI.need and Adventure.have(pI.costItem) >= pI.cost then
                local qI = Adventure.have(pI.costItem)
                local rI, sI = App.request("rshop", "buy_raidshop_shop_item", pI.shopKey, "1")
                local tI = Utils.now()
                while Utils.now() - tI < 3 and Adventure.have(pI.costItem) >= qI do
                    task.wait(0.2)
                end
                if rI and Adventure.have(pI.costItem) < qI then
                    Spending.add((Core.Items [pI.item] or {
                    }).name or pI.item, pI.cost, (Core.Items [pI.costItem] or {
                    }).name or pI.costItem, "for " .. Units.name(nI.to))
                    if App.notify then
                        App.notify("Goals", string.format("Bought %s for %s (Units → Goals)", (Core.Items [pI.item] or {
                        }).name or pI.item, Units.name(nI.from)), "success")
                    end
                    return true
                else
                    App.log(1, "SHOP", "raid shop refused " .. tostring(pI.shopKey) .. " (" .. tostring(sI) .. ")")
                    App.backoff("rshop", 900)
                end
                return
            end
        end
    end
end

function Adventure.lbText()
    local uI = Core.session()
    if not uI then
        return "…"
    end
    local vI = Brain.lb
    local wI = Adventure.have("divine_wish")
    local xI = {
    }
    for yI, zI in ipairs(Units.equipped()) do
        xI [zI.uuid] = true
    end
    local AI, BI = 0, 0
    for CI, DI in pairs(uI.profile_data.collection.owned_units) do
        local EI = Core.Units [DI.unit_id]
        if EI and (EI.rarity == "Mythic" or EI.rarity == "Secret") and not EI._event_unit and not xI [CI] then
            local FI, GI, HI = pcall(Core.USC.is_unit_good_for_fusion, {
                uuid = "x"
            }, DI)
            HI = (FI and GI) and (tonumber(HI) or 1) or 0
            if DI._locked then
                BI = BI + HI
            else
                AI = AI + HI
            end
        end
    end
    local II, JI
    for KI, LI in ipairs(Units.equipped()) do
        local MI = LI.u.further_modifiers and LI.u.further_modifiers.limit_break and LI.u.further_modifiers.limit_break.current_limit_break or 0
        if MI < 1 and not Units.isFarm(LI.id) then
            local NI, OI = pcall(Units.score, LI.u)
            if NI and (not JI or OI > JI) then
                II, JI = LI, OI
            end
        end
    end
    local PI = vI and tonumber(vI.requirement) or 12
    return string.format("Best target: %s (your strongest unit; level cap 100 → 110 ≈ +20%% damage after levelling, and +5%% damage for your whole team). " .. "Needs %d fuel points: you have %d in unlocked Mythic/Secret units (+%d in locked ones) and %d Divine Wish. " .. "It destroys the fuel units, so the farm never does it — the Unit Fusion NPC does it when you choose.", II and Units.name(II.id) or "—", PI, AI, BI, wI)
end
Strategy.LOG = "POWER"

function Strategy.traitName(QI, RI)
    if not QI then
        return "no trait"
    end
    local SI = Core.traitInfo(QI)
    local TI = SI and SI.name or tostring(QI)
    return TI .. ((RI and tostring(RI) ~= "1") and (" " .. tostring(RI)) or "")
end

function Strategy.role(VI)
    if Units.isFarm(VI) then
        return "farm"
    elseif Units.allyBuff(VI) then
        return "buffer"
    end
    return "carry"
end
Strategy._salt = 0

function Strategy.whatIf(WI, XI)
    Strategy._salt = Strategy._salt + 1
    local YI = {
    }
    for ZI, _I in pairs(WI) do
        YI [ZI] = _I
    end
    YI.uuid = "what:" .. Strategy._salt .. ":" .. tostring(WI.uuid)
    for aJ, bJ in pairs(XI or {
    }) do
        YI [aJ] = bJ
    end
    return YI
end

function Strategy.base(cJ)
    return Strategy.score(Strategy.whatIf(cJ, {
    }))
end

function Strategy.score(dJ)
    local eJ, fJ = pcall(Units.score, dJ)
    return (eJ and tonumber(fJ)) or 0
end

function Strategy.level(gJ)
    local hJ, iJ = pcall(Core.USC.calculate_level, gJ.unit_id, tonumber(gJ.xp) or 0)
    return (hJ and tonumber(iJ)) or 1
end

function Strategy.cap(jJ)
    local kJ, lJ = pcall(Core.USC.get_max_level, jJ)
    return (kJ and tonumber(lJ)) or 100
end

function Strategy.xpFor(mJ, nJ)
    local oJ, pJ = pcall(Core.USC.calculate_xp, mJ, nJ)
    return (oJ and tonumber(pJ)) or 0
end

function Strategy.lb(qJ)
    local rJ = qJ.further_modifiers
    return (rJ and rJ.limit_break and tonumber(rJ.limit_break.current_limit_break)) or 0
end

function Strategy.share(sJ)
    local tJ = Brain.str.share [sJ]
    if tJ and (Brain.str.shareN or 0) >= 3 then
        return math.max(0.05, tJ)
    end
    local uJ, vJ = 0, 0
    for wJ, xJ in ipairs(Units.equipped()) do
        if not Units.isFarm(xJ.id) then
            local yJ = Strategy.score(xJ.u)
            uJ = uJ + yJ
            if xJ.id == sJ then
                vJ = yJ
            end
        end
    end
    return math.max(0.05, uJ > 0 and vJ / uJ or 0.1)
end

function Strategy.learn(zJ, AJ)
    Brain.str.shareN = (Brain.str.shareN or 0) + 1
    local BJ = math.max(0.1, 1 / Brain.str.shareN)
    for CJ, DJ in ipairs(AJ or {
    }) do
        if DJ.id and not Units.isFarm(DJ.id) then
            local EJ = zJ [DJ.id] or 0
            local FJ = Brain.str.share [DJ.id]
            Brain.str.share [DJ.id] = FJ and (FJ + (EJ - FJ) * BJ) or EJ
        end
    end
    App.saveSoon()
end

function Strategy.core(GJ)
    local HJ = Core.session()
    if not HJ then
        return Brain.str.core or {
        }
    end
    local IJ = {
    }
    if type(Brain.savedTeam) == "table" and # Brain.savedTeam > 0 then
        for JJ, KJ in ipairs(Brain.savedTeam) do
            local LJ = HJ.collection:get_unit_by_uuid(KJ)
            if LJ then
                table.insert(IJ, {
                    uuid = KJ,
                    id = LJ.unit_id
                })
            end
        end
    end
    if # IJ == 0 then
        for MJ, NJ in ipairs(Units.equipped()) do
            table.insert(IJ, {
                uuid = NJ.uuid,
                id = NJ.id
            })
        end
    end
    local OJ = {
    }
    for PJ, QJ in ipairs(IJ) do
        table.insert(OJ, QJ.uuid)
    end
    table.sort(OJ)
    local RJ = table.concat(OJ, ",")
    if not GJ and # (Brain.str.core or {
    }) >= 6 and os.time() - (tonumber(Brain.str.coreAt) or 0) < (Config.teamCoreDays or 7) * 86400 then
        if Brain.str.teamSig == RJ then
            return Brain.str.core
        end
        if Brain.str.pendingSig ~= RJ then
            Brain.str.pendingSig, Brain.str.pendingAt = RJ, os.time()
            return Brain.str.core
        end
        if os.time() - (tonumber(Brain.str.pendingAt) or 0) < 600 then
            return Brain.str.core
        end
    end
    Brain.str.pendingSig, Brain.str.pendingAt = nil, nil
    local SJ, TJ = {
    }, {
    }
    for UJ, VJ in ipairs(IJ) do
        table.insert(SJ, VJ.uuid)
        TJ [VJ.id] = true
    end
    for WJ, XJ in ipairs({
        "evolveUnit",
        "fuseUnit",
        "focusDone"
    }) do
        local YJ = Config [XJ]
        local ZJ = YJ ~= "" and HJ.collection:get_unit_by_uuid(YJ)
        if ZJ and not table.find(SJ, YJ) then
            table.insert(SJ, YJ)
            TJ [ZJ.unit_id] = true
        end
    end
    local _J = {
    }
    for aK, bK in pairs(Brain.simTeam or {
    }) do
        if type(bK) == "table" and os.time() - (tonumber(bK.at) or 0) < 7 * 86400 then
            for cK, dK in ipairs(bK.names or {
            }) do
                _J [dK] = (_J [dK] or 0) + 1
            end
        end
    end
    local eK = {
    }
    for fK, gK in pairs(HJ.profile_data.collection.owned_units) do
        local hK = Core.Units [gK.unit_id]
        if hK and (hK.rarity == "Mythic" or hK.rarity == "Secret") and not TJ [gK.unit_id] and Units.rows(gK.unit_id) and not Units.hidden(gK.unit_id) and not Units.isFarm(gK.unit_id) and not Units.allyBuff(gK.unit_id) then
            local iK = HJ.collection:get_unit_by_uuid(fK) or gK
            table.insert(eK, {
                uuid = fK,
                id = gK.unit_id,
                k = (_J [Units.name(gK.unit_id)] or 0) * 1e12 + Strategy.score(iK)
            })
        end
    end
    table.sort(eK, function(jK, kK)
        if jK.k ~= kK.k then
            return jK.k > kK.k
        end
        return jK.uuid < kK.uuid
    end)
    for lK, mK in ipairs(eK) do
        if # SJ >= 8 then
            break
        end
        if not TJ [mK.id] then
            table.insert(SJ, mK.uuid)
            TJ [mK.id] = true
        end
    end
    Brain.str.core, Brain.str.coreAt, Brain.str.teamSig = SJ, os.time(), RJ
    local nK = {
    }
    for oK, pK in ipairs(SJ) do
        local qK = HJ.collection:get_unit_by_uuid(pK)
        if qK then
            table.insert(nK, Units.name(qK.unit_id))
        end
    end
    App.log(1, Strategy.LOG, "core units: " .. table.concat(nK, ", "))
    App.saveSoon()
    return SJ
end

function Strategy.gainXp(rK, sK)
    local tK, uK = tonumber(rK.xp) or 0, Strategy.xpFor(rK.unit_id, Strategy.cap(rK))
    local vK = math.max(0, uK - tK)
    if vK <= 0 or (sK or 0) <= 0 then
        return 0, 0
    end
    local wK = math.min(sK, vK)
    local xK = Strategy.base(rK)
    if xK <= 0 then
        return 0, wK
    end
    return Strategy.share(rK.unit_id) * (Strategy.score(Strategy.whatIf(rK, {
        xp = tK + wK
    })) / xK - 1) * 100, wK
end

function Strategy.gainFuse(yK)
    if Strategy.lb(yK) >= 1 then
        return 0
    end
    local zK = Strategy.base(yK)
    if zK <= 0 then
        return 0
    end
    local AK = Strategy.whatIf(yK, {
        xp = math.max(tonumber(yK.xp) or 0,
        Strategy.xpFor(yK.unit_id,
        110)),
        further_modifiers = {
            limit_break = {
                current_limit_break = 1
            }
        }
    })
    return Strategy.share(yK.unit_id) * (Strategy.score(AK) / zK - 1) * 100 + 5
end
Strategy.MAX_RELICS = 6
Strategy.RELIC_MOVE_GAIN = 0.5
Strategy.RELIC_SETTLED_GAIN = 2

function Strategy.relicBar()
    if Brain.str.relicTeam == nil or Brain.str.relicTeam == Modes.teamSig() then
        return Strategy.RELIC_SETTLED_GAIN
    end
    return Strategy.RELIC_MOVE_GAIN
end

function Strategy.relicWorth(BK, CK)
    local DK = CK._unique_item_data and CK._unique_item_data._unique_relic_data
    if not DK then
        return 0
    end
    local EK = Core.Items [CK.item_id] or {
    }
    local FK, GK = Units.types(BK.unit_id)
    if EK.main_damage_type and EK.main_damage_type ~= "both" and EK.main_damage_type ~= GK then
        return 0
    end
    local HK, IK = 0, 0
    for JK, KK in pairs(DK._core_damage_type_buffs or {
    }) do
        if FK [KK.damage_type] then
            HK = HK + (tonumber(KK.mul) or 0) + (tonumber(KK.add_upg) or 0) * 0.01 + (tonumber(KK.pen) or 0) * 0.001
            IK = IK + (tonumber(KK.crit) or 0)
        end
    end
    HK = HK + IK * 0.5
    local LK = Units.rows(BK.unit_id)
    local MK = LK and LK [LK.max]
    local NK = (MK and tonumber(MK.cd) or 0) * Units.mult(BK, "attack_cooldown")
    for OK, PK in pairs(DK._unique_relic_effects or {
    }) do
        local QK = type(PK.params) == "table" and PK.params or {
        }
        if PK.id == "hourglass_relic" then
            local RK = math.min(1, (tonumber(QK.extra_damage) or 0) * NK / math.max(1, tonumber(QK.time_interval) or 40))
            local SK = Units.DRONES and Units.DRONES [BK.unit_id]
            if SK and SK.late and NK > 0 then
                local TK = 1 / NK
                RK = RK * TK / (TK + (tonumber(SK.max) or 0) * (tonumber(SK.late.dmg) or 0) * (tonumber(SK.hits) or 1) / math.max(0.1, tonumber(SK.late.cd) or 4))
            end
            HK = HK + RK
        elseif PK.id == "yuno_clover" then
            HK = HK + (tonumber(QK.dmg_buff) or 0) * 0.25
        elseif PK.id == "nail" then
            HK = HK + (tonumber(QK.dmg_buff) or 0) * IK
        elseif PK.id == "asta_clover" then
            if FK.magic then
                HK = 0
            else
                HK = HK + (tonumber(QK.dmg_buff) or 0) * 0.3
            end
        elseif PK.id == "noelle_crown" then
            if FK.water_damage then
                HK = HK + 0.05
            end
        end
    end
    return HK
end

function Strategy.relicPlan()
    local UK = Core.session()
    if not UK then
        return nil
    end
    local VK = UK.inventory and UK.inventory.inventory_profile_data or {
    }
    local WK = {
    }
    for XK, YK in ipairs(VK.unique_items or {
    }) do
        if type(YK) == "table" and YK.uuid and (Core.Items [YK.item_id] or {
        }).item_group == "Relics" then
            table.insert(WK, YK)
        end
    end
    local ZK = {
    }
    for _K, aL in ipairs(Units.equipped()) do
        local bL = aL.data and aL.data.rarity
        if not Units.isFarm(aL.id) and (bL == "Legendary" or bL == "Mythic" or bL == "Secret" or bL == "Exclusive") then
            local cL = Strategy.share(aL.id)
            if not Brain.str.share [aL.id] then
                cL = math.min(cL, 0.15)
            end
            local dL = {
            }
            for eL, fL in ipairs(WK) do
                local gL = Strategy.relicWorth(aL.u, fL) * cL * 100
                if gL > 0.01 then
                    table.insert(dL, {
                        it = fL,
                        w = gL
                    })
                end
            end
            table.sort(dL, function(hL, iL)
                if hL.w ~= iL.w then
                    return hL.w > iL.w
                end
                return hL.it.uuid < iL.it.uuid
            end)
            local jL, kL = {
            }, {
            }
            for lL, mL in ipairs(dL) do
                local nL = kL [mL.it.item_id] or 0
                if # jL < 6 and nL < ((Core.Items [mL.it.item_id] or {
                }).unique_equip and 1 or 2) then
                    kL [mL.it.item_id] = nL + 1
                    table.insert(jL, mL)
                end
            end
            if aL.u._equipped_relic then
                local oL = false
                for pL, qL in ipairs(jL) do
                    if qL.it.uuid == aL.u._equipped_relic then
                        oL = true
                    end
                end
                local rL = not oL and UK.inventory:get_item_by_uuid(aL.u._equipped_relic)
                if rL then
                    table.insert(jL, {
                        it = rL,
                        w = Strategy.relicWorth(aL.u,
                        rL) * cL * 100
                    })
                end
            end
            table.insert(ZK, {
                e = aL,
                share = cL,
                opts = jL
            })
        end
    end
    local sL, tL = {
    }, - 1
    local uL, vL, wL = {
    }, {
    }, {
    }
    local function xL(yL, zL)
        if yL > # ZK then
            if zL > tL then
                tL = zL
                sL = table.clone(uL)
            end
            return
        end
        local AL = ZK [yL]
        uL [AL.e.uuid] = nil
        xL(yL + 1, zL)
        for BL, CL in ipairs(AL.opts) do
            local DL = (Core.Items [CL.it.item_id] or {
            }).unique_equip
            if not vL [CL.it.uuid] and not (DL and wL [CL.it.item_id]) then
                vL [CL.it.uuid] = true
                if DL then
                    wL [CL.it.item_id] = true
                end
                uL [AL.e.uuid] = CL.it.uuid
                xL(yL + 1, zL + CL.w + (CL.it.uuid == AL.e.u._equipped_relic and 0.01 or 0))
                uL [AL.e.uuid] = nil
                vL [CL.it.uuid] = nil
                if DL then
                    wL [CL.it.item_id] = nil
                end
            end
        end
    end
    xL(1, 0)
    local EL, FL = 0, {
    }
    for GL, HL in ipairs(ZK) do
        local IL = HL.e.u._equipped_relic and UK.inventory:get_item_by_uuid(HL.e.u._equipped_relic)
        local JL = IL and Strategy.relicWorth(HL.e.u, IL) * HL.share * 100 or 0
        EL = EL + JL
        local KL = sL [HL.e.uuid] and UK.inventory:get_item_by_uuid(sL [HL.e.uuid])
        local LL = KL and Strategy.relicWorth(HL.e.u, KL) * HL.share * 100 or 0
        table.insert(FL, string.format("%s: %s (%+.1f%%) → %s (%+.1f%%)", Units.name(HL.e.id), IL and (Core.Items [IL.item_id] or {
        }).name or "none", JL, KL and (Core.Items [KL.item_id] or {
        }).name or "none", LL))
    end
    return sL, tL - EL, FL, ZK
end

function Strategy.relicsApply(ML)
    if not (Config.team and Config.teamRelics) or Config.strDry then
        return false
    end
    local NL = Modes.teamSig()
    if not ML and Brain.str.relicSig == NL and os.time() - (tonumber(Brain.str.relicAt) or 0) < 600 then
        return false
    end
    if App.req.back.relicMove and Utils.now() < App.req.back.relicMove then
        return false
    end
    Brain.str.relicSig, Brain.str.relicAt = NL, os.time()
    local OL, PL, QL, RL = Strategy.relicPlan()
    if not OL then
        return false
    end
    Brain.str.relicNote = string.format("relics now on the best spread for this team (a change would add %.1f%%)", math.max(0, PL))
    if PL < Strategy.relicBar() then
        Brain.str.relicTeam = NL
        return false
    end
    local SL = Core.session()
    local TL = SL.profile_data.collection.owned_units
    local function UL(VL)
        for WL, XL in pairs(TL) do
            if XL._equipped_relic == VL then
                return WL, XL
            end
        end
    end
    local function YL(ZL)
        return App.gameSaid(ZL) or "no answer"
    end
    local function _L(aM)
        local bM, cM = UL(aM)
        if not bM then
            return true
        end
        local dM = Utils.now()
        App.request("relicMove", "request_unequip_relic", aM)
        while Utils.now() - dM < 4 and cM._equipped_relic == aM do
            task.wait(0.25)
        end
        task.wait(1.2)
        if cM._equipped_relic == aM then
            App.log(1, "POWER", string.format("%s's %s wouldn't come off (%s): relics stay as they are for now", Units.name(cM.unit_id), tostring(Units.relicName(cM)), YL(dM)))
            App.backoff("relicMove", 300)
            return false
        end
        return true
    end
    App.log(1, "POWER", string.format("moving relics for +%.1f%% team damage: %s", PL, table.concat(QL, " · ")))
    for eM, fM in ipairs(RL) do
        local gM = fM.e.u._equipped_relic
        if gM and gM ~= OL [fM.e.uuid] and not _L(gM) then
            return false
        end
    end
    for hM, iM in pairs(OL) do
        local jM = UL(iM)
        if jM and jM ~= hM and not _L(iM) then
            return false
        end
    end
    table.sort(RL, function(kM, lM)
        return kM.share > lM.share
    end)
    local mM = 0
    for nM, oM in ipairs(RL) do
        local pM = OL [oM.e.uuid]
        if pM and oM.e.u._equipped_relic ~= pM then
            local qM, rM = 0, nil
            local sM = {
            }
            for tM, uM in ipairs(Units.equipped()) do
                sM [uM.uuid] = true
            end
            for vM, wM in pairs(TL) do
                if wM._equipped_relic then
                    qM = qM + 1
                    if not sM [vM] and (not rM or not table.find(Brain.str.core or {
                    }, vM)) then
                        rM = wM._equipped_relic
                    end
                end
            end
            if qM >= Strategy.MAX_RELICS and rM and not _L(rM) then
                return false
            end
            local xM = Utils.now()
            App.request("relicMove", "use_unique_item", pM, {
                unit_uuid = oM.e.uuid
            })
            while Utils.now() - xM < 4 and oM.e.u._equipped_relic ~= pM do
                task.wait(0.25)
            end
            task.wait(1.2)
            if oM.e.u._equipped_relic ~= pM then
                App.log(1, "POWER", string.format("the game didn't put %s on %s (%s): trying again in 5 min", (Core.Items [(SL.inventory:get_item_by_uuid(pM) or {
                }).item_id] or {
                }).name or "that relic", Units.name(oM.e.id), YL(xM)))
                App.backoff("relicMove", 300)
                Brain.str.relicAt = 0
                return false
            end
            mM = mM + 1
        end
    end
    Modes._sigAt = nil
    Brain.str.relicSig = Modes.teamSig()
    Brain.str.relicTeam = Brain.str.relicSig
    Brain.str.relicNote = string.format("relics moved for +%.1f%% team damage", PL)
    Strategy.note(string.format("moved %d relics for +%.1f%% team damage", mM, PL))
    return true
end

function Strategy.foodHeld()
    local yM = Core.session()
    local zM = {
    }
    local AM = yM and yM.inventory and yM.inventory.inventory_profile_data or {
    }
    for BM, CM in pairs(AM.normal_items or {
    }) do
        local DM = Core.Items [BM]
        if type(DM) == "table" and type(DM.usage) == "table" and DM.usage.type == "xp_feed" and (tonumber(CM) or 0) > 0 then
            table.insert(zM, {
                id = BM,
                n = tonumber(CM),
                xp = tonumber(DM.usage.xp_amount) or 0
            })
        end
    end
    table.sort(zM, function(EM, FM)
        return EM.xp > FM.xp
    end)
    return zM
end

function Strategy.xpRoom()
    local GM, HM = Core.session(), 0
    for IM, JM in ipairs(GM and Strategy.core() or {
    }) do
        local KM = GM.collection:get_unit_by_uuid(JM)
        if KM then
            HM = HM + math.max(0, Strategy.xpFor(KM.unit_id, Strategy.cap(KM)) - (tonumber(KM.xp) or 0))
        end
    end
    return HM
end

function Strategy.plan()
    local LM = Core.session()
    if not LM then
        return {
        }
    end
    local MM = {
    }
    local NM = Strategy.core()
    local OM = Strategy.foodHeld()
    local PM = 0
    for QM, RM in ipairs(OM) do
        PM = PM + RM.n * RM.xp
    end
    local SM = Config.autoFuse and Config.fuseUnit ~= "" and Config.fuseUnit or nil
    local TM = (Brain.fuseInfo and tonumber(Brain.fuseInfo.requirement)) or (Brain.lb and tonumber(Brain.lb.requirement)) or 12
    local UM = Adventure.have("divine_wish")
    for VM, WM in ipairs(NM) do
        local XM = LM.collection:get_unit_by_uuid(WM)
        if XM then
            local YM, ZM = XM.unit_id, Units.name(XM.unit_id)
            local _M = Strategy.role(YM)
            if Config.teamXp and PM > 0 then
                local aN, bN = Strategy.gainXp(XM, PM)
                local cN, dN = Strategy.gainXp(XM, 500000)
                local eN = dN > 0 and cN / dN * bN or 0
                if bN > 0 and eN > 0 then
                    table.insert(MM, {
                        kind = "feed",
                        uuid = WM,
                        name = ZM,
                        gain = eN,
                        add = bN,
                        text = string.format("feed %s %s XP: level %d → %d (+%.1f%% team damage)",
                        ZM,
                        Utils.fmt(bN),
                        Strategy.level(XM),
                        Strategy.level({
                            unit_id = YM,
                            xp = (tonumber(XM.xp) or 0) + bN
                        }),
                        eN)
                    })
                end
            end
            local fN = Brain.str.fuseNo and tonumber(Brain.str.fuseNo [WM])
            if Config.teamFuse and Strategy.lb(XM) == 0 and _M ~= "farm" and WM ~= SM and not (fN and os.time() - fN < 86400) then
                local gN = Strategy.gainFuse(XM)
                local hN = Strategy.xpFor(YM, Strategy.cap(XM)) <= (tonumber(XM.xp) or 0)
                local iN, jN, kN = pcall(FarmHub.fuseFuel, XM, TM)
                kN = iN and kN or 0
                local lN = (not hN and "not at its level cap yet") or (UM < 1 and "no Divine Wish (the Daily Challenge pays one)") or (kN < TM and string.format("spare units it may use are worth %d of %d points", math.floor(kN), math.floor(TM))) or nil
                table.insert(MM, {
                    kind = "fuse",
                    uuid = WM,
                    name = ZM,
                    gain = gN,
                    blocked = lN,
                    text = string.format("limit break %s (+%.1f%% team damage once it reaches level 110)",
                    ZM,
                    gN)
                })
            end
        end
    end
    table.sort(MM, function(mN, nN)
        if mN.gain ~= nN.gain then
            return mN.gain > nN.gain
        end
        return mN.text < nN.text
    end)
    for oN in pairs(Units._mult) do
        if type(oN) == "string" and oN:sub(1, 5) == "what:" then
            Units._mult [oN] = nil
        end
    end
    Brain.str.acts, Brain.str.actsAt = {
    }, os.time()
    for pN = 1, math.min(12, # MM) do
        local qN = MM [pN]
        table.insert(Brain.str.acts, {
            kind = qN.kind,
            uuid = qN.uuid,
            name = qN.name,
            gain = qN.gain,
            text = qN.text,
            blocked = qN.blocked
        })
    end
    return MM
end

function Strategy.itemWorth(rN)
    if not (Brain.str.acts and os.time() - (tonumber(Brain.str.actsAt) or 0) < 900) then
        return nil
    end
    local sN = {
    }
    for tN, uN in ipairs(Brain.str.acts) do
        if uN.gain and (not sN [uN.kind] or uN.gain > sN [uN.kind]) then
            sN [uN.kind] = uN.gain
        end
    end
    local vN = Config.strengthValue or 300
    if rN == "divine_wish" then
        return sN.fuse and math.max(Core.ITEM_VALUE.divine_wish or 400, sN.fuse * vN) or nil
    end
    return nil
end

function Strategy.xpRate()
    local wN = Core.session()
    if not wN then
        return 0
    end
    local xN = 0
    for yN, zN in ipairs(Strategy.core()) do
        local AN = wN.collection:get_unit_by_uuid(zN)
        if AN then
            local BN, CN = Strategy.gainXp(AN, 500000)
            if CN > 0 then
                xN = math.max(xN, BN / CN)
            end
        end
    end
    local DN = xN * (Config.strengthValue or 300)
    if (tonumber(Core.cur("gold")) or 0) > (Config.xpGoldFloor or 100000) then
        DN = math.min(DN, (Core.GOLD_VALUE or 0.02) / 14)
    end
    return DN
end

function Strategy.xpGuess(EN)
    local FN = EN.level and Core.Levels [EN.level]
    if not FN then
        return 0
    end
    local GN = math.min(9, tonumber(FN.story_world_rank) or tonumber(EN.rank) or 9)
    local HN = tonumber(FN.story_level_rank) or 6
    local IN = (EN.kind == "raid" and 1.5 or 1) * (GN > 5 and 2 or 1)
    local JN = 2.1564 ^ (GN - 1) * (40 + 10 * HN) / IN
    if EN.kind == "infinite" then
        JN = 3 * 30 * 2.1564 ^ (GN - 1) / IN
    end
    local KN = GN >= 9 and 0.3 or (GN >= 7 and 0.5 or 1)
    return JN * KN * 6
end

function Strategy.modeBonus(LN)
    if not (Config.team and Config.teamXp) or LN.kind == "dungeon" or LN.kind == "event" then
        return 0
    end
    local MN = Strategy._xpRate and os.time() - (Strategy._xpRateAt or 0) < 300 and Strategy._xpRate or nil
    if not MN then
        MN = Strategy.xpRate()
        Strategy._xpRate, Strategy._xpRateAt = MN, os.time()
    end
    if MN <= 0 then
        return 0
    end
    local NN = Brain.modes and Brain.modes [LN.key]
    local ON = tonumber(NN and NN.xp) or Strategy.xpGuess(LN)
    local PN = ON * MN
    if PN < 1 then
        return 0
    end
    return PN, string.format("≈%s XP for your team (≈%d gems)", Utils.fmt(ON), math.floor(PN + 0.5))
end

function Strategy.xpSettle()
    local QN = Brain.lastRun
    if not (QN and type(QN.xp0) == "table" and QN.key) then
        return
    end
    local RN = Core.session()
    if not RN then
        return
    end
    local SN, TN = 0, 0
    for UN, VN in pairs(QN.xp0) do
        local WN = RN.collection:get_unit_by_uuid(UN)
        if WN then
            SN = SN + math.max(0, (tonumber(WN.xp) or 0) - (tonumber(VN) or 0))
            TN = TN + 1
        end
    end
    Brain.lastRun = nil
    if TN == 0 then
        return
    end
    local XN = Modes.rec(QN.key)
    XN.xp = XN.xp and (XN.xp + (SN - XN.xp) * 0.3) or SN
    if SN > 0 then
        App.log(2, Strategy.LOG, string.format("%s paid your units %s XP", QN.key, Utils.fmt(SN)))
    end
    App.saveSoon()
end

function Strategy.note(YN)
    App.log(1, Strategy.LOG, YN)
    table.insert(Brain.str.log, 1, {
        at = os.time(),
        msg = YN
    })
    while # Brain.str.log > 20 do
        table.remove(Brain.str.log)
    end
    App.saveSoon()
end

function Strategy.run(ZN)
    local _N = Core.session()
    local aO = _N and _N.collection:get_unit_by_uuid(ZN.uuid)
    if not aO then
        return
    end
    if ZN.kind == "feed" then
        local bO = Units.trait(aO)
        local cO = bO == "neuroplasticity" and 1.5 or 1
        local dO = math.max(0, Strategy.xpFor(aO.unit_id, Strategy.cap(aO)) - (tonumber(aO.xp) or 0))
        local eO, fO, gO = {
        }, 0, 0
        for hO, iO in ipairs(Strategy.foodHeld()) do
            local jO = iO.xp * cO
            local kO = math.min(iO.n, math.floor((dO - fO) / math.max(1, jO)))
            if kO > 0 then
                eO [iO.id] = kO
                fO = fO + kO * jO
                gO = gO + kO
            end
        end
        if gO == 0 then
            Brain.str.feedNote = ZN.name .. ": no food small enough for the XP it has left"
            return
        end
        local lO, mO = tonumber(aO.xp) or 0, Strategy.level(aO)
        local nO, oO = App.request("feed", "level_up_feed", ZN.uuid, eO)
        local pO = Utils.now()
        while Utils.now() - pO < 4 and (tonumber((_N.collection:get_unit_by_uuid(ZN.uuid) or aO).xp) or 0) <= lO do
            task.wait(0.25)
        end
        local qO = _N.collection:get_unit_by_uuid(ZN.uuid) or aO
        local rO = (tonumber(qO.xp) or 0) - lO
        if rO > 0 then
            Spending.add(string.format("%d XP food on %s", gO, ZN.name), gO, "items", string.format("Units → Upgrades: +%s XP, level %d → %d", Utils.fmt(rO), mO, Strategy.level(qO)))
            Strategy.note(string.format("fed %s %d items: +%s XP, level %d → %d%s", ZN.name, gO, Utils.fmt(rO), mO, Strategy.level(qO), math.abs(rO - fO) > fO * 0.1 and string.format(" (planned %s)", Utils.fmt(fO)) or ""))
        else
            Strategy.note(string.format("the game didn't take the food for %s (%s): trying again in 10 min", ZN.name, tostring(nO and oO or "no answer")))
            App.backoff("feed", 600)
        end
    elseif ZN.kind == "fuse" then
        FarmHub.fuseInto(ZN.uuid, false)
    end
end

function Strategy.slotOf(sO)
    local tO = Core.session()
    for uO, vO in pairs(tO and tO.profile_data.collection.equipped_units or {
    }) do
        if vO == sO then
            return tonumber(uO) or uO
        end
    end
    return nil
end

function Strategy.reequip()
    local wO = Brain.str.reequip
    if not wO then
        return true
    end
    local xO = Core.session()
    local yO = xO and xO.collection:get_unit_by_uuid(wO.uuid)
    if not yO then
        Brain.str.reequip = nil
        return true
    end
    for zO = 1, 3 do
        if Strategy.slotOf(wO.uuid) then
            break
        end
        App.request("eq", "equip_unit", wO.uuid)
        local AO = Utils.now()
        while Utils.now() - AO < 3 and not Strategy.slotOf(wO.uuid) do
            task.wait(0.25)
        end
    end
    Modes._sigAt = nil
    if Strategy.slotOf(wO.uuid) then
        Brain.str.reequip = nil
        App.saveSoon()
        return true
    end
    App.log(1, "TEAM", string.format("%s didn't go back into slot %s: trying again", Units.name(yO.unit_id), tostring(wO.slot)))
    return false
end
Strategy.REMOTE = {
    feed = "feed",
    fuse = "fuse"
}
Strategy.WORK_MAX = 300

function Strategy.nextAct(BO)
    local CO = os.time()
    for DO, EO in ipairs(BO or {
    }) do
        local FO = App.req.back [Strategy.REMOTE [EO.kind] or ""]
        if not EO.blocked and not (FO and Utils.now() < FO) and (tonumber(Brain.str.noWork [EO.kind]) or 0) <= CO and (tonumber(Brain.str.noWork [EO.kind .. ":" .. tostring(EO.uuid)]) or 0) <= CO then
            return EO
        end
    end
end

function Strategy.workSig()
    local GO = 0
    for HO, IO in ipairs(Strategy.foodHeld()) do
        GO = GO + IO.n
    end
    return table.concat({
        GO,
        Adventure.have("divine_wish")
    }, ",")
end
Strategy.FEED_STOP_GAIN = 0.5

function Strategy.focusReady()
    if not (Config.autoEvolve and Config.evolveUnit ~= "") then
        return nil
    end
    pcall(Adventure.refresh)
    for JO, KO in ipairs(Brain.goals or {
    }) do
        if KO.pinned and KO.uuid == Config.evolveUnit and KO.ready and (FarmHub.evoBlocked [KO.uuid] or 0) < os.time() then
            local LO = {
            }
            for MO, NO in ipairs(Units.equipped()) do
                LO [NO.uuid] = true
            end
            if not FarmHub.evoEats(KO, LO) then
                return KO
            end
        end
    end
end

function Strategy.hasWork(OO)
    if not OO then
        local PO = Strategy.focusReady()
        if PO then
            return "evolve " .. Units.name(PO.from) .. ", your focus", "evolve"
        end
        if FarmHub.snipeWanted() then
            return "pull " .. Units.name(Config.snipeUnit) .. " while it's featured (Banner Snipe)", "snipe"
        end
        if FarmHub.snipeDue() then
            return "look at the banners for " .. Units.name(Config.snipeUnit) .. ": they've turned over (Banner Snipe)", "snipe"
        end
        if Brain.ownSwap then
            return "put " .. Units.name(Brain.ownSwap.into) .. " on your team", "ownSwap"
        end
    end
    if not Config.team or Config.strDry then
        return nil
    end
    Strategy.acts = Strategy.plan()
    FarmHub.last.teamPlan = Utils.now()
    local QO = Strategy.acts
    if not OO then
        QO = {
        }
        for RO, SO in ipairs(Strategy.acts) do
            if not (SO.kind == "feed" and (tonumber(SO.gain) or 0) < Strategy.FEED_STOP_GAIN) then
                table.insert(QO, SO)
            end
        end
    end
    local TO = Strategy.nextAct(QO)
    if TO then
        return TO.text, TO.kind
    end
    if Config.teamRelics and (tonumber(Brain.str.noWork.relic) or 0) <= os.time() and (not OO or not (Config.autoTeam and Config.play)) then
        local UO, VO = Strategy.relicPlan()
        if VO and VO >= (OO and Strategy.relicBar() or Strategy.RELIC_SETTLED_GAIN) then
            return string.format("move relics for +%.1f%% team damage", VO), "relic"
        end
    end
    if not OO and Config.teamXp and Config.teamBuyXp and Config.goldShop and os.time() - (tonumber(Brain.str.shopAt) or 0) > 21600 and Strategy.xpRoom() > 0 and (tonumber(Core.cur("gold")) or 0) > (Config.xpGoldFloor or 100000) then
        return "look for XP food in the gold shop", "shop"
    end
    return nil
end

function Strategy.finishWork()
    local WO = Utils.now()
    local XO = 0
    while App.alive and Config.master and not Brain.holdLobby and Utils.now() - WO < Strategy.WORK_MAX do
        local YO, ZO = Strategy.hasWork(true)
        if not YO then
            break
        end
        App.status("Mode", "Units → Upgrades first: " .. tostring(YO))
        if ZO == "relic" then
            local _O, aP = pcall(Strategy.relicsApply, true)
            if not (_O and aP) then
                Brain.str.noWork.relic = os.time() + 1800
            end
        else
            Strategy.tick()
        end
        XO = XO + 1
        task.wait(4)
    end
    if XO > 0 then
        App.log(1, Strategy.LOG, string.format("Units → Upgrades finished for now: %d actions in %ds", XO, math.floor(Utils.now() - WO)))
        Modes._sigAt, Modes.lastScored = nil, nil
        App.saveSoon()
    end
end

function Strategy.tick()
    if not Config.team then
        Brain.str.next = "Off."
        return
    end
    if Brain.str.reequip then
        Strategy.reequip()
    end
    local bP
    if FarmHub.every("teamPlan", 60) or not Brain.str.acts then
        bP = Strategy.plan()
    else
        bP = Strategy.acts
    end
    Strategy.acts = bP or Strategy.acts or {
    }
    local cP = Strategy.nextAct(Strategy.acts)
    if not cP then
        local dP = Strategy.acts [1]
        Brain.str.next = dP and (dP.text .. " — waiting: " .. tostring(dP.blocked)) or "Nothing to do: every core unit is as strong as what you have allows."
        return
    end
    if Config.strDry then
        Brain.str.next = "Would " .. cP.text .. ". Dry Run is on: nothing is spent."
        if Brain.str.dryLast ~= cP.text then
            Brain.str.dryLast = cP.text
            App.log(1, Strategy.LOG, "dry run: would " .. cP.text)
        end
        return
    end
    Brain.str.next = cP.text
    local eP = Strategy.workSig()
    local fP, gP = pcall(Strategy.run, cP)
    if not fP then
        App.log(1, "ERROR", "team: " .. tostring(gP))
    end
    local hP = cP.kind == "fuse" and os.time() - (tonumber(Config.fuseArmAt) or 0) < 45
    if Strategy.workSig() == eP and not hP then
        Brain.str.noWork [cP.kind .. ":" .. tostring(cP.uuid)] = os.time() + 1800
    end
    local iP = App.req.back [Strategy.REMOTE [cP.kind] or ""]
    if iP and iP > Utils.now() then
        Brain.str.noWork [cP.kind] = os.time() + math.ceil(iP - Utils.now())
    end
    FarmHub.last.teamPlan = nil
end

function Strategy.rows()
    local jP = Core.session()
    local kP = {
    }
    if not jP then
        return kP
    end
    for lP, mP in ipairs(Brain.str.core or {
    }) do
        local nP = jP.collection:get_unit_by_uuid(mP)
        if nP then
            local oP, pP = Units.trait(nP)
            local qP = {
                string.format("level %d/%d",
                Strategy.level(nP),
                Strategy.cap(nP)),
                Strategy.traitName(oP,
                pP)
            }
            if nP.trait_stats then
                table.insert(qP, (FarmHub.statRanks(nP):gsub(" · ", " / ")))
            end
            table.insert(qP, Units.relicName(nP) and ("relic: " .. Units.relicName(nP)) or "no relic")
            if Strategy.lb(nP) >= 1 then
                table.insert(qP, "limit broken ✓")
            end
            local rP
            for sP, tP in ipairs(Brain.str.acts or {
            }) do
                if tP.uuid == mP then
                    rP = tP
                    break
                end
            end
            if rP then
                table.insert(qP, "next: " .. (rP.text:gsub("^%l", string.upper)) .. (rP.blocked and (" (waiting: " .. rP.blocked .. ")") or ""))
            end
            table.insert(kP, {
                name = Units.name(nP.unit_id),
                text = table.concat(qP,
                " · ")
            })
        end
    end
    return kP
end

function Strategy.text()
    if not Config.team then
        return "Off. Switch it on and the farm makes your core units stronger with what you already have."
    end
    local uP = {
        Brain.str.next or "Working it out in the lobby…"
    }
    if Brain.str.fuseNote then
        table.insert(uP, "Limit break: " .. Brain.str.fuseNote)
    end
    if Brain.str.relicNote then
        table.insert(uP, "Relics: " .. Brain.str.relicNote)
    end
    for vP = 1, math.min(4, # (Brain.str.log or {
    })) do
        table.insert(uP, os.date("%H:%M", Brain.str.log [vP].at) .. " " .. Brain.str.log [vP].msg)
    end
    return table.concat(uP, "\n")
end
FarmHub.last = {
}
FarmHub.hatched = {
}

function FarmHub.evolve(wP, xP)
    local yP = Core.session()
    local zP = yP.collection:get_unit_by_uuid(wP.uuid)
    if not zP then
        return false, "unit not found"
    end
    local AP, BP = 0, {
    }
    for CP, DP in pairs(yP.profile_data.collection.owned_units) do
        if DP.unit_id == wP.to then
            AP = AP + 1
            BP [CP] = true
        end
    end
    local FP, GP = App.request("evolve", "evolve_unit", wP.uuid)
    task.wait(2)
    local HP = yP.collection:get_unit_by_uuid(wP.uuid)
    local IP = 0
    for JP, KP in pairs(yP.profile_data.collection.owned_units) do
        if KP.unit_id == wP.to then
            IP = IP + 1
            if not BP [JP] then
                if Config.fuseXpUnit == wP.uuid then
                    Config.fuseXpUnit, Config.fuseXpId = JP, wP.to
                    App.saveSoon()
                end
                if Config.fuseUnit == wP.uuid then
                    Config.fuseUnit = JP
                    App.saveSoon()
                end
            end
        end
    end
    if IP > AP then
        local LP = {
        }
        for MP, NP in ipairs(wP.items or {
        }) do
            table.insert(LP, string.format("%s ×%d", (Core.Items [NP.id] or {
            }).name or NP.id, NP.amount))
        end
        for OP, PP in ipairs(wP.eats or {
        }) do
            table.insert(LP, string.format("%d× %s", PP.amount, Units.name(PP.id)))
        end
        local QP = string.format("%s → %s (score %s → %s)", Units.name(wP.from), Units.name(wP.to), Utils.fmt(wP.scoreFrom or 0), Utils.fmt(wP.scoreTo or 0))
        Spending.add("evolved " .. QP, 1, "evolution", (xP or "your choice") .. (# LP > 0 and (" · used " .. table.concat(LP, ", ")) or ""))
        App.log(1, "EVOLVE", QP .. " — " .. (xP or "your choice") .. (# LP > 0 and (" · used " .. table.concat(LP, ", ")) or ""))
        Modes._sigAt = nil
        pcall(Adventure.refresh)
        return true, Units.name(wP.to) .. " is yours!"
    end
    App.log(1, "EVOLVE", "evolve refused for " .. Units.name(wP.from) .. " (" .. tostring(GP) .. "), unit now " .. tostring(HP and HP.unit_id))
    return false, "the game said no (" .. tostring(GP) .. ")"
end
FarmHub.evoBlocked = {
}

function FarmHub.evoEats(RP, SP)
    local TP = Core.session()
    local UP, VP = pcall(Units.score, TP.collection:get_unit_by_uuid(RP.uuid))
    for WP, XP in ipairs(RP.eats or {
    }) do
        for YP, ZP in ipairs(Adventure.copies(XP.id, XP.shiny, RP.uuid)) do
            local _P = TP.collection:get_unit_by_uuid(ZP.uuid) or ZP
            local aQ, bQ = pcall(Units.score, _P)
            if SP [ZP.uuid] or Units.trait(_P) or (UP and aQ and bQ >= VP) then
                return string.format("would use up a %s you may want (on your team, a trait, or stronger) — lock it in the game to keep it", Units.name(XP.id))
            end
        end
    end
end
FarmHub.pickNote = {
}

function FarmHub.pickDone(cQ, dQ, eQ, fQ)
    Config [cQ] = false
    pcall(function()
        GUI.UI [cQ].Set(false, true)
    end)
    FarmHub.pickNote [cQ] = eQ
    App.log(1, "LOBBY", dQ .. ": " .. eQ)
    if App.notify then
        App.notify(dQ, eQ, fQ or "success")
    end
    App.saveSoon()
end

function FarmHub.focusNextUp()
    if Config.focusNext == "" or GUI.focusNow() ~= "" then
        return
    end
    local gQ = Config.focusNext
    local hQ = Core.session()
    local iQ, jQ
    for kQ, lQ in pairs(hQ.profile_data.collection.owned_units) do
        if lQ.unit_id == gQ and (not iQ or (tonumber(lQ.xp) or 0) > jQ) then
            iQ, jQ = kQ, tonumber(lQ.xp) or 0
        end
    end
    if not iQ then
        Config.focusNext = ""
        App.log(1, "LOBBY", "Focus: next up was " .. Units.name(gQ) .. ", and you don't have one any more")
        return App.saveSoon()
    end
    Config.focusDone = Config.evolveUnit
    App.log(1, "LOBBY", "Focus: next up is " .. Units.name(gQ))
    FarmHub.setFocus(iQ)
    GUI.focusSig = nil
    if App.notify then
        App.notify("Focus", "now focusing on " .. Units.name(gQ), "success")
    end
end

function FarmHub.autoEvolve()
    if not Config.autoEvolve or Config.evolveUnit == "" then
        return
    end
    local mQ = Core.session()
    if not (mQ and mQ.collection:get_unit_by_uuid(Config.evolveUnit)) then
        return FarmHub.pickDone("autoEvolve", "Focus", "that unit is gone", "warning")
    end
    local nQ
    for oQ, pQ in ipairs(Brain.goals or {
    }) do
        if pQ.pinned and pQ.uuid == Config.evolveUnit then
            nQ = pQ
            break
        end
    end
    if not nQ then
        local qQ = mQ.collection:get_unit_by_uuid(Config.evolveUnit)
        local rQ = Core.Units [qQ.unit_id]
        if not (rQ and rQ.evolve and rQ.evolve.evolve_unit) then
            FarmHub.pickDone("autoEvolve", "Focus", Units.name(qQ.unit_id) .. " has no evolution left", "warning")
        end
        return
    end
    FarmHub.pickNote.autoEvolve = nil
    if not nQ.ready then
        return
    end
    local sQ = {
    }
    for tQ, uQ in ipairs(Units.equipped()) do
        sQ [uQ.uuid] = true
    end
    local vQ = FarmHub.evoEats(nQ, sQ)
    if vQ then
        FarmHub.pickNote.autoEvolve = vQ
        return
    end
    if (FarmHub.evoBlocked [nQ.uuid] or 0) >= os.time() then
        return
    end
    local wQ, xQ = FarmHub.evolve(nQ, "your focus (Units → Goals)")
    if wQ then
        FarmHub.pickDone("autoEvolve", "Focus", xQ)
    else
        FarmHub.evoBlocked [nQ.uuid] = os.time() + 3600
        FarmHub.pickNote.autoEvolve = xQ
    end
end

function FarmHub.evolveText()
    if Config.evolveUnit == "" then
        return "Pick a unit. The farm goes after the items and takedowns it needs, and evolves it once it's ready (evolving can't be undone)."
    end
    local yQ = FarmHub.pickNote.autoEvolve and ("\n" .. FarmHub.pickNote.autoEvolve) or ""
    if not Config.autoEvolve then
        return "Switch it on to start." .. yQ
    end
    for zQ, AQ in ipairs(Brain.goals or {
    }) do
        if AQ.pinned and AQ.uuid == Config.evolveUnit then
            return AQ.text .. ((Modes.onlyOn() and not AQ.ready) and ("\nOnly " .. Modes.onlyText() .. " is on (Farm → Stages), so it can only farm there.") or "") .. yQ
        end
    end
    return "Works out what it needs in the lobby…" .. yQ
end

function FarmHub.fuseFuel(BQ, CQ)
    local DQ = Core.session()
    local EQ = {
        [BQ.uuid] = true,
        [Config.evolveUnit] = true,
        [Config.fuseXpUnit] = true
    }
    local FQ = {
    }
    for GQ, HQ in ipairs(Units.equipped()) do
        EQ [HQ.uuid] = true
    end
    for IQ, JQ in ipairs(Brain.savedTeam or {
    }) do
        EQ [JQ] = true
    end
    for KQ, LQ in ipairs(Brain.train and Brain.train.on and Brain.train.on.base or {
    }) do
        EQ [LQ] = true
    end
    for MQ, NQ in ipairs(Brain.goals or {
    }) do
        EQ [NQ.uuid] = true
        for OQ, PQ in ipairs(NQ.eats or {
        }) do
            FQ [PQ.id] = true
        end
    end
    for QQ, RQ in ipairs(Brain.str and Brain.str.core or {
    }) do
        EQ [RQ] = true
    end
    local SQ = Adventure.strongest(10)
    local TQ, UQ = {
    }, 0
    for VQ, WQ in pairs(DQ.profile_data.collection.owned_units) do
        local XQ = DQ.collection:get_unit_by_uuid(VQ) or WQ
        local YQ, ZQ, _Q = pcall(Core.USC.is_unit_good_for_fusion, BQ, XQ)
        if YQ and ZQ and not (WQ._locked or XQ._locked) and not EQ [VQ] and not FQ [XQ.unit_id] and not (WQ._equipped_relic or XQ._equipped_relic) and not (WQ.shiny or XQ.shiny) and not Units.trait(XQ) and not (WQ.further_modifiers and WQ.further_modifiers.limit_break) then
            local aR = Adventure.fodderOrder(XQ.unit_id)
            if aR and not SQ [VQ] then
                local bR, cR = pcall(Units.score, XQ)
                table.insert(TQ, {
                    uuid = VQ,
                    id = XQ.unit_id,
                    pts = tonumber(_Q) or 1,
                    sc = bR and cR or 0,
                    order = aR
                })
                UQ = UQ + (tonumber(_Q) or 1)
            end
        end
    end
    table.sort(TQ, function(dR, eR)
        if dR.order ~= eR.order then
            return dR.order < eR.order
        end
        if dR.sc ~= eR.sc then
            return dR.sc < eR.sc
        end
        return dR.uuid < eR.uuid
    end)
    local fR, gR = {
    }, 0
    for hR, iR in ipairs(TQ) do
        if gR >= CQ then
            break
        end
        table.insert(fR, iR)
        gR = gR + iR.pts
    end
    return fR, gR, UQ
end

function FarmHub.fodderRows(jR)
    local kR = Core.session()
    if not (kR and jR) then
        return {
        }
    end
    local lR, mR, nR, oR = {
    }, {
    }, {
    }, {
    }
    for pR, qR in ipairs(Units.equipped()) do
        lR [qR.uuid] = true
    end
    for rR, sR in ipairs(Brain.str and Brain.str.core or {
    }) do
        mR [sR] = true
    end
    for tR, uR in ipairs(Brain.goals or {
    }) do
        nR [uR.uuid] = true
        for vR, wR in ipairs(uR.eats or {
        }) do
            oR [wR.id] = true
        end
    end
    local xR = {
    }
    local yR, zR = pcall(FarmHub.fuseFuel, jR, math.huge)
    for AR, BR in ipairs(yR and zR or {
    }) do
        xR [BR.uuid] = true
    end
    local CR = {
    }
    for DR, ER in pairs(kR.profile_data.collection.owned_units) do
        if DR ~= jR.uuid and not lR [DR] and not ER._locked then
            local FR = kR.collection:get_unit_by_uuid(DR) or ER
            local GR, HR, IR = pcall(Core.USC.is_unit_good_for_fusion, jR, FR)
            if GR and HR and not FR._locked then
                local JR = Core.Units [FR.unit_id] or {
                }
                local KR = {
                }
                local LR, MR = Units.trait(FR)
                if LR then
                    table.insert(KR, "trait " .. tostring((Core.traitInfo(LR) or {
                    }).name or LR) .. (MR and MR ~= "1" and (" " .. MR) or ""))
                end
                if FR._equipped_relic or ER._equipped_relic then
                    table.insert(KR, "relic " .. tostring(Units.relicName(FR) or ""))
                end
                if FR.shiny or ER.shiny then
                    table.insert(KR, "shiny")
                end
                if FR.further_modifiers and FR.further_modifiers.limit_break then
                    table.insert(KR, "limit broken")
                end
                if mR [DR] then
                    table.insert(KR, "a core unit")
                end
                if nR [DR] or oR [FR.unit_id] then
                    table.insert(KR, "part of a goal")
                end
                local NR, OR = pcall(Units.score, FR)
                table.insert(CR, {
                    uuid = DR,
                    id = FR.unit_id,
                    name = Units.name(FR.unit_id),
                    rarity = JR.rarity or "?",
                    lvl = Strategy.level(FR),
                    pts = tonumber(IR) or 1,
                    evolved = Units.isEvolvedForm(FR.unit_id),
                    flags = KR,
                    safe = xR [DR] or false,
                    sc = NR and OR or 0
                })
            end
        end
    end
    table.sort(CR, function(PR, QR)
        if PR.safe ~= QR.safe then
            return PR.safe
        end
        if PR.sc ~= QR.sc then
            return PR.sc < QR.sc
        end
        return PR.uuid < QR.uuid
    end)
    return CR
end

function FarmHub.fodderPicked(RR)
    local SR = Core.session()
    local TR, UR, VR = {
    }, 0, 0
    local WR = {
    }
    for XR, YR in ipairs(Units.equipped()) do
        WR [YR.uuid] = true
    end
    for ZR, _R in ipairs(Config.fuseFodder or {
    }) do
        local aS = SR and SR.collection:get_unit_by_uuid(_R)
        local bS, cS, dS = false, false, 0
        if aS and RR and _R ~= RR.uuid and not aS._locked and not WR [_R] then
            bS, cS, dS = pcall(Core.USC.is_unit_good_for_fusion, RR, aS)
        end
        if bS and cS then
            table.insert(TR, {
                uuid = _R,
                id = aS.unit_id,
                pts = tonumber(dS) or 1
            })
            UR = UR + (tonumber(dS) or 1)
        else
            VR = VR + 1
        end
    end
    return TR, UR, VR
end

function FarmHub.fuseText()
    if Config.fuseUnit == "" then
        return "Pick a unit. Fusing limit breaks it (level cap 100 → 110), and destroys the units it uses."
    end
    local eS = Core.session()
    local fS = eS and eS.collection:get_unit_by_uuid(Config.fuseUnit)
    if not fS then
        return "That unit is gone."
    end
    local gS = (Brain.fuseInfo and Brain.fuseInfo.uuid == fS.uuid) and tonumber(Brain.fuseInfo.requirement) or 12
    local hS
    if # (Config.fuseFodder or {
    }) > 0 then
        local iS, jS, kS = FarmHub.fodderPicked(fS)
        local lS = {
        }
        for mS, nS in ipairs(iS) do
            table.insert(lS, Units.name(nS.id))
        end
        hS = string.format("Your picks: %d units worth %d of %d points%s.", # iS, jS, gS, kS > 0 and string.format(" (%d of them can't be used any more)", kS) or "")
        if jS >= gS then
            hS = hS .. "\nIt would destroy: " .. table.concat(lS, ", ") .. "."
        end
    else
        local oS, pS, qS = FarmHub.fuseFuel(fS, gS)
        local rS = {
        }
        for sS, tS in ipairs(oS) do
            table.insert(rS, Units.name(tS.id))
        end
        hS = string.format("No picks yet, so the farm chooses: units it may use are worth %d of %d points.", qS, gS)
        if pS >= gS then
            hS = hS .. "\nIt would destroy: " .. table.concat(rS, ", ") .. "."
        else
            hS = hS .. "\nIt only takes units that are unlocked, off your team, not part of a goal, with no trait, relic or shine, and that the guides don't rate S or better. Tick units below to choose yourself."
        end
    end
    return hS .. (FarmHub.pickNote.autoFuse and ("\n" .. FarmHub.pickNote.autoFuse) or "")
end

function FarmHub.autoFuse()
    if not Config.autoFuse or Config.fuseUnit == "" then
        return
    end
    FarmHub.fuseInto(Config.fuseUnit, true)
end
FarmHub.FUSE_RANK = {
    Rare = 1,
    Epic = 2,
    Legendary = 3
}

function FarmHub.xpFodder(uS)
    local vS = Core.session()
    local wS = FarmHub.FUSE_RANK [Config.fuseXpRarity] or 2
    local xS = {
        [uS.uuid] = true,
        [Config.evolveUnit] = true,
        [Config.fuseUnit] = true
    }
    for yS, zS in ipairs(Units.equipped()) do
        xS [zS.uuid] = true
    end
    for AS, BS in ipairs(Brain.savedTeam or {
    }) do
        xS [BS] = true
    end
    for CS, DS in ipairs(Brain.train and Brain.train.on and Brain.train.on.base or {
    }) do
        xS [DS] = true
    end
    local ES, FS = {
    }, 0
    for HS, IS in pairs(vS.profile_data.collection.owned_units) do
        local JS = Core.Units [IS.unit_id]
        local KS = JS and FarmHub.FUSE_RANK [JS.rarity]
        if KS and KS <= wS and not xS [HS] then
            local LS = vS.collection:get_unit_by_uuid(HS) or IS
            if not (IS._locked or LS._locked) and not (IS._equipped_relic or LS._equipped_relic) then
                local MS, NS = pcall(Core.USC.calculate_xp_gain_from_fuse, uS, {
                    LS
                }, vS)
                NS = MS and tonumber(NS) or 0
                if NS > 0 then
                    table.insert(ES, {
                        uuid = HS,
                        id = IS.unit_id,
                        xp = NS,
                        rarity = JS.rarity
                    })
                    FS = FS + NS
                end
            end
        end
    end
    table.sort(ES, function(OS, PS)
        if OS.xp ~= PS.xp then
            return OS.xp < PS.xp
        end
        return OS.uuid < PS.uuid
    end)
    local QS = math.max(0, Strategy.xpFor(uS.unit_id, Strategy.cap(uS)) - (tonumber(uS.xp) or 0))
    local RS, TS = {
    }, 0
    for US, VS in ipairs(ES) do
        if TS >= QS then
            break
        end
        table.insert(RS, VS)
        TS = TS + VS.xp
    end
    return RS, TS, QS, FS
end

function FarmHub.fuseXpTarget(WS)
    local XS = WS and WS.collection:get_unit_by_uuid(Config.fuseXpUnit)
    if XS then
        if Config.fuseXpId ~= XS.unit_id then
            Config.fuseXpId = XS.unit_id
            App.saveSoon()
        end
        return XS
    end
    local YS = WS and Core.Units [Config.fuseXpId]
    local ZS = YS and YS.evolve and YS.evolve.evolve_unit
    local _S, aT
    for bT, cT in pairs(ZS and WS.profile_data.collection.owned_units or {
    }) do
        if cT.unit_id == ZS and (not _S or (tonumber(cT.xp) or 0) > aT) then
            _S, aT = bT, tonumber(cT.xp) or 0
        end
    end
    if not _S then
        return nil
    end
    App.log(1, "LOBBY", string.format("Fuse For XP: %s evolved, it now feeds %s", Units.name(Config.fuseXpId), Units.name(ZS)))
    Config.fuseXpUnit, Config.fuseXpId = _S, ZS
    App.saveSoon()
    return WS.collection:get_unit_by_uuid(_S)
end

function FarmHub.fuseXpText()
    if Config.fuseXpUnit == "" then
        return "Pick a unit. It gets the XP of the spare units fused into it, and those units are destroyed."
    end
    local dT = Core.session()
    local eT = FarmHub.fuseXpTarget(dT)
    if not eT then
        return "That unit is gone, so nothing is fused. Pick another: your switch stays as you set it."
    end
    local fT, gT, hT = FarmHub.xpFodder(eT)
    local iT = {
    }
    for jT, kT in ipairs(fT) do
        iT [kT.rarity] = (iT [kT.rarity] or 0) + 1
    end
    local lT = {
    }
    for mT, nT in ipairs({
        "Rare",
        "Epic",
        "Legendary"
    }) do
        if iT [nT] then
            table.insert(lT, iT [nT] .. " " .. nT)
        end
    end
    local oT, pT = Strategy.level(eT), Strategy.cap(eT)
    local qT
    if hT <= 0 then
        qT = string.format("%s: level %d/%d, at its level cap.", Units.name(eT.unit_id), oT, pT)
    elseif # fT == 0 then
        qT = string.format("%s: level %d/%d. No spare units to fuse yet.", Units.name(eT.unit_id), oT, pT)
    else
        qT = string.format("%s: level %d/%d. It would destroy %s, for %s XP (level %d).", Units.name(eT.unit_id), oT, pT, table.concat(lT, ", "), Utils.fmt(gT), Strategy.level({
            unit_id = eT.unit_id,
            xp = (tonumber(eT.xp) or 0) + math.min(gT,
            hT)
        }))
    end
    qT = qT .. "\nEvery unit up to " .. tostring(Config.fuseXpRarity) .. " that isn't locked, shiny and traited ones too, except your team and picks and units wearing a relic. Lock a unit in the game to keep it out."
    return qT .. (FarmHub.pickNote.autoFuseXp and ("\n" .. FarmHub.pickNote.autoFuseXp) or "")
end

function FarmHub.autoFuseXp()
    if not Config.autoFuseXp or Config.fuseXpUnit == "" then
        return
    end
    local rT = Core.session()
    local sT = FarmHub.fuseXpTarget(rT)
    if not sT then
        return
    end
    local tT = Units.name(sT.unit_id)
    local uT, vT, wT = FarmHub.xpFodder(sT)
    if wT <= 0 then
        FarmHub.pickNote.autoFuseXp = nil
        return
    end
    if # uT == 0 then
        FarmHub.pickNote.autoFuseXp = "Waiting: no spare units to fuse."
        return
    end
    if os.time() - (tonumber(Config.fuseXpOnAt) or 0) < 30 then
        FarmHub.pickNote.autoFuseXp = "Fusing in a moment: switch it off to cancel."
        return
    end
    FarmHub.pickNote.autoFuseXp = nil
    if App.req.back.fuseXp and Utils.now() < App.req.back.fuseXp then
        return
    end
    FarmHub.fuseBatch = FarmHub.fuseBatch or 50
    local xT, yT, zT = 0, 0, {
    }
    while App.alive and xT < 10 do
        if xT > 0 then
            local AT, BT, CT = FarmHub.xpFodder(rT.collection:get_unit_by_uuid(Config.fuseXpUnit) or sT)
            uT, wT = {
            }, CT
            for ET, FT in ipairs(AT) do
                if not zT [FT.uuid] then
                    table.insert(uT, FT)
                end
            end
            if wT <= 0 or # uT == 0 then
                break
            end
        end
        local GT = {
        }
        for HT = 1, math.min(FarmHub.fuseBatch, # uT) do
            table.insert(GT, uT [HT].uuid)
        end
        local IT = tonumber((rT.collection:get_unit_by_uuid(Config.fuseXpUnit) or sT).xp) or 0
        local JT = Utils.now()
        local KT, LT = App.request("fuseXp", "feed_units", Config.fuseXpUnit, GT)
        if not KT and (LT == "slowing down" or LT == "waiting") then
            if LT == "waiting" or yT >= 3 then
                break
            end
            yT = yT + 1
            task.wait(3.5)
            continue
        end
        while Utils.now() - JT < 5 and (tonumber((rT.collection:get_unit_by_uuid(Config.fuseXpUnit) or sT).xp) or 0) <= IT do
            task.wait(0.1)
        end
        local NT = tonumber((rT.collection:get_unit_by_uuid(Config.fuseXpUnit) or sT).xp) or 0
        if NT > IT then
            xT = xT + 1
            for OT, PT in ipairs(GT) do
                zT [PT] = true
            end
            Spending.add(string.format("%d units fused into %s", # GT, tT), # GT, "units", string.format("Fuse For XP: your pick (Units → Fusion): +%s XP", Utils.fmt(NT - IT)))
            App.log(1, "LOBBY", string.format("Fuse For XP: %d units into %s, +%s XP, level %d", # GT, tT, Utils.fmt(NT - IT), Strategy.level(rT.collection:get_unit_by_uuid(Config.fuseXpUnit) or sT)))
        elseif # GT > 20 then
            FarmHub.fuseBatch = 20
            App.log(1, "LOBBY", string.format("Fuse For XP: the game didn't take %d at once (%s): 20 a batch", # GT, tostring(App.gameSaid(JT) or (KT and LT) or "no answer")))
        else
            local QT = App.gameSaid(JT)
            FarmHub.pickNote.autoFuseXp = "The game said no (" .. tostring(QT or (KT and LT) or "no answer") .. "): trying again in 30 min."
            App.log(1, "LOBBY", "Fuse For XP refused: " .. tostring(QT or (KT and LT) or "no answer"))
            App.backoff("fuseXp", 1800)
            break
        end
    end
end

function FarmHub.fuseInto(RT, TT)
    local UT = Core.session()
    local VT = UT and UT.collection:get_unit_by_uuid(RT)
    local function WT(XT, YT)
        if TT then
            FarmHub.pickDone("autoFuse", "Auto Fuse", XT, YT)
        else
            Brain.str.fuseNote = XT
            App.log(1, Strategy.LOG, "limit break: " .. XT)
        end
    end
    local function ZT(_T)
        if TT then
            FarmHub.pickNote.autoFuse = _T
        else
            Brain.str.fuseNote = _T
        end
    end
    if not VT then
        return WT("that unit is gone", "warning")
    end
    local aU = Units.name(VT.unit_id)
    local function bU(cU)
        return cU.further_modifiers and cU.further_modifiers.limit_break and tonumber(cU.further_modifiers.limit_break.current_limit_break) or 0
    end
    if bU(VT) >= (tonumber(Core.USC.get_max_limit_break(VT)) or 1) then
        return WT(aU .. " is already limit broken")
    end
    local dU, eU = App.request("fuseInfo", "request_fusion_information", RT)
    if not (dU and type(eU) == "table") then
        return
    end
    Brain.fuseInfo = {
        requirement = eU.requirement,
        divine_wish = eU.divine_wish,
        allowed = eU.allowed,
        uuid = RT
    }
    if not eU.allowed then
        if not TT then
            Brain.str.fuseNo = Brain.str.fuseNo or {
            }
            Brain.str.fuseNo [RT] = os.time()
            FarmHub.last.teamPlan = nil
        end
        return WT("the game says " .. aU .. " can't be limit broken", "warning")
    end
    ZT(nil)
    if Core.USC.calculate_xp(VT.unit_id, Core.USC.get_max_level(VT)) > (tonumber(VT.xp) or 0) then
        return ZT("Waiting: " .. aU .. " has to reach its level cap first.")
    end
    local fU = tonumber(eU.divine_wish) or 1
    if Adventure.have("divine_wish") < fU then
        return ZT("Waiting: it needs a Divine Wish.")
    end
    local gU = tonumber(eU.requirement) or 12
    local hU = TT and # (Config.fuseFodder or {
    }) > 0
    local iU, jU
    if hU then
        local kU
        kU, jU = FarmHub.fodderPicked(VT)
        if jU < gU then
            return ZT(string.format("Waiting: the units you ticked are worth %d of %d points. Tick more on the Units → Fusion.", math.floor(jU), math.floor(gU)))
        end
        iU, jU = {
        }, 0
        for lU, mU in ipairs(kU) do
            if jU >= gU then
                break
            end
            table.insert(iU, mU)
            jU = jU + mU.pts
        end
    else
        iU, jU = FarmHub.fuseFuel(VT, gU)
        if jU < gU then
            return ZT(string.format("Waiting: spare units it may use are worth %d of %d points.", math.floor(jU), math.floor(gU)))
        end
    end
    local nU, oU = {
    }, {
    }
    for pU, qU in ipairs(iU) do
        table.insert(nU, qU.uuid)
        table.insert(oU, Units.name(qU.id))
    end
    local rU = RT .. "|" .. table.concat(nU, ",")
    if Config.fuseArmSig ~= rU then
        Config.fuseArmSig, Config.fuseArmAt = rU, os.time()
        App.saveSoon()
        App.log(1, TT and "LOBBY" or Strategy.LOG, string.format("%s: %s will use %s (switch it off to cancel)", TT and "Auto Fuse" or "Limit break", aU, table.concat(oU, ", ")))
    end
    if os.time() - Config.fuseArmAt < 30 then
        return ZT("Fusing " .. aU .. " in a moment: switch it off to cancel. It uses " .. table.concat(oU, ", ") .. ".")
    end
    local sU = bU(VT)
    local tU, uU = App.request("fuse", "fusion_units", RT, nU)
    local vU = Utils.now()
    while Utils.now() - vU < 5 and bU(UT.collection:get_unit_by_uuid(RT) or VT) <= sU do
        task.wait(0.25)
    end
    Config.fuseArmSig, Config.fuseArmAt = "", 0
    if bU(UT.collection:get_unit_by_uuid(RT) or VT) > sU then
        Spending.add("limit broke " .. aU, # nU, "units", (TT and ("Auto Limit Break: your pick (Units → Fusion)" .. (hU and ", your fodder" or "")) or "Units → Upgrades") .. " · used " .. table.concat(oU, ", ") .. " and a Divine Wish")
        if hU then
            local wU = {
            }
            for xU, yU in ipairs(Config.fuseFodder or {
            }) do
                if not table.find(nU, yU) then
                    table.insert(wU, yU)
                end
            end
            Config.fuseFodder = wU
            App.saveSoon()
        end
        WT(aU .. " is limit broken!")
        Modes._sigAt = nil
    else
        WT("the game said no to limit breaking " .. aU .. " (" .. tostring(tU and uU or "no answer") .. ")", "error")
    end
end
