    },
    {
        id = "range_stat",
        name = "Range"
    }
}

function FarmHub.statRank(zU, AU)
    local BU = Core.core("TraitServiceCore").calculate_stat_rank(zU.unit_id, zU.trait_stats, AU, zU.trait_stats [AU])
    return BU, table.find(FarmHub.GRADES, BU) or 0
end

function FarmHub.statRanks(CU)
    local DU = {
    }
    for EU, FU in ipairs(FarmHub.STATS) do
        table.insert(DU, FU.name .. " " .. (FarmHub.statRank(CU, FU.id)))
    end
    return table.concat(DU, " · ")
end
FarmHub.BANNER_NAME = {
    EventClover = "Newest Units",
    Legacy = "Legacy Units",
    April2025 = "April (limited)",
    SakamotoEvent = "Assassin (limited)",
    Summer2026 = "Summer (Sunny Stars)"
}

function FarmHub.bannerCost(GU)
    local HU = Core.Banners [GU]
    if not HU then
        return nil
    end
    if HU.item_cost then
        local IU = HU.item_cost.item_id
        return {
            cost = tonumber(HU.item_cost.amount) or 10,
            have = function()
                return Adventure.have(IU)
            end,
            name = (Core.Items [IU] or {
            }).name or IU,
            floor = "tokenFloor"
        }
    end
    local JU = HU.resource_cost
    if JU and JU.id == "SummerPearls" then
        return {
            cost = tonumber(JU.amount) or 150,
            have = function()
                return Core.cur("SummerPearls")
            end,
            name = "Summer Pearls",
            floor = "pearlFloor"
        }
    end
    if JU and JU.id then
        return {
            cost = tonumber(JU.amount) or 50,
            have = function()
                return Core.cur(JU.id)
            end,
            name = JU.id == "GemsLegacy" and "Legacy Gems" or JU.id,
            floor = JU.id == "AprilCoins" and "aprilFloor" or "tokenFloor"
        }
    end
    return {
        cost = tonumber(HU.gem_cost) or 50,
        have = function()
            return Core.cur("gems")
        end,
        name = "gems",
        floor = "gemFloor"
    }
end

function FarmHub.quietFx(KU)
    local MU = Config.skipSummonFx and not KU
    local NU = Core.svc("SummonFX")
    if NU and type(NU.open_star_new) == "function" then
        if rawget(NU, "__aaOrig") == nil then
            rawset(NU, "__aaOrig", NU.open_star_new)
        end
        NU.open_star_new = MU and function(OU, PU, QU, RU, SU)
            if type(SU) == "function" then
                task.defer(SU)
            end
        end or rawget(NU, "__aaOrig")
    end
    local TU = Core.GUIS and Core.GUIS.drop_obtained_ui
    if type(TU) == "table" then
        for UU, VU in ipairs({
            "show_message",
            "show_message_custom"
        }) do
            rawset(TU, VU, MU and function()
            end or nil)
        end
    end
end

function FarmHub.summonText()
    local WU = Config.summonBanner ~= "" and FarmHub.bannerCost(Config.summonBanner)
    if not WU then
        return "Pick a banner. It stops at the line below, or when your unit storage is full."
    end
    return string.format("You have %s %s. 10 summons cost %s, and it keeps %s.%s", Utils.fmt(WU.have()), WU.name, Utils.fmt(WU.cost * 10), Utils.fmt(Config [WU.floor]), Status.Summon and ("\n" .. tostring(Status.Summon)) or "")
end

function FarmHub.smartEvolve()
    if not Config.smartEvolve then
        return App.status("Evolve", "smart evolve is off (Units → Goals)")
    end
    local XU = Core.session()
    if not XU then
        return
    end
    local YU = {
    }
    for ZU, _U in ipairs(Brain.goals or {
    }) do
        table.insert(YU, _U)
    end
    table.sort(YU, function(aV, bV)
        return (aV.gain or 0) > (bV.gain or 0)
    end)
    local cV = {
    }
    for dV, eV in ipairs(Units.equipped()) do
        cV [eV.uuid] = true
    end
    local fV, gV, hV = {
    }, 0, {
    }
    for iV, jV in ipairs(YU) do
        if jV.pinned then
            for kV, lV in ipairs(jV.items or {
            }) do
                fV [lV.id] = (fV [lV.id] or 0) + lV.amount
            end
        end
    end
    for mV, nV in ipairs(YU) do
        local oV, pV
        if nV.ready and not nV.pinned and gV < 2 and (FarmHub.evoBlocked [nV.uuid] or 0) < os.time() then
            if nV.hidden and (nV.tierRank or 0) < Adventure.TIER_RANK.S then
                oV = "its strength is unknown (the game hides its upgrades until it's in a match), so this one is your call"
            end
            for qV, rV in ipairs(oV and {
            } or nV.items or {
            }) do
                if Adventure.have(rV.id) - rV.amount < (fV [rV.id] or 0) then
                    oV = string.format("keeps %s for a bigger evolution", (Core.Items [rV.id] or {
                    }).name or rV.id)
                    break
                end
            end
            oV = oV or FarmHub.evoEats(nV, cV)
            if not oV then
                local sV, tV = FarmHub.evolve(nV, "smart evolve: ready, stronger at full upgrade, uses only spare items" .. (# (nV.eats or {
                }) > 0 and " and spare copies" or ""))
                if sV then
                    gV, pV = gV + 1, true
                    table.insert(hV, "evolved " .. Units.name(nV.from) .. " → " .. Units.name(nV.to))
                else
                    FarmHub.evoBlocked [nV.uuid] = os.time() + 3600
                    oV = tV
                end
            end
            if oV then
                table.insert(hV, Units.name(nV.from) .. ": " .. oV)
            end
        end
        if not pV then
            for uV, vV in ipairs(nV.items or {
            }) do
                fV [vV.id] = (fV [vV.id] or 0) + vV.amount
            end
        end
    end
    App.status("Evolve", # hV > 0 and table.concat(hV, " · ") or "nothing ready to evolve")
end
Training.BONUS = 1.5
Training.SLOW = 1.4

function Training.boost(wV, xV, yV, zV)
    if xV < 2 or yV >= math.min(Config.dangerReach, (zV or 1) * 0.9) then
        return
    end
    local AV = yV < math.min(Config.safeReach, (zV or 1) * 0.75)
    local BV = 0
    for CV, DV in ipairs(wV) do
        if not DV.farm and not DV.train and DV.cost > 0 then
            BV = math.max(BV, DV.gain / DV.cost)
        end
    end
    for EV, FV in ipairs(wV) do
        if FV.train == "first" or (FV.train == "more" and AV) then
            FV.gain = math.max(FV.gain, BV * FV.cost * 1.05)
        end
    end
end
Training.HOLD_REACH = 0.3
Training.ZONE = 0.25

function Training.hold(GV, HV, IV)
    if HV < 2 or GV >= Training.HOLD_REACH + (IV and 0.1 or 0) then
        return false
    end
    return true, string.format("holding your other units back so enemies reach the trainee (they die at %d%% of the road)", math.floor(GV * 100 + 0.5))
end

function Training.same(JV, KV)
    if # JV ~= # KV then
        return false
    end
    local LV = {
    }
    for MV, NV in ipairs(JV) do
        LV [NV] = true
    end
    for OV, PV in ipairs(KV) do
        if not LV [PV] then
            return false
        end
    end
    return true
end

function Training.team()
    local QV = {
    }
    for RV, SV in ipairs(Units.equipped()) do
        table.insert(QV, SV.uuid)
    end
    return QV
end

function Training.target()
    local TV = Core.session()
    if not TV then
        return nil
    end
    local UV, VV
    local WV = Config.autoEvolve and Config.evolveUnit ~= "" and Config.evolveUnit or nil
    for XV, YV in ipairs(Brain.goals or {
    }) do
        local ZV, _V = nil, 0
        for aW, bW in ipairs(YV.plans or {
        }) do
            if bW.takedown then
                ZV = bW
            else
                _V = _V + 1
            end
        end
        local cW = ZV and YV.intoTeam and (YV.pinned or not YV.unknown) and (not WV or YV.uuid == WV) and TV.collection:get_unit_by_uuid(YV.uuid)
        if cW then
            local dW = tonumber(ZV.what == "kills" and cW.total_kills or cW.total_takedowns) or 0
            if dW < ZV.need then
                local eW = (_V == 0 and 1000 or 0) + (tonumber(YV.tierRank) or 0) * 10 - XV * 0.01
                if not UV or eW > VV then
                    UV, VV = {
                        uuid = YV.uuid,
                        id = YV.from,
                        to = YV.to,
                        what = ZV.what,
                        have = dW,
                        need = ZV.need
                    }, eW
                end
            end
        end
    end
    return UV
end

function Training.realHave(fW)
    local gW = Core.session()
    local hW = gW and gW.collection:get_unit_by_uuid(fW.uuid)
    local iW = hW and tonumber(fW.what == "kills" and hW.total_kills or hW.total_takedowns) or 0
    return math.max(iW, fW.have + (fW.got or 0))
end

function Training.now()
    if Training._at and Utils.now() - Training._at < 10 then
        return Training._t, Training._base
    end
    local jW = (Brain.train.on and Brain.train.on.base) or Training.team()
    local kW = table.clone(jW)
    table.sort(kW)
    Training._t, Training._base, Training._at = Training.target(), table.concat(kW, ","), Utils.now()
    return Training._t, Training._base
end

function Training.valueFor(lW)
    if not (Config.trainTakedowns and Config.goals) then
        return 0, 1
    end
    local mW = Brain.trainSim [lW.key]
    if not (mW and mW.ok and os.time() - (mW.at or 0) < 6 * 3600) then
        return 0, 1
    end
    local nW, oW = Training.now()
    local pW = {
    }
    for qW, rW in ipairs(Brain.savedTeam or {
    }) do
        pW [qW] = rW
    end
    table.sort(pW)
    if not (nW and mW.uuid == nW.uuid and (mW.base == oW or mW.base == table.concat(pW, ","))) or not Training.eligible(lW) then
        return 0, 1
    end
    local sW = Training.perRun(lW.key, nW.id) or 0
    local tW = math.max(1, nW.need - nW.have)
    return Config.goalValue * math.min(sW, tW) / tW, mW.slow or 1
end

function Training.scan()
    local uW = Config.trainTakedowns and Config.sim and Training.now()
    if not uW then
        return
    end
    local vW = (Brain.train.on and Brain.train.on.base) or Training.team()
    for wW, xW in ipairs(vW) do
        if xW == uW.uuid then
            return
        end
    end
    local yW, zW = 0, 0
    for AW, BW in ipairs(Modes.lastScored or {
    }) do
        if yW >= 3 or zW >= 2 then
            break
        end
        if Training.eligible(BW) then
            local CW = Brain.trainSim [BW.key]
            local DW = CW and CW.uuid == uW.uuid and os.time() - (CW.at or 0) < 6 * 3600
            local EW = Training.plan(BW, uW, vW)
            if not DW then
                zW = zW + 1
            end
            if EW.ok then
                yW = yW + 1
            end
        end
    end
    local FW = Training.bestInfinite()
    if FW then
        Training.plan(FW, uW, vW)
    end
end

function Training.bestInfinite()
    local GW, HW
    for IW, JW in ipairs(Modes.lastScored or {
    }) do
        if JW.kind == "infinite" and Training.eligible(JW) then
            local KW, LW = Brain.train.real [JW.key], JW.rec or Modes.rec(JW.key)
            local MW = (tonumber(LW.timed) or 0) > 0 and LW.sec / LW.timed / 60 or 0
            local NW = (KW and KW.n > 0 and MW > 0) and (KW.sum / KW.n) / MW or 0
            if NW <= 0 then
                NW = Reports.hiveTrainRate(JW.key) or 0
            end
            if NW > (HW or 0) then
                GW, HW = JW, NW
            end
        end
    end
    return GW
end

function Training.ratio()
    local OW = Brain.train.cal
    if not (OW and (OW.n or 0) > 0 and (OW.sim or 0) > 0) then
        return 1
    end
    return Utils.clamp(OW.real / OW.sim, 0.05, 2)
end

function Training.perRun(PW, QW)
    local RW = Brain.train.real [PW]
    if RW and RW.n > 0 then
        return RW.sum / RW.n, true
    end
    local SW = Reports.hiveTrain(PW, QW)
    if SW then
        return SW, true
    end
    local TW, UW = 0, 0
    local VW = Modes.isInf(PW)
    for WW, XW in pairs(Brain.train.real) do
        if Modes.isInf(WW) == VW then
            TW, UW = TW + XW.sum, UW + XW.n
        end
    end
    if UW > 0 then
        return TW / UW, true
    end
    local YW = Brain.trainSim [PW]
    return YW and YW.tk and YW.tk * Training.ratio() or nil, false
end

function Training.eligible(ZW)
    if ZW.kind == "daily" or ZW.kind == "challenge" then
        return false, "a limited reward, played with your own team"
    end
    if ZW.kind == "dungeon" then
        return false, "a lost dungeon room costs a life: played with your own team"
    end
    if Core.Levels [ZW.level] and Core.Levels [ZW.level]._randomequippedmode then
        return false, "this mode deals you a random team"
    end
    if (Brain.train.bad [ZW.key] or 0) > os.time() then
        return false, "a training run lost there, so not before " .. os.date("%H:%M", Brain.train.bad [ZW.key])
    end
    local _W = ZW.rec or Modes.rec(ZW.key)
    if _W.runs >= 3 and _W.wins / _W.runs < 0.8 then
        return false, "your farm wins it less than 80% of the time"
    end
    local aX = Brain.simRes [ZW.key]
    if aX and aX.trust and not aX.trust.ok then
        return false, "the simulator doesn't match real runs there yet"
    end
    return true
end

function Training.plan(bX, cX, dX)
    local eX = Core.session()
    local fX = table.clone(dX)
    table.sort(fX)
    local gX = table.concat(fX, ",")
    local hX = (tonumber((Brain.simCal [bX.key] or {
    }).n) or 0) > 0
    local iX = hX and 1.3 or 2
    local jX = gX .. "+" .. cX.uuid .. (hX and "#c" or "#n") .. "#r4"
    local kX = Brain.trainSim [bX.key]
    if kX and kX.sig == jX and not kX.pending and os.time() - (kX.at or 0) < 6 * 3600 then
        return kX
    end
    local lX = {
        sig = jX,
        base = gX,
        uuid = cX.uuid,
        at = os.time(),
        ok = false,
        margin = iX,
        pending = true
    }
    Brain.trainSim [bX.key] = lX
    local mX, nX = Simulator.levelFor(bX)
    if bX.ldOverride then
        mX = bX.ldOverride
    end
    if not mX then
        lX.why, lX.pending = "the simulator can't play this mode", nil
        return lX
    end
    local oX = Simulator.info(mX, bX.key, nX, bX.mod)
    local pX = {
    }
    for qX, rX in ipairs(dX) do
        local sX = eX.collection:get_unit_by_uuid(rX)
        if sX then
            table.insert(pX, sX)
        end
    end
    local tX = eX.collection:get_unit_by_uuid(cX.uuid)
    if not tX or # pX == 0 then
        lX.why, lX.pending = "the unit wasn't found", nil
        return lX
    end
    local uX = Simulator.run(oX, Simulator.teamFrom(pX, oX.map), {
        hpMul = 1
    })
    local vX = oX.infinite and Simulator.unbound(mX)
    local wX = vX and Modes.infTier(Simulator.run(oX, Simulator.teamFrom(pX, oX.map), {
        hpMul = iX
    }).wave) or nil
    local xX = {
    }
    for yX, zX in ipairs(pX) do
        if not Units.isFarm(zX.unit_id) then
            local AX, BX = pcall(Units.score, zX, bX.mod)
            table.insert(xX, {
                i = yX,
                sc = AX and BX or 0
            })
        end
    end
    table.sort(xX, function(CX, DX)
        return CX.sc < DX.sc
    end)
    local EX
    for FX = 1, math.min(3, # xX) do
        local GX = table.clone(pX)
        GX [xX [FX].i] = tX
        local HX = Simulator.teamFrom(GX, oX.map)
        local IX = Simulator.run(oX, HX, {
            hpMul = iX,
            train = cX.uuid
        })
        if (vX and Modes.infTier(IX.wave) >= wX) or (not vX and IX.won) then
            local JX = Simulator.run(oX, HX, {
                hpMul = 1,
                train = cX.uuid
            })
            local KX = (JX.tk or 0) / math.max(0.5, JX.t / 60)
            if (JX.won or vX) and (not EX or KX > math.max(EX.rate * 1.5, EX.rate + 1)) then
                EX = {
                    out = pX [xX [FX].i].unit_id,
                    r = JX,
                    rate = KX,
                    trial = GX
                }
            end
        end
    end
    lX.ownMin = uX.t / 60
    if not EX then
        lX.why = vX and string.format("every swap loses a daily milestone (wave %d) against %s enemies in the simulator", wX, hX and "30% tougher" or "twice as tough") or hX and "no swap still wins with 30% tougher enemies in the simulator" or "no swap still wins against twice as tough enemies in the simulator (no real run there yet)"
    else
        lX.out, lX.tk, lX.minutes = EX.out, EX.r.tk or 0, EX.r.t / 60
        lX.uuids = {
        }
        for LX, MX in ipairs(EX.trial) do
            table.insert(lX.uuids, MX.uuid)
        end
        lX.slow = (uX.won and not vX) and lX.minutes / math.max(0.1, lX.ownMin) or 1
        if lX.tk <= 0 and next(Brain.train.real) == nil then
            lX.why = "the simulator says it would hit nothing there"
        elseif lX.slow > Training.SLOW then
            lX.why = string.format("the clear would be %d%% slower", math.floor((lX.slow - 1) * 100 + 0.5))
        else
            lX.ok = true
        end
    end
    lX.pending = nil
    App.log(1, "TRAIN", string.format("%s: %s%s → %s", bX.label, Units.name(cX.id), lX.out and (" in for " .. Units.name(lX.out)) or "", lX.ok and string.format("trains here (≈%d %s a run, %.1f min vs %.1f with your team)", math.floor((Training.perRun(bX.key, cX.id) or 0) + 0.5), cX.what, lX.minutes, lX.ownMin) or tostring(lX.why)))
    App.saveSoon()
    return lX
end

function Training.home()
    local NX = Brain.train.on
    if not NX then
        return
    end
    Brain.train.on = nil
    App.saveSoon()
    if not Training.same(Training.team(), NX.uuids or {
    }) then
        App.log(1, "TRAIN", "your team was changed outside the farm, so it stays as it is")
        if not Config.autoTeam then
            Brain.savedTeam = nil
        end
        return
    end
    if Brain.savedTeam and Training.same(Brain.savedTeam, NX.base) then
        FarmHub.restoreTeam()
    else
        FarmHub.equipTeam(NX.base, "back from takedown training")
    end
    App.log(1, "TRAIN", Units.name(NX.out or "?") .. " is back in your team")
end

function Training.apply(OX)
    local PX = Brain.testTeam
    if PX and (PX.left or 0) > 0 and OX and PX.key == OX.key then
        Training.home()
        return App.status("Training", "paused for a team test")
    end
    local QX = Config.trainTakedowns and Training.target() or nil
    if not QX then
        Training.home()
        return App.status("Training", Config.trainTakedowns and "no evolution is waiting on takedowns" or "off (Units → Goals)")
    end
    local RX = Units.name(QX.id)
    local SX = string.format("%s %s/%s", QX.what, Utils.fmt(QX.have), Utils.fmt(QX.need))
    local TX = Brain.train.on
    local UX = TX and TX.base or Training.team()
    for VX, WX in ipairs(UX) do
        if WX == QX.uuid then
            return App.status("Training", string.format("%s is on your team (%s)", RX, SX))
        end
    end
    local XX, YX = Training.eligible(OX)
    local ZX
    if XX then
        App.status("Training", string.format("checking %s in %s with the simulator…", RX, OX.label))
        ZX = Training.plan(OX, QX, UX)
        XX, YX = ZX.ok, ZX.why
    end
    if not XX then
        Training.home()
        return App.status("Training", string.format("%s · %s · not in %s: %s", RX, SX, OX.label, tostring(YX)))
    end
    if not (TX and Training.same(Training.team(), ZX.uuids)) then
        FarmHub.equipTeam(ZX.uuids, string.format("takedown training: %s in for %s (%s)", RX, Units.name(ZX.out), OX.label))
        local _X = Utils.now()
        while Utils.now() - _X < 4 and not Training.same(Training.team(), ZX.uuids) do
            task.wait(0.25)
        end
        if not Training.same(Training.team(), ZX.uuids) then
            if Brain.savedTeam and Training.same(Brain.savedTeam, UX) then
                FarmHub.restoreTeam()
            else
                FarmHub.equipTeam(UX, "takedown training swap didn't work")
            end
            Brain.train.bad [OX.key] = os.time() + 3600
            App.log(1, "TRAIN", "the game didn't take the training team for " .. OX.label .. ": your own team is back")
            return App.status("Training", RX .. ": the swap didn't work, trying again in an hour")
        end
        Brain.train.on = {
            uuid = QX.uuid,
            id = QX.id,
            to = QX.to,
            what = QX.what,
            have = QX.have,
            need = QX.need,
            got = 0,
            base = UX,
            uuids = ZX.uuids,
            out = ZX.out,
            key = OX.key,
            at = os.time()
        }
        App.log(1, "TRAIN", string.format("%s in for %s for %s (%s)", RX, Units.name(ZX.out), OX.label, SX))
    end
    Brain.train.on.key = OX.key
    local aY, bY = Training.perRun(OX.key, QX.id)
    App.status("Training", string.format("%s in for %s in %s · %s · ≈%d a run%s", RX, Units.name(ZX.out), OX.label, SX, math.floor((aY or 0) + 0.5), bY and "" or " (simulated)"))
end

function Training.text()
    if not Config.trainTakedowns then
        return "Off. A unit whose evolution needs takedowns only earns them while you keep it on your team."
    end
    local cY = Training.target()
    if not cY then
        return "No evolution that would join your team is waiting on takedowns."
    end
    local dY, eY = 0, 0
    for fY, gY in pairs(Brain.train.real) do
        dY = dY + gY.sum
        eY = eY + gY.n
    end
    local hY = eY > 0 and dY / eY or nil
    local iY = {
    }
    for jY, kY in ipairs(Brain.train.log) do
        if # iY < 5 then
            table.insert(iY, string.format("+%d (%s, %s)", kY.got, GUI.keyName and GUI.keyName(kY.key) or kY.key, kY.won and "won" or "lost"))
        end
    end
    return string.format("%s needs %s %s for %s and has %s.%s%s\n" .. "It joins your team only where the simulator says you still win with 30%% tougher enemies (twice as tough where the farm has no real run yet), in place of your weakest unit that passes that test (a stronger one of your 3 weakest only if it trains 1.5× faster). " .. "Never in the challenges, where your farm wins under 80%% of runs, or where clearing gets more than 40%% slower. " .. "Its progress counts in the mode ranking (Goal Value, spread over the takedowns it still needs). " .. "Your own team goes back after every run, and a lost run stops training in that mode for 6 hours.", Units.name(cY.id), Utils.fmt(cY.need), cY.what, Units.name(cY.to), Utils.fmt(cY.have), hY and string.format(" It gets about %d a run, so ≈%d more runs.", math.floor(hY + 0.5), math.ceil((cY.need - cY.have) / math.max(1, hY))) or "", # iY > 0 and (" Last runs: " .. table.concat(iY, " · ") .. ".") or "")
end

function FarmHub.every(lY, mY)
    local nY = Utils.now()
    if FarmHub.last [lY] and nY - FarmHub.last [lY] < mY then
        return false
    end
    FarmHub.last [lY] = nY
    return true
end

function FarmHub.refreshLive()
    local oY = Brain.live
    local pY, qY = App.request("live_n", "get_normal_challenge")
    if pY and type(qY) == "table" and qY.current_uuid then
        local rY = (oY.normal and oY.normal.uuid == qY.current_uuid) and oY.normal.lost or 0
        local sY = (oY.normal and oY.normal.uuid == qY.current_uuid) and oY.normal.doneUuid or nil
        local tY = Core.GS.CHALLENGE_DURATION or 1800
        local uY = (math.floor(os.time() / tY) + 1) * tY
        oY.normal = {
            uuid = qY.current_uuid,
            level = qY.current_level_id,
            challenge = qY.current_challenge,
            value = Modes.rewardValue(qY.current_reward),
            expires = uY,
            lost = rY,
            doneUuid = sY
        }
    end
    local vY, wY = App.request("live_d", "get_daily_challenge")
    if vY and type(wY) == "table" and wY.current_uuid then
        local xY = type(wY.current_level) == "table" and wY.current_level or {
        }
        local yY = Modes.dailyMod(xY._challenge_uuid or wY.current_uuid, xY._daily_challenge_weak_against or wY.weak_against, xY._daily_challenge_strong_against or wY.strong_against)
        local zY = (oY.daily and oY.daily.uuid == wY.current_uuid) and oY.daily.lost or 0
        local AY = (oY.daily and oY.daily.uuid == wY.current_uuid) and oY.daily.doneUuid or nil
        local BY = type(wY.current_level) == "table" and Simulator.slim(wY.current_level) or nil
        if BY then
            BY._challenge = wY.current_challenge
        end
        oY.daily = {
            uuid = wY.current_uuid,
            value = Modes.rewardValue(wY.current_reward),
            challenge = wY.current_challenge,
            mod = yY,
            lost = zY,
            doneUuid = AY,
            ld = BY
        }
    end
    local CY, DY = App.request("live_e", "get_event_challenges")
    if CY and type(DY) == "table" then
        oY.event = nil
        for EY, FY in pairs(DY) do
            local GY = type(FY) == "table" and FY.current_level_data
            if type(GY) == "string" then
                GY = Core.Levels [GY]
            end
            if GY then
                local HY = Simulator.slim(GY)
                HY._difficulty = HY._difficulty or "Hard"
                oY.event = {
                    level = GY.id or EY,
                    name = GY.name,
                    pad = Core.GS.ACTIVE_EVENT_CHALLENGES and Core.GS.ACTIVE_EVENT_CHALLENGES [EY],
                    board = EY,
                    map = GY.map,
                    weather = FY.current_weather,
                    ld = HY,
                    forecast = type(FY.forecast) == "table" and {
                        map = FY.forecast.map,
                        weather = FY.forecast.weather,
                        map_hint = FY.forecast.map_hint,
                        weather_hint = FY.forecast.weather_hint
                    } or nil
                }
            end
        end
    end
    local IY, JY, KY = App.request("live_a", "get_current_artifacts")
    if IY and type(JY) == "table" and type(JY.world_ids) == "table" then
        local LY = {
        }
        for MY, NY in ipairs(JY.world_ids) do
            local OY = Core.Worlds [NY]
            local PY = OY and type(OY.levels) == "table" and (OY.levels ["1"] or OY.levels [1])
            if PY and Core.Levels [PY.id] then
                table.insert(LY, {
                    level = PY.id,
                    world = NY
                })
            end
        end
        oY.artifact = {
            list = LY,
            interval = JY.interval,
            ends = tonumber(JY.ends_at),
            ad = type(KY) == "table" and KY or (oY.artifact and oY.artifact.interval == JY.interval and oY.artifact.ad) or nil
        }
    end
    oY.at = os.time()
    App.saveSoon()
end

function FarmHub.rewards()
    if not Config.rewards then
        return App.status("Rewards", "off")
    end
    local QY = Core.session()
    local RY = Core.prof()
    if not (QY and RY) then
        return
    end
    local SY = {
    }
    if (os.time() - (tonumber(RY.last_daily_reward_claimed_time) or 0)) >= (Core.GS.DAILY_REWARD_WAIT or 82800) then
        local TY, UY = App.request("daily", "claim_daily_reward")
        if TY and UY then
            table.insert(SY, "daily login")
        end
    end
    for VY, WY in pairs(QY.quest_handler.quest_profile_data.quests or {
    }) do
        local XY, YY = pcall(Core.QCC.is_quest_complete, QY, WY)
        if XY and YY and not Brain.claims [VY] then
            local ZY, _Y = App.request("quest", "redeem_quest", VY)
            if ZY and _Y then
                Brain.claims [VY] = os.time()
                table.insert(SY, "quest " .. tostring(WY.quest_info and (WY.quest_info.name or WY.quest_info.id) or ""))
            else
                Brain.claims [VY] = os.time() - 259200 + 3600
            end
            task.wait(0.3)
        end
    end
    if FarmHub.every("bp", 600) then
        App.request("bp", "claim_battlepass_rewards")
    end
    if FarmHub.every("bingo", 120) then
        pcall(Hunt.claim)
    end
    if FarmHub.every("clr", 300) then
        for aZ, bZ in pairs(RY.level_data.completed_story_levels or {
        }) do
            local cZ = Core.Levels [aZ]
            if cZ and cZ.clear_rewards and bZ.difficulty_completed_data then
                for dZ, eZ in pairs(cZ.clear_rewards) do
                    local fZ = bZ.difficulty_completed_data [dZ] and bZ.difficulty_completed_data [dZ].times_completed or 0
                    for gZ, hZ in pairs(eZ) do
                        local iZ = RY.clear_rewards [aZ] and RY.clear_rewards [aZ] [dZ] and RY.clear_rewards [aZ] [dZ] [hZ._id]
                        local jZ = aZ .. dZ .. tostring(hZ._id)
                        if not iZ and fZ >= (hZ.clears or 1e9) and not Brain.claims [jZ] then
                            local kZ, lZ = App.request("clr", "claim_first_clear_rewards", aZ, dZ, hZ._id)
                            Brain.claims [jZ] = os.time()
                            if kZ and lZ then
                                table.insert(SY, "milestone " .. Modes.levelName(aZ))
                            end
                        end
                    end
                end
            end
        end
    end
    if FarmHub.every("clrA", 300) then
        for mZ, nZ in ipairs(Brain.live.artifact and Brain.live.artifact.list or {
        }) do
            local oZ = Core.Levels [nZ.level]
            local pZ, qZ, rZ, sZ = Modes.artifactLeft(nZ.level)
            for tZ, uZ in pairs(oZ and oZ.clear_rewards and oZ.clear_rewards.Hard or {
            }) do
                local vZ = "ar" .. nZ.level .. tostring(Brain.live.artifact.interval) .. tostring(uZ._id)
                if not sZ [uZ._id] and pZ >= (tonumber(uZ.clears) or 1e9) and not Brain.claims [vZ] then
                    local wZ, xZ = App.request("clr", "claim_first_clear_rewards", nZ.level, "Hard", uZ._id)
                    Brain.claims [vZ] = os.time()
                    if wZ and xZ then
                        table.insert(SY, "Artifact Stage " .. tostring(uZ._reward_text or uZ._id))
                    end
                end
            end
        end
    end
    for yZ, zZ in pairs(Brain.claims) do
        if os.time() - zZ > 259200 then
            Brain.claims [yZ] = nil
        end
    end
    if # SY > 0 then
        App.log(1, "REWARD", "claimed " .. table.concat(SY, ", "))
    end
    App.status("Rewards", # SY > 0 and ("claimed " .. table.concat(SY, ", ")) or "nothing waiting")
end

function FarmHub.goldShop()
    if not Config.goldShop then
        return App.status("Gold Shop", "off")
    end
    Brain.str.shopAt = os.time()
    local AZ = Core.prof()
    local BZ = Core.session()
    if not (AZ and BZ) then
        return
    end
    local CZ, DZ = App.request("gshop", "request_current_gold_shop")
    if not (CZ and type(DZ) == "table") then
        return App.status("Gold Shop", "shop not answering")
    end
    local EZ = 0
    local FZ = (type(AZ.gold_shop_data) == "table" and type(AZ.gold_shop_data.bought_items) == "table") and AZ.gold_shop_data.bought_items or {
    }
    local function GZ(HZ, IZ)
        if IZ.stock == "inf" then
            return math.huge
        end
        return math.max(0, (tonumber(IZ.stock) or 0) - (tonumber(FZ [HZ]) or 0))
    end
    for JZ, KZ in pairs(DZ) do
        if type(KZ) == "table" and tostring(KZ.id or JZ):find("^StarFruit") and GZ(JZ, KZ) > 0 then
            local LZ = Core.GS.ITEM_CAPS and Core.GS.ITEM_CAPS [KZ.id] or 1e9
            local MZ = 0
            pcall(function()
                MZ = BZ.inventory:get_number_of_owned_item(KZ.id)
            end)
            local NZ = tonumber(KZ.gold_cost) or 1e12
            local OZ = GZ(JZ, KZ)
            while OZ > 0 and MZ < LZ and (tonumber(AZ.gold_amount) or 0) - NZ >= Config.goldFloor and EZ < 10 do
                local PZ = tonumber(AZ.gold_amount) or 0
                local QZ = Utils.now()
                local RZ, SZ = App.request("gbuy", "buy_gold_shop_item", JZ, "1")
                local TZ = Utils.now()
                while Utils.now() - TZ < 3 and (tonumber(AZ.gold_amount) or 0) >= PZ do
                    task.wait(0.2)
                end
                if not RZ or (tonumber(AZ.gold_amount) or 0) >= PZ then
                    App.log(1, "SHOP", "gold shop refused " .. tostring(JZ) .. " (" .. tostring(App.gameSaid(QZ) or SZ) .. ")")
                    App.backoff("gbuy", 600)
                    break
                end
                EZ = EZ + 1
                OZ = OZ - 1
                MZ = MZ + 1
                Spending.add((Core.Items [KZ.id] and Core.Items [KZ.id].name or KZ.id), NZ, "gold", string.format("evolve material, %d/%d held · gold floor %s", MZ, LZ, Utils.fmt(Config.goldFloor)))
            end
        end
    end
    local UZ, VZ = 0, 0
    if Config.team and Config.teamXp and Config.teamBuyXp then
        local WZ, XZ
        pcall(function()
            WZ = Core.core("ProgressionServiceCore")
            XZ = Core.data("WorldLevelOrder")
        end)
        local function YZ(ZZ)
            local _Z = Core.LU and type(Core.LU.xp_items_order) == "table" and Core.LU.xp_items_order [ZZ]
            local a_ = _Z and XZ and type(XZ.WORLD_ORDER) == "table" and XZ.WORLD_ORDER [_Z]
            if not (a_ and WZ and WZ.check_if_unlocked_story_world) then
                return true
            end
            local b_, c_ = pcall(WZ.check_if_unlocked_story_world, Core.session(), a_)
            return b_ and c_ == true
        end
        local d_, e_ = {
        }, 0
        for f_, g_ in pairs(DZ) do
            local h_ = type(g_) == "table" and Core.Items [g_.id or f_]
            if h_ and type(h_.usage) == "table" and h_.usage.type == "xp_feed" and GZ(f_, g_) > 0 and tonumber(g_.gold_cost) and (tonumber(h_.usage.xp_amount) or 0) / math.max(1, tonumber(g_.gold_cost)) >= 3 then
                if YZ(g_.id or f_) then
                    table.insert(d_, {
                        key = f_,
                        id = g_.id or f_,
                        it = g_,
                        xp = tonumber(h_.usage.xp_amount) or 0,
                        cost = tonumber(g_.gold_cost)
                    })
                else
                    e_ = e_ + 1
                end
            end
        end
        table.sort(d_, function(i_, j_)
            return i_.xp / i_.cost > j_.xp / j_.cost
        end)
        local k_ = Strategy.xpRoom()
        for l_, m_ in ipairs(Strategy.foodHeld()) do
            k_ = k_ - m_.n * m_.xp
        end
        if Config.strDry then
            local n_, o_, p_ = {
            }, tonumber(AZ.gold_amount) or 0, 0
            for q_, r_ in ipairs(d_) do
                local s_ = math.min(GZ(r_.key, r_.it), math.floor(math.max(0, o_ - Config.xpGoldFloor) / r_.cost), r_.xp > 0 and math.floor(k_ / r_.xp) or 0)
                if s_ > 0 then
                    table.insert(n_, string.format("%d %s", s_, (Core.Items [r_.id] or {
                    }).name or r_.id))
                    o_, k_, p_ = o_ - s_ * r_.cost, k_ - s_ * r_.xp, p_ + s_
                end
            end
            local t_ = (p_ > 0 and string.format("dry run: would buy %s for %s gold", table.concat(n_, ", "), Utils.fmt((tonumber(AZ.gold_amount) or 0) - o_)) or "dry run: no XP food worth buying (your core units are full, or gold is at the line)") .. (e_ > 0 and string.format(" · %d kinds locked behind later worlds", e_) or "")
            if Brain.str.dryShop ~= t_ then
                Brain.str.dryShop = t_
                App.log(1, Strategy.LOG, t_)
            end
        else
            local u_
            local function v_()
                return tonumber(Core.cur("gold")) or tonumber(AZ.gold_amount) or 0
            end
            for w_, x_ in ipairs(d_) do
                if u_ then
                    break
                end
                local y_ = GZ(x_.key, x_.it)
                while y_ > 0 and k_ > 0 and x_.xp > 0 and v_() - x_.cost >= Config.xpGoldFloor and UZ < 80 do
                    local z_ = (y_ >= 10 and v_() - x_.cost * 10 >= Config.xpGoldFloor and k_ >= x_.xp * 10) and 10 or 1
                    local A_, B_ = v_(), Adventure.have(x_.id)
                    local C_ = Utils.now()
                    local D_, E_ = App.request("xpbuy", "buy_gold_shop_item", x_.key, tostring(z_))
                    if not D_ and (E_ == "slowing down" or E_ == "waiting") then
                        task.wait(3.5)
                        continue
                    end
                    local F_ = Utils.now()
                    while Utils.now() - F_ < 3 and v_() >= A_ and Adventure.have(x_.id) <= B_ do
                        task.wait(0.2)
                    end
                    if not D_ or (v_() >= A_ and Adventure.have(x_.id) <= B_) then
                        App.log(1, "SHOP", "gold shop refused " .. tostring(x_.key) .. " ×" .. z_ .. " (" .. tostring(App.gameSaid(C_) or E_) .. "): XP food waits for the next pass")
                        App.backoff("xpbuy", 600)
                        u_ = true
                        break
                    end
                    UZ, y_, k_, VZ = UZ + z_, y_ - z_, k_ - x_.xp * z_, VZ + x_.xp * z_
                    Spending.add((Core.Items [x_.id] or {
                    }).name or x_.id, x_.cost * z_, "gold", string.format("XP food for your team: %s XP · gold kept %s", Utils.fmt(x_.xp * z_), Utils.fmt(Config.xpGoldFloor)))
                end
            end
            if UZ > 0 then
                App.log(1, Strategy.LOG, string.format("bought %d XP food (%s XP) in the gold shop · gold %s", UZ, Utils.fmt(VZ), Utils.fmt(AZ.gold_amount)))
            end
        end
    end
    App.status("Gold Shop", (EZ > 0 or UZ > 0) and string.format("bought %d Star Fruit(s), %d XP food", EZ, UZ) or string.format("nothing to buy (gold %s, floor %s)", Utils.fmt(AZ.gold_amount), Utils.fmt(Config.goldFloor)))
end
FarmHub.SNIPE_KEEP = {
    gems = "snipeGemFloor",
    SummerPearls = "snipePearlFloor",
    GemsLegacy = "snipeLegacyFloor"
}
FarmHub.SNIPE_ALSO = {
    griffith = {
        "griffith_reincarnation"
    }
}

function FarmHub.snipeForms(G_)
    local H_, I_ = {
    }, {
    }
    while G_ and Core.Units [G_] and not I_ [G_] do
        I_ [G_] = true
        table.insert(H_, G_)
        local J_ = Core.Units [G_].evolve
        G_ = type(J_) == "table" and J_.evolve_unit or nil
    end
    for K_, L_ in ipairs(FarmHub.SNIPE_ALSO [H_ [1]] or {
    }) do
        table.insert(H_, L_)
    end
    return H_
end

function FarmHub.snipeHas(M_)
    M_ = M_ or Config.snipeUnit
    if not M_ or M_ == "" then
        return false
    end
    for N_, O_ in ipairs(FarmHub.snipeForms(M_)) do
        if FarmHub.hatched [O_] or Units.owns(O_) then
            return true
        end
    end
    return false
end

function FarmHub.snipeCost(P_)
    local Q_ = FarmHub.bannerCost(P_)
    local R_ = Core.Banners [P_]
    if not (Q_ and R_) then
        return nil
    end
    Q_.cur = (R_.item_cost and R_.item_cost.item_id) or (R_.resource_cost and R_.resource_cost.id) or "gems"
    Q_.keep = tonumber(Config [FarmHub.SNIPE_KEEP [Q_.cur] or Q_.floor]) or 0
    Q_.label = FarmHub.BANNER_NAME [P_] or P_
    return Q_
end

function FarmHub.watchRoom()
    local S_ = Core.prof()
    local T_ = 0
    for U_ in pairs(S_.collection.owned_units) do
        T_ = T_ + 1
    end
    return T_ + 20 <= (tonumber(S_.collection.capacity) or math.huge)
end

function FarmHub.snipeSay(V_, W_)
    Brain.snipe.note, Brain.snipe.noteAt = V_, os.time()
    App.log(1, "SUMMON", "Banner Snipe: " .. V_)
    if App.notify then
        App.notify("Banner Snipe", V_, W_ or "success")
    end
    App.saveSoon()
end

function FarmHub.snipeRate()
    local X_
    for Y_, Z_ in pairs(Core.Banners or {
    }) do
        if type(Z_) == "table" and Z_.active and not Z_._does_not_rotate and tonumber(Z_.HATCH_REFRESH_RATE) then
            X_ = math.min(X_ or math.huge, tonumber(Z_.HATCH_REFRESH_RATE))
        end
    end
    return X_ or 14400
end

function FarmHub.snipeTurnAfter(__)
    local a0 = FarmHub.snipeRate()
    local b0 = Brain.snipe.clock
    local c0 = (b0 and tonumber(b0.next) or 0) % a0
    return math.floor((__ - c0) / a0 + 1) * a0 + c0
end

function FarmHub.snipeStale()
    local d0 = Brain.snipe
    if not d0.lookAt then
        return true
    end
    return os.time() >= FarmHub.snipeTurnAfter(d0.lookAt) or (tonumber(d0.changedAt) or 0) > d0.lookAt
end

function FarmHub.snipeHeard(e0, ...)
    local f0 = Brain.snipe
    local g0 = table.pack(...)
    local function h0()
        local i0 = {
        }
        for j0 = 1, math.min(g0.n, 4) do
            local k0 = g0 [j0]
            if type(k0) == "table" then
                local l0 = {
                }
                for m0 in pairs(k0) do
                    if # l0 < 8 then
                        table.insert(l0, tostring(m0))
                    end
                end
                table.insert(i0, "{" .. table.concat(l0, ",") .. "}")
            else
                table.insert(i0, tostring(k0):sub(1, 40))
            end
        end
        return table.concat(i0, ", ")
    end
    if e0 == "hatch_refresh_remaining_time_changed" then
        if not f0.clockSeen then
            f0.clockSeen = true
            App.log(1, "SUMMON", "Banner Snipe: the game's hourly countdown says " .. h0())
        end
        return
    end
    f0.clock = {
        next = math.floor((os.time() + 30) / 60) * 60 + FarmHub.snipeRate(),
        at = os.time(),
        src = "changed"
    }
    local n0, o0 = {
    }, nil
    for q0 = 1, g0.n do
        if type(g0 [q0]) == "table" then
            for r0, s0 in pairs(g0 [q0]) do
                if type(s0) == "table" and Core.Banners [r0] then
                    if not o0 then
                        local t0 = {
                        }
                        for v0, w0 in pairs(s0) do
                            if # t0 < 10 then
                                table.insert(t0, tostring(v0) .. ":" .. type(w0))
                            end
                        end
                        o0 = tostring(r0) .. " {" .. table.concat(t0, ",") .. "}"
                    end
                    local x0 = type(s0.rateup_units) == "table" and s0.rateup_units or nil
                    if x0 then
                        local y0 = {
                        }
                        for z0, A0 in pairs(x0) do
                            if type(A0) == "string" and Core.Units [A0] then
                                table.insert(y0, A0)
                            end
                        end
                        table.sort(y0)
                        if # y0 > 0 then
                            n0 [r0] = y0
                        end
                    end
                end
            end
        end
    end
    if next(n0) then
        for B0, C0 in pairs(f0.feat or {
        }) do
            if not n0 [B0] then
                n0 [B0] = C0
            end
        end
        f0.feat, f0.lookAt, f0.changedAt = n0, os.time(), os.time()
        local D0 = {
        }
        for E0, F0 in pairs(n0) do
            local G0 = {
            }
            for H0, I0 in ipairs(F0) do
                table.insert(G0, Units.name(I0))
                f0.seen [I0] = {
                    banner = E0,
                    at = os.time()
                }
            end
            table.insert(D0, (FarmHub.BANNER_NAME [E0] or E0) .. ": " .. table.concat(G0, ", "))
        end
        table.sort(D0)
        App.log(1, "SUMMON", "Banner Snipe: the banners changed: " .. table.concat(D0, " · "))
        local J0 = Config.snipeOn and Config.snipeUnit ~= "" and not FarmHub.snipeHas() and FarmHub.snipeWhere(Config.snipeUnit)
        if J0 and f0.featured ~= J0 then
            f0.featured = J0
            FarmHub.snipeSay(string.format("%s is featured on %s right now%s", Units.name(Config.snipeUnit), FarmHub.BANNER_NAME [J0] or J0, App.where == "match" and ": the lobby pulls after this match" or ""))
        end
    else
        f0.changedAt = os.time()
        App.log(1, "SUMMON", "Banner Snipe: the game says a banner changed (" .. h0() .. (o0 and ("; " .. o0) or "") .. ")" .. (App.where == "match" and ": the lobby looks after this match" or ""))
    end
    FarmHub.last.snipe = nil
    App.saveSoon()
end

function FarmHub.snipeLook()
    local K0 = Brain.snipe
    local L0, M0 = App.request("hatch", "get_hatch_setup_data")
    if not (L0 and type(M0) == "table") then
        return nil
    end
    local N0, O0 = {
    }, {
    }
    for P0, Q0 in pairs(M0) do
        if type(Q0) == "table" then
            for R0 in pairs(Q0) do
                O0 [tostring(R0)] = true
            end
            if type(Q0.rateup_units) == "table" and Core.Banners [P0] then
                local S0 = {
                }
                for T0, U0 in pairs(Q0.rateup_units) do
                    if type(U0) == "string" and Core.Units [U0] then
                        table.insert(S0, U0)
                    end
                end
                table.sort(S0)
                N0 [P0] = S0
                for V0, W0 in ipairs(S0) do
                    K0.seen [W0] = {
                        banner = P0,
                        at = os.time()
                    }
                end
            end
        end
    end
    if not K0.keysSeen then
        local X0 = {
        }
        for Y0 in pairs(O0) do
            table.insert(X0, Y0)
        end
        table.sort(X0)
        K0.keysSeen = true
        App.log(1, "SUMMON", "Banner Snipe: a banner from the game carries " .. table.concat(X0, ", "))
    end
    K0.feat, K0.lookAt = N0, os.time()
    return N0
end

function FarmHub.snipeWhere(Z0)
    local _0, a1
    for b1, c1 in pairs(Brain.snipe.feat or {
    }) do
        local d1 = Core.Banners [b1]
        if d1 and d1.active and table.find(c1, Z0) then
            local e1 = FarmHub.snipeCost(b1)
            local f1 = not e1 and 9 or e1.cur == "GemsLegacy" and 1 or e1.cur == "gems" and 3 or 2
            if not a1 or f1 < a1 then
                _0, a1 = b1, f1
            end
        end
    end
    return _0
end

function FarmHub.bannerSnipe()
    if not (Config.snipeOn and Config.snipeUnit ~= "") then
        return
    end
    local g1 = Brain.snipe
    local h1 = Config.snipeUnit
    local i1 = Units.name(h1)
    if g1.unit ~= h1 then
        g1.unit, g1.pulls, g1.got, g1.featured, g1.note, g1.saidAt = h1, 0, nil, nil, nil, nil
    end
    if Adventure.have("celestial_compass_u21") > 0 and not (g1.compass and g1.compass.unit == h1) then
        local j1, k1 = App.request("hatch", "get_celestial_compass_units", "celestial_compass_u21")
        if j1 and type(k1) == "table" then
            local l1, m1 = false, 0
            for n1, o1 in pairs(k1) do
                m1 = m1 + 1
                if o1 == h1 then
                    l1 = true
                end
            end
            g1.compass = {
                unit = h1,
                at = os.time(),
                n = m1,
                on = l1
            }
            App.log(1, "SUMMON", string.format("Celestial Compass: it can pick %d units, %s", m1, l1 and (i1 .. " among them") or ("not " .. i1)))
            if l1 then
                FarmHub.snipeSay("your Celestial Compass can pick " .. i1 .. ". It's still in your bag: that pick is yours to make")
            end
        end
    end
    if FarmHub.snipeHas(h1) then
        if not g1.got then
            g1.got = os.time()
            FarmHub.snipeSay("you have " .. i1 .. "!")
        end
        return
    end
    if not FarmHub.snipeLook() then
        return
    end
    local p1 = FarmHub.snipeWhere(h1)
    if not p1 then
        if g1.featured then
            FarmHub.snipeSay(string.format("%s isn't featured any more. It waits for the next turnover (%s)", i1, os.date("%H:%M", FarmHub.snipeTurnAfter(os.time()))), "warning")
        end
        g1.featured = nil
        return
    end
    local q1 = FarmHub.snipeCost(p1)
    if not q1 then
        return
    end
    if g1.featured ~= p1 then
        g1.featured = p1
        FarmHub.snipeSay(string.format("%s is featured on %s right now", i1, q1.label))
    end
    local r1 = {
    }
    for s1, t1 in ipairs({
        "gems",
        "GemsLegacy",
        "SummerPearls"
    }) do
        if t1 ~= q1.cur then
            r1 [t1] = tonumber(Core.cur(t1)) or 0
        end
    end
    local u1, v1 = 0, 0
    while App.alive and Config.snipeOn and Config.snipeUnit == h1 and q1.have() - q1.cost * 10 >= q1.keep and FarmHub.watchRoom() and not FarmHub.snipeHas(h1) do
        local w1, x1 = q1.have(), Utils.now()
        local y1, z1 = App.request("snipe", "buy_from_banner", p1, "gems10")
        if not y1 and (z1 == "slowing down" or z1 == "waiting") and v1 < 3 then
            v1 = v1 + 1
            task.wait(3.5)
            continue
        end
        local A1 = Utils.now()
        while Utils.now() - A1 < 4 and q1.have() >= w1 do
            task.wait(0.25)
        end
        for B1, C1 in pairs(r1) do
            if (tonumber(Core.cur(B1)) or 0) < C1 then
                Config.snipeOn = false
                pcall(function()
                    GUI.UI.snipeOn.Set(false, true)
                end)
                App.saveSoon()
                return FarmHub.snipeSay(string.format("%s went down during a pull on %s, so Banner Snipe switched itself off", B1 == "gems" and "Gems" or B1, q1.label), "warning")
            end
        end
        if q1.have() >= w1 then
            local D1 = App.gameSaid(x1) or z1
            if tostring(D1):lower():find("too fast") and v1 < 3 then
                v1 = v1 + 1
                task.wait(6)
                continue
            end
            App.log(1, "SUMMON", "Banner Snipe: " .. q1.label .. " refused (" .. tostring(D1) .. ")")
            App.backoff("snipe", 600)
            break
        end
        v1 = 0
        u1 = u1 + 10
        g1.pulls = (tonumber(g1.pulls) or 0) + 10
        Spending.add("10 summons on " .. q1.label, w1 - q1.have(), q1.name, "Banner Snipe: " .. i1 .. " is featured")
        task.wait(5)
    end
    local E1 = FarmHub.snipeTurnAfter(os.time())
    if FarmHub.snipeHas(h1) then
        g1.got = os.time()
        FarmHub.snipeSay(string.format("you have %s! It dropped after %d pulls", i1, tonumber(g1.pulls) or 0))
    elseif g1.saidAt ~= E1 and not FarmHub.watchRoom() then
        g1.saidAt = E1
        FarmHub.snipeSay(i1 .. " is featured, but your unit storage is nearly full. Sell some units and it carries on", "warning")
    elseif g1.saidAt ~= E1 and q1.have() - q1.cost * 10 < q1.keep then
        g1.saidAt = E1
        FarmHub.snipeSay(string.format("%s is featured, but %s is at your Keep line (%s, keeping %s) after %d pulls", i1, q1.name, Utils.fmt(q1.have()), Utils.fmt(q1.keep), tonumber(g1.pulls) or 0), "warning")
    end
end

function FarmHub.snipeWanted()
    if not (Config.snipeOn and Config.snipeUnit ~= "") or FarmHub.snipeHas() or FarmHub.snipeStale() then
        return false
    end
    if App.req.back.snipe and Utils.now() < App.req.back.snipe then
        return false
    end
    local F1 = FarmHub.snipeWhere(Config.snipeUnit)
    local G1 = F1 and FarmHub.snipeCost(F1)
    return G1 ~= nil and G1.have() - G1.cost * 10 >= G1.keep and FarmHub.watchRoom()
end

function FarmHub.snipeDue()
    if not (Config.snipeOn and Config.snipeUnit ~= "") or FarmHub.snipeHas() or not FarmHub.snipeStale() then
        return false
    end
    local H1 = Brain.snipe
    local I1 = FarmHub.snipeTurnAfter(os.time()) - FarmHub.snipeRate()
    if (tonumber(H1.askAt) or 0) >= math.max(I1, tonumber(H1.changedAt) or 0) or not FarmHub.watchRoom() then
        return false
    end
    local J1 = false
    for K1, L1 in pairs(Core.Banners or {
    }) do
        local M1 = type(L1) == "table" and L1.active and FarmHub.snipeCost(K1)
        if M1 and M1.have() - M1.cost * 10 >= M1.keep then
            J1 = true
        end
    end
    if not J1 then
        return false
    end
    H1.askAt = os.time()
    return true
end

function FarmHub.snipeText()
    local N1 = Brain.snipe
    local O1 = Config.snipeUnit
    local P1 = {
    }
    if O1 == "" then
        table.insert(P1, "Pick a unit below. It's pulled on whichever banner features it, until it drops or a Keep line below is reached.")
    elseif FarmHub.snipeHas(O1) then
        table.insert(P1, "You have " .. Units.name(O1) .. ".")
    elseif not Config.snipeOn then
        table.insert(P1, Units.name(O1) .. " is picked. Switch Banner Snipe on to pull for it.")
    else
        local Q1 = not FarmHub.snipeStale() and FarmHub.snipeWhere(O1)
        table.insert(P1, Q1 and (Units.name(O1) .. " is featured on " .. (FarmHub.BANNER_NAME [Q1] or Q1) .. " right now.") or ("Waiting for " .. Units.name(O1) .. " to be featured."))
    end
    if N1.lookAt then
        local R1 = {
        }
        for S1, T1 in pairs(N1.feat or {
        }) do
            local U1 = {
            }
            for V1, W1 in ipairs(T1) do
                table.insert(U1, Units.name(W1))
            end
            if # U1 > 0 then
                table.insert(R1, (FarmHub.BANNER_NAME [S1] or S1) .. ": " .. table.concat(U1, ", "))
            end
        end
        table.sort(R1)
        table.insert(P1, "Featured at " .. os.date("%H:%M", N1.lookAt) .. " · " .. table.concat(R1, " · "))
    end
    table.insert(P1, string.format("Banners turn over next at %s%s", os.date("%H:%M", FarmHub.snipeTurnAfter(os.time())), N1.clock and "" or " (expected)"))
    table.insert(P1, string.format("Gems %s · Pearls %s · Legacy Gems %s · pulled so far: %d", Utils.fmt(tonumber(Core.cur("gems")) or 0), Utils.fmt(tonumber(Core.cur("SummerPearls")) or 0), Utils.fmt(tonumber(Core.cur("GemsLegacy")) or 0), tonumber(N1.pulls) or 0))
    if N1.note then
        table.insert(P1, os.date("%H:%M", N1.noteAt or os.time()) .. " " .. N1.note)
    end
    return table.concat(P1, "\n")
end

function FarmHub.summon()
    local X1 = Core.prof()
    if not X1 then
        return
    end
    local Y1 = {
    }
    local function Z1(_1, a2, b2, c2, d2, e2, f2, g2)
        local h2, i2 = 0, 0
        while h2 < Config.summonsPerVisit and b2() - d2 * 10 >= c2 and not (g2 and g2()) do
            local j2 = b2()
            local k2 = Utils.now()
            local l2, m2 = App.request("summon", "buy_from_banner", _1, "gems10")
            if not l2 and (m2 == "slowing down" or m2 == "waiting") and i2 < 3 then
                i2 = i2 + 1
                task.wait(3.5)
                continue
            end
            local n2 = Utils.now()
            while Utils.now() - n2 < 4 and b2() >= j2 do
                task.wait(0.1)
            end
            if not l2 or b2() >= j2 then
                local o2 = App.gameSaid(k2) or m2
                if tostring(o2):lower():find("too fast") and i2 < 3 then
                    i2 = i2 + 1
                    task.wait(2 * i2)
                    continue
                end
                App.log(1, "SUMMON", _1 .. " refused (" .. tostring(o2) .. ")")
                App.backoff("summon", 600)
                break
            end
            i2 = 0
            h2 = h2 + 10
            Spending.add("10 summons on " .. _1, j2 - b2(), f2, e2)
            task.wait(0.3)
        end
        return h2
    end
    if Config.summonApril and Core.Banners.April2025 then
        local p2 = Adventure.pullGoal()
        local q2, r2 = {
        }, {
        }
        local function s2(t2)
            if not table.find(r2, t2) then
                table.insert(q2, Units.name(t2))
                table.insert(r2, t2)
            end
        end
        if p2 then
            if p2.step == "pull" then
                s2(p2.id)
            end
        else
            for u2, v2 in ipairs({
                "osaka",
                "dokuro",
                "rikka",
                "chihiro"
            }) do
                local w2, x2 = Adventure.tierBest(v2)
                if not Units.owns(v2) and (not Config.community or x2 >= Adventure.TIER_RANK.S) then
                    s2(v2)
                end
            end
        end
        for y2, z2 in ipairs(Config.aprilTargets or {
        }) do
            if Core.Units [z2] and not Units.owns(z2) and not FarmHub.hatched [z2] then
                s2(z2)
            end
        end
        local A2 = Config.aprilFloor
        if p2 and p2.item and not p2.haveItem then
            A2 = math.max(A2, p2.itemCost)
        end
        local B2 = function()
            return Core.cur("AprilCoins")
        end
        if # q2 == 0 then
            table.insert(Y1, p2 and ("April banner: " .. Units.name(p2.id) .. " is yours ✓") or (Config.community and "April banner: you have every limited unit worth the coins ✓" or "April banner: all limited units owned ✓"))
        else
            local function C2(D2)
                return FarmHub.hatched [D2] or Units.owns(D2)
            end
            local G2 = function()
                for E2, F2 in ipairs(r2) do
                    if not C2(F2) then
                        return false
                    end
                end
                return true
            end
            local H2 = Z1("April2025", "AprilCoins", B2, A2, 150, "for " .. table.concat(q2, ", "), "AprilCoins", G2)
            for I2, J2 in ipairs(r2) do
                if C2(J2) then
                    App.log(1, "SUMMON", Units.name(J2) .. " dropped from the April banner!")
                    if p2 and J2 == p2.id then
                        if App.notify then
                            App.notify("Main goal", Units.name(p2.id) .. " is yours! Next: its evolve item (" .. Utils.fmt(p2.itemCost) .. " AprilCoins)", "success")
                        end
                        pcall(Adventure.refresh)
                    elseif App.notify then
                        App.notify("April banner", Units.name(J2) .. " is yours!", "success")
                    end
                end
            end
            table.insert(Y1, string.format("April banner: %s (%s coins, keeping %s)", H2 > 0 and (H2 .. " summons") or "saving", Utils.fmt(B2()), Utils.fmt(A2)))
        end
    end
    if Config.summonGems then
        local K2 = Units.equipped()
        local L2 = math.huge
        for M2, N2 in ipairs(K2) do
            if not Units.isFarm(N2.id) then
                L2 = math.min(L2, Units.score(N2.u))
            end
        end
        local O2, P2 = App.request("hatch", "get_hatch_setup_data")
        local Q2, R2 = {
        }, 0
        if O2 and type(P2) == "table" and P2.EventClover and P2.EventClover.rateup_units then
            for S2, T2 in pairs(P2.EventClover.rateup_units) do
                local U2, V2 = Adventure.tierBest(T2, true)
                if Core.Units [T2] and not Units.owns(T2) and Units.hidden(T2) and V2 >= Adventure.TIER_RANK.S then
                    table.insert(Q2, Units.name(U2) .. " (tier " .. tostring((Adventure.tier(U2, true))) .. ")")
                elseif Core.Units [T2] and not Units.owns(T2) and Units.hidden(T2) then
                    R2 = R2 + 1
                elseif Core.Units [T2] and not Units.owns(T2) then
                    local W2 = {
                        unit_id = T2,
                        uuid = "sim:" .. T2,
                        xp = 0,
                        traits = {
                        },
                        trait_stats = {
                            potency_stat = 1,
                            speed_stat = 1,
                            range_stat = 1
                        }
                    }
                    local X2, Y2 = pcall(Units.score, W2)
                    if X2 and Y2 > L2 then
                        table.insert(Q2, Units.name(T2))
                    end
                end
            end
        end
        if # Q2 == 0 then
            table.insert(Y1, "gem banner: nothing that beats your team" .. (R2 > 0 and string.format(" (%d featured units can't be judged: the game hides their upgrades)", R2) or ""))
        else
            local Z2 = function()
                return Core.cur("gems")
            end
            local _2 = Z1("EventClover", "gems", Z2, Config.gemFloor, 50, "would beat your weakest unit: " .. table.concat(Q2, ", "), "gems")
            table.insert(Y1, string.format("gem banner: %s", _2 > 0 and (_2 .. " summons") or "saving"))
        end
    end
    if Config.autoSummon and Config.summonBanner ~= "" and not (App.req.back.summon and Utils.now() < App.req.back.summon) then
        local a3 = FarmHub.bannerCost(Config.summonBanner)
        if a3 then
            local function b3()
                local c3 = 0
                for d3 in pairs(X1.collection.owned_units) do
                    c3 = c3 + 1
                end
                return c3 + 20 > (tonumber(X1.collection.capacity) or math.huge)
            end
            local e3 = Z1(Config.summonBanner, a3.name, a3.have, Config [a3.floor], a3.cost, "Auto Summon: your pick (Units → Summon)", a3.name, b3)
            local f3 = FarmHub.BANNER_NAME [Config.summonBanner] or Config.summonBanner
            table.insert(Y1, e3 > 0 and string.format("%s: %d summons", f3, e3) or (b3() and (f3 .. ": your unit storage is full") or (f3 .. ": at your Keep At Least line")))
        end
    end
    App.status("Summon", # Y1 > 0 and table.concat(Y1, " · ") or "off")
end

function FarmHub.buyStorage()
    local g3 = Brain.buyStorage
    if not g3 then
        return
    end
    Brain.buyStorage = nil
    App.saveNow()
    local h3 = Core.prof()
    local i3 = Core.GS.CAPACITY_INCREASES and Core.GS.CAPACITY_INCREASES.units
    local j3 = h3.inventory_capacity_increases and tonumber(h3.inventory_capacity_increases.unit_capacity_increase) or 0
    local k3 = i3 and i3 [j3 + 1]
    if not k3 then
        return App.log(1, "SHOP", "unit storage: no more steps to buy")
    end
    local l3 = tonumber(k3.gold_cost) or math.huge
    if l3 > (tonumber(g3.maxGold) or 0) then
        return App.log(1, "SHOP", string.format("unit storage: the next step costs %s gold, more than the %s you agreed: not bought", Utils.fmt(l3), Utils.fmt(g3.maxGold)))
    end
    local m3, n3 = tonumber(Core.cur("gold")) or 0, h3.collection.capacity
    local o3 = Utils.now()
    local p3, q3 = App.request("storage", "try_purchase_unit_capacity")
    while Utils.now() - o3 < 5 and (tonumber(Core.cur("gold")) or 0) >= m3 do
        task.wait(0.25)
    end
    local s3 = m3 - (tonumber(Core.cur("gold")) or 0)
    if s3 > 0 then
        Spending.add("+" .. tostring(k3.increase) .. " unit storage", s3, "gold", "your go-ahead: the collection was full, which refuses every pad")
        App.log(1, "SHOP", string.format("bought +%s unit storage for %s gold (storage was %s) · gold %s", tostring(k3.increase), Utils.fmt(s3), tostring(n3), Utils.fmt(Core.cur("gold"))))
        Modes.rec("dc").restUntil, Modes.rec("dc").restWhy = nil, nil
        Modes.lastScored, FarmHub.last.pick = nil, nil
    else
        task.wait(0.5)
        App.log(1, "SHOP", string.format("the game didn't sell unit storage (%s): not trying again", tostring(App.gameSaid(o3) or (p3 and q3) or "no answer")))
    end
    App.saveSoon()
end

function FarmHub.buyOnce()
    local t3 = Brain.buyOnce
    if not t3 then
        return
    end
    local u3 = (Core.Items [t3.item] or {
    }).name or t3.item
    Brain.buyOnce = nil
    App.saveNow()
    if Adventure.have(t3.item) >= 1 then
        return App.log(1, "SHOP", u3 .. ": you have one already, so nothing was bought")
    end
    local v3 = tonumber(Core.cur(t3.cur)) or 0
    if v3 < (tonumber(t3.max) or 0) then
        return App.log(1, "SHOP", string.format("%s: %s short of its %s %s, so nothing was bought", u3, Utils.fmt(v3), Utils.fmt(t3.max), tostring(t3.cur)))
    end
    local w3 = Utils.now()
    local x3, y3 = App.request("eshop", "buy_item_generic", t3.item, t3.shop or "event", t3.gui or "event_shop", "1")
    while Utils.now() - w3 < 5 and Adventure.have(t3.item) < 1 do
        task.wait(0.25)
    end
    local z3 = v3 - (tonumber(Core.cur(t3.cur)) or 0)
    if Adventure.have(t3.item) >= 1 then
        Spending.add(u3, z3, tostring(t3.cur), tostring(t3.why or "your go-ahead"))
        pcall(Adventure.refresh)
        FarmHub.last.goals = nil
        if App.notify then
            App.notify("Shop", "Bought " .. u3, "success")
        end
    else
        task.wait(0.5)
        App.log(1, "SHOP", string.format("the shop didn't sell %s (%s): not trying again", u3, tostring(App.gameSaid(w3) or (x3 and y3) or "no answer")))
    end
end

function FarmHub.pad(A3, B3)
    local function C3(D3)
        for E3, F3 in ipairs(D3:GetChildren()) do
            local G3 = F3:FindFirstChild("Owner")
            local H3 = F3:FindFirstChild("Active")
            if G3 and G3.Value == nil and not (H3 and H3.Value) then
                return F3
            end
        end
    end
    if A3 == "story" or A3 == "infinite" then
        return C3(workspace._LOBBIES.Story)
    end
    if A3 == "raid" then
        return C3(workspace._RAID.Raid)
    end
    if A3 == "challenge" then
        return workspace._CHALLENGES.Challenges:GetChildren() [1]
    end
    if A3 == "daily" then
        return workspace._CHALLENGES.DailyChallenge:GetChildren() [1]
    end
    if A3 == "event" then
        local I3 = Brain.live.event and Brain.live.event.pad
        return I3 and workspace._EVENT_CHALLENGES.Lobbies:FindFirstChild(I3) or nil
    end
end

function FarmHub.launch(J3)
    if J3.kind == "dungeon" then
        return Dungeon.launch(J3)
    end
    local K3, L3 = pcall(Strategy.relicsApply)
    if not K3 then
        App.log(1, "ERROR", "relics: " .. tostring(L3))
    end
    Brain.watch = nil
    for M3, N3 in pairs(Modes.PORTALS) do
        if (J3.kind == "portal" and J3.level == N3.level) or (J3.portalMap and J3.level == N3.from) then
            Brain.watch = {
                key = J3.key,
                portal = M3,
                item = N3.item,
                have = Adventure.have(N3.item),
                held = # Modes.portalsHeld(M3),
                used = J3.kind == "portal",
                at = os.time()
            }
        end
    end
    if J3.kind == "portal" or J3.kind == "artifact" then
        return FarmHub.launchPortal(J3)
    end
    local O3 = FarmHub.pad(J3.kind, J3)
    if not O3 then
        App.log(1, "MODE", "no free pad for " .. J3.label)
        App.backoff("launch", 20)
        return false
    end
    Brain.pending = {
        key = J3.key,
        kind = J3.kind,
        level = J3.level,
        diff = J3.diff,
        label = J3.label,
        at = os.time(),
        value = J3.value
    }
    if Brain.nextMode == J3.key then
        Brain.nextMode = nil
    end
    App.log(1, "MODE", string.format("launching %s on %s — %s (≈%.0f gems/min)", J3.label, O3.Name, J3.why or "", J3.score or 0))
    App.saveNow()
    App.status("Mode", "starting " .. J3.label)
    if FarmHub.matchOn(J3) then
        FarmHub.matchmake(J3)
        local P3, Q3 = pcall(Modes.needsHelp, J3)
        if App.alive and J3.kind == "daily" and P3 and Q3 then
            App.log(1, "MODE", "nobody joined the Daily Challenge, and the simulator says your team can't win it alone: not played alone, matchmaking again in 10 min")
            Brain.pending = nil
            local R3 = Modes.rec(J3.key)
            R3.restUntil, R3.restWhy = os.time() + 600, "alone"
            Modes.lastScored = nil
            App.backoff("launch", 5)
            return false
        end
    end
    local S3 = Utils.now()
    local T3, U3 = App.request("join", "request_join_lobby", O3.Name)
    if not (T3 and U3) then
        task.wait(0.5)
        local V3 = App.gameSaid(S3)
        App.log(1, "MODE", "join refused on " .. O3.Name .. " (" .. tostring(V3 or U3) .. ")" .. (V3 and (": " .. J3.label .. " rests for half an hour") or ""))
        Brain.pending = nil
        if V3 then
            Modes.rec(J3.key).restUntil, Modes.rec(J3.key).restWhy = os.time() + 1800, "refused"
            Modes.lastScored = nil
        end
        App.backoff("launch", V3 and 5 or 15)
        return false
    end
    if J3.kind == "story" or J3.kind == "raid" or J3.kind == "infinite" then
        local W3, X3 = App.request("lock", "request_lock_level", O3.Name, J3.level, false, J3.diff)
        if not (W3 and X3) then
            App.log(1, "MODE", "lock refused for " .. J3.label .. " (" .. tostring(X3) .. ")")
            App.request("leave", "request_leave_lobby", O3.Name)
            local Y3 = Modes.rec(J3.key)
            Y3.restUntil, Y3.restWhy = os.time() + 1800, "refused"
            Brain.pending = nil
            App.backoff("launch", 10)
            return false
        end
    end
    task.wait(0.5)
    App.request("start", "request_start_game", O3.Name)
    local Z3 = Utils.now()
    while App.alive and Utils.now() - Z3 < 45 do
        task.wait(1)
    end
    if App.alive then
        App.log(1, "MODE", "no teleport after 45s for " .. J3.label .. " — leaving the pad")
        App.request("leave", "request_leave_lobby", O3.Name)
        local _3 = Modes.rec(J3.key)
        _3.restUntil, _3.restWhy = os.time() + 900, "no teleport"
        Brain.pending = nil
        App.backoff("launch", 10)
    end
    return false
end

function FarmHub.matchOn(a4)
    if Brain.trial or (Brain.testTeam and (Brain.testTeam.left or 0) > 0) then
        return false
    end
    if a4.kind == "daily" then
        return Config.dailyMatch == true
    end
    local b4 = (a4.kind == "raid" and Config.mmRaid) or (a4.kind == "infinite" and Config.mmInfinite) or (a4.kind == "story" and a4.legend and Config.mmLegend) or (a4.kind == "event" and Config.mmEvent)
    local c4 = b4 and Core.Levels [a4.level]
    return c4 ~= nil and c4 ~= false and type(c4._MATCHMAKING) == "table"
end

function FarmHub.matchmake(d4)
    local e4 = ReplicatedStorage.endpoints.server_to_client
    local f4, g4, h4 = false, false, {
    }
    if e4:FindFirstChild("matchmaking_started") then
        table.insert(h4, e4.matchmaking_started.OnClientEvent:Connect(function()
            f4 = true
        end))
    end
    if e4:FindFirstChild("matchmaking_ended") then
        table.insert(h4, e4.matchmaking_ended.OnClientEvent:Connect(function()
            g4 = true
        end))
    end
    for i4, j4 in ipairs(h4) do
        table.insert(App.conns, j4)
    end
    local function k4()
        for l4, m4 in ipairs(h4) do
            m4:Disconnect()
        end
    end
    local n4 = Utils.now()
    local o4 = d4.kind == "daily" and "__DAILY_CHALLENGE" or d4.level
    local p4 = tostring(d4.label or o4)
    local q4, r4 = App.request("match", "request_matchmaking", o4)
    while App.alive and Utils.now() - n4 < 5 and not f4 do
        task.wait(0.25)
    end
    if not f4 then
        App.log(1, "MODE", "matchmaking didn't start for " .. p4 .. " (" .. tostring(App.gameSaid(n4) or (q4 and r4) or "no answer") .. "): alone")
        k4()
        return false
    end
    local s4 = math.max(30, tonumber(Config.dailyMatchWait) or 120)
    App.log(1, "MODE", string.format("matchmaking for %s: up to %d s for other players, then alone", p4, s4))
    App.status("Mode", "matchmaking: " .. p4)
    local t4
    while App.alive and Utils.now() - n4 < s4 do
        if g4 and not t4 then
            t4 = Utils.now()
        end
        if t4 and Utils.now() - t4 > 30 then
            break
        end
        task.wait(1)
    end
    if not App.alive then
        return true
    end
    k4()
    App.request("match_leave", "leave_matchmaking")
    App.log(1, "MODE", t4 and ("matchmaking ended with no match: " .. p4 .. " alone") or string.format("nobody joined in %d s: %s alone", s4, p4))
    task.wait(2)
    return false
end

function FarmHub.launchPortal(u4)
    Brain.pending = {
        key = u4.key,
        kind = u4.kind,
        level = u4.level,
        diff = u4.diff,
        label = u4.label,
        at = os.time(),
        value = u4.value
    }
    App.log(1, "MODE", string.format("launching %s %s — %s (≈%.0f gems/min)", u4.label, u4.kind == "artifact" and "alone" or ("with a " .. ((Core.Items [(Brain.watch or {
    }).portal or ""] or {
    }).name or "portal")), u4.why or "", u4.score or 0))
    App.saveNow()
    App.status("Mode", "opening " .. u4.label)
    local v4 = Utils.now()
    local w4
    if u4.kind == "artifact" then
        _, w4 = App.request("portal", "open_portal_level_new", u4.level, {
            difficulty = "Hard"
        })
    else
        _, w4 = App.request("portal", "use_portal", u4.portal)
    end
    local x4 = Core.svc("LobbyServiceClient")
    local function y4()
        local z4 = x4 and x4.current_lobby
        if z4 then
            return z4
        end
        local A4 = workspace:FindFirstChild("_PORTALS") and workspace._PORTALS:FindFirstChild("Lobbies")
        for B4, C4 in ipairs(A4 and A4:GetChildren() or {
        }) do
            local D4 = C4:FindFirstChild("Owner")
            if D4 and D4.Value == LocalPlayer then
                return C4.Name
            end
        end
    end
    local E4
    while App.alive and Utils.now() - v4 < 28 and not E4 do
        E4 = y4()
        if not E4 then
            if App.gameSaid(v4) then
                break
            end
            task.wait(0.5)
        end
    end
    if E4 and Utils.now() - v4 > 10 then
        App.log(1, "MODE", string.format("the portal opened late (after %.0f s): it plays", Utils.now() - v4))
    end
    if not E4 then
        local F4 = App.gameSaid(v4)
        local G4 = F4 and F4:lower():find("once every", 1, true)
        FarmHub.badPortal = FarmHub.badPortal or {
        }
        if u4.portal and not G4 then
            FarmHub.badPortal [u4.portal] = os.time() + 3600
        end
        local H4 = u4.kind == "artifact" and not G4
        if H4 then
            Modes.rec(u4.key).restUntil, Modes.rec(u4.key).restWhy = os.time() + 1800, "refused"
            Modes.lastScored = nil
        end
        App.log(1, "MODE", string.format("the %s didn't open (%s): trying again %s", u4.kind == "artifact" and "Artifact Stage" or "portal", tostring(F4 or w4 or "no answer"), G4 and "once the game's 30 s are up" or (H4 and "in half an hour" or "with another portal")))
        task.wait(2)
        local I4 = y4()
        if I4 then
            App.request("leave", "request_leave_lobby", I4)
        end
        Brain.pending, Brain.watch = nil, nil
        App.backoff("launch", math.max(5, 32 - (Utils.now() - v4)))
        return false
    end
    task.wait(0.5)
    pcall(function()
        local J4 = x4 and x4.more_lobby_params and x4.more_lobby_params [E4]
        local K4 = J4 and J4._level_data
        if type(K4) ~= "table" then
            return
        end
        local L4 = Core.Levels [u4.level] or {
        }
        local M4 = {
        }
        for N4, O4 in pairs(K4) do
            local P4 = L4 [N4]
            if type(O4) ~= "table" and type(O4) ~= "function" and O4 ~= P4 then
                table.insert(M4, tostring(N4) .. "=" .. tostring(O4))
            elseif type(O4) == "table" and type(P4) ~= "table" then
                local Q4, R4 = pcall(HttpService.JSONEncode, HttpService, O4)
                table.insert(M4, tostring(N4) .. "=" .. (Q4 and R4:sub(1, 120) or "{…}"))
            end
        end
        table.sort(M4)
        local S4 = # M4 > 0 and table.concat(M4, " · ") or "none beyond the plain level"
        Brain.portalMods = S4
        App.saveNow()
        App.log(1, "PORTAL", string.format("%s opened: %s", u4.label, S4:sub(1, 400)))
        local T4 = S4:find("weak") or S4:find("challenge") or S4:find("difficulty") or S4:find("resist") or S4:find("health")
        if T4 and Config.autoTeam then
            u4.ldOverride = K4
            local U4, V4 = pcall(FarmHub.teamFor, u4, FarmHub.QUICK_SEARCH)
            if not U4 then
                App.log(1, "ERROR", "portal team: " .. tostring(V4))
            end
            u4.ldOverride = nil
        end
    end)
    local W4 = Utils.now()
    local X4 = {
    }
    for Y4 = 1, 3 do
        local Z4, _4 = App.request("start", "request_start_game", E4)
        table.insert(X4, tostring(Z4 and _4))
        local a5 = Utils.now()
        while App.alive and Utils.now() - a5 < 12 do
            task.wait(1)
        end
        if not App.alive then
            return false
        end
        E4 = (x4 and x4.current_lobby) or E4
    end
    if App.alive then
        local b5 = App.gameSaid(W4)
        App.log(1, "MODE", string.format("no teleport after 3 Starts (%s%s) for %s — leaving the portal lobby, %s", table.concat(X4, ", "), b5 and (", the game said: " .. b5) or "", u4.label, u4.kind == "artifact" and "trying again in 15 min" or "next try with another portal"))
        App.request("leave", "request_leave_lobby", E4)
        FarmHub.badPortal = FarmHub.badPortal or {
        }
        if u4.portal then
            FarmHub.badPortal [u4.portal] = os.time() + 3600
        end
        if u4.kind == "artifact" then
            Modes.rec(u4.key).restUntil, Modes.rec(u4.key).restWhy = os.time() + 900, "no teleport"
            Modes.lastScored = nil
        end
        Brain.pending, Brain.watch = nil, nil
        App.backoff("launch", 10)
    end
    return false
end

function FarmHub.portalLine(c5)
    local d5 = Core.FOLDER .. "/portal_runs.txt"
    local e5, f5 = pcall(readfile, d5)
    pcall(writefile, d5, (e5 and f5 or "") .. c5 .. "\n")
end

function FarmHub.watchDone()
    local g5 = Brain.watch
    if not g5 then
        return
    end
    Brain.watch = nil
    if os.time() - (tonumber(g5.at) or 0) > 3 * 3600 then
        return
    end
    local h5 = Adventure.have(g5.item) - (tonumber(g5.have) or 0)
    local i5 = # Modes.portalsHeld(g5.portal)
    local function j5(k5, l5)
        local m5 = Brain.portalPay [k5] or {
            n = 0
        }
        m5.n = (tonumber(m5.n) or 0) + 1
        m5.per = m5.per and (m5.per + (l5 - m5.per) * math.max(0.25, 1 / m5.n)) or l5
        Brain.portalPay [k5] = m5
    end
    local n5, o5 = (Core.Items [g5.item] or {
    }).name or g5.item, (Core.Items [g5.portal] or {
    }).name or g5.portal
    if g5.used then
        FarmHub.portalLine(string.format("%s · paid +%d %s (now %d) · %d portals left", os.date("%m-%d %H:%M"), h5, n5, Adventure.have(g5.item), i5))
        if g5.won == false then
            App.log(1, "PORTAL", string.format("%s: lost, so +%d %s (now %d) · %d portals left · not counted as what a portal pays", Modes.levelName(Modes.PORTALS [g5.portal].level), h5, n5, Adventure.have(g5.item), i5))
        else
            j5(g5.portal, math.max(0, h5))
            App.log(1, "PORTAL", string.format("%s: +%d %s (now %d) · %d portals left", Modes.levelName(Modes.PORTALS [g5.portal].level), h5, n5, Adventure.have(g5.item), i5))
        end
    else
        local p5 = i5 - (tonumber(g5.held) or 0)
        j5("drop:" .. g5.portal, math.max(0, p5))
        App.log(1, "PORTAL", string.format("%s dropped %d %s (now %d)%s", Modes.levelName(Modes.PORTALS [g5.portal].from), p5, o5, i5, h5 > 0 and string.format(" · +%d %s", h5, n5) or ""))
    end
    Modes.lastScored = nil
    App.saveSoon()
end

function FarmHub.simFresh(q5)
    local r5 = Brain.simRes [q5.key]
    return r5 and r5.sig == Modes.teamSig() and os.time() - (r5.at or 0) < 6 * 3600 or false
end

function FarmHub.relicClash(s5)
    local t5 = Core.session()
    local u5 = {
    }
    for v5, w5 in ipairs(Brain.savedTeam or {
    }) do
        u5 [w5] = true
    end
    local x5 = {
    }
    for y5, z5 in ipairs(s5) do
        local A5 = t5.collection:get_unit_by_uuid(z5)
        local B5 = A5 and A5._equipped_relic and t5.inventory:get_item_by_uuid(A5._equipped_relic)
        if B5 and B5.item_id and (Core.Items [B5.item_id] or {
        }).unique_equip then
            table.insert(x5, {
                uuid = z5,
                u = A5,
                kind = B5.item_id,
                relic = A5._equipped_relic,
                k = (u5 [z5] and 1e12 or 0) + Strategy.score(A5)
            })
        end
    end
    table.sort(x5, function(C5, D5)
        if C5.k ~= D5.k then
            return C5.k > D5.k
        end
        return C5.uuid < D5.uuid
    end)
    local E5 = {
    }
    for F5, G5 in ipairs(x5) do
        if E5 [G5.kind] then
            local H5 = (Core.Items [G5.kind] or {
            }).name or G5.kind
            local I5, J5 = App.request("relicOff", "request_unequip_relic", G5.relic)
            local K5 = Utils.now()
            while Utils.now() - K5 < 3 and G5.u._equipped_relic == G5.relic do
                task.wait(0.25)
            end
            if G5.u._equipped_relic ~= G5.relic then
                Brain.relicOff [G5.uuid] = G5.relic
                App.log(1, "TEAM", string.format("%s took off its %s for this team: %s has one, and a team can hold one of each", Units.name(G5.u.unit_id), H5, Units.name(E5 [G5.kind])))
            else
                App.log(1, "TEAM", string.format("%s's %s wouldn't come off (%s): the game won't take both on a team", Units.name(G5.u.unit_id), H5, tostring(J5)))
            end
        else
            E5 [G5.kind] = G5.u.unit_id
        end
    end
end

function FarmHub.relicBack()
    if Config.team and Config.teamRelics then
        table.clear(Brain.relicOff)
        return
    end
    local L5 = Core.session()
    for M5, N5 in pairs(Brain.relicOff) do
        local O5 = L5.collection:get_unit_by_uuid(M5)
        local P5 = L5.inventory:get_item_by_uuid(N5)
        local Q5 = P5 and P5._unique_item_data and P5._unique_item_data._unique_relic_data
        if O5 and Q5 and not O5._equipped_relic and not Q5._equipped_unit_uuid and not Strategy.slotOf(M5) then
            local R5
            for S5, T5 in ipairs(Units.equipped()) do
                local U5 = T5.u._equipped_relic and L5.inventory:get_item_by_uuid(T5.u._equipped_relic)
                if U5 and U5.item_id == P5.item_id then
                    R5 = T5
                end
            end
            if R5 then
                Brain.str.reequip = {
                    uuid = R5.uuid,
                    slot = R5.slot
                }
                App.saveNow()
                App.request("uneq", "unequip_unit", R5.uuid)
                local V5 = Utils.now()
                while Utils.now() - V5 < 4 and Strategy.slotOf(R5.uuid) do
                    task.wait(0.25)
                end
            end
            App.request("relicOff", "use_unique_item", N5, {
                unit_uuid = M5
            })
            local W5 = Utils.now()
            while Utils.now() - W5 < 3 and O5._equipped_relic ~= N5 do
                task.wait(0.25)
            end
            if R5 then
                Strategy.reequip()
            end
            App.log(1, "TEAM", string.format("%s has its %s back%s", Units.name(O5.unit_id), (Core.Items [P5.item_id] or {
            }).name or tostring(P5.item_id), O5._equipped_relic == N5 and "" or ": the game didn't take it"))
        end
        Brain.relicOff [M5] = nil
    end
end

function FarmHub.equipTeam(X5, Y5)
    local Z5 = {
    }
    for _5, a6 in ipairs(Units.equipped()) do
        Z5 [a6.uuid] = true
    end
    if not Brain.savedTeam then
        local b6 = {
        }
        for c6, d6 in ipairs(Units.equipped()) do
            table.insert(b6, d6.uuid)
        end
        Brain.savedTeam = b6
    end
    local e6, f6 = pcall(FarmHub.relicClash, X5)
    if not e6 then
        App.log(1, "ERROR", "relic clash: " .. tostring(f6))
    end
    local g6 = {
    }
    for h6, i6 in ipairs(X5) do
        g6 [i6] = true
    end
    local j6, k6 = false, {
    }
    for l6 = 1, 4 do
        for m6 in pairs(Z5) do
            if not g6 [m6] then
                local n6, o6 = App.request("uneq", "unequip_unit", m6)
                table.insert(k6, string.format("out %s: %s", Units.name((Core.session().collection:get_unit_by_uuid(m6) or {
                }).unit_id or "?"), tostring(o6)))
                task.wait(0.8)
            end
        end
        for p6, q6 in ipairs(X5) do
            if not Z5 [q6] then
                local r6
                if l6 > 2 then
                    local s6 = {
                    }
                    for t6, u6 in ipairs(Units.equipped()) do
                        s6 [u6.slot] = true
                    end
                    for v6 = 1, 6 do
                        if not s6 [v6] then
                            r6 = v6
                            break
                        end
                    end
                end
                local w6, x6
                if r6 then
                    w6, x6 = App.request("eq", "equip_unit", q6, r6)
                else
                    w6, x6 = App.request("eq", "equip_unit", q6)
                end
                table.insert(k6, string.format("in %s%s: %s %s", Units.name((Core.session().collection:get_unit_by_uuid(q6) or {
                }).unit_id or "?"), r6 and (" slot " .. r6) or "", tostring(w6), tostring(x6)))
                task.wait(0.8)
            end
        end
        local y6 = Utils.now()
        while Utils.now() - y6 < 3 and not Training.same(Training.team(), X5) do
            task.wait(0.25)
        end
        j6 = Training.same(Training.team(), X5)
        if j6 then
            break
        end
        Z5 = {
        }
        for z6, A6 in ipairs(Units.equipped()) do
            Z5 [A6.uuid] = true
        end
    end
    Modes._sigAt = nil
    if j6 then
        App.log(1, "TEAM", "equipped " .. # X5 .. " units — " .. tostring(Y5))
    else
        local B6 = {
        }
        for C6, D6 in ipairs(Units.equipped()) do
            table.insert(B6, Units.name(D6.id))
        end
        App.log(1, "TEAM", "the team swap didn't take (" .. tostring(Y5) .. "): the game has " .. table.concat(B6, ", ") .. " · calls: " .. table.concat(k6, " · "))
        if not FarmHub.refilling and # Units.equipped() < 6 then
            FarmHub.refilling = true
            local E6, F6 = {
            }, {
            }
            for G6, H6 in ipairs(Units.equipped()) do
                F6 [H6.uuid] = true
            end
            for I6, J6 in ipairs(Brain.savedTeam or {
            }) do
                if not F6 [J6] and Core.session().collection:get_unit_by_uuid(J6) then
                    table.insert(E6, J6)
                end
            end
            local K6 = 0
            for L6, M6 in ipairs(E6) do
                if # Units.equipped() >= 6 then
                    break
                end
                App.request("eq", "equip_unit", M6)
                task.wait(0.8)
                local N6 = Utils.now()
                while Utils.now() - N6 < 3 and # Units.equipped() < math.min(6, K6 + 1 + (6 - # E6)) do
                    task.wait(0.25)
                end
                for O6, P6 in ipairs(Units.equipped()) do
                    if P6.uuid == M6 then
                        K6 = K6 + 1
                    end
                end
            end
            local Q6 = {
            }
            for R6, S6 in ipairs(Units.equipped()) do
                table.insert(Q6, Units.name(S6.id))
            end
            App.log(1, "TEAM", string.format("filled the empty slots with %d of your own units back: the team is %s", K6, table.concat(Q6, ", ")))
            Modes._sigAt = nil
            FarmHub.refilling = nil
        end
    end
    App.saveSoon()
    return j6
end

function FarmHub.ownSwap()
    local T6 = Brain.ownSwap
    if not T6 then
        return
    end
    local U6 = App.request("hatch", "get_hatch_setup_data")
    if not U6 then
        return
    end
    if Brain.train.on then
        Training.home()
    end
    local V6 = Core.session()
    local W6 = table.clone(Brain.savedTeam or Training.team())
    local X6, Y6
    for Z6, _6 in ipairs(W6) do
        local a7 = V6.collection:get_unit_by_uuid(_6)
        if a7 and a7.unit_id == T6.out then
            X6 = Z6
        end
        if a7 and a7.unit_id == T6.into then
            Y6 = true
        end
    end
    local b7, c7
    for d7, e7 in pairs(V6.profile_data.collection.owned_units) do
        if e7.unit_id == T6.into and (not b7 or (tonumber(e7.xp) or 0) > c7) then
            b7, c7 = d7, tonumber(e7.xp) or 0
        end
    end
    if Y6 or not X6 or not b7 then
        Brain.ownSwap = nil
        App.log(1, "TEAM", string.format("your own team: %s for %s wasn't needed (%s), nothing changed", Units.name(T6.into), Units.name(T6.out), Y6 and "it's already on" or not X6 and "that unit isn't on your team" or "you don't have that unit"))
        return App.saveSoon()
    end
    W6 [X6] = b7
    local f7 = Brain.savedTeam
    Brain.savedTeam = nil
    if FarmHub.equipTeam(W6, string.format("your own team: %s in for %s", Units.name(T6.into), Units.name(T6.out))) then
        Brain.savedTeam, Brain.ownSwap = nil, nil
        Modes.lastScored = nil
        if App.notify then
            App.notify("Team", string.format("%s is on your team, in for %s", Units.name(T6.into), Units.name(T6.out)), "success")
        end
    else
        Brain.savedTeam = f7 or Brain.savedTeam
    end
    App.saveSoon()
end

function FarmHub.restoreTeam()
    if not Brain.savedTeam then
        return false
    end
    local g7 = {
    }
    for h7, i7 in ipairs(Brain.savedTeam) do
        if Core.session() and Core.session().collection:get_unit_by_uuid(i7) then
            table.insert(g7, i7)
        end
    end
    Brain.savedTeam = nil
    Brain.savedTeam = not FarmHub.equipTeam(g7, "your own team back") and g7 or nil
    if not Brain.savedTeam then
        local j7, k7 = pcall(FarmHub.relicBack)
        if not j7 then
            App.log(1, "ERROR", "relic back: " .. tostring(k7))
        end
    end
    App.saveSoon()
    return true
end
FarmHub.QUICK_SEARCH = 7

function FarmHub.teamFor(l7, m7)
    if l7.key == "dg" then
        if Brain.savedTeam then
            FarmHub.restoreTeam()
        end
        return
    end
    local n7 = Core.session()
    local o7 = Brain.testTeam
    if o7 and (o7.left or 0) > 0 and o7.key == l7.key and type(o7.uuids) == "table" then
        local p7 = 0
        for q7, r7 in ipairs(o7.uuids) do
            if n7.collection:get_unit_by_uuid(r7) then
                p7 = p7 + 1
            end
        end
        if p7 == # o7.uuids then
            if Brain.train.on then
                Training.home()
            end
            if not Training.same(Training.team(), o7.uuids) then
                FarmHub.equipTeam(o7.uuids, "team test: " .. tostring(o7.label))
            end
            return
        end
    end
    if Config.dailyLoop and l7.kind == "daily" and type(Config.dailyTeam) == "table" and # Config.dailyTeam > 0 then
        local s7, t7 = {
        }, {
        }
        for u7, v7 in ipairs(Brain.savedTeam or Training.team()) do
            local w7 = n7.collection:get_unit_by_uuid(v7)
            if w7 then
                t7 [w7.unit_id] = v7
            end
        end
        for x7, y7 in ipairs(Config.dailyTeam) do
            local z7, A7 = t7 [y7], nil
            if not z7 then
                local B7, C7 = Units.isFarm(y7), Units.rows(y7)
                for D7, E7 in pairs(n7.profile_data.collection.owned_units) do
                    if E7.unit_id == y7 then
                        local F7 = n7.collection:get_unit_by_uuid(E7.uuid) or E7
                        local G7, H7
                        if B7 then
                            G7, H7 = pcall(Units.farm, F7, C7 and C7.max or 0)
                        else
                            G7, H7 = pcall(Units.score, F7)
                        end
                        H7 = G7 and H7 or 0
                        if not A7 or H7 > A7 then
                            z7, A7 = E7.uuid, H7
                        end
                    end
                end
            end
            if z7 then
                table.insert(s7, z7)
            end
        end
        if # s7 == # Config.dailyTeam then
            if Brain.train.on then
                Training.home()
            end
            if not Training.same(Training.team(), s7) then
                FarmHub.equipTeam(s7, "your team for the Daily Challenge")
            end
            return
        end
        App.log(1, "TEAM", "your Daily Challenge team has a unit you no longer own: the search picks instead")
    end
    local I7 = Brain.savedTeam or Training.team()
    local J7 = {
    }
    for K7, L7 in ipairs(I7) do
        local M7 = n7.collection:get_unit_by_uuid(L7)
        if M7 then
            table.insert(J7, M7)
        end
    end
    if # J7 == 0 then
        return
    end
    local N7 = Simulator.sig(J7)
    local O7 = Brain.simTeam [l7.key]
    if not (O7 and O7.base == N7 and os.time() - (tonumber(O7.at) or 0) < 120) then
        App.status("Mode", "looking for the best team for " .. tostring(l7.label))
        Simulator.memoOn()
        local P7, Q7 = pcall(Simulator.plan, l7, true, m7 or 20, J7)
        Simulator.memo = nil
        if not P7 then
            App.log(1, "ERROR", "team search: " .. tostring(Q7))
        end
    end
    local R7 = Brain.simTeam [l7.key]
    local S7 = R7 and R7.base == N7 and os.time() - (tonumber(R7.at) or 0) < 120
    local T7 = (S7 and R7.better and type(R7.uuids) == "table" and # R7.uuids > 0) and R7.uuids or I7
    local U7 = Brain.train.on
    if U7 and not Training.same(U7.base or {
    }, T7) then
        Training.home()
        U7 = nil
    end
    if not U7 and not Training.same(Training.team(), T7) then
        if T7 == I7 and Brain.savedTeam then
            FarmHub.restoreTeam()
        else
            FarmHub.equipTeam(T7, (S7 and R7.why) and (R7.why .. ": " .. tostring(l7.label)) or ("the simulator's best team for " .. tostring(l7.label)))
        end
    end
end

function FarmHub.run()
    App.status("Mode", "in the lobby")
    local V7 = Utils.now()
    pcall(Units.markHidden)
    pcall(function()
        local W7 = ReplicatedStorage.endpoints.server_to_client:FindFirstChild("units_hatched_through_banner")
        if not W7 then
            return
        end
        table.insert(App.conns, W7.OnClientEvent:Connect(function(X7)
            for Y7, Z7 in pairs(type(X7) == "table" and X7 or {
            }) do
                local _7 = Core.session() and Core.session().collection:get_unit_by_uuid(Z7)
                if _7 and _7.unit_id then
                    FarmHub.hatched [_7.unit_id] = true
                    App.log(2, "SUMMON", "pulled " .. Units.name(_7.unit_id))
                end
            end
        end))
    end)
    App.listenGame()
    task.delay(6, function()
        local a8, b8 = pcall(Strategy.xpSettle)
        if not a8 then
            App.log(1, "ERROR", "xp settle: " .. tostring(b8))
        end
    end)
    task.delay(8, function()
        local c8, d8 = pcall(FarmHub.watchDone)
        if not c8 then
            App.log(1, "ERROR", "portal count: " .. tostring(d8))
        end
    end)
    while App.alive do
        if Config.master and not Brain.holdLobby then
            if Brain.str.reequip then
                pcall(Strategy.reequip)
            end
            if Brain.buyStorage then
                local e8, f8 = pcall(FarmHub.buyStorage)
                if not e8 then
                    App.log(1, "ERROR", "unit storage: " .. tostring(f8))
                end
            end
            if Brain.buyOnce then
                local g8, h8 = pcall(FarmHub.buyOnce)
                if not g8 then
                    App.log(1, "ERROR", "shop item: " .. tostring(h8))
                end
            end
            if Brain.ownSwap and FarmHub.every("ownSwap", 60) then
                local i8, j8 = pcall(FarmHub.ownSwap)
                if not i8 then
                    App.log(1, "ERROR", "team change: " .. tostring(j8))
                end
            end
            if Brain.train.on then
                local k8, l8 = pcall(Training.home)
                if not k8 then
                    App.log(1, "ERROR", "training: " .. tostring(l8))
                end
            end
            if FarmHub.every("live", 60) then
                pcall(FarmHub.refreshLive)
            end
            if FarmHub.every("huntShop", 3600) then
                pcall(Hunt.shopLook)
            end
            if FarmHub.every("hive", 60) then
                pcall(Reports.sendHive)
            end
            if FarmHub.every("hiveUnit", 60) then
                task.delay(20, function()
                    pcall(Reports.sendUnit)
                end)
            end
            if # Brain.studyQ > 0 and FarmHub.every("hiveStudy", 15) then
                task.spawn(function()
                    pcall(Reports.sendStudy, 3)
                end)
            end
            if Config.useHive and FarmHub.every("hiveGet", 6 * 3600) then
                task.spawn(function()
                    local m8, n8 = pcall(Reports.hiveFetch)
                    if not m8 then
                        App.log(1, "ERROR", "local learning read: " .. tostring(n8))
                    end
                end)
            end
            if FarmHub.every("rewards", 45) then
                local o8, p8 = pcall(FarmHub.rewards)
                if not o8 then
                    App.log(1, "ERROR", "rewards: " .. tostring(p8))
                end
            end
            if FarmHub.every("gold", 600) then
                local q8, r8 = pcall(FarmHub.goldShop)
                if not q8 then
                    App.log(1, "ERROR", "gold shop: " .. tostring(r8))
                end
            end
            if Config.snipeOn and (FarmHub.every("snipe", 600) or (FarmHub.snipeStale() and FarmHub.every("snipeStale", 30))) then
                local s8, t8 = pcall(FarmHub.bannerSnipe)
                if not s8 then
                    App.log(1, "ERROR", "Banner Snipe: " .. tostring(t8))
                end
            end
            if FarmHub.every("summon", 30) then
                local u8, v8 = pcall(FarmHub.summon)
                if not u8 then
                    App.log(1, "ERROR", "summon: " .. tostring(v8))
                end
                local w8, x8 = pcall(FarmHub.eventShop)
                if not w8 then
                    App.log(1, "ERROR", "event shop: " .. tostring(x8))
                end
            end
            if FarmHub.every("codes", 21600) then
                local y8, z8 = pcall(FarmHub.codes)
                if not y8 then
                    App.log(1, "ERROR", "codes: " .. tostring(z8))
                end
            end
            if FarmHub.every("rshopCache", 1800) then
                local A8, B8 = App.request("rshopList", "request_current_raidshop_shop")
                if A8 and type(B8) == "table" then
                    table.clear(Brain.raidShop)
                    for C8, D8 in pairs(B8) do
                        if type(D8) == "table" and D8.id and D8.item_cost then
                            Brain.raidShop [C8] = {
                                id = D8.id,
                                costItem = D8.item_cost.item_id,
                                cost = tonumber(D8.item_cost.amount) or 0,
                                stock = D8.stock
                            }
                        end
                    end
                end
            end
            if FarmHub.every("lbInfo", 1800) then
                local E8 = Units.equipped() [1]
                if E8 then
                    local F8, G8 = App.request("lbInfo", "request_fusion_information", E8.uuid)
                    if F8 and type(G8) == "table" then
                        Brain.lb = {
                            requirement = G8.requirement,
                            allowed = G8.allowed
                        }
                    end
                end
            end
            if FarmHub.every("goals", 300) then
                local H8, I8 = pcall(Adventure.refresh)
                if not H8 then
                    App.log(1, "ERROR", "goals: " .. tostring(I8))
                else
                    local J8, K8 = pcall(Adventure.buyShopGoals)
                    if J8 and K8 then
                        pcall(Adventure.refresh)
                    end
                    local L8, M8 = pcall(FarmHub.smartEvolve)
                    if not L8 then
                        App.log(1, "ERROR", "smart evolve: " .. tostring(M8))
                    end
                end
                Modes.lastScored = nil
            end
            if FarmHub.every("picks", 20) then
                for N8, O8 in ipairs({
                    FarmHub.focusNextUp,
                    FarmHub.autoEvolve,
                    FarmHub.autoFuse,
                    FarmHub.autoFuseXp,
                    Hunt.skinTick
                }) do
                    local P8, Q8 = pcall(O8)
                    if not P8 then
                        App.log(1, "ERROR", "lobby picks: " .. tostring(Q8))
                    end
                end
                local R8, S8 = pcall(Strategy.tick)
                if not R8 then
                    App.log(1, "ERROR", "team: " .. tostring(S8))
                end
            end
            local T8, U8 = pcall(Strategy.finishWork)
            if not T8 then
                App.log(1, "ERROR", "team work: " .. tostring(U8))
            end
            local V8 = Modes.lastScored and Modes.lastScored [1]
            if FarmHub.every("pick", 5) or not V8 then
                local W8, X8 = pcall(Modes.pick)
                if not W8 then
                    App.log(1, "ERROR", "ranking: " .. tostring(X8))
                    X8 = nil
                end
                V8 = X8
            end
            if Config.sim and Config.simTeams and (FarmHub.planNow or not (Config.autoTeam and Config.play)) and FarmHub.every("simTeam", 600) then
                FarmHub.planNow = nil
                task.spawn(function()
                    for Y8, Z8 in ipairs(Modes.lastScored or {
                    }) do
                        if Z8.kind == "daily" or Z8.kind == "challenge" or Z8.first then
                            local _8, a9 = pcall(Simulator.plan, Z8, true)
                            if not _8 then
                                App.log(1, "ERROR", "planner: " .. tostring(a9))
                            end
                            break
                        end
                    end
                end)
            end
            if Config.trainTakedowns and Config.sim and Modes.lastScored and FarmHub.every("trainScan", 600) then
                FarmHub.scanning = Utils.now()
                task.spawn(function()
                    local b9, c9 = pcall(Training.scan)
                    if not b9 then
                        App.log(1, "ERROR", "training planner: " .. tostring(c9))
                    end
                    FarmHub.scanning = nil
                    Modes.lastScored = nil
                end)
                V8 = nil
            end
            if FarmHub.scanning and Utils.now() - FarmHub.scanning < 30 then
                V8 = nil
            end
            if Config.play and Config.sim and V8 and not FarmHub.simFresh(V8) and V8.kind ~= "event" and V8.kind ~= "dungeon" then
                App.status("Mode", "simulating " .. V8.label .. " with your team…")
                local d9, e9 = pcall(Simulator.plan, V8, false)
                if not d9 then
                    App.log(1, "ERROR", "sim: " .. tostring(e9))
                end
                if not (d9 and e9) then
                    Brain.simRes [V8.key] = {
                        none = true,
                        sig = Modes.teamSig(),
                        at = os.time()
                    }
                end
                Modes.lastScored = nil
                V8 = nil
            end
            if Config.play and V8 and Utils.now() - V7 > 8 and not (App.req.back.launch and Utils.now() < App.req.back.launch) then
                local f9 = LocalPlayer:FindFirstChild("AlreadyInLobby")
                if Brain.trial then
                    local g9, h9 = pcall(Modes.trialTeam)
                    if not g9 then
                        App.log(1, "ERROR", "trial team: " .. tostring(h9))
                        Brain.trial = nil
                    end
                    if g9 and h9 and not (f9 and f9.Value) then
                        pcall(FarmHub.launch, V8)
                    end
                else
                    if Config.autoTeam or (Brain.testTeam and (Brain.testTeam.left or 0) > 0 and Brain.testTeam.key == V8.key) then
                        pcall(FarmHub.teamFor, V8)
                    end
                    local i9, j9 = pcall(Training.apply, V8)
                    if not i9 then
                        App.log(1, "ERROR", "training: " .. tostring(j9))
                        pcall(Training.home)
                    end
                    local k9, l9 = pcall(Hunt.charmTick, V8)
                    if not k9 then
                        App.log(1, "ERROR", "charm: " .. tostring(l9))
                    end
                    if not (f9 and f9.Value) then
                        pcall(FarmHub.launch, V8)
                    end
                end
            elseif not Config.play then
                App.status("Mode", "Auto Play is off")
            elseif not V8 then
                App.status("Mode", Modes.onlyOn() and string.format("only %s is on and none can be played right now: waiting", Modes.onlyText()) or "nothing to play (all modes off or resting)")
            end
        else
            App.status("Mode", Brain.holdLobby and ("held in the lobby: " .. tostring(Brain.holdLobby.why)) or "paused")
            if not Config.master or Brain.holdLobby then
                if # Brain.studyQ > 0 and FarmHub.every("hiveStudy", 15) then
                    task.spawn(function()
                        pcall(Reports.sendStudy, 3)
                    end)
                end
                if FarmHub.every("summon", 30) then
                    local m9, n9 = pcall(FarmHub.summon)
                    if not m9 then
                        App.log(1, "ERROR", "summon: " .. tostring(n9))
                    end
                end
                if Config.snipeOn and (FarmHub.every("snipe", 600) or (FarmHub.snipeStale() and FarmHub.every("snipeStale", 30))) then
                    local o9, p9 = pcall(FarmHub.bannerSnipe)
                    if not o9 then
                        App.log(1, "ERROR", "Banner Snipe: " .. tostring(p9))
                    end
                end
                if FarmHub.every("picks", 20) then
                    for q9, r9 in ipairs({
                        FarmHub.autoFuse,
                        FarmHub.autoFuseXp,
                        Hunt.skinTick
                    }) do
                        local s9, t9 = pcall(r9)
                        if not s9 then
                            App.log(1, "ERROR", "lobby picks: " .. tostring(t9))
                        end
                    end
                end
            end
        end
        task.wait(2)
    end
end

function Economy.upgradeGain(u9, v9, w9, x9, y9, z9)
    local A9, B9 = v9 [w9], v9 [w9 + 1]
    local C9 = (A9.cd > 0 and A9.damage / A9.cd or 0)
    local D9 = (B9.cd > 0 and B9.damage / B9.cd or 0) * Units.aoe(B9.atk, B9.range) / math.max(0.3, Units.aoe(A9.atk, A9.range))
    local E9 = C9 > 0 and u9 * (D9 / C9 - 1) or (z9 or 0)
    local F9 = v9 [w9 + 2]
    if F9 and w9 + 1 < v9.max and F9.cd > 0 and B9.cd > 0 and C9 > 0 then
        local G9 = u9 * ((F9.damage / F9.cd) / C9 - 1)
        local H9 = x9 + F9.cost * y9
        if G9 / H9 > E9 / x9 then
            E9 = E9 + (G9 / H9 * x9 - E9) * 0.5
        end
    end
    local I9 = (B9.range or 0) > (A9.range or 0) and (1 + ((B9.range - A9.range) / math.max(1, A9.range))) or 1
    return math.max(0, E9) * I9
end

function Economy.dpsFor(J9, K9)
    if K9 <= 0 then
        return 0
    end
    local L9 = {
    }
    for M9, N9 in ipairs(J9) do
        if not N9.farm and N9.gain > 0 then
            table.insert(L9, N9)
        end
    end
    table.sort(L9, function(O9, P9)
        return O9.gain / O9.cost > P9.gain / P9.cost
    end)
    local Q9, R9 = 0, 0
    for S9, T9 in ipairs(L9) do
        if K9 <= 0 then
            break
        end
        R9 = T9.gain / T9.cost
        local U9 = math.min(1, K9 / T9.cost)
        Q9 = Q9 + T9.gain * U9
        K9 = K9 - T9.cost * U9
    end
    return Q9 + math.max(0, K9) * R9 * 0.7
end

function Economy.shieldDps(V9, W9, X9, Y9, Z9, _9, aab)
    if (Y9 or 0) <= 0 or (V9 or 0) <= 0 or (Z9 or 0) <= 0 then
        return V9 or 0
    end
    W9, X9, _9 = math.max(0.3, W9 or 2), math.max(1, X9 or 1), _9 or 1
    local bab = V9 * _9 * W9 / X9
    return Z9 * X9 / ((Y9 / math.max(1, aab or 1) + math.max(1, Z9 / bab)) * W9) / _9
end

function Economy.shieldGain(cab, dab, eab, fab, gab, hab, iab, jab)
    local kab, lab = Units.attackInfo(dab.atk, dab.range), Units.attackInfo(fab.atk, fab.range)
    local mab = Economy.shieldDps(cab, (tonumber(dab.cd) or 2) * (iab or 1), kab.n, gab, hab, jab, kab.hits)
    local nab = Economy.shieldDps(eab, (tonumber(fab.cd) or 2) * (iab or 1), lab.n, gab, hab, jab, lab.hits)
    local oab = math.max(0, ((tonumber(fab.range) or 0) - (tonumber(dab.range) or 0)) / math.max(1, tonumber(dab.range) or 1))
    return math.max(0, nab - mab) + mab * oab
end

function Economy.shieldWork(pab, qab, rab, sab, tab, uab, vab, wab, xab)
    if (sab or 0) <= 0 then
        return 0
    end
    local yab = 3 * sab * (tab or 1) / math.max(1, uab or 20)
    if (rab or 0) >= yab then
        return 0
    end
    return math.max(1, pab or 1) * math.max(1, xab or 1) / math.max(0.3, qab or 2) * math.min(vab or 0, wab or 0)
end

function Economy.holdGain(zab, Aab, Bab, Cab)
    if not zab or (Aab or 0) <= 0 then
        return 0
    end
    local Dab, Eab = tonumber(zab.stun) or 0, tonumber(zab.slowTime) or 0
    if Dab <= 0 and Eab <= 0 then
        return 0
    end
    local Fab, Gab = Dab > 0 and Dab or Eab, Dab > 0 and 1 or (tonumber(zab.slowPct) or 0.3)
    local Hab = Gab * Fab / (Fab + (tonumber(zab.ccCd) or 8))
    local Iab = Hab / math.max(0.1, 1 - Hab)
    return Aab * Iab * Utils.clamp(Bab or 0.5, 0, 1) * math.min(1, (tonumber(zab.n) or 1) / 2) / (1 + (Cab or 0))
end

function Economy.bleedGain(Jab, Kab, Lab, Mab)
    if (Jab or 0) <= 0 then
        return 0
    end
    local Nab = Kab or 0
    for Oab, Pab in ipairs(Lab or {
    }) do
        Nab = math.max(Nab, (tonumber(Pab.hp) or 0) * 0.5)
    end
    return Jab * Nab * (Mab and 0.5 or 1)
end

function Economy.bleedShare(Qab, Rab, Sab, Uab)
    if Qab <= 0 or not Rab then
        return 0
    end
    if Uab then
        return Rab == 0 and Qab or Qab / (Rab + 1)
    end
    return Sab < Rab and Qab / (Rab - Sab) or 0
end

function Economy.keepsUp(Vab, Wab, Xab, Yab, Zab)
    local _ab = Vab.coming
    if not (_ab and # _ab > 0 and Vab.waveSec) then
        return true
    end
    local abb = Vab.eff or 1
    local bbb = Vab.money - Xab
    local cbb = (Vab.teamDps or 0) * (Vab.shieldK or 1) + (Yab or 0) * abb + Economy.dpsFor(Wab, math.max(0, bbb)) * abb
    local dbb = (Vab.farmNow or 0) + (Zab or 0)
    local ebb = (Vab.roadSec or 130) * Utils.clamp(Vab.cover or 0.6, 0.1, 1)
    local fbb = Vab.hpAlive or 0
    for gbb, hbb in ipairs(_ab) do
        fbb = math.max(0, fbb + hbb.hp - cbb * Vab.waveSec)
        local ibb = cbb * ebb
        if fbb > ibb then
            return false, gbb, ibb / math.max(1, fbb)
        end
        if gbb < # _ab then
            cbb = cbb + Economy.dpsFor(Wab, (hbb.reward or 0) + dbb) * abb * (0.85 ^ gbb)
        end
    end
    return true
end

function Economy.decide(jbb, kbb)
    local lbb = Utils.clamp(kbb.cover or 0.6, 0.1, 1)
    local mbb = math.max(Config.clearSec, 0.7 * (kbb.roadSec or 50) * lbb)
    local nbb = (kbb.clearSec or 0) > mbb
    kbb.piling = kbb.piling and nbb
    local obb = kbb.attackers > 0 and kbb.pressure < math.min(Config.safeReach, lbb * 0.75) and not kbb.piling and not nbb
    local pbb = kbb.pressure >= math.min(Config.dangerReach, lbb * 0.9) or (kbb.piling and kbb.enemies >= 18)
    local qbb, rbb
    for sbb, tbb in ipairs(jbb) do
        if tbb.farm then
            if Config.farmUnits and tbb.gain > 0 then
                tbb.payback = tbb.cost / tbb.gain
                if kbb.left - 1 >= tbb.payback + Config.farmSpare and (not qbb or tbb.payback < qbb.payback) then
                    qbb = tbb
                end
            end
        else
            tbb.ratio = tbb.gain / math.max(1, tbb.cost)
            if not rbb or tbb.ratio > rbb.ratio then
                rbb = tbb
            end
        end
    end
    if kbb.leak and kbb.attackers > 0 then
        local ubb
        for vbb, wbb in ipairs(jbb) do
            local xbb = not kbb.airLeak or (wbb.e and Match.cardAir(wbb.e.id))
            if wbb.place and not wbb.farm and xbb and wbb.cost <= kbb.money and not (wbb.e and Units.allyBuff(wbb.e.id)) and (not ubb or wbb.gain > ubb.gain) then
                ubb = wbb
            end
        end
        if ubb then
            return ubb, string.format("an enemy got past all your units (%d%% of the road): a unit in its way", math.floor(kbb.leak * 100))
        end
    end
    local ybb = kbb.future < kbb.wantLeft * 1.1
    local zbb, Abb, Bbb = true, nil, nil
    if qbb then
        zbb, Abb, Bbb = Economy.keepsUp(kbb, jbb, qbb.cost, 0, qbb.gain)
    end
    local Cbb = kbb.coming and not Economy.keepsUp(kbb, jbb, 0, 0, 0)
    local Dbb = false
    if Match.random and qbb and not pbb and kbb.attackers >= 2 and qbb.payback <= kbb.left / 3 then
        local Ebb = 0
        for Fbb, Gbb in ipairs(Match.mine or {
        }) do
            if Units.isFarm(Gbb._stats.id.Value) then
                Ebb = Ebb + 1
            end
        end
        Dbb = not qbb.place or Ebb < 4
    end
    if Cbb and kbb.attackers > 0 then
        pbb = true
    end
    local Hbb = math.max(1, kbb.incomeRate or 20)
    local Ibb = kbb.waveSec or 20
    local function Jbb(Kbb, Lbb, Mbb)
        local Nbb = math.max(0, (Kbb.cost - kbb.money) / Hbb)
        local Obb = Kbb.gain * math.max(0, Mbb - Nbb)
        if Lbb then
            local Pbb = math.max(0, kbb.money - Kbb.cost)
            local Qbb = Nbb + math.max(0, (Lbb.cost - Pbb) / Hbb)
            Obb = Obb + Lbb.gain * math.max(0, Mbb - Qbb)
        end
        return Obb
    end
    local Rbb, Sbb
    if kbb.attackers == 0 and rbb then
        local Tbb = 4 * Ibb
        local Ubb, Vbb
        for Wbb, Xbb in ipairs(jbb) do
            if Xbb.place and not Xbb.farm then
                local Ybb = Jbb(Xbb, nil, Tbb)
                if not Vbb or Ybb > Vbb then
                    Ubb, Vbb = Xbb, Ybb
                end
            end
        end
        Rbb, Sbb = Ubb or rbb, "opening: the unit that does the most damage over the first waves"
    elseif qbb and obb and ybb and not pbb and zbb then
        Rbb = qbb
        Sbb = string.format("farm pays back in %.1f waves (%d left) and the defense still keeps up with the next %d waves", qbb.payback, kbb.left, kbb.coming and # kbb.coming or 0)
    elseif Dbb then
        Rbb = qbb
        Sbb = string.format("farm pays back in %.1f waves (%d left) and nothing is close to the base", qbb.payback, kbb.left)
    elseif rbb then
        Rbb = rbb
        if Cbb then
            Sbb = string.format("the next waves bring more HP than your units can kill: damage now")
        elseif pbb then
            Sbb = string.format("enemies reach %d%% of the road (your units cover %d%%): damage now", math.floor(kbb.pressure * 100), math.floor(lbb * 100))
        elseif qbb and not zbb then
            Sbb = string.format("defense first: after that farm buy, wave +%d would only be %d%% covered", Abb or 1, math.floor((Bbb or 0) * 100))
        elseif qbb and nbb then
            Sbb = string.format("defense first: killing what's alive takes %ds (farm only under %ds)", math.min(999, math.floor(kbb.clearSec)), math.floor(mbb))
        elseif qbb and kbb.piling then
            Sbb = string.format("defense first: %d enemies piling up", kbb.enemies)
        elseif qbb and not obb then
            Sbb = "defense first (enemies get too far to farm)"
        elseif qbb and not ybb then
            Sbb = "farm not needed: coming yen already covers every upgrade"
        else
            Sbb = "most damage per yen"
        end
    end
    if not Rbb then
        return nil
    end
    if Rbb.cost > kbb.money then
        local Zbb
        if not Rbb.farm then
            local _bb = ((kbb.pressure or 0) >= 0.95 and 0.5 or pbb and 2 or 6) * Ibb
            local acb
            for bcb, ccb in ipairs(jbb) do
                if not ccb.farm and ccb ~= Rbb and ccb.cost <= kbb.money then
                    local dcb = Jbb(ccb, Rbb, _bb)
                    local ecb = Jbb(Rbb, ccb, _bb)
                    if dcb > ecb and (not acb or dcb > acb) then
                        Zbb, acb = ccb, dcb
                    end
                end
            end
        end
        if not Zbb then
            return nil, nil, string.format("saving ¥%s for: %s (≈%ds at ¥%d/s) — %s", Utils.fmt(Rbb.cost), Rbb.what or "?", math.ceil((Rbb.cost - kbb.money) / Hbb), math.floor(Hbb), Sbb)
        end
        Rbb, Sbb = Zbb, Sbb .. " (worth buying while saving)"
    end
    return Rbb, Sbb
end
Simulator.DT = 1
Simulator.BINS = 20
Simulator.PRIOR = {
    waveSec = 20,
    walk = 0.0054,
    spawnGap = 1,
    baseHp = 100,
    baseRel = 0.3,
    start = 600,
    eff = 0.7,
    waveTimer = 60,
    skipDelay = 5,
    voteAt = 30,
    voteBase = 2,
    votePer = 1.9
}

function Simulator.voteSec(fcb, gcb)
    local hcb = fcb.voteWave and tonumber(fcb.voteWave [tostring(gcb)])
    if hcb then
        return hcb
    end
    if gcb <= 2 then
        return 5
    elseif gcb <= 5 then
        return 10
    end
    return fcb.voteAt
end
Simulator.LAND_CAP = 1.3

function Simulator.autoskip()
    local icb, jcb = pcall(function()
        return LocalPlayer._settings.autoskip_waves.Value
    end)
    if icb and type(jcb) == "boolean" then
        return jcb
    end
    return true
end

function Simulator.cal(kcb)
    local lcb = Brain.simCal [kcb]
    if not lcb then
        lcb = {
        }
        Brain.simCal [kcb] = lcb
    end
    return lcb
end

function Simulator.effFor(mcb)
    local ncb, ocb = 0, 0
    for pcb, qcb in pairs(Brain.simCal) do
        local rcb, scb = tonumber(qcb.eff), tonumber(qcb.n) or 0
        if rcb and scb > 0 then
            ncb = ncb + rcb * scb
            ocb = ocb + scb
        end
    end
    local tcb = ocb > 0 and ncb / ocb or Simulator.PRIOR.eff
    local ucb, vcb = tonumber(mcb and mcb.eff), tonumber(mcb and mcb.n) or 0
    if not ucb then
        return tcb
    end
    return (ucb * vcb + tcb * 3) / (vcb + 3)
end
Simulator.LD_FIELDS = {
    "id",
    "map",
    "waves",
    "world",
    "story_world_rank",
    "story_level_rank",
    "_gamemode",
    "_OVERRIDE_GAMEMODE",
    "_difficulty",
    "_challenge",
    "infinite",
    "_use_max",
    "_override_infinite_bound_waves",
    "_override_infinite_boss_interval",
    "_override_multiplayer_diff_scale",
    "_no_multiplayer_scale",
    "_raid_multiplayer_scale",
    "portal_group",
    "_infinite_bound_level",
    "_lobby_difficulty_scale",
    "_location_name",
    "name",
    "boss",
    "_world_diff_scale_multiplier",
    "_portal_lanes"
}

function Simulator.unbound(wcb)
    return not tonumber(wcb._override_infinite_bound_waves) and not wcb._infinite_bound_level
end

function Simulator.boundEnd(xcb, ycb, zcb)
    if not (xcb and xcb._infinite_bound_level) or tonumber(xcb._override_infinite_bound_waves) then
        return nil
    end
    local Acb = zcb and Brain.simCal [zcb]
    if type(Acb) == "table" and (tonumber(Acb.lastWave) or 0) > 15 then
        return nil
    end
    return (ycb or 0) > 0 and math.min(ycb, 15) or 15
end

function Simulator.slim(Bcb)
    local Ccb = {
    }
    for Dcb, Ecb in ipairs(Simulator.LD_FIELDS) do
        local Fcb = Bcb [Ecb]
        if type(Fcb) ~= "table" and type(Fcb) ~= "function" then
            Ccb [Ecb] = Fcb
        end
    end
    if type(Bcb._override_waves) == "table" then
        Ccb._override_waves = {
            infinite = Bcb._override_waves.infinite,
            template = Bcb._override_waves.template
        }
    end
    if type(Bcb._dungeon) == "table" then
        Ccb._dungeon = {
            depth = Bcb._dungeon.depth,
            choice_str = Bcb._dungeon.choice_str
        }
    end
    if type(Bcb._override_infinite_final_boss_wave) == "table" then
        Ccb._final = {
            wave = Bcb._override_infinite_final_boss_wave.wave,
            cfg = Bcb._override_infinite_final_boss_wave.final_boss_config_id
        }
    end
    if type(Bcb._override_infinite_boss_interval__skip_waves) == "table" then
        Ccb._skip = {
        }
        for Gcb in pairs(Bcb._override_infinite_boss_interval__skip_waves) do
            Ccb._skip [tostring(Gcb)] = true
        end
    end
    return Ccb
end
local function Hcb(Icb, ...)
    local Jcb, Kcb = pcall(Icb, ...)
    return Jcb and tonumber(Kcb) or nil
end

function Simulator.info(Lcb, Mcb, Ncb, Ocb)
    local Pcb = Brain.simCal [Mcb] or {
    }
    local Qcb = Lcb._OVERRIDE_GAMEMODE or Lcb._gamemode or (Lcb.infinite and "infinite") or "story"
    local Rcb = Lcb.id == "__DAILY_CHALLENGE"
    local Scb = (Brain.live.event and Lcb.id == Brain.live.event.level) and true or false
    local Tcb = {
        _is_daily_challenge = Rcb or nil,
        _is_event_challenge = Scb or nil,
        _use_max = Lcb._use_max,
        world = Lcb.world,
        id = Lcb.id,
        _override_multiplayer_diff_scale = Lcb._override_multiplayer_diff_scale,
        _no_multiplayer_scale = Lcb._no_multiplayer_scale,
        portal_group = Lcb.portal_group,
        _raid_multiplayer_scale = Lcb._raid_multiplayer_scale
    }
    local Ucb = tonumber(Lcb.story_world_rank) or # Utils.list(Core.WLO.WORLD_ORDER)
    local Vcb = (Qcb == "infinite") and "challenge" or Qcb
    local Wcb = Hcb(Core.LU.calculate_world_diff_scale, Ucb, Vcb, nil, Lcb.map, Tcb) or 1
    local Xcb = Hcb(Core.LU.calculate_level_diff_scale, tonumber(Lcb.story_level_rank) or 6, (Qcb == "infinite" or Qcb == "raid") and Qcb or (Qcb == "challenge" and "challenge" or "story"), Tcb) or 1
    local Ycb = Hcb(Core.LU.calculate_multiplayer_diff_scale, Qcb, 1, Tcb) or 1
    local Zcb = Lcb._override_waves
    local _cb = Core.Waves [(Zcb and Zcb.template) or Lcb.waves or Lcb.id]
    local adb = _cb
    if _cb and _cb.template and Core.Waves [_cb.template] then
        adb = Core.Waves [_cb.template]
    end
    local bdb = (Zcb and Zcb.infinite) or Lcb.infinite or (_cb and _cb.infinite) or false
    local cdb = (_cb and _cb.initial_unit_configs) or (adb and adb.initial_unit_configs) or {
    }
    if bdb and Lcb._infinite_bound_level then
        local ddb = false
        for edb, fdb in pairs(cdb) do
            if type(fdb) == "table" and fdb.spawn_tier_normal then
                ddb = true
            end
        end
        if not ddb then
            bdb = false
        end
    end
    local gdb = Utils.list((_cb and (_cb.override_waves or _cb.waves)) or (adb and adb.waves))
    local hdb = Ncb or Lcb._challenge
    local idb = Core.CAR.challenges and Core.CAR.challenges [hdb or ""] or nil
    local jdb, kdb = 0, 0
    for ldb, mdb in pairs(idb and idb.enemy_buffs or {
    }) do
        if type(mdb) == "table" and mdb.name == "damage_reduction" then
            jdb = jdb + (tonumber(mdb.params and mdb.params.reduction) or 0)
        end
        if type(mdb) == "table" and mdb.name == "healing" then
            kdb = kdb + (tonumber(mdb.params and mdb.params.percent) or 0)
        end
    end
    local ndb = Lcb._difficulty or ((bdb and not Lcb._dungeon and not Lcb._infinite_bound_level) and "Hard") or "Normal"
    local odb = ((not bdb) or (not Lcb._dungeon and not Lcb._infinite_bound_level)) and (Core.GS.DIFFICULTY_HEALTH_SCALES and Core.GS.DIFFICULTY_HEALTH_SCALES [ndb]) or 1
    local pdb = Wcb * Xcb * Ycb * odb * (idb and tonumber(idb.enemy_health_scale) or 1) * (tonumber(Lcb._lobby_difficulty_scale) or 1) * (tonumber(Lcb._world_diff_scale_multiplier) or 1)
    local qdb = Hcb(Core.LU.calculate_world_resource_scale, Ucb, Vcb) or 2.6
    local rdb = (_cb and tonumber(_cb.wave_max_time)) or (adb and tonumber(adb.wave_max_time)) or Simulator.PRIOR.waveTimer
    local sdb, tdb = Lcb.map, (Brain.maps [Lcb.map] or {
    }).lanes
    local udb = tonumber(Lcb._portal_lanes)
    if udb and udb >= 1 and type(tdb) == "table" and # tdb > udb then
        sdb = tostring(Lcb.map) .. "~" .. udb
        local vdb = {
        }
        for wdb = 1, udb do
            vdb [wdb] = tdb [wdb]
        end
        tdb = # vdb >= 2 and vdb or nil
    end
    local zdb = {
        key = Mcb,
        ld = Lcb,
        map = sdb,
        infinite = bdb and true or false,
        list = gdb,
        configs = cdb,
        gm = Qcb,
        total = (type(Lcb._dungeon) == "table" and 15) or tonumber(Lcb._override_infinite_bound_waves) or Simulator.boundEnd(Lcb,
        # gdb,
        Mcb) or (((not bdb) or Lcb._infinite_bound_level) and # gdb > 0 and # gdb) or (Lcb._infinite_bound_level and 15) or (bdb and Simulator.INF_CAP) or 30,
        hpRaw = pdb,
        hpScale = pdb * (tonumber(Pcb.hpCal) or (function()
            local xdb,
            ydb = pcall(Reports.hiveHp,
            Mcb)
            return xdb and ydb or nil
        end)() or 1),
        speedScale = idb and tonumber(idb.enemy_speed_scale) or 1,
        costScale = idb and tonumber(idb.player_cost_scale) or 1,
        rangeScale = idb and tonumber(idb.player_range_scale) or 1,
        red = math.min(0.75,
        jdb),
        regen = kdb,
        shield = idb and tonumber(idb.enemy_additional_shield) or 0,
        flyChance = hdb == "flying_enemies" and 1 or 0,
        armorAll = hdb == "armored_enemies" or nil,
        bounty = qdb * (tonumber(Pcb.bountyCal) or 1),
        payBase = qdb,
        pay = qdb * (tonumber(Pcb.yenCal) or 1),
        waveSec = tonumber(Pcb.waveSec) or Simulator.PRIOR.waveSec,
        walk = Simulator.mapWalk(sdb) or Simulator.mapWalk(Lcb.map) or tonumber(Pcb.walk) or Simulator.PRIOR.walk,
        waveTimer = rdb,
        skipDelay = tonumber(Pcb.skipDelay) or Simulator.PRIOR.skipDelay,
        autoskip = Simulator.autoskip(),
        voteAt = tonumber(Pcb.voteAt) or rdb / 2,
        votePer = tonumber(Pcb.votePer) or Simulator.PRIOR.votePer,
        eff = Simulator.effFor(Pcb),
        voteWave = type(Pcb.voteWave) == "table" and Pcb.voteWave or nil,
        spawnGap = tonumber(Pcb.spawnGap) or Simulator.PRIOR.spawnGap,
        baseHp = tonumber(Pcb.baseHp) or (_cb and tonumber(_cb.base_health)) or (adb and tonumber(adb.base_health)) or Simulator.PRIOR.baseHp,
        baseRel = tonumber(Pcb.baseRel) or Simulator.PRIOR.baseRel,
        timerAt = type(Pcb.timerAt) == "table" and Pcb.timerAt or {
        },
        start = tonumber(Pcb.start) or (Lcb._dungeon and 2500) or (_cb and tonumber(_cb.initial_resource)) or (adb and tonumber(adb.initial_resource)) or Simulator.PRIOR.start,
        mod = Ocb,
        cal = Pcb,
        skinSet = Hunt.skinSet(Lcb),
        laneList = tdb,
        bossEvery = tonumber(Lcb._override_infinite_boss_interval) or 10,
        final = Lcb._final,
        skip = Lcb._skip or {
        },
        zone = type(Lcb._dungeon) == "table" and Config.killZone ~= false
    }
    zdb.cfgById = {
    }
    for Adb, Bdb in pairs(cdb) do
        if type(Bdb) == "table" and Bdb.unit_id then
            zdb.cfgById [Bdb.unit_id] = Adb
            local Cdb = Core.Units [Bdb.unit_id]
            if Simulator.flies(Cdb) then
                zdb.mapFly = true
            end
            local Ddb = type(Cdb) == "table" and type(Cdb.enemy_modifiers) == "table" and Cdb.enemy_modifiers or {
            }
            if Ddb.Armor or Ddb.Ice or zdb.armorAll then
                zdb.mapMods = true
            end
        end
    end
    if Hunt.is(Lcb.id) then
        Simulator.applyFx(zdb, Hunt.fx(Hunt.weatherNow()))
    end
    local Edb, Fdb = pcall(Hunt.charmDmg, Lcb)
    if Edb and (tonumber(Fdb) or 0) > 0 then
        if not zdb.fx then
            Simulator.applyFx(zdb, Hunt.fx("clear"))
        end
        zdb.fx.dmg = zdb.fx.dmg * (1 + Fdb)
    end
    return zdb
end

function Simulator.applyFx(Gdb, Hdb)
    if not Hdb then
        return Gdb
    end
    Gdb.fx = Hdb
    Gdb.rangeScale = Gdb.rangeScale * Hdb.range
    Gdb.costScale = Gdb.costScale * Hdb.cost
    Gdb.speedScale = Gdb.speedScale * Hdb.speed
    Gdb.regen = (Gdb.regen or 0) + Hdb.regen
    Gdb.shield = (Gdb.shield or 0) + (Hdb.shield or 0)
    Gdb.flyChance = (Gdb.flyChance or 0) + (Hdb.fly or 0)
    Gdb.noCC, Gdb.shroud = Hdb.noCC, Hdb.shroud
    if (Hdb.ice or 0) > 0 then
        Gdb.iceShare, Gdb.mapMods = Hdb.ice, true
    end
    Gdb.hpRaw, Gdb.hpScale = Gdb.hpRaw * Hdb.hp, Gdb.hpScale * Hdb.hp
    return Gdb
end

function Simulator.fxDps(Idb, Jdb)
    local Kdb = Idb.fx
    if not Kdb then
        return 1
    end
    local Ldb, Mdb = Units.types(Jdb)
    local Ndb = Kdb.dmg / Kdb.cd * (1 + (Kdb.kinds [Mdb] or 0))
    if Mdb == "physical" and Kdb.crit > 0 then
        Ndb = Ndb * (1 + Kdb.crit * 0.5)
    end
    return Ndb
end

function Simulator.waveYen(Odb, Pdb, Qdb)
    local Rdb
    if Odb.infinite then
        Rdb = (Core.LU.Infinite and Core.LU.Infinite.initial_wave_template and Core.LU.Infinite.initial_wave_template.wave_reward) or 1000
    else
        Rdb = Odb.list [Pdb] and tonumber(Odb.list [Pdb].wave_reward) or 0
    end
    return Rdb * (Qdb or Odb.pay or 1)
end

function Simulator.waveScale(Sdb, Tdb, Udb)
    if Sdb.infinite then
        return Hcb(Core.LU.Infinite.infinite_diff_scale, Tdb, Sdb.ld.id) or 1
    end
    return Udb and tonumber(Udb.wave_diff_scale) or 1
end

function Simulator.baseStats(Vdb, Wdb)
    local Xdb = Vdb.configs [Wdb]
    if type(Xdb) ~= "table" then
        return nil
    end
    local Ydb = Xdb.override_stats and (Xdb.override_stats [1] or Xdb.override_stats ["1"]) or {
    }
    return tonumber(Ydb.health) or 20, tonumber(Ydb.speed) or 1, tonumber(Ydb.resource_reward) or 30
end

function Simulator.enemy(Zdb, _db, aeb, beb)
    local ceb, deb, eeb = Simulator.baseStats(Zdb, _db)
    if not ceb then
        return nil
    end
    ceb = ceb * Zdb.hpScale * Simulator.waveScale(Zdb, aeb, beb)
    local feb = Core.Units [Zdb.configs [_db].unit_id] or {
    }
    local geb = {
        hp = ceb,
        max = ceb,
        speed = deb * Zdb.speedScale,
        bounty = eeb * Zdb.bounty,
        boss = tostring(_db):find("boss") ~= nil,
        p = 0,
        sh = (tonumber(feb.shield) or 0) + (Zdb.shield or 0),
        fly = Simulator.flies(feb)
    }
    local heb = type(feb.enemy_modifiers) == "table" and feb.enemy_modifiers or {
    }
    geb.fire, geb.soar = heb.Fire and true or nil, heb.Soaring and true or nil
    geb.armor, geb.ice = (heb.Armor or Zdb.armorAll) and true or nil, heb.Ice and true or nil
    if not geb.ice and (Zdb.iceShare or 0) > 0 then
        if geb.boss then
            geb.iceAvg = Zdb.iceShare
        else
            Zdb.iceAcc = (Zdb.iceAcc or 0) + Zdb.iceShare
            if Zdb.iceAcc >= 1 then
                geb.ice, geb.iceKey, Zdb.iceAcc = true, "Ice@snow", Zdb.iceAcc - 1
            end
        end
    end
    Simulator.enemyTraits(geb, feb, ceb)
    return geb
end

function Simulator.modRead(ieb)
    if type(ieb) ~= "table" or type(ieb.r) ~= "table" or # ieb.r < 8 then
        return nil
    end
    local jeb = # ieb.r
    if ieb._n == jeb and ieb._last == ieb.r [jeb] and ieb._f ~= nil then
        return ieb._f
    end
    local keb = table.clone(ieb.r)
    table.sort(keb)
    local leb, meb, neb = keb [math.floor(jeb / 2) + 1], keb [math.floor(jeb / 4) + 1], keb [math.min(jeb, math.floor(jeb * 3 / 4) + 1)]
    ieb._n, ieb._last = jeb, ieb.r [jeb]
    ieb._f = (meb >= leb * 0.7 and neb <= leb * 1.4) and leb or false
    ieb.f = ieb._f or nil
    return ieb._f
end

function Simulator.modFactor(oeb)
    local peb = Simulator.modRead(Brain.enemyMods [oeb])
    if peb then
        return peb
    end
    local qeb = Reports.hive()
    local reb = qeb and type(qeb.enemyMods) == "table" and qeb.enemyMods [oeb]
    if type(reb) == "table" and tonumber(reb.f) and ((tonumber(reb.players) or 0) >= 2 or (tonumber(reb.pairs) or 0) >= 16) then
        return tonumber(reb.f)
    end
    return Simulator.MOD_GUESS [oeb] or 1
end
Simulator.MOD_GUESS = {
    ["Ice@snow"] = 1 / 3
}

function Simulator.modHit(seb, teb)
    local ueb = 1
    if seb.armor and teb.full then
        ueb = ueb * Simulator.modFactor("Armor")
    end
    if seb.ice and not teb.fireDmg then
        ueb = ueb * Simulator.modFactor(seb.iceKey or "Ice")
    end
    if seb.iceAvg and not teb.fireDmg then
        ueb = ueb / (1 - seb.iceAvg + seb.iceAvg / Simulator.modFactor("Ice@snow"))
    end
    return ueb
end

function Simulator.flies(veb)
    return type(veb) == "table" and ((type(veb.enemy_modifiers) == "table" and veb.enemy_modifiers.Flying) or (type(veb.passives) == "table" and veb.passives.Flying)) and true or false
end

function Simulator.enemyTraits(web, xeb, yeb)
    for zeb, Aeb in pairs(type(xeb.buffs) == "table" and xeb.buffs or {
    }) do
        if type(Aeb) == "table" and Aeb.name == "healing" and type(Aeb.params) == "table" then
            web.regen = (web.regen or 0) + (tonumber(Aeb.params.percent) or 0) / math.max(0.1, tonumber(Aeb.params.healing_rate) or 1)
        end
    end
    if type(xeb.barrier) == "table" and tonumber(xeb.barrier.health_ratio) then
        local Beb = 0
        for Ceb, Deb in pairs(type(xeb.barrier.buffs) == "table" and xeb.barrier.buffs or {
        }) do
            if type(Deb) == "table" and Deb.name == "damage_reduction" and type(Deb.params) == "table" then
                Beb = Beb + (tonumber(Deb.params.reduction) or 0)
            end
        end
        web.bar = yeb * tonumber(xeb.barrier.health_ratio) / math.max(0.1, 1 - Beb)
    end
    local Eeb = xeb.death_spawn
    if type(Eeb) == "table" and type(Eeb.units) == "table" then
        for Feb, Geb in pairs(Eeb.units) do
            if type(Geb) == "table" and tonumber(Geb.health_ratio) then
                web.split = {
                    n = tonumber(Eeb.amount) or 1,
                    ratio = tonumber(Geb.health_ratio),
                    unit = Geb.unit
                }
                break
            end
        end
    end
end

function Simulator.wave(Heb, Ieb, Jeb)
    local Keb = {
    }
    Heb.iceAcc = (Ieb * 0.6180339887) % 1
    if not Heb.infinite then
        local Leb = Heb.list [Ieb]
        if not Leb then
            return Keb, 0
        end
        for Meb, Neb in ipairs(Utils.list(Leb.wave)) do
            for Oeb = 1, tonumber(Neb.amount) or 1 do
                local Peb = Simulator.enemy(Heb, Neb.unit, Ieb, Leb)
                if Peb then
                    table.insert(Keb, Peb)
                end
            end
        end
    else
        local Qeb = Hcb(Core.LU.Infinite.infinite_amt_scale, Ieb, Heb.ld) or 10
        local Reb, Seb = {
        }, 0
        for Teb, Ueb in pairs(Heb.configs) do
            if type(Ueb) == "table" and Ueb.spawn_tier_normal then
                local Veb = Hcb(Core.LU.Infinite.infinite_get_normal_unit_chance, Ueb, Ieb) or 0
                if Veb > 0 then
                    table.insert(Reb, {
                        k = Teb,
                        c = Veb
                    })
                    Seb = Seb + Veb
                end
            end
        end
        table.sort(Reb, function(Web, Xeb)
            return Web.k < Xeb.k
        end)
        local Yeb, Zeb = math.floor(Qeb + 0.5), 0
        for _eb, afb in ipairs(Reb) do
            local bfb = (_eb == # Reb) and math.max(0, Yeb - Zeb) or math.floor(Yeb * afb.c / Seb + 0.5)
            for cfb = 1, bfb do
                local dfb = Simulator.enemy(Heb, afb.k, Ieb)
                if dfb then
                    table.insert(Keb, dfb)
                end
            end
            Zeb = Zeb + bfb
        end
        local efb = Heb.ld._infinite_bound_level and Ieb == Heb.total
        if efb then
            local ffb, gfb = {
            }, 0
            for hfb, ifb in pairs(Heb.configs) do
                if type(ifb) == "table" and tonumber(ifb.spawn_tier_boss) and (Hcb(Core.LU.Infinite.infinite_get_boss_unit_chance, ifb, Ieb) or 0) > 0 then
                    local jfb = Simulator.baseStats(Heb, hfb)
                    if jfb then
                        table.insert(ffb, {
                            k = hfb,
                            hp = jfb,
                            tier = tonumber(ifb.spawn_tier_boss)
                        })
                        gfb = gfb + jfb
                    end
                end
            end
            table.sort(ffb, function(kfb, lfb)
                return kfb.tier > lfb.tier
            end)
            local mfb = type(Heb.ld._dungeon) == "table" and (tonumber(Heb.ld._dungeon.depth) or 0) >= 20
            local nfb = ffb [1]
            if nfb and not mfb then
                local ofb = gfb / # ffb
                for pfb, qfb in ipairs(ffb) do
                    if math.abs(qfb.hp - ofb) < math.abs(nfb.hp - ofb) then
                        nfb = qfb
                    end
                end
            end
            if nfb then
                local rfb = Simulator.enemy(Heb, nfb.k, Ieb)
                if rfb then
                    rfb.boss = true
                    table.insert(Keb, rfb)
                end
            end
        elseif Ieb % Heb.bossEvery == 0 and not Heb.skip [tostring(Ieb)] then
            local sfb = math.max(1, math.min(6, math.floor(Ieb / Heb.bossEvery)))
            for tfb, ufb in pairs(Heb.configs) do
                if type(ufb) == "table" and tonumber(ufb.spawn_tier_boss) == sfb then
                    local vfb = Simulator.enemy(Heb, tfb, Ieb)
                    if vfb then
                        vfb.boss = true
                        table.insert(Keb, vfb)
                    end
                    break
                end
            end
        end
        if Heb.final and tonumber(Heb.final.wave) == Ieb and Heb.final.cfg then
            local wfb = Simulator.enemy(Heb, Heb.final.cfg, Ieb)
            if wfb then
                wfb.boss = true
                table.insert(Keb, wfb)
            end
        end
    end
    local xfb = Heb.fx and Heb.fx.starfall
    local yfb = xfb and Heb.cfgById and Heb.cfgById.star_golem_1
    if yfb and (tonumber(xfb.perWave) or 0) > 0 then
        if Ieb <= 1 then
            Heb.starAcc = 0
        end
        Heb.starAcc = (Heb.starAcc or 0) + xfb.perWave
        while Heb.starAcc >= 1 do
            local zfb = Simulator.enemy(Heb, yfb, Ieb)
            if zfb then
                local Afb = tonumber(xfb.hpK) or 1
                zfb.hp, zfb.max = zfb.hp * Afb, zfb.max * Afb
                table.insert(Keb, zfb)
            end
            Heb.starAcc = Heb.starAcc - 1
        end
    end
    local Bfb = tonumber(Heb.cal and Heb.cal.countCal)
    if Bfb and not Jeb and math.abs(Bfb - 1) > 0.05 and # Keb > 0 then
        local Cfb = math.max(1, math.floor(# Keb * Bfb + 0.5))
        local Dfb = # Keb
        if Cfb > Dfb then
            for Efb = 1, Cfb - Dfb do
                local Ffb = Keb [((Efb - 1) % Dfb) + 1]
                table.insert(Keb, table.clone(Ffb))
            end
        else
            for Gfb = 1, Dfb - Cfb do
                table.remove(Keb)
            end
        end
    end
    return Keb, Simulator.waveYen(Heb, Ieb)
end
Simulator._masks = {
}
Simulator._walk = {
}

function Simulator.mapWalk(Hfb)
    if not Hfb then
        return nil
    end
    if Simulator._walk [Hfb] ~= nil then
        return Simulator._walk [Hfb] or nil
    end
    local Ifb = Brain.maps [Hfb] and tonumber(Brain.maps [Hfb].walk)
    if not Ifb then
        local Jfb = {
        }
        for Kfb, Lfb in pairs(Brain.simCal) do
            local Mfb = type(Lfb) == "table" and tonumber(Lfb.walk) and (tostring(Kfb):match("^st:([^:]+)") or tostring(Kfb):match("^rd:([^:]+)") or tostring(Kfb):match("^inf:([^:]+)"))
            local Nfb = Mfb and Core.Levels [Mfb]
            if Nfb and Nfb.map == Hfb then
                table.insert(Jfb, tonumber(Lfb.walk))
            end
        end
        if # Jfb > 0 then
            table.sort(Jfb)
            Ifb = Jfb [math.ceil(# Jfb / 2)]
        end
    end
    if not Ifb then
        local Ofb = Reports.hive()
        local Pfb = Ofb and type(Ofb.mapInfo) == "table" and Ofb.mapInfo [Hfb]
        if type(Pfb) == "table" and (tonumber(Pfb.runs) or 0) >= 3 then
            Ifb = tonumber(Pfb.walk)
        end
    end
    Simulator._walk [Hfb] = Ifb or false
    return Ifb
end

function Simulator.mask(Qfb, Rfb)
    local Sfb = math.max(5, math.min(60, math.floor((Rfb or 10) / 5 + 0.5) * 5))
    local Tfb = tostring(Qfb) .. ":" .. Sfb
    if Simulator._masks [Tfb] then
        return Simulator._masks [Tfb]
    end
    local Ufb = Brain.maps [Qfb] or Brain.maps [tostring(Qfb):match("^(.-)~%d+$") or ""]
    local Vfb = Ufb and Ufb.bins and Ufb.bins [tostring(Sfb)]
    local Wfb = {
    }
    if type(Vfb) == "string" and # Vfb == Simulator.BINS then
        for Xfb = 1, Simulator.BINS do
            Wfb [Xfb] = Vfb:sub(Xfb, Xfb) == "1"
        end
        local Yfb = Ufb.binsL and Ufb.binsL [tostring(Sfb)]
        if type(Yfb) == "table" then
            Wfb.lanes = {
            }
            for Zfb, _fb in pairs(Yfb) do
                local agb = {
                }
                for bgb = 1, Simulator.BINS do
                    agb [bgb] = _fb:sub(bgb, bgb) == "1"
                end
                Wfb.lanes [Zfb] = agb
            end
        end
    else
        local cgb = math.min(0.7, Sfb / 70)
        for dgb = 1, Simulator.BINS do
            local egb = (dgb - 0.5) / Simulator.BINS
            Wfb [dgb] = egb >= 0.1 and egb <= 0.1 + cgb
        end
    end
    Simulator._masks [Tfb] = Wfb
    return Wfb
end

function Simulator.laneList(fgb)
    local ggb, hgb = {
    }, {
    }
    for igb, jgb in ipairs(fgb or {
    }) do
        local kgb = tostring(jgb.lane)
        if jgb.lane ~= nil and not ggb [kgb] then
            ggb [kgb] = true
            table.insert(hgb, kgb)
        end
    end
    table.sort(hgb)
    return # hgb >= 2 and hgb or nil
end

function Simulator.spotMask(lgb, mgb, ngb)
    local ogb = math.floor(ngb + 0.5)
    local pgb = string.format("%d,%d,%d", mgb.X, mgb.Z, ogb)
    local qgb = lgb.cache [pgb]
    if qgb then
        return qgb
    end
    qgb = {
    }
    local rgb = ogb * ogb
    local sgb = Simulator.laneList(lgb.samples) ~= nil
    if sgb then
        qgb.lanes = {
        }
    end
    for tgb, ugb in ipairs(lgb.samples) do
        local vgb, wgb = ugb.pos.X - mgb.X, ugb.pos.Z - mgb.Z
        if vgb * vgb + wgb * wgb <= rgb then
            local xgb = math.min(Simulator.BINS, math.floor(ugb.prog * Simulator.BINS) + 1)
            qgb [xgb] = true
            if sgb then
                local ygb = tostring(ugb.lane)
                qgb.lanes [ygb] = qgb.lanes [ygb] or {
                }
                qgb.lanes [ygb] [xgb] = true
            end
        end
    end
    lgb.cache [pgb] = qgb
    return qgb
end

function Simulator.teamFrom(zgb, Agb)
    local Bgb = {
    }
    local Cgb = Brain.maps [Agb] or Brain.maps [tostring(Agb):match("^(.-)~%d+$") or ""]
    local Dgb = not (Cgb and Cgb.hill == false)
    for Egb, Fgb in ipairs(zgb) do
        local Ggb = Core.Units [Fgb.unit_id]
        local Hgb = Ggb and Units.rows(Fgb.unit_id)
        if Hgb then
            table.insert(Bgb, {
                u = Fgb,
                id = Fgb.unit_id,
                data = Ggb,
                rows = Hgb,
                cap = Units.cap(Fgb),
                farm = Units.isFarm(Fgb.unit_id),
                placeable = (not Ggb.hill_unit) or Dgb
            })
        end
    end
    return Bgb
end

function Simulator.sig(Igb)
    local Jgb = {
    }
    for Kgb, Lgb in ipairs(Igb) do
        table.insert(Jgb, tostring(Lgb.unit_id))
    end
    table.sort(Jgb)
    return table.concat(Jgb, ",")
end
Simulator.WALK_STUDS = 1.9

function Simulator.boxBins(Mgb, Ngb, Ogb)
    local Pgb = 2 * (Ngb or 0) * (tonumber(Mgb.walk) or Simulator.PRIOR.walk) / Simulator.WALK_STUDS
    return math.max(1, math.min(Ogb, math.floor(Pgb * Simulator.BINS + 0.5)))
end
Simulator._holds, Simulator._holdsFrom = {
}, {
}

function Simulator.holds(Qgb)
    local Rgb = Simulator._holds [Qgb]
    if Rgb == nil then
        Rgb = false
        local Sgb, Tgb = pcall(Units.toggleOf, Qgb)
        if Sgb and Tgb then
            Rgb, Simulator._holdsFrom [Qgb] = true, tonumber(Tgb.from) or 1
        end
        local Ugb = not Rgb and Units.rows(Qgb)
        for Vgb = 0, Ugb and Ugb.max or - 1 do
            local Wgb = Ugb [Vgb]
            local Xgb, Ygb = false, nil
            if Wgb then
                Xgb, Ygb = pcall(Units.attackInfo, Wgb.atk, Wgb.range)
            end
            if Xgb and Ygb and ((Ygb.stun or 0) > 0 or (Ygb.slowTime or 0) > 0) then
                Rgb, Simulator._holdsFrom [Qgb] = true, Vgb
                break
            end
        end
        Simulator._holds [Qgb] = Rgb
    end
    return Rgb, Simulator._holdsFrom [Qgb]
end
Simulator.GALE_SLOW = 0.3

function Simulator.memoOn()
    Simulator.memo, Simulator.memoAt = setmetatable({
    }, {
        __mode = "k"
    }), os.clock()
end

function Simulator.run(Zgb, _gb, ahb)
    local bhb = Simulator.memo
    if bhb and os.clock() - (Simulator.memoAt or 0) > 180 then
        Simulator.memo, bhb = nil, nil
    end
    if not bhb then
        return Simulator.runRaw(Zgb, _gb, ahb)
    end
    for chb in pairs(ahb or {
    }) do
        if chb ~= "hpMul" then
            return Simulator.runRaw(Zgb, _gb, ahb)
        end
    end
    local dhb = {
        tostring(Zgb.zone),
        tostring(ahb and ahb.hpMul or 1)
    }
    for ehb, fhb in ipairs(_gb) do
        dhb [# dhb + 1] = tostring(fhb.u and fhb.u.uuid) .. ":" .. tostring(fhb.id) .. ":" .. tostring(fhb.u and fhb.u.xp) .. ":" .. tostring(fhb.u and fhb.u._equipped_relic)
    end
    local ghb = table.concat(dhb, ",")
    local hhb = bhb [Zgb]
    if not hhb then
        hhb = {
        }
        bhb [Zgb] = hhb
    end
    local ihb = hhb [ghb]
    if not ihb then
        ihb = Simulator.runRaw(Zgb, _gb, ahb)
        hhb [ghb] = ihb
        Simulator.memoMiss = (Simulator.memoMiss or 0) + 1
    else
        Simulator.memoHit = (Simulator.memoHit or 0) + 1
    end
    return ihb
end

function Simulator.runRaw(jhb, khb, lhb)
    lhb = lhb or {
    }
    local mhb = lhb.hpMul or 1
    local nhb = Simulator.DT
    local ohb = 0
    if lhb.layout and lhb.layout.laneList == nil then
        lhb.layout.laneList = Simulator.laneList(lhb.layout.samples) or false
    end
    local phb = not lhb.noLanes and ((lhb.layout and lhb.layout.laneList) or jhb.laneList) or nil
    local qhb, rhb = phb and # phb or 0, 0
    local function shb(thb, uhb, vhb)
        local whb = qhb >= 2 and uhb.lane and thb.mask.lanes
        if whb then
            local xhb = whb [uhb.lane]
            return xhb ~= nil and xhb [vhb] == true
        end
        return thb.mask [vhb] and true or false
    end
    local yhb, zhb, Ahb, Bhb = jhb.start, 0, 0, 3
    local Chb, Dhb, Ehb, Fhb, Ghb, Hhb, Ihb = {
    }, {
    }, {
    }, {
    }, {
    }, {
    }, {
    }
    local Jhb, Khb = {
    }, {
    }
    local Lhb = jhb.baseHp
    local Mhb = {
    }
    for Nhb = 1, jhb.total do
        Mhb [Nhb] = Simulator.waveYen(jhb, Nhb)
    end
    local Ohb = true
    local Phb = Simulator.wave(jhb, 1, true)
    local Qhb = {
    }
    local function Rhb(Shb, Thb, Uhb)
        local Vhb = Qhb [Shb]
        if not Vhb then
            Vhb = {
            }
            Qhb [Shb] = Vhb
        end
        local Whb = Uhb and - 1 - Thb or Thb
        local Xhb = Vhb [Whb]
        if not Xhb then
            Xhb = Units.dps(Shb.u, Thb, jhb.mod, Uhb) * (1 - jhb.red) * Simulator.fxDps(jhb, Shb.id) * Units.skinMul(Shb.u, jhb.skinSet)
            Vhb [Whb] = Xhb
        end
        return Xhb
    end
    local Yhb, Zhb = nil, 0
    for _hb, aib in ipairs(khb) do
        local bib = aib.rows [0]
        if not aib.farm and bib then
            local cib = Rhb(aib, 0) * (tonumber(bib.cd) or 2) / math.max(1, Units.attackInfo(bib.atk, bib.range).n)
            if cib > Zhb then
                Yhb, Zhb = aib.id, cib
            end
        end
    end
    local dib = 0
    for eib, fib in ipairs(Phb) do
        dib = dib + (fib.sh or 0)
    end
    dib = # Phb > 0 and dib / # Phb or 0
    local gib = jhb.eff or Simulator.PRIOR.eff
    local hib = {
    }
    local function iib(jib)
        if jib > jhb.total then
            return nil
        end
        if not hib [jib] then
            local kib = 0
            for lib, mib in ipairs((Simulator.wave(jhb, jib))) do
                kib = kib + mib.hp + (mib.bar or 0)
            end
            hib [jib] = kib * mhb
        end
        return hib [jib]
    end
    local nib
    if lhb.train then
        nib = Simulator.BINS
        for oib, pib in ipairs(khb) do
            if not pib.farm and pib.u.uuid ~= lhb.train then
                local qib = Simulator.mask(jhb.map, Units.range(pib.u, 0) * jhb.rangeScale)
                for rib = 1, Simulator.BINS do
                    if qib [rib] then
