                        break
                    end
                end
            end
        end
    end
    local sib, tib, uib, vib = false, 0, 1, false
    local wib, xib = {
    }, {
    }
    local yib, zib, Aib = 0, 0, 0
    local Bib = 0
    local function Cib()
        return 1 + Units.BLESS.dmg * math.min(Units.BLESS.cap, Bib)
    end
    local Dib = jhb.zone and not lhb.noZone and not lhb.layout
    local Eib = lhb.layout and lhb.layout.style
    local Fib = Dib or Eib == "box"
    local function Gib(Hib)
        Hib.dps = Hib.e.farm and 0 or Rhb(Hib.e, Hib.lvl, true)
        Hib.dpsAll = Hib.e.farm and 0 or Rhb(Hib.e, Hib.lvl)
        local Iib = Units.galeOf(Hib.e.id)
        Hib.gale = Iib and Hib.lvl >= Iib.from and Iib or nil
        if Hib.gale then
            vib = true
        end
        local Jib = lhb.layout and not Hib.later and lhb.layout.spots [Hib.e.id]
        local Kib = Units.range(Hib.e.u, Hib.lvl) * jhb.rangeScale * (Units.SUMMONER [Hib.e.id] and Units.SUMMONER [Hib.e.id].reach * (1 + Units.BLESS.range * math.min(Units.BLESS.cap, Bib)) or 1)
        Hib.mask = Jib and Simulator.spotMask(lhb.layout, Jib, Kib) or Simulator.mask(jhb.map, Kib)
        local Lib = lhb.place and lhb.place [Hib.e.id]
