            end
            local Oib = {
            }
            for Pib = 1, Simulator.BINS do
                Oib [Pib] = (Lib == "start" and Pib <= Mib) or (Lib == "end" and Pib > Simulator.BINS - Mib) or (Lib == "best" and Hib.mask [Pib] == true) or false
            end
            Hib.mask = Oib
        end
        if (Dib or (Eib == "box" and Hib.later)) and not Lib and not Hib.e.farm and Hib.e.u.uuid ~= lhb.train then
            local Qib = 0
            for Rib = 1, Simulator.BINS do
                if Hib.mask [Rib] then
                    Qib = Qib + 1
                end
            end
            Qib = Simulator.boxBins(jhb, Kib, Qib)
            local Sib = Hib.later and Simulator.BINS - 1 or Simulator.BINS
            local Tib = {
            }
            for Uib = 1, Simulator.BINS do
