                    Zib = Zib + 1
                end
            end
            Zib = math.max(1, Zib)
            local ajb, bjb
            for cjb, djb in ipairs(Ehb) do
                if djb ~= Hib and not djb.ctlN and not djb.e.farm and not djb.buff and djb.mask then
