                            local Rmb = Qmb.fly and not Mmb.air
                            Qmb.galeCov = math.min(1, (Qmb.galeCov or 0) + Nmb.duty)
                            if not Rmb and not Qmb.fire then
                                Qmb.galeBy = Mmb
                            end
                            if (Qmb.sh or 0) <= 0 then
                                local Smb = Omb * Nmb.tick * Nmb.duty * nhb * (Rmb and Core.FLY_GROUND or 1) * Simulator.modHit(Qmb, Mmb)
                                if lhb.dealt then
                                    lhb.dealt [Units.name(Mmb.e.id)] = (lhb.dealt [Units.name(Mmb.e.id)] or 0) + math.min(Smb, math.max(0, Qmb.hp))
                                end
                                Qmb.hp = Qmb.hp - Smb
                            end
                        end
                    end
                end
            end
            for Tmb, Umb in ipairs(Dhb) do
                local Vmb = Umb.galeBy
                Umb.galeSlow = (Vmb and not Umb.boss and not jhb.noCC) and (lhb.galeSlow or Simulator.GALE_SLOW) * Umb.galeCov or nil
                if Vmb then
                    Umb.chill = (Umb.chill or 0) + nhb * Umb.galeCov
                    if Umb.chill >= Vmb.gale.chill and zhb >= (Umb.galeFree or 0) then
                        Umb.chill, Umb.galeFree = 0, zhb + Vmb.gale.freeze + Vmb.gale.immune
                        if not Umb.boss and not jhb.noCC then
                            Umb.stunTo = math.max(Umb.stunTo or 0, zhb + Vmb.gale.freeze)
                        end
                        if (Umb.sh or 0) <= 0 then
                            local Wmb = fkb(Vmb) * math.max(0.3, Vmb.cd) / math.max(1, Vmb.aoe)
                            if lhb.dealt then
                                lhb.dealt [Units.name(Vmb.e.id)] = (lhb.dealt [Units.name(Vmb.e.id)] or 0) + math.min(Wmb, math.max(0, Umb.hp))
                            end
                            Umb.hp = Umb.hp - Wmb
                        end
                    end
                else
                    Umb.chill = nil
                end
            end
        end
        local Xmb = Cib()
        for Ymb, Zmb in ipairs(Ehb) do
            if Zmb.dps > 0 then
                vlb(Zmb, fkb(Zmb) * (Units.SUMMONER [Zmb.e.id] and Xmb or (1 + (Xmb - 1) * (Zmb.summonSh or 0))))
            end
        end
        for _mb = # wib, 1, - 1 do
            local anb = wib [_mb]
            if zhb >= anb.till then
                table.remove(wib, _mb)
            else
                vlb(anb, fkb(anb.owner) * math.max(0.3, anb.owner.cd) / math.max(1, anb.owner.aoe) * anb.dmg * anb.share / anb.cd * (anb.bless or 1))
            end
        end
        for bnb = # Dhb, 1, - 1 do
            local cnb = Dhb [bnb]
            if cnb.hp <= 0 then
                yhb = yhb + cnb.bounty
                table.insert(Ihb, {
                    t = zhb,
                    y = cnb.bounty
                })
                table.remove(Dhb, bnb)
                if cnb.tr then
                    ohb = ohb + 1
                end
                if cnb.split then
                    local dnb = Core.Units [cnb.split.unit] or {
                    }
                    for enb = 1, cnb.split.n do
                        local fnb = {
                            hp = cnb.max * cnb.split.ratio,
                            max = cnb.max * cnb.split.ratio,
                            speed = cnb.speed,
                            bounty = 0,
                            boss = false,
                            p = cnb.p,
                            at = zhb,
                            sh = (tonumber(dnb.shield) or 0) + (jhb.shield or 0),
                            fly = false,
                            lane = cnb.lane
                        }
                        if (jhb.flyChance or 0) > 0 then
                            Djb = Djb + jhb.flyChance
                            if Djb >= 1 then
                                Djb = Djb - 1
                                fnb.fly = true
                            end
                        end
                        Simulator.enemyTraits(fnb, dnb, fnb.hp)
                        table.insert(Dhb, fnb)
                    end
                end
                local gnb = cnb.droneBy
                if gnb and gnb.owner then
                    gnb = gnb.owner
                end
                if gnb and gnb.drone then
                    gnb.takes = (gnb.takes or 0) + 1
                    if gnb.takes >= gnb.drone.every then
                        gnb.takes = gnb.takes - gnb.drone.every
                        local hnb = 0
                        for inb, jnb in ipairs(wib) do
                            if jnb.owner == gnb then
                                hnb = hnb + 1
                            end
                        end
                        if hnb < gnb.drone.max then
                            local knb = gnb.droneNow
                            table.insert(wib, {
                                owner = gnb,
                                till = zhb + knb.life,
                                dmg = knb.dmg,
                                share = gnb.drone.share,
                                cd = knb.cd,
                                hits = gnb.drone.hits,
                                aoe = 1,
                                base = gnb.base,
                                mask = gnb.mask,
                                air = gnb.air,
                                hill = gnb.hill,
                                fireDmg = gnb.fireDmg,
                                stun = 0,
                                slowT = 0,
                                ccCd = 8,
                                drone = gnb.drone,
                                bless = Cib()
                            })
                        end
                    end
                end
            end
        end
        while Ihb [1] and zhb - Ihb [1].t > 30 do
            table.remove(Ihb, 1)
        end
        local lnb = 0
        for mnb, nnb in ipairs(Ihb) do
            lnb = lnb + nnb.y
        end
        local onb = zhb >= 8 and lnb / math.min(30, zhb) or ((Mhb [Ahb + 1] or Mhb [Ahb] or 500) / jhb.waveSec)
        if Lhb <= 0 then
            local pnb, qnb = 0, 0
            for rnb, snb in ipairs(Dhb) do
                pnb = pnb + math.max(0, snb.hp)
                qnb = qnb + snb.max
            end
            for tnb, unb in ipairs(Chb) do
                pnb = pnb + unb.hp
                qnb = qnb + unb.max
            end
            local vnb = {
            }
            for wnb, xnb in ipairs(Ehb) do
                vnb [xnb.e.id] = math.max(vnb [xnb.e.id] or 0, xnb.lvl)
            end
            return {
                won = false,
                wave = Ahb,
                t = zhb,
                aliveAt = Ghb,
                dpsAt = Jhb,
                spentAt = Khb,
                money = yhb,
                tk = ohb,
                left = qnb > 0 and pnb / qnb or 1,
                levels = vnb
            }
        end
        if Ahb >= jhb.total and # Chb == 0 and # Dhb == 0 then
            local ynb = {
            }
            for znb, Anb in ipairs(Ehb) do
                ynb [Anb.e.id] = math.max(ynb [Anb.e.id] or 0, Anb.lvl)
            end
            return {
                won = true,
                wave = Ahb,
                t = zhb,
                aliveAt = Ghb,
                dpsAt = Jhb,
                spentAt = Khb,
                money = yhb,
                tk = ohb,
                levels = ynb
            }
        end
        local Bnb, Cnb = 0, 0
        for Dnb, Enb in ipairs(Dhb) do
            Bnb = Bnb + Enb.hp
        end
        for Fnb, Gnb in ipairs(Ehb) do
            Cnb = Cnb + fkb(Gnb)
        end
        table.insert(Fhb, # Dhb)
        local Hnb = Fhb [# Fhb - math.floor(12 / nhb)]
        local Inb = (# Dhb >= 8 and Hnb and # Dhb > Hnb + 1) or # Dhb >= 18
        local Jnb = math.max(Hhb [Ahb] or 0, Hhb [Ahb - 1] or 0)
        if Ahb >= jhb.total and not emb and not jhb.infinite and not lhb.oldBuy then
            emb = true
            for Knb = # Ehb, 1, - 1 do
                local Lnb = Ehb [Knb]
                if Lnb.e.farm and not Lnb.e.data.unsellable then
                    yhb = yhb + 0.25 * (Lnb.spent or 0)
                    table.remove(Ehb, Knb)
                end
            end
            Tjb()
        end
        local function Mnb(Nnb, Onb, Pnb)
            if (jhb.regen or 0) <= 0 then
                return 0
            end
            local Qnb = Units.bleeds(Nnb.id)
            if not Qnb then
                return 0
            end
            local Rnb = false
            for Snb, Tnb in ipairs(Ehb) do
                if (Units.bleeds(Tnb.e.id) or 99) <= Tnb.lvl then
                    Rnb = true
                    break
                end
            end
            local Unb = {
            }
            for Vnb = 1, 5 do
                local Wnb = iib(Ahb + Vnb)
                if not Wnb then
                    break
                end
                table.insert(Unb, {
                    hp = Wnb
                })
            end
            return Economy.bleedShare(Economy.bleedGain(jhb.regen, Bnb, Unb, Rnb), Qnb, Onb, Pnb)
        end
        for Xnb = 1, 3 do
            local Ynb, Znb, _nb, aob = {
            }, 0, 0, 0
            for bob, cob in ipairs(khb) do
                local dob = {
                }
                local eob = lhb.trial and cob.id ~= lhb.trial and not cob.farm and (not Units.allyBuff(cob.id)) and Jnb < (lhb.trialAt or 0.6)
                for fob, gob in ipairs(Ehb) do
                    if gob.e == cob then
                        table.insert(dob, gob)
                    end
                end
                if not cob.farm and # dob > 0 then
                    aob = aob + 1
                end
                if eob then
                    dob = nil
                end
                for hob, iob in ipairs(dob or {
                }) do
                    if cob.farm then
                        _nb = _nb + Units.farm(cob.u, iob.lvl)
                    end
                    local job = cob.rows [iob.lvl + 1]
                    if job and iob.lvl < cob.rows.max then
                        local kob = job.cost * jhb.costScale
                        if cob.farm then
                            table.insert(Ynb, {
                                farm = true,
                                cost = kob,
                                gain = Units.farm(cob.u,
                                iob.lvl + 1) - Units.farm(cob.u,
                                iob.lvl),
                                c = iob
                            })
                        else
                            local lob = dib > 0 and not lhb.oldBuy and Economy.shieldGain(iob.dpsAll or iob.dps, cob.rows [iob.lvl], Rhb(cob, iob.lvl + 1), job, dib, Ejb, Mjb, gib) or Economy.upgradeGain(iob.dpsAll or iob.dps, cob.rows, iob.lvl, kob, jhb.costScale, Rhb(cob, iob.lvl + 1))
                            table.insert(Ynb, {
                                cost = kob,
                                gain = lob * (iob.train and Training.BONUS or 1) * ikb(cob.id,
                                iob.lvl) * Wkb(iob) * olb(iob) + Mnb(cob,
                                iob.lvl,
                                false),
                                c = iob
                            })
                            for mob = iob.lvl + 1, cob.rows.max do
                                Znb = Znb + cob.rows [mob].cost * jhb.costScale
                            end
                        end
                    end
                end
                local nob = Units.allyBuff(cob.id)
                local oob = false
                if nob and not lhb.oldBuy then
                    oob = true
                    for pob, qob in ipairs(khb) do
                        if not qob.farm and not Units.allyBuff(qob.id) and not (lhb.trial and qob.id ~= lhb.trial and Jnb < (lhb.trialAt or 0.6)) then
                            local rob, sob = Units.types(qob.id)
                            if nob.types [sob] then
                                oob = false
                                break
                            end
                        end
                    end
                end
                if dob and not oob and # dob < (nob and math.min(cob.cap, Units.buffCopies(nob)) or cob.cap) and cob.placeable then
                    local tob = (cob.data.cost or 0) * jhb.costScale
                    if cob.farm then
                        table.insert(Ynb, {
                            farm = true,
                            place = true,
                            cost = tob,
                            gain = Units.farm(cob.u,
                            0),
                            e = cob
                        })
                    else
                        local uob = lhb.train ~= nil and cob.u.uuid == lhb.train
                        local vob = (# dob == 0 and 2.5 or 1) * (aob < 3 and 1.3 or 1) * (uob and Training.BONUS or 1) * ikb(cob.id, 0, true)
                        local wob = cob.rows [0]
                        local xob = wob and Units.attackInfo(wob.atk, wob.range) or {
                            n = 1,
                            hits = 1
                        }
                        local yob = (tonumber(wob and wob.cd) or 2) * Mjb
                        local zob = lhb.oldBuy and Rhb(cob, 0) or Economy.shieldDps(Rhb(cob, 0), yob, xob.n, dib, Ejb, gib, xob.hits)
                        if Rhb(cob, 0) > 0 and not lhb.oldBuy then
                            local Aob = 0
                            for Bob, Cob in ipairs(Ehb) do
                                if Cob.dps > 0 then
                                    Aob = Aob + Cob.aoe * Cob.hits / math.max(0.3, Cob.cd)
                                end
                            end
                            zob = zob + Economy.shieldWork(xob.n, yob, Aob, dib, Fjb, jhb.waveSec, Zhb * gib, Ejb, xob.hits)
                        end
                        table.insert(Ynb, {
                            place = true,
                            cost = tob,
                            gain = zob * vob + Gkb(cob) + zkb(cob) + blb(cob,
                            xob) + Mnb(cob,
                            0,
                            true),
                            e = cob,
                            train = uob and (# dob == 0 and "first" or "more") or nil
                        })
                        for Dob = 0, cob.rows.max do
                            Znb = Znb + cob.rows [Dob].cost * jhb.costScale
                        end
                    end
                end
            end
            if # Ynb == 0 then
                break
            end
            if lhb.train then
                Training.boost(Ynb, aob, Jnb, Pjb)
            end
            local Eob = math.max(0, jhb.total - Ahb)
            local Fob = yhb + _nb * Eob
            for Gob = Ahb + 1, jhb.total do
                Fob = Fob + (Mhb [Gob] or 0)
            end
            local Hob = {
            }
            for Iob = 1, 5 do
                local Job = iib(Ahb + Iob)
                if not Job then
                    break
                end
                table.insert(Hob, {
                    hp = Job,
                    reward = Mhb [Ahb + Iob] or 0
                })
            end
            local Kob = lhb.oldBuy and 1 or tkb()
            local Lob = Economy.decide(Ynb, {
                money = yhb,
                left = Eob,
                attackers = aob,
                pressure = Jnb,
                piling = Inb,
                clearSec = Bnb > 0 and (Cnb > 0 and Bnb / (Cnb * (lhb.oldBuy and gib or 1) * Kob) or math.huge) or 0,
                enemies = # Dhb,
                future = Fob,
                wantLeft = Znb,
                coming = Hob,
                waveSec = jhb.waveSec,
                eff = gib,
                teamDps = Cnb * gib,
                shieldK = Kob,
                farmNow = _nb,
                hpAlive = Bnb,
                incomeRate = onb,
                roadSec = 1 / math.max(0.001,
                jhb.walk * (jhb.speedScale or 1)),
                cover = Pjb,
                leak = (Pjb and qmb > Pjb + 0.02) and qmb or nil
            })
            if not Lob or Lob.cost > yhb then
                break
            end
            yhb = yhb - Lob.cost
            Khb [Ahb] = (Khb [Ahb] or 0) + Lob.cost
            if Lob.place then
                local Mob = {
                    e = Lob.e,
                    lvl = 0,
                    spent = Lob.cost
                }
                for Nob, Oob in ipairs(Ehb) do
                    if Oob.e == Lob.e then
                        Mob.later = true
                        break
                    end
                end
                if Fib and Simulator.holds(Lob.e.id) then
                    Mob.ctlN = 1
                    for Pob, Qob in ipairs(Ehb) do
                        if Qob.ctlN then
                            Mob.ctlN = Mob.ctlN + 1
                        end
                    end
                end
                if not Fib and not Lob.e.farm and Pjb and qmb > Pjb then
                    Mob.lo = math.floor(qmb * Simulator.BINS) + 2
                end
                Gib(Mob)
                table.insert(Ehb, Mob)
                if Units.BLESS.by [Mob.e.id] then
                    Bib = Bib + 1
                    for Rob, Sob in ipairs(Ehb) do
                        if Units.SUMMONER [Sob.e.id] then
                            Gib(Sob)
                        end
                    end
                end
                if lhb.buys then
                    table.insert(lhb.buys, string.format("%.0fs w%d place %s", zhb, Ahb, Units.name(Mob.e.id)))
                end
            else
                Lob.c.lvl = Lob.c.lvl + 1
                Lob.c.spent = (Lob.c.spent or 0) + Lob.cost
                Gib(Lob.c)
                if lhb.buys then
                    table.insert(lhb.buys, string.format("%.0fs w%d up %s L%d", zhb, Ahb, Units.name(Lob.c.e.id), Lob.c.lvl))
                end
            end
            Tjb()
            Cnb = 0
            for Tob, Uob in ipairs(Ehb) do
                Cnb = Cnb + fkb(Uob)
            end
        end
        if lhb.trace then
            lhb.trace(zhb, Ahb, yhb, Ehb, Dhb, Lhb)
        end
        zhb = zhb + nhb
        cmb = cmb + 1
        if cmb % 120 == 0 then
            task.wait()
        end
    end
    return {
        won = false,
        wave = Ahb,
        t = zhb,
        aliveAt = Ghb,
        dpsAt = Jhb,
        spentAt = Khb,
        money = yhb,
        timeout = true,
        tk = ohb
    }
end
Simulator.INF_CAP = 80

function Simulator.evaluate(Vob, Wob)
    local Xob = Simulator.run(Vob, Wob, {
        hpMul = 1
    })
    local Yob = {
        won = Xob.won,
        wave = Xob.wave,
        minutes = Xob.t / 60,
        aliveAt = Xob.aliveAt,
        total = Vob.total,
        at = os.time()
    }
    if Vob.infinite and Simulator.unbound(Vob.ld) then
        Yob.p = 1
        Yob.margin = Xob.won and string.format("lasts past wave %d", Vob.total) or string.format("lasts to wave %d (%.0f min)", Xob.wave, Xob.t / 60)
    elseif Xob.won then
        local Zob = Simulator.run(Vob, Wob, {
            hpMul = 1.3
        })
        Yob.p = Zob.won and 0.92 or 0.7
        Yob.margin = Zob.won and "wins with room to spare" or "wins, but only just"
    else
        local _ob = Simulator.run(Vob, Wob, {
            hpMul = 0.75
        })
        Yob.p = _ob.won and 0.25 or 0.05
        Yob.margin = _ob.won and string.format("loses at wave %d (would win vs 25%% weaker enemies)", Xob.wave) or string.format("loses at wave %d of %d", Xob.wave, Vob.total)
        if not _ob.won then
            local apb = Simulator.run(Vob, Wob, {
                hpMul = 0.25
            })
            if not apb.won then
                Yob.p, Yob.hopeless = 0.005, true
                Yob.margin = string.format("loses at wave %d of %d, even against enemies at a quarter of their health", Xob.wave, Vob.total)
            end
        end
    end
    return Yob
end

function Simulator.trust(bpb, cpb)
    local dpb = bpb.cal or {
    }
    if type(dpb.alive) ~= "table" or dpb.teamSig ~= Simulator.sig((function()
        local epb = {
        }
        for fpb, gpb in ipairs(cpb) do
            table.insert(epb, gpb.u)
        end
        return epb
    end)()) then
        return nil
    end
    if bpb.key == "ch" and not dpb.aliveLvl then
        return nil
    end
    if dpb.aliveLvl and bpb.ld and bpb.ld.id and dpb.aliveLvl ~= tostring(bpb.ld.id) .. (Hunt.is(bpb.ld.id) and ("@" .. tostring(bpb.ld.map)) or "") then
        return nil
    end
    local hpb = Simulator.run(bpb, cpb, {
        hpMul = 1
    })
    local ipb, jpb, kpb = 0, 0, 0
    for lpb = 3, math.min(hpb.wave, tonumber(dpb.lastWave) or 99) do
        local mpb = tonumber(dpb.alive [tostring(lpb)])
        local npb = hpb.aliveAt [lpb]
        if mpb and npb and mpb > 0 then
            ipb = ipb + mpb
            jpb = jpb + npb
            kpb = kpb + 1
        end
    end
    if kpb < 2 or jpb <= 0 then
        return nil
    end
    local opb = ipb / jpb
    return {
        ratio = opb,
        ok = opb >= 0.75 and opb <= 1.33,
        waves = kpb
    }
end
Simulator.GROWN_LEVEL, Simulator.GROWN_MIN = 50, 6

function Simulator.grownKinds()
    local ppb = Core.session()
    local qpb, rpb = {
    }, 0
    for spb, tpb in pairs(ppb.profile_data.collection.owned_units) do
        local upb = tpb.unit_id
        if not qpb [upb] and Core.Units [upb] and not Units.isFarm(upb) and Units.rows(upb) and not Units.hidden(upb) then
            local vpb, wpb = pcall(Core.USC.calculate_level, upb, tonumber(tpb.xp) or 0)
            if vpb and (tonumber(wpb) or 0) >= Simulator.GROWN_LEVEL then
                qpb [upb] = true
                rpb = rpb + 1
            end
        end
    end
    return rpb
end

function Simulator.pool(xpb, ypb)
    local zpb = Core.session()
    local Apb, Bpb = {
    }, {
    }
    local Cpb = Simulator.grownKinds() >= Simulator.GROWN_MIN
    for Dpb, Epb in pairs(zpb.profile_data.collection.owned_units) do
        local Fpb = zpb.collection:get_unit_by_uuid(Epb.uuid) or Epb
        local Gpb, Hpb = pcall(Core.USC.calculate_level, Fpb.unit_id, tonumber(Fpb.xp) or 0)
        local Ipb = Units.isFarm(Fpb.unit_id) or not Cpb or (Gpb and (tonumber(Hpb) or 0) >= Simulator.GROWN_LEVEL)
        if Core.Units [Fpb.unit_id] and Units.rows(Fpb.unit_id) and not Units.hidden(Fpb.unit_id) and Ipb then
            local Jpb = Units.isFarm(Fpb.unit_id)
            local Kpb, Lpb = pcall(Jpb and function()
                return Units.farm(Fpb, Units.rows(Fpb.unit_id).max)
            end or Units.score, Fpb, xpb)
            Lpb = (Kpb and Lpb or 0) * (Jpb and 1 or Units.skinMul(Fpb, ypb and ypb.skinSet))
            local Mpb = Jpb and Bpb or Apb
            if not Mpb [Fpb.unit_id] or Lpb > Mpb [Fpb.unit_id].sc then
                Mpb [Fpb.unit_id] = {
                    u = Fpb,
                    sc = Lpb
                }
            end
        end
    end
    local Npb, Opb = {
    }, {
    }
    for Ppb, Qpb in pairs(Apb) do
        table.insert(Npb, Qpb)
    end
    for Rpb, Spb in pairs(Bpb) do
        table.insert(Opb, Spb)
    end
    table.sort(Npb, function(Tpb, Upb)
        return Tpb.sc > Upb.sc
    end)
    table.sort(Opb, function(Vpb, Wpb)
        return Vpb.sc > Wpb.sc
    end)
    local Xpb = {
    }
    for Ypb = 1, math.min(10, # Npb) do
        table.insert(Xpb, Npb [Ypb].u)
    end
    local Zpb, _pb = {
    }, {
    }
    for aqb = 11, # Npb do
        local bqb = Units.rows(Npb [aqb].u.unit_id)
        for cqb = 0, bqb.max do
            if bqb [cqb] and bqb [cqb].atk and Units.attackInfo(bqb [cqb].atk, bqb [cqb].range).dot > 0 then
                table.insert(cqb == 0 and Zpb or _pb, Npb [aqb].u)
                break
            end
        end
    end
    for dqb = 1, math.min(4, # Zpb) do
        table.insert(Xpb, Zpb [dqb])
    end
    for eqb = 1, math.min(2, # _pb) do
        table.insert(Xpb, _pb [eqb])
    end
    for fqb = 1, math.min(3, # Opb) do
        table.insert(Xpb, Opb [fqb].u)
    end
    local gqb = {
    }
    for hqb = 11, # Npb do
        local iqb = Units.rows(Npb [hqb].u.unit_id) [0]
        local jqb = iqb and iqb.atk and Units.attackInfo(iqb.atk, iqb.range)
        if jqb and (jqb.slowTime > 0 or jqb.stun > 0) then
            table.insert(gqb, Npb [hqb].u)
        end
    end
    for kqb = 1, math.min(3, # gqb) do
        table.insert(Xpb, gqb [kqb])
    end
    for lqb = 11, # Npb do
        local mqb = Npb [lqb].u.unit_id
        if Units.allyBuff(mqb) or Units.BLESS.by [mqb] or Units.GALE [mqb] then
            table.insert(Xpb, Npb [lqb].u)
        end
    end
    if ypb and ((ypb.flyChance or 0) > 0 or ypb.mapFly or (ypb.shield or 0) > 0) then
        local nqb, oqb = {
        }, {
        }
        for pqb = 11, # Npb do
            local qqb = Npb [pqb].u
            local rqb = Units.rows(qqb.unit_id) [0]
            if Units.airFrom(qqb.unit_id) == 0 then
                table.insert(nqb, qqb)
            end
            local sqb, tqb = tonumber(rqb and rqb.cd) or 0, tonumber((Core.Units [qqb.unit_id] or {
            }).cost) or 0
            if sqb > 0 and tqb > 0 and Units.range(qqb, 0) >= 15 then
                local uqb = Units.attackInfo(rqb.atk, rqb.range)
                table.insert(oqb, {
                    u = qqb,
                    v = uqb.n * uqb.hits / sqb / tqb * math.min(6,
                    Units.cap(qqb))
                })
            end
        end
        table.sort(oqb, function(vqb, wqb)
            return vqb.v > wqb.v
        end)
        for xqb = 1, math.min(4, # nqb) do
            table.insert(Xpb, nqb [xqb])
        end
        for yqb = 1, math.min(6, # oqb) do
            table.insert(Xpb, oqb [yqb].u)
        end
    end
    local zqb, Aqb = {
    }, {
    }
    for Bqb, Cqb in ipairs(Xpb) do
        if not zqb [Cqb] then
            zqb [Cqb] = true
            table.insert(Aqb, Cqb)
        end
    end
    Aqb.rest = {
    }
    for Dqb, Eqb in ipairs(Npb) do
        if not zqb [Eqb.u] then
            table.insert(Aqb.rest, Eqb.u)
        end
    end
    return Aqb
end

function Simulator.objective(Fqb)
    return (Fqb.won and 1000 or 0) + Fqb.wave * 10 - (Fqb.won and Fqb.t / 60 or ((Fqb.left or 1) * 9 - math.min(9, Fqb.t / 60)))
end
Simulator.LADDER = {
    1,
    1.3,
    1.7,
    2.2,
    3,
    4,
    6,
    8,
    12,
    16,
    24
}

function Simulator.cliff(Gqb, Hqb, Iqb)
    local Jqb
    for Kqb, Lqb in ipairs(Simulator.LADDER) do
        Jqb = Simulator.run(Gqb, Hqb, {
            hpMul = Lqb,
            layout = Iqb
        })
        if not Jqb.won then
            return Lqb, Jqb
        end
    end
    return Simulator.LADDER [# Simulator.LADDER], Jqb
end

function Simulator.exam(Mqb, Nqb)
    local Oqb, Pqb, Qqb = Simulator.teamFrom(Nqb, Mqb.map), 0, 0
    for Rqb, Sqb in ipairs(Simulator.LADDER) do
        local Tqb, Uqb = 0, 0
        for Vqb, Wqb in ipairs({
            0.92,
            1,
            1.08
        }) do
            local Xqb = Simulator.run(Mqb, Oqb, {
                hpMul = Sqb * Wqb
            })
            if Xqb.won then
                Tqb = Tqb + 1
            end
            Uqb = Uqb + Xqb.wave
        end
        Pqb, Qqb = Pqb + Tqb, Uqb / 3
        task.wait()
        if Tqb == 0 then
            break
        end
    end
    return Pqb, Qqb
end
Simulator.ZONE_CLOSE, Simulator.ZONE_GAIN = 1.3, 20

function Simulator.zoneKey(Yqb)
    return tostring(Yqb.key) .. ":" .. tostring(Yqb.map)
end

function Simulator.zoneChoice(Zqb, _qb, arb, brb)
    if Config.killZone == false or Zqb.zone or (Zqb.infinite and Simulator.unbound(Zqb.ld)) then
        return false
    end
    local crb = Brain.zoneRec [Simulator.zoneKey(Zqb)]
    local drb = crb and (crb.style == "box" or (crb.style == nil and crb.zone == true))
    if crb and crb.won then
        return drb == true, drb and "the kill box won here last time" or nil
    end
    if crb and drb then
        return false, "the kill box lost here last time"
    end
    local erb = Brain.modes [Zqb.key]
    local frb = erb and tonumber(erb.streak) or 0
    if not crb and erb and (tonumber(erb.wins) or 0) > 0 and frb == 0 and Zqb.key ~= "ch" and Zqb.key ~= "dc" then
        return false
    end
    local grb = crb ~= nil or frb > 0
    local hrb = brb and arb <= 1 or (not brb and arb <= Simulator.ZONE_CLOSE)
    if not (grb or hrb) then
        return false
    end
    local irb = table.clone(Zqb)
    irb.zone = true
    local function jrb(krb)
        local lrb = 0
        for mrb, nrb in ipairs({
            0.92,
            1,
            1.08
        }) do
            lrb = lrb + Simulator.objective(Simulator.run(krb, _qb, {
                hpMul = arb * nrb
            }))
        end
        return lrb / 3
    end
    local orb = jrb(irb) - jrb(Zqb)
    if grb and orb > - Simulator.ZONE_GAIN then
        return true, "spread-out units lost here last time", orb
    end
    if hrb and orb > Simulator.ZONE_GAIN then
        return true, string.format("the simulator says your team is close to losing here (enemies ×%.1f), and it plays better stacked", arb), orb
    end
    return false, nil, orb
end

function Simulator.strength(prb, qrb)
    local rrb, srb, trb, urb, vrb = Simulator.teamFrom(qrb, prb.map), 0, 0, 0, 0
    for wrb, xrb in ipairs(Simulator.LADDER) do
        local yrb, zrb = 0, 0
        for Arb, Brb in ipairs({
            0.92,
            1,
            1.08
        }) do
            local Crb = Simulator.run(prb, rrb, {
                hpMul = xrb * Brb
            })
            if Crb.won then
                yrb = yrb + 1
            end
            zrb = zrb + Crb.wave
        end
        srb, vrb = srb + yrb, zrb / 3
        if xrb == 1 then
            trb, urb = yrb, zrb / 3
        end
        task.wait()
        if yrb == 0 then
            break
        end
    end
    return srb, trb, urb, vrb
end

function Simulator.bestTeam(Drb, Erb, Frb, Grb)
    local Hrb = Utils.now()
    Grb = Grb or 25
    local Irb = table.clone(Erb)
    local Jrb, Krb = Simulator.cliff(Drb, Simulator.teamFrom(Irb, Drb.map))
    local function Lrb(Mrb)
        local Nrb = 0
        for Orb, Prb in ipairs(Mrb) do
            if Units.isFarm(Prb.unit_id) then
                Nrb = Nrb + 1
            end
        end
        return Nrb
    end
    local Qrb = Lrb(Frb) > 0
    local function Rrb(Srb)
        local Trb = 0
        for Urb, Vrb in ipairs(Srb) do
            if not Units.isFarm(Vrb.unit_id) and not Units.allyBuff(Vrb.unit_id) then
                Trb = Trb + Units.cap(Vrb)
            end
        end
        return Trb
    end
    local Wrb
    while # Irb < 6 do
        local Xrb, Yrb
        local Zrb = Qrb and Lrb(Irb) == 0
        for _rb, asb in ipairs(Frb) do
            local bsb = false
            for csb, dsb in ipairs(Irb) do
                if dsb.unit_id == asb.unit_id then
                    bsb = true
                end
            end
            if not bsb and (not Zrb or Units.isFarm(asb.unit_id)) then
                local esb = table.clone(Irb)
                table.insert(esb, asb)
                local fsb = Simulator.run(Drb, Simulator.teamFrom(esb, Drb.map), {
                    hpMul = Jrb
                })
                local gsb = Simulator.objective(fsb)
                if not Yrb or gsb > Yrb then
                    Xrb, Yrb, Wrb = asb, gsb, fsb
                end
            end
        end
        if not Xrb then
            break
        end
        table.insert(Irb, Xrb)
    end
    if Qrb and Lrb(Irb) == 0 then
        local hsb, isb
        for jsb = 1, # Irb do
            for ksb, lsb in ipairs(Frb) do
                if Units.isFarm(lsb.unit_id) then
                    local msb = table.clone(Irb)
                    msb [jsb] = lsb
                    local nsb = Simulator.run(Drb, Simulator.teamFrom(msb, Drb.map), {
                        hpMul = Jrb
                    })
                    local osb = Simulator.objective(nsb)
                    if not isb or osb > isb then
                        hsb, isb, Wrb = msb, osb, nsb
                    end
                end
            end
        end
        if hsb then
            Irb = hsb
        end
    end
    local function psb(qsb, rsb)
        local ssb = Simulator.teamFrom(qsb, Drb.map)
        return (Simulator.objective(rsb) + Simulator.objective(Simulator.run(Drb, ssb, {
            hpMul = Jrb * 0.92
        })) + Simulator.objective(Simulator.run(Drb, ssb, {
            hpMul = Jrb * 1.08
        }))) / 3
    end
    local tsb, usb = Wrb or Krb, psb(Irb, Wrb or Krb)
    if type(Frb.rest) == "table" and # Frb.rest > 0 then
        local vsb, wsb
        for xsb, ysb in ipairs(Irb) do
            if not Units.isFarm(ysb.unit_id) and not Units.allyBuff(ysb.unit_id) then
                local zsb, Asb = pcall(Units.score, ysb, Drb.mod)
                Asb = (zsb and Asb or 0) * Units.skinMul(ysb, Drb.skinSet)
                if not wsb or Asb < wsb then
                    vsb, wsb = xsb, Asb
                end
            end
        end
        if vsb then
            local Bsb, Csb = {
            }, Utils.now()
            for Dsb, Esb in ipairs(Frb.rest) do
                if Utils.now() - Csb > 5 then
                    break
                end
                local Fsb = false
                for Gsb, Hsb in ipairs(Irb) do
                    if Hsb.unit_id == Esb.unit_id then
                        Fsb = true
                    end
                end
                if not Fsb then
                    local Isb = table.clone(Irb)
                    Isb [vsb] = Esb
                    table.insert(Bsb, {
                        u = Esb,
                        o = Simulator.objective(Simulator.run(Drb,
                        Simulator.teamFrom(Isb,
                        Drb.map),
                        {
                            hpMul = Jrb
                        }))
                    })
                end
            end
            table.sort(Bsb, function(Jsb, Ksb)
                return Jsb.o > Ksb.o
            end)
            Frb = table.clone(Frb)
            for Lsb = 1, math.min(4, # Bsb) do
                table.insert(Frb, 1, Bsb [Lsb].u)
            end
            Hrb = Hrb + (Utils.now() - Csb)
        end
    end
    for Msb = 1, 2 do
        local Nsb = false
        for Osb = 1, # Irb do
            for Psb, Qsb in ipairs(Frb) do
                if Utils.now() - Hrb > Grb then
                    return Irb, tsb, Jrb, Krb
                end
                local Rsb = false
                for Ssb, Tsb in ipairs(Irb) do
                    if Tsb.unit_id == Qsb.unit_id then
                        Rsb = true
                    end
                end
                if not Rsb then
                    local Usb = table.clone(Irb)
                    Usb [Osb] = Qsb
                    if (not Qrb or Lrb(Usb) > 0) and Rrb(Usb) >= math.min(8, Rrb(Irb)) then
                        local Vsb = Simulator.run(Drb, Simulator.teamFrom(Usb, Drb.map), {
                            hpMul = Jrb
                        })
                        local Wsb = Simulator.objective(Vsb)
                        if Wsb > usb + 1 then
                            Wsb = psb(Usb, Vsb)
                            if Wsb > usb + 1 then
                                Irb, usb, tsb, Nsb = Usb, Wsb, Vsb, true
                            end
                        end
                    end
                end
            end
        end
        if not Nsb then
            break
        end
    end
    return Irb, tsb, Jrb, Krb
end

function Simulator.evolutions()
    local Xsb = Core.session()
    local Ysb, Zsb = {
    }, {
    }
    local _sb = Xsb.inventory
    local function atb(btb)
        local ctb = 0
        pcall(function()
            ctb = _sb:get_number_of_owned_item(btb)
        end)
        return ctb
    end
    for dtb, etb in pairs(Xsb.profile_data.collection.owned_units) do
        local ftb = Core.Units [etb.unit_id]
        if ftb and ftb.evolve and ftb.evolve.evolve_unit and not ftb.evolve.hide_from_ui and not Zsb [etb.unit_id] and Core.Units [ftb.evolve.evolve_unit] then
            Zsb [etb.unit_id] = true
            local gtb = etb.shiny and ftb.evolve.shiny or ftb.evolve.normal
            if gtb then
                local htb = {
                }
                for itb, jtb in pairs(gtb.item_requirement or {
                }) do
                    if atb(jtb.item_id) < (jtb.amount or 1) then
                        table.insert(htb, string.format("%s %d/%d", (Core.Items [jtb.item_id] or {
                        }).name or jtb.item_id, atb(jtb.item_id), jtb.amount))
                    end
                end
                for ktb, ltb in pairs(gtb.unit_requirement or {
                }) do
                    local mtb = 0
                    for ntb, otb in pairs(Xsb.profile_data.collection.owned_units) do
                        if otb.unit_id == ltb.unit_id and (not ltb.shiny or otb.shiny) then
                            mtb = mtb + 1
                        end
                    end
                    if mtb < (ltb.amount or 1) then
                        table.insert(htb, string.format("%s %d/%d", Units.name(ltb.unit_id), mtb, ltb.amount))
                    end
                end
                local ptb = Adventure.killsShort(Xsb.collection:get_unit_by_uuid(etb.uuid) or etb, gtb)
                if ptb then
                    table.insert(htb, string.format("%s %s/%s", ptb.what, Utils.fmt(ptb.have), Utils.fmt(ptb.need)))
                end
                if # htb <= 1 then
                    local qtb = Xsb.collection:get_unit_by_uuid(etb.uuid) or etb
                    table.insert(Ysb, {
                        u = qtb,
                        from = etb.unit_id,
                        to = ftb.evolve.evolve_unit,
                        missing = htb,
                        evolved = {
                            unit_id = ftb.evolve.evolve_unit,
                            uuid = "evo:" .. tostring(qtb.uuid),
                            xp = qtb.xp,
                            traits = qtb.traits,
                            trait_stats = qtb.trait_stats,
                            further_modifiers = qtb.further_modifiers
                        }
                    })
                end
            end
        end
    end
    return Ysb
end

function Simulator.levelFor(rtb)
    local stb = Brain.simCal [rtb.key]
    if rtb.kind == "daily" and Brain.live.daily and Brain.live.daily.ld then
        return Brain.live.daily.ld, Brain.live.daily.challenge
    end
    if Hunt.is(rtb.level) and Brain.live.event and Brain.live.event.ld then
        return Brain.live.event.ld, nil
    end
    local ttb = rtb.kind ~= "challenge" or (stb and type(stb.ld) == "table" and stb.ld.id == rtb.level and stb.ch == rtb.challenge)
    if stb and type(stb.ld) == "table" and ttb then
        return stb.ld, stb.ch
    end
    if rtb.kind == "challenge" and Core.Levels [rtb.level] then
        local utb = Simulator.slim(Core.Levels [rtb.level])
        utb._difficulty = "Hard"
        utb._gamemode = "challenge"
        utb._challenge = rtb.challenge
        return utb, rtb.challenge
    end
    if Core.Levels [rtb.level] then
        local vtb = Simulator.slim(Core.Levels [rtb.level])
        vtb._difficulty = rtb.diff
        vtb._gamemode = vtb._OVERRIDE_GAMEMODE or ((rtb.kind == "raid" or rtb.kind == "artifact") and "raid") or (vtb.infinite and "infinite") or "story"
        return vtb, nil
    end
end

function Simulator.plan(wtb, xtb, ytb, ztb)
    local Atb, Btb = Simulator.levelFor(wtb)
    if wtb.ldOverride then
        Atb = wtb.ldOverride
    end
    if not Atb then
        return nil
    end
    local Ctb = wtb.mod or (wtb.kind == "daily" and Brain.live.daily and Brain.live.daily.mod) or Modes.levelMod(wtb.level)
    local Dtb = Simulator.info(Atb, wtb.key, Btb, Ctb)
    local Etb = ztb
    if not Etb then
        Etb = {
        }
        for Ftb, Gtb in ipairs(Units.equipped()) do
            table.insert(Etb, Gtb.u)
        end
    end
    local Htb = Simulator.teamFrom(Etb, Dtb.map)
    local Itb = Simulator.evaluate(Dtb, Htb)
    local Jtb, Ktb = pcall(Simulator.zoneChoice, Dtb, Htb, Itb.p >= 0.92 and 1.7 or Itb.p >= 0.7 and 1.3 or 1, false)
    if Jtb and Ktb then
        Dtb.zone = true
        Itb = Simulator.evaluate(Dtb, Htb)
        Itb.zone = true
        Itb.margin = Itb.margin .. " with the kill box"
    end
    Itb.sig = Simulator.sig(Etb)
    Itb.trust = Simulator.trust(Dtb, Htb)
    Itb.label = wtb.label
    Itb.calibrated = (tonumber(Dtb.cal.n) or 0) > 0
    Brain.simRes [wtb.key] = Itb
    Itb.aliveAt = nil
    App.log(1, "SIM", string.format("%s: your team %s (%s, %s)", wtb.label, Itb.margin, Itb.calibrated and "calibrated on real runs" or "not calibrated yet", Itb.trust and string.format("real/sim HP %.2f", Itb.trust.ratio) or "no same-team run to compare"))
    local Ltb = Modes.rec(wtb.key)
    if Config.simTeams and xtb and type(Ltb.winTeam) == "table" and # Ltb.winTeam > 0 then
        local Mtb = Core.session()
        local Ntb = {
        }
        for Otb, Ptb in ipairs(Ltb.winTeam) do
            local Qtb = Mtb.collection:get_unit_by_uuid(Ptb)
            if Qtb then
                table.insert(Ntb, Qtb)
            end
        end
        if # Ntb == # Ltb.winTeam then
            local Rtb = Simulator.teamFrom(Ntb, Dtb.map)
            local Stb = Simulator.run(Dtb, Rtb, {
                hpMul = 1
            })
            local Ttb = Simulator.trust(Dtb, Rtb)
            local Utb = Ttb and not Ttb.ok
            if not Stb.won or Utb then
                local Vtb, Wtb = {
                }, {
                }
                for Xtb, Ytb in ipairs(Ntb) do
                    table.insert(Vtb, Units.name(Ytb.unit_id))
                    table.insert(Wtb, Ytb.unit_id)
                end
                Brain.simTeam [wtb.key] = {
                    uuids = Ltb.winTeam,
                    names = Vtb,
                    ids = Wtb,
                    won = true,
                    wave = Dtb.total,
                    better = Simulator.sig(Ntb) ~= Itb.sig,
                    cur = {
                        won = Itb.won,
                        wave = Itb.wave
                    },
                    at = os.time(),
                    label = wtb.label,
                    base = Itb.sig,
                    why = "the team that won here last run, no search"
                }
                App.log(1, "SIM", string.format("%s: the team that won here last run plays again (%s): %s, and real runs won %d in a row", wtb.label, table.concat(Vtb, ", "), Utb and string.format((Ttb.ratio or 0) < 0.1 and "the simulator is off ×%.2f against real runs here" or "the simulator is off ×%.1f against real runs here", Ttb.ratio or 0) or string.format("the simulator calls it a loss at wave %d", Stb.wave), Ltb.winTeamN or 1))
                return Itb
            end
        end
    end
    if Config.simTeams and xtb then
        local Ztb, _tb, aub, bub, cub = pcall(Simulator.bestTeam, Dtb, Etb, Simulator.pool(Ctb, Dtb), ytb)
        if Ztb and _tb then
            local dub = Simulator.sig(_tb) ~= Itb.sig
            if dub and Itb.won and (Itb.p or 0) >= 0.92 then
                local eub = {
                }
                for fub, gub in ipairs(_tb) do
                    table.insert(eub, Units.name(gub.unit_id))
                end
                App.log(1, "SIM", string.format("%s: your team already wins with room to spare, so it stays (the search had %s)", wtb.label, table.concat(eub, ", ")))
                _tb, dub = Etb, false
            end
            local hub = ""
            if dub then
                local iub, jub = Simulator.exam(Dtb, Etb)
                local kub, lub = Simulator.exam(Dtb, _tb)
                local mub = # _tb > # Etb and kub == iub and lub >= jub
                if kub > iub or (kub == iub and lub > jub) or mub then
                    hub = string.format(" · up the rising test it won %d tries, yours %d", kub, iub) .. (mub and string.format(", a tie, and it fills %d slots to your %d", # _tb, # Etb) or "")
                else
                    local nub = {
                    }
                    for oub, pub in ipairs(_tb) do
                        table.insert(nub, Units.name(pub.unit_id))
                    end
                    App.log(1, "SIM", string.format("%s: the search tried %s, but it doesn't go further than your team up the rising test (it won %d tries, yours %d): yours stays", wtb.label, table.concat(nub, ", "), kub, iub))
                    _tb, dub = Etb, false
                end
            end
            local qub = Simulator.run(Dtb, Simulator.teamFrom(_tb, Dtb.map), {
                hpMul = 1
            })
            if dub then
                Itb.playing = qub.won and "the best team wins" or string.format("the best team reaches wave %d of %d", qub.wave, Dtb.total)
            end
            local rub, tub = {
            }, {
            }
            for uub, vub in ipairs(_tb) do
                table.insert(rub, vub.uuid)
                table.insert(tub, Units.name(vub.unit_id))
            end
            local wub = {
            }
            for xub, yub in ipairs(_tb) do
                table.insert(wub, yub.unit_id)
            end
            Brain.simTeam [wtb.key] = {
                uuids = rub,
                names = tub,
                ids = wub,
                won = qub.won,
                wave = qub.wave,
                better = dub,
                cur = {
                    won = Itb.won,
                    wave = Itb.wave
                },
                at = os.time(),
                label = wtb.label,
                base = Itb.sig
            }
            App.log(1, "SIM", string.format("%s: best team from your units %s (%s)%s", wtb.label, qub.won and "wins" or ("reaches wave " .. qub.wave), table.concat(tub, ", "), dub and (string.format(" · it plays · against enemies ×%.1f: %s at wave %d, yours %s at wave %d", bub, aub.won and "wins" or "falls", aub.wave, cub.won and "wins" or "falls", cub.wave) .. hub) or " · the same as yours"))
            local zub = {
            }
            for Aub, Bub in ipairs(Simulator.evolutions()) do
                local Cub
                if Units.hidden(Bub.from) or Units.hidden(Bub.to) then
                    Cub = "strength unknown (the game shows its upgrades only in a match)"
                else
                    local Dub = table.clone(_tb)
                    local Eub = false
                    for Fub, Gub in ipairs(Dub) do
                        if Gub.unit_id == Bub.from then
                            Dub [Fub] = Bub.evolved
                            Eub = true
                        end
                    end
                    if not Eub then
                        local Hub, Iub = nil, math.huge
                        for Jub, Kub in ipairs(Dub) do
                            if not Units.isFarm(Kub.unit_id) then
                                local Lub, Mub = pcall(Units.score, Kub, Ctb)
                                if Lub and Mub < Iub then
                                    Hub, Iub = Jub, Mub
                                end
                            end
                        end
                        if Hub then
                            Dub [Hub] = Bub.evolved
                        end
                    end
                    local Nub = Simulator.run(Dtb, Simulator.teamFrom(Dub, Dtb.map), {
                        hpMul = 1
                    })
                    if Nub.won and not qub.won then
                        Cub = "turns " .. wtb.label .. " into a win"
                    elseif Nub.wave > qub.wave then
                        Cub = string.format("%s: reaches wave %d instead of %d", wtb.label, Nub.wave, qub.wave)
                    elseif Nub.won and qub.won and Nub.t < qub.t - 6 then
                        Cub = string.format("clears %s %.1f min faster", wtb.label, (qub.t - Nub.t) / 60)
                    else
                        Cub = qub.won and ("no difference in " .. wtb.label .. " (already a win)") or ("doesn't help in " .. wtb.label)
                    end
                end
                table.insert(zub, {
                    from = Units.name(Bub.from),
                    to = Units.name(Bub.to),
                    ready = # Bub.missing == 0,
                    missing = Bub.missing [1],
                    gain = Cub,
                    mode = wtb.label
                })
            end
            Brain.simEvo = zub
        end
    end
    App.saveSoon()
    return Itb
end
Dungeon.T = {
    CURSE = 0,
    SHOP = 1,
    MONEY = 2,
    GOLD = 3,
    CHEST = 4,
    BOSS = 5,
    OPEN = 6,
    SHRINE = 7
}
Dungeon.TAG_NAMES = {
    [0] = "curse",
    [1] = "shop",
    [2] = "coins",
    [3] = "rare chest",
    [4] = "chest",
    [5] = "final boss",
    [6] = "chest opening",
    [7] = "shrine"
}
Dungeon.KNOWN = {
    _started = true,
    _items = true,
    selected_next = true,
    next = true,
    _resources = true
}
Dungeon.ROOMS = 20

function Dungeon.core()
    if not Dungeon._core then
        Dungeon._core = Core.core("DungeonServiceCore")
    end
    return Dungeon._core
end

function Dungeon.data()
    local Oub = Core.prof()
    return Oub and type(Oub.dungeon_data) == "table" and Oub.dungeon_data or nil
end

function Dungeon.item(Pub)
    local Qub = Dungeon.core()
    return Pub and Qub and type(Qub.ITEMS) == "table" and Qub.ITEMS [Pub] or nil
end

function Dungeon.isCurse(Rub)
    return tostring(Rub):sub(1, 7) == "_curse_"
end

function Dungeon.tags(Sub)
    local Tub = {
    }
    for Uub, Vub in pairs(type(Sub) == "table" and type(Sub._t) == "table" and Sub._t or {
    }) do
        if Vub then
            Tub [tonumber(Uub) or - 1] = true
        end
    end
    return Tub
end

function Dungeon.list(Wub)
    local Xub = {
    }
    for Yub, Zub in pairs(type(Wub) == "table" and Wub or {
    }) do
        local _ub = tonumber(Yub)
        if _ub and type(Zub) == "table" then
            table.insert(Xub, {
                choice = _ub,
                key = Yub,
                r = Zub,
                tags = Dungeon.tags(Zub),
                d = tonumber(Zub._d) or 1
            })
        end
    end
    table.sort(Xub, function(avb, bvb)
        return avb.choice < bvb.choice
    end)
    return Xub
end

function Dungeon.rooms(cvb)
    return Dungeon.list(cvb and cvb.next)
end

function Dungeon.after(dvb, evb)
    return Dungeon.list(dvb and type(dvb.next) == "table" and dvb.next ["next" .. tostring(evb)] or nil)
end

function Dungeon.depth(fvb)
    local gvb = Dungeon.rooms(fvb) [1]
    return gvb and gvb.d or nil
end

function Dungeon.items(hvb)
    local ivb = {
    }
    for jvb, kvb in pairs(hvb and type(hvb._items) == "table" and hvb._items or {
    }) do
        local lvb = type(kvb) == "table" and kvb.id or (type(kvb) == "string" and kvb) or nil
        if lvb then
            ivb [lvb] = (ivb [lvb] or 0) + 1
        end
    end
    return ivb
end

function Dungeon.curses(mvb)
    local nvb = 0
    for ovb, pvb in pairs(Dungeon.items(mvb)) do
        if Dungeon.isCurse(ovb) then
            nvb = nvb + pvb
        end
    end
    return nvb
end

function Dungeon.res(qvb)
    local rvb = qvb and type(qvb._resources) == "table" and qvb._resources or {
    }
    return tonumber(rvb.money) or 0, tonumber(rvb.treasure) or 0, tonumber(rvb.treasure_gold) or 0
end

function Dungeon.lives(svb)
    local tvb = tonumber(svb and svb.lives) or tonumber(svb and type(svb.selected_next) == "table" and svb.selected_next.lives)
    if tvb then
        if tvb ~= Brain.dg.lives then
            Brain.dg.lives = tvb
            App.saveSoon()
        end
        return tvb
    end
    local uvb = tonumber(Brain.dg.lives)
    return (uvb and uvb > 0) and uvb or 5
end

function Dungeon.luck(vvb)
    local wvb = Dungeon.core()
    local xvb, yvb = pcall(function()
        return wvb.calculate_luck_multiplier(vvb)
    end)
    return xvb and tonumber(yvb) or 1
end

function Dungeon.tagText(zvb)
    local Avb = {
    }
    for Bvb = 0, 7 do
        if zvb [Bvb] then
            table.insert(Avb, Dungeon.TAG_NAMES [Bvb])
        end
    end
    return # Avb > 0 and table.concat(Avb, " + ") or "fight only"
end

function Dungeon.share(Cvb)
    local Dvb, Evb = 0, 0
    for Fvb, Gvb in ipairs(Units.equipped()) do
        local Hvb = Gvb.id or (Gvb.u and Gvb.u.unit_id)
        if Hvb and Gvb.u and not Units.isFarm(Hvb) and not Units.allyBuff(Hvb) then
            local Ivb = Units.rows(Hvb)
            local Jvb, Kvb = pcall(Units.dps, Gvb.u, Ivb and Ivb.max or 0, nil)
            Kvb = Jvb and tonumber(Kvb) or 0
            local Lvb, Mvb = Units.types(Hvb)
            Dvb = Dvb + Kvb
            if Mvb == Cvb or Mvb == Cvb .. "_damage" then
                Evb = Evb + Kvb
            end
        end
    end
    return Dvb > 0 and Evb / Dvb or 0.5
end

function Dungeon.itemValue(Nvb, Ovb)
    local Pvb = Dungeon.item(Nvb)
    if not Pvb or Dungeon.isCurse(Nvb) then
        return 0
    end
    local Qvb = 0
    if tonumber(Pvb.luck_increase) then
        Qvb = Qvb + 300 * Pvb.luck_increase
    end
    if tonumber(Pvb.star_remnant_chest_add) then
        Qvb = Qvb + 150 * Pvb.star_remnant_chest_add
    end
    if Nvb == "philospher_stone" then
        local Rvb, Svb = Dungeon.res(Ovb)
        Qvb = Qvb + 60 + 25 * Svb
    end
    if Nvb == "chest_mock_item" then
        Qvb = Qvb + 120
    end
    for Tvb, Uvb in pairs(type(Pvb.wave_modifier_effects) == "table" and Pvb.wave_modifier_effects or {
    }) do
        local Vvb = math.abs(tonumber(Uvb.amount) or 0)
        if Uvb.type == "stat_mul" and Uvb.stat == "damage" then
            Qvb = Qvb + 100 * Vvb
        elseif Uvb.type == "stat_mul" and Uvb.stat == "attack_cooldown" then
            Qvb = Qvb + 100 * Vvb / math.max(0.2, 1 - Vvb)
        elseif Uvb.type == "stat_mul" and Uvb.stat == "range" then
            Qvb = Qvb + 50 * Vvb
        elseif Uvb.type == "stat_attr_add" and Uvb.stat == "_dmg_mul_physical" then
            Qvb = Qvb + 100 * Vvb * Dungeon.share("physical")
        elseif Uvb.type == "stat_attr_add" and Uvb.stat == "_dmg_mul_magic" then
            Qvb = Qvb + 100 * Vvb * Dungeon.share("magic")
        elseif Uvb.type == "stat_attr_add" and Uvb.stat == "_dmg_mul_true_damage" then
            Qvb = Qvb + 100 * Vvb * Dungeon.share("true")
        elseif Uvb.type == "stat_add" and Uvb.stat == "physical_crit_chance" then
            Qvb = Qvb + 60 * Vvb * Dungeon.share("physical")
        elseif Uvb.type == "boss_damage" then
            Qvb = Qvb + 40 * Vvb
        elseif Uvb.type == "enemy_speedup" then
            Qvb = Qvb + 80 * Vvb
        elseif Uvb.type == "unit_cost" then
            Qvb = Qvb + 80 * Vvb
        end
    end
    return Qvb
end
Dungeon.CURSE_COST = {
    _curse_money = 0.5,
    _curse_shop = 0.5,
    _curse_health = 0.5,
    _curse_speed = 0.5,
    _curse_regen = 0.5,
    _curse_shield = 1,
    _curse_explode = 1.5,
    _curse_random = 2,
    _curse_super_health = 1,
    _curse_super_speed = 1,
    _curse_super_regen = 1,
    _curse_super_armored = 3,
    _curse_super_burst = 3,
    _curse_super_explode = 3,
    _curse_super_chaos = 3
}

function Dungeon.curseCost(Wvb)
    if Wvb == "_curse_fly" then
        local Xvb, Yvb = 0, 0
        for Zvb, _vb in ipairs(Units.equipped()) do
            local awb = _vb.id or (_vb.u and _vb.u.unit_id)
            if awb and not Units.isFarm(awb) then
                Xvb = Xvb + 1
                local bwb, cwb = pcall(Units.airFrom, awb)
                if bwb and cwb then
                    Yvb = Yvb + (cwb == 0 and 1 or 0.5)
                end
            end
        end
        return 1 + 2 * (Xvb > 0 and 1 - Yvb / Xvb or 0.5)
    end
    return Dungeon.CURSE_COST [Wvb] or 1.5
end

function Dungeon.roomValue(dwb, ewb)
    local fwb, gwb = dwb.tags, dwb.d
    local hwb = 0
    if fwb [Dungeon.T.GOLD] then
        hwb = hwb + 12
    end
    if fwb [Dungeon.T.CHEST] then
        hwb = hwb + 4
    end
    if fwb [Dungeon.T.MONEY] then
        hwb = hwb + (gwb <= 15 and 2 or 0.5)
    end
    if fwb [Dungeon.T.SHOP] then
        if gwb >= 10 and gwb <= 15 then
            hwb = hwb + (ewb >= 300 and 5 or 1)
        else
            hwb = hwb + (ewb >= 300 and (gwb > 15 and 3 or 1) or 0.3)
        end
    end
    if fwb [Dungeon.T.SHRINE] then
        hwb = hwb + 1.5
    end
    if fwb [Dungeon.T.CURSE] then
        hwb = hwb - Dungeon.curseCost(Dungeon.roomCurse(dwb.r))
    end
    return hwb
end

function Dungeon.mod(iwb)
    local jwb = {
        weak = {
        },
        strong = {
        }
    }
    for kwb, lwb in pairs(type(iwb) == "table" and type(iwb._weak_against) == "table" and iwb._weak_against or {
    }) do
        if type(lwb) == "table" and lwb.damage_type then
            jwb.weak [lwb.damage_type] = Modes.weakAmp(lwb.amplification)
        end
    end
    for mwb, nwb in pairs(type(iwb) == "table" and type(iwb._strong_against) == "table" and iwb._strong_against or {
    }) do
        jwb.strong [type(nwb) == "table" and nwb.damage_type or nwb] = true
    end
    return (next(jwb.weak) or next(jwb.strong)) and jwb or nil
end

function Dungeon.roomCurse(owb)
    local pwb = type(owb) == "table" and type(owb._t) == "table" and owb._t or {
    }
    local qwb = pwb [0] or pwb ["0"]
    return type(qwb) == "table" and qwb.id or nil
end

function Dungeon.fx(rwb, swb, twb)
    local uwb = {
        dmg = 1,
        cd = 1,
        range = 1,
        cost = 1,
        hp = 1,
        speed = 1,
        regen = 0,
        crit = 0,
        kinds = {
        },
        shield = 0,
        fly = 0
    }
    local vwb = Dungeon.items(rwb)
    if swb and Dungeon.item(swb) then
        vwb [swb] = (vwb [swb] or 0) + 1
    end
    if twb and Dungeon.item(twb) then
        vwb [twb] = (vwb [twb] or 0) + 1
    end
    for wwb, xwb in pairs(vwb) do
        local ywb = Dungeon.item(wwb)
        for zwb, Awb in pairs(type(ywb and ywb.wave_modifier_effects) == "table" and ywb.wave_modifier_effects or {
        }) do
            local Bwb = (tonumber(Awb.amount) or 0) * xwb
            if Awb.type == "stat_mul" and Awb.stat == "damage" then
                uwb.dmg = uwb.dmg + Bwb
            elseif Awb.type == "stat_mul" and Awb.stat == "attack_cooldown" then
                uwb.cd = uwb.cd + Bwb
            elseif Awb.type == "stat_mul" and Awb.stat == "range" then
                uwb.range = uwb.range + Bwb
            elseif Awb.type == "stat_attr_add" and tostring(Awb.stat):sub(1, 9) == "_dmg_mul_" then
                local Cwb = tostring(Awb.stat):sub(10)
                uwb.kinds [Cwb] = (uwb.kinds [Cwb] or 0) + Bwb
            elseif Awb.type == "stat_add" and Awb.stat == "physical_crit_chance" then
                uwb.crit = uwb.crit + Bwb
            elseif Awb.type == "unit_cost" then
                uwb.cost = uwb.cost + Bwb
            elseif Awb.type == "enemy_stat_mul" and Awb.stat == "health" then
                uwb.hp = uwb.hp + Bwb
            elseif Awb.type == "enemy_speedup" then
                uwb.speed = uwb.speed + Bwb
            elseif Awb.type == "enemy_regen" then
                uwb.regen = uwb.regen + Bwb
            elseif Awb.type == "enemy_shield" then
                uwb.shield = uwb.shield + Bwb
            elseif Awb.type == "enemy_passive_chance" and Awb.passive == "Flying" then
                uwb.fly = uwb.fly + Bwb
            end
        end
    end
    uwb.cd, uwb.cost, uwb.speed = math.max(0.1, uwb.cd), math.max(0.1, uwb.cost), math.max(0.1, uwb.speed)
    return uwb
end

function Dungeon.fxText(Dwb)
    local Ewb = {
    }
    local function Fwb(Gwb, Hwb)
        if math.abs(Hwb - 1) > 0.001 then
            table.insert(Ewb, string.format("%s ×%.2f", Gwb, Hwb))
        end
    end
    Fwb("damage", Dwb.dmg)
    Fwb("cooldown", Dwb.cd)
    Fwb("range", Dwb.range)
    Fwb("unit prices", Dwb.cost)
    for Iwb, Jwb in pairs(Dwb.kinds) do
        table.insert(Ewb, string.format("%s +%d%%", Iwb, math.floor(Jwb * 100 + 0.5)))
    end
    if Dwb.crit > 0 then
        table.insert(Ewb, string.format("physical crit +%d%%", math.floor(Dwb.crit * 100 + 0.5)))
    end
    Fwb("enemy HP", Dwb.hp)
    Fwb("enemy speed", Dwb.speed)
    if Dwb.regen > 0 then
        table.insert(Ewb, string.format("enemy regen %d%%", math.floor(Dwb.regen * 100 + 0.5)))
    end
    if Dwb.shield > 0 then
        table.insert(Ewb, string.format("enemy shield +%d", math.floor(Dwb.shield + 0.5)))
    end
    if Dwb.fly > 0 then
        table.insert(Ewb, string.format("flyers +%d%%", math.floor(Dwb.fly * 100 + 0.5)))
    end
    return # Ewb > 0 and table.concat(Ewb, ", ") or "none"
end

function Dungeon.sim(Kwb, Lwb, Mwb)
    if not Config.sim or type(Kwb.r._l) ~= "table" then
        return nil
    end
    local Nwb = tostring(Kwb.r._r or (Kwb.d .. ":" .. Kwb.choice)) .. (Lwb and ("+" .. tostring(Lwb)) or "") .. (Mwb and "#spread" or "")
    local Owb = Dungeon.data()
    local Pwb = Dungeon.fx(Owb, Dungeon.roomCurse(Kwb.r), Lwb)
    local Qwb = Modes.teamSig() .. "#" .. Dungeon.fxText(Pwb) .. (Config.killZone ~= false and "#stack" or "")
    local Rwb = Brain.dg.sim [Nwb]
    if Rwb and Rwb.sig == Qwb then
        return not Rwb.none and Rwb or nil
    end
    local Swb = {
    }
    for Twb, Uwb in ipairs(Units.equipped()) do
        table.insert(Swb, Uwb.u)
    end
    if # Swb == 0 then
        return nil
    end
    local Vwb = Simulator.applyFx(Simulator.info(Simulator.slim(Kwb.r._l), "dg", nil, Dungeon.mod(Kwb.r._l)), Pwb)
    if Mwb then
        Vwb.zone = false
    end
    local Wwb = Simulator.wave(Vwb, 1, true)
    if # Wwb == 0 then
        Rwb = {
            none = true,
            sig = Qwb,
            at = os.time()
        }
    else
        local Xwb = Simulator.evaluate(Vwb, Simulator.teamFrom(Swb, Vwb.map))
        Rwb = {
            p = Xwb.p,
            wave = Xwb.wave,
            won = Xwb.won,
            total = Vwb.total,
            margin = Xwb.margin,
            sig = Qwb,
            at = os.time()
        }
    end
    Brain.dg.sim [Nwb] = Rwb
    if Utils.count(Brain.dg.sim) > 60 then
        local Ywb, Zwb
        for _wb, axb in pairs(Brain.dg.sim) do
            if not Zwb or (axb.at or 0) < Zwb then
                Ywb, Zwb = _wb, axb.at or 0
            end
        end
        Brain.dg.sim [Ywb] = nil
    end
    App.saveSoon()
    return not Rwb.none and Rwb or nil
end

function Dungeon.winP(bxb)
    local cxb = tostring(math.min(4, math.max(1, math.ceil(bxb.d / 5))))
    local dxb = Brain.dg.depth [cxb] or {
        runs = 0,
        wins = 0
    }
    local exb = Utils.clamp(0.95 - 0.015 * bxb.d, 0.5, 0.95)
    local fxb = ((tonumber(dxb.wins) or 0) + exb * 2) / ((tonumber(dxb.runs) or 0) + 2)
    local gxb, hxb = pcall(Dungeon.sim, bxb)
    if gxb and hxb and hxb.p then
        fxb = (fxb * 2 + hxb.p) / 3
    end
    return fxb, gxb and hxb or nil
end

function Dungeon.hopeless(ixb)
    return ixb ~= nil and ixb.won == false and (tonumber(ixb.p) or 1) <= 0.05
end

function Dungeon.stake(jxb)
    local kxb, lxb, mxb = Dungeon.res(jxb)
    return lxb + 2 * mxb
end

function Dungeon.curseBar(nxb, oxb)
    local pxb = Dungeon.stake(nxb)
    if oxb >= 15 or pxb >= 8 then
        return 0.9, "beat them against 30% tougher enemies", pxb
    end
    if oxb >= 10 or pxb >= 4 then
        return 0.6, "beat them", pxb
    end
    return 0.1, "have a chance at them", pxb
end

function Dungeon.blindCurse(qxb, rxb)
    return Dungeon.fxText(Dungeon.fx(qxb, rxb)) == Dungeon.fxText(Dungeon.fx(qxb))
end

function Dungeon.curseOk(sxb, txb, uxb, vxb, wxb)
    local xxb = tostring((Dungeon.item(sxb) or {
    }).name or sxb)
    local yxb, zxb, Axb = Dungeon.curseBar(txb, uxb)
    if yxb > 0.2 and Dungeon.blindCurse(txb, sxb) then
        return false, string.format("the simulator can't play %s, and %d chests are riding on the run", xxb, Axb)
    end
    local function Bxb(Cxb)
        return Cxb == nil or (tonumber(Cxb.p) or 1) >= yxb
    end
    if vxb then
        local Dxb, Exb = pcall(Dungeon.sim, vxb, nil, true)
        if Dxb and not Bxb(Exb) then
            return false, string.format("with %s your team wouldn't %s (this room: %s)", xxb, (zxb:gsub("them", "this room")), tostring(Exb.margin or "?"))
        end
    end
    if # wxb == 0 then
        return true
    end
    local Fxb
    for Gxb, Hxb in ipairs(wxb) do
        local Ixb, Jxb = pcall(Dungeon.sim, Hxb, sxb, true)
        if not Ixb or Bxb(Jxb) then
            return true
        end
        if not Fxb or (tonumber(Jxb.p) or 0) > (tonumber(Fxb.p) or 0) then
            Fxb = Jxb
        end
    end
    return false, string.format("with %s your team wouldn't %s (the rooms after it, at best: %s)", xxb, zxb, tostring(Fxb and Fxb.margin or "?"))
end

function Dungeon.curseGate(Kxb, Lxb)
    local Mxb = Dungeon.roomCurse(Kxb.r)
    if not Mxb then
        return true
    end
    return Dungeon.curseOk(Mxb, Lxb, Kxb.d, Kxb, Dungeon.after(Lxb, Kxb.choice))
end

function Dungeon.payValue()
    local Nxb, Oxb = 0, 0
    for Pxb, Qxb in ipairs(Brain.dg.pay or {
    }) do
        if type(Qxb.items) == "table" then
            local Rxb = tonumber(Qxb.gems) or 0
            for Sxb, Txb in pairs(Qxb.items) do
                if (tonumber(Txb) or 0) > 0 then
                    Rxb = Rxb + Modes.itemValue(Sxb, Txb)
                end
            end
            Nxb, Oxb = Nxb + Rxb, Oxb + 1
        end
    end
    if Oxb < 5 then
        return nil
    end
    return Nxb / Oxb * 0.7
end

function Dungeon.pick(Uxb)
    local Vxb, Wxb = Dungeon.curses(Uxb), Dungeon.lives(Uxb)
    local Xxb = Dungeon.res(Uxb)
    local Yxb = Dungeon.rooms(Uxb)
    local Zxb = {
    }
    for _xb, ayb in ipairs(Yxb) do
        table.insert(Zxb, tostring(ayb.r._r))
    end
    local byb = table.concat(Zxb, ",") .. string.format("|%d|%d|%d|%s", Wxb, Xxb, Vxb, Modes.teamSig())
    if Dungeon._pick and Dungeon._pick.sig == byb then
        return Dungeon._pick.x
    end
    local cyb, dyb
    for eyb, fyb in ipairs(Yxb) do
        local gyb = Dungeon.roomValue(fyb, Xxb)
        local hyb, iyb
        for jyb, kyb in ipairs(Dungeon.after(Uxb, fyb.choice)) do
            local lyb = Dungeon.roomValue(kyb, Xxb)
            if not hyb or lyb > hyb then
                hyb, iyb = lyb, kyb
            end
        end
        local myb, nyb = Dungeon.winP(fyb)
        local oyb = 1 - (1 - myb) ^ math.max(1, Wxb)
        local pyb = Wxb >= 3 and 1 or (Wxb == 2 and 2 or 6)
        fyb.p, fyb.sim, fyb.value, fyb.nextValue, fyb.nextRoom = myb, nyb, gyb, hyb or 0, iyb
        fyb.score = oyb * (gyb + 0.6 * (hyb or 0)) - (1 - myb) * pyb
        local qyb, ryb, syb = pcall(Dungeon.curseGate, fyb, Uxb)
        if qyb and not ryb then
            fyb.blocked = syb
        end
        if not fyb.blocked and (not cyb or fyb.score > cyb.score) then
            cyb = fyb
        end
        if not dyb or fyb.score > dyb.score then
            dyb = fyb
        end
    end
    cyb = cyb or dyb
    Dungeon._pick = {
        sig = byb,
        x = cyb,
        rooms = Yxb
    }
    return cyb
end

function Dungeon.roomName(tyb)
    local uyb = type(tyb.r._l) == "table" and tyb.r._l or {
    }
    return string.format("%s (%s)", tostring(uyb._location_name or uyb.map or "?"), Dungeon.tagText(tyb.tags))
end

function Dungeon.screens(vyb)
    local wyb = {
    }
    for xyb, yyb in pairs(type(vyb.current_shops) == "table" and vyb.current_shops or {
    }) do
        if type(yyb) == "table" then
            table.insert(wyb, {
                i = tonumber(xyb) or 0,
                t = tonumber(yyb._t),
                data = yyb.data
            })
        end
    end
    table.sort(wyb, function(zyb, Ayb)
        return zyb.i < Ayb.i
    end)
    return wyb
end

function Dungeon.cleared(Byb)
    return math.max(1, (Dungeon.depth(Byb) or (Dungeon.ROOMS + 1)) - 1)
end

function Dungeon.state(Cyb)
    if Cyb._dead then
        return "dead"
    end
    if Cyb._finished then
        return "finished"
    end
    local Dyb = Dungeon.screens(Cyb) [1]
    if Dyb then
        if Dyb.t == Dungeon.T.SHOP then
            return "shop", Dyb
        end
        if Dyb.t == Dungeon.T.OPEN then
            return "chests", Dyb
        end
        if Dyb.t == Dungeon.T.SHRINE then
            return "shrine", Dyb
        end
        return "screen", Dyb
    end
    return "rooms"
end

function Dungeon.logState(Eyb, Fyb)
    local Gyb = {
    }
    for Hyb, Iyb in pairs(Eyb) do
        if not Dungeon.KNOWN [Hyb] and not (type(Iyb) == "table" and next(Iyb) == nil) then
            table.insert(Gyb, tostring(Hyb))
        end
    end
    table.sort(Gyb)
    local Jyb = {
    }
    for Kyb, Lyb in ipairs(Dungeon.screens(Eyb)) do
        table.insert(Jyb, tostring(Lyb.t))
    end
    local Myb = table.concat(Gyb, ",") .. (# Jyb > 0 and ("|" .. table.concat(Jyb, ",")) or "")
    if Myb == "" or Brain.dg.seen [Myb] then
        return
    end
    Brain.dg.seen [Myb] = os.time()
    local Nyb = {
    }
    for Oyb, Pyb in ipairs(Gyb) do
        local Qyb = Eyb [Pyb]
        table.insert(Nyb, Pyb .. "=" .. (type(Qyb) == "table" and Utils.json(Utils.plain(Qyb)):sub(1, 500) or tostring(Qyb)))
    end
    App.log(1, "DUNGEON", "new screen (" .. tostring(Fyb) .. "): " .. table.concat(Nyb, " · "))
    App.saveSoon()
end

function Dungeon.note(Ryb)
    App.log(1, "DUNGEON", Ryb)
    table.insert(Brain.dg.log, 1, {
        at = os.time(),
        msg = Ryb
    })
    while # Brain.dg.log > 15 do
        table.remove(Brain.dg.log)
    end
    App.saveSoon()
end

function Dungeon.offers(Syb, Tyb)
    local Uyb = {
    }
    if type(Syb) ~= "table" then
        return Uyb
    end
    for Vyb, Wyb in pairs(Syb) do
        local Xyb, Yyb
        if type(Wyb) == "table" then
            Xyb = Wyb.id or Wyb.item_id or Wyb.item
            Yyb = tonumber(Wyb.cost) or tonumber(Wyb.price)
        elseif type(Wyb) == "string" then
            Xyb = Wyb
        elseif Dungeon.item(Vyb) then
            Xyb = Vyb
            Yyb = tonumber(Wyb)
        end
        if type(Xyb) == "string" and Dungeon.item(Xyb) then
            table.insert(Uyb, {
                key = Vyb,
                id = Xyb,
                cost = Yyb or tonumber(Dungeon.item(Xyb).cost) or 0,
                bought = type(Wyb) == "table" and (Wyb.bought or Wyb.sold or Wyb.purchased) or nil
            })
        end
    end
    if # Uyb == 0 and not Tyb then
        for Zyb, _yb in pairs(Syb) do
            if type(_yb) == "table" then
                Uyb = Dungeon.offers(_yb, true)
                if # Uyb > 0 then
                    break
                end
            end
        end
    end
    return Uyb
end

function Dungeon.buy(azb)
    local bzb = Dungeon.res(Dungeon.data())
    local czb = {
    }
    if Brain.dg.buyArg == "id" then
        czb = {
            azb.id,
            azb.key
        }
    else
        czb = {
            azb.key,
            azb.id
        }
    end
    if czb [1] == czb [2] then
        czb [2] = nil
    end
    for dzb, ezb in ipairs(czb) do
        local fzb, gzb = App.request("dgBuy", "dungeon_buy_shop", ezb)
        local hzb = Utils.now()
        while Utils.now() - hzb < 3 and Dungeon.res(Dungeon.data()) >= bzb do
            task.wait(0.25)
        end
        if Dungeon.res(Dungeon.data()) < bzb then
            Brain.dg.buyArg = (ezb == azb.id and azb.id ~= azb.key) and "id" or "key"
            return true
        end
        if not fzb then
            break
        end
    end
    return false
end

function Dungeon.shopAhead(izb)
    for jzb, kzb in ipairs(Dungeon.rooms(izb)) do
        if kzb.tags [Dungeon.T.SHOP] then
            return true
        end
        for lzb, mzb in ipairs(Dungeon.after(izb, kzb.choice)) do
            if mzb.tags [Dungeon.T.SHOP] then
                return true
            end
        end
    end
    return false
end
Dungeon.LUCK_RESERVE = 500
Dungeon.MIN_WORTH = 0.02
Dungeon.TOP_WORTH = 0.08

function Dungeon.shop(nzb, ozb)
    local pzb = Dungeon.cleared(nzb)
    local qzb = Dungeon.res(nzb)
    local rzb = 1 + 0.1 * (Dungeon.items(nzb)._curse_shop or 0)
    local szb = Dungeon.shopAhead(nzb) and math.ceil(Dungeon.LUCK_RESERVE * rzb) or 0
    local tzb = {
    }
    local uzb, vzb = {
    }, 0
    for wzb, xzb in ipairs(Dungeon.offers(ozb and ozb.data)) do
        xzb.cost = math.ceil(xzb.cost * rzb)
        table.insert(uzb, tostring(Dungeon.item(xzb.id).name or xzb.id))
        if not xzb.bought and not Dungeon.isCurse(xzb.id) then
            xzb.luck = tonumber(Dungeon.item(xzb.id).luck_increase) ~= nil
            xzb.v = Dungeon.itemValue(xzb.id, nzb)
            if not xzb.luck and xzb.v / math.max(1, xzb.cost) < Dungeon.MIN_WORTH then
                vzb = vzb + 1
            elseif xzb.v > 0 and (xzb.luck or pzb >= 10 or xzb.v / math.max(1, xzb.cost) >= Dungeon.TOP_WORTH) then
                table.insert(tzb, xzb)
            end
        end
    end
    table.sort(tzb, function(yzb, zzb)
        if yzb.luck ~= zzb.luck then
            return yzb.luck
        end
        return yzb.v / math.max(1, yzb.cost) > zzb.v / math.max(1, zzb.cost)
    end)
    local Azb, Bzb, Czb = {
    }, 0, 0
    for Dzb, Ezb in ipairs(tzb) do
        if Ezb.cost <= qzb - (Ezb.luck and 0 or szb) then
            if Dungeon.buy(Ezb) then
                qzb = Dungeon.res(Dungeon.data())
                table.insert(Azb, string.format("%s (%d coins)", tostring(Dungeon.item(Ezb.id).name or Ezb.id), Ezb.cost))
            end
        elseif Ezb.cost <= qzb then
            Czb = Czb + 1
        else
            Bzb = Bzb + 1
        end
    end
    Dungeon.note(string.format("shop at depth %d (%s): %s · %d coins left%s%s%s", pzb, # uzb > 0 and table.concat(uzb, ", ") or "offer not read", # Azb > 0 and ("bought " .. table.concat(Azb, ", ")) or (pzb < 10 and "no chest luck on sale: coins kept for the shops at floors 10–15" or (Czb > 0 and "nothing bought" or "nothing worth buying")), qzb, Bzb > 0 and string.format(" (%d too dear)", Bzb) or "", Czb > 0 and string.format(" (%d left on the shelf: %d coins kept for chest luck, a shop room is ahead)", Czb, szb) or "", vzb > 0 and string.format(" (%d would do nothing for this team's damage type)", vzb) or ""))
    App.request("dgCont", "dungeon_continue_shop")
end

function Dungeon.shrine(Fzb, Gzb)
    local Hzb = Dungeon.offers(Gzb and Gzb.data)
    local Izb, Jzb = 0, {
    }
    local Kzb
    for Lzb, Mzb in ipairs(Hzb) do
        local Nzb = Dungeon.item(Mzb.id)
        table.insert(Jzb, tostring(Nzb and Nzb.name or Mzb.id))
        if Dungeon.isCurse(Mzb.id) then
            local Ozb, Pzb, Qzb = pcall(Dungeon.curseOk, Mzb.id, Fzb, Dungeon.cleared(Fzb) + 1, nil, Dungeon.rooms(Fzb))
            if Ozb and not Pzb then
                Kzb = Qzb
            end
        else
            Izb = Izb + Dungeon.itemValue(Mzb.id, Fzb)
        end
    end
    local Rzb = # Hzb > 0 and Izb > 0 and not Kzb
    if Rzb then
        App.request("dgShrine", "dungeon_shrine_accept")
    else
        App.request("dgCont", "dungeon_continue_shop")
    end
    Dungeon.note(string.format("shrine (%s): %s", # Jzb > 0 and table.concat(Jzb, ", ") or "offer not read", Rzb and "taken" or (Kzb and ("passed: " .. Kzb) or "passed")))
end

function Dungeon.wallet()
    local Szb = Core.session() and Core.session().profile_data or {
    }
    local Tzb = Szb.inventory or {
    }
    local Uzb = {
        gems = tonumber(Core.cur("gems")) or 0,
        gold = tonumber(Core.cur("gold")) or 0,
        items = {
        },
        units = {
        },
        unique = 0
    }
    for Vzb, Wzb in pairs(Tzb.normal_items or {
    }) do
        Uzb.items [Vzb] = tonumber(Wzb) or 0
    end
    for Xzb, Yzb in pairs(Szb.collection and Szb.collection.owned_units or {
    }) do
        Uzb.units [Xzb] = Yzb.unit_id
    end
    for Zzb in pairs(Tzb.unique_items or {
    }) do
        Uzb.unique = Uzb.unique + 1
    end
    return Uzb
end

function Dungeon.walletDiff(_zb, aAb)
    local bAb = {
    }
    if aAb.gems ~= _zb.gems then
        table.insert(bAb, string.format("%+d gems", aAb.gems - _zb.gems))
    end
    if aAb.gold ~= _zb.gold then
        table.insert(bAb, string.format("%+d gold", aAb.gold - _zb.gold))
    end
    for cAb, dAb in pairs(aAb.items) do
        if dAb ~= (_zb.items [cAb] or 0) then
            table.insert(bAb, string.format("%+d %s", dAb - (_zb.items [cAb] or 0), tostring(cAb)))
        end
    end
    for eAb, fAb in pairs(aAb.units) do
        if not _zb.units [eAb] then
            table.insert(bAb, "new unit " .. Units.name(fAb))
        end
    end
    if aAb.unique ~= _zb.unique then
        table.insert(bAb, string.format("%+d relics", aAb.unique - _zb.unique))
    end
    return # bAb > 0 and table.concat(bAb, ", ") or "nothing seen"
end

function Dungeon.openChests(gAb, hAb)
    local iAb, jAb, kAb = Dungeon.res(gAb)
    local lAb = Dungeon.lives(gAb)
    local mAb = Dungeon.cleared(gAb)
    if not (hAb or mAb >= Dungeon.ROOMS or lAb <= 1) then
        Dungeon.note(string.format("chest room at depth %d: keeping %d chests and %d rare chests for floor 20 (luck ×%.1f now)", mAb, jAb, kAb, Dungeon.luck(gAb)))
        App.request("dgCont", "dungeon_continue_shop")
        return
    end
    local nAb, oAb, pAb = 0, 0, 0
    local qAb = tonumber(Core.cur("gems")) or 0
    local rAb = Dungeon.wallet()
    for sAb = 1, jAb + kAb + 4 do
        local tAb, uAb, vAb = Dungeon.res(Dungeon.data())
        if uAb + vAb <= 0 or pAb >= 2 then
            break
        end
        local wAb, xAb
        if uAb > 0 then
            wAb, xAb = App.request("dgChest", "dungeon_open_chest")
        else
            wAb, xAb = App.request("dgChest", "dungeon_open_chest", true)
        end
        if wAb and xAb ~= nil then
            App.log(1, "DUNGEON", "chest: " .. (type(xAb) == "table" and Utils.json(Utils.plain(xAb)):sub(1, 300) or tostring(xAb)))
        end
        local yAb = Utils.now()
        while Utils.now() - yAb < 4 do
            local zAb, AAb, BAb = Dungeon.res(Dungeon.data())
            if AAb < uAb or BAb < vAb then
                break
            end
            task.wait(0.25)
        end
        local CAb, DAb, EAb = Dungeon.res(Dungeon.data())
        if DAb < uAb then
            nAb = nAb + (uAb - DAb)
            pAb = 0
        elseif EAb < vAb then
            oAb = oAb + (vAb - EAb)
            pAb = 0
        else
            pAb = pAb + 1
        end
        task.wait(1)
        if DAb < uAb or EAb < vAb then
            local FAb = Dungeon.wallet()
            local GAb = Dungeon.walletDiff(rAb, FAb)
            App.log(1, "DUNGEON", (EAb < vAb and "rare chest: " or "chest: ") .. GAb)
            Brain.dg.pay = Brain.dg.pay or {
            }
            local HAb = {
            }
            for IAb, JAb in pairs(FAb.items) do
                if JAb ~= (rAb.items [IAb] or 0) then
                    HAb [IAb] = JAb - (rAb.items [IAb] or 0)
                end
            end
            table.insert(Brain.dg.pay, {
                at = os.time(),
                rare = EAb < vAb,
                gems = FAb.gems - rAb.gems,
                luck = Dungeon.luck(gAb),
                paid = GAb,
                items = HAb
            })
            while # Brain.dg.pay > 60 do
                table.remove(Brain.dg.pay, 1)
            end
            rAb = FAb
        end
    end
    Dungeon.note(string.format("opened %d chests and %d rare chests (%s, luck ×%.1f) · gems %+d", nAb, oAb, hAb and "last room" or (lAb <= 1 and "one life left" or "floor 20"), Dungeon.luck(gAb), (tonumber(Core.cur("gems")) or 0) - qAb))
    local KAb, LAb, MAb = Dungeon.res(Dungeon.data())
    if (hAb or mAb >= Dungeon.ROOMS) and LAb + MAb > 0 then
        Dungeon.note(string.format("%d chests and %d rare chests didn't open: the last room stays open, trying again in 30 min", LAb, MAb))
        Modes.rec("dg").restUntil = os.time() + 1800
        return "hold"
    end
    if not hAb then
        App.request("dgCont", "dungeon_continue_shop")
    end
end

function Dungeon.act(NAb)
    local OAb, PAb = Dungeon.state(NAb)
    Dungeon.logState(NAb, OAb)
    if OAb == "rooms" then
        return false
    end
    if OAb == "screen" then
        Dungeon.note(string.format("a screen of a kind not known yet (tag %s): closed with Continue", tostring(PAb and PAb.t)))
        App.request("dgCont", "dungeon_continue_shop")
        return true
    end
    if OAb == "dead" then
        App.request("dgDeath", "dungeon_continue_death")
        Dungeon.note("the run is over: that was the last life, and its unopened chests went with it")
        Brain.dg.lives, Brain.dg.lost = 5, {
        }
    elseif OAb == "finished" then
        if Dungeon.openChests(NAb, true) == "hold" then
            return "hold"
        end
        App.request("dgCont", "dungeon_continue_shop")
        local QAb, RAb, SAb = Dungeon.res(Dungeon.data())
        table.insert(Brain.dg.runs, 1, {
            at = os.time(),
            depth = Dungeon.ROOMS,
            items = Utils.count(Dungeon.items(NAb)),
            left = RAb + SAb
        })
        while # Brain.dg.runs > 10 do
            table.remove(Brain.dg.runs)
        end
        Dungeon.note("dungeon finished: all 20 rooms")
    elseif OAb == "shop" then
        Dungeon.shop(NAb, PAb)
    elseif OAb == "shrine" then
        Dungeon.shrine(NAb, PAb)
    elseif OAb == "chests" then
        if Dungeon.openChests(NAb, false) == "hold" then
            return "hold"
        end
    end
    return true
end

function Dungeon.launch(TAb)
    local UAb = Dungeon.data()
    if not UAb then
        App.backoff("launch", 30)
        return false
    end
    if not UAb._started then
        if not (Config.dungeonStart or Config.onlyDungeons) then
            return false
        end
        local VAb, WAb = App.request("dgStart", "dungeon_start")
        task.wait(2.5)
        UAb = Dungeon.data()
        if not (VAb and UAb and UAb._started) then
            App.log(1, "DUNGEON", "the game didn't start a dungeon run (" .. tostring(WAb) .. "): trying again in 30 min")
            Modes.rec("dg").restUntil = os.time() + 1800
            App.backoff("launch", 10)
            return false
        end
        Brain.dg.lost = {
        }
        Dungeon.note("new dungeon run started (4 lives)")
    end
    if Dungeon.enter(UAb, TAb.value, false) then
        return true
    end
    App.backoff("launch", 10)
    return false
end

function Dungeon.playLast()
    local XAb = Brain.dg.playLast
    return type(XAb) == "table" and os.time() - (tonumber(XAb.at) or 0) < 1800 and XAb or nil
end

function Dungeon.forced(YAb)
    local ZAb = Brain.dg.force
    if type(ZAb) ~= "table" or type(ZAb.uuids) ~= "table" or ZAb.seed ~= tostring(YAb.r._r) then
        return nil
    end
    if os.time() - (tonumber(ZAb.at) or 0) > 3600 then
        Brain.dg.force = nil
        return nil
    end
    return ZAb
end

function Dungeon.startTeam(_Ab, aBb, bBb, cBb)
    Brain.startTeam = {
        uuids = table.clone(_Ab),
        must = true,
        own = cBb or nil,
        seed = tostring(aBb.r._r),
        why = bBb
    }
end

function Dungeon.planTeam(dBb, eBb, fBb)
    if not (Config.sim and Config.simTeams) or type(dBb.r._l) ~= "table" then
        return
    end
    if Dungeon.playLast() then
        App.log(1, "SIM", string.format("dungeon room %d: your own pick stays, no search", dBb.d))
        return
    end
    local gBb = Dungeon.forced(dBb)
    if gBb then
        if fBb then
            App.log(1, "SIM", string.format("dungeon room %d: your call — %s goes in as the room starts, no search", dBb.d, tostring(gBb.label)))
            if not Training.same(Training.team(), gBb.uuids) then
                Dungeon.startTeam(gBb.uuids, dBb, tostring(gBb.label))
            end
            return
        end
        App.log(1, "SIM", string.format("dungeon room %d: your call — %s goes in, no search", dBb.d, tostring(gBb.label)))
        FarmHub.equipTeam(gBb.uuids, tostring(gBb.label))
        task.wait(0.5)
        return
    end
    if fBb and not Config.autoTeam then
        return
    end
    local hBb = Brain.simTeam.dg
    if not fBb and Config.autoTeam and hBb and hBb.better and hBb.seed == tostring(dBb.r._r) and os.time() - (tonumber(hBb.at) or 0) < 300 then
        FarmHub.equipTeam(hBb.uuids, "the best team found for dungeon room " .. dBb.d)
        task.wait(0.5)
        return
    end
    local iBb = Dungeon.fx(eBb, Dungeon.roomCurse(dBb.r))
    local jBb = {
    }
    if fBb and type(Brain.savedTeam) == "table" and # Brain.savedTeam > 0 then
        local kBb = Core.session()
        for lBb, mBb in ipairs(Brain.savedTeam) do
            local nBb = kBb.collection:get_unit_by_uuid(mBb)
            if nBb then
                table.insert(jBb, nBb)
            end
        end
    else
        for oBb, pBb in ipairs(Units.equipped()) do
            table.insert(jBb, pBb.u)
        end
    end
    if # jBb == 0 then
        return
    end
    local qBb = Dungeon.mod(dBb.r._l)
    local rBb = Simulator.applyFx(Simulator.info(Simulator.slim(dBb.r._l), "dg", nil, qBb), iBb)
    App.status("Mode", "looking for the best team for dungeon room " .. dBb.d)
    Simulator.memoOn()
    local sBb = Simulator.pool(qBb, rBb)
    local tBb, uBb, vBb, wBb = Simulator.bestTeam(rBb, jBb, sBb, Dungeon.lives(eBb) <= 1 and 45 or 20)
    local function xBb(yBb)
        local zBb = Simulator.sig(yBb)
        local ABb = type(Brain.dg.teams) == "table" and Brain.dg.teams [zBb] or {
        }
        local BBb = type(Brain.dg.lost) == "table" and Brain.dg.lost [tostring(dBb.r._r)] and Brain.dg.lost [tostring(dBb.r._r)] [zBb] or 0
        if type(Brain.dg.bail) == "table" and Brain.dg.bail.sig == zBb and os.time() - (tonumber(Brain.dg.bail.at) or 0) < 1800 then
            BBb = BBb + 1
        end
        local CBb, DBb, EBb, FBb = Simulator.strength(rBb, yBb)
        local GBb = math.clamp((tonumber(ABb.w) or 0) - 2 * (tonumber(ABb.l) or 0), - 6, 3)
        if dBb.d >= 13 then
            GBb = math.min(GBb, 1)
        end
        GBb = GBb - 3 * BBb
        return {
            score = CBb + GBb,
            wins = CBb,
            atOne = DBb,
            reach = EBb,
            far = FBb,
            lostHere = BBb,
            w = tonumber(ABb.w) or 0,
            l = tonumber(ABb.l) or 0
        }
    end
    local HBb = Simulator.sig(tBb) == Simulator.sig(jBb)
    local IBb = xBb(jBb)
    local JBb = HBb and IBb or xBb(tBb)
    if (rBb.regen or 0) > 0 then
        local KBb = false
        for LBb, MBb in ipairs(jBb) do
            if Units.bleeds(MBb.unit_id) then
                KBb = true
            end
        end
        for NBb, OBb in ipairs(tBb) do
            if Units.bleeds(OBb.unit_id) then
                KBb = true
            end
        end
        local PBb = not KBb and Units.bestBleeder(jBb) or nil
        if PBb then
            local QBb = {
            }
            for RBb, SBb in ipairs(jBb) do
                if not Units.isFarm(SBb.unit_id) and not Units.allyBuff(SBb.unit_id) then
                    local TBb = table.clone(jBb)
                    TBb [RBb] = PBb
                    local UBb = xBb(TBb)
                    table.insert(QBb, string.format("%s out: %d tries", Units.name(SBb.unit_id), UBb.wins))
                    if UBb.score > JBb.score then
                        tBb, JBb, HBb = TBb, UBb, false
                        uBb = {
                            won = UBb.wins > 0,
                            wave = UBb.reach
                        }
                    end
                    task.wait()
                end
            end
            App.log(1, "SIM", string.format("dungeon room %d: enemies regenerate, so %s (bleeds from upgrade %d) was tried in each slot: %s", dBb.d, Units.name(PBb.unit_id), Units.bleeds(PBb.unit_id) or 0, table.concat(QBb, " · ")))
        end
    end
    Simulator.memo = nil
    local VBb = JBb.wins > IBb.wins or (JBb.wins == IBb.wins and (JBb.far or 0) > (IBb.far or 0))
    local WBb = not HBb and VBb and JBb.lostHere <= IBb.lostHere
    local XBb, YBb = {
    }, {
    }
    for ZBb, _Bb in ipairs(tBb) do
        table.insert(XBb, _Bb.uuid)
        table.insert(YBb, Units.name(_Bb.unit_id))
    end
    Brain.simTeam.dg = {
        uuids = XBb,
        names = YBb,
        won = uBb.won,
        wave = uBb.wave,
        better = WBb,
        cur = {
            won = wBb.won,
            wave = wBb.wave
        },
        at = os.time(),
        label = "Dungeon",
        seed = tostring(dBb.r._r)
    }
    local function aCb(bCb)
        return string.format("wins %d simulated tries up the rising test, gets to wave %d at normal strength, real rooms %d won and %d lost", bCb.wins, math.floor(bCb.reach + 0.5), bCb.w, bCb.l)
    end
    if not WBb then
        if HBb then
            App.log(1, "SIM", string.format("dungeon room %d: tried %d units, none beats your team (%s)", dBb.d, # sBb, aCb(IBb)))
        elseif not VBb then
            App.log(1, "SIM", string.format("dungeon room %d: your team goes in (%s): the search's pick, %s, doesn't go further up the rising test (%s)", dBb.d, aCb(IBb), table.concat(YBb, ", "), aCb(JBb)))
        else
            App.log(1, "SIM", string.format("dungeon room %d: your team goes in (%s): the search's pick, %s, already lost here %d times (%s)", dBb.d, aCb(IBb), table.concat(YBb, ", "), JBb.lostHere, aCb(JBb)))
        end
        if fBb and type(Brain.savedTeam) == "table" and not Training.same(Training.team(), Brain.savedTeam) then
            Dungeon.startTeam(Brain.savedTeam, dBb, "your own team back for dungeon room " .. dBb.d, true)
        end
        return
    end
    App.log(1, "SIM", string.format("dungeon room %d: the search's top pick: %s (%s; yours: %s)", dBb.d, table.concat(YBb, ", "), aCb(JBb), aCb(IBb)))
    if fBb then
        if not Training.same(Training.team(), XBb) then
            Dungeon.startTeam(XBb, dBb, "the simulator's best team for dungeon room " .. dBb.d)
        end
        return
    end
    if Config.autoTeam then
        FarmHub.equipTeam(XBb, "the simulator's best team for dungeon room " .. dBb.d)
        task.wait(0.5)
    else
        App.log(1, "SIM", "Auto-Equip Best Team is off, so your team stays as it is")
    end
end

function Dungeon.enter(cCb, dCb, eCb)
    for fCb = 1, 5 do
        local gCb, hCb = pcall(Dungeon.act, cCb)
        if not gCb then
            App.log(1, "ERROR", "dungeon screen: " .. tostring(hCb))
            break
        end
        if hCb == "hold" then
            return false
        end
        if not hCb then
            break
        end
        task.wait(2)
        cCb = Dungeon.data()
        if not (cCb and cCb._started) then
            return false
        end
    end
    Dungeon._pick = nil
    local iCb = Dungeon.pick(cCb)
    if not iCb then
        Dungeon.logState(cCb, "no rooms on offer")
        local jCb, kCb, lCb = Dungeon.res(cCb)
        if kCb + lCb > 0 then
            App.log(1, "DUNGEON", string.format("no room on offer and %d + %d chests unopened: nothing pressed, trying again in 30 min", kCb, lCb))
            Modes.rec("dg").restUntil = os.time() + 1800
            return false
        end
        App.log(1, "DUNGEON", "no room on offer: leaving the screen it's on")
        App.request("dgCont", "dungeon_continue_shop")
        return false
    end
    local mCb, nCb = pcall(Dungeon.planTeam, iCb, cCb, eCb)
    if not mCb then
        App.log(1, "ERROR", "dungeon team: " .. tostring(nCb))
    end
    if not eCb then
        local oCb = Brain.simTeam.dg
        local pCb = tostring(iCb.r._r)
        Brain.dg.swapFail = type(Brain.dg.swapFail) == "table" and Brain.dg.swapFail or {
        }
        local qCb = tonumber(Brain.dg.swapFail [pCb]) or 0
        local rCb = Dungeon.forced(iCb)
        local sCb = (rCb and rCb.uuids) or ((oCb and oCb.better and oCb.seed == pCb and qCb < 2) and oCb.uuids) or Brain.savedTeam
        local tCb = Training.team()
        local uCb = # tCb == 6 and (not sCb or Training.same(tCb, sCb))
        if not uCb then
            Brain.dg.swapFail [pCb] = qCb + 1
            local vCb = {
            }
            for wCb, xCb in ipairs(Units.equipped()) do
                table.insert(vCb, Units.name(xCb.id))
            end
            if qCb + 1 >= 2 and oCb and oCb.better and oCb.seed == pCb then
                oCb.better = false
                App.log(1, "TEAM", string.format("the planned team for room %d wouldn't equip twice: your own team goes in instead", iCb.d))
                pcall(FarmHub.restoreTeam)
            end
            App.log(1, "DUNGEON", string.format("room %d not entered: the team isn't right yet (%d units: %s). Trying the swap again in a moment", iCb.d, # tCb, table.concat(vCb, ", ")))
            App.status("Mode", "waiting for the right team before dungeon room " .. iCb.d)
            Modes.rec("dg").restUntil = os.time() + 45
            Brain.pending = nil
            App.saveSoon()
            return false
        end
        Brain.dg.swapFail [pCb] = nil
        local yCb, zCb = pcall(Strategy.relicsApply)
        if not yCb then
            App.log(1, "ERROR", "relics: " .. tostring(zCb))
        end
    end
    if Dungeon.lives(cCb) <= 1 then
        Brain.dg.lost = Brain.dg.lost or {
        }
        local ACb = Dungeon.sim(iCb)
        local BCb = (Brain.dg.lost [tostring(iCb.r._r)] or {
        }) [Modes.teamSig()] or 0
        local CCb = # Units.equipped() < 6
        if (not ACb or BCb >= 2 or CCb) and not (Dungeon.playLast() and not CCb) then
            local DCb = CCb and string.format("the team has only %d units", # Units.equipped()) or BCb >= 2 and string.format("this team already lost here %d times", BCb) or "the simulator can't play this room"
            Dungeon.note(string.format("last life on room %d: holding it (%s). Looks again in an hour", iCb.d, DCb))
            Modes.rec("dg").restUntil = os.time() + 3600
            Brain.pending = nil
            App.saveSoon()
            return false
        end
    end
    Brain.dg.room = {
        seed = iCb.r._r,
        d = iCb.d
    }
    Brain.pending = {
        key = "dg",
        kind = "dungeon",
        level = "dungeon",
        diff = "Hard",
        label = "Dungeon room " .. iCb.d,
        at = os.time(),
        value = dCb,
        depth = iCb.d
    }
    if Brain.nextMode == "dg" then
        Brain.nextMode = nil
    end
    local ECb, FCb, GCb = Dungeon.res(cCb)
    local HCb = string.format("win ≈%d%%%s · leads to %s · %d lives · %d coins · chests %d + %d rare", math.floor(iCb.p * 100 + 0.5), iCb.sim and (" (sim: " .. tostring(iCb.sim.margin) .. ")") or "", iCb.nextRoom and Dungeon.roomName(iCb.nextRoom) or "the last room", Dungeon.lives(cCb), ECb, FCb, GCb)
    App.log(1, "MODE", string.format("entering dungeon room %d/%d%s: %s — %s", iCb.d, Dungeon.ROOMS, eCb and " from the results screen" or "", Dungeon.roomName(iCb), HCb))
    local ICb = {
    }
    for JCb, KCb in ipairs(Dungeon._pick and Dungeon._pick.rooms or {
    }) do
        if KCb ~= iCb then
            table.insert(ICb, string.format("%s, win ≈%d%%%s", Dungeon.roomName(KCb), math.floor((KCb.p or 0) * 100 + 0.5), KCb.blocked and (" (skipped: " .. KCb.blocked .. ")") or ""))
        end
    end
    if # ICb > 0 then
        App.log(1, "DUNGEON", "chosen over: " .. table.concat(ICb, " · "))
    end
    App.saveNow()
    App.status("Mode", "entering dungeon room " .. iCb.d)
    local LCb = type(cCb.selected_next) == "table" and cCb.selected_next.choice_str and tostring(cCb.selected_next.choice_str) or nil
    local MCb = {
        tostring(iCb.key)
    }
    if LCb and LCb ~= tostring(iCb.key) and not eCb then
        table.insert(MCb, LCb)
    end
    for NCb, OCb in ipairs(MCb) do
        if NCb == 2 then
            local PCb
            for QCb, RCb in ipairs(Dungeon.rooms(cCb)) do
                if tostring(RCb.key) == OCb then
                    PCb = RCb
                end
            end
            App.log(1, "DUNGEON", string.format("the game only lets the run enter its selected room %s: %s", OCb, PCb and Dungeon.roomName(PCb) or "?"))
        end
        local SCb, TCb = App.request("dgEnter", "dungeon_enter_room", OCb)
        local UCb = Utils.now()
        while App.alive and Utils.now() - UCb < 15 do
            task.wait(1)
        end
        if not App.alive then
            return true
        end
        App.log(1, "DUNGEON", string.format("no teleport after entering room %s (answer %s)", OCb, tostring(TCb)))
    end
    Dungeon.logState(cCb, "enter didn't teleport")
    Brain.pending = nil
    if not eCb then
        Modes.rec("dg").restUntil = os.time() + 900
    end
    App.saveSoon()
    return false
end

function Dungeon.chain()
    task.wait(4)
    local VCb = Dungeon.data()
    if not (VCb and VCb._started) then
        return false
    end
    return Dungeon.enter(VCb, Config.dungeonValue, true)
end

function Dungeon.roomDone(WCb)
    Brain.dg.playLast = nil
    local XCb = tonumber(type(Match.ld._dungeon) == "table" and Match.ld._dungeon.depth) or (Brain.pending and tonumber(Brain.pending.depth)) or 1
    local YCb = tostring(math.min(4, math.max(1, math.ceil(XCb / 5))))
    local ZCb = Brain.dg.depth [YCb] or {
        runs = 0,
        wins = 0
    }
    ZCb.runs, ZCb.wins = (tonumber(ZCb.runs) or 0) + 1, (tonumber(ZCb.wins) or 0) + (WCb and 1 or 0)
    Brain.dg.depth [YCb] = ZCb
    local _Cb = Dungeon.data()
    local aDb, bDb, cDb = Dungeon.res(_Cb)
    Dungeon.note(string.format("room %d/%d %s · %d coins · chests %d + %d rare · %d lives", XCb, Dungeon.ROOMS, WCb and "cleared" or "lost", aDb, bDb, cDb, Dungeon.lives(_Cb)))
    Brain.dg.teams = type(Brain.dg.teams) == "table" and Brain.dg.teams or {
    }
    local dDb = Brain.dg.teams [Modes.teamSig()] or {
        w = 0,
        l = 0
    }
    if WCb then
        dDb.w = (tonumber(dDb.w) or 0) + 1
    else
        dDb.l = (tonumber(dDb.l) or 0) + 1
    end
    Brain.dg.teams [Modes.teamSig()] = dDb
    if WCb then
        Brain.dg.lives = 5
    elseif Brain.dg.room and Brain.dg.room.d == XCb then
        Brain.dg.lost = Brain.dg.lost or {
        }
        local eDb, fDb = tostring(Brain.dg.room.seed), Modes.teamSig()
        Brain.dg.lost [eDb] = Brain.dg.lost [eDb] or {
        }
        Brain.dg.lost [eDb] [fDb] = (Brain.dg.lost [eDb] [fDb] or 0) + 1
    end
end

function Dungeon.text()
    if not Config.dungeon then
        return "Off."
    end
    local gDb = Dungeon.data()
    if not gDb then
        return "No dungeon data yet (shows in the lobby)."
    end
    if not gDb._started then
        return Config.dungeonStart and "No run going: the farm starts one when the dungeon ranks first." or "No run going (starting new runs is off)."
    end
    local hDb, iDb, jDb = Dungeon.res(gDb)
    local kDb, lDb = {
    }, {
    }
    for mDb, nDb in pairs(Dungeon.items(gDb)) do
        local oDb = tostring((Dungeon.item(mDb) or {
        }).name or mDb) .. (nDb > 1 and (" ×" .. nDb) or "")
        table.insert(Dungeon.isCurse(mDb) and lDb or kDb, oDb)
    end
    local pDb = {
        string.format("Room %s/%d · %d lives · %d coins · chests %d + %d rare · luck ×%.1f",
        tostring(Dungeon.depth(gDb) or "?"),
        Dungeon.ROOMS,
        Dungeon.lives(gDb),
        hDb,
        iDb,
        jDb,
        Dungeon.luck(gDb))
    }
    table.insert(pDb, "Items: " .. (# kDb > 0 and table.concat(kDb, ", ") or "none") .. " · Curses: " .. (# lDb > 0 and table.concat(lDb, ", ") or "none"))
    table.insert(pDb, "They add up to: " .. Dungeon.fxText(Dungeon.fx(gDb)))
    local qDb = Dungeon._pick and Dungeon._pick.x
    if qDb then
        table.insert(pDb, string.format("Next: %s, win ≈%d%%", Dungeon.roomName(qDb), math.floor(qDb.p * 100 + 0.5)))
    end
    for rDb, sDb in ipairs(Brain.dg.log) do
        if rDb <= 4 then
            table.insert(pDb, os.date("%H:%M ", sDb.at) .. sDb.msg)
        end
    end
    return table.concat(pDb, "\n")
end
Match.refused, Match.spent, Match.actions = {
}, 0, {
}
Match.waveMax = {
}

function Match.mapKey()
    return tostring(Match.ld and Match.ld.map or "?") .. (Match.laneCut and ("#L" .. Match.laneCut) or "")
end

function Match.label()
    if Match.kind == "dungeon" then
        local tDb = type(Match.ld._dungeon) == "table" and Match.ld._dungeon.depth or "?"
        return string.format("Dungeon room %s/%d · %s", tostring(tDb), Dungeon.ROOMS, tostring(Match.ld._location_name or Match.ld.map or "?"))
    end
    return Modes.levelName(Match.ld.id or "?") .. (Match.ld._difficulty and (" (" .. Match.ld._difficulty .. ")") or "")
end

function Match.money()
    local uDb = LocalPlayer:FindFirstChild("_stats")
    return uDb and uDb.resource.Value or 0
end

function Match.wave()
    return workspace:FindFirstChild("_wave_num") and workspace._wave_num.Value or 0
end

function Match.buildPath()
    Match.samples = {
    }
    local vDb = Core.PATH and Core.PATH.PATH_CACHE and Core.PATH.PATH_CACHE [workspace._BASES.pve]
    if not vDb then
        return
    end
    for wDb, xDb in pairs(vDb) do
        if not (Core.PATH.HIDDEN_MOCK_LANES and Core.PATH.HIDDEN_MOCK_LANES [wDb.Name]) then
            local yDb = {
            }
            for zDb, ADb in ipairs(xDb.points or {
            }) do
                table.insert(yDb, ADb.part.Position)
            end
            local BDb = 0
            for CDb = 2, # yDb do
                BDb = BDb + (yDb [CDb] - yDb [CDb - 1]).Magnitude
            end
            local DDb = 0
            for EDb = 2, # yDb do
                local FDb, GDb = yDb [EDb - 1], yDb [EDb]
                local HDb = (GDb - FDb).Magnitude
                local IDb = math.max(1, math.floor(HDb / 2))
                for JDb = 0, IDb - 1 do
                    local KDb = FDb:Lerp(GDb, JDb / IDb)
                    table.insert(Match.samples, {
                        pos = KDb,
                        prog = (DDb + HDb * JDb / IDb) / math.max(1,
                        BDb),
                        lane = wDb.Name
                    })
                end
                DDb = DDb + HDb
            end
            if yDb [# yDb] then
                table.insert(Match.samples, {
                    pos = yDb [# yDb],
                    prog = 1,
                    lane = wDb.Name
                })
            end
        end
    end
    Match.laneCut, Match.laneWant, Match.laneFirst = nil, nil, nil
    local LDb = tonumber(Match.ld and Match.ld._portal_lanes)
    local MDb = Simulator.laneList(Match.samples)
    if LDb and LDb >= 1 and MDb and # MDb > LDb then
        Match.laneWant = LDb
    end
    Match.laneTotal = MDb and # MDb or 1
    Match.countLanes()
end

function Match.countLanes()
    local NDb, ODb, PDb = {
    }, 0, 0
    for QDb, RDb in ipairs(Match.samples) do
        local SDb = tostring(RDb.lane)
        if not NDb [SDb] then
            ODb = ODb + 1
        end
        NDb [SDb] = (NDb [SDb] or 0) + 1
        PDb = PDb + 1
    end
    Match.laneCount = {
        n = ODb,
        by = NDb,
        avg = ODb > 0 and PDb / ODb or 1
    }
end

function Match.portalLanes()
    if not Match.laneWant or Match.laneCut then
        return true
    end
    if Match.planning then
        return false
    end
    local TDb, UDb = {
    }, 0
    for VDb, WDb in ipairs(workspace._UNITS:GetChildren()) do
        local XDb = WDb:FindFirstChild("_stats")
        if XDb and XDb:FindFirstChild("player") and XDb.player.Value == nil and XDb:FindFirstChild("lane") and WDb:FindFirstChild("HumanoidRootPart") then
            local YDb = tostring(XDb.lane.Value)
            if not TDb [YDb] then
                TDb [YDb] = true
                UDb = UDb + 1
            end
        end
    end
    if UDb == 0 then
        if Utils.now() - (Match.startT or Utils.now()) > 45 then
            Match.laneWant = nil
            App.log(1, "MATCH", "no enemy seen in 45 s: placing for every lane")
            return true
        end
        return false
    end
    Match.laneFirst = Match.laneFirst or Utils.now()
    if UDb < Match.laneWant and Utils.now() - Match.laneFirst < 10 then
        return false
    end
    local ZDb, _Db = {
    }, {
    }
    for aEb, bEb in ipairs(Match.samples) do
        if TDb [tostring(bEb.lane)] then
            table.insert(ZDb, bEb)
        end
    end
    if # ZDb == 0 then
        Match.laneWant = nil
        return true
    end
    for cEb in pairs(TDb) do
        table.insert(_Db, cEb)
    end
    table.sort(_Db)
    Match.samples, Match.laneCut = ZDb, table.concat(_Db, "+")
    Match.countLanes()
    local dEb, eEb = pcall(Match.buildCandidates)
    if not dEb then
        App.log(1, "ERROR", "spots on the portal's lane: " .. tostring(eEb))
    end
    App.log(1, "MATCH", string.format("this portal opens %d of the map's lanes, and the enemies walk lane %s: placing there", Match.laneWant, Match.laneCut))
    if Match.info and Config.simSpots and not Match.joinedMid and not Match.random and not Match.infinite and not Match.trialId then
        Match.planning = Utils.now()
        task.spawn(function()
            local fEb, gEb = pcall(Match.planSpots)
            Match.planning = nil
            if not fEb then
                App.log(1, "ERROR", "spot search: " .. tostring(gEb))
            end
        end)
    end
    return true
end

function Match.buildWaves()
    local hEb = Match.ld
    local iEb = hEb and hEb._dungeon and type(hEb._override_waves) == "table" and hEb._override_waves or nil
    local jEb = hEb and Core.Waves [(iEb and iEb.template) or hEb.waves or hEb.id]
    local kEb
    if type(jEb) == "table" then
        kEb = jEb.override_waves or jEb.waves
        if not kEb and jEb.template and Core.Waves [jEb.template] then
            kEb = Core.Waves [jEb.template].waves or Core.Waves [jEb.template].override_waves
        end
    end
    Match.waveList = Utils.list(kEb)
    Match.infinite = hEb and (hEb._gamemode == "infinite" or hEb.infinite) and Simulator.unbound(hEb) or false
    if Match.infinite then
        Match.waveList = {
        }
        Match.total = math.max(30, math.floor(Modes.infReach(Match.key) + 0.5))
        return
    end
    Match.total = (hEb and type(hEb._dungeon) == "table" and 15) or tonumber(hEb and hEb._override_infinite_bound_waves) or Simulator.boundEnd(hEb, # Match.waveList, Match.key) or (# Match.waveList > 0 and # Match.waveList) or 15
end

function Match.infExtend()
    if Match.infinite and Match.wave() + 5 > Match.total then
        Match.total = Match.wave() + 10
    end
end

function Match.infWave(lEb)
    Match.infExtend()
    if Config.trainLeave and not Match.stopping then
        local mEb, nEb = pcall(Match.trainLeave, lEb)
        if not mEb then
            App.log(1, "ERROR", "leave when trained: " .. tostring(nEb))
        end
    end
    if Config.infiniteStop and not Match.stopping then
        local oEb, pEb = pcall(Match.infStop, lEb)
        if not oEb then
            App.log(1, "ERROR", "Infinite stop: " .. tostring(pEb))
        end
    end
    local qEb = Modes.infTier(lEb - 1)
    if qEb <= 0 or qEb == Match.infTierSeen then
        return
    end
    Match.infTierSeen = qEb
    task.delay(5, function()
        if not App.alive then
            return
        end
        local rEb = Core.prof()
        local sEb = rEb and rEb.daily_infinite_reward_claims and rEb.daily_infinite_reward_claims [Match.ld.id]
        local tEb = type(sEb) == "table" and (tonumber(sEb.highest_claimed_wave) or 0) >= qEb and os.time() - (tonumber(sEb.highest_claim_time) or 0) < 900
        if tEb then
            Brain.infLive = true
        end
        App.log(1, "MATCH", string.format("Infinite: wave %d passed — daily gems %s", qEb, tEb and "claimed now" or "not in your profile yet (paid at the end?)"))
    end)
end

function Match.infStop(uEb)
    local vEb = 0
    for wEb, xEb in ipairs(Utils.list(Core.GS.DAILY_INFINITE_REWARDS)) do
        vEb = math.max(vEb, tonumber(xEb.wave) or 0)
    end
    if vEb <= 0 or uEb <= vEb + 1 then
        return
    end
    local yEb = Brain.train.on
    if Match.trainee and yEb and yEb.have + (yEb.got or 0) + (Match.trainTk or 0) < yEb.need then
        return
    end
    if not FarmHub.every("infStop", 60) then
        return
    end
    local zEb = Modes.rec(Match.key)
    local AEb = tonumber(zEb.timed) or 0
    local BEb = (AEb > 0 and (zEb.sec or 0) > 0) and math.max(0.5, ((zEb.gems or 0) - 200 * AEb) / (zEb.sec / 60)) or 2.5
    local CEb = pcall(Modes.pick)
    local DEb
    for EEb, FEb in ipairs(CEb and Modes.lastScored or {
    }) do
        if FEb.kind ~= "infinite" and (not DEb or (FEb.score or 0) > (DEb.score or 0)) then
            DEb = FEb
        end
    end
    if not DEb or (DEb.score or 0) <= BEb then
        return
    end
    Match.stopping = true
    App.log(1, "MATCH", string.format("Infinite: wave %d, the daily gems are in and no unit trains here — ending the run (≈%.1f gems/min from here, %.1f in %s): selling your units", uEb, BEb, DEb.score, DEb.label))
    Match.sellAll()
end

function Match.trainLeave(GEb)
    local HEb = Brain.train.on
    if not (Match.infinite and Match.trainee and HEb) then
        return
    end
    Match.trainCount()
    local IEb = HEb.have + (HEb.got or 0) + (Match.trainTk or 0)
    if IEb < HEb.need then
        return
    end
    local JEb, KEb, LEb = pcall(Modes.infDaily, Core.prof(), Match.ld.id, (Modes.infReach(Match.key)))
    if JEb and (KEb or 0) > 0 and LEb > 0 and GEb <= LEb then
        App.status("Training", string.format("%s has its %s: playing to wave %d for the daily gems, then ending the run", Units.name(HEb.id), HEb.what, LEb))
        return
    end
    Match.stopping = true
    App.log(1, "MATCH", string.format("Infinite: %s has its %s (%s of %s) — ending the run at wave %d so it can evolve: selling your units", Units.name(HEb.id), HEb.what, Utils.fmt(IEb), Utils.fmt(HEb.need), GEb))
    Match.sellAll()
end

function Match.sellAll()
    task.spawn(function()
        local MEb = {
        }
        for NEb, OEb in ipairs(Match.mine or {
        }) do
            local PEb = OEb:FindFirstChild("_stats")
            local QEb = PEb and PEb:FindFirstChild("id") and Core.Units [PEb.id.Value]
            if not (QEb and QEb.unsellable) then
                table.insert(MEb, OEb)
            end
        end
        local function REb(SEb)
            local TEb = SEb:FindFirstChild("_stats")
            return TEb and TEb:FindFirstChild("id") and Units.isFarm(TEb.id.Value) or false
        end
        table.sort(MEb, function(UEb, VEb)
            return (REb(UEb) and 1 or 0) < (REb(VEb) and 1 or 0)
        end)
        local WEb = {
        }
        for XEb = 1, 2 do
            local YEb = {
            }
            for ZEb, _Eb in ipairs(XEb == 1 and MEb or WEb) do
                if not App.alive or Match.finished then
                    return
                end
                if _Eb.Parent and _Eb.Parent.Name == "_UNITS" then
                    local aFb, bFb = App.request("sell", "sell_unit_ingame", _Eb)
                    if bFb ~= true then
                        table.insert(YEb, _Eb)
                    end
                    task.wait(1.3)
                end
            end
            WEb = YEb
        end
        if # WEb > 0 then
            local cFb = {
            }
            for dFb, eFb in ipairs(WEb) do
                table.insert(cFb, eFb.Name)
            end
            App.log(1, "MATCH", "the game didn't sell " .. table.concat(cFb, ", ") .. " (the run still ends: nothing else is defending)")
        end
    end)
end

function Match.waveReward(fFb)
    if Match.info then
        return Simulator.waveYen(Match.info, fFb)
    end
    local gFb = Match.waveList and Match.waveList [fFb]
    return (gFb and tonumber(gFb.wave_reward) or 0) * 2.6
end

function Match.progressAt(hFb)
    local iFb, jFb, kFb = 0, math.huge, nil
    local lFb = Utils.flat(hFb)
    for mFb, nFb in ipairs(Match.samples) do
        local oFb = (Utils.flat(nFb.pos) - lFb).Magnitude
        if oFb < jFb then
            jFb, iFb, kFb = oFb, nFb.prog, nFb.lane
        end
    end
    return iFb, jFb, kFb ~= nil and tostring(kFb) or nil
end

function Match.scan()
    local pFb, qFb = {
    }, {
    }
    for rFb, sFb in ipairs({
        workspace._UNITS
    }) do
        for tFb, uFb in ipairs(sFb:GetChildren()) do
            local vFb = uFb:FindFirstChild("_stats")
            if vFb and vFb:FindFirstChild("player") then
                local wFb = vFb:FindFirstChild("parent_unit")
                local xFb = wFb and wFb.Value
                local yFb = xFb and xFb:FindFirstChild("_stats")
                local zFb = Core.Units [vFb.id.Value]
                local AFb = xFb ~= nil and zFb ~= nil and (tonumber(zFb.cost) or 0) >= 100 and (not yFb or (yFb:FindFirstChild("id") and yFb.id.Value == vFb.id.Value))
                if vFb.id.Value == "mahoraga" then
                    AFb = true
                end
                local BFb = (xFb ~= nil and not AFb) or not vFb:FindFirstChild("attack_cooldown") or not vFb:FindFirstChild("upgrade") or not vFb:FindFirstChild("range")
                if vFb.player.Value == LocalPlayer then
                    if not BFb then
                        table.insert(qFb, uFb)
                    end
                elseif vFb.player.Value == nil and uFb:FindFirstChild("HumanoidRootPart") then
                    local CFb, DFb, EFb = Match.progressAt(uFb.HumanoidRootPart.Position)
                    local FFb = uFb:FindFirstChildOfClass("Humanoid")
                    local GFb = FFb and FFb.Health or (vFb:FindFirstChild("health") and vFb.health.Value) or 0
                    local HFb = vFb:FindFirstChild("damage_reduction") and tonumber(vFb.damage_reduction.Value) or 0
                    local IFb = Match.info and Match.info.cfgById [vFb.id.Value]
                    local JFb = vFb:FindFirstChild("Flying") and (tonumber(vFb.Flying.Value) or 0) > 0 or false
                    local KFb = vFb:FindFirstChild("shield") and tonumber(vFb.shield.Value) or 0
                    table.insert(pFb, {
                        m = uFb,
                        pos = uFb.HumanoidRootPart.Position,
                        prog = CFb,
                        lane = EFb,
                        hp = GFb,
                        red = HFb,
                        fly = JFb,
                        sh = KFb,
                        boss = IFb and tostring(IFb):find("boss") ~= nil or false
                    })
                    if tostring(vFb.id.Value):find("^star_golem") then
                        pcall(Match.noteStar, uFb, FFb)
                    end
                end
            end
        end
    end
    Match.enemies, Match.mine = pFb, qFb
    if not Match.flyerSeen then
        for LFb, MFb in ipairs(pFb) do
            if MFb.fly then
                Match.flyerSeen = math.max(1, Match.wave())
                if not Match.random then
                    App.log(1, "MATCH", string.format("flyers from wave %d: units that hit them get more of the yen now", Match.flyerSeen))
                end
                break
            end
        end
    end
    if not Match.shieldSeen then
        for NFb, OFb in ipairs(pFb) do
            if (OFb.sh or 0) > 0 then
                Match.shieldSeen = true
                local PFb = OFb.m._stats
                App.log(1, "MATCH", string.format("enemy shield seen at wave %d: %s (its most %s), %s, %.3g HP · the simulator has +%s on every enemy", Match.wave(), tostring(OFb.sh), tostring(PFb:FindFirstChild("max_shield") and PFb.max_shield.Value), tostring(PFb:FindFirstChild("id") and PFb.id.Value), OFb.hp, tostring(Match.info and Match.info.shield)))
                break
            end
        end
    end
    local QFb = Match.wave()
    local RFb = 0
    local SFb, TFb, UFb = 0, 0, 0
    for VFb, WFb in ipairs(pFb) do
        RFb = math.max(RFb, WFb.prog)
        SFb = SFb + WFb.hp / math.max(0.1, 1 - WFb.red)
        UFb = UFb + WFb.hp
    end
    Match.hpAliveRaw = UFb
    for XFb, YFb in ipairs(qFb) do
        local ZFb = YFb._stats.id.Value
        if not Units.isFarm(ZFb) and YFb._stats:FindFirstChild("damage") then
            local _Fb, aGb = pcall(Match.liveDps, YFb, ZFb)
            if _Fb and aGb then
                TFb = TFb + aGb
            end
        end
    end
    Match.hpAlive, Match.teamDps = SFb, TFb
    Match.clearSec = SFb > 0 and (TFb > 0 and SFb / TFb or math.huge) or 0
    Match.waveMax [QFb] = math.max(Match.waveMax [QFb] or 0, RFb)
    Match.front = RFb
    Match.pressure = math.max(Match.waveMax [QFb] or 0, Match.waveMax [QFb - 1] or 0)
    Match.depth = Match.coverage(qFb, pFb)
    local bGb = Utils.now()
    Match.aliveHist = Match.aliveHist or {
    }
    table.insert(Match.aliveHist, {
        t = bGb,
        n = # pFb
    })
    while Match.aliveHist [1] and bGb - Match.aliveHist [1].t > 12 do
        table.remove(Match.aliveHist, 1)
    end
    local cGb = Match.aliveHist [1]
    Match.piling = # pFb >= 8 and cGb and bGb - cGb.t >= 8 and # pFb > cGb.n + 1 or false
    if # pFb >= 18 then
        Match.piling = true
    end
end

function Match.setupChecks()
    Match.probe = Instance.new("Part")
    Match.probe.Name = "_aa_probe"
    Match.probe.Anchored = true
    Match.probe.CanCollide = false
    Match.probe.CanTouch = false
    Match.probe.CanQuery = false
    Match.probe.Transparency = 1
    Match.probe.Parent = workspace:FindFirstChild("ignore") or workspace
    local dGb = ReplicatedStorage:FindFirstChild("_bounds")
    Match.bounds = Instance.new("Folder")
    Match.bounds.Name = "_aa_bounds"
    if dGb then
        for eGb, fGb in ipairs(dGb:GetDescendants()) do
            if fGb:IsA("BasePart") then
                local gGb = fGb:Clone()
                for hGb, iGb in ipairs(gGb:GetChildren()) do
                    iGb:Destroy()
                end
                gGb.Anchored = true
                gGb.CanCollide = false
                gGb.CanTouch = false
                gGb.CanQuery = true
                gGb.Transparency = 1
                gGb.CFrame = fGb.CFrame
                gGb.Parent = Match.bounds
            end
        end
    end
    Match.bounds.Parent = workspace:FindFirstChild("ignore") or workspace
    Match.overlap = OverlapParams.new()
    Match.overlap.FilterType = Enum.RaycastFilterType.Include
    Match.overlap.FilterDescendantsInstances = {
        workspace._road,
        Match.bounds
    }
end

function Match.spotKey(jGb)
    return string.format("%d,%d", math.floor(jGb.X + 0.5), math.floor(jGb.Z + 0.5))
end

function Match.killZone()
    return Config.killZone ~= false and (Match.style == "box" or (Match.style == nil and Match.kind == "dungeon"))
end

function Match.blockedSpot(kGb)
    local lGb = Match.spotKey(kGb)
    if Match.refused [lGb] then
        return true
    end
    local mGb = Brain.blocked [Match.mapKey()]
    return mGb and (tonumber(mGb [lGb]) or 0) >= 2
end

function Match.valid(nGb, oGb)
    local pGb = Core.PC.raycast(nGb + Vector3.new(0, 40, 0), Vector3.new(0, - 120, 0))
    if not pGb then
        return nil
    end
    if not Core.PC.is_valid_raycast_hit(pGb.Instance, oGb) then
        return nil
    end
    local qGb = pGb.Position
    if Match.blockedSpot(qGb) then
        return nil
    end
    local rGb = (tonumber(oGb.override_hitbox_radius) or 1.5) + 0.25
    Match.probe.Size = Vector3.new(rGb * 2, 2.5, rGb * 2)
    Match.probe.CFrame = CFrame.new(qGb + Vector3.new(0, 1.35, 0))
    if # workspace:GetPartsInPart(Match.probe, Match.overlap) > 0 then
        return nil
    end
    for sGb, tGb in ipairs(Match.mine or {
    }) do
        local uGb = tGb:FindFirstChild("_hitbox")
        local vGb = uGb and uGb.Position or tGb:GetPivot().Position
        local wGb = uGb and math.max(uGb.Size.X, uGb.Size.Z) / 2 or 1.5
        if (Utils.flat(qGb) - Utils.flat(vGb)).Magnitude < rGb + wGb then
            return nil
        end
    end
    return qGb
end

function Match.buildCandidates()
    Match.cands = {
    }
    local xGb = {
    }
    for yGb = 1, # Match.samples, 3 do
        local zGb = Match.samples [yGb]
        local AGb = Match.samples [math.min(# Match.samples, yGb + 1)]
        local BGb = Utils.flat(AGb.pos - zGb.pos)
        if BGb.Magnitude < 0.01 then
            BGb = Vector3.new(1, 0, 0)
        end
        BGb = BGb.Unit
        local CGb = Vector3.new(- BGb.Z, 0, BGb.X)
        for DGb, EGb in ipairs({
            3,
            4.5,
            6,
            8,
            10.5,
            13.5,
            17
        }) do
            for FGb, GGb in ipairs({
                1,
                - 1
            }) do
                local HGb = zGb.pos + CGb * EGb * GGb
                local IGb = string.format("%d,%d", math.floor(HGb.X / 1.5), math.floor(HGb.Z / 1.5))
                if not xGb [IGb] then
                    xGb [IGb] = true
                    table.insert(Match.cands, HGb)
                end
            end
        end
    end
end

function Match.coverage(JGb, KGb)
    local LGb = {
    }
    for MGb, NGb in ipairs(JGb) do
        local OGb = NGb._stats
        if not Units.isFarm(OGb.id.Value) and OGb:FindFirstChild("range") then
            table.insert(LGb, {
                p = Utils.flat(NGb:GetPivot().Position),
                r = OGb.range.Value * (Units.SUMMONER [OGb.id.Value] and Units.SUMMONER [OGb.id.Value].reach or 1),
                air = Match.canAir(NGb)
            })
        end
    end
    local PGb, QGb = 0, 0
    if # LGb > 0 then
        for RGb, SGb in ipairs(Match.samples) do
            if SGb.prog > QGb then
                local TGb = Utils.flat(SGb.pos)
                for UGb, VGb in ipairs(LGb) do
                    if (TGb - VGb.p).Magnitude <= VGb.r then
                        if SGb.prog > PGb then
                            PGb = SGb.prog
                        end
                        if VGb.air then
                            QGb = SGb.prog
                            break
                        end
                    end
                end
            end
        end
    end
    local WGb, XGb = {
    }, Match.laneCount
    if XGb and XGb.n >= 2 and # LGb > 0 then
        local YGb = {
        }
        for ZGb, _Gb in ipairs(Match.samples) do
            local aHb = Utils.flat(_Gb.pos)
            for bHb, cHb in ipairs(LGb) do
                if (aHb - cHb.p).Magnitude <= cHb.r then
                    local dHb = tostring(_Gb.lane)
                    YGb [dHb] = (YGb [dHb] or 0) + 1
                    if _Gb.prog > (WGb [dHb] or 0) then
                        WGb [dHb] = _Gb.prog
                    end
                    break
                end
            end
        end
        local eHb, fHb = {
        }, 0
        for gHb, hHb in pairs(XGb.by) do
            eHb [gHb] = (YGb [gHb] or 0) / math.max(1, hHb)
            fHb = math.max(fHb, eHb [gHb])
        end
        Match.laneW = {
        }
        for iHb, jHb in pairs(XGb.by) do
            Match.laneW [iHb] = (XGb.avg / math.max(1, jHb)) * (1 + 1.5 * (fHb > 0 and (1 - eHb [iHb] / fHb) or 0))
        end
        Match.laneFrac = eHb
    else
        Match.laneW, Match.laneFrac = nil, nil
    end
    local kHb, lHb, mHb
    if # LGb > 0 then
        for nHb, oHb in ipairs(KGb) do
            local pHb = (Match.laneW and oHb.lane and WGb [oHb.lane]) or PGb
            if oHb.hp > 0 and oHb.prog > pHb + 0.02 and oHb.prog > (kHb or 0) then
                kHb, mHb = oHb.prog, Match.laneW and oHb.lane or nil
            end
            if oHb.hp > 0 and oHb.fly and oHb.prog > QGb + 0.02 then
                lHb = true
            end
        end
    end
    local qHb = # LGb > 0 and (Match.pressure or 0) >= PGb - 0.08
    return {
        covEnd = PGb,
        airEnd = QGb,
        leak = kHb,
        leakLane = mHb,
        covL = WGb,
        airLeak = lHb,
        push = qHb,
        units = # LGb
    }
end

function Match.needLastLine(rHb)
    if Units.isFarm(rHb.id) or Units.allyBuff(rHb.id) or Match.fieldCount() < 5 then
        return false
    end
    local sHb, tHb = 0, 0
    for uHb, vHb in ipairs(Match.mine or {
    }) do
        local wHb = vHb._stats
        if not Units.isFarm(wHb.id.Value) and wHb:FindFirstChild("range") then
            local xHb, yHb = Utils.flat(vHb:GetPivot().Position), wHb.range.Value
            for zHb, AHb in ipairs(Match.samples) do
                if AHb.prog >= 0.85 and (Utils.flat(AHb.pos) - xHb).Magnitude <= yHb then
                    sHb = sHb + 1
                    if Match.canAir(vHb) then
                        tHb = tHb + 1
                    end
                    break
                end
            end
        end
    end
    return sHb < 2 or (tHb < 1 and Match.flyMode() and Match.cardAir(rHb.id))
end
Match.airCache = setmetatable({
}, {
    __mode = "k"
})

function Match.canAir(BHb)
    local CHb = BHb._stats:FindFirstChild("upgrade") and BHb._stats.upgrade.Value or 0
    local DHb = Match.airCache [BHb]
    if not DHb or DHb.lvl ~= CHb then
        local EHb = BHb:GetAttribute("_on_hill") == true or BHb:GetAttribute("_anti_air") == true
        DHb = {
            lvl = CHb,
            v = EHb
        }
        Match.airCache [BHb] = DHb
    end
    return DHb.v
end
Units._airFrom = {
}

function Units.airFrom(FHb)
    local GHb = Units._airFrom [FHb]
    if GHb ~= nil then
        return GHb or nil
    end
    local HHb = Core.Units [FHb]
    if HHb and (HHb.hill_unit or HHb.hybrid_placement or Units.SUMMONER [FHb]) then
        Units._airFrom [FHb] = 0
        return 0
    end
    local IHb = Units.rows(FHb)
    if not (IHb and IHb.max) then
        return Match.cardAir(FHb) and 0 or nil
    end
    local JHb = false
    for KHb = 0, IHb.max do
        local LHb = IHb [KHb] and IHb [KHb].atk
        if LHb and Core.Attacks [LHb] and Core.Attacks [LHb].targets_flying then
            JHb = KHb
            break
        end
    end
    if JHb == false and Match.cardAir(FHb) then
        JHb = 0
    end
    Units._airFrom [FHb] = JHb
    return JHb or nil
end

function Match.cardAir(MHb)
    local NHb = Core.Units [MHb]
    if not NHb then
        return false
    end
    if NHb.hill_unit or NHb.hybrid_placement then
        return true
    end
    local OHb = Units.field(MHb, "primary_attack_no_upgrades") or Units.field(MHb, "primary_attack")
    return OHb and Core.Attacks [OHb] and Core.Attacks [OHb].targets_flying and true or false
end

function Match.airShare()
    local PHb, QHb = 0, 0
    for RHb, SHb in ipairs(Match.mine or {
    }) do
        local THb = SHb._stats.id.Value
        if not Units.isFarm(THb) then
            local UHb, VHb = pcall(Match.liveDps, SHb, THb)
            VHb = UHb and VHb or 0
            PHb = PHb + VHb
            if Match.canAir(SHb) then
                QHb = QHb + VHb
            end
        end
    end
    return PHb > 0 and QHb / PHb or 0
end

function Match.cover(WHb, XHb, YHb, ZHb)
    local _Hb = 0
    local aIb = Utils.flat(WHb)
    local bIb = YHb and Brain.maps [Match.mapKey()] and Brain.maps [Match.mapKey()].dens
    local cIb = Match.laneW
    for dIb, eIb in ipairs(Match.samples) do
        if (Utils.flat(eIb.pos) - aIb).Magnitude <= XHb then
            local fIb = 1
            if bIb then
                fIb = 0.15 + 0.85 * (tonumber(bIb [math.min(Simulator.BINS, math.floor(eIb.prog * Simulator.BINS) + 1)]) or 0)
            end
            if cIb then
                fIb = fIb * (cIb [tostring(eIb.lane)] or 1)
            end
            if ZHb then
                if ZHb.leak and eIb.prog >= ZHb.leak - 0.01 and (not ZHb.leakLane or tostring(eIb.lane) == ZHb.leakLane) then
                    fIb = fIb + 3
                elseif ZHb.push and eIb.prog > ZHb.covEnd then
                    fIb = fIb + 0.6
                end
            end
            _Hb = _Hb + fIb
        end
    end
    return _Hb
end

function Match.bleedGain(gIb, hIb, iIb)
    local jIb = Match.info and tonumber(Match.info.regen) or 0
    if jIb <= 0 then
        return 0
    end
    local kIb = Units.bleeds(gIb)
    if not kIb then
        return 0
    end
    local lIb = false
    for mIb, nIb in ipairs(Match.mine or {
    }) do
        local oIb = nIb:FindFirstChild("_stats")
        local pIb = oIb and oIb:FindFirstChild("id") and oIb.id.Value
        local qIb = oIb and oIb:FindFirstChild("upgrade") and tonumber(oIb.upgrade.Value) or 0
        if pIb and (Units.bleeds(pIb) or 99) <= qIb then
            lIb = true
            break
        end
    end
    return Economy.bleedShare(Economy.bleedGain(jIb, Match.hpAlive or 0, Match.coming, lIb), kIb, hIb, iIb)
end

function Match.fieldBuffers()
    local rIb = {
    }
    for sIb, tIb in ipairs(Match.mine or {
    }) do
        local uIb = Units.allyBuff(tIb._stats.id.Value)
        if uIb then
            table.insert(rIb, {
                pos = tIb:GetPivot().Position,
                range = tIb._stats.range.Value,
                b = uIb
            })
        end
    end
    return rIb
end

function Match.buffShort(vIb)
    local wIb = {
    }
    for xIb, yIb in ipairs(Match.fieldBuffers()) do
        if yIb.b.attack == vIb.attack then
            table.insert(wIb, yIb)
        end
    end
    local zIb = Units.buffCopies(vIb)
    local AIb = {
    }
    for BIb, CIb in ipairs(Match.mine or {
    }) do
        local DIb = CIb._stats.id.Value
        local EIb, FIb = Units.types(DIb)
        if not Units.isFarm(DIb) and not Units.allyBuff(DIb) and vIb.types [FIb] then
            local GIb = Utils.flat(CIb:GetPivot().Position)
            local HIb = 0
            for IIb, JIb in ipairs(wIb) do
                if (Utils.flat(JIb.pos) - GIb).Magnitude <= JIb.range then
                    HIb = HIb + 1
                end
            end
            if HIb < zIb then
                local KIb, LIb = pcall(Match.liveDps, CIb, DIb)
                table.insert(AIb, {
                    pos = GIb,
                    base = FIb,
                    n = HIb,
                    dps = math.max(1,
                    KIb and tonumber(LIb) or 1)
                })
            end
        end
    end
    return AIb
end

function Match.spotRec(MIb, NIb, OIb)
    local PIb = Match.mapKey()
    Brain.maps [PIb] = Brain.maps [PIb] or {
    }
    local QIb = Brain.maps [PIb].lay
    if not QIb then
        if not OIb then
            return nil
        end
        QIb = {
        }
        Brain.maps [PIb].lay = QIb
    end
    local RIb = QIb [MIb]
    if not RIb then
        if not OIb then
            return nil
        end
        RIb = {
        }
        QIb [MIb] = RIb
    end
    local SIb = Match.spotKey(NIb)
    if not RIb [SIb] and OIb then
        RIb [SIb] = {
            runs = 0,
            wins = 0
        }
    end
    return RIb [SIb]
end

function Match.lastLife(TIb, UIb)
    if Match.kind ~= "dungeon" then
        return
    end
    local VIb, WIb = pcall(Dungeon.lives, Dungeon.data())
    if not (VIb and WIb <= 1) then
        return
    end
    local XIb = TIb > 1 or UIb.won
    Dungeon.note(string.format("last life, on this map: the simulator says your team %s", XIb and "wins" or ("falls at wave " .. UIb.wave)))
    if not XIb and Dungeon.playLast() then
        Dungeon.note("last life: played all the same, the user's call")
    elseif not XIb then
        Match.noBuy = true
        Modes.rec("dg").restUntil = os.time() + 3600
        Brain.pending = nil
        Dungeon.note("last life kept: back to the lobby before a wave starts. Looks again in an hour")
        App.saveNow()
        task.wait(1)
        App.request("lobby", "teleport_back_to_lobby")
    end
end
Match.STYLE_FAST, Match.STYLE_BALANCED, Match.FAST_ROAD, Match.PLAN_TOTAL = 1.5, 1.1, 0.35, 14
Match.STYLE_WORDS = {
    fast = "fast clear, at the road's start",
    balanced = "balanced, spread over the road",
    box = "kill box, on the road's last stretch"
}

function Match.styleRec(YIb)
    local ZIb, _Ib
    if Match.kind == "dungeon" then
        Brain.dg.styles = type(Brain.dg.styles) == "table" and Brain.dg.styles or {
        }
        ZIb, _Ib = Brain.dg.styles, tostring(Brain.dg.room and Brain.dg.room.seed)
    else
        ZIb, _Ib = Brain.zoneRec, Simulator.zoneKey(Match.info)
    end
    if not ZIb [_Ib] and YIb then
        ZIb [_Ib] = {
            at = os.time()
        }
        if ZIb ~= Brain.zoneRec and Utils.count(ZIb) > 40 then
            local aJb, bJb
            for cJb, dJb in pairs(ZIb) do
                if not bJb or (tonumber(dJb.at) or 0) < bJb then
                    aJb, bJb = cJb, tonumber(dJb.at) or 0
                end
            end
            ZIb [aJb] = nil
        end
    end
    return ZIb [_Ib]
end

function Match.styleRecord(eJb)
    if not Match.style or not Match.info then
        return
    end
    local fJb = Match.styleRec(true)
    fJb.style, fJb.zone, fJb.won, fJb.at = Match.style, Match.style == "box", eJb and true or false, os.time()
    fJb.lost = type(fJb.lost) == "table" and fJb.lost or {
    }
    fJb.lost [Match.style] = (not eJb) and {
        at = os.time(),
        sig = Match.styleSig
    } or nil
    fJb.far = type(fJb.far) == "table" and fJb.far or {
    }
    fJb.far [Match.style] = math.max(tonumber(fJb.far [Match.style]) or 0, Match.wave())
end

function Match.planSpots()
    local gJb = Utils.now()
    local hJb = Match.info
    local iJb = tonumber(hJb.rangeScale) or 1
    local jJb, kJb = {
    }, {
    }
    for lJb, mJb in ipairs(Match.team or {
    }) do
        table.insert(jJb, mJb.u)
        if not Units.isFarm(mJb.id) and not Units.allyBuff(mJb.id) and mJb.uuid ~= Match.trainee and Units.rows(mJb.id) then
            local nJb, oJb = pcall(Units.score, mJb.u, Match.mod)
            table.insert(kJb, {
                e = mJb,
                id = mJb.id,
                sc = nJb and oJb or 0
            })
        end
    end
    if # kJb == 0 then
        return
    end
    table.sort(kJb, function(pJb, qJb)
        return pJb.sc > qJb.sc
    end)
    local rJb = {
    }
    local function sJb(tJb)
        local uJb = (tJb.hill_unit and "hill" or "ground") .. ":" .. tostring(tJb.override_hitbox_radius or "")
        if rJb [uJb] then
            return rJb [uJb]
        end
        local vJb = {
        }
        for wJb, xJb in ipairs(Match.cands) do
            local yJb = Match.valid(xJb, tJb)
            if yJb then
                table.insert(vJb, yJb)
            end
            if wJb % 40 == 0 then
                task.wait()
            end
        end
        rJb [uJb] = vJb
        return vJb
    end
    local function zJb(AJb, BJb)
        local CJb, DJb, EJb, FJb = 0, 0, 0, BJb * BJb
        for GJb, HJb in ipairs(Match.samples) do
            local IJb, JJb = HJb.pos.X - AJb.X, HJb.pos.Z - AJb.Z
            if IJb * IJb + JJb * JJb <= FJb then
                CJb = CJb + 1
                if HJb.prog <= Match.FAST_ROAD then
                    DJb = DJb + 1.5 - HJb.prog
                end
                if HJb.prog >= 0.6 then
                    EJb = EJb + HJb.prog - 0.5
                end
            end
        end
        return CJb, DJb, EJb
    end
    local function KJb(LJb, MJb, NJb)
        for OJb, PJb in ipairs(LJb) do
            if MJb <= 0 then
                break
            end
            local QJb = true
            for RJb, SJb in ipairs(NJb) do
                if (Utils.flat(SJb) - Utils.flat(PJb.p)).Magnitude < 6 then
                    QJb = false
                    break
                end
            end
            if QJb then
                table.insert(NJb, PJb.p)
                MJb = MJb - 1
            end
        end
    end
    for TJb, UJb in ipairs(kJb) do
        local VJb = Units.rows(UJb.id)
        local WJb = Units.range(UJb.e.u, VJb.max) * iJb
        local XJb = Units.range(UJb.e.u, math.min(3, VJb.max)) * iJb
        local YJb, ZJb, _Jb, aKb = {
        }, {
        }, {
        }, {
        }
        for bKb, cKb in ipairs(sJb(UJb.e.data)) do
            local dKb, eKb, fKb = zJb(cKb, WJb)
            local gKb, hKb = zJb(cKb, XJb)
            table.insert(YJb, {
                p = cKb,
                v = dKb + 0.25 * gKb
            })
            table.insert(ZJb, {
                p = cKb,
                v = Match.cover(cKb,
                XJb,
                true)
            })
            table.insert(_Jb, {
                p = cKb,
                v = eKb + 0.5 * hKb
            })
            table.insert(aKb, {
                p = cKb,
                v = fKb
            })
            if bKb % 60 == 0 then
                task.wait()
            end
        end
        for iKb, jKb in ipairs({
            YJb,
            ZJb,
            _Jb,
            aKb
        }) do
            table.sort(jKb, function(kKb, lKb)
                return kKb.v > lKb.v
            end)
        end
        UJb.cands = {
        }
        KJb(ZJb, 1, UJb.cands)
        UJb.old = UJb.cands [1]
        KJb(YJb, 4, UJb.cands)
        KJb(ZJb, 2, UJb.cands)
        local function mKb(nKb)
            local oKb, pKb = nKb [1] and nKb [1].v or 0, {
            }
            for qKb, rKb in ipairs(nKb) do
                if oKb <= 0 or rKb.v < oKb * 0.7 then
                    break
                end
                table.insert(pKb, rKb)
            end
            return # pKb > 0 and pKb or nKb
        end
        UJb.fast, UJb.box = {
        }, {
        }
        KJb(mKb(_Jb), 5, UJb.fast)
        KJb(mKb(aKb), 5, UJb.box)
    end
    local sKb = Simulator.teamFrom(jJb, hJb.map)
    local tKb, uKb = {
    }, 0
    local function vKb(wKb, xKb)
        uKb = uKb + 1
        local yKb = Simulator.run(hJb, sKb, {
            hpMul = xKb,
            layout = wKb
        })
        task.wait()
        return yKb
    end
    local function zKb(AKb)
        local BKb = 0
        for CKb, DKb in pairs(AKb.spots) do
            local EKb = Match.spotRec(CKb, DKb)
            if EKb then
                BKb = BKb + (tonumber(EKb.wins) or 0) * 200 - ((tonumber(EKb.runs) or 0) - (tonumber(EKb.wins) or 0)) * 1500
            end
        end
        return BKb
    end
    local function FKb(GKb, HKb)
        return Simulator.objective(HKb) * 100 + zKb(GKb)
    end
    local function IKb(JKb, KKb, LKb)
        for MKb, NKb in pairs(JKb.spots) do
            if MKb ~= KKb and (Utils.flat(NKb) - Utils.flat(LKb)).Magnitude < 4.5 then
                return true
            end
        end
        return false
    end
    local function OKb(PKb, QKb)
        local RKb = {
            samples = Match.samples,
            cache = tKb,
            spots = {
            },
            style = PKb,
            list = QKb
        }
        for SKb, TKb in ipairs(kJb) do
            local UKb
            for VKb, WKb in ipairs(TKb [QKb]) do
                if not IKb(RKb, TKb.id, WKb) then
                    UKb = WKb
                    break
                end
            end
            RKb.spots [TKb.id] = UKb or TKb [QKb] [1] or TKb.old
        end
        return RKb
    end
    local function XKb(YKb)
        local ZKb, _Kb = 4, nil
        for aLb, bLb in ipairs({
            1,
            1.3,
            1.7,
            2.2,
            3,
            4
        }) do
            _Kb = vKb(YKb, bLb)
            if not _Kb.won then
                ZKb = bLb
                break
            end
        end
        return ZKb, _Kb
    end
    local function cLb(dLb, eLb, fLb, gLb, hLb)
        local iLb, jLb = Utils.now(), uKb
        local kLb = FKb(dLb, hLb or vKb(dLb, eLb))
        for lLb = 1, 2 do
            local mLb = false
            for nLb, oLb in ipairs(kJb) do
                local pLb = dLb.spots [oLb.id]
                local qLb = pLb
                for rLb, sLb in ipairs(oLb [dLb.list]) do
                    if Utils.now() - iLb > fLb or uKb - jLb >= gLb or Utils.now() - gJb > Match.PLAN_TOTAL then
                        break
                    end
                    if sLb ~= pLb and not IKb(dLb, oLb.id, sLb) then
                        dLb.spots [oLb.id] = sLb
                        local tLb = FKb(dLb, vKb(dLb, eLb))
                        if tLb > kLb + 1 then
                            kLb, qLb = tLb, sLb
                            mLb = true
                        end
                    end
                end
                dLb.spots [oLb.id] = qLb
            end
            if not mLb then
                break
            end
        end
    end
    local function uLb(vLb, wLb)
        local xLb = 0
        for yLb, zLb in ipairs({
            0.92,
            1,
            1.08
        }) do
            if vKb(vLb, wLb * zLb).won then
                xLb = xLb + 1
            end
        end
        return xLb
    end
    local ALb = Match.styleRec()
    local BLb = Simulator.sig(jJb)
    Match.styleSig = BLb
    local CLb = Match.kind ~= "dungeon" and Brain.modes [hJb.key] or nil
    local DLb = CLb and tonumber(CLb.streak) or 0
    local ELb = Config.dailyLoop and Match.kind == "daily"
    local FLb = ELb and ALb and type(ALb.far) == "table" and (tonumber(ALb.far.balanced) or 0) > 0 and (tonumber(ALb.far.balanced) or 0) >= (tonumber(ALb.far.box) or 0) and tonumber(ALb.far.balanced) or nil
    local function GLb(HLb)
        if ELb then
            return false
        end
        local ILb = ALb and type(ALb.lost) == "table" and ALb.lost [HLb]
        if ILb then
            return ILb.sig == BLb and os.time() - (tonumber(ILb.at) or 0) < 7 * 86400
        end
        if ALb and not ALb.style and ALb.won == false then
            return HLb == (ALb.zone and "box" or "balanced")
        end
        return not ALb and DLb > 0 and HLb == "balanced"
    end
    local function JLb(KLb)
        if ALb and ALb.won then
            return (ALb.style or (ALb.zone and "box" or "balanced")) == KLb
        end
        return not ALb and KLb == "balanced" and CLb ~= nil and (tonumber(CLb.wins) or 0) > 0 and DLb == 0 and hJb.key ~= "ch" and hJb.key ~= "dc"
    end
    local LLb = Config.killZone ~= false
    local MLb, NLb = pcall(Dungeon.lives, Dungeon.data())
    local OLb = LLb and Match.kind == "dungeon" and MLb and NLb <= 1
    local PLb = ELb and Config.dailyBox and LLb
    local QLb, RLb, SLb
    local TLb = (PLb and "you asked for the kill box here") or (OLb and "it's this room's last life") or (Match.trainee and "a unit is training here and needs enemies left to hit") or (GLb("fast") and "it lost here") or (GLb("balanced") and "spread-out units already lost here") or ((tonumber(hJb.cal and hJb.cal.n) or 0) == 0 and "no real run here yet to check the simulator against") or nil
    if not TLb then
        uKb = uKb + 1
        if not Simulator.run(hJb, sKb, {
            hpMul = Match.STYLE_FAST * 0.92,
            noZone = true
        }).won then
            TLb = string.format("your team doesn't beat enemies ×%.1f", Match.STYLE_FAST)
        end
    end
    if TLb then
        App.log(1, "SPOTS", "no fast clear: " .. TLb)
    else
        local ULb, VLb = Utils.now(), uKb
        local WLb = OKb("fast", "fast")
        cLb(WLb, Match.STYLE_FAST, 4, 40)
        local XLb = uLb(WLb, Match.STYLE_FAST)
        App.log(1, "SPOTS", string.format("fast clear: tried %d layouts in %.1f s, the best wins %d of 3 tries against enemies ×%.1f", uKb - VLb, Utils.now() - ULb, XLb, Match.STYLE_FAST))
        if XLb >= 2 then
            QLb, RLb = WLb, string.format("your team beats enemies ×%.1f from there", Match.STYLE_FAST)
        end
    end
    if not QLb and not OLb and not PLb and (LLb == false or not GLb("balanced")) then
        local YLb, ZLb = Utils.now(), uKb
        local _Lb = OKb("balanced", "cands")
        local aMb, bMb = XKb(_Lb)
        for cMb, dMb in ipairs(kJb) do
            if cMb > 1 then
                local eMb = Units.rows(dMb.id)
                local fMb = math.min(eMb.max, math.max(tonumber(bMb.levels and bMb.levels [dMb.id]) or 0, 1))
                local gMb = Units.range(dMb.e.u, fMb) * iJb
                local hMb, iMb = gMb * gMb, {
                }
                for jMb, kMb in ipairs(sJb(dMb.e.data)) do
                    local lMb = 0
                    for mMb, nMb in ipairs(Match.samples) do
                        if nMb.prog <= 0.5 then
                            local oMb, pMb = nMb.pos.X - kMb.X, nMb.pos.Z - kMb.Z
                            if oMb * oMb + pMb * pMb <= hMb then
                                lMb = lMb + 1
                            end
                        end
                    end
                    table.insert(iMb, {
                        p = kMb,
                        v = lMb
                    })
                    if jMb % 60 == 0 then
                        task.wait()
                    end
                end
                table.sort(iMb, function(qMb, rMb)
                    return qMb.v > rMb.v
                end)
                local sMb = dMb.cands
                dMb.cands = {
                }
                KJb(iMb, 3, dMb.cands)
                for tMb, uMb in ipairs(sMb) do
                    table.insert(dMb.cands, uMb)
                end
            end
        end
        cLb(_Lb, aMb, 5, 50, bMb)
        local vMb = uLb(_Lb, Match.STYLE_BALANCED)
        App.log(1, "SPOTS", string.format("balanced: tried %d layouts in %.1f s, the best wins %d of 3 tries against enemies ×%.1f", uKb - ZLb, Utils.now() - YLb, vMb, Match.STYLE_BALANCED))
        SLb = _Lb
        if vMb >= 2 then
            QLb, RLb = _Lb, string.format("your team beats enemies ×%.1f spread out%s", Match.STYLE_BALANCED, TLb and "" or string.format(", not ×%.1f from the road's start", Match.STYLE_FAST))
        elseif JLb("balanced") then
            QLb, RLb = _Lb, "it won here last time, and the simulator reads spread-out units low"
        elseif not LLb then
            QLb, RLb = _Lb, "the kill box is switched off"
        elseif FLb then
            QLb, RLb = _Lb, string.format("it got furthest here, to wave %d", FLb)
        elseif GLb("box") then
            QLb, RLb = _Lb, "the kill box lost here"
        end
    end
    if not QLb then
        local wMb, xMb = Utils.now(), uKb
        local yMb = OKb("box", "box")
        local zMb, AMb = XKb(yMb)
        cLb(yMb, zMb, 4, 40, AMb)
        local BMb = uLb(yMb, 1)
        App.log(1, "SPOTS", string.format("kill box: tried %d layouts in %.1f s, the best wins %d of 3 tries against normal enemies", uKb - xMb, Utils.now() - wMb, BMb))
        if BMb == 0 and SLb and uLb(SLb, 1) >= 2 then
            QLb, RLb = SLb, "the kill box loses at normal strength, spread-out units win"
        else
            QLb, RLb = yMb, PLb and "you asked for it: a control unit works best in one" or OLb and "it's this room's last life" or (not SLb and "spread-out units lost here") or string.format("your team doesn't beat enemies ×%.1f spread out", Match.STYLE_BALANCED)
        end
    end
    Match.style = QLb.style
    Match.styleWhy = RLb
    hJb.zone = QLb.style == "box"
    Match.layout = {
    }
    local CMb = {
    }
    for DMb, EMb in ipairs(kJb) do
        local FMb = QLb.spots [EMb.id]
        local GMb = {
            FMb
        }
        for HMb, IMb in ipairs(EMb [QLb.list]) do
            if IMb ~= FMb then
                table.insert(GMb, IMb)
            end
        end
        Match.layout [EMb.id] = GMb
        if FMb then
            table.insert(CMb, string.format("%s %s (%d%% of the road at full range)", Units.name(EMb.id), Match.spotKey(FMb), math.floor((zJb(FMb, Units.range(EMb.e.u, Units.rows(EMb.id).max) * iJb)) / math.max(1, # Match.samples) * 100 + 0.5)))
        end
    end
    Match.layoutSim = QLb
    local JMb, KMb = XKb(QLb)
    App.log(1, "SPOTS", string.format("placement: %s, because %s · %s · against enemies ×%.1f the simulator %s at wave %d · %d runs in %.1f s", Match.STYLE_WORDS [QLb.style], RLb, table.concat(CMb, " · "), JMb, KMb.won and "wins" or "falls", KMb.wave, uKb, Utils.now() - gJb))
    App.status("Placement", Match.STYLE_WORDS [QLb.style])
    Match.lastLife(JMb, KMb)
end

function Match.spotResult(LMb)
    for MMb, NMb in pairs(Match.layoutUsed or {
    }) do
        local OMb = Match.spotRec(MMb, NMb, true)
        OMb.runs, OMb.wins = (tonumber(OMb.runs) or 0) + 1, (tonumber(OMb.wins) or 0) + (LMb and 1 or 0)
    end
    if not Match.infinite then
        Match.styleRecord(LMb)
    end
end
Match.CONTROL_WORDS = {
    "at the front of",
    "at the back of",
    "in the middle of",
    "ahead of"
}

function Match.controlSpot(PMb, QMb)
    if not Match.killZone() then
        return nil
    end
    local RMb = Simulator.holds
    if not RMb(PMb.id) or Units.toggleOf(PMb.id) then
        return nil
    end
    local SMb, TMb, UMb, VMb = 1, 0, 0, {
    }
    for WMb, XMb in ipairs(Match.mine or {
    }) do
        local YMb = XMb._stats
        local ZMb = YMb.id.Value
        if YMb:FindFirstChild("range") and not Units.isFarm(ZMb) and not Units.allyBuff(ZMb) then
            local _Mb, aNb = Utils.flat(XMb:GetPivot().Position), YMb.range.Value
            if RMb(ZMb) and not Units.toggleOf(ZMb) then
                UMb = UMb + 1
                table.insert(VMb, {
                    p = _Mb,
                    r = aNb
                })
            else
                for bNb, cNb in ipairs(Match.samples) do
                    if (Utils.flat(cNb.pos) - _Mb).Magnitude <= aNb then
                        SMb, TMb = math.min(SMb, cNb.prog), math.max(TMb, cNb.prog)
                    end
                end
            end
        end
    end
    if TMb <= SMb then
        SMb, TMb = 0.75, 0.98
    end
    local dNb = (QMb or UMb) + 1
    local eNb = ({
        SMb,
        TMb,
        (SMb + TMb) / 2,
        SMb - (TMb - SMb) / 2
    }) [dNb]
    if not eNb then
        return nil
    end
    local fNb = Units.range(PMb.u, 0) * ((Match.info and tonumber(Match.info.rangeScale)) or 1)
    local gNb = {
    }
    for hNb, iNb in ipairs(Match.cands) do
        local jNb, kNb, lNb = Utils.flat(iNb), 0, 0
        for mNb, nNb in ipairs(Match.samples) do
            if (Utils.flat(nNb.pos) - jNb).Magnitude <= fNb then
                lNb = lNb + 1
                if math.abs(nNb.prog - eNb) <= 0.05 then
                    kNb = kNb + 1
                    local oNb = Utils.flat(nNb.pos)
                    for pNb, qNb in ipairs(VMb) do
                        if (oNb - qNb.p).Magnitude <= qNb.r then
                            kNb = kNb - 0.5
                            break
                        end
                    end
                end
            end
        end
        if kNb > 0 then
            table.insert(gNb, {
                pos = iNb,
                sc = kNb,
                cov = lNb
            })
        end
        if hNb % 60 == 0 then
            task.wait()
        end
    end
    table.sort(gNb, function(rNb, sNb)
        return rNb.sc > sNb.sc
    end)
    for tNb, uNb in ipairs(gNb) do
        local vNb = Match.valid(uNb.pos, PMb.data)
        if vNb then
            App.log(1, "PLACE", string.format("%s goes %s the kill box (%d%% of the road)", Units.name(PMb.id), Match.CONTROL_WORDS [dNb], math.floor(eNb * 100 + 0.5)))
            return vNb, uNb.cov, eNb
        end
        if tNb % 20 == 0 then
            task.wait()
        end
    end
    return nil
end

function Match.holdSpot(wNb)
    local xNb, yNb = Simulator.holds(wNb.id)
    if not xNb then
        return nil
    end
    local zNb, ANb = {
    }, 0
    for BNb, CNb in ipairs(Match.mine or {
    }) do
        local DNb = CNb._stats
        local ENb = DNb.id.Value
        if DNb:FindFirstChild("range") and not Units.isFarm(ENb) and not Units.allyBuff(ENb) and ENb ~= wNb.id then
            local FNb, GNb = pcall(Match.liveDps, CNb, ENb)
            GNb = FNb and tonumber(GNb) or 0
            if GNb > 0 then
                table.insert(zNb, {
                    p = Utils.flat(CNb:GetPivot().Position),
                    r = DNb.range.Value,
                    d = GNb
                })
                ANb = ANb + GNb
            end
        end
    end
    if # zNb == 0 or ANb <= 0 then
        return nil
    end
    local HNb = {
    }
    for INb, JNb in ipairs(Match.samples) do
        local KNb, LNb = Utils.flat(JNb.pos), 0
        for MNb, NNb in ipairs(zNb) do
            if (KNb - NNb.p).Magnitude <= NNb.r then
                LNb = LNb + NNb.d
            end
        end
        HNb [INb] = LNb / ANb
    end
    local ONb = Units.range(wNb.u, math.min(tonumber(yNb) or 0, 3, Units.rows(wNb.id).max)) * ((Match.info and tonumber(Match.info.rangeScale)) or 1)
    local PNb, QNb, RNb
    for SNb, TNb in ipairs(Match.cands) do
        local UNb, VNb, WNb = Utils.flat(TNb), 0, 0
        for XNb, YNb in ipairs(Match.samples) do
            if (Utils.flat(YNb.pos) - UNb).Magnitude <= ONb then
                VNb = VNb + HNb [XNb]
                WNb = WNb + 1
            end
        end
        if VNb > 0 and (not QNb or VNb > QNb) then
            local ZNb = Match.valid(TNb, wNb.data)
            if ZNb then
                PNb, QNb, RNb = ZNb, VNb, WNb
            end
        end
        if SNb % 40 == 0 then
            task.wait()
        end
    end
    if not PNb then
        return nil
    end
    Match.holdSaid = Match.holdSaid or {
    }
    if not Match.holdSaid [wNb.id] then
        Match.holdSaid [wNb.id] = true
        App.log(1, "PLACE", string.format("%s holds enemies, so it stands where your attackers' damage is: what it holds stays under all of them", Units.name(wNb.id)))
    end
    return PNb, RNb or 0
end

function Match.bestSpot(_Nb, aOb, bOb)
    if Match.focus and not aOb and not bOb and not Units.allyBuff(_Nb.id) then
        local cOb, dOb = Match.focusSpot(_Nb)
        if cOb then
            return cOb, dOb
        end
    end
    if not aOb and not bOb and not (Match.depth and Match.depth.leak) then
        local eOb, fOb, gOb = pcall(Match.controlSpot, _Nb)
        if eOb and fOb then
            return fOb, gOb
        end
        local hOb, iOb, jOb = pcall(Match.holdSpot, _Nb)
        if hOb and iOb then
            return iOb, jOb
        end
    end
    local kOb = Match.depth and Match.depth.leak
    if Match.layout and Match.layout [_Nb.id] and not aOb and not bOb then
        local lOb = false
        for mOb, nOb in ipairs(Match.mine or {
        }) do
            local oOb = nOb._stats:FindFirstChild("uuid")
            if oOb and oOb.Value == _Nb.uuid then
                lOb = true
                break
            end
        end
        if not lOb then
            for pOb, qOb in ipairs(Match.layout [_Nb.id]) do
                local rOb = Match.valid(qOb, _Nb.data)
                if rOb and kOb then
                    local sOb, tOb, uOb = false, Utils.flat(rOb), Units.range(_Nb.u, 0) * ((Match.info and tonumber(Match.info.rangeScale)) or 1)
                    for vOb, wOb in ipairs(Match.samples) do
                        if wOb.prog >= kOb + 0.02 and (Utils.flat(wOb.pos) - tOb).Magnitude <= uOb then
                            sOb = true
                            break
                        end
                    end
                    if not sOb then
                        rOb = nil
                    end
                end
                if rOb then
                    Match.layoutUsed = Match.layoutUsed or {
                    }
                    Match.layoutUsed [_Nb.id] = rOb
                    return rOb, Match.cover(rOb, Units.range(_Nb.u, math.min(3, Units.rows(_Nb.id).max)) * ((Match.info and tonumber(Match.info.rangeScale)) or 1))
                end
            end
        end
    end
    local xOb = _Nb.data
    local yOb = Match.depth
    local zOb
    if bOb then
        zOb = 1
        for AOb, BOb in ipairs(Match.mine or {
        }) do
            local COb = BOb._stats
            if not Units.isFarm(COb.id.Value) and not (COb:FindFirstChild("uuid") and COb.uuid.Value == _Nb.uuid) then
                local DOb, EOb = Utils.flat(BOb:GetPivot().Position), COb.range.Value
                for FOb, GOb in ipairs(Match.samples) do
                    if GOb.prog < zOb and (Utils.flat(GOb.pos) - DOb).Magnitude <= EOb then
                        zOb = GOb.prog
                    end
                end
            end
        end
        if Units.ENTRY [_Nb.id] or (Match.studyEntry and _Nb.id == Match.trialId) then
            zOb = math.min(zOb, 0.1)
        end
    end
    local HOb = (Match.info and tonumber(Match.info.rangeScale)) or 1
    local IOb = Units.range(_Nb.u, (yOb and yOb.leak) and 0 or math.min(3, Units.rows(_Nb.id).max)) * HOb
    local JOb = (Match.kind == "dungeon" or Match.style == "box" or Match.style == "fast") and not aOb and not (yOb and yOb.leak) and not Units.isFarm(_Nb.id) and Units.range(_Nb.u, Units.rows(_Nb.id).max) * HOb or nil
    local KOb = Units.allyBuff(_Nb.id)
    if Match.killZone() and not aOb and not bOb and not KOb and not (yOb and yOb.leak) and not Units.isFarm(_Nb.id) then
        local LOb = JOb or IOb
        local MOb = {
        }
        for NOb, OOb in ipairs(Match.mine or {
        }) do
            local POb = OOb._stats
            local QOb = POb.id.Value
            if not Units.isFarm(QOb) and not Units.allyBuff(QOb) and POb:FindFirstChild("range") then
                table.insert(MOb, {
                    p = Utils.flat(OOb:GetPivot().Position),
                    r = POb.range.Value
                })
            end
        end
        local ROb = {
        }
        for SOb, TOb in ipairs(Match.samples) do
            local UOb = 0
            local VOb = Utils.flat(TOb.pos)
            for WOb, XOb in ipairs(MOb) do
                if (VOb - XOb.p).Magnitude <= XOb.r then
                    UOb = UOb + 1
                end
            end
            ROb [SOb] = UOb
        end
        local YOb, ZOb, _Ob
        local aPb = 0
        for bPb, cPb in ipairs(Match.cands) do
            local dPb = Match.valid(cPb, xOb)
            aPb = aPb + 1
            if aPb % 40 == 0 then
                task.wait()
            end
            if dPb then
                local ePb, fPb, gPb = Utils.flat(dPb), 0, 0
                for hPb, iPb in ipairs(Match.samples) do
                    if (Utils.flat(iPb.pos) - ePb).Magnitude <= LOb then
                        gPb = gPb + 1
                        if iPb.prog >= 0.6 then
                            fPb = fPb + (iPb.prog - 0.5) * (1 + ROb [hPb])
                        end
                    end
                end
                if not ZOb or fPb > ZOb then
                    YOb, ZOb, _Ob = dPb, fPb, gPb
                end
            end
        end
        if YOb and ZOb > 0 then
            if not Match.zoneSaid then
                Match.zoneSaid = true
                App.log(1, "PLACE", "attackers stack on the road's last stretch, so what walks in takes everyone's damage at once")
            end
            return YOb, _Ob or 0
        end
    end
    if Match.style == "fast" and not aOb and not bOb and not KOb and not (yOb and yOb.leak) and not Units.isFarm(_Nb.id) then
        local jPb = JOb or IOb
        local kPb, lPb, mPb
        local nPb = 0
        for oPb, pPb in ipairs(Match.cands) do
            local qPb = Match.valid(pPb, xOb)
            nPb = nPb + 1
            if nPb % 40 == 0 then
                task.wait()
            end
            if qPb then
                local rPb, sPb, tPb = Utils.flat(qPb), 0, 0
                for uPb, vPb in ipairs(Match.samples) do
                    if (Utils.flat(vPb.pos) - rPb).Magnitude <= jPb then
                        tPb = tPb + 1
                        if vPb.prog <= Match.FAST_ROAD then
                            sPb = sPb + 1.5 - vPb.prog
                        end
                    end
                end
                if not lPb or sPb > lPb then
                    kPb, lPb, mPb = qPb, sPb, tPb
                end
            end
        end
        if kPb and lPb > 0 then
            return kPb, mPb or 0
        end
    end
    local wPb = Match.infinite and Match.trainee and not bOb and _Nb.uuid ~= Match.trainee and not Units.isFarm(_Nb.id) and not KOb and not aOb and not (yOb and yOb.leak) and (Match.pressure or 0) < Config.dangerReach and Training.ZONE or nil
    local xPb = wPb and Units.range(_Nb.u, Units.rows(_Nb.id).max) or nil
    local yPb, zPb = Units.types(_Nb.id)
    local APb = KOb and {
    } or Match.fieldBuffers()
    local BPb, CPb = {
    }, 0
    if KOb then
        BPb = Match.buffShort(KOb)
        for DPb, EPb in ipairs(BPb) do
            CPb = CPb + EPb.dps
        end
    end
    local FPb = Config.community and not zOb and Core.TIPS [_Nb.id]
    local GPb = ((FPb and FPb.spot == "exit") or (not zOb and Match.needLastLine(_Nb))) and not (yOb and yOb.leak)
    local HPb = not (zOb or aOb or KOb) and Match.mergeSpot(_Nb)
    local IPb = HPb and Units.range(_Nb.u, 0) * 0.7
    local JPb, KPb
    if aOb and Units.isFarm(_Nb.id) then
        JPb, KPb = Match.farmMergeSpot(_Nb)
        KPb = JPb and KPb * 0.8
    end
    local LPb = aOb and not JPb and Match.random and Units.isFarm(_Nb.id) and Match.farmMergeOk() and {
    } or nil
    local MPb = Match.cands
    local NPb, OPb = JPb or HPb, JPb and KPb or IPb
    if NPb and OPb and OPb > 0 then
        MPb = table.clone(Match.cands)
        for PPb, QPb in ipairs({
            0.5,
            0.7,
            0.9
        }) do
            for RPb = 0, 11 do
                local SPb = RPb * math.pi / 6
                table.insert(MPb, NPb + Vector3.new(math.cos(SPb), 0, math.sin(SPb)) * OPb * QPb)
            end
        end
    end
    local TPb, UPb, VPb
    local WPb = 0
    local XPb = Brain.maps [Match.mapKey()] and Brain.maps [Match.mapKey()].dens
    for YPb, ZPb in ipairs(MPb) do
        local _Pb = Match.valid(ZPb, xOb)
        WPb = WPb + 1
        if WPb % 40 == 0 then
            task.wait()
        end
        if _Pb then
            local aQb
            if aOb then
                aQb = - Match.cover(_Pb, IOb)
            elseif zOb then
                aQb = 0
                local bQb = Utils.flat(_Pb)
                for cQb, dQb in ipairs(Match.samples) do
                    if (Utils.flat(dQb.pos) - bQb).Magnitude <= IOb then
                        aQb = aQb + (dQb.prog <= zOb + 0.05 and 1 or 0.1)
                    end
                end
            elseif wPb then
                aQb = 0
                local eQb = Utils.flat(_Pb)
                for fQb, gQb in ipairs(Match.samples) do
                    local hQb = (Utils.flat(gQb.pos) - eQb).Magnitude
                    if gQb.prog < wPb then
                        if hQb <= xPb then
                            aQb = aQb - 2
                        end
                    elseif hQb <= IOb then
                        aQb = aQb + 1
                    end
                end
            elseif GPb then
                aQb = 0
                local iQb = Utils.flat(_Pb)
                for jQb, kQb in ipairs(Match.samples) do
                    if (Utils.flat(kQb.pos) - iQb).Magnitude <= IOb then
                        aQb = aQb + kQb.prog * kQb.prog
                    end
                end
            elseif KOb and CPb > 0 then
                local lQb = 0
                for mQb, nQb in ipairs(BPb) do
                    local oQb = (Utils.flat(nQb.pos) - Utils.flat(_Pb)).Magnitude
                    if oQb <= IOb then
                        lQb = lQb + nQb.dps * (1.1 - 0.1 * oQb / math.max(1, IOb))
                    end
                end
                aQb = lQb / CPb * 100 + Match.cover(_Pb, IOb, true) * 0.05
            else
                local pQb = Match.cover(_Pb, IOb, true, yOb)
                if JOb then
                    pQb = Match.cover(_Pb, JOb) + pQb * 0.25
                end
                aQb = pQb + (XPb and 0 or (1 - Match.progressAt(_Pb)) * 0.5)
                local qQb = 0
                for rQb, sQb in ipairs(APb) do
                    local tQb = sQb.b.types [zPb]
                    if tQb and (Utils.flat(sQb.pos) - Utils.flat(_Pb)).Magnitude <= sQb.range then
                        qQb = math.max(qQb, math.min(tQb, qQb + tQb * sQb.b.uptime))
                    end
                end
                aQb = aQb * (1 + qQb)
            end
            if HPb and (Utils.flat(HPb) - Utils.flat(_Pb)).Magnitude <= IPb then
                aQb = aQb + 1e6
            end
            if JPb and (Utils.flat(JPb) - Utils.flat(_Pb)).Magnitude <= KPb then
                aQb = aQb + 1e6
            end
            if LPb then
                table.insert(LPb, {
                    p = _Pb,
                    sc = aQb
                })
            end
            if not UPb or aQb > UPb then
                TPb, UPb, VPb = _Pb, aQb, Match.cover(_Pb, IOb)
            end
        end
    end
    if KOb and # BPb > 0 and TPb then
        local uQb = false
        for vQb, wQb in ipairs(BPb) do
            if (Utils.flat(wQb.pos) - Utils.flat(TPb)).Magnitude <= IOb then
                uQb = true
                break
            end
        end
        if not uQb then
            return nil, 0
        end
    end
    if LPb and # LPb > 0 then
        table.sort(LPb, function(xQb, yQb)
            return xQb.sc > yQb.sc
        end)
        for zQb = 1, math.min(15, # LPb) do
            local AQb, BQb = LPb [zQb].p, 0
            for CQb = 0, 7 do
                local DQb = CQb * math.pi / 4
                if Match.valid(AQb + Vector3.new(math.cos(DQb), 0, math.sin(DQb)) * 5, xOb) then
                    BQb = BQb + 1
                end
                if BQb >= 2 then
                    break
                end
            end
            if BQb >= 2 then
                return AQb, Match.cover(AQb, IOb)
            end
        end
    end
    return TPb, VPb or 0
end

function Match.lookAt(EQb)
    local FQb, GQb = math.huge, nil
    for HQb, IQb in ipairs(Match.samples) do
        local JQb = (Utils.flat(IQb.pos) - Utils.flat(EQb)).Magnitude
        if JQb < FQb then
            FQb, GQb = JQb, IQb.pos
        end
    end
    local KQb = GQb and Utils.flat(GQb - EQb) or Vector3.new(0, 0, - 1)
    return KQb.Magnitude > 0.01 and KQb.Unit or Vector3.new(0, 0, - 1)
end

function Match.place(LQb, MQb)
    local NQb = Units.isFarm(LQb.id)
    local OQb, PQb = Match.bestSpot(LQb, NQb or (Match.random and Units.idol(LQb.id)), (Match.trainee ~= nil and LQb.uuid == Match.trainee) or Units.ENTRY [LQb.id] == true or (Match.studyEntry == true and LQb.id == Match.trialId))
    if not OQb then
        Match.noSpot [LQb.uuid] = (Match.noSpot [LQb.uuid] or 0) + 1
        App.status("Placement", "no free spot for " .. Units.name(LQb.id))
        return false
    end
    local QQb = Match.money()
    local RQb, SQb = App.request("place", "spawn_unit", LQb.uuid, Core.Util.CFramePLV(OQb, Match.lookAt(OQb)))
    if RQb and SQb then
        Match.spent = Match.spent + (LQb.data.cost or 0)
        table.insert(Match.actions, string.format("placed %s", Units.name(LQb.id)))
        App.log(1, "PLACE", string.format("%s at %s (covers %d road samples) — %s", Units.name(LQb.id), Match.spotKey(OQb), PQb, MQb))
        Match.placeLog = Match.placeLog or {
        }
        table.insert(Match.placeLog, {
            t = math.floor(Utils.now() - (Match.startT or Utils.now())),
            w = Match.wave(),
            id = LQb.id,
            x = math.floor(OQb.X),
            z = math.floor(OQb.Z),
            cover = math.floor((PQb or 0) + 0.5),
            why = tostring(MQb):sub(1,
            90)
        })
        App.status("Placement", string.format("placed %s — %s", Units.name(LQb.id), MQb))
        Match.placedAt = Match.placedAt or {
        }
        Match.placedAt [LQb.uuid] = (Match.placedAt [LQb.uuid] or 0) + 1
        return true
    end
    if QQb >= (LQb.data.cost or 0) and Match.random then
        Match.placeFail = Match.placeFail or {
        }
        Match.placeFail [LQb.uuid] = (Match.placeFail [LQb.uuid] or 0) + 1
        if Match.placeFail [LQb.uuid] >= 2 then
            Match.noSpot [LQb.uuid] = 3
            App.log(1, "PLACE", string.format("the game refused %s twice (%d/%d units counted) — buying something else", Units.name(LQb.id), Match.fieldCount(), Match.FIELD_MAX))
        end
    end
    if RQb and QQb >= (LQb.data.cost or 0) and not Match.random then
        local TQb = Match.spotKey(OQb)
        Match.refused [TQb] = true
        local UQb = Match.mapKey()
        Brain.blocked [UQb] = Brain.blocked [UQb] or {
        }
        if not Match.refusedRun [TQb] then
            Brain.blocked [UQb] [TQb] = (tonumber(Brain.blocked [UQb] [TQb]) or 0) + 1
            Match.refusedRun [TQb] = true
        end
        Match.refusals = (Match.refusals or 0) + 1
        Match.unitRefusals [LQb.uuid] = (Match.unitRefusals [LQb.uuid] or 0) + 1
        if Match.unitRefusals [LQb.uuid] >= 3 then
            local VQb = math.max(1, Match.count(LQb.uuid))
            if Brain.caps [LQb.uuid] ~= VQb then
                Brain.caps [LQb.uuid] = VQb
                App.log(1, "PLACE", string.format("%s: the server allows %d on the field (learned)", Units.name(LQb.id), VQb))
            end
        end
        App.log(2, "PLACE", "refused spot " .. TQb .. " for " .. Units.name(LQb.id))
        App.saveSoon()
    end
    return false
end

function Match.count(WQb)
    local XQb = 0
    for YQb, ZQb in ipairs({
        workspace._UNITS,
        workspace:FindFirstChild("_DEAD_UNITS")
    }) do
        if ZQb then
            for _Qb, aRb in ipairs(ZQb:GetChildren()) do
                local bRb = aRb:FindFirstChild("_stats")
                if bRb and bRb:FindFirstChild("uuid") and bRb.player.Value == LocalPlayer and bRb.uuid.Value == WQb then
                    XQb = XQb + 1
                end
            end
        end
    end
    return XQb
end

function Match.measure()
    local cRb, dRb = Match.calRun, Match.info
    if not (cRb and dRb) then
        return
    end
    pcall(Match.sampleHelpers)
    local eRb = Utils.now()
    local fRb = Match.wave()
    local gRb = Match.money()
    if not cRb.start and gRb > 0 and # Match.mine == 0 then
        cRb.start = gRb
    end
    if fRb ~= cRb.lastW then
        if Match.trialId and fRb > 0 then
            Match.trialTrace = Match.trialTrace or {
            }
            local hRb, iRb, jRb, kRb = 0, {
            }, 0, 0
            for lRb, mRb in ipairs(Match.mine) do
                local nRb = mRb._stats
                if nRb.id.Value == Match.trialId then
                    hRb = hRb + 1
                    table.insert(iRb, tostring(nRb.upgrade.Value))
                elseif not Units.isFarm(nRb.id.Value) then
                    kRb = kRb + 1
                end
            end
            pcall(Match.sampleHelpers, true)
            for oRb, pRb in pairs(Match.ownDealt) do
                if pRb.id == Match.trialId then
                    jRb = jRb + pRb.v
                end
            end
            local qRb = 0
            for rRb, sRb in pairs(Match.helperDealt) do
                if sRb.owner == Match.trialId then
                    qRb = qRb + sRb.v
                end
            end
            table.insert(Match.trialTrace, string.format("w%d t=%.0f ¥%d copies[%s] others %d dealt %.0f alive %d hp %.0f front %.2f dps %.0f", fRb, eRb - (Match.startT or eRb), gRb, table.concat(iRb, ","), kRb, jRb + qRb, # (Match.enemies or {
            }), Match.hpAliveRaw or 0, Match.waveMax [fRb - 1] or 0, Match.teamDps or 0))
        end
        if cRb.lastW and cRb.lastW > 0 and cRb.lastWT then
            table.insert(cRb.waveSec, eRb - cRb.lastWT)
        end
        if cRb.paidT and fRb > 0 and eRb - cRb.paidT < 15 then
            table.insert(cRb.skip, eRb - cRb.paidT)
        end
        cRb.paidT = nil
        if fRb > 0 then
            cRb.alive [tostring(fRb)] = Match.hpAliveRaw or 0
        end
        cRb.lastW, cRb.lastWT = fRb, eRb
    end
    local tRb = workspace:FindFirstChild("_wave_time")
    if tRb and fRb > 0 then
        cRb.timer [tostring(fRb)] = math.max(cRb.timer [tostring(fRb)] or 0, tonumber(tRb.Value) or 0)
    end
    local uRb = gRb - (Match.lastMoneyR or gRb)
    Match.lastMoneyR = gRb
    Match.incomeLog = Match.incomeLog or {
    }
    if uRb > 0 then
        table.insert(Match.incomeLog, {
            t = eRb,
            y = uRb
        })
    end
    while Match.incomeLog [1] and eRb - Match.incomeLog [1].t > 30 do
        table.remove(Match.incomeLog, 1)
    end
    local vRb = 0
    for wRb, xRb in ipairs(Match.incomeLog) do
        vRb = vRb + xRb.y
    end
    local yRb = math.min(30, eRb - (Match.startT or eRb))
    Match.incomeRate = yRb >= 8 and vRb / yRb or nil
    for zRb, ARb in ipairs(Match.enemies) do
        local BRb = ARb.m
        local CRb = Match.track [BRb]
        if not CRb then
            local DRb = BRb._stats
            local ERb = BRb:FindFirstChildOfClass("Humanoid")
            local FRb = dRb.cfgById [DRb.id.Value]
            local GRb = FRb and Simulator.baseStats(dRb, FRb)
            if ERb and GRb and fRb > 0 then
                local HRb = GRb * dRb.hpRaw * Simulator.waveScale(dRb, fRb, dRb.list [fRb])
                if HRb > 0 and ERb.MaxHealth > 0 then
                    table.insert(cRb.hp, ERb.MaxHealth / HRb)
                end
            end
            Match.track [BRb] = {
                t = eRb,
                p = ARb.prog,
                sp = (DRb:FindFirstChild("speed") and tonumber(DRb.speed.Value)) or 1
            }
            if fRb > 0 then
                cRb.spawn [tostring(fRb)] = (cRb.spawn [tostring(fRb)] or 0) + 1
                cRb.spawnLast [tostring(fRb)] = eRb - (cRb.lastWT or eRb)
            end
        elseif not CRb.done and eRb - CRb.t >= 15 then
            CRb.done = true
            local IRb = (ARb.prog - CRb.p) / (eRb - CRb.t) / math.max(0.1, CRb.sp)
            if IRb > 0.001 and ARb.prog < 0.95 then
                table.insert(cRb.walk, IRb)
            end
        end
    end
    local JRb = 0
    for KRb, LRb in ipairs(Match.mine) do
        local MRb = LRb._stats:FindFirstChild("total_damage")
        if MRb then
            JRb = JRb + MRb.Value
        end
    end
    cRb.potSum = cRb.potSum or 0
    if cRb.lastDealtT then
        local NRb = eRb - cRb.lastDealtT
        local ORb = 0
        for PRb, QRb in ipairs(Match.mine) do
            local RRb = QRb._stats
            local SRb = RRb.id.Value
            if not Units.isFarm(SRb) and RRb:FindFirstChild("target") and RRb.target.Value ~= nil then
                local TRb, URb = pcall(Match.liveDps, QRb, SRb)
                if TRb and URb then
                    ORb = ORb + URb * NRb
                end
            end
        end
        cRb.potWin = (cRb.potWin or 0) + ORb
        if eRb - (cRb.winT or eRb) >= 5 then
            local VRb = JRb - (cRb.winDealt or JRb)
            if cRb.potWin > 0 and VRb >= 0 then
                cRb.dealtSum = (cRb.dealtSum or 0) + VRb
                cRb.potSum = cRb.potSum + cRb.potWin
            end
            cRb.winT, cRb.winDealt, cRb.potWin = eRb, JRb, 0
        end
    end
    if not cRb.winT then
        cRb.winT, cRb.winDealt = eRb, JRb
    end
    cRb.lastDealtT = eRb
    if fRb ~= cRb.dpsW and fRb > 0 then
        cRb.dpsAt [tostring(fRb)] = Match.teamDps or 0
        cRb.dpsW = fRb
    end
    local WRb = math.min(1, eRb - (cRb.densT or eRb))
    cRb.densT = eRb
    for XRb, YRb in ipairs(Match.enemies) do
        local ZRb = math.min(Simulator.BINS, math.floor(YRb.prog * Simulator.BINS) + 1)
        cRb.dens [ZRb] = (cRb.dens [ZRb] or 0) + WRb
    end
    local _Rb = workspace._BASES.player:FindFirstChild("base")
    local aSb = _Rb and _Rb:FindFirstChild("fake_unit")
    local bSb = aSb and aSb:FindFirstChildOfClass("Humanoid")
    if bSb then
        cRb.baseHp = math.max(cRb.baseHp or 0, bSb.MaxHealth)
        local cSb = 0
        for dSb, eSb in ipairs(Match.enemies) do
            if eSb.prog >= 0.97 then
                local fSb = eSb.m:FindFirstChildOfClass("Humanoid")
                cSb = cSb + (fSb and fSb.MaxHealth or eSb.hp)
            end
        end
        if cRb.lastBase and bSb.Health < cRb.lastBase and cSb > 0 and cRb.lastBaseT then
            table.insert(cRb.baseRel, (cRb.lastBase - bSb.Health) / math.max(0.1, eRb - cRb.lastBaseT) / cSb)
        end
        cRb.lastBase, cRb.lastBaseT = bSb.Health, eRb
    end
end

function Match.recordMap()
    local gSb = Match.mapKey()
    local hSb = Brain.maps [gSb]
    if hSb and hSb.v == 1 and hSb.laneV and (hSb.densN or 0) == (hSb.binsDensN or 0) then
        return
    end
    if hSb and hSb.v == 1 and hSb.laneV and (hSb.densN or 0) > 5 and (hSb.binsDensN or 0) >= 5 then
        return
    end
    local iSb = {
        override_hitbox_radius = 1.75
    }
    local jSb = {
        hill_unit = true,
        override_hitbox_radius = 1.75
    }
    local kSb, lSb = {
    }, false
    for mSb, nSb in ipairs(Match.cands) do
        local oSb = Match.valid(nSb, iSb)
        if oSb then
            table.insert(kSb, oSb)
        end
        if not lSb and Match.valid(nSb, jSb) then
            lSb = true
        end
        if mSb % 30 == 0 then
            task.wait()
        end
    end
    local pSb, qSb = {
    }, {
    }
    local rSb = Simulator.laneList(Match.samples)
    for sSb = 5, 60, 5 do
        local tSb, uSb
        for vSb, wSb in ipairs(kSb) do
            local xSb = Match.cover(wSb, sSb, true)
            if not uSb or xSb > uSb then
                tSb, uSb = wSb, xSb
            end
        end
        if tSb then
            local ySb, zSb = {
            }, {
            }
            for ASb = 1, Simulator.BINS do
                ySb [ASb] = "0"
            end
            for BSb, CSb in ipairs(rSb or {
            }) do
                zSb [CSb] = {
                }
                for DSb = 1, Simulator.BINS do
                    zSb [CSb] [DSb] = "0"
                end
            end
            local ESb = Utils.flat(tSb)
            for FSb, GSb in ipairs(Match.samples) do
                if (Utils.flat(GSb.pos) - ESb).Magnitude <= sSb then
                    local HSb = math.min(Simulator.BINS, math.floor(GSb.prog * Simulator.BINS) + 1)
                    ySb [HSb] = "1"
                    if zSb [tostring(GSb.lane)] then
                        zSb [tostring(GSb.lane)] [HSb] = "1"
                    end
                end
            end
            pSb [tostring(sSb)] = table.concat(ySb)
            if rSb then
                qSb [tostring(sSb)] = {
                }
                for ISb, JSb in pairs(zSb) do
                    qSb [tostring(sSb)] [ISb] = table.concat(JSb)
                end
            end
        end
        task.wait()
    end
    local KSb = Brain.maps [gSb] or {
    }
    Brain.maps [gSb] = {
        v = 1,
        laneV = 1,
        bins = pSb,
        binsL = rSb and qSb or nil,
        lanes = rSb,
        hill = lSb,
        spots = # kSb,
        dens = KSb.dens,
        densN = KSb.densN,
        binsDensN = KSb.densN or 0,
        lay = KSb.lay,
        walk = KSb.walk,
        walkN = KSb.walkN
    }
    Simulator._masks = {
    }
    App.log(1, "SIM", string.format("mapped %s: %d free spots%s", gSb, # kSb, lSb and ", hill spots too" or ", no hill spots"))
    App.saveSoon()
end
Match.helperDealt, Match.helperAt, Match.ownDealt = {
}, 0, {
}

function Match.sampleHelpers(LSb)
    if not LSb and Utils.now() - Match.helperAt < 3 then
        return
    end
    Match.helperAt = Utils.now()
    local MSb = workspace:FindFirstChild("_UNITS")
    local NSb = {
    }
    for OSb, PSb in ipairs(Match.mine or {
    }) do
        NSb [PSb] = true
        local QSb = PSb:FindFirstChild("_stats")
        local RSb = QSb and QSb:FindFirstChild("total_damage")
        if RSb and QSb:FindFirstChild("id") then
            local SSb = Match.ownDealt [PSb] or {
                id = QSb.id.Value,
                v = 0,
                lvl = 0
            }
            SSb.v = math.max(SSb.v, RSb.Value)
            SSb.lvl = math.max(SSb.lvl, QSb:FindFirstChild("upgrade") and tonumber(QSb.upgrade.Value) or 0)
            Match.ownDealt [PSb] = SSb
        end
    end
    for TSb, USb in ipairs(MSb and MSb:GetChildren() or {
    }) do
        local VSb = USb:FindFirstChild("_stats")
        local WSb = VSb and VSb:FindFirstChild("parent_unit")
        local XSb = VSb and VSb:FindFirstChild("total_damage")
        if WSb and XSb and WSb.Value ~= nil and NSb [WSb.Value] then
            local YSb = WSb.Value:FindFirstChild("_stats")
            local ZSb = Match.helperDealt [USb] or {
                id = VSb.id.Value,
                owner = YSb and YSb:FindFirstChild("id") and YSb.id.Value or nil,
                v = 0
            }
            ZSb.v = math.max(ZSb.v, XSb.Value)
            Match.helperDealt [USb] = ZSb
        end
    end
end

function Match.watchHelpers()
    local _Sb = workspace:FindFirstChild("_UNITS")
    if not _Sb then
        return
    end
    table.insert(App.conns, _Sb.ChildAdded:Connect(function(aTb)
        task.spawn(function()
            local bTb = aTb:WaitForChild("_stats", 3)
            task.wait(0.1)
            local cTb = bTb and bTb:FindFirstChild("parent_unit")
            local dTb = bTb and bTb:FindFirstChild("total_damage")
            if not (dTb and cTb and cTb.Value) then
                return
            end
            local eTb = cTb.Value:FindFirstChild("_stats")
            local fTb = eTb and eTb:FindFirstChild("id") and eTb.id.Value or nil
            if not fTb then
                return
            end
            local gTb = false
            for hTb, iTb in ipairs(Match.mine or {
            }) do
                if iTb == cTb.Value then
                    gTb = true
                    break
                end
            end
            if not gTb then
                return
            end
            local function jTb()
                local kTb = Match.helperDealt [aTb] or {
                    id = bTb.id.Value,
                    owner = fTb,
                    v = 0
                }
                kTb.v = math.max(kTb.v, dTb.Value)
                Match.helperDealt [aTb] = kTb
            end
            jTb()
            table.insert(App.conns, dTb.Changed:Connect(jTb))
        end)
    end))
end

function Match.damageShares()
    pcall(Match.sampleHelpers, true)
    local lTb, mTb = {
    }, 0
    local function nTb(oTb, pTb)
        lTb [oTb] = (lTb [oTb] or 0) + pTb
        mTb = mTb + pTb
    end
    for qTb, rTb in pairs(Match.ownDealt) do
        if not Units.isFarm(rTb.id) then
            nTb(rTb.id, rTb.v)
        end
    end
    local sTb = 0
    for tTb, uTb in pairs(Match.helperDealt) do
        nTb(uTb.owner or "helpers", uTb.v)
        sTb = sTb + 1
    end
    if mTb <= 0 then
        return nil
    end
    for vTb, wTb in pairs(lTb) do
        lTb [vTb] = wTb / mTb
    end
    return lTb, mTb, sTb
end

function Match.summonSplit()
    local xTb, yTb = {
    }, {
    }
    for zTb, ATb in pairs(Match.ownDealt) do
        xTb [ATb.id] = (xTb [ATb.id] or 0) + (tonumber(ATb.v) or 0)
    end
    for BTb, CTb in pairs(Match.helperDealt) do
        if CTb.owner then
            yTb [CTb.owner] = (yTb [CTb.owner] or 0) + (tonumber(CTb.v) or 0)
        end
    end
    local DTb = {
    }
    for ETb, FTb in pairs(yTb) do
        local GTb = FTb + (xTb [ETb] or 0)
        if GTb > 0 then
            DTb [ETb] = {
                share = FTb / GTb,
                total = GTb
            }
        end
    end
    return DTb
end

function Match.damageLine()
    local HTb, ITb, JTb = Match.damageShares()
    if not HTb then
        return nil
    end
    local KTb = {
    }
    for LTb, MTb in pairs(HTb) do
        table.insert(KTb, {
            name = LTb == "helpers" and "helpers" or Units.name(LTb),
            v = MTb
        })
    end
    table.sort(KTb, function(NTb, OTb)
        return NTb.v > OTb.v
    end)
    local PTb = {
    }
    for QTb, RTb in ipairs(KTb) do
        table.insert(PTb, string.format("%s %d%%", RTb.name, math.floor(RTb.v * 100 + 0.5)))
    end
    local STb, TTb = pcall(Match.summonSplit)
    local UTb = {
    }
    for VTb, WTb in pairs(STb and TTb or {
    }) do
        if WTb.share >= 0.05 and WTb.total >= 0.01 * ITb then
            table.insert(UTb, string.format("%s %d%%", Units.name(VTb), math.floor(WTb.share * 100 + 0.5)))
        end
    end
    table.sort(UTb)
    return string.format("%s dealt: %s%s%s", Utils.fmt(ITb), table.concat(PTb, " · "), JTb > 0 and string.format(" (%d helpers)", JTb) or "", # UTb > 0 and (" · from summons: " .. table.concat(UTb, ", ")) or "")
end

function Match.calMerge(XTb)
    local YTb = Match.calRun
    if not (YTb and Match.key) then
        return
    end
    local ZTb = Simulator.cal(Match.key)
    ZTb.n = (tonumber(ZTb.n) or 0) + 1
    local _Tb = math.max(0.2, 1 / ZTb.n)
    local function aUb(bUb)
        if # bUb == 0 then
            return nil
        end
        table.sort(bUb)
        return bUb [math.ceil(# bUb / 2)]
    end
    local function cUb(dUb, eUb)
        if eUb then
            ZTb [dUb] = ZTb [dUb] and (ZTb [dUb] + (eUb - ZTb [dUb]) * _Tb) or eUb
        end
    end
    Match.hpRun = aUb(YTb.hp)
    cUb("hpCal", Match.hpRun)
    cUb("walk", aUb(YTb.walk))
    do
        local fUb, gUb = aUb(YTb.walk), Match.mapKey()
        if fUb then
            local hUb = Simulator.mapWalk(gUb)
            Brain.maps [gUb] = Brain.maps [gUb] or {
            }
            local iUb = Brain.maps [gUb]
            iUb.walkN = (tonumber(iUb.walkN) or 0) + 1
            iUb.walk = hUb and (hUb + (fUb - hUb) * math.max(0.2, 1 / (iUb.walkN + 1))) or fUb
            Simulator._walk [gUb] = iUb.walk
        end
    end
    if (YTb.potSum or 0) > 0 and (YTb.dealtSum or 0) > 0 then
        cUb("eff", Utils.clamp(YTb.dealtSum / YTb.potSum, 0.1, 2))
    end
    local jUb = Match.mapKey()
    local kUb = 0
    for lUb, mUb in pairs(YTb.dens) do
        kUb = math.max(kUb, mUb)
    end
    if kUb > 0 then
        Brain.maps [jUb] = Brain.maps [jUb] or {
        }
        local nUb = type(Brain.maps [jUb].dens) == "table" and Brain.maps [jUb].dens or {
        }
        local oUb = (tonumber(Brain.maps [jUb].densN) or 0) + 1
        for pUb = 1, Simulator.BINS do
            local qUb = (YTb.dens [pUb] or 0) / kUb
            local rUb = tonumber(nUb [pUb])
            nUb [pUb] = rUb and (rUb + (qUb - rUb) * math.max(0.2, 1 / oUb)) or qUb
        end
        Brain.maps [jUb].dens, Brain.maps [jUb].densN = nUb, oUb
    end
    if # YTb.pay >= 2 then
        cUb("yenCal", Utils.clamp(aUb(YTb.pay), 0.5, 2))
    end
    if not Match.joinedMid then
        cUb("waveSec", aUb(YTb.waveSec))
        cUb("baseRel", aUb(YTb.baseRel))
        ZTb.baseDps = nil
        cUb("skipDelay", aUb(YTb.skip))
        local sUb = {
        }
        for tUb = 2, Match.wave() - 1 do
            local uUb, vUb = tonumber(YTb.spawn [tostring(tUb)]), tonumber(YTb.spawnLast [tostring(tUb)])
            if uUb and vUb and uUb >= 3 then
                table.insert(sUb, vUb / (uUb - 1))
            end
        end
        if # sUb >= 3 then
            cUb("spawnGap", Utils.clamp(aUb(sUb), 0.05, 5))
        end
        local wUb = tonumber(ZTb.voteAt) or (Match.info and Match.info.voteAt) or Simulator.PRIOR.voteAt
        local xUb, yUb = {
        }, {
        }
        for zUb, AUb in ipairs(YTb.votes) do
            local BUb = tonumber(AUb.n) or 0
            if BUb > 0 and Simulator.PRIOR.voteBase + Simulator.PRIOR.votePer * BUb >= wUb + 3 then
                table.insert(xUb, AUb.t)
            elseif BUb > 0 and AUb.t < wUb - 2 then
                table.insert(yUb, (AUb.t - Simulator.PRIOR.voteBase) / BUb)
            end
        end
        cUb("voteAt", aUb(xUb))
        cUb("votePer", yUb [1] and Utils.clamp(aUb(yUb), 0.2, 6) or nil)
        ZTb.voteWave = type(ZTb.voteWave) == "table" and ZTb.voteWave or {
        }
        for CUb, DUb in ipairs(YTb.votes) do
            if DUb.w and DUb.t then
                local EUb, FUb = tostring(DUb.w), tonumber(ZTb.voteWave [tostring(DUb.w)])
                ZTb.voteWave [EUb] = FUb and (FUb + (DUb.t - FUb) * _Tb) or DUb.t
            end
        end
        ZTb.timerAt = type(ZTb.timerAt) == "table" and ZTb.timerAt or {
        }
        for GUb, HUb in pairs(YTb.timer) do
            if HUb > 5 then
                local IUb = tonumber(ZTb.timerAt [GUb])
                ZTb.timerAt [GUb] = IUb and (IUb + (HUb + 1 - IUb) * _Tb) or (HUb + 1)
            end
        end
        if YTb.start then
            ZTb.start = YTb.start
        end
        if YTb.baseHp then
            ZTb.baseHp = YTb.baseHp
        end
        ZTb.yen = nil
        if Match.info then
            local JUb, KUb = 0, 0
            for LUb = 2, Match.wave() - 1 do
                local MUb = tonumber(YTb.spawn [tostring(LUb)])
                if MUb then
                    JUb = JUb + MUb
                    KUb = KUb + # (Simulator.wave(Match.info, LUb, true))
                end
            end
            if JUb > 0 and KUb > 0 then
                cUb("countCal", Utils.clamp(JUb / KUb, 0.25, 6))
            end
        end
        local NUb = {
        }
        for OUb, PUb in ipairs(Match.team or {
        }) do
            table.insert(NUb, PUb.u)
        end
        local QUb = Simulator.sig(NUb)
        local RUb = tostring(Match.ld.id or "?") .. (Hunt.is(Match.ld.id) and ("@" .. tostring(Match.ld.map)) or "")
        if ZTb.teamSig ~= QUb or ZTb.aliveLvl ~= RUb then
            ZTb.alive = {
            }
            ZTb.teamSig = QUb
            ZTb.aliveLvl = RUb
            ZTb.aliveN = 0
            ZTb.lastWave = 0
            ZTb.dpsAt = {
            }
        end
        ZTb.aliveN = (tonumber(ZTb.aliveN) or 0) + 1
        local SUb = 1 / ZTb.aliveN
        ZTb.alive = type(ZTb.alive) == "table" and ZTb.alive or {
        }
        for TUb, UUb in pairs(YTb.alive) do
            local VUb = tonumber(ZTb.alive [TUb])
            ZTb.alive [TUb] = VUb and (VUb + (UUb - VUb) * SUb) or UUb
        end
        ZTb.lastWave = math.max(tonumber(ZTb.lastWave) or 0, Match.wave())
        ZTb.dpsAt = type(ZTb.dpsAt) == "table" and ZTb.dpsAt or {
        }
        for WUb, XUb in pairs(YTb.dpsAt) do
            local YUb = tonumber(ZTb.dpsAt [WUb])
            ZTb.dpsAt [WUb] = YUb and (YUb + (XUb - YUb) * SUb) or XUb
        end
    end
    ZTb.ld = Simulator.slim(Match.ld)
    ZTb.ch = Match.ld._challenge
    Brain.simRes [Match.key] = nil
    Simulator._masks = {
    }
    if Match.pred and Match.infinite then
        App.log(1, "SIM", string.format("predicted the base falls at wave %d%s · real wave %d", Match.pred.wave, Match.pred.won and "+" or "", Match.wave()))
        ZTb.lastPred = {
            won = Match.pred.won,
            wave = Match.pred.wave,
            realWon = XTb,
            realWave = Match.wave(),
            at = os.time()
        }
    elseif Match.pred then
        App.log(1, "SIM", string.format("predicted %s at wave %d · real %s at wave %d", Match.pred.won and "a win" or "a loss", Match.pred.wave, XTb and "a win" or "a loss", Match.wave()))
        ZTb.lastPred = {
            won = Match.pred.won,
            wave = Match.pred.wave,
            realWon = XTb,
            realWave = Match.wave(),
            at = os.time()
        }
    end
end

function Match.holdGain(ZUb, _Ub)
    if Match.random or not _Ub or not Match.info then
        return 0
    end
    local aVb = Units.attackInfo(_Ub.atk, _Ub.range)
    if (aVb.stun or 0) <= 0 and (aVb.slowTime or 0) <= 0 then
        return 0
    end
    local bVb = 0
    for cVb, dVb in ipairs(Match.mine or {
    }) do
        local eVb = dVb._stats
        local fVb = Units.rows(eVb.id.Value)
        local gVb = fVb and fVb [math.min(eVb.upgrade.Value, fVb.max)]
        local hVb = gVb and gVb.atk and Units.attackInfo(gVb.atk, gVb.range)
        if hVb and ((hVb.stun or 0) > 0 or (hVb.slowTime or 0) > 0) then
            bVb = bVb + 1
        end
    end
    local iVb, jVb = Simulator.mask(Match.info.map, Units.range(ZUb.u, 0) * (Match.info.rangeScale or 1)), 0
    for kVb = 1, Simulator.BINS do
        if iVb [kVb] then
            jVb = jVb + 1
        end
    end
    local lVb = Match.depth and Match.depth.units > 0 and Match.depth.covEnd or 1
    local mVb = (Units.airFrom(ZUb.id) == 0) and 1 or (1 - (1 - Core.FLY_GROUND) * math.min(1, Match.info.flyChance or 0))
    return Economy.holdGain(aVb, Match.teamDps or 0, jVb / (math.max(0.1, lVb) * Simulator.BINS) * mVb, bVb)
end

function Match.buffGain(nVb)
    local oVb = Units.allyBuff(nVb.id)
    if not oVb then
        return 0
    end
    local pVb = Match.buffShort(oVb)
    local qVb = Brain.stack [oVb.attack]
    local rVb = qVb and qVb.stacks and (qVb.cap or 1) or nil
    local sVb, tVb = pcall(Units.range, nVb.u, 0)
    tVb = (sVb and tonumber(tVb) or 15) * ((Match.info and tonumber(Match.info.rangeScale)) or 1)
    local uVb = rVb and Config.community and tonumber(oVb.time) and tonumber(oVb.cd)
    local function vVb(wVb, xVb)
        local yVb = math.floor(wVb * oVb.time / math.max(1, oVb.cd) + 0.001)
        return math.min(rVb, (1 + xVb) ^ yVb - 1)
    end
    local zVb = 0
    for AVb, BVb in ipairs(pVb) do
        local CVb = 0
        for DVb, EVb in ipairs(pVb) do
            if (EVb.pos - BVb.pos).Magnitude <= tVb then
                local FVb = oVb.types [EVb.base]
                local GVb = FVb * oVb.uptime
                if uVb then
                    local HVb, IVb = vVb(EVb.n, FVb), EVb.n + 1
                    while IVb < EVb.n + 6 and vVb(IVb, FVb) <= HVb + 0.001 do
                        IVb = IVb + 1
                    end
                    GVb = math.max(0, (vVb(IVb, FVb) - HVb) / (IVb - EVb.n))
                elseif rVb then
                    GVb = math.max(0, math.min(rVb, (EVb.n + 1) * FVb * oVb.uptime) - math.min(rVb, EVb.n * FVb * oVb.uptime))
                end
                CVb = CVb + EVb.dps * GVb
            end
        end
        zVb = math.max(zVb, CVb)
    end
    return zVb * (uVb and 1 or 0.7)
end

function Match.buffWanted(JVb)
    return Match.buffGain(JVb) > 0.01 * (Match.teamDps or 0)
end
Match.summonHist = {
}

function Match.summonRate()
    local KVb, LVb = Utils.now(), 0
    for MVb, NVb in pairs(Match.helperDealt) do
        LVb = LVb + (tonumber(NVb.v) or 0)
    end
    local OVb = Match.summonHist
    if not OVb [# OVb] or KVb - OVb [# OVb].t >= 1 then
        table.insert(OVb, {
            t = KVb,
            v = LVb
        })
    end
    while # OVb > 2 and KVb - OVb [1].t > 30 do
        table.remove(OVb, 1)
    end
    local PVb = OVb [1]
    return (PVb and KVb - PVb.t >= 5) and math.max(0, LVb - PVb.v) / (KVb - PVb.t) or 0
end

function Match.blessGain(QVb)
    if not Units.BLESS.by [QVb.id] then
        return 0
    end
    local RVb, SVb = 0, 0
    for TVb, UVb in ipairs(Match.mine or {
    }) do
        local VVb = UVb._stats.id.Value
        if Units.BLESS.by [VVb] then
            RVb = RVb + 1
        end
        if Units.SUMMONER [VVb] then
            SVb = SVb + Match.liveDps(UVb, VVb)
        end
    end
    if RVb >= Units.BLESS.cap then
        return 0
    end
    local WVb = math.max(Match.summonRate(), SVb * (1 + Units.BLESS.dmg * RVb))
    return WVb / (1 + Units.BLESS.dmg * RVb) * Units.BLESS.dmg
end

function Match.liveDps(XVb, YVb)
    local ZVb = XVb:FindFirstChild("_stats")
    if not (ZVb and ZVb:FindFirstChild("attack_cooldown") and ZVb:FindFirstChild("damage") and ZVb:FindFirstChild("range")) then
        return 0
    end
    local _Vb = math.max(0.1, ZVb.attack_cooldown.Value)
    local aWb = ZVb:FindFirstChild("primary_attack") and ZVb.primary_attack.Value or nil
    local bWb = 0
    for cWb, dWb in ipairs({
        "physical_crit_chance",
        "magic_crit_chance"
    }) do
        local eWb = ZVb:FindFirstChild(dWb)
        if eWb then
            bWb = math.max(bWb, tonumber(eWb.Value) or 0)
        end
    end
    local fWb, gWb = Units.types(YVb)
    local hWb = "_dmg_mul_" .. tostring(gWb)
    local iWb = 1 + (tonumber(XVb:GetAttribute(hWb)) or tonumber(ZVb:GetAttribute(hWb)) or 0)
    local jWb = ZVb.damage.Value * Units.galeDps(YVb, ZVb:FindFirstChild("upgrade") and tonumber(ZVb.upgrade.Value) or 0)
    return (ZVb.damage.Value / _Vb * Units.aoe(aWb, ZVb.range.Value) * (1 + bWb * 0.5) + jWb) * Units.elem(YVb, Match.mod) * Units.nudge(YVb) * iWb
end
Match.upFail, Match.upFailAt = setmetatable({
}, {
    __mode = "k"
