Match.TRIAL_DEAR, Match.TRIAL_KEEP_ALIVE = 30000, 20000

function Match.trialSaving()
    local kWb = Core.Units [Match.trialId]
    if (tonumber(kWb and kWb.cost) or 0) < Match.TRIAL_DEAR or (Match.spent or 0) < Match.TRIAL_KEEP_ALIVE then
        return false
    end
    for lWb, mWb in ipairs(Match.mine or {
    }) do
        if mWb._stats.id.Value == Match.trialId then
            return false
        end
    end
    return true
end

function Match.econ()
    if Match.noBuy then
        return App.status("Economy", "keeping the last life: back to the lobby")
    end
    if Match.laneWant and not Match.laneCut then
        local nWb, oWb = pcall(Match.portalLanes)
        if nWb and not oWb then
            return App.status("Economy", string.format("this portal opens %d of the map's lanes and the game picks which: waiting for the first enemies", Match.laneWant))
        end
        if not nWb then
            Match.laneWant = nil
            App.log(1, "ERROR", "portal lanes: " .. tostring(oWb))
        end
    end
    if Match.planning and Utils.now() - Match.planning < 20 then
        return App.status("Economy", "the simulator is choosing spots on this map…")
    end
    local pWb = Match.money()
    local qWb = Match.wave()
    local rWb = math.max(0, Match.total - qWb)
    local sWb = Match.team
    local tWb = 1
    local uWb = 1
    pcall(function()
        uWb = Core.USC.calculate_spawn_cost_multiplier(Core.session())
    end)
    local vWb = {
    }
    local wWb, xWb, yWb = 0, 0, 0
    local zWb = 0
    for AWb, BWb in ipairs(Match.mine) do
        if not Units.isFarm(BWb._stats.id.Value) then
            zWb = zWb + 1
        end
    end
    local CWb = {
    }
    for DWb, EWb in ipairs(Match.mine) do
        local FWb = EWb._stats
        local GWb = FWb:FindFirstChild("uuid") and FWb.uuid.Value
        if GWb then
            CWb [GWb] = CWb [GWb] or {
            }
            table.insert(CWb [GWb], EWb)
        end
    end
    for HWb, IWb in ipairs(sWb) do
        local JWb = Match.trialId and Brain.trial and Brain.trial.study and qWb >= (tonumber(Match.total) or math.huge)
        if Match.trialId and not Match.studyTeam and not JWb and IWb.id ~= Match.trialId and not Units.isFarm(IWb.id) and (Match.trialSaving() or (not Units.allyBuff(IWb.id) and (Match.pressure or 0) < 0.6)) then
            continue
        end
        if Match.trialId == IWb.id and (tonumber(IWb.data.cost) or 0) >= Match.TRIAL_DEAR and # (CWb [IWb.uuid] or {
        }) == 0 and pWb >= (tonumber(IWb.data.cost) or 0) * uWb then
            Match.place(IWb, "on trial")
            return
        end
        if Match.studyTeam and Match.trialId == IWb.id and (Match.pressure or 0) < 0.6 then
            local KWb = tonumber(Units.field(IWb.id, "spawn_cap")) or tonumber(IWb.data.spawn_cap) or 1
            if # (CWb [IWb.uuid] or {
            }) < KWb and pWb >= (tonumber(IWb.data.cost) or 0) * uWb then
                Match.place(IWb, "on study: down first")
                return
            end
        end
        local LWb = Units.rows(IWb.id)
        local MWb = Units.isFarm(IWb.id)
        local NWb = CWb [IWb.uuid] or {
        }
        local OWb = Match.trainee == IWb.uuid and Training.BONUS or 1
        if not MWb and # NWb > 0 then
            wWb = wWb + 1
        end
        for PWb, QWb in ipairs(NWb) do
            if QWb._stats.id.Value == IWb.id and not ((Match.upFail [QWb] or 0) >= 3 and Utils.now() - (Match.upFailAt [QWb] or 0) < 60) then
                local RWb = QWb._stats.upgrade.Value
                if MWb then
                    xWb = xWb + (tonumber(QWb._stats.farm_amount and QWb._stats.farm_amount.Value) or Units.farm(IWb.u, RWb))
                end
                local SWb = LWb [RWb + 1]
                if SWb and RWb < LWb.max then
                    pcall(function()
                        tWb = Core.USC.calculate_upgrade_cost_multiplier(QWb, Core.session())
                    end)
                    local TWb = SWb.cost * tWb
                    if MWb then
                        local UWb = Units.farm(IWb.u, RWb + 1) - Units.farm(IWb.u, RWb)
                        table.insert(vWb, {
                            farm = true,
                            cost = TWb,
                            gain = UWb,
                            m = QWb,
                            e = IWb,
                            what = string.format("upgrade %s to level %d",
                            Units.name(IWb.id),
                            RWb + 1)
                        })
                    elseif Match.random and Units.idol(IWb.id) then
                        table.insert(vWb, {
                            cost = TWb,
                            gain = (Match.teamDps or 0) * Match.idolStep(),
                            m = QWb,
                            e = IWb,
                            idol = true,
                            what = string.format("upgrade %s to level %d",
                            Units.name(IWb.id),
                            RWb + 1)
                        })
                    elseif Match.mergeHold(QWb) then
                    else
                        local VWb, WWb = Match.shieldNow()
                        local XWb = (VWb > 0 and Economy.shieldGain(Match.liveDps(QWb, IWb.id), LWb [RWb], Units.dps(IWb.u, RWb + 1, Match.mod), SWb, VWb, WWb, 1, Match.info and Match.info.eff) or Economy.upgradeGain(Match.liveDps(QWb, IWb.id), LWb, RWb, TWb, tWb, Units.dps(IWb.u, RWb + 1, Match.mod))) * OWb * Match.mergeBoost(QWb) * Match.airBoost(QWb) * Match.reach(QWb) * Match.focusGain(QWb)
                        local YWb = Match.bleedGain(IWb.id, RWb, false)
                        XWb = XWb + YWb
                        table.insert(vWb, {
                            cost = TWb,
                            gain = XWb,
                            m = QWb,
                            e = IWb,
                            what = string.format("upgrade %s to level %d%s",
                            Units.name(IWb.id),
                            RWb + 1,
                            YWb > 0 and " (towards its bleed, which stops regen)" or "")
                        })
                        Match.upRate [QWb] = XWb / math.max(1, TWb)
                        for ZWb = RWb + 1, LWb.max do
                            yWb = yWb + LWb [ZWb].cost * tWb
                        end
                    end
                end
            end
        end
        local _Wb = Units.cap(IWb.u)
        if Match.random then
            _Wb = IWb.hand and 1 or 0
        elseif Units.allyBuff(IWb.id) and OWb == 1 and not Match.buffWanted(IWb) then
            _Wb = 0
        end
        if # NWb < _Wb and (Match.noSpot [IWb.uuid] or 0) < 3 then
            local aXb = (IWb.data.cost or 0) * uWb
            if MWb then
                table.insert(vWb, {
                    farm = true,
                    place = true,
                    cost = aXb,
                    gain = Units.farm(IWb.u,
                    0),
                    e = IWb,
                    what = "place " .. Units.name(IWb.id)
                })
            else
                local bXb = (# NWb == 0 and 2.5 or 1) * OWb
                if wWb < 3 then
                    bXb = bXb * 1.3
                end
                if Match.random then
                    bXb = bXb * (1 + 2 * Match.carry(IWb.id)) * (1 - Match.resistOf(IWb.id)) * Match.airNeed(IWb.id) * (Match.mergeIds [IWb.id] and 2 or 1)
                elseif Match.flyMode() then
                    bXb = bXb * Match.airNeed(IWb.id)
                end
                if Match.random and zWb < 8 then
                    bXb = bXb * (1 + (8 - zWb) * 0.25)
                end
                local cXb = Match.random and Units.idol(IWb.id) and (Match.teamDps or 0) * Match.idolStep() * 2 or 0
                local dXb = Match.shieldOf(Match.random and Match.cardDps(IWb) or Units.dps(IWb.u, 0, Match.mod), LWb [0]) + Match.shieldWork(IWb.id, LWb [0])
                local eXb = Match.blessGain(IWb)
                table.insert(vWb, {
                    place = true,
                    cost = aXb,
                    gain = dXb * bXb + Match.buffGain(IWb) + eXb + cXb + Match.holdGain(IWb,
                    LWb [0]) + Match.bleedGain(IWb.id,
                    0,
                    true),
                    e = IWb,
                    what = "place " .. Units.name(IWb.id) .. (eXb > 0 and string.format(" (its blessing: +%s summon damage a second)",
                    Utils.fmt(eXb)) or ""),
                    train = OWb ~= 1 and (# NWb == 0 and "first" or "more") or nil
                })
                for fXb = 0, LWb.max do
                    yWb = yWb + LWb [fXb].cost * (fXb == 0 and uWb or tWb)
                end
            end
        end
    end
    if Match.random and FarmHub.every("summonCheck", 1) then
        Match.summonWait = false
        for gXb, hXb in pairs(Core.session().ingame_spells or {
        }) do
            if hXb == "summon" and Match.summonWorth() then
                Match.summonWait = true
            end
        end
    end
    do
        local iXb = Match.depth and Match.depth.units > 0 and Match.depth.covEnd or 1
        if Match.summonWait and pWb < 10000 and (Match.pressure or 0) < math.min(Config.dangerReach, iXb * 0.9) then
            return App.status("Economy", string.format("saving ¥10k for Astral Summon (a unit from your own team): ¥%s", Utils.fmt(pWb)))
        end
        local jXb = Match.random and Match.spellWant
        if jXb and pWb < jXb.cost and ((Match.pressure or 0) < math.min(Config.dangerReach, iXb * 0.9) or (jXb.rate or 0) > (Match.bestRate or 0)) then
            return App.status("Economy", string.format("saving ¥%s for %s: ¥%s", Utils.fmt(jXb.cost), jXb.why, Utils.fmt(pWb)))
        end
    end
    if Match.fieldCount() >= Match.FIELD_MAX then
        local kXb = {
        }
        for lXb, mXb in ipairs(vWb) do
            if not mXb.place then
                table.insert(kXb, mXb)
            end
        end
        vWb = kXb
        local nXb = Match.depth and Match.depth.units > 0 and Match.depth.covEnd or 1
        if Match.roomPlan and pWb < Match.roomPlan.need and (Match.pressure or 0) < math.min(Config.dangerReach, nXb * 0.9) then
            return App.status("Economy", string.format("saving ¥%s to swap %s for %s (the field is full)", Utils.fmt(Match.roomPlan.need), Match.roomPlan.out, Match.roomPlan.name))
        end
    end
    if Match.infinite and Match.trainee then
        local oXb, pXb = Training.hold(Match.pressure or 0, wWb, Match.holding)
        if oXb then
            local qXb = {
            }
            for rXb, sXb in ipairs(vWb) do
                if sXb.farm or (sXb.e and sXb.e.uuid == Match.trainee) then
                    table.insert(qXb, sXb)
                end
            end
            vWb = qXb
            if # vWb == 0 then
                return App.status("Economy", pXb .. " · everything for the trainee is bought: saving ¥" .. Utils.fmt(pWb))
            end
        end
        if oXb ~= (Match.holding or false) then
            Match.holding = oXb
            if FarmHub.every("holdLog", 60) then
                App.log(1, "TRAIN", oXb and pXb or "enemies get further now: your other units are bought for again")
            end
        end
    end
    Match.bestRate = 0
    for tXb, uXb in ipairs(vWb) do
        if not uXb.farm and not uXb.place and uXb.cost > 0 then
            Match.bestRate = math.max(Match.bestRate, uXb.gain / uXb.cost)
        end
    end
    if # vWb == 0 then
        return App.status("Economy", "everything is placed and fully upgraded ✓")
    end
    if Match.trainee then
        Training.boost(vWb, wWb, Match.pressure or 0, Match.depth and Match.depth.units > 0 and Match.depth.covEnd or nil)
    end
    local vXb = pWb + xWb * rWb
    for wXb = qWb + 1, Match.total do
        vXb = vXb + Match.waveReward(wXb)
    end
    Match.farmNow, Match.future, Match.wantLeft = xWb, vXb, yWb
    if Match.info and Match.comingW ~= qWb then
        local xXb = {
        }
        local yXb = math.min(0.9, Match.info.red or 0)
        for zXb = 1, 5 do
            local AXb = qWb + zXb
            if AXb > Match.total then
                break
            end
            local BXb, CXb, DXb = pcall(Simulator.wave, Match.info, AXb)
            local EXb = 0
            for FXb, GXb in ipairs(BXb and CXb or {
            }) do
                EXb = EXb + GXb.hp + (GXb.bar or 0)
            end
            table.insert(xXb, {
                hp = EXb / (1 - yXb),
                reward = (BXb and tonumber(DXb)) or Match.waveReward(AXb)
            })
        end
        Match.comingW, Match.coming = qWb, xXb
    end
    local HXb = Match.info and Match.info.eff or Simulator.PRIOR.eff
    local IXb = Match.teamShield()
    if Match.focus and (Match.focusInRange or 0) > 0 then
        local JXb = {
        }
        for KXb, LXb in ipairs(vWb) do
            if not LXb.place then
                table.insert(JXb, LXb)
            end
        end
        if # JXb > 0 then
            vWb = JXb
        end
    end
    local MXb, NXb, OXb = Economy.decide(vWb, {
        money = pWb,
        left = rWb,
        attackers = wWb,
        pressure = Match.pressure or 0,
        piling = Match.piling,
        clearSec = (Match.clearSec or 0) / IXb,
        enemies = # Match.enemies,
        future = vXb,
        wantLeft = yWb,
        coming = Match.coming,
        waveSec = Match.info and Match.info.waveSec,
        eff = HXb,
        teamDps = (Match.teamDps or 0) * HXb,
        shieldK = IXb,
        farmNow = xWb,
        hpAlive = Match.hpAlive or 0,
        roadSec = 1 / math.max(0.001,
        ((Match.info and Match.info.walk) or Simulator.PRIOR.walk) * ((Match.info and Match.info.speedScale) or 1)),
        leak = Match.depth and Match.depth.leak,
        airLeak = Match.depth and Match.depth.airLeak,
        cover = Match.depth and Match.depth.units > 0 and Match.depth.covEnd or nil,
        incomeRate = Match.incomeRate or (((Match.coming and Match.coming [1] and Match.coming [1].reward) or 500) + xWb) / ((Match.info and Match.info.waveSec) or 20)
    })
    if OXb then
        return App.status("Economy", OXb)
    end
    if not MXb then
        return
    end
    if not Config.upgrade and not MXb.place then
        return
    end
    if not Config.place and MXb.place then
        return
    end
    App.status("Economy", string.format("%s — %s", MXb.what, NXb))
    if MXb.place then
        Match.place(MXb.e, NXb)
    else
        local PXb = pWb
        local QXb, RXb = App.request("upg", "upgrade_unit_ingame", MXb.m)
        if QXb and RXb then
            Match.spent = Match.spent + MXb.cost
            table.insert(Match.actions, MXb.what)
            if MXb.idol then
                pcall(Match.idolMeasure)
            end
            App.log(2, "UPGRADE", MXb.what .. " for ¥" .. Utils.fmt(MXb.cost) .. " — " .. NXb)
            App.status("Upgrade", MXb.what)
        elseif QXb then
            App.backoff("upg", 1.5)
            if PXb >= MXb.cost then
                App.log(2, "UPGRADE", "refused: " .. MXb.what)
                Match.upFail [MXb.m] = (Match.upFail [MXb.m] or 0) + 1
                Match.upFailAt [MXb.m] = Utils.now()
                if Match.upFail [MXb.m] == 3 then
                    App.log(1, "UPGRADE", "the game refused " .. MXb.what .. " 3 times — buying something else for a minute")
                end
            end
        end
    end
end
Match.readySince, Match.buffedTill = setmetatable({
}, {
    __mode = "k"
}), {
