Match.buffSeen = {
}

function Match.buffOn(SXb, TXb)
    if (tonumber(SXb:GetAttribute("_dmg_buff_" .. tostring(TXb))) or 0) > 0 then
        return true
    end
    local UXb = SXb:FindFirstChild("buff_damage_multiplier")
    return UXb ~= nil and (tonumber(UXb.Value) or 0) > 0
end

function Match.buffRotation(VXb, WXb, XXb, YXb, ZXb, _Xb)
    if # Match.enemies == 0 then
        return false
    end
    local aYb = 0
    for bYb, cYb in pairs(YXb.ally.types or {
    }) do
        aYb = math.max(aYb, tonumber(cYb) or 0)
    end
    if aYb <= 0 then
        return false
    end
    local dYb = tonumber(Brain.stack [XXb].cap) or ((1 + aYb) ^ 2 - 1)
    local eYb = 1
    while eYb < 6 and (1 + aYb) ^ eYb - 1 < dYb - 0.02 do
        eYb = eYb + 1
    end
    local fYb = 0
    for gYb, hYb in ipairs(Match.mine) do
        local iYb = hYb._stats:FindFirstChild("active_attack")
        if iYb and tostring(iYb.Value) == XXb then
            fYb = fYb + 1
        end
    end
    local jYb = Units.allyBuff(WXb.id.Value)
    local kYb = (jYb and tonumber(jYb.cd)) or 60
    local lYb = math.max(1, math.min(eYb, math.floor(fYb * ZXb / math.max(1, kYb) + 0.001)))
    local mYb = math.min(dYb, (1 + aYb) ^ lYb - 1)
    local nYb = ZXb / lYb
    local oYb = VXb:GetPivot().Position
    local pYb, qYb = 0, 0
    for rYb, sYb in ipairs(Match.mine) do
        local tYb = sYb._stats
        local uYb = tYb.id.Value
        if sYb ~= VXb and not Units.isFarm(uYb) and not Units.allyBuff(uYb) and (Utils.flat(sYb:GetPivot().Position) - Utils.flat(oYb)).Magnitude <= WXb.range.Value then
            local vYb, wYb = Units.types(uYb)
            if YXb.ally.types [wYb] then
                pYb = pYb + 1
                if (tonumber(tYb:GetAttribute("_dmg_buff_" .. tostring(wYb))) or 0) < mYb - 0.02 then
                    qYb = qYb + 1
                end
            end
        end
    end
    if pYb == 0 or qYb == 0 then
        return false
    end
    Match.buffNext = Match.buffNext or {
    }
    if _Xb < (Match.buffNext [XXb] or 0) then
        return false
    end
    Match.buffNext [XXb] = _Xb + nYb
    return true, string.format("rotation: %d of the %d units it reaches are under +%d%% (%d buffs at once from %d copies, one every %.0f s)", qYb, pYb, math.floor(mYb * 100 + 0.5), lYb, fYb, nYb)
end

function Match.buffLevel(xYb)
    local yYb = 0
    for zYb, AYb in ipairs(Match.mine) do
        local BYb = AYb._stats
        local CYb = BYb.id.Value
        if not Units.isFarm(CYb) and not Units.allyBuff(CYb) then
            local DYb, EYb = Units.types(CYb)
            local FYb = BYb:FindFirstChild("buff_damage_multiplier")
            if FYb and not xYb then
                yYb = math.max(yYb, tonumber(FYb.Value) or 0)
            end
            if not xYb or xYb [EYb] then
                yYb = math.max(yYb, tonumber(BYb:GetAttribute("_dmg_buff_" .. tostring(EYb))) or 0)
            end
        end
    end
    return yYb
end
Match.galeIdle = setmetatable({
}, {
    __mode = "k"
})

function Match.isGale(GYb, HYb)
    return GYb:FindFirstChild("unit_bar") ~= nil and (HYb:match(":active$") or HYb:match(":off$")) ~= nil
end
Match.barSeen = setmetatable({
}, {
    __mode = "k"
})

function Match.learnToggle(IYb, JYb, KYb, LYb)
    local MYb = JYb.id.Value
    local NYb = Brain.toggles [MYb]
    local OYb = tonumber(JYb:FindFirstChild("upgrade") and JYb.upgrade.Value) or 0
    local PYb = NYb == nil
    if not NYb then
        NYb = {
            from = OYb,
            fill = 0,
            drain = 0,
            nf = 0,
            nd = 0,
            at = os.time()
        }
        Brain.toggles [MYb] = NYb
        Simulator._holds [MYb] = nil
    end
    if OYb < (tonumber(NYb.from) or OYb) then
        NYb.from = OYb
    end
    Match.togglesSeen = Match.togglesSeen or {
    }
    Match.togglesSeen [MYb] = true
    local QYb, RYb = tonumber(JYb.unit_bar.Value) or 0, KYb:match(":off$") ~= nil
    local SYb = Match.barSeen [IYb]
    if SYb and SYb.on == RYb and LYb - SYb.t >= 1.5 then
        if QYb > 0.5 and QYb < 99.5 and SYb.bar > 0.5 and SYb.bar < 99.5 then
            local TYb = (QYb - SYb.bar) / (LYb - SYb.t)
            if RYb and TYb < 0 then
                NYb.drain = (NYb.drain * NYb.nd - TYb) / (NYb.nd + 1)
                NYb.nd = math.min(NYb.nd + 1, 50)
            elseif not RYb and TYb > 0 then
                NYb.fill = (NYb.fill * NYb.nf + TYb) / (NYb.nf + 1)
                NYb.nf = math.min(NYb.nf + 1, 50)
            end
        end
        Match.barSeen [IYb] = {
            bar = QYb,
            t = LYb,
            on = RYb
        }
    elseif not SYb or SYb.on ~= RYb then
        Match.barSeen [IYb] = {
            bar = QYb,
            t = LYb,
            on = RYb
        }
    end
    if PYb then
        App.log(1, "UNITS", string.format("%s has a switch ability with a bar (from upgrade %d): learned, so its copies take turns and it stands where your damage is", Units.name(MYb), OYb))
        App.saveSoon()
    end
end

function Match.gale(UYb, VYb, WYb, XYb)
    local YYb = WYb:match("^(.+):")
    local function ZYb(_Yb)
        local aZb, bZb = Utils.flat(_Yb:GetPivot().Position), _Yb._stats.range.Value
        local cZb, dZb = 0, {
        }
        for eZb, fZb in ipairs(Match.enemies) do
            if (Utils.flat(fZb.pos) - aZb).Magnitude <= bZb then
                cZb = cZb + 1
                if fZb.boss then
                    table.insert(dZb, fZb)
                end
            end
        end
        return cZb, dZb
    end
    local gZb = tonumber(VYb.unit_bar.Value) or 0
    local hZb, iZb = ZYb(UYb)
    local jZb = # iZb > 0
    if WYb:match(":off$") then
        if hZb > 0 then
            Match.galeIdle [UYb] = nil
            return nil
        end
        Match.galeIdle [UYb] = Match.galeIdle [UYb] or XYb
        if XYb - Match.galeIdle [UYb] >= 3 and gZb >= 15 then
            return true, string.format("Gale off: nothing in range, keeping its bar (%d)", math.floor(gZb))
        end
        return nil
    end
    Match.galeIdle [UYb] = nil
    if hZb == 0 or gZb < 20 then
        return nil
    end
    local kZb = Utils.flat(UYb:GetPivot().Position)
    for lZb, mZb in ipairs(Match.mine) do
        local nZb = mZb._stats
        local oZb = nZb:FindFirstChild("active_attack")
        local pZb = oZb and tostring(oZb.Value) or ""
        if mZb ~= UYb and nZb:FindFirstChild("unit_bar") and pZb:match("^(.+):") == YYb then
            local qZb, rZb = Utils.flat(mZb:GetPivot().Position), tonumber(nZb.unit_bar.Value) or 0
            local sZb = (qZb - kZb).Magnitude <= math.max(VYb.range.Value, nZb.range.Value)
            local tZb = false
            for uZb, vZb in ipairs(iZb) do
                if (Utils.flat(vZb.pos) - qZb).Magnitude <= nZb.range.Value then
                    tZb = true
                end
            end
            if pZb:match(":off$") then
                if rZb > 5 and (tZb or (sZb and not jZb)) then
                    return nil
                end
            elseif sZb and rZb > gZb + 10 and rZb >= 20 and ZYb(mZb) > 0 then
                return nil
            end
        end
    end
    if not Match.galeSaid then
        Match.galeSaid = true
        App.log(1, "ABILITY", string.format("%s: %s in use, copies take turns so enemies stay slowed and freezing", Units.name(VYb.id.Value), YYb == "rukia_bankai" and "Gale of the Moon" or YYb))
    end
    return true, string.format("Gale on: %d enemies in range%s, bar %d (copies take turns)", hZb, jZb and ", a boss" or "", math.floor(gZb))
end

function Match.actives()
    if not Config.actives or Match.activeBusy then
        return
    end
    local wZb = tick()
    local xZb = Utils.now()
    for yZb, zZb in ipairs(Match.mine) do
        local AZb = zZb._stats
        local BZb, CZb, DZb = AZb:FindFirstChild("active_attack"), AZb:FindFirstChild("active_attack_cooldown"), AZb:FindFirstChild("last_active_cast")
        if BZb and CZb and DZb and BZb.Value ~= "nil" and BZb.Value ~= "" then
            if Match.isGale(AZb, tostring(BZb.Value)) then
                pcall(Match.learnToggle, zZb, AZb, tostring(BZb.Value), xZb)
            end
            if CZb.Value - (wZb - DZb.Value) > 0 then
                Match.readySince [zZb] = nil
            else
                Match.readySince [zZb] = Match.readySince [zZb] or xZb
                local EZb = Units.attackInfo(BZb.Value)
                local FZb = zZb:GetPivot().Position
                local GZb = AZb.range.Value
                local HZb, IZb, JZb
                local KZb = Match.trialId == AZb.id.Value and Brain.trial and Brain.trial.study and # Match.enemies > 0 and not Match.isGale(AZb, tostring(BZb.Value))
                if KZb then
                    HZb, IZb = true, "on study: what it does"
                elseif Match.isGale(AZb, tostring(BZb.Value)) then
                    HZb, IZb = Match.gale(zZb, AZb, tostring(BZb.Value), xZb)
                elseif EZb.ally and Brain.stack [BZb.Value] and Brain.stack [BZb.Value].stacks and Config.community then
                    HZb, IZb = Match.buffRotation(zZb, AZb, tostring(BZb.Value), EZb, tonumber(EZb.ally.time) or 30, xZb)
                elseif EZb.ally or EZb.allyCd or EZb.allyRange then
                    local LZb = (EZb.ally and EZb.ally.time) or (EZb.allyCd and EZb.allyCd.time) or (EZb.allyRange and EZb.allyRange.time) or 30
                    local MZb = Match.buffedTill [BZb.Value]
                    if not MZb then
                        MZb = setmetatable({
                        }, {
                            __mode = "k"
                        })
                        Match.buffedTill [BZb.Value] = MZb
                    end
                    local NZb, OZb, PZb, QZb = {
                    }, 0, 0, 0
                    for RZb, SZb in ipairs(Match.mine) do
                        local TZb = SZb._stats
                        local UZb = TZb.id.Value
                        if SZb ~= zZb and not Units.isFarm(UZb) and not Units.allyBuff(UZb) and (Utils.flat(SZb:GetPivot().Position) - Utils.flat(FZb)).Magnitude <= GZb then
                            local VZb, WZb = Units.types(UZb)
                            if not EZb.ally or EZb.ally.types [WZb] then
                                table.insert(NZb, SZb)
                                if TZb:FindFirstChild("target") and TZb.target.Value ~= nil then
                                    local XZb = (MZb [SZb] or 0) >= xZb
                                    if EZb.ally then
                                        XZb = Match.buffOn(TZb, WZb) or (MZb [SZb] or 0) - LZb + 2 >= xZb
                                    end
                                    if XZb then
                                        PZb = PZb + 1
                                        QZb = math.max(QZb, MZb [SZb] or 0)
                                    else
                                        OZb = OZb + 1
                                    end
                                end
                            end
                        end
                    end
                    local YZb = Brain.stack [BZb.Value]
                    if YZb and not YZb.stacks and os.time() - (YZb.at or 0) > 3 * 86400 then
                        YZb = nil
                    end
                    local ZZb = EZb.ally and PZb > 0 and Match.buffLevel(EZb.ally.types) or 0
                    local _Zb = PZb > 0 and EZb.ally and Config.community and ZZb > 0 and ((YZb == nil and QZb - xZb > 5) or (YZb and YZb.stacks and ZZb < (YZb.cap or 1) - 0.02))
                    if OZb > PZb or _Zb then
                        HZb, IZb = true, string.format("buffs %d of your units that are fighting", OZb + PZb)
                        if _Zb and YZb == nil then
                            JZb = {
                                key = BZb.Value,
                                types = EZb.ally.types,
                                before = ZZb
                            }
                            IZb = IZb .. string.format(" (testing whether a 2nd buff adds up: now +%d%%)", math.floor(ZZb * 100 + 0.5))
                        elseif _Zb then
                            IZb = IZb .. string.format(" (chaining: now +%d%%)", math.floor(ZZb * 100 + 0.5))
                        end
                        for a_b, b_b in ipairs(NZb) do
                            MZb [b_b] = xZb + LZb
                        end
                    end
                elseif EZb.baseSafe then
                    for c_b, d_b in ipairs(Match.enemies) do
                        if d_b.prog >= 0.98 then
                            HZb, IZb = true, "an enemy is at the base"
                            break
                        end
                    end
                else
                    local e_b, f_b = 0, false
                    for g_b, h_b in ipairs(Match.enemies) do
                        if (Utils.flat(h_b.pos) - Utils.flat(FZb)).Magnitude <= GZb then
                            e_b = e_b + 1
                            if h_b.boss then
                                f_b = true
                            end
                        end
                    end
                    local i_b = xZb - Match.readySince [zZb]
                    local j_b = math.min(Config.abilityHold * math.max(1, CZb.Value / 60), CZb.Value * 0.3)
                    local k_b = math.max(3, math.floor(# Match.enemies * 0.3))
                    if Match.trialId == AZb.id.Value and (tonumber((Core.Units [Match.trialId] or {
                    }).damage) or 0) <= 0 and # Match.enemies > 0 then
                        HZb, IZb = true, "on trial"
                    elseif e_b > 0 and f_b then
                        HZb, IZb = true, "a boss is in range"
                    elseif e_b >= k_b then
                        HZb, IZb = true, e_b .. " enemies in range"
                    elseif e_b >= 3 and i_b >= j_b * 0.5 then
                        HZb, IZb = true, string.format("%d enemies in range after %ds", e_b, math.floor(i_b))
                    elseif e_b >= 1 and i_b >= j_b then
                        HZb, IZb = true, string.format("held %ds for a crowd, firing on %d", math.floor(i_b), e_b)
                    end
                end
                if HZb then
                    Match.activeBusy = true
                    Match.readySince [zZb] = nil
                    task.spawn(function()
                        local l_b = App.request("active", "use_active_attack", zZb)
                        if l_b then
                            Match.casts = Match.casts or {
                            }
                            Match.casts [AZb.id.Value] = (Match.casts [AZb.id.Value] or 0) + 1
                            App.status("Abilities", string.format("%s used its ability — %s", Units.name(AZb.id.Value), IZb))
                            App.log(2, "ABILITY", Units.name(AZb.id.Value) .. ": " .. IZb)
                            if EZb.ally then
                                task.delay(2, function()
                                    if not App.alive then
                                        return
                                    end
                                    local m_b = Match.buffSeen [AZb.id.Value] or {
                                        casts = 0,
                                        levels = {
                                        }
                                    }
                                    Match.buffSeen [AZb.id.Value] = m_b
                                    m_b.casts = m_b.casts + 1
                                    if # m_b.levels < 12 then
                                        table.insert(m_b.levels, math.floor(Match.buffLevel(EZb.ally.types) * 100 + 0.5))
                                    end
                                end)
                            end
                            if JZb then
                                task.wait(2)
                                local n_b = Match.buffLevel(JZb.types)
                                local o_b = n_b > JZb.before + 0.05
                                Brain.stack [JZb.key] = {
                                    stacks = o_b,
                                    cap = o_b and 1 or nil,
                                    before = JZb.before,
                                    after = n_b,
                                    at = os.time()
                                }
                                App.log(1, "ABILITY", string.format("%s's buff %s: +%d%% → +%d%% with a second copy", Units.name(AZb.id.Value), o_b and "adds up (chaining it from now on)" or "doesn't add up (copies take turns)", math.floor(JZb.before * 100 + 0.5), math.floor(n_b * 100 + 0.5)))
                                App.saveSoon()
                            end
                        end
                        Match.activeBusy = false
                    end)
                    return
                end
            end
        end
    end
end
Match.prioAt = setmetatable({
}, {
    __mode = "k"
})

function Match.targeting()
    for p_b, q_b in ipairs(Match.trainee and Match.mine or {
    }) do
        local r_b = q_b._stats
        local s_b = r_b:FindFirstChild("priority")
        if s_b and r_b:FindFirstChild("uuid") and r_b.uuid.Value == Match.trainee and s_b.Value ~= "last" and Utils.now() - (Match.prioAt [q_b] or 0) > 8 then
            Match.prioAt [q_b] = Utils.now()
            if App.request("prio", "change_priority", q_b, "last") then
                App.log(2, "TARGET", Units.name(r_b.id.Value) .. " → last (takedown training)")
            end
            return
        end
    end
    for t_b, u_b in ipairs(Config.community and Match.mine or {
    }) do
        local v_b = u_b._stats
        local w_b = Core.TIPS [v_b.id.Value]
        local x_b = v_b:FindFirstChild("priority")
        if w_b and w_b.target and x_b and x_b.Value ~= w_b.target and Utils.now() - (Match.prioAt [u_b] or 0) > 8 then
            Match.prioAt [u_b] = Utils.now()
            if App.request("prio", "change_priority", u_b, w_b.target) then
                App.log(2, "TARGET", Units.name(v_b.id.Value) .. " → " .. w_b.target .. " (" .. w_b.why .. ")")
            end
            return
        end
    end
    local y_b = false
    for z_b, A_b in ipairs(Match.enemies or {
    }) do
        if A_b.fly then
            y_b = true
            break
        end
    end
    for B_b, C_b in ipairs(y_b and Match.mine or {
    }) do
        local D_b = C_b._stats
        local E_b = D_b:FindFirstChild("priority")
        local F_b = Config.community and Core.TIPS [D_b.id.Value] and Core.TIPS [D_b.id.Value].target
        if E_b and E_b.Value ~= "flying" and not F_b and Match.canAir(C_b) and not Units.isFarm(D_b.id.Value) and not Units.allyBuff(D_b.id.Value) and Utils.now() - (Match.prioAt [C_b] or 0) > 8 then
            local G_b, H_b = pcall(Core.USC.get_valid_priorities, C_b)
            if G_b and type(H_b) == "table" and H_b.flying then
                Match.prioAt [C_b] = Utils.now()
                if App.request("prio", "change_priority", C_b, "flying") then
                    App.log(2, "TARGET", Units.name(D_b.id.Value) .. " → flying (a flyer is on the road)")
                end
                return
            end
        end
    end
    if not Config.smartTarget then
        return
    end
    local I_b = false
    for J_b, K_b in ipairs(Match.enemies) do
        if K_b.boss then
            I_b = true
            break
        end
    end
    for L_b, M_b in ipairs(Match.mine) do
        local N_b = M_b._stats
        local O_b = N_b.id.Value
        local P_b = N_b:FindFirstChild("priority")
        local Q_b = Match.trainee and N_b:FindFirstChild("uuid") and N_b.uuid.Value == Match.trainee
        local R_b = Config.community and Core.TIPS [O_b] and Core.TIPS [O_b].target
        local S_b = y_b and Match.canAir(M_b)
        if P_b and not Q_b and not R_b and not S_b and not Units.isFarm(O_b) and not Units.allyBuff(O_b) then
            local T_b = N_b:FindFirstChild("primary_attack") and N_b.primary_attack.Value or nil
            local U_b = Units.attackInfo(T_b, N_b.range.Value)
            local V_b = U_b.n <= 1.4 and U_b.slow == 0 and U_b.stun == 0
            local W_b = (V_b and I_b) and "strongest" or "first"
            if P_b.Value ~= W_b and Utils.now() - (Match.prioAt [M_b] or 0) > 8 then
                local X_b, Y_b = pcall(Core.USC.get_valid_priorities, M_b)
                if X_b and type(Y_b) == "table" and Y_b [W_b] then
                    Match.prioAt [M_b] = Utils.now()
                    local Z_b = App.request("prio", "change_priority", M_b, W_b)
                    if Z_b then
                        App.status("Targeting", string.format("%s → %s (%s)", Units.name(O_b), W_b, W_b == "strongest" and "boss on the road" or (V_b and "no boss now" or "holds the front")))
                        App.log(2, "TARGET", Units.name(O_b) .. " → " .. W_b)
                    end
                    return
                end
            end
        end
    end
end
Hunt.CARD_PICKS = {
    "Secret Luck",
    "Gems",
    "Easiest Win",
    "Smart"
}

function Hunt.cardLuck(__b)
    local a0b = 0
    for b0b, c0b in pairs(type(__b) == "table" and type(__b.effects) == "table" and __b.effects or {
    }) do
        if type(c0b) == "table" and c0b.type == "secret_drop" then
            a0b = a0b + (tonumber(c0b.amount) or 0)
        end
    end
    return a0b
end

function Match.huntChoose(d0b, e0b)
    Match.fhP = Match.fhP or 1
    local f0b = Hunt.floor()
    local g0b = (Match.pressure or 0) >= Config.safeReach or (Match.depth and Match.depth.leak)
    local h0b = Hunt.weatherStrength(Hunt.weatherNow())
    local i0b = table.find(Hunt.CARD_PICKS, Config.huntCards) and Config.huntCards or "Smart"
    local j0b, k0b, l0b, m0b
    local n0b = {
    }
    for o0b, p0b in pairs(d0b) do
        local q0b, r0b = 1, {
        }
        for s0b, t0b in pairs(type(p0b) == "table" and p0b.effects or {
        }) do
            if type(t0b) == "table" then
                local u0b = Match.rogueEffect(t0b)
                q0b = q0b * u0b
                table.insert(r0b, Match.effectText(t0b))
            end
        end
        if type(p0b) == "table" and p0b.weather then
            q0b = q0b * Hunt.weatherStrength(p0b.weather) / math.max(0.05, h0b)
        end
        local v0b = type(p0b) == "table" and Hunt.cardGems(p0b, e0b) or 0
        local w0b = q0b >= 1 or (Match.fhP * q0b >= f0b and not g0b)
        local x0b = math.log(math.max(0.05, q0b))
        local y0b = x0b * Hunt.STRENGTH_GEMS + (w0b and v0b or - 1000)
        local z0b = Hunt.cardLuck(p0b)
        if i0b == "Secret Luck" and w0b and z0b > 0 then
            y0b = 2e6 + z0b * 1e4 + v0b
        elseif i0b == "Gems" and w0b then
            y0b = 1e6 + v0b + x0b
        elseif i0b == "Easiest Win" then
            y0b = x0b * 1e6 + v0b
        end
        if not k0b or y0b > k0b then
            j0b, k0b, l0b, m0b = o0b, y0b, q0b, v0b
        end
        table.insert(n0b, string.format("%s) %s%s [%s] ×%.2f, %d gems: %s", tostring(o0b), tostring(type(p0b) == "table" and p0b.title or "?"), (type(p0b) == "table" and p0b.weather) and (" (" .. tostring(p0b.weather) .. ")") or "", tostring(type(p0b) == "table" and p0b.option_type or "?"), q0b, math.floor(v0b + 0.5), table.concat(r0b, " + ")))
    end
    return j0b, l0b, m0b, n0b, f0b, g0b, i0b
end

function Match.huntPick(A0b)
    local B0b = Match.wave()
    local C0b, D0b, E0b, F0b, G0b, H0b, I0b = Match.huntChoose(A0b, B0b)
    Match.fhP = Match.fhP * (D0b or 1)
    Match.rogueOptions = nil
    local J0b, K0b = pcall(HttpService.JSONEncode, HttpService, Hunt.plain(A0b))
    if J0b then
        Hunt.write("hunt_cards.txt", string.format("%s wave %d map %s weather %s: %s", os.date("%m-%d %H:%M"), B0b, tostring(Match.ld.map), tostring(Hunt.weatherNow()), K0b))
    end
    local L0b = App.request("rogue", "select_roguelike_option", C0b)
    local M0b = C0b and Hunt.cardLuck(A0b [C0b]) or 0
    App.log(1, "ROGUE", string.format("wave %d · picked %s by %s (worth %d gems%s, strength now ×%.2f, floor ×%.2f%s) of: %s", B0b, tostring(C0b), tostring(I0b), math.floor((E0b or 0) + 0.5), M0b > 0 and string.format(", secret luck +%g", M0b) or "", Match.fhP, G0b, H0b and ", under pressure" or "", table.concat(F0b, " | ")))
    return L0b
end

function Match.huntRecord(N0b, O0b, P0b, Q0b)
    local R0b, S0b = pcall(Hunt.starfallRecord)
    Match.starSummary = R0b and S0b or nil
    local T0b = Hunt.floor()
    Brain.hunt.pmin = Utils.clamp(T0b + (P0b and - 0.1 or 0.1), 0.4, 2)
    Brain.hunt.runs = Brain.hunt.runs or {
    }
    table.insert(Brain.hunt.runs, 1, {
        at = os.time(),
        wave = Match.wave(),
        won = P0b or nil,
        pearls = O0b,
        mult = Match.fhMult or 1,
        strength = Match.fhP or 1,
        floor = T0b,
        map = Match.ld.map,
        weather = Hunt.weatherNow(),
        sec = Q0b,
        picks = Match.fhPicks
    })
    while # Brain.hunt.runs > 20 do
        table.remove(Brain.hunt.runs)
    end
    local U0b = Hunt.board()
    App.log(1, "HUNT", string.format("%s at wave %d in %.0f min: +%d Summer Pearls at ×%.2f · map %s, weather %s%s", P0b and "won" or "lost", Match.wave(), (tonumber(Q0b) or 0) / 60, O0b, Match.fhMult or 1, tostring(Match.ld.map), tostring(Hunt.weatherNow()), U0b and string.format(" · bingo %d of %d squares", U0b.squares, # U0b.board) or ""))
    local V0b = {
    }
    for W0b, X0b in ipairs({
        "victory",
        "resource_reward",
        "gem_reward",
        "new_items",
        "new_units",
        "waves_completed",
        "first_completion_gems",
        "party_bonus"
    }) do
        if type(N0b) == "table" then
            V0b [X0b] = N0b [X0b]
        end
    end
    local Y0b = {
    }
    for Z0b in pairs(type(N0b) == "table" and N0b or {
    }) do
        table.insert(Y0b, tostring(Z0b))
    end
    table.sort(Y0b)
    local _0b, a1b = pcall(HttpService.JSONEncode, HttpService, Hunt.plain(V0b))
    if _0b then
        Hunt.write("hunt_results.txt", os.date("%m-%d %H:%M ") .. a1b .. " · fields: " .. table.concat(Y0b, ", "))
    end
end

function Match.pickRogue()
    local b1b = Match.rogueOptions
    if b1b and Match.hunt then
        return Match.huntPick(b1b)
    end
    if not b1b then
        local c1b = App.request("rogue", "select_roguelike_option", 1)
        return c1b
    end
    Match.fhP = Match.fhP or 1
    local d1b = tonumber(Brain.fh.pmin) or 1
    local e1b = (Match.pressure or 0) >= Config.safeReach or (Match.depth and Match.depth.leak)
    local f1b, g1b, h1b
    for i1b, j1b in pairs(b1b) do
        local k1b, l1b = 1, 0
        for m1b, n1b in pairs(type(j1b) == "table" and j1b.effects or {
        }) do
            if type(n1b) == "table" then
                local o1b, p1b = Match.rogueEffect(n1b)
                k1b = k1b * o1b
                l1b = l1b + p1b
            end
        end
        local q1b = math.log(math.max(0.05, k1b)) * 10
        if l1b > 0 and Match.fhP * k1b >= d1b and not e1b then
            q1b = q1b + 100 * l1b
        elseif l1b > 0 then
            q1b = q1b - 50 + l1b
        end
        if not g1b or q1b > g1b then
            f1b, g1b, h1b = i1b, q1b, k1b
        end
    end
    Match.fhP = Match.fhP * (h1b or 1)
    local r1b = {
    }
    for s1b, t1b in pairs(b1b) do
        local u1b = {
        }
        for v1b, w1b in pairs(type(t1b) == "table" and t1b.effects or {
        }) do
            if type(w1b) == "table" then
                table.insert(u1b, Match.effectText(w1b))
            end
        end
        table.insert(r1b, tostring(s1b) .. ") " .. table.concat(u1b, " + "))
    end
    Match.rogueOptions = nil
    local x1b = App.request("rogue", "select_roguelike_option", f1b)
    App.log(1, "ROGUE", string.format("wave %d · picked %s (score %.1f, strength now ×%.2f, floor ×%.2f) of: %s", Match.wave(), tostring(f1b), g1b or 0, Match.fhP, d1b, table.concat(r1b, " | ")))
    return x1b
end

function Match.rogueShare(y1b)
    if not y1b then
        return 0.5
    end
    local z1b = tostring(y1b):gsub("_damage$", "")
    local A1b, B1b = 0, 0
    for C1b, D1b in ipairs(Match.mine or {
    }) do
        local E1b = D1b._stats.id.Value
        if not Units.isFarm(E1b) then
            local F1b, G1b = pcall(Match.liveDps, D1b, E1b)
            G1b = F1b and G1b or 0
            local H1b = Units.types(E1b)
            A1b = A1b + G1b
            if H1b [z1b] or H1b [z1b .. "_damage"] then
                B1b = B1b + G1b
            end
        end
    end
    local I1b = 0
    for J1b, K1b in ipairs(Match.mine or {
    }) do
        if not Units.isFarm(K1b._stats.id.Value) then
            I1b = I1b + 1
        end
    end
    local L1b = I1b / (I1b + 4)
    return L1b * (A1b > 0 and B1b / A1b or 0.5) + (1 - L1b) * 0.5
end

function Match.resistOf(M1b)
    local N1b = Units.types(M1b)
    local O1b = 0
    for P1b, Q1b in pairs(Match.fhResist or {
    }) do
        local R1b = tostring(P1b):gsub("_damage$", "")
        if N1b [R1b] or N1b [R1b .. "_damage"] then
            O1b = math.max(O1b, Q1b / 100)
        end
    end
    return math.min(0.95, O1b)
end

function Match.rogueEffect(S1b)
    local T1b, U1b, V1b = S1b.type, tonumber(S1b.amount) or 0, tostring(S1b.stat or "")
    if T1b == "candy_multiplier" then
        return 1, math.abs(U1b)
    end
    if T1b == "stat_mul" or T1b == "stat_add" or T1b == "stat_attr_add" then
        if V1b == "damage" then
            return math.max(0.3, 1 + U1b), 0
        end
        if V1b == "range" then
            return math.max(0.5, 1 + U1b / 2), 0
        end
        if V1b:find("cooldown") then
            return 1 / math.max(0.3, 1 + U1b), 0
        end
        return 1, 0
    end
    if T1b == "stat_mul_real" then
        if V1b == "damage" then
            return math.max(0.3, U1b), 0
        end
        if V1b == "range" then
            return math.max(0.5, 1 + (U1b - 1) / 2), 0
        end
        if V1b:find("cooldown") then
            return 1 / math.max(0.3, U1b), 0
        end
        return 1, 0
    end
    if T1b == "boss_damage" then
        return 1 + U1b / 3, 0
    end
    if T1b == "enemy_stat_mul" then
        return 1 / math.max(0.3, 1 + U1b), 0
    end
    if T1b == "enemy_resistance_specific" then
        return math.max(0.2, 1 - Match.rogueShare(S1b.damage_type) * (1 - 100 / (100 + U1b))), 0
    end
    if T1b == "enemy_amp_specific" then
        return 1 + Match.rogueShare(S1b.damage_type) * U1b, 0
    end
    if T1b == "weather_flying_chance" then
        return math.max(0.5, 1 - U1b * 0.5), 0
    end
    if T1b == "weather_soaring_share" then
        return math.max(0.5, 1 - U1b * 0.2), 0
    end
    if T1b == "flying_damage" then
        return 1 + U1b * 0.1, 0
    end
    if T1b == "burst_speed" then
        return 1 / math.max(0.3, 1 + U1b * 0.5), 0
    end
    if T1b == "lightning_strikes" then
        return math.max(0.5, 1 - U1b * 0.1), 0
    end
    if T1b == "enemy_speedup" then
        return 1 / math.max(0.3, 1 + U1b), 0
    end
    if T1b == "enemy_regen" then
        return math.max(0.3, 1 - U1b * 20), 0
    end
    if T1b == "enemy_shield" then
        return math.max(0.5, 1 - U1b * 0.03), 0
    end
    if T1b == "enemy_bomb" then
        return 0.95, 0
    end
    if T1b == "enemy_passive_chance" then
        return math.max(0.5, 1 - U1b), 0
    end
    if T1b == "resource_gain" then
        return 1 + math.min(0.3, U1b / 40000), 0
    end
    if T1b == "unit_cost" then
        return 1 / math.max(0.3, 1 + U1b / 2), 0
    end
    if T1b == "new_path" then
        return 0.8, 0
    end
    if T1b == "random_effects" then
        local W1b = math.max(1, math.abs(U1b)) * math.max(1, math.abs(tonumber(S1b.tier) or 1))
        return S1b._type == "Good" and 1.1 ^ W1b or 0.8 ^ W1b, 0
    end
    return 1, 0
end

function Match.effectText(X1b)
    return string.format("%s%s %s", tostring(X1b.type), X1b.stat and ("." .. tostring(X1b.stat)) or "", tostring(X1b.amount))
end

function Match.learn()
    local Y1b, Z1b = {
    }, {
    }
    local _1b, a2b = 0, 0
    for b2b, c2b in ipairs(Match.mine) do
        local d2b = c2b._stats
        local e2b = d2b.id.Value
        local f2b = d2b:FindFirstChild("total_damage") and d2b.total_damage.Value or 0
        if not Units.isFarm(e2b) then
            Y1b [e2b] = (Y1b [e2b] or 0) + f2b
            Z1b [e2b] = (Z1b [e2b] or 0) + Match.liveDps(c2b, e2b) / math.max(0.5, Units.nudge(e2b))
            local g2b = Units.passive(e2b).mark
            if g2b then
                Z1b [e2b] = Z1b [e2b] + g2b.dot * d2b.damage.Value
            end
            _1b = _1b + f2b
        end
    end
    for h2b, i2b in pairs(Z1b) do
        a2b = a2b + i2b
    end
    if _1b <= 0 or a2b <= 0 then
        return
    end
    Match.lastEff = {
    }
    for j2b, k2b in pairs(Y1b) do
        local l2b, m2b = k2b / _1b, Z1b [j2b] / a2b
        if m2b > 0.02 then
            local n2b = Brain.learn [j2b] or {
                eff = 1,
                n = 0
            }
            local o2b = math.max(0.02, 0.25 * math.sqrt(30 / (30 + n2b.n)))
            local p2b = Utils.clamp(l2b / m2b, 0.3, 3)
            Match.lastEff [j2b] = math.floor(p2b * 1000 + 0.5) / 1000
            n2b.eff = n2b.eff + (p2b - n2b.eff) * o2b
            n2b.n = n2b.n + 1
            Brain.learn [j2b] = n2b
        end
    end
end

function Match.randomTeam()
    local q2b = Core.session()
    local r2b = q2b and q2b.collection.temporary_units or {
    }
    local s2b, t2b = {
    }, {
    }
    local function u2b(v2b, w2b, x2b)
        local y2b = v2b and r2b [v2b]
        if y2b and Core.Units [y2b.unit_id] and not t2b [v2b] then
            t2b [v2b] = true
            table.insert(s2b, {
                slot = x2b or 99,
                uuid = v2b,
                u = y2b,
                id = y2b.unit_id,
                data = Core.Units [y2b.unit_id],
                hand = w2b
            })
        end
    end
    for z2b, A2b in pairs(q2b and q2b.override_equipped_units or {
    }) do
        u2b(A2b, true, tonumber(z2b))
    end
    for B2b, C2b in ipairs(Match.mine or {
    }) do
        local D2b = C2b._stats
        u2b(D2b:FindFirstChild("uuid") and D2b.uuid.Value, false)
    end
    table.sort(s2b, function(E2b, F2b)
        return E2b.slot < F2b.slot
    end)
    return s2b
end

function Match.fhSnap()
    local G2b, H2b = nil, nil
    pcall(function()
        for I2b, J2b in ipairs(workspace._BASES:GetDescendants()) do
            if J2b:IsA("Humanoid") then
                G2b, H2b = J2b.Health, J2b.MaxHealth
                break
            end
        end
    end)
    local K2b = G2b and H2b and H2b > 0 and math.floor(G2b / H2b * 100) or - 1
    local L2b, M2b, N2b = 0, {
    }, {
    }
    for O2b, P2b in ipairs(Match.enemies or {
    }) do
        if (P2b.prog or 0) > 0.8 then
            L2b = L2b + 1
            M2b [tostring(P2b.m)] = (M2b [tostring(P2b.m)] or 0) + 1
        end
        N2b [tostring(P2b.m)] = (N2b [tostring(P2b.m)] or 0) + 1
    end
    if not next(M2b) then
        M2b = N2b
    end
    local Q2b = 0
    for R2b, S2b in ipairs(Match.mine or {
    }) do
        local T2b, U2b = pcall(Match.liveDps, S2b, S2b._stats.id.Value)
        if T2b and U2b then
            Q2b = Q2b + U2b
        end
    end
    Match.fhWaves = Match.fhWaves or {
    }
    local V2b = 0
    for W2b, X2b in ipairs(Match.enemies or {
    }) do
        if X2b.fly then
            V2b = V2b + 1
        end
    end
    table.insert(Match.fhWaves, string.format("%d:%d:%d:%d:%s:%d:%.2f:%s:air%d%%:fly%d", Match.wave(), K2b, # (Match.enemies or {
    }), L2b, Utils.fmt(Q2b), Match.fieldCount(), Match.fhMult or 1, Utils.fmt(Match.money()), math.floor(Match.airShare() * 100 + 0.5), V2b))
    if K2b >= 0 and Match.fhLastPct and K2b < Match.fhLastPct and not Match.fhLeak then
        local Y2b = {
        }
        for Z2b, _2b in pairs(M2b) do
            table.insert(Y2b, Units.name(Z2b) .. "×" .. _2b)
        end
        Match.fhLeak = string.format("wave %d: base %d%% → %d%%, near it: %s", Match.wave(), Match.fhLastPct, K2b, # Y2b > 0 and table.concat(Y2b, ", ") or "nothing seen")
        App.log(1, "MATCH", "first damage to the base — " .. Match.fhLeak)
    end
    Match.fhLastPct = K2b
end

function Match.fhRecord(a3b, b3b)
    local c3b, d3b = {
    }, 0
    for e3b, f3b in ipairs(Match.mine or {
    }) do
        local g3b = f3b._stats
        local h3b = g3b:FindFirstChild("total_damage") and tonumber(g3b.total_damage.Value) or 0
        local i3b = g3b.id.Value
        if h3b > 0 then
            c3b [i3b] = (c3b [i3b] or 0) + h3b
            d3b = d3b + h3b
        end
    end
    local j3b = {
    }
    for k3b, l3b in pairs(c3b) do
        local m3b = d3b > 0 and l3b / d3b or 0
        local n3b = Brain.fh.units [k3b] or {
            n = 0,
            share = 0
        }
        n3b.share = (n3b.share * n3b.n + m3b) / (n3b.n + 1)
        n3b.n = n3b.n + 1
        Brain.fh.units [k3b] = n3b
        table.insert(j3b, {
            id = k3b,
            share = m3b
        })
    end
    table.sort(j3b, function(o3b, p3b)
        return o3b.share > p3b.share
    end)
    local q3b = {
    }
    for r3b = 1, math.min(4, # j3b) do
        table.insert(q3b, string.format("%s %d%%", Units.name(j3b [r3b].id), math.floor(j3b [r3b].share * 100 + 0.5)))
    end
    pcall(Match.fhSnap)
    local s3b = tonumber(Brain.fh.pmin) or 1
    Brain.fh.pmin = Utils.clamp(s3b * (b3b and 0.9 or 1.1), 0.5, 2.5)
    table.insert(Brain.fh.runs, 1, {
        at = os.time(),
        wave = Match.wave(),
        won = b3b or nil,
        coins = a3b,
        top = q3b,
        mult = Match.fhMult or 1,
        discards = Match.discards,
        strength = Match.fhP,
        floor = s3b,
        effects = Match.fhEffects,
        picks = Match.fhPicks,
        leak = Match.fhLeak,
        waves = Match.fhWaves
    })
    while # Brain.fh.runs > 20 do
        table.remove(Brain.fh.runs)
    end
    App.log(1, "RESULT", string.format("dealt team reached wave %d; most damage: %s", Match.wave(), table.concat(q3b, ", ")))
end

function Match.carry(t3b)
    local u3b = Brain.fh.units [t3b]
    return u3b and u3b.n > 0 and u3b.share or 0
end

function Match.fhText()
    local v3b = Brain.fh.runs
    if # v3b == 0 then
        return "No Fool's Hunt run recorded yet."
    end
    local w3b, x3b = 0, 0
    for y3b, z3b in ipairs(v3b) do
        w3b = w3b + (z3b.wave or 0)
        x3b = x3b + (z3b.coins or 0)
    end
    local A3b = {
    }
    for B3b, C3b in pairs(Brain.fh.units) do
        if C3b.n >= 2 then
            table.insert(A3b, {
                id = B3b,
                share = C3b.share,
                n = C3b.n
            })
        end
    end
    table.sort(A3b, function(D3b, E3b)
        return D3b.share > E3b.share
    end)
    local F3b = {
    }
    for G3b = 1, math.min(6, # A3b) do
        table.insert(F3b, string.format("%s %d%% (%d runs)", Units.name(A3b [G3b].id), math.floor(A3b [G3b].share * 100 + 0.5), A3b [G3b].n))
    end
    local H3b = 0
    for I3b in pairs(Brain.unitData) do
        H3b = H3b + 1
    end
    local J3b = 0
    for K3b, L3b in ipairs(v3b) do
        if L3b.won then
            J3b = J3b + 1
        end
    end
    local M3b = v3b [1]
    local N3b, O3b = Brain.fh.merge, Brain.fh.idol
    local P3b = ""
    if N3b and N3b.n > 0 then
        P3b = P3b .. string.format("\nMerges cast: %d, each gave %.0f%% of what the game's description promises.", N3b.n, N3b.ratio / N3b.n * 100)
    end
    if O3b and O3b.n > 0 then
        P3b = P3b .. string.format("\nIdol: each upgrade adds %.1f%% damage and makes upgrades %.1f%% cheaper (measured %d times).", O3b.dmg / O3b.n * 100, O3b.cost / O3b.n * 100, O3b.n)
    end
    local Q3b, R3b = Brain.fh.clone, Brain.fh.ritual
    if Q3b and Q3b.n > 0 then
        P3b = P3b .. string.format("\nClones: %d made, each with %.0f%% of the original's damage and %.0f%% of the yen in it.", Q3b.n, Q3b.ratio / Q3b.n * 100, Q3b.spent / Q3b.n * 100)
    end
    if R3b and R3b.n > 0 then
        P3b = P3b .. string.format("\nRitual: %d cast, the Divine General came out at %.1f× the sacrificed unit's damage.", R3b.n, R3b.ratio / R3b.n)
    end
    local S3b = Brain.fh.farmMerge
    if S3b and S3b.n > 0 then
        P3b = P3b .. string.format("\nFarm merges: %d tested, each kept %.0f%% of 1.5× the income it took in.", S3b.n, S3b.ratio / S3b.n * 100)
    end
    return string.format("Fool's Hunt: %d runs recorded (%d won), wave %.0f and %d AprilCoins a run on average. Last run: wave %s, coin multiplier ×%.2f, team strength ×%.2f%s; most damage: %s.\n" .. "Coin-multiplier picks need team strength ×%.2f or more (it goes up after a lost run, down after a won one, until it wins with the highest multiplier).\n" .. "Dealt units that carry (average share of the damage): %s.\nHidden unit stats learned so far: %d units.%s", # v3b, J3b, w3b / # v3b, math.floor(x3b / # v3b + 0.5), tostring(M3b.wave), tonumber(M3b.mult) or 1, tonumber(M3b.strength) or 1, M3b.leak and (" · first base hit: " .. M3b.leak) or "", table.concat(M3b.top or {
    }, ", "), tonumber(Brain.fh.pmin) or 1, # F3b > 0 and table.concat(F3b, " · ") or "needs 2 runs with a unit", H3b, P3b)
end

function Match.cardDps(T3b)
    local U3b, V3b = pcall(Units.dps, T3b.u, 0, Match.mod)
    V3b = U3b and tonumber(V3b) or 0
    if V3b > 0 or Units.isFarm(T3b.id) or Units.idol(T3b.id) or Units.allyBuff(T3b.id) then
        return V3b
    end
    local W3b = table.clone(Match.cardVals or {
    })
    if # W3b == 0 then
        return 1000
    end
    table.sort(W3b)
    return W3b [math.max(1, math.ceil(# W3b * 0.6))]
end

function Match.cardValue(X3b)
    if Units.isFarm(X3b.id) then
        return 0
    end
    if Units.idol(X3b.id) then
        return (Match.teamDps or 0) * Match.idolStep() * 3
    end
    local Y3b = Units.allyBuff(X3b.id) and Match.buffGain(X3b) or Match.cardDps(X3b)
    return Y3b * (1 + 2 * Match.carry(X3b.id)) * (1 - Match.resistOf(X3b.id)) * Match.airNeed(X3b.id) * (Match.mergeIds [X3b.id] and 2 or 1)
end

function Match.flyMode()
    if Match.random or Match.flyerSeen then
        return true
    end
    if Match.kind == "dungeon" then
        if Match._curseFly == nil then
            local Z3b, _3b = pcall(Dungeon.items, Dungeon.data())
            Match._curseFly = Z3b and (_3b._curse_fly or 0) > 0 or false
        end
        return Match._curseFly
    end
    return false
end

function Match.shieldNow()
    local a4b = Match.wave()
    if Match._shieldW ~= a4b then
        Match._shieldW, Match._shieldS, Match._shieldH = a4b, 0, 1
        local b4b, c4b = pcall(Simulator.wave, Match.info, math.max(1, a4b), true)
        if Match.info and b4b and # c4b > 0 then
            local d4b, e4b = 0, 0
            for f4b, g4b in ipairs(c4b) do
                d4b, e4b = d4b + (g4b.sh or 0), e4b + g4b.hp
            end
            Match._shieldS, Match._shieldH = d4b / # c4b, e4b / # c4b
        end
    end
    return Match._shieldS, Match._shieldH
end

function Match.shieldOf(h4b, i4b)
    local j4b, k4b = Match.shieldNow()
    if j4b <= 0 or not i4b then
        return h4b
    end
    local l4b = Units.attackInfo(i4b.atk, i4b.range)
    return Economy.shieldDps(h4b, tonumber(i4b.cd) or 2, l4b.n, j4b, k4b, Match.info and Match.info.eff, l4b.hits)
end

function Match.shieldWork(m4b, n4b)
    local o4b, p4b = Match.shieldNow()
    if o4b <= 0 or not n4b or not Match.info then
        return 0
    end
    local q4b, r4b = 0, 0
    for s4b, t4b in ipairs(Match.team or {
    }) do
        local u4b = Units.rows(t4b.id)
        u4b = u4b and u4b [0]
        if u4b and not Units.isFarm(t4b.id) then
            q4b = math.max(q4b, Units.dps(t4b.u, 0, Match.mod) * (tonumber(u4b.cd) or 2) / math.max(1, Units.attackInfo(u4b.atk, u4b.range).n))
        end
    end
    for v4b, w4b in ipairs(Match.mine or {
    }) do
        local x4b = w4b._stats.id.Value
        local y4b = Units.rows(x4b)
        local z4b = y4b and y4b [w4b._stats.upgrade and w4b._stats.upgrade.Value or 0]
        if z4b and not Units.isFarm(x4b) and not Units.allyBuff(x4b) then
            local A4b = Units.attackInfo(z4b.atk, z4b.range)
            r4b = r4b + A4b.n * A4b.hits / math.max(0.3, tonumber(z4b.cd) or 2)
        end
    end
    local B4b, C4b = pcall(Simulator.wave, Match.info, math.max(1, Match.wave()), true)
    local D4b = Units.attackInfo(n4b.atk, n4b.range)
    return Economy.shieldWork(D4b.n, tonumber(n4b.cd) or 2, r4b, o4b, B4b and # C4b or 1, Match.info.waveSec, q4b * (Match.info.eff or 1), p4b, D4b.hits)
end

function Match.teamShield()
    if Match._shieldAt and Utils.now() - Match._shieldAt < 2 then
        return Match._shieldTeam
    end
    local E4b, F4b = 0, 0
    for G4b, H4b in ipairs(Match.mine or {
    }) do
        local I4b = H4b._stats.id.Value
        if not Units.isFarm(I4b) and H4b._stats:FindFirstChild("upgrade") then
            local J4b = Units.rows(I4b)
            local K4b, L4b = pcall(Match.liveDps, H4b, I4b)
            if K4b and J4b then
                E4b = E4b + L4b
                F4b = F4b + Match.shieldOf(L4b, J4b [H4b._stats.upgrade.Value])
            end
        end
    end
    Match._shieldTeam, Match._shieldAt = E4b > 0 and math.max(0.05, F4b / E4b) or 1, Utils.now()
    return Match._shieldTeam
end

function Match.airLow()
    if not Match.flyMode() then
        return false
    end
    if FarmHub.every("airShare", 1) or not Match.airShareNow then
        Match.airShareNow = Match.airShare()
    end
    return Match.airShareNow < 0.5
end

function Match.airWeight(M4b)
    if not (M4b and Match.flyMode()) then
        return 1
    end
    return Match.airLow() and 2.5 or 1.5
end

function Match.reach(N4b)
    if not Match.reachAt or Utils.now() - Match.reachAt > 5 then
        local O4b, P4b = 0, 0
        for Q4b, R4b in ipairs(Match.mine or {
        }) do
            local S4b = R4b._stats
            if not Units.isFarm(S4b.id.Value) and S4b:FindFirstChild("range") then
                O4b, P4b = O4b + Match.cover(R4b:GetPivot().Position, S4b.range.Value), P4b + 1
            end
        end
        Match.reachAvg, Match.reachAt = P4b > 0 and O4b / P4b or 0, Utils.now()
    end
    local T4b = N4b._stats
    if (Match.reachAvg or 0) <= 0 or not T4b:FindFirstChild("range") then
        return 1
    end
    local U4b = Match.reachCache [N4b]
    if U4b and Utils.now() - U4b.t < 5 then
        return U4b.v
    end
    local V4b = Utils.clamp(Match.cover(N4b:GetPivot().Position, T4b.range.Value) / Match.reachAvg, 0.4, 1.6)
    Match.reachCache [N4b] = {
        v = V4b,
        t = Utils.now()
    }
    return V4b
end
Match.reachCache = setmetatable({
}, {
    __mode = "k"
})

function Match.airNeed(W4b)
    local X4b = Units.airFrom(W4b)
    if X4b == 0 then
        return Match.airWeight(true)
    end
    if X4b then
        return 1 + (Match.airWeight(true) - 1) * 0.4
    end
    return 1
end

function Match.airBoost(Y4b)
    if Match.canAir(Y4b) then
        return Match.airWeight(true)
    end
    local Z4b = Units.airFrom(Y4b._stats.id.Value)
    if not Z4b then
        return 1
    end
    return 1 + (Match.airWeight(true) - 1) * math.min(1, (Y4b._stats.upgrade.Value + 1) / math.max(1, Z4b))
end
Match.cardSeen, Match.cardVals = {
}, {
}

function Match.fish()
    if not Match.random then
        return
    end
    local _4b = {
    }
    for a5b, b5b in ipairs(Match.team) do
        if b5b.hand then
            table.insert(_4b, b5b)
            if not Match.cardSeen [b5b.uuid] then
                Match.cardSeen [b5b.uuid] = Utils.now()
                if not Units.isFarm(b5b.id) and not Units.idol(b5b.id) then
                    table.insert(Match.cardVals, Match.cardValue(b5b))
                end
            end
        end
    end
    if # Match.cardVals < 8 or not FarmHub.every("fish", 5) then
        return
    end
    local c5b = table.clone(Match.cardVals)
    table.sort(c5b)
    local d5b = c5b [math.max(1, math.ceil(# c5b * 0.6))]
    local e5b = 0
    for f5b, g5b in ipairs(Match.mine or {
    }) do
        if Units.isFarm(g5b._stats.id.Value) then
            e5b = e5b + 1
        end
    end
    local h5b = Match.fieldCount() < 16
    local i5b = false
    for j5b, k5b in ipairs(_4b) do
        local l5b = Units.isFarm(k5b.id) and Match.wave() < 12 and e5b < 3 and not i5b
        if l5b then
            i5b = true
        end
        local m5b = Match.roomPlan and Match.roomPlan.name == Units.name(k5b.id)
        local n5b = (Match.noSpot [k5b.uuid] or 0) >= 3
        local o5b = not n5b and (l5b or m5b or Units.idol(k5b.id) or Match.mergeIds [k5b.id])
        local p5b = Utils.now() - (tonumber(Match.cardSeen [k5b.uuid]) or Utils.now()) > 60
        if n5b or (not o5b and Match.cardValue(k5b) < d5b * ((h5b and not p5b) and 0.25 or 1)) then
            if Match.discardCard(k5b) then
                App.log(2, "PLACE", string.format("discarded %s (%s) for a new card", Units.name(k5b.id), n5b and "no spot it fits" or ("worth " .. Utils.fmt(Match.cardValue(k5b)) .. ", the bar is " .. Utils.fmt(d5b))))
                Match.discards = (Match.discards or 0) + 1
            end
            return
        end
    end
end

function Match.discardCard(q5b)
    local r5b = tostring(q5b.slot)
    local s5b = Core.session().override_equipped_units or {
    }
    if s5b [r5b] ~= q5b.uuid then
        return false
    end
    if not App.request("discard", "delete_ingame_temporary_unit", r5b) then
        return false
    end
    task.wait(0.3)
    local t5b = (Core.session().override_equipped_units or {
    }) [r5b] ~= q5b.uuid
    if not t5b and FarmHub.every("discardFail", 30) then
        App.log(1, "PLACE", "the game didn't take the discard of " .. Units.name(q5b.id))
    end
    return t5b
end

function Match.watchLine()
    local u5b = Core.session()
    local v5b, w5b = {
    }, {
    }
    for x5b, y5b in ipairs(Match.team or {
    }) do
        if y5b.hand then
            table.insert(v5b, Units.name(y5b.id) .. " " .. Utils.fmt(Match.cardValue(y5b)))
            table.insert(w5b, y5b.uuid)
        end
    end
    local z5b = {
    }
    for A5b, B5b in pairs((u5b and u5b.ingame_spells) or {
    }) do
        table.insert(z5b, Match.SPELL_NAMES [B5b] or tostring(B5b))
    end
    local C5b = table.concat(w5b, ",")
    if C5b ~= Match.handKey then
        Match.handKey, Match.handSince = C5b, Utils.now()
    end
    local D5b = # w5b > 0 and Utils.now() - Match.handSince >= 90
    App.log(1, "WATCH", string.format("wave %d · %d/%d units · ¥%s · hand: %s%s · merge: %s%s · economy: %s%s", Match.wave(), Match.fieldCount(), Match.FIELD_MAX, Utils.fmt(Match.money()), # v5b > 0 and table.concat(v5b, ", ") or "no unit cards", # z5b > 0 and (" + " .. table.concat(z5b, ", ")) or "", tostring(Status.Merge or "-"), Match.cloneNote and (" · clone: " .. Match.cloneNote) or "", tostring(Status.Economy or "-"), D5b and " · HAND STUCK 90s+" or ""))
end
