function Match.summonWorth()
    if Match.summonAvg == nil then
        local E5b, F5b, G5b = 0, 0, 0
        for H5b, I5b in ipairs(Units.equipped()) do
            local J5b, K5b = pcall(Units.dps, I5b.u, 0, Match.mod)
            E5b, F5b, G5b = E5b + ((not Units.isFarm(I5b.id) and J5b and K5b) or 0), F5b + 1, G5b + (I5b.data.cost or 0)
        end
        Match.summonAvg, Match.summonCost = F5b > 0 and E5b / F5b or 0, F5b > 0 and G5b / F5b or 0
    end
    local L5b = Match.bestRate or 0
    return L5b <= 0 or Match.summonAvg * 2 >= L5b * (10000 + Match.summonCost)
end

function Match.hasGeneral()
    for M5b, N5b in ipairs(Match.mine or {
    }) do
        if N5b._stats.id.Value == "mahoraga" then
            return true
        end
    end
    return false
end

function Match.ritualWorth()
    local O5b = Brain.fh.ritual
    return O5b and O5b.n >= 2 and O5b.ratio / O5b.n or nil
end

function Match.ritualTarget()
    local P5b = Match.mergePlan
    local Q5b = {
    }
    for R5b, S5b in ipairs(Match.mine) do
        local T5b = S5b._stats.id.Value
        if not Units.isFarm(T5b) and not Units.allyBuff(T5b) and not Units.idol(T5b) and not (P5b and P5b.id == T5b) and not (Match.airLow() and Match.canAir(S5b)) then
            local U5b, V5b = pcall(Match.liveDps, S5b, T5b)
            if U5b and V5b and V5b > 0 then
                table.insert(Q5b, {
                    m = S5b,
                    dps = V5b
                })
            end
        end
    end
    if # Q5b < 3 then
        return nil
    end
    table.sort(Q5b, function(W5b, X5b)
        return W5b.dps > X5b.dps
    end)
    local Y5b = Match.ritualWorth()
    if not Y5b then
        return Q5b [3].m, "a test: how strong the Divine General comes out of this unit"
    end
    if Y5b >= 1.5 then
        return Q5b [1].m, string.format("the Divine General came out at %.1f× the unit's damage before", Y5b)
    end
    return nil
end
Match.ADAPT_ORDER = {
    "Divine Wings",
    "Adapted Slash",
