function Match.adapt()
    if not getconnections then
        return
    end
    local Z5b = false
    for _5b, a6b in ipairs(Match.mine or {
    }) do
        if a6b._stats.id.Value == "mahoraga" then
            Z5b = true
            break
        end
    end
    if not Z5b then
        return
    end
    if not (Match.adaptPrompt and Match.adaptPrompt.Parent) then
        Match.adaptPrompt = nil
        local b6b = LocalPlayer:FindFirstChild("PlayerGui")
        for c6b, d6b in ipairs(b6b and b6b:GetDescendants() or {
        }) do
            if d6b.Name == "MahoragaAdaptationPrompt" and not d6b:FindFirstAncestorOfClass("Configuration") then
                Match.adaptPrompt = d6b
                break
            end
        end
    end
    local e6b = Match.adaptPrompt
    if not (e6b and e6b:IsA("GuiObject") and e6b.Visible) then
        Match.adaptTries = 0
        return
    end
    Match.adaptTries = (Match.adaptTries or 0) + 1
    if Match.adaptTries > 3 then
        return
    end
    local f6b = {
    }
    for g6b, h6b in ipairs(e6b:GetDescendants()) do
        if h6b:IsA("TextLabel") and h6b.Name == "Mode" and h6b.Parent then
            f6b [h6b.Text] = h6b.Parent
        end
    end
    for i6b, j6b in ipairs(Match.ADAPT_ORDER) do
        local k6b = f6b [j6b]
        local l6b = k6b and (k6b:IsA("GuiButton") and k6b or k6b:FindFirstChildWhichIsA("GuiButton", true))
        if l6b and k6b.Visible then
            local m6b = 0
            for n6b, o6b in ipairs({
                l6b.Activated,
                l6b.MouseButton1Click,
                l6b.MouseButton1Down
            }) do
                for p6b, q6b in ipairs(getconnections(o6b)) do
                    if pcall(function()
                        q6b:Fire()
                    end) then
                        m6b = m6b + 1
                    end
                end
            end
            App.log(1, "SPELL", string.format("Divine General adapts: %s (%d click handler%s, try %d)", j6b, m6b, m6b == 1 and "" or "s", Match.adaptTries))
            return
        end
    end
end

function Match.newUnitMeasure(r6b, s6b, t6b, u6b, v6b)
    task.spawn(function()
        local w6b
        for x6b = 1, 10 do
            task.wait(1)
            for y6b, z6b in ipairs(workspace._UNITS:GetChildren()) do
                local A6b = z6b:FindFirstChild("_stats")
                if not v6b [z6b] and A6b and A6b:FindFirstChild("player") and A6b.player.Value == LocalPlayer and A6b:FindFirstChild("damage") and (r6b == "ritual" or A6b.id.Value == u6b.id) then
                    w6b = z6b
                    break
                end
            end
            if w6b then
                task.wait(1)
                break
            end
        end
        if not w6b then
            App.log(2, "SPELL", (Match.SPELL_NAMES [r6b] or r6b) .. ": couldn't find the new unit to measure")
            return
        end
        local B6b = w6b._stats
        local C6b, D6b = pcall(Match.liveDps, w6b, B6b.id.Value)
        D6b = C6b and tonumber(D6b) or 0
        local E6b = B6b:FindFirstChild("total_spent") and tonumber(B6b.total_spent.Value) or 0
        local F6b = Brain.fh [r6b] or {
            n = 0,
            ratio = 0,
            spent = 0
        }
        if u6b.dps > 0 then
            F6b.n, F6b.ratio, F6b.spent = F6b.n + 1, F6b.ratio + D6b / u6b.dps, F6b.spent + (u6b.spent > 0 and E6b / u6b.spent or 0)
        end
        Brain.fh [r6b] = F6b
        App.log(1, "SPELL", string.format("%s result: %s at level %s does %s damage a second (%s had %s at level %d) · ¥%s in it (%s had ¥%s) · %.0f studs away", Match.SPELL_NAMES [r6b] or r6b, Units.name(B6b.id.Value), tostring(B6b:FindFirstChild("upgrade") and B6b.upgrade.Value or "?"), Utils.fmt(D6b), t6b, Utils.fmt(u6b.dps), u6b.lvl, Utils.fmt(E6b), t6b, Utils.fmt(u6b.spent), (Utils.flat(w6b:GetPivot().Position) - Utils.flat(u6b.pos)).Magnitude))
    end)
end

