function Match.makeRoom()
    local K6b = Core.session()
    if not (Match.random and K6b) or Match.spellBusy then
        return
    end
    local L6b = {
    }
    for M6b, N6b in pairs(K6b.ingame_spells or {
    }) do
        L6b [N6b] = (L6b [N6b] or 0) + 1
        local O6b = Match.ritualWorth()
        local P6b = N6b == "ritual" and ((O6b and O6b < 1.5) and 0 or 1) or (N6b == "sacrifice" and Match.mergePlan) and 2 or 1
        if (N6b == "summon" or N6b == "gate") and not Match.summonWorth() then
            P6b = 0
        end
        if N6b == "ritual" and Match.hasGeneral() then
            P6b = 0
        end
        if N6b == "sell_refund" and Match.wave() < 22 and Match.fieldCount() < 18 then
            P6b = 0
        end
        if L6b [N6b] > P6b then
            if App.request("discard", "delete_ingame_spell", M6b) and (task.wait(0.3) and (Core.session().ingame_spells or {
            }) [M6b] ~= N6b) then
                local Q6b = P6b > 0 and "one is enough in the hand" or N6b == "ritual" and (Match.hasGeneral() and "a Divine General is already on the field" or "the Divine General came out too weak") or N6b == "sell_refund" and "Refund is for late waves" or "not worth its price now"
                App.log(1, "SPELL", string.format("discarded %s (%s) for a new card", Match.SPELL_NAMES [N6b] or tostring(N6b), Q6b))
            end
            return
        end
    end
    if Match.fieldCount() < Match.FIELD_MAX or Utils.now() - (Match.roomSoldAt or - 99) < 15 then
        return
    end
    local R6b, S6b
    for T6b, U6b in ipairs(Match.team) do
        if U6b.hand and not Units.isFarm(U6b.id) and (Match.noSpot [U6b.uuid] or 0) < 3 then
            local V6b = Match.cardValue(U6b)
            if not S6b or V6b > S6b then
                R6b, S6b = U6b, V6b
            end
        end
    end
    local W6b = math.max(0, (Match.total or 30) - Match.wave())
    local X6b = Match.mergePlan
    local Y6b, Z6b
    if R6b and (tonumber(R6b.data.override_hitbox_radius) or 0) > 3 and not Match.bestSpot(R6b, true, false) then
        Match.noSpot [R6b.uuid] = 3
        R6b = nil
    end
    local _6b = Match.airLow()
    for a7b, b7b in ipairs(Match.mine) do
        local c7b = b7b._stats.id.Value
        local d7b = Core.Units [c7b]
        if d7b and (tonumber(d7b.cost) or 0) > 0 and not d7b.unsellable and not Units.allyBuff(c7b) and not Units.idol(c7b) and not (X6b and X6b.id == c7b) and not (_6b and Match.canAir(b7b)) then
            local e7b
            if Units.isFarm(c7b) then
                local f7b = b7b._stats:FindFirstChild("farm_amount") and tonumber(b7b._stats.farm_amount.Value) or 0
                e7b = (Match.bestRate or 0) > 0 and f7b * W6b * Match.bestRate or math.huge
            else
                local g7b, h7b = pcall(Match.liveDps, b7b, c7b)
                e7b = g7b and h7b or math.huge
            end
            if not Z6b or e7b < Z6b then
                Y6b, Z6b = b7b, e7b
            end
        end
    end
    Match.roomPlan = nil
    if R6b and Y6b and S6b > 2 * Z6b then
        local i7b
        for j7b, k7b in pairs(K6b.ingame_spells or {
        }) do
            if k7b == "sell_refund" then
                i7b = j7b
            end
        end
        local l7b = Y6b._stats:FindFirstChild("total_spent") and tonumber(Y6b._stats.total_spent.Value) or 0
        local m7b = (R6b.data.cost or 0) - l7b * (i7b and 1 or 0.5)
        local n7b = Units.name(Y6b._stats.id.Value)
        if Match.money() >= m7b then
            local o7b = i7b and App.request("spell", "use_ingame_spell", i7b, Y6b) or (not i7b and App.request("sell", "sell_unit_ingame", Y6b))
            if o7b then
                App.log(1, "PLACE", string.format("made room: sold %s%s for %s (2× the damage or more)", n7b, i7b and " (full refund)" or "", Units.name(R6b.id)))
                Match.roomSoldAt = Utils.now()
                task.wait(0.6)
                Match.scan()
                Match.place(R6b, "the spot just made for it")
            end
        else
            Match.roomPlan = {
                name = Units.name(R6b.id),
                out = n7b,
                need = m7b
            }
        end
        return
    end
    if not FarmHub.every("discard", 20) then
        return
    end
    local p7b, q7b
    for r7b, s7b in ipairs(Match.team) do
        if s7b.hand and not Units.idol(s7b.id) and not Match.mergeIds [s7b.id] then
            local t7b = Units.isFarm(s7b.id) and 0 or Match.cardDps(s7b)
            if not q7b or t7b < q7b then
                p7b, q7b = s7b, t7b
            end
        end
    end
    if p7b and Match.discardCard(p7b) then
        App.log(2, "PLACE", "discarded " .. Units.name(p7b.id) .. " from the hand (the field is full, it isn't worth a spot)")
    end
end
