function Match.refund()
    local u7b = Core.session()
    if not (Match.random and u7b) or Match.spellBusy or Match.roomPlan or not FarmHub.every("refund", 20) then
        return
    end
    local v7b
    for w7b, x7b in pairs(u7b.ingame_spells or {
    }) do
        if x7b == "sell_refund" then
            v7b = w7b
        end
    end
    if not v7b then
        return
    end
    local y7b = (Match.pressure or 0) >= math.min(Config.dangerReach, ((Match.depth and Match.depth.units > 0 and Match.depth.covEnd) or 1) * 0.9)
    local z7b = Match.bestRate or 0
    if y7b or z7b <= 0 then
        return
    end
    local A7b = Match.wave()
    local B7b = math.max(0, (Match.total or 30) - A7b)
    local C7b = Match.mergePlan
    local D7b = Match.airLow()
    local E7b, F7b, G7b
    for H7b, I7b in ipairs(Match.mine) do
        local J7b = I7b._stats
        local K7b = J7b.id.Value
        local L7b = Core.Units [K7b]
        local M7b = J7b:FindFirstChild("total_spent") and tonumber(J7b.total_spent.Value) or 0
        if L7b and not L7b.unsellable and M7b > 0 and not Units.allyBuff(K7b) and not Units.idol(K7b) and not (C7b and C7b.id == K7b) then
            local N7b, O7b
            if Units.isFarm(K7b) then
                local P7b = J7b:FindFirstChild("farm_amount") and tonumber(J7b.farm_amount.Value) or 0
                local Q7b = P7b * B7b
                if M7b > Q7b * 1.2 then
                    N7b = (M7b - Q7b) * z7b
                    O7b = string.format("a farm that still pays ¥%s but gives back ¥%s now", Utils.fmt(Q7b), Utils.fmt(M7b))
                end
            elseif A7b >= 10 and B7b > 2 and M7b >= 5000 and (Match.upRate [I7b] or 0) < z7b / 3 and Match.progressAt(I7b:GetPivot().Position) < 0.8 and not (D7b and Match.canAir(I7b)) then
                local R7b, S7b = pcall(Match.liveDps, I7b, K7b)
                S7b = R7b and S7b or math.huge
                if M7b * z7b > 3 * S7b and S7b < 0.1 * (Match.teamDps or 0) then
                    N7b = M7b * z7b - S7b
                    O7b = string.format("its ¥%s buys over 3× its damage in upgrades", Utils.fmt(M7b))
                end
            end
            if N7b and (not F7b or N7b > F7b) then
                E7b, F7b, G7b = I7b, N7b, O7b
            end
        end
    end
    if not E7b then
        return
    end
    Match.spellBusy = true
    task.spawn(function()
        local T7b = Units.name(E7b._stats.id.Value)
        local U7b = App.request("spell", "use_ingame_spell", v7b, E7b)
        task.wait(1.5)
        if U7b and (Core.session().ingame_spells or {
        }) [v7b] ~= "sell_refund" then
            Match.refunds = (Match.refunds or 0) + 1
            App.log(1, "SPELL", string.format("Refund on %s — %s", T7b, G7b))
            App.status("Abilities", "Refund on " .. T7b)
        else
            App.backoff("spell", 15)
            App.log(2, "SPELL", "Refund wasn't taken on " .. T7b)
        end
        Match.spellBusy = false
    end)
end

function Match.bossStep()
    Match.focus = nil
    if Match.random or Match.infinite or not (Match.total and Match.wave() >= Match.total) then
        return
    end
    local V7b = Match.enemies or {
    }
    for W7b, X7b in ipairs(V7b) do
        local Y7b = X7b.m and X7b.m:FindFirstChildOfClass("Humanoid")
        if Y7b and Y7b.MaxHealth > ((Match.bossTop and Match.bossTop.hp) or 0) then
            local Z7b = X7b.m:FindFirstChild("_stats")
            Match.bossTop = {
                hp = Y7b.MaxHealth,
                id = Z7b and Z7b:FindFirstChild("id") and Z7b.id.Value,
                regen = Z7b and Z7b:FindFirstChild("Regen") and Z7b.Regen.Value
            }
        end
    end
    if # V7b <= 2 and Match.bossTop and not Match.bossSaid then
        Match.bossSaid = true
        pcall(function()
            local _7b = 0
            if Match.info then
                for a8b, b8b in ipairs((Simulator.wave(Match.info, Match.total))) do
                    if b8b.boss and b8b.hp > _7b then
                        _7b = b8b.hp
                    end
                end
            end
            App.log(1, "MATCH", string.format("the boss: %s, %.3g HP, heals %s%% a second · the simulator plays one of %.3g HP", tostring(Match.bossTop.id), Match.bossTop.hp, tostring(Match.bossTop.regen), _7b))
        end)
    end
    if # V7b == 0 or # V7b > 2 then
        Match.focusTrack = nil
        return
    end
    local c8b, d8b = nil, 1
    for e8b, f8b in ipairs(V7b) do
        if not c8b or f8b.hp > c8b.hp then
            c8b = f8b
        end
        d8b = math.min(d8b, f8b.prog)
    end
    Match.focus = {
        pos = c8b.pos,
        prog = c8b.prog,
        fly = c8b.fly,
        m = c8b.m
    }
    local g8b = Utils.now()
    local h8b = Match.focusTrack
    if not h8b or h8b.m ~= c8b.m then
        Match.focusTrack = {
            m = c8b.m,
            t = g8b,
            hp = c8b.hp,
            prog = c8b.prog
        }
        return
    end
    if g8b - h8b.t >= 10 then
        h8b.net, h8b.rate = (h8b.hp - c8b.hp) / (g8b - h8b.t), (c8b.prog - h8b.prog) / (g8b - h8b.t)
        h8b.t, h8b.hp, h8b.prog = g8b, c8b.hp, c8b.prog
    end
    if not h8b.rate or h8b.rate <= 0 then
        return
    end
    local i8b = Utils.flat(c8b.pos)
    local j8b, k8b, l8b, m8b = {
    }, {
    }, 0, 0
    for n8b, o8b in ipairs(Match.mine or {
    }) do
        local p8b = o8b._stats
        local q8b = p8b.id.Value
        local r8b = Core.Units [q8b]
        if not Units.isFarm(q8b) and not Units.allyBuff(q8b) and not Units.BLESS.by [q8b] and r8b and not r8b.unsellable and p8b:FindFirstChild("range") then
            local s8b, t8b = Utils.flat(o8b:GetPivot().Position), p8b.range.Value
            local u8b = not c8b.fly or Match.canAir(o8b)
            if (s8b - i8b).Magnitude <= t8b and u8b then
                l8b = l8b + 1
            end
            if not ((s8b - i8b).Magnitude <= t8b and u8b) then
                local v8b
                for w8b, x8b in ipairs(Match.samples) do
                    if x8b.prog >= d8b and (Utils.flat(x8b.pos) - s8b).Magnitude <= t8b and (not v8b or x8b.prog < v8b) then
                        v8b = x8b.prog
                    end
                end
                local y8b = p8b:FindFirstChild("total_spent") and tonumber(p8b.total_spent.Value) or 0
                local z8b = Match.focusMoved and Match.focusMoved [q8b]
                local A8b = y8b <= 2.5 * (tonumber(r8b.cost) or 0)
                if v8b and u8b then
                    m8b = m8b + 1
                end
                if not v8b or not u8b then
                    if not z8b then
                        table.insert(j8b, {
                            m = o8b,
                            id = q8b,
                            spent = y8b
                        })
                    end
                elseif not z8b and A8b then
                    table.insert(k8b, {
                        m = o8b,
                        id = q8b,
                        spent = y8b,
                        eta = (v8b - c8b.prog) / h8b.rate
                    })
                end
            end
        end
    end
    local B8b = (1 - c8b.prog) / h8b.rate
    Match.focusLeft, Match.focusInRange = B8b, l8b
    local C8b = h8b.net and (h8b.net <= 0 or c8b.hp / h8b.net > B8b * 0.8)
    if C8b and FarmHub.every("bossBehind", 30) then
        App.log(1, "MATCH", string.format("boss: %s HP left, %s HP a second after its regen, at the base in %ds, %d units reach it: moving units up to it", Utils.fmt(c8b.hp), Utils.fmt(h8b.net), math.floor(B8b), l8b))
    end
    local D8b = tostring(Brain.dg.room and Brain.dg.room.seed)
    Brain.dg.bails = type(Brain.dg.bails) == "table" and Brain.dg.bails or {
    }
    if Match.kind == "dungeon" and not Match.bailed and Config.bailOut ~= false and (m8b == 0 or B8b < 15) and h8b.net and B8b > 4 and B8b < 60 and (tonumber(Brain.dg.bails [D8b]) or 0) < 3 then
        local E8b = c8b.m and c8b.m:FindFirstChildOfClass("Humanoid")
        local F8b = E8b and E8b.MaxHealth or c8b.hp
        local G8b = workspace:FindFirstChild("_BASES") and workspace._BASES:FindFirstChild("player")
        local H8b = G8b and G8b:FindFirstChild("base") and G8b.base:FindFirstChild("fake_unit")
        local I8b = H8b and H8b:FindFirstChildOfClass("Humanoid")
        local J8b = I8b and I8b.Health or (Match.info and tonumber(Match.info.baseHp)) or 100
        local K8b = (Match.info and tonumber(Match.info.baseRel)) or Simulator.PRIOR.baseRel
        local L8b = c8b.hp - math.max(0, h8b.net) * B8b
        local M8b = J8b / math.max(1, K8b * F8b)
        local N8b = L8b / math.max(1, h8b.net)
        if L8b > 0 and (h8b.net <= 0 or N8b > M8b * 1.3) then
            Match.bailed = true
            Brain.dg.bails [D8b] = (tonumber(Brain.dg.bails [D8b]) or 0) + 1
            Brain.dg.bail = {
                sig = Modes.teamSig(),
                at = os.time()
            }
            pcall(Match.styleRecord, false)
            App.log(1, "MATCH", string.format("bailing out: the boss would reach the base with %s HP, your units deal %s a second to it and the base would last %ds against it: back to the lobby to keep the life", Utils.fmt(L8b), Utils.fmt(h8b.net), math.floor(M8b)))
            App.flush()
            App.request("lobby", "teleport_back_to_lobby")
            return
        end
    end
    local O8b, P8b
    if l8b == 0 and B8b < 30 then
        return
    end
    if j8b [1] and FarmHub.every("bossSell", 2) then
        table.sort(j8b, function(Q8b, R8b)
            return Q8b.spent < R8b.spent
        end)
        O8b, P8b = j8b [1], l8b > 0 and "the boss has walked past it: its money goes to the units that reach it" or "the boss has walked past it"
    elseif C8b and k8b [1] and B8b >= 30 and FarmHub.every("bossSell", 8) then
        table.sort(k8b, function(S8b, T8b)
            return S8b.eta > T8b.eta
        end)
        if k8b [1].eta > 15 then
            O8b, P8b = k8b [1], string.format("the boss wouldn't reach it for %ds", math.floor(k8b [1].eta))
        end
    end
    if O8b then
        local U8b, V8b = App.request("sell", "sell_unit_ingame", O8b.m)
        if V8b == true then
            Match.focusMoved = Match.focusMoved or {
            }
            Match.focusMoved [O8b.id] = true
            App.log(1, "PLACE", string.format("boss: sold %s, ¥%s spent on it, to move up: %s", Units.name(O8b.id), Utils.fmt(O8b.spent), P8b))
        end
    end
end

function Match.focusSpot(W8b)
    local X8b = Match.focus
    local Y8b = Units.range(W8b.u, 0) * ((Match.info and Match.info.rangeScale) or 1)
    local Z8b = Utils.flat(X8b.pos)
    local _8b, a9b
    local b9b = 0
    for c9b, d9b in ipairs(Match.cands) do
        if (Utils.flat(d9b) - Z8b).Magnitude <= Y8b then
            local e9b = Match.valid(d9b, W8b.data)
            b9b = b9b + 1
            if b9b % 40 == 0 then
                task.wait()
            end
            if e9b then
                local f9b, g9b = 0, Utils.flat(e9b)
                for h9b, i9b in ipairs(Match.samples) do
                    if i9b.prog >= X8b.prog and (Utils.flat(i9b.pos) - g9b).Magnitude <= Y8b then
                        f9b = f9b + 1
                    end
                end
                if not a9b or f9b > a9b then
                    _8b, a9b = e9b, f9b
                end
            end
        end
    end
    return _8b, a9b or 0
end

function Match.focusGain(j9b)
    local k9b = Match.focus
    if not k9b then
        return 1
    end
    local l9b = j9b._stats
    if not l9b:FindFirstChild("range") then
        return 1
    end
    local m9b, n9b = Utils.flat(j9b:GetPivot().Position), l9b.range.Value
    if k9b.fly and not Match.canAir(j9b) then
        return 0.02
    end
    if (m9b - Utils.flat(k9b.pos)).Magnitude <= n9b then
        return 1
    end
    return (m9b - Utils.flat(k9b.pos)).Magnitude <= n9b * 1.5 and 0.3 or 0.02
end
