function Match.mergeScan()
    Match.mergePlan, Match.mergeIds = nil, {
    }
    if not Match.random then
        return
    end
    local D9b = Core.session()
    local E9b = false
    Match.cloneCard = false
    for F9b, G9b in pairs((D9b and D9b.ingame_spells) or {
    }) do
        if G9b == "sacrifice" then
            E9b = true
        elseif G9b == "clone" then
            Match.cloneCard = true
        end
    end
    local H9b = {
    }
    local I9b = Brain.fh.noMerge or {
    }
    for J9b, K9b in ipairs(Match.mine or {
    }) do
        local L9b = K9b._stats
        local M9b = L9b.id.Value
        if not Units.isFarm(M9b) and not Units.allyBuff(M9b) and not Units.idol(M9b) and L9b:FindFirstChild("max_upgrade") and (I9b [M9b] or 0) < 2 then
            local N9b, O9b = pcall(Match.liveDps, K9b, M9b)
            H9b [M9b] = H9b [M9b] or {
            }
            table.insert(H9b [M9b], {
                m = K9b,
                lvl = L9b.upgrade.Value,
                max = L9b.max_upgrade.Value,
                dps = N9b and O9b or 0
            })
        end
    end
    local P9b = {
    }
    for Q9b, R9b in ipairs(Match.team or {
    }) do
        if R9b.hand then
            P9b [R9b.id] = true
        end
    end
    local S9b = {
    }
    for T9b, U9b in pairs(H9b) do
        table.sort(U9b, function(V9b, W9b)
            if V9b.dps ~= W9b.dps then
                return V9b.dps > W9b.dps
            end
            return V9b.lvl > W9b.lvl
        end)
        table.insert(S9b, {
            id = T9b,
            dps = U9b [1].dps * Match.airBoost(U9b [1].m) * Match.reach(U9b [1].m)
        })
    end
    table.sort(S9b, function(X9b, Y9b)
        return X9b.dps > Y9b.dps
    end)
    for Z9b = 1, math.min(3, # S9b) do
        Match.mergeIds [S9b [Z9b].id] = true
    end
    local _9b
    for aac, bac in pairs(H9b) do
        local cac = table.clone(bac)
        table.sort(cac, function(dac, eac)
            if dac.lvl ~= eac.lvl then
                return dac.lvl < eac.lvl
            end
            return dac.dps < eac.dps
        end)
        for fac, gac in ipairs(cac) do
            if gac.m == Match.freshM and fac > 1 then
                table.remove(cac, fac)
                table.insert(cac, 1, gac)
                break
            end
        end
        local hac, iac, jac, kac
        for lac, mac in ipairs(cac) do
            local nac, oac = Utils.flat(mac.m:GetPivot().Position), mac.m._stats.range.Value
            local pac, qac, rac = 0, 0, nil
            for sac, tac in ipairs(bac) do
                if tac ~= mac and (Utils.flat(tac.m:GetPivot().Position) - nac).Magnitude <= oac then
                    pac, qac = pac + tac.dps, qac + 1
                    if not rac or tac.dps > rac.dps then
                        rac = tac
                    end
                end
            end
            if qac > 0 then
                hac, iac, jac, kac = mac, pac, qac, rac
                break
            end
        end
        kac = kac or bac [1]
        local uac = kac.dps * Match.airBoost(kac.m) * Match.reach(kac.m) * (aac == Match.planId and 2 or 1)
        if (Match.mergeIds [aac] or aac == Match.planId) and (hac or P9b [aac]) and (not _9b or uac > _9b.score) then
            _9b = {
                id = aac,
                top = kac,
                fresh = hac,
                near = iac or 0,
                n = jac or 0,
                coming = P9b [aac],
                score = uac
            }
        end
    end
    Match.planId, Match.freshM = _9b and _9b.id, _9b and _9b.fresh and _9b.fresh.m
    Match.mergeHeldAt = (E9b and _9b and _9b.fresh) and (Match.mergeHeldAt or Match.wave()) or nil
    if not _9b then
        return App.status("Merge", "no second copy of a strong unit yet")
    end
    local vac, wac = Match.wave(), (Match.total or 30) - Match.wave()
    local xac = (Match.pressure or 0) >= math.min(Config.dangerReach, ((Match.depth and Match.depth.units > 0 and Match.depth.covEnd) or 1) * 0.9)
    local yac = _9b.fresh
    local zac = not xac and wac > 3
    _9b.waits = yac and yac.lvl <= _9b.top.lvl and _9b.top.lvl < _9b.top.max and zac or false
    local Aac = (not yac or yac.lvl >= _9b.top.lvl) and _9b.coming and zac
    local Bac = Match.cloneCard and _9b.top.lvl >= _9b.top.max and zac
    local Cac = yac and yac.lvl > _9b.top.lvl and _9b.near < 0.3 * yac.dps
    _9b.ready = E9b and yac ~= nil and not Cac and (not (_9b.waits or Aac or Bac) or vac - (Match.mergeHeldAt or vac) >= 5)
    Match.holdNoCardAt = (_9b.waits and not E9b) and (Match.holdNoCardAt or vac) or nil
    _9b.hold = _9b.waits and (E9b or vac - (Match.holdNoCardAt or vac) < 4)
    Match.mergePlan = _9b
    App.status("Merge", yac and string.format("%s: merge %d cop%s into the one with %d upgrades %s", Units.name(_9b.id), _9b.n, _9b.n == 1 and "y" or "ies", yac.lvl, _9b.ready and "now" or (E9b and "once the top copy is maxed" or "when a Merge card comes")) or string.format("%s: a second copy in the hand goes next to it", Units.name(_9b.id)))
end

function Match.mergeHold(Dac)
    local Eac = Match.mergePlan
    return Eac and Eac.hold and Eac.fresh and Eac.fresh.m == Dac or false
end

function Match.mergeBoost(Fac)
    local Gac = Match.mergePlan
    if not (Gac and Gac.top.m == Fac and (Gac.fresh or Gac.coming)) then
        return 1
    end
    return Match.mergeHeldAt and 2 or 1.3
end

function Match.mergeSpot(Hac)
    if not (Match.random and Match.mergeIds [Hac.id]) then
        return nil
    end
    local Iac, Jac
    for Kac, Lac in ipairs(Match.mine or {
    }) do
        if Lac._stats.id.Value == Hac.id then
            local Mac, Nac = pcall(Match.liveDps, Lac, Hac.id)
            Nac = Mac and Nac or 0
            if not Jac or Nac > Jac then
                Iac, Jac = Lac, Nac
            end
        end
    end
    return Iac and Iac:GetPivot().Position
end

function Match.mergeMeasure(Oac)
    local Pac = Match.mergeBefore
    if not Pac then
        return
    end
    task.delay(2, function()
        if not (Oac and Oac.Parent) then
            return
        end
        local Qac, Rac = pcall(Match.liveDps, Oac, Oac._stats.id.Value)
        if not Qac then
            return
        end
        local Sac = Pac.own + 1.5 * Pac.near
        local Tac = Brain.fh.merge or {
            n = 0,
            ratio = 0
        }
        if Sac > 0 then
            Tac.n, Tac.ratio = Tac.n + 1, Tac.ratio + Rac / Sac
        end
        Brain.fh.merge = Tac
        local Uac = Oac._stats.id.Value
        Brain.fh.noMerge = Brain.fh.noMerge or {
        }
        local Vac, Wac = Rac - Pac.own, 1.5 * Pac.near
        if Wac > 0 and Vac < 0.1 * Wac then
            Brain.fh.noMerge [Uac] = (Brain.fh.noMerge [Uac] or 0) + 1
        elseif Wac > 0 and Vac >= 0.5 * Wac then
            Brain.fh.noMerge [Uac] = nil
        end
        App.log(1, "SPELL", string.format("Merge result: %s went from %s to %s damage a second at %d upgrades (its own + 1.5× the copies' %s = %s expected; the top copy had %d)", Units.name(Oac._stats.id.Value), Utils.fmt(Pac.own), Utils.fmt(Rac), Pac.lvl, Utils.fmt(Pac.near), Utils.fmt(Sac), Pac.top))
    end)
end

function Match.farmMergeOk()
    local Xac = Brain.fh.farmMerge
    if not (Xac and Xac.n > 0) then
        return true
    end
    return Xac.ratio / Xac.n >= 0.8
end

function Match.farmMergePair()
    local Yac = {
    }
    for Zac, _ac in ipairs(Match.mine or {
    }) do
        local abc = _ac._stats.id.Value
        if Units.isFarm(abc) and _ac._stats:FindFirstChild("farm_amount") then
            Yac [abc] = Yac [abc] or {
            }
            table.insert(Yac [abc], _ac)
        end
    end
    for bbc, cbc in pairs(Yac) do
        if # cbc >= 2 then
            table.sort(cbc, function(dbc, ebc)
                return dbc._stats.upgrade.Value < ebc._stats.upgrade.Value
            end)
            for fbc, gbc in ipairs(cbc) do
                local hbc, ibc = Utils.flat(gbc:GetPivot().Position), gbc._stats.range.Value
                local jbc, kbc = 0, 0
                for lbc, mbc in ipairs(cbc) do
                    if mbc ~= gbc and (Utils.flat(mbc:GetPivot().Position) - hbc).Magnitude <= ibc then
                        jbc, kbc = jbc + (tonumber(mbc._stats.farm_amount.Value) or 0), kbc + 1
                    end
                end
                if kbc > 0 then
                    return gbc, jbc, kbc
                end
            end
        end
    end
end

function Match.farmMergeSpot(nbc)
    if not (Match.random and Match.farmMergeOk()) then
        return nil
    end
    for obc, pbc in ipairs(Match.mine or {
    }) do
        if pbc._stats.id.Value == nbc.id then
            return pbc:GetPivot().Position, tonumber(pbc._stats.range.Value) or 0
        end
    end
end

function Match.farmMergeMeasure(qbc)
    local rbc = Match.farmMergeBefore
    if not rbc then
        return
    end
    task.delay(2, function()
        if not (qbc and qbc.Parent) then
            return
        end
        local sbc = tonumber(qbc._stats.farm_amount.Value) or 0
        local tbc = rbc.own + 1.5 * rbc.inc
        local ubc = Brain.fh.farmMerge or {
            n = 0,
            ratio = 0
        }
        ubc.n, ubc.ratio = ubc.n + 1, ubc.ratio + (tbc > 0 and sbc / tbc or 0)
        Brain.fh.farmMerge = ubc
        App.log(1, "SPELL", string.format("Farm merge result: %s pays ¥%s a wave now (it paid ¥%s and took in farms paying ¥%s; keeping 1.5× would make ¥%s)", Units.name(qbc._stats.id.Value), Utils.fmt(sbc), Utils.fmt(rbc.own), Utils.fmt(rbc.inc), Utils.fmt(tbc)))
    end)
end
Match.IDOL_PRIOR = {
    dmg = 0.05,
    cost = 0.05
}

function Match.idolStep()
    local vbc = Brain.fh.idol
    local wbc, xbc = Match.IDOL_PRIOR.dmg, Match.IDOL_PRIOR.cost
    if vbc and vbc.n > 0 then
        wbc, xbc = vbc.dmg / vbc.n, vbc.cost / vbc.n
    end
    return math.max(0, wbc) + math.max(0, xbc) * 0.5
end

function Match.idolMeasure()
    local ybc
    for zbc, Abc in ipairs(Match.mine) do
        local Bbc = Abc._stats.id.Value
        local Cbc = Abc._stats:FindFirstChild("damage")
        if not Units.isFarm(Bbc) and not Units.idol(Bbc) and Cbc and Cbc.Value > 0 then
            ybc = Abc
            break
        end
    end
    if not ybc then
        return
    end
    local Dbc = ybc._stats
    local function Ebc()
        local Fbc, Gbc = pcall(Core.USC.calculate_upgrade_cost_multiplier, ybc, Core.session())
        local Hbc = Dbc:FindFirstChild("buff_damage_multiplier") and tonumber(Dbc.buff_damage_multiplier.Value) or 0
        return Dbc.damage.Value * (1 + Hbc), Fbc and tonumber(Gbc) or nil
    end
    local Ibc, Jbc = Ebc()
    local Kbc = Dbc.upgrade.Value
    task.delay(3, function()
        if not ybc.Parent or Dbc.upgrade.Value ~= Kbc then
            return
        end
        local Lbc, Mbc = Ebc()
        if not (Jbc and Mbc and Jbc > 0 and Ibc > 0) then
            return
        end
        if Lbc == Ibc and Mbc == Jbc then
            return App.log(2, "UPGRADE", "Idol upgrade: no change seen yet, not counted")
        end
        local Nbc = Brain.fh.idol or {
            n = 0,
            dmg = 0,
            cost = 0
        }
        Nbc.n, Nbc.dmg, Nbc.cost = Nbc.n + 1, Nbc.dmg + (Lbc / Ibc - 1), Nbc.cost + (1 - Mbc / Jbc)
        Brain.fh.idol = Nbc
        App.log(1, "UPGRADE", string.format("Idol upgrade measured on %s: %+.1f%% damage, upgrades %.1f%% cheaper", Units.name(Dbc.id.Value), (Lbc / Ibc - 1) * 100, (1 - Mbc / Jbc) * 100))
    end)
end

function Match.spells()
    local Obc = Core.session()
    local Pbc = Obc and Obc.ingame_spells
    if type(Pbc) ~= "table" or Match.spellBusy then
        return
    end
    local Qbc = Match.money()
    local Rbc = (Match.pressure or 0) >= math.min(Config.dangerReach, ((Match.depth and Match.depth.units > 0 and Match.depth.covEnd) or 1) * 0.9)
    local Sbc, Tbc, Ubc
    for Vbc, Wbc in ipairs(Match.mine) do
        local Xbc = Wbc._stats.id.Value
        if not Units.isFarm(Xbc) and not Units.allyBuff(Xbc) and Xbc ~= "mahoraga" then
            local Ybc, Zbc = pcall(Match.liveDps, Wbc, Xbc)
            local _bc = Ybc and Zbc and Zbc * Match.airBoost(Wbc) * Match.reach(Wbc)
            if _bc and (not Ubc or _bc > Ubc) then
                Sbc, Tbc, Ubc = Wbc, Zbc, _bc
            end
        end
    end
    local acc = Match.mergePlan
    local bcc = {
    }
    for ccc, dcc in pairs(Pbc) do
        table.insert(bcc, {
            slot = ccc,
            spell = dcc,
            rank = Match.SPELL_ORDER [dcc] or 9
        })
    end
    table.sort(bcc, function(ecc, fcc)
        return ecc.rank < fcc.rank
    end)
    Match.spellWant = nil
    Match.cloneNote = nil
    for gcc, hcc in ipairs(bcc) do
        local icc, jcc = hcc.slot, hcc.spell
        local kcc, lcc
        local mcc
        for ncc, occ in ipairs(Match.mine) do
            if occ._stats.id.Value == "mahoraga" then
                mcc = occ
            end
        end
        local pcc = mcc and (Match.buffCount [mcc] or 0) < 2
        if jcc == "random_buff" and Qbc >= 1000 and (pcc or Sbc) then
            if pcc then
                kcc, lcc = mcc, "the Divine General (two buffs make it a boss killer; its range is only 8.5)"
            else
                kcc, lcc = Sbc, "+100% attack or range on your strongest unit"
            end
        elseif jcc == "sacrifice" and acc and acc.ready then
            if Qbc >= 1000 then
                kcc, lcc = acc.fresh.m, string.format("the %d other cop%s in its range (it keeps 1.5× their damage through its own upgrades)", acc.n, acc.n == 1 and "y" or "ies")
                Match.mergeBefore = {
                    own = acc.fresh.dps,
                    near = acc.near,
                    lvl = acc.fresh.lvl,
                    top = acc.top.lvl
                }
            else
                Match.spellWant = Match.spellWant or {
                    cost = 1000,
                    why = "Merge on " .. Units.name(acc.id)
                }
            end
        elseif jcc == "sacrifice" and Qbc >= 1000 and not Rbc and not (acc and acc.fresh) and Match.farmMergeOk() and Match.farmMergePair() then
            local qcc, rcc, scc = Match.farmMergePair()
            kcc = qcc
            lcc = string.format("the %d other %s in its reach (does a farm keep their income?)", scc, Units.name(qcc._stats.id.Value))
            Match.farmMergeBefore = {
                own = tonumber(qcc._stats.farm_amount.Value) or 0,
                inc = rcc
            }
        elseif jcc == "clone" then
            local tcc = not Rbc and acc and acc.fresh and acc.top.lvl < acc.top.max
            Match.cloneWaitAt = tcc and (Match.cloneWaitAt or Match.wave()) or nil
            local ucc = tcc and Match.wave() - Match.cloneWaitAt < 5
            local vcc, wcc
            if not Rbc and acc and acc.fresh and acc.top.lvl >= acc.top.max then
                vcc, wcc = acc.top.m, "a maxed copy for the Merge to take in"
            elseif not ucc and Sbc then
                vcc, wcc = Sbc, Rbc and "a copy of your strongest unit: instant damage with enemies near the base" or "a copy of your strongest unit (two copies make a Merge)"
            end
            if ucc then
                Match.cloneNote = string.format("waits for %s to max (%d/%d, up to %d more waves)", Units.name(acc.id), acc.top.lvl, acc.top.max, 5 - (Match.wave() - Match.cloneWaitAt))
            end
            if vcc and Qbc >= 5000 then
                kcc, lcc = vcc, wcc
            elseif vcc then
                local xcc, ycc = pcall(Match.liveDps, vcc, vcc._stats.id.Value)
                ycc = xcc and tonumber(ycc) or 0
                if ycc >= (Match.bestRate or 0) * 5000 * 0.5 then
                    Match.spellWant = Match.spellWant or {
                        cost = 5000,
                        why = "Clone of " .. Units.name(vcc._stats.id.Value),
                        rate = ycc / 5000
                    }
                    Match.cloneNote = "saving for a copy of " .. Units.name(vcc._stats.id.Value)
                else
                    Match.cloneNote = string.format("a copy of %s (%s dps) is worth less than ¥5k of upgrades (%s)", Units.name(vcc._stats.id.Value), Utils.fmt(ycc), Utils.fmt((Match.bestRate or 0) * 5000))
                end
            end
        elseif jcc == "ritual" and not Rbc and Match.wave() >= 8 and not Match.hasGeneral() then
            local zcc, Acc = Match.ritualTarget()
            if zcc and Qbc >= 10000 then
                kcc, lcc = zcc, Acc
            elseif zcc then
                Match.spellWant = Match.spellWant or {
                    cost = 10000,
                    why = "a Ritual (" .. Acc .. ")"
                }
            end
        elseif jcc == "summon" and Qbc >= 10000 and not Rbc and Match.summonWorth() then
            kcc, lcc = false, "a unit from your own team"
        elseif jcc == "gate" and Qbc >= 2500 and not Rbc and Match.summonWorth() then
            kcc, lcc = false, "3× the odds of Astral Summon"
        end
        if lcc then
            Match.spellBusy = true
            local Bcc = {
            }
            for Ccc, Dcc in ipairs(workspace._UNITS:GetChildren()) do
                Bcc [Dcc] = true
            end
            local Ecc
            if kcc then
                local Fcc = kcc._stats
                local Gcc, Hcc = pcall(Match.liveDps, kcc, Fcc.id.Value)
                Ecc = {
                    id = Fcc.id.Value,
                    pos = kcc:GetPivot().Position,
                    dps = Gcc and tonumber(Hcc) or 0,
                    lvl = Fcc.upgrade.Value,
                    spent = Fcc:FindFirstChild("total_spent") and tonumber(Fcc.total_spent.Value) or 0
                }
            end
            task.spawn(function()
                local Icc
                if kcc then
                    Icc = App.request("spell", "use_ingame_spell", icc, kcc)
                else
                    Icc = App.request("spell", "use_ingame_spell", icc)
                end
                task.wait(1.5)
                local Jcc = kcc and Units.name(kcc._stats.id.Value) or ""
                if Icc and (Core.session().ingame_spells or {
                }) [icc] ~= jcc then
                    App.log(1, "SPELL", string.format("%s%s — %s", Match.SPELL_NAMES [jcc] or tostring(jcc), kcc and (" on " .. Jcc) or "", lcc))
                    App.status("Abilities", string.format("spell %s%s — %s", Match.SPELL_NAMES [jcc] or tostring(jcc), kcc and (" on " .. Jcc) or "", lcc))
                    if jcc == "sacrifice" then
                        if Ecc and Units.isFarm(Ecc.id) then
                            pcall(Match.farmMergeMeasure, kcc)
                        else
                            pcall(Match.mergeMeasure, kcc)
                        end
                    end
                    if jcc == "random_buff" and kcc then
                        Match.buffCount [kcc] = (Match.buffCount [kcc] or 0) + 1
                    end
                    if (jcc == "clone" or jcc == "ritual") and Ecc then
                        pcall(Match.newUnitMeasure, jcc, kcc, Jcc, Ecc, Bcc)
                    end
                else
                    App.backoff("spell", 15)
                    App.log(2, "SPELL", tostring(jcc) .. " wasn't taken" .. (kcc and (" on " .. Jcc) or ""))
                end
                Match.spellBusy = false
            end)
            return
        end
    end
end

function Match.trainCount()
    local Kcc = Brain.train.on
    if not (Kcc and Match.trainee) then
        return
    end
    local Lcc = 0
    for Mcc, Ncc in ipairs(Match.mine) do
        local Occ = Ncc._stats
        local Pcc = Occ:FindFirstChild("uuid") and Occ.uuid.Value
        local Qcc = Pcc == Match.trainee and Occ:FindFirstChild(Kcc.what == "kills" and "kill_count" or "takedown_count")
        if Qcc then
            Lcc = Lcc + (tonumber(Qcc.Value) or 0)
        end
    end
    Match.trainTk = math.max(Match.trainTk or 0, Lcc)
    App.status("Training", string.format("%s: %d %s this match · %s/%s", Units.name(Kcc.id), Match.trainTk, Kcc.what, Utils.fmt(Kcc.have + (Kcc.got or 0) + Match.trainTk), Utils.fmt(Kcc.need)))
end

function Match.trainDone(Rcc, Scc)
    local Tcc = Brain.train.on
    if not (Tcc and Match.trainee) then
        return
    end
    Match.trainCount()
    local Ucc = Match.trainTk or 0
    Tcc.got = (Tcc.got or 0) + Ucc
    local Vcc = Brain.trainSim [Rcc] and tonumber(Brain.trainSim [Rcc].tk)
    if not Match.joinedMid then
        local Wcc = Brain.train.real [Rcc] or {
            n = 0,
            sum = 0
        }
        Wcc.n, Wcc.sum = Wcc.n + 1, Wcc.sum + Ucc
        Brain.train.real [Rcc] = Wcc
        if Vcc and Vcc > 0 then
            local Xcc = Brain.train.cal
            Xcc.real, Xcc.sim, Xcc.n = (Xcc.real or 0) + Ucc, (Xcc.sim or 0) + Vcc, (Xcc.n or 0) + 1
        end
    end
    table.insert(Brain.train.log, 1, {
        key = Rcc,
        got = Ucc,
        won = Scc,
        at = os.time()
    })
    while # Brain.train.log > 20 do
        table.remove(Brain.train.log)
    end
    App.log(1, "TRAIN", string.format("%s: +%d %s this run (%s%s) · %s/%s", Units.name(Tcc.id), Ucc, Tcc.what, Scc and "won" or "lost", Vcc and string.format(", the simulator said ≈%d", Vcc) or "", Utils.fmt(Training.realHave(Tcc)), Utils.fmt(Tcc.need)))
    if not Scc then
        Brain.train.bad [Rcc] = os.time() + 6 * 3600
        App.log(1, "TRAIN", "the training team lost here: no training in this mode for 6 h")
    end
end

function Match.finish()
    if Match.finished then
        return
    end
    Match.finished = true
    local Ycc
    local Zcc = Utils.now()
    while Utils.now() - Zcc < 8 do
        Ycc = Match.result or (Core.GUIS.results_ui and Core.GUIS.results_ui.settings)
        if Ycc then
            break
        end
        task.wait(0.25)
    end
    local _cc = Ycc and Ycc.victory or false
    local adc = Match.infinite and Match.wave() or nil
    if adc then
        _cc = true
    end
    local bdc = Match.key
    local cdc = Modes.rec(bdc)
    if adc and not Match.joinedMid and not Match.stopping then
        cdc.waveSum, cdc.waveN = (tonumber(cdc.waveSum) or 0) + adc, (tonumber(cdc.waveN) or 0) + 1
        cdc.waveBest = math.max(tonumber(cdc.waveBest) or 0, adc)
    end
    if adc and (tonumber(Brain.infResults) or 0) < 3 and type(Ycc) == "table" then
        Brain.infResults = (tonumber(Brain.infResults) or 0) + 1
        local ddc = {
        }
        for edc, fdc in pairs(Ycc) do
            table.insert(ddc, type(fdc) == "table" and (edc .. "{…}") or (edc .. "=" .. tostring(fdc)))
        end
        table.sort(ddc)
        App.log(1, "MATCH", "Infinite result fields: " .. table.concat(ddc, ", "))
    end
    local gdc = Ycc and Ycc.stats and tonumber(Ycc.stats.time_taken) or (os.clock() - (Match.startClock or os.clock()))
    local hdc = Ycc and ((tonumber(Ycc.gem_reward) or 0) + (tonumber(Ycc.first_completion_gems) or 0)) or 0
    local idc = Core.GS.CURRENT_EVENT_RESOURCE or "AprilCoins"
    local jdc = Ycc and Ycc.resource_reward and tonumber(Ycc.resource_reward [idc]) or 0
    if not Match.joinedMid then
        cdc.runs = cdc.runs + 1
        if _cc then
            cdc.wins = cdc.wins + 1
            cdc.streak = 0
        elseif Match.kind == "event" and jdc > 0 then
            cdc.streak = 0
        else
            cdc.streak = (cdc.streak or 0) + 1
        end
        cdc.sec = cdc.sec + gdc
        cdc.timed = (tonumber(cdc.timed) or 0) + 1
    end
    if _cc then
        if Match.ld._gamemode == "story" or Match.kind == "raid" then
            Brain.cleared [Match.ld.id .. ":" .. tostring(Match.ld._difficulty or "Normal")] = os.time()
        end
        if bdc == "ch" and Brain.live.normal then
            Brain.live.normal.doneUuid = Brain.live.normal.uuid
        end
        if bdc == "dc" and Brain.live.daily then
            Brain.live.daily.doneUuid = Brain.live.daily.uuid
        end
    end
    for kdc, ldc in pairs(Brain.cleared) do
        if os.time() - ldc > 86400 then
            Brain.cleared [kdc] = nil
        end
    end
    cdc.gems = cdc.gems + hdc
    cdc.coins = cdc.coins + jdc
    cdc.last = os.time()
    local mdc = (cdc.streak or 0) >= Config.restAfterLosses and Match.kind ~= "dungeon" and Match.kind ~= "portal" and not Match.trialId and not (Config.dailyLoop and bdc == "dc")
    if mdc then
        cdc.restUntil, cdc.restWhy = os.time() + 6 * 3600, "losses"
        App.log(1, "MODE", Match.label() .. ": lost " .. cdc.streak .. " in a row — resting it for 6 h")
    end
    if not _cc and (bdc == "ch" or bdc == "dc") then
        local ndc = bdc == "ch" and Brain.live.normal or Brain.live.daily
        if ndc then
            ndc.lost = (ndc.lost or 0) + 1
        end
    end
    Brain.totals.matches = (Brain.totals.matches or 0) + 1
    if not Match.joinedMid then
        if _cc then
            Brain.totals.wins = Brain.totals.wins + 1
        else
            Brain.totals.losses = Brain.totals.losses + 1
        end
    end
    Brain.totals.gems = (Brain.totals.gems or 0) + hdc
    Brain.totals.coins = (Brain.totals.coins or 0) + jdc
    local odc = {
    }
    for pdc, qdc in pairs(Ycc and Ycc.new_items or {
    }) do
        local rdc = type(qdc) == "table" and (qdc.item_id or qdc.id) or tostring(qdc)
        odc [rdc] = (odc [rdc] or 0) + (type(qdc) == "table" and tonumber(qdc.amount) or 1)
    end
    local sdc = Match.label()
    if Match.kind == "dungeon" and not Match.joinedMid then
        local tdc, udc = pcall(Dungeon.roomDone, _cc)
        if not tdc then
            App.log(1, "ERROR", "dungeon: " .. tostring(udc))
        end
    end
    if not Match.joinedMid and not Match.random and not Match.stopping and not Match.trialId then
        pcall(Match.spotResult, _cc)
    end
    Brain.lastResult = {
        won = _cc,
        text = string.format("%s · %s · wave %s · %dm%02ds",
        sdc,
        _cc and "won" or "lost",
        tostring(Ycc and Ycc.stats and Ycc.stats.waves_completed or Match.wave()),
        math.floor(gdc / 60),
        math.floor(gdc % 60)),
        gems = hdc,
        coins = jdc,
        items = odc,
        at = os.time()
    }
    table.insert(Brain.history, 1, {
        key = bdc,
        won = _cc,
        sec = gdc,
        gems = hdc,
        coins = jdc,
        at = os.time()
    })
    while # Brain.history > 30 do
        table.remove(Brain.history)
    end
    Brain.lastMatch = {
        label = sdc,
        spent = Match.spent,
        actions = # Match.actions,
        refusals = Match.refusals or 0,
        at = os.time()
    }
    if not Match.trialId then
        pcall(Match.learn)
    end
    local vdc, wdc = pcall(Match.trainDone, bdc, _cc)
    if not vdc then
        App.log(1, "ERROR", "training: " .. tostring(wdc))
    end
    local xdc, ydc = true, nil
    if Match.hunt then
        local zdc, Adc = pcall(Match.huntRecord, Ycc, jdc, _cc, gdc)
        if not zdc then
            App.log(1, "ERROR", "hunt record: " .. tostring(Adc))
        end
    end
    if Match.random then
        pcall(Match.fhRecord, jdc, _cc)
    elseif not Match.stopping and not Match.trialId then
        xdc, ydc = pcall(Match.calMerge, _cc)
    end
    if not xdc then
        App.log(1, "ERROR", "sim calibration: " .. tostring(ydc))
    end
    Reports.record({
        mode = bdc,
        won = _cc,
        sec = math.floor(gdc),
        wave = Match.wave(),
        gems = hdc,
        coins = jdc,
        mid = Match.joinedMid or nil
    })
    App.log(1, "RESULT", string.format("%s — %s, +%d gems%s, ¥%s spent, %d refused spots", sdc, adc and ("reached wave " .. adc) or (_cc and "WON" or "LOST"), hdc, jdc > 0 and (", +" .. jdc .. " " .. idc) or "", Utils.fmt(Match.spent), Match.refusals or 0))
    if Brain.watch and Brain.watch.key == bdc then
        Brain.watch.won = _cc and true or false
        App.saveNow()
    end
    local Bdc = Brain.testTeam
    local Cdc = Bdc and (Bdc.left or 0) > 0 and Bdc.key == bdc and type(Bdc.uuids) == "table" and Training.same(Training.team(), Bdc.uuids)
    if Bdc and (Bdc.left or 0) > 0 and Bdc.key == bdc then
        Bdc.left = Bdc.left - 1
        Bdc.runs = Bdc.runs or {
        }
        local Ddc = Match.damageLine() or ""
        table.insert(Bdc.runs, {
            won = _cc,
            wave = Match.wave(),
            sec = gdc,
            at = os.time(),
            dmg = Ddc,
            other = not Cdc or nil
        })
        App.log(1, "TEST", string.format("%s: run %d of %d %s at wave %d in %.1f min%s · %s", tostring(Bdc.label), # Bdc.runs, tonumber(Bdc.n) or # Bdc.runs, _cc and "WON" or "LOST", Match.wave(), (tonumber(gdc) or 0) / 60, Cdc and "" or " (the test team wasn't on: not counted)", Ddc))
        if Bdc.left <= 0 then
            App.log(1, "TEST", tostring(Bdc.label) .. ": done, the usual team picking is back")
        end
        App.saveSoon()
    end
    pcall(function()
        if Cdc then
            return
        end
        local Edc = Modes.rec(bdc)
        if _cc and not adc then
            local Fdc = {
            }
            for Gdc, Hdc in ipairs(Units.equipped()) do
                table.insert(Fdc, Hdc.uuid)
            end
            table.sort(Fdc)
            local Idc = table.concat(Fdc, ",")
            local function Jdc(Kdc)
                local Ldc, Mdc = Core.session(), 0
                for Ndc, Odc in ipairs(Kdc or {
                }) do
                    local Pdc = Ldc.collection:get_unit_by_uuid(Odc)
                    local Qdc, Rdc = pcall(Units.score, Pdc or {
                    })
                    Mdc = Mdc + (Qdc and Rdc or 0)
                end
                return Mdc
            end
            if # Fdc > 0 then
                if Edc.winSig == Idc then
                    Edc.winTeamN = (tonumber(Edc.winTeamN) or 0) + 1
                elseif not Edc.winTeam or Jdc(Fdc) >= Jdc(Edc.winTeam) then
                    Edc.winTeam, Edc.winSig, Edc.winTeamN = Fdc, Idc, 1
                end
            end
        elseif not _cc then
            Edc.winTeam, Edc.winSig, Edc.winTeamN = nil, nil, nil
        end
    end)
    local Sdc, Tdc = pcall(Reports.match, {
        key = bdc,
        won = _cc,
        sec = gdc,
        gems = hdc,
        coins = jdc,
        items = odc
    })
    if not Sdc then
        App.log(1, "ERROR", "local learning: " .. tostring(Tdc))
    end
    if Match.kind == "portal" then
        pcall(function()
            local Udc = {
            }
            for Vdc, Wdc in ipairs(Units.equipped()) do
                table.insert(Udc, Units.name(Wdc.id))
            end
            local Xdc = Match.pred
            FarmHub.portalLine(string.format("%s · %s at wave %d of %d · predicted %s · team: %s · style %s · modifiers: %s · %s", os.date("%m-%d %H:%M"), _cc and "WON" or "LOST", Match.wave(), Match.total or 0, Xdc and ((Xdc.won and "a win at " or "a loss at ") .. tostring(Xdc.wave)) or "nothing", table.concat(Udc, ", "), tostring(Match.style), tostring(Brain.portalMods or "?"):sub(1, 300), tostring(Match.damageLine() or "")))
        end)
    end
    for Ydc, Zdc in pairs(Match.buffSeen) do
        local _dc = 0
        for aec, bec in ipairs(Zdc.levels) do
            _dc = math.max(_dc, bec)
        end
        App.log(1, "BUFF", string.format("%s cast %d times: your units read %s%% after the casts (highest +%d%%)", Units.name(Ydc), Zdc.casts, table.concat(Zdc.levels, ", "), _dc))
        local cec = Units.allyBuff(Ydc)
        if cec and cec.attack then
            local dec = 0
            for eec, fec in pairs(cec.types or {
            }) do
                dec = math.max(dec, tonumber(fec) or 0)
            end
            local gec = Brain.stack [cec.attack]
            if dec > 0 and _dc / 100 > dec + 0.05 and not (gec and gec.stacks and (tonumber(gec.cap) or 0) >= _dc / 100) then
                Brain.stack [cec.attack] = {
                    stacks = true,
                    cap = math.max(gec and gec.stacks and tonumber(gec.cap) or 0,
                    _dc / 100),
                    before = dec,
                    after = _dc / 100,
                    at = os.time(),
                    seen = true
                }
                App.log(1, "BUFF", string.format("%s's buffs stack: +%d%% with one, +%d%% seen with more. Copies now chain up to that", Units.name(Ydc), math.floor(dec * 100 + 0.5), _dc))
            end
        end
    end
    local hec, iec = pcall(Match.damageLine)
    if hec and iec then
        App.log(1, "DAMAGE", iec)
    end
    if not Match.random then
        local jec, kec, lec = pcall(Match.damageShares)
        if jec and kec and not Match.trialId then
            pcall(Strategy.learn, kec, Match.team)
        end
        local mec, nec = pcall(Match.summonSplit)
        if mec and nec and jec and (lec or 0) > 0 then
            Brain.str.summon = type(Brain.str.summon) == "table" and Brain.str.summon or {
            }
            for oec, pec in pairs(nec) do
                if pec.total >= 0.01 * lec then
                    local qec = Brain.str.summon [oec]
                    local tec = (type(qec) == "table" and tonumber(qec.n) or 0) + 1
                    local uec = math.max(0.2, 1 / tec)
                    Brain.str.summon [oec] = {
                        s = type(qec) == "table" and (qec.s + (pec.share - qec.s) * uec) or pec.share,
                        n = tec
                    }
                end
            end
        end
        Brain.lastRun = {
            key = bdc,
            at = os.time(),
            xp0 = Match.xp0
        }
    end
    if Match.trialId then
        local vec, wec = pcall(Match.trialDone, _cc, gdc)
        if not vec then
            App.log(1, "ERROR", "trial: " .. tostring(wec))
            Brain.trial = nil
        end
    end
    local xec
    if _cc and Match.ld._is_actual_storymode then
        local yec, zec = pcall(Core.PSC.get_next_story_level, Match.ld.id)
        if yec and zec then
            xec = zec
            local Aec = Utils.now()
            while App.alive and Utils.now() - Aec < 2 do
                if Modes.open(zec) then
                    break
                end
                task.wait(0.5)
            end
        end
    end
    local Bec = nil
    pcall(function()
        Bec = Modes.pick()
    end)
    if Bec and Bec.kind == "story" and Bec.first and xec and Bec.level ~= xec and not Brain.nextMode then
        for Cec, Dec in ipairs(Modes.lastScored or {
        }) do
            if Dec.kind == "story" and Dec.first and Dec.level == xec and Dec.diff == Match.ld._difficulty and (Dec.baseScore or Dec.score or 0) >= (Bec.baseScore or Bec.score or 0) * Modes.CHAIN_MIN then
                Bec = Dec
                break
            end
        end
    end
    if not Bec and xec and Config.onlyStory and (Config.pickStory == "" or Config.pickStory == "progress") and Match.ld._difficulty == "Normal" and not Modes.done((Core.prof() or {
    }).level_data or {
    }, xec, "Normal") then
        local Eec = "st:" .. xec .. ":Normal"
        Bec = {
            key = Eec,
            kind = "story",
            first = true,
            level = xec,
            diff = "Normal",
            label = Modes.levelName(xec) .. " (Normal)",
            rec = Modes.rec(Eec)
        }
    end
    local Fec, Gec = "lobby", "back to the lobby"
    local Hec = (Match.ld._gamemode == "story" or Match.ld._gamemode == "infinite" or (Match.kind == "event" and Match.ld._OVERRIDE_CAN_REPLAY)) and _cc
    if not Config.play or not Config.master then
        Fec, Gec = "stay", "Auto Play is off"
    elseif Bec and Bec.key == bdc and Hec then
        Fec, Gec = "replay", "replaying: still the best mode"
    elseif Bec and Bec.kind == "story" and Match.ld._is_actual_storymode and _cc then
        local Iec, Jec = pcall(Core.PSC.get_next_story_level, Match.ld.id)
        if Iec and Jec == Bec.level and Bec.diff == Match.ld._difficulty then
            Fec, Gec = "next_story", "next act: " .. Bec.label
        end
    end
    if Fec ~= "replay" and Fec ~= "next_story" and Bec then
        Gec = "lobby for: " .. Bec.label
    end
    local Kec = Brain.train.on
    if Kec and Match.trainee and (Fec == "replay" or Fec == "next_story") and Training.realHave(Kec) >= Kec.need then
        Fec, Gec = "lobby", "lobby: " .. Units.name(Kec.id) .. " has its " .. tostring(Kec.what) .. ", your own team goes back in"
    end
    if Brain.holdLobby and Fec ~= "stay" then
        Fec, Gec = "lobby", "lobby: held there: " .. tostring(Brain.holdLobby.why)
    end
    if (Fec == "replay" or Fec == "next_story") and Bec then
        local Lec, Mec = pcall(FarmHub.matchOn, Bec)
        if Lec and Mec then
            Fec, Gec = "lobby", "lobby: matchmaking again for " .. tostring(Bec.label)
        end
    end
    if (Fec == "replay" or Fec == "next_story") and Config.smartCharm and Bec then
        local Nec, Oec = pcall(Hunt.charmWant, Bec)
        if Nec and Oec then
            Fec, Gec = "lobby", "lobby: putting on the Summer Charm (" .. Hunt.charmWords(Oec) .. ")"
        end
    end
    if Match.trialId and Fec ~= "stay" then
        Fec, Gec = "lobby", Brain.trial and "lobby: the next trial run" or "lobby: your own team goes back in"
    end
    if Brain.buyStorage and Fec ~= "stay" then
        Fec, Gec = "lobby", "lobby: buying the unit storage you agreed"
    end
    if Brain.buyOnce and Fec ~= "stay" then
        Fec, Gec = "lobby", "lobby: buying the " .. tostring((Core.Items [Brain.buyOnce.item] or {
        }).name or Brain.buyOnce.item) .. " you agreed"
    end
    local Pec
    if ((Match.kind == "dungeon" and _cc) or Fec == "next_story" or Fec == "replay") and Fec ~= "stay" then
        local Qec, Rec = pcall(Strategy.hasWork)
        if Qec then
            Pec = Rec
        else
            App.log(1, "ERROR", "team work: " .. tostring(Rec))
        end
        if Pec then
            Fec, Gec = "lobby", "lobby: the Units → Upgrades can " .. tostring(Pec)
        end
    end
    if Match.kind == "dungeon" and Fec ~= "stay" and Bec and Bec.key == "dg" and _cc and # Units.equipped() >= 6 and not Brain.holdLobby and not Brain.buyStorage and not Pec then
        Brain.pending = nil
        App.saveNow()
        App.status("Match", "next dungeon room")
        local Sec, Tec = pcall(Dungeon.chain)
        if not Sec then
            App.log(1, "ERROR", "dungeon next room: " .. tostring(Tec))
        end
        if Sec and Tec then
            return
        end
        Brain.startTeam = nil
        Fec, Gec = "lobby", "lobby: the next dungeon room didn't start from here"
    end
    Brain.pending = (Fec == "replay" or Fec == "next_story") and {
        key = Bec.key,
        kind = Bec.kind,
        level = Bec.level,
        diff = Bec.diff,
        label = Bec.label,
        at = os.time()
    } or nil
    if Fec == "next_story" or Fec == "replay" then
        Brain.startTeam = {
            train = {
                key = Bec.key,
                kind = Bec.kind,
                first = Bec.first,
                level = Bec.level,
                diff = Bec.diff,
                label = Bec.label
            },
            why = (Fec == "replay" and "replay: " or "next act: ") .. tostring(Bec.label)
        }
    end
    App.saveNow()
    App.status("Match", Gec)
    App.log(1, "MODE", Gec)
    if Fec == "stay" then
        return
    end
    task.wait(2.5)
    if Fec == "replay" or Fec == "next_story" then
        local Uec = ReplicatedStorage.endpoints.server_to_client
        local Vec, Wec = false, false
        local Xec = Uec.match_rematch_started.OnClientEvent:Connect(function()
            Vec = true
        end)
        local Yec = Uec.match_rematch_ready.OnClientEvent:Connect(function()
            Wec = true
        end)
        table.insert(App.conns, Xec)
        table.insert(App.conns, Yec)
        App.request("vote", "set_game_finished_vote", Fec)
        local Zec = Utils.now()
        while App.alive and Utils.now() - Zec < 30 and not Vec do
            task.wait(0.25)
        end
        if Vec then
            local _ec = Utils.now()
            while App.alive and Utils.now() - _ec < 60 and not Wec do
                task.wait(0.25)
            end
            if App.alive then
                App.log(1, "MODE", string.format("the match restarted in place in %.0f s (%s)", Utils.now() - Zec, Fec))
                local afc, bfc = pcall(App.restart)
                if afc then
                    return
                end
                App.log(1, "ERROR", "couldn't start again in place: " .. tostring(bfc))
            else
                return
            end
        end
    end
    if App.alive then
        App.request("lobby", "teleport_back_to_lobby")
    end
end

function Match.watchMods()
    local cfc = workspace:FindFirstChild("ignore")
    if not cfc then
        return
    end
    local dfc = {
    }
    local efc, ffc = - 9, false
    local Jfc = cfc.ChildAdded:Connect(function(gfc)
        task.defer(function()
            local hfc = gfc:FindFirstChild("Gui")
            if not (hfc and gfc:IsA("BasePart")) then
                return
            end
            local ifc, jfc
            for kfc, lfc in ipairs(workspace._UNITS:GetChildren()) do
                local mfc = lfc:FindFirstChild("HumanoidRootPart")
                if mfc then
                    local nfc = (mfc.Position - gfc.Position).Magnitude
                    if nfc < 4 and (not jfc or nfc < jfc) then
                        ifc, jfc = lfc, nfc
                    end
                end
            end
            local ofc = ifc and ifc:FindFirstChild("_stats")
            if not (ofc and ofc:FindFirstChild("Armor")) then
                return
            end
            local pfc = ofc:FindFirstChild("player")
            if pfc and pfc.Value ~= nil then
                return
            end
            local qfc = {
            }
            for rfc, sfc in ipairs({
                "Armor",
                "Ice",
                "Flying",
                "Soaring"
            }) do
                local tfc = ofc:FindFirstChild(sfc)
                qfc [sfc] = tfc and (tonumber(tfc.Value) or 0) > 0
            end
            if qfc.Flying or qfc.Soaring then
                return
            end
            local ufc = (qfc.Armor and not qfc.Ice and "Armor") or (qfc.Ice and not qfc.Armor and "Ice") or ((not qfc.Armor and not qfc.Ice) and "plain") or nil
            if not ufc then
                return
            end
            if ufc == "Ice" then
                if os.clock() - efc > 2 then
                    efc, ffc = os.clock(), Hunt.is(Match.ld and Match.ld.id) and Hunt.weatherNow() == "snow"
                end
                if ffc then
                    ufc = "Ice@snow"
                end
            end
            local vfc = os.clock()
            for wfc, xfc in ipairs(hfc:GetChildren()) do
                local yfc = tonumber(xfc:GetAttribute("final_damage"))
                if yfc and yfc > 1 then
                    local zfc, Afc = false, xfc:FindFirstChild("text")
                    for Bfc, Cfc in ipairs(Afc and Afc:GetChildren() or {
                    }) do
                        if Cfc:IsA("ImageLabel") then
                            zfc = true
                        end
                    end
                    local Dfc = xfc.Name
                    local Efc = {
                        at = vfc,
                        t = Dfc,
                        dmg = yfc,
                        crit = xfc:GetAttribute("is_crit") and true or false,
                        kind = ufc,
                        icon = zfc,
                        res = tonumber(ofc:GetAttribute("_dmg_res_" .. Dfc)) or 0,
                        weak = (tonumber(ofc:GetAttribute("_dmg_weak_" .. Dfc)) or 0) + (tonumber(ofc:GetAttribute("_dmg_amp_" .. Dfc)) or 0)
                    }
                    if not (ufc ~= "Armor" and ufc ~= "plain" and Dfc:find("fire")) then
                        for Ffc, Gfc in ipairs(dfc) do
                            if vfc - Gfc.at < 0.05 and Gfc.t == Dfc and Gfc.crit == Efc.crit and Gfc.res == Efc.res and Gfc.weak == Efc.weak then
                                local Hfc = (Efc.kind ~= "plain" and Efc.icon and Efc) or (Gfc.kind ~= "plain" and Gfc.icon and Gfc) or nil
                                local Ifc = (Efc.kind == "plain" and not Efc.icon and Efc) or (Gfc.kind == "plain" and not Gfc.icon and Gfc) or nil
                                if Hfc and Ifc then
                                    Match.modPair(Hfc.kind, Hfc.dmg / Ifc.dmg)
                                end
                            end
                        end
                    end
                    table.insert(dfc, Efc)
                end
            end
            while dfc [1] and vfc - dfc [1].at > 0.2 do
                table.remove(dfc, 1)
            end
        end)
    end)
    table.insert(App.conns, Jfc)
end

function Match.modPair(Kfc, Lfc)
    if Lfc <= 0.02 or Lfc >= 1.2 then
        return
    end
    local Mfc = Brain.enemyMods [Kfc] or {
        r = {
        }
    }
    Brain.enemyMods [Kfc] = Mfc
    table.insert(Mfc.r, Lfc)
    while # Mfc.r > 80 do
        table.remove(Mfc.r, 1)
    end
    local Nfc = Simulator.modRead(Mfc)
    local Ofc = Mfc.said and Nfc and math.abs(Nfc - Mfc.said) <= Mfc.said * 0.1
    if Nfc and not Ofc then
        Mfc.said = Nfc
    end
    local Pfc, Qfc = Kfc == "Armor" and "Armored" or (Kfc == "Ice@snow" and "Ice (Blizzard)" or "Ice"), Kfc == "Armor" and "from full-area attacks" or "from everything but fire"
    if Nfc and not Ofc then
        App.log(1, "MATCH", string.format("%s enemies measured from %d real hits: they take ×%.2f %s", Pfc, # Mfc.r, Nfc, Qfc))
    end
    if Nfc == false and not Mfc.saidLoose then
        Mfc.saidLoose = true
        local Rfc = table.clone(Mfc.r)
        table.sort(Rfc)
        App.log(1, "MATCH", string.format("%s enemies: %d real hits so far disagree (×%.2f to ×%.2f), so the simulator doesn't count them until they agree", Pfc, # Rfc, Rfc [1], Rfc [# Rfc]))
    end
end

function Match.startTeam()
    local Sfc = Brain.startTeam
    if type(Sfc) ~= "table" then
        return
    end
    Brain.startTeam = nil
    App.saveSoon()
    App.listenGame()
    if Sfc.train and Sfc.train.key ~= Match.key then
        return
    end
    if Sfc.seed and tostring(Brain.dg.room and Brain.dg.room.seed) ~= tostring(Sfc.seed) then
        return
    end
    local function Tfc(Ufc)
        Match.noBuy = true
        Brain.pending = nil
        App.log(1, "TEAM", string.format("%s: no wave started, back to the lobby (%s)", tostring(Ufc), tostring(Sfc.why)))
        App.saveNow()
        for Vfc = 1, 3 do
            App.request("lobby", "teleport_back_to_lobby")
            local Wfc = Utils.now()
            while App.alive and Utils.now() - Wfc < 5 do
                task.wait(0.5)
            end
        end
    end
    if workspace._DATA.GameStarted.Value then
        App.log(1, "TEAM", "too late for a team change before the first wave: " .. tostring(Sfc.why))
        if Sfc.must and not Training.same(Training.team(), Sfc.uuids) then
            Tfc("the first wave had already started")
        end
        return
    end
    local Xfc = Utils.now()
    local Yfc = Training.team()
    local Zfc, _fc = pcall(function()
        if Sfc.train then
            Sfc.train.rec = Modes.rec(Sfc.train.key)
            Sfc.train.ldOverride = Simulator.slim(Match.ld)
            if Config.autoTeam then
                FarmHub.teamFor(Sfc.train, FarmHub.QUICK_SEARCH)
            end
            Training.apply(Sfc.train)
        elseif Sfc.home then
            Training.home()
        elseif Sfc.own then
            FarmHub.restoreTeam()
        else
            FarmHub.equipTeam(Sfc.uuids, tostring(Sfc.why))
        end
    end)
    local agc = Training.team()
    local bgc = not Training.same(Yfc, agc)
    local cgc = App.gameSaid(Xfc)
    if bgc or not Zfc or cgc then
        App.log(1, "TEAM", string.format("team change before the first wave (%s): %s in %.1f s%s%s", tostring(Sfc.why), bgc and "the game took it" or "nothing changed", Utils.now() - Xfc, cgc and (" · the game said: " .. tostring(cgc)) or "", Zfc and "" or (" · error: " .. tostring(_fc))))
    end
    if Sfc.must then
        if not Zfc or # agc < 6 or not Training.same(agc, Sfc.uuids) then
            Tfc(string.format("the team for this room didn't go on (%d of 6 units right)", (function()
                local dgc = 0
                for egc, fgc in ipairs(agc) do
                    if table.find(Sfc.uuids, fgc) then
                        dgc = dgc + 1
                    end
                end
                return dgc
            end)()))
            return false
        end
        local ggc, hgc = pcall(Strategy.relicsApply)
        if not ggc then
            App.log(1, "ERROR", "relics: " .. tostring(hgc))
        end
    end
    return bgc
end

function Match.run()
    App.status("Match", "loading the map")
    local igc = Utils.now()
    while App.alive and not (Core.Loader.LevelData and workspace:FindFirstChild("_MAP_CONFIG") and workspace._MAP_CONFIG:FindFirstChild("MapLoaded") and workspace._MAP_CONFIG.MapLoaded.Value) do
        if Utils.now() - igc > 60 then
            break
        end
        task.wait(0.5)
    end
    Match.ld = Core.Loader.LevelData or {
    }
    Match.key, Match.kind = Modes.fromLevelData(Match.ld)
    Match.key = Match.key or "?"
    if Brain.holdLobby and os.time() - (tonumber(Brain.holdLobby.at) or 0) < 90 then
        App.log(1, "MODE", "this match started just after you pressed Go To Lobby: going back")
        pcall(App.flush)
        App.request("lobby", "teleport_back_to_lobby")
    end
    if Brain.watch and Brain.watch.key == Match.key and os.time() - (tonumber(Brain.watch.at) or 0) > 120 then
        pcall(FarmHub.watchDone)
        for jgc, kgc in pairs(Modes.PORTALS) do
            if Match.key == "inf:" .. kgc.from then
                Brain.watch = {
                    key = Match.key,
                    portal = jgc,
                    item = kgc.item,
                    have = Adventure.have(kgc.item),
                    held = # Modes.portalsHeld(jgc),
                    used = false,
                    at = os.time()
                }
            end
        end
    end
    Match.noSpot, Match.refusedRun, Match.unitRefusals = {
    }, {
    }, {
    }
    Match.style, Match.styleSig = nil, nil
    Match.refusals = 0
    Match.startClock = os.clock()
    Match.startT = Utils.now()
    Match.placeLog, Match.styleWhy = {
    }, nil
    Match.starRun, Match.stars = nil, nil
    Match.joinedMid = (workspace._DATA.GameStarted.Value and Match.wave() > 2) or workspace._DATA.GameFinished.Value
    local lgc = {
        weak = {
        },
        strong = {
        }
    }
    for mgc, ngc in pairs(Match.ld._weak_against or Match.ld.weak_against or {
    }) do
        if type(ngc) == "table" then
            lgc.weak [ngc.damage_type] = Modes.weakAmp(ngc.amplification)
        else
            lgc.weak [ngc] = 1.5
        end
    end
    for ogc, pgc in pairs(Match.ld._strong_against or Match.ld.strong_against or {
    }) do
        lgc.strong [type(pgc) == "table" and pgc.damage_type or pgc] = true
    end
    if Match.key == "dc" and (Match.ld._daily_challenge_weak_against or Match.ld._daily_challenge_strong_against) then
        lgc = Modes.dailyMod(Match.ld._challenge_uuid, Match.ld._daily_challenge_weak_against, Match.ld._daily_challenge_strong_against)
    elseif Match.key == "dc" and Brain.live.daily and Brain.live.daily.mod then
        lgc = Brain.live.daily.mod
    end
    Match.mod = (next(lgc.weak) or next(lgc.strong) or next(lgc.res or {
    })) and lgc or Modes.levelMod(Match.ld.id)
    if Match.mod and Match.mod.res then
        local qgc = {
        }
        for rgc, sgc in pairs(Match.mod.weak) do
            table.insert(qgc, string.format("%s ×%.2f", (rgc:gsub("_damage", "")), sgc))
        end
        for tgc, ugc in pairs(Match.mod.res) do
            table.insert(qgc, string.format("%s ×%.2f", (tgc:gsub("_damage", "")), ugc))
        end
        table.sort(qgc)
        App.log(1, "MATCH", (Match.key == "dc" and "the Daily's damage taken by type, as every enemy carries it: " or "this level's weak points, weighted by enemy HP: ") .. table.concat(qgc, ", "))
    end
    Match.buildPath()
    Match.buildWaves()
    Match.setupChecks()
    Match.buildCandidates()
    Match.random = Match.ld._randomequippedmode ~= nil or Core.session().override_equipped_units ~= nil
    Match.hunt = Hunt.is(Match.ld.id)
    if not Match.random then
        local vgc, wgc = pcall(Match.startTeam)
        if not vgc then
            App.log(1, "ERROR", "team change at the start: " .. tostring(wgc))
        end
    end
    Match.team = Match.random and Match.randomTeam() or Units.equipped()
    if Match.random then
        App.log(1, "MATCH", "this mode deals its own team: " .. # Match.team .. " units in hand")
    end
    pcall(Match.watchHelpers)
    Match.trialId = nil
    do
        local xgc = Brain.trial
        local ygc = type(xgc) == "table" and type(xgc.list) == "table" and xgc.key == Match.key and not Match.joinedMid and xgc.list [tonumber(xgc.i) or 1]
        for zgc, Agc in ipairs(ygc and Match.team or {
        }) do
            if Agc.id == ygc then
                Match.trialId = ygc
            end
        end
        local Bgc = Match.trialId and xgc.study and Brain.study and Brain.study.id == Match.trialId and Brain.study.role or nil
        Match.studyTeam, Match.studyEntry = Bgc and Bgc.team or nil, Bgc and Bgc.entry or nil
        if Match.trialId then
            Match.style = "balanced"
            App.log(1, Bgc and "STUDY" or "TRIAL", string.format("%s %d of %d: %s%s", Bgc and "study run" or "trial", tonumber(xgc.i) or 1, # xgc.list, Units.name(ygc), Match.studyTeam and " plays with the whole team fighting" or " gets the yen, the rest of the team stands by") .. (Match.studyEntry and ", at the road's entrance" or ""))
        end
    end
    Match.xp0 = {
    }
    for Cgc, Dgc in ipairs(Match.team) do
        if Dgc.u and Dgc.uuid then
            Match.xp0 [Dgc.uuid] = tonumber(Dgc.u.xp) or 0
        end
    end
    pcall(Units.capture)
    task.delay(15, function()
        local Egc, Fgc = pcall(Units.capture)
        if not Egc then
            App.log(1, "ERROR", "unit stats: " .. tostring(Fgc))
        end
    end)
    Match.trainee, Match.trainTk = nil, 0
    for Ggc, Hgc in ipairs(Match.team) do
        if Brain.train.on and Hgc.uuid == Brain.train.on.uuid then
            Match.trainee = Hgc.uuid
        end
    end
    local Igc = Match.ld._challenge or (Match.key == "dc" and Brain.live.daily and Brain.live.daily.challenge) or nil
    Match.calRun = {
        waveSec = {
        },
        walk = {
        },
        hp = {
        },
        baseRel = {
        },
        alive = {
        },
        spawn = {
        },
        spawnLast = {
        },
        dpsAt = {
        },
        dens = {
        },
        pay = {
        },
        skip = {
        },
        timer = {
        },
        votes = {
        }
    }
    Match.track = setmetatable({
    }, {
        __mode = "k"
    })
    local Jgc, Kgc = pcall(Simulator.info, Simulator.slim(Match.ld), Match.key, Igc, Match.mod)
    Match.info = Jgc and Kgc or nil
    if not Jgc then
        App.log(1, "ERROR", "sim info: " .. tostring(Kgc))
    end
    if Match.info and Match.info.mapMods then
        local Lgc, Mgc = pcall(Match.watchMods)
        if not Lgc then
            App.log(1, "ERROR", "enemy types: " .. tostring(Mgc))
        end
    end
    if Match.info and Match.kind == "dungeon" then
        local Ngc, Ogc = pcall(Dungeon.fx, Dungeon.data())
        if Ngc then
            Simulator.applyFx(Match.info, Ogc)
            local Pgc = {
            }
            for Qgc, Rgc in pairs(Match.mod and Match.mod.weak or {
            }) do
                table.insert(Pgc, string.format("%s ×%.2f", tostring(Qgc):gsub("_damage", ""), Rgc))
            end
            App.log(1, "DUNGEON", string.format("this room's effects: %s · the run's items and curses: %s", # Pgc > 0 and table.concat(Pgc, ", ") or "none", Dungeon.fxText(Ogc)))
        end
    end
    if Match.info and Match.trialId then
        task.spawn(function()
            local Sgc = {
            }
            for Tgc, Ugc in ipairs(Match.team) do
                if Ugc.id == Match.trialId or Units.isFarm(Ugc.id) or Units.allyBuff(Ugc.id) then
                    table.insert(Sgc, Ugc.u)
                end
            end
            local Vgc = {
            }
            local Wgc, Xgc = pcall(Simulator.run, Match.info, Simulator.teamFrom(Sgc, Match.info.map), {
                hpMul = 1,
                dealt = Vgc
            })
            if Wgc and Xgc then
                Match.trialSim = {
                    won = Xgc.won,
                    wave = Xgc.wave,
                    dealt = (Vgc [Units.name(Match.trialId)] or 0) + (Vgc.drones or 0),
                    lvl = Xgc.levels and Xgc.levels [Match.trialId]
                }
            end
        end)
    end
    if Match.info and Config.simSpots and not Match.joinedMid and not Match.random and not Match.infinite and not Match.trialId and not Match.laneWant then
        Match.planning = Utils.now()
        task.spawn(function()
            local Ygc, Zgc = pcall(Match.planSpots)
            Match.planning = nil
            if not Ygc then
                App.log(1, "ERROR", "spot search: " .. tostring(Zgc))
            end
        end)
    end
    Match.lastRes = Match.money()
    table.insert(App.conns, LocalPlayer._stats.resource.Changed:Connect(function(_gc)
        _gc = tonumber(_gc) or 0
        local ahc = _gc - (Match.lastRes or _gc)
        Match.lastRes = _gc
        local bhc = Match.calRun
        if ahc <= 0 or not (bhc and Match.info) then
            return
        end
        local chc = Simulator.waveYen(Match.info, Match.wave(), Match.info.payBase)
        local dhc = Match.farmNow or 0
        if chc > 0 and ahc >= 0.5 * (chc + dhc) then
            table.insert(bhc.pay, (ahc - dhc) / chc)
            bhc.paidT = Utils.now()
        end
    end))
    task.spawn(function()
        local ehc, fhc = pcall(Match.recordMap)
        if not ehc then
            App.log(1, "ERROR", "map record: " .. tostring(fhc))
        end
    end)
    if Match.info and not Match.joinedMid and not Match.random then
        task.spawn(function()
            task.wait(5)
            local ghc = {
            }
            for hhc, ihc in ipairs(Match.team) do
                table.insert(ghc, ihc.u)
            end
            local jhc = Utils.now()
            while Match.planning and Utils.now() - jhc < 20 do
                task.wait(0.5)
            end
            local khc, lhc = pcall(Simulator.run, Match.info, Simulator.teamFrom(ghc, Match.info.map), {
                hpMul = 1,
                train = Match.trainee,
                layout = Match.layoutSim
            })
            if khc then
                Match.pred = lhc
                App.log(1, "SIM", Match.infinite and string.format("prediction for this run: the base falls at wave %d%s (%.0f min)", lhc.wave, lhc.won and "+" or "", lhc.t / 60) or string.format("prediction for this run: %s at wave %d", lhc.won and "win" or "loss", lhc.wave))
            end
        end)
    end
    local mhc = ReplicatedStorage.endpoints.server_to_client
    table.insert(App.conns, mhc.game_finished.OnClientEvent:Connect(function(nhc)
        Match.result = nhc
    end))
    table.insert(App.conns, mhc.show_roguelike_options.OnClientEvent:Connect(function(ohc, phc)
        Match.rogueOptions = phc
    end))
    if mhc:FindFirstChild("show_roguelike_vote_result") then
        table.insert(App.conns, mhc.show_roguelike_vote_result.OnClientEvent:Connect(function(qhc, rhc)
            if type(rhc) == "table" then
                Match.fhMult = 1 + (tonumber(rhc.candy_multiplier) or 0)
                local shc, thc = {
                }, {
                }
                for uhc, vhc in pairs(rhc.persistent_effects or {
                }) do
                    if type(vhc) == "table" then
                        table.insert(shc, Match.effectText(vhc) .. (vhc.damage_type and (" " .. tostring(vhc.damage_type)) or ""))
                        if vhc.type == "enemy_resistance_specific" and vhc.damage_type then
                            thc [vhc.damage_type] = (thc [vhc.damage_type] or 0) + (tonumber(vhc.amount) or 0)
                        end
                    end
                end
                Match.fhEffects, Match.fhResist = shc, thc
            end
            Match.fhPicks = Match.fhPicks or {
            }
            table.insert(Match.fhPicks, string.format("w%d %s", Match.wave(), tostring(type(qhc) == "table" and (qhc.title or qhc.name) or qhc)))
        end))
    end
    if mhc:FindFirstChild("start_vote_wave_skip") then
        table.insert(App.conns, mhc.start_vote_wave_skip.OnClientEvent:Connect(function()
            local whc = Match.calRun
            if not (whc and whc.lastWT and Match.info) then
                return
            end
            local xhc = Match.wave()
            local yhc = # (Simulator.wave(Match.info, xhc))
            table.insert(whc.votes, {
                w = xhc,
                t = Utils.now() - whc.lastWT,
                n = yhc,
                alive = # (Match.enemies or {
                }),
                out = (tonumber(whc.spawn [tostring(xhc)]) or 0) >= yhc
            })
        end))
    end
    local zhc = Match.label()
    App.log(1, "MATCH", string.format("%s · %d waves · %d road samples · %d spots to try%s", zhc, Match.total, # Match.samples, # Match.cands, Match.joinedMid and " · joined mid-way" or ""))
    App.status("Match", zhc .. (Brain.pending and Brain.pending.key == Match.key and "" or " (not launched by the farm)"))
    local Ahc, Bhc, Chc = false, - 1, Utils.now()
    local Dhc, Ehc = nil, nil
    while App.alive do
        if Config.master and Config.battle then
            local gic, hic = pcall(function()
                Match.scan()
                local Fhc, Ghc = pcall(Match.measure)
                if not Fhc and FarmHub.every("measErr", 30) then
                    App.log(1, "ERROR", "measure: " .. tostring(Ghc))
                end
                if workspace._DATA.GameFinished.Value then
                    Match.finish()
                    return
                end
                if Config.autoStart and not Match.noBuy and not workspace._DATA.GameStarted.Value and (# Match.mine > 0 or Utils.now() - igc > 6) and (not Ahc or (Dhc and Utils.now() - Ahc > 6 and Utils.now() - Ehc < 60)) then
                    Ehc = Ehc or Utils.now()
                    local Hhc, Ihc = App.request("vstart", "vote_start")
                    if Hhc and Dhc then
                        App.log(1, "MATCH", string.format("the start vote went through %.0f s after the first one failed", Utils.now() - Ehc))
                    end
                    Ahc, Dhc = Utils.now(), (not Hhc) and ((Ihc == "waiting" or Ihc == "slowing down") and Dhc or tostring(Ihc)) or nil
                    if Dhc and Utils.now() - Ehc >= 54 then
                        App.log(1, "MATCH", "the start vote kept failing (" .. Dhc .. "): the game starts on its own timer")
                    end
                end
                local Jhc = workspace._DATA:FindFirstChild("Roguelike")
                if Jhc and Jhc:FindFirstChild("WaitingForRoguelikeChoice") and Jhc.WaitingForRoguelikeChoice.Value and FarmHub.every("rogue", 3) then
                    Match.pickRogue()
                end
                if not Match.infinite and FarmHub.every("lastCash", 2) then
                    local Khc, Lhc = pcall(Match.lastWaveCash)
                    if not Khc and FarmHub.every("lastCashErr", 30) then
                        App.log(1, "ERROR", "last-wave cash-in: " .. tostring(Lhc))
                    end
                end
                if Match.random and FarmHub.every("adapt", 2) then
                    local Mhc, Nhc = pcall(Match.adapt)
                    if not Mhc and FarmHub.every("adaptErr", 60) then
                        App.log(1, "ERROR", "adaptation: " .. tostring(Nhc))
                    end
                end
                if Match.random and FarmHub.every("watch", 45) then
                    local Ohc, Phc = pcall(Match.watchLine)
                    if not Ohc and FarmHub.every("watchErr", 60) then
                        App.log(1, "ERROR", "watch line: " .. tostring(Phc))
                    end
                end
                if Match.random and FarmHub.every("merge", 1) then
                    local Qhc, Rhc = pcall(Match.mergeScan)
                    if not Qhc and FarmHub.every("mergeErr", 30) then
                        App.log(1, "ERROR", "merge plan: " .. tostring(Rhc))
                    end
                end
                if FarmHub.every("bossStep", 1) then
                    local Shc, Thc = pcall(Match.bossStep)
                    if not Shc and FarmHub.every("bossErr", 30) then
                        App.log(1, "ERROR", "boss step: " .. tostring(Thc))
                    end
                end
                if not Match.stopping then
                    Match.econ()
                end
                if FarmHub.every("act", 0.5) then
                    Match.actives()
                end
                if FarmHub.every("prio", 2) then
                    local Uhc, Vhc = pcall(Match.targeting)
                    if not Uhc and FarmHub.every("prioErr", 30) then
                        App.log(1, "ERROR", "targeting: " .. tostring(Vhc))
                    end
                end
                if Match.trainee and FarmHub.every("train", 2) then
                    pcall(Match.trainCount)
                end
                if Match.random and FarmHub.every("dealt", 2) then
                    Match.team = Match.randomTeam()
                end
                if Match.random and FarmHub.every("dealtStats", 30) then
                    pcall(Units.capture)
                end
                if Match.random and FarmHub.every("room", 3) then
                    local Whc, Xhc = pcall(Match.makeRoom)
                    if not Whc and FarmHub.every("roomErr", 30) then
                        App.log(1, "ERROR", "make room: " .. tostring(Xhc))
                    end
                    local Yhc, Zhc = pcall(Match.refund)
                    if not Yhc and FarmHub.every("refundErr", 30) then
                        App.log(1, "ERROR", "refund: " .. tostring(Zhc))
                    end
                    local _hc, aic = pcall(Match.fish)
                    if not _hc and FarmHub.every("fishErr", 30) then
                        App.log(1, "ERROR", "card fishing: " .. tostring(aic))
                    end
                end
                if Config.actives and FarmHub.every("spells", 1) then
                    local bic, cic = pcall(Match.spells)
                    if not bic and FarmHub.every("spellErr", 30) then
                        App.log(1, "ERROR", "spells: " .. tostring(cic))
                    end
                end
                local dic = Match.wave()
                if Match.random and dic ~= Match.fhWaveSeen then
                    Match.fhWaveSeen = dic
                    pcall(Match.fhSnap)
                end
                if dic ~= Bhc then
                    Bhc, Chc = dic, Utils.now()
                    if Match.infinite then
                        pcall(Match.infWave, dic)
                    end
                end
                local eic = # (Match.enemies or {
                })
                if eic > 0 then
                    Match.emptyAt = nil
                elseif not Match.emptyAt then
                    Match.emptyAt = Utils.now()
                end
                local fic = Match.total and dic >= Match.total and (eic > 0 or Utils.now() - Match.emptyAt < 30)
                if workspace._DATA.GameStarted.Value and Utils.now() - Chc > (fic and 1800 or 360) then
                    App.log(1, "MATCH", string.format("no progress for %d min — back to the lobby", fic and 30 or 6))
                    App.flush()
                    Chc = Utils.now()
                    App.request("lobby", "teleport_back_to_lobby")
                end
            end)
            if not gic then
                App.log(1, "ERROR", "match loop: " .. tostring(hic))
                task.wait(1)
            end
        end
        if Match.finished then
            break
        end
        task.wait(0.3)
    end
end

function Reports.record(iic)
    iic.v = VERSION
    iic.at = os.time()
    table.insert(Brain.hiveQueue, iic)
    while # Brain.hiveQueue > 50 do
        table.remove(Brain.hiveQueue, 1)
    end
end
Reports.SETTINGS_SKIP = {
    seenVersion = true,
    shareNoticed = true,
    shareChosen = true,
    autoTeamChosen = true,
    studiedSeeded = true
}

function Reports.settingsOf()
    local jic, kic = {
    }, 0
    for lic, mic in pairs(Core.DEFAULTS) do
        local nic = Config [lic]
        local oic = type(nic)
        local pic = oic == "boolean" or oic == "number" or (oic == "string" and # nic <= 24 and not nic:find("[{}%-]") and not tostring(lic):lower():find("unit"))
        if nic ~= mic and pic and not Reports.SETTINGS_SKIP [lic] and not tostring(lic):find("At$") and not tostring(lic):find("Sig$") then
            jic [lic] = oic == "number" and math.floor(nic * 100 + 0.5) / 100 or nic
            kic = kic + 1
        end
    end
    return kic > 0 and jic or nil
end

function Reports.searchOf(qic)
    local ric = Brain.simTeam [qic]
    if type(ric) ~= "table" or type(ric.ids) ~= "table" or os.time() - (tonumber(ric.at) or 0) > 7200 then
        return nil
    end
    local sic = {
    }
    for tic, uic in ipairs(Match.team or {
    }) do
        sic [uic.id] = true
    end
    local vic = # ric.ids > 0
    for wic, xic in ipairs(ric.ids) do
        if not sic [xic] then
            vic = false
        end
    end
    return {
        ids = ric.ids,
        won = ric.won and true or false,
        wave = ric.wave,
        cur = ric.cur,
        better = ric.better and true or nil,
        played = vic,
        ago = os.time() - (tonumber(ric.at) or 0)
    }
end

function Reports.modsOf()
    local function yic(zic)
        local Aic
        for Bic, Cic in pairs(type(zic) == "table" and zic or {
        }) do
            Aic = Aic or {
            }
            Aic [Bic] = type(Cic) == "number" and math.floor(Cic * 1000 + 0.5) / 1000 or Cic
        end
        return Aic
    end
    local Dic = {
    }
    if Match.mod then
        Dic.weak, Dic.res, Dic.strong = yic(Match.mod.weak), yic(Match.mod.res), yic(Match.mod.strong)
    end
    Dic.seed = Match.ld._is_daily_challenge and tonumber(Match.ld._challenge_uuid) or nil
    local Eic = {
    }
    for Fic, Gic in pairs(Match.info and Match.info.configs or {
    }) do
        local Hic = type(Gic) == "table" and Core.Units [Gic.unit_id]
        if type(Hic) == "table" then
            local Iic = type(Hic.enemy_modifiers) == "table" and Hic.enemy_modifiers or {
            }
            for Jic, Kic in pairs(Iic) do
                if Kic then
                    Eic [Jic] = (Eic [Jic] or 0) + 1
                end
            end
            if not Iic.Flying and Simulator.flies(Hic) then
                Eic.Flying = (Eic.Flying or 0) + 1
            end
        end
    end
    if next(Eic) then
        Dic.enemy = Eic
    end
    for Lic, Mic in ipairs({
        "Armor",
        "Ice",
        "Ice@snow"
    }) do
        local Nic = Brain.enemyMods [Mic]
        local Oic = Simulator.modRead(Nic)
        if Oic then
            Dic.measured = Dic.measured or {
            }
            Dic.measured [Mic] = {
                f = math.floor(Oic * 1000 + 0.5) / 1000,
                n = # Nic.r
            }
        end
    end
    return next(Dic) and Dic or nil
end

function Reports.mapOf(Pic)
    local Qic = Match.mapKey()
    local Ric = Brain.maps [Qic] or {
    }
    local Sic = Brain.simCal [Pic] or {
    }
    local function Tic(Uic)
        Uic = tonumber(Uic)
        return Uic and math.floor(Uic * 10000 + 0.5) / 10000 or nil
    end
    local Vic
    if type(Ric.dens) == "table" then
        Vic = {
        }
        for Wic = 1, Simulator.BINS do
            Vic [Wic] = math.floor((tonumber(Ric.dens [Wic]) or 0) * 100 + 0.5) / 100
        end
    end
    return {
        key = Qic,
        walk = Tic(Simulator.mapWalk(Qic)),
        spots = tonumber(Ric.spots),
        hill = Ric.hill,
        lanes = type(Ric.lanes) == "table" and # Ric.lanes or nil,
        dens = Vic,
        cal = {
            waveSec = Tic(Sic.waveSec),
            spawnGap = Tic(Sic.spawnGap),
            yenCal = Tic(Sic.yenCal),
            bountyCal = Tic(Sic.bountyCal),
            baseRel = Tic(Sic.baseRel),
            countCal = Tic(Sic.countCal),
            skipDelay = Tic(Sic.skipDelay)
        }
    }
end

function Reports.match(Xic)
    local Yic, Zic = # game:GetService("Players"):GetPlayers() - 1, 0
    for _ic, ajc in ipairs(workspace._UNITS:GetChildren()) do
        local bjc = ajc:FindFirstChild("_stats")
        local cjc = bjc and bjc:FindFirstChild("player")
        local djc = bjc and bjc:FindFirstChild("parent_unit")
        if cjc and cjc.Value ~= nil and cjc.Value ~= LocalPlayer and not (djc and djc.Value) then
            Zic = Zic + 1
        end
    end
    local ejc = {
    }
    local function fjc(gjc)
        ejc [gjc] = ejc [gjc] or {
            dealt = 0,
            copies = 0,
            top = 0
        }
        return ejc [gjc]
    end
    for hjc, ijc in pairs(Match.ownDealt or {
    }) do
        local jjc = fjc(ijc.id)
        jjc.dealt = jjc.dealt + (ijc.v or 0)
        jjc.copies = jjc.copies + 1
        jjc.top = math.max(jjc.top, ijc.lvl or 0)
    end
    for kjc, ljc in pairs(Match.helperDealt or {
    }) do
        if ljc.owner then
            local mjc = fjc(ljc.owner)
            mjc.helpers = (mjc.helpers or 0) + (ljc.v or 0)
        end
    end
    for njc, ojc in ipairs(Match.mine or {
    }) do
        local pjc = ojc:FindFirstChild("_stats")
        local qjc = pjc and pjc:FindFirstChild("takedown_count")
        if pjc and pjc:FindFirstChild("id") and qjc then
            local rjc = fjc(pjc.id.Value)
            rjc.tk = (rjc.tk or 0) + (tonumber(qjc.Value) or 0)
        end
    end
    local sjc = {
    }
    for tjc, ujc in ipairs(Match.team or {
    }) do
        local vjc = ejc [ujc.id] or {
        }
        table.insert(sjc, {
            id = ujc.id,
            lvl = Strategy.level(ujc.u),
            trait = (Units.trait(ujc.u)),
            relic = Units.relicName(ujc.u),
            skin = ujc.u.skin and ujc.u.skin._skin_id or nil,
            copies = vjc.copies or 0,
            top = vjc.top or 0,
            dealt = math.floor(vjc.dealt or 0),
            helpers = vjc.helpers and math.floor(vjc.helpers) or nil,
            tk = vjc.tk,
            eff = Match.lastEff and Match.lastEff [ujc.id] or nil
        })
    end
    local wjc = {
    }
    local xjc, yjc = Match.calRun or {
    }, Match.pred or {
    }
    local function zjc(Ajc, Bjc)
        return math.floor(tonumber(Ajc and (Ajc [Bjc] or Ajc [tostring(Bjc)])) or 0)
    end
    for Cjc = 1, Match.wave() do
        table.insert(wjc, {
            Cjc,
            zjc(xjc.alive,
            Cjc),
            zjc(xjc.dpsAt,
            Cjc),
            zjc(yjc.aliveAt,
            Cjc),
            zjc(yjc.dpsAt,
            Cjc)
        })
    end
    local Djc = {
    }
    for Ejc, Fjc in pairs(Match.layout or {
    }) do
        if Fjc [1] then
            Djc [Ejc] = {
                math.floor(Fjc [1].X),
                math.floor(Fjc [1].Z)
            }
        end
    end
    local Gjc = Brain.simRes [Xic.key] or {
    }
    local Kjc = {
        v = VERSION,
        at = os.time(),
        mode = Xic.key,
        kind = Match.kind,
        level = Match.ld.id,
        map = Match.ld.map,
        diff = Match.ld._difficulty,
        challenge = Match.ld._challenge or (Match.key == "dc" and Brain.live.daily and Brain.live.daily.challenge) or nil,
        portal = Match.kind == "portal" and Brain.portalMods or nil,
        weather = Hunt.is(Match.ld.id) and Hunt.weatherNow() or nil,
        players = Yic,
        otherUnits = Zic,
        joinedMid = Match.joinedMid or nil,
        lanes = Match.laneCount and Match.laneCount.n or 1,
        result = {
            won = Xic.won and true or false,
            wave = Match.wave(),
            total = Match.total,
            sec = math.floor(tonumber(Xic.sec) or 0),
            gems = Xic.gems,
            coins = Xic.coins,
            spent = math.floor(Match.spent or 0),
            refused = Match.refusals or 0,
            items = (type(Xic.items) == "table" and next(Xic.items)) and Xic.items or nil
        },
        sim = {
            pred = Match.pred and {
                won = Match.pred.won,
                wave = Match.pred.wave,
                min = math.floor((Match.pred.t or 0) / 6) / 10
            } or nil,
            p = Gjc.p,
            margin = Gjc.playing or Gjc.margin,
            trust = Gjc.trust and Gjc.trust.ratio or nil,
            style = Match.style,
            why = Match.styleWhy,
            hpCal = Match.info and Match.info.cal and Match.info.cal.hpCal or nil,
            hpRun = Match.hpRun
        },
        team = sjc,
        placed = Match.placeLog,
        plan = Djc,
        waves = wjc,
        trainee = Match.trainee and Brain.train.on and Brain.train.on.id or nil,
        trial = Match.trialId,
        hunt = Match.hunt and {
            picks = Match.fhPicks,
            how = Config.huntCards,
            strength = Match.fhP and math.floor(Match.fhP * 100 + 0.5) / 100 or nil,
            mult = Match.fhMult and math.floor(Match.fhMult * 100 + 0.5) / 100 or nil,
            starfall = Match.starSummary,
            floor = select(2,
            pcall(Hunt.floor))
        } or nil,
        settings = select(2,
        pcall(Reports.settingsOf)),
        toggles = (function()
            local Hjc
            for Ijc in pairs(Match.togglesSeen or {
            }) do
                local Jjc = Brain.toggles [Ijc]
                if Jjc then
                    Hjc = Hjc or {
                    }
                    Hjc [Ijc] = {
                        from = Jjc.from,
                        fill = math.floor((Jjc.fill or 0) * 100 + 0.5) / 100,
                        drain = math.floor((Jjc.drain or 0) * 100 + 0.5) / 100
                    }
                end
            end
            return Hjc
        end)(),
        traineeTk = Match.trainee and Brain.train.on and Match.trainTk or nil,
        trainWhat = Match.trainee and Brain.train.on and Brain.train.on.what or nil,
        search = select(2,
        pcall(Reports.searchOf,
        Xic.key)),
        mods = select(2,
        pcall(Reports.modsOf)),
        mapData = select(2,
        pcall(Reports.mapOf,
        Xic.key))
    }
    for Ljc, Mjc in ipairs({
        "search",
        "mods",
        "mapData"
    }) do
        if type(Kjc [Mjc]) ~= "table" then
            Kjc [Mjc] = nil
        end
    end
    Brain.hiveN = (tonumber(Brain.hiveN) or 0) + 1
    local Njc = Core.FOLDER .. "/hive"
    pcall(makefolder, Njc)
    local Ojc = string.format("%s/matches_%d.jsonl", Njc, math.floor((Brain.hiveN - 1) / 500) + 1)
    local Pjc = Utils.json(Kjc) .. "\n"
    if appendfile and isfile and isfile(Ojc) then
        pcall(appendfile, Ojc, Pjc)
    else
        local Qjc, Rjc = pcall(readfile, Ojc)
        pcall(writefile, Ojc, (Qjc and Rjc or "") .. Pjc)
    end
    if Config.shareStats and Core.WEBHOOK_URL ~= "" then
        Kjc.id = Brain.anonId
        table.insert(Brain.aaHiveQ, Reports.fit(Kjc))
        while # Brain.aaHiveQ > 30 do
            table.remove(Brain.aaHiveQ, 1)
        end
        task.spawn(function()
            pcall(Reports.sendHive)
        end)
    end
    App.saveSoon()
end

function Reports.fit(Sjc)
    local Tjc = Utils.json(Sjc)
    if # Tjc <= 3900 then
        return Tjc
    end
    for Ujc, Vjc in ipairs({
        2,
        5,
        10
    }) do
        local Wjc = {
        }
        for Xjc, Yjc in ipairs(Sjc.waves or {
        }) do
            if Xjc % Vjc == 0 or Xjc == # Sjc.waves then
                table.insert(Wjc, Yjc)
            end
        end
        Sjc.waves = Wjc
        Tjc = Utils.json(Sjc)
        if # Tjc <= 3900 then
            return Tjc
        end
    end
    for Zjc, _jc in ipairs(Sjc.placed or {
    }) do
        _jc.why = nil
    end
    Tjc = Utils.json(Sjc)
    if # Tjc <= 3900 then
        return Tjc
    end
    if Sjc.mapData then
        Sjc.mapData.dens = nil
    end
    Tjc = Utils.json(Sjc)
    if # Tjc <= 3900 then
        return Tjc
    end
    Sjc.placed, Sjc.plan = nil, nil
    return Utils.json(Sjc):sub(1, 3900)
end

function Reports.postEmbed(akc, bkc)
    local ckc = (syn and syn.request) or (http and http.request) or http_request or request
    if not ckc or Core.WEBHOOK_URL == "" then
        return false
    end
    local dkc, ekc = pcall(ckc, {
        Url = Core.WEBHOOK_URL,
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json"
        },
        Body = Utils.json({
            username = "RobScript Team",
            allowed_mentions = {
                parse = {
                }
            },
            embeds = {
                {
                    title = akc,
                    description = bkc,
                    color = 15418782
                }
            }
        })
    })
    local fkc = dkc and type(ekc) == "table" and tonumber(ekc.StatusCode or ekc.Status) or nil
    return dkc and (not fkc or fkc < 300)
end

function Reports.sendHive()
    if not (Config.shareStats and Core.WEBHOOK_URL ~= "") or # Brain.aaHiveQ == 0 or Reports.sending then
        return
    end
    Reports.sending = true
    local gkc, hkc = pcall(Reports.postEmbed, string.format("🎌 AA · match · %s · v%s", tostring(Brain.anonId), VERSION), "```json\n" .. Brain.aaHiveQ [1] .. "\n```")
    Reports.sending = nil
    if gkc and hkc then
        table.remove(Brain.aaHiveQ, 1)
        Brain.hiveSent = (tonumber(Brain.hiveSent) or 0) + 1
        pcall(App.saveNow)
    end
end

function Reports.sendAll()
    if not (Config.shareStats and Core.WEBHOOK_URL ~= "") then
        return 0, # Brain.aaHiveQ
    end
    local ikc = 0
    for jkc = 1, 10 do
        local kkc = # Brain.aaHiveQ
        if kkc == 0 then
            break
        end
        Reports.sendHive()
        if # Brain.aaHiveQ >= kkc then
            break
        end
        ikc = ikc + 1
        task.wait(1.5)
    end
    return ikc, # Brain.aaHiveQ
end

function Reports.post(lkc)
    if Core.WEBHOOK_URL == "" then return false, "not connected" end
    local mkc = (syn and syn.request) or (http and http.request) or http_request or request
    if not mkc then
        return false, "no http"
    end
    local nkc, okc = pcall(mkc, {
        Url = Core.WEBHOOK_URL,
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json"
        },
        Body = Utils.json({
            content = lkc,
            allowed_mentions = {
                parse = {
                }
            }
        })
    })
    return nkc and okc and (okc.StatusCode == 200 or okc.StatusCode == 204), okc
end

function Reports.flush()
    if Core.WEBHOOK_URL == "" or not Config.shareStats or # Brain.hiveQueue == 0 then
        return false, "not connected"
    end
    local pkc = Reports.post("📊 AA " .. Utils.json({
        id = Brain.anonId,
        v = VERSION,
        runs = Brain.hiveQueue
    }))
    if pkc then
        table.clear(Brain.hiveQueue)
        App.saveSoon()
    end
    return pkc
end
Reports.HIVE_FILE = Core.FOLDER .. "/hive_shared.json"

function Reports.hive()
    if not Config.useHive then
        return nil
    end
    if Reports.shared == nil then
        local qkc = Utils.readJson(Reports.HIVE_FILE)
        Reports.shared = type(qkc) == "table" and type(qkc.units) == "table" and qkc or false
    end
    return Reports.shared or nil
end

function Reports.hiveUnit(rkc)
    local skc = Reports.hive()
    local tkc = skc and skc.units [rkc]
    if type(tkc) == "table" and (tonumber(tkc.eff) or 0) > 0 and ((tonumber(tkc.matches) or 0) >= 5 or (tonumber(tkc.players) or 0) >= 2) then
        return tkc
    end
end

function Reports.hiveTrain(ukc, vkc)
    local wkc = Reports.hive()
    local xkc = wkc and type(wkc.train) == "table" and wkc.train [ukc]
    if type(xkc) ~= "table" then
        return nil
    end
    local ykc = vkc and type(xkc.units) == "table" and xkc.units [vkc]
    if type(ykc) == "table" and (tonumber(ykc.runs) or 0) >= 3 then
        return tonumber(ykc.perRun)
    end
    if (tonumber(xkc.runs) or 0) >= 3 then
        return tonumber(xkc.perRun)
    end
end

function Reports.hiveToggle(zkc)
    local Akc = Reports.hive()
    local Bkc = Akc and type(Akc.toggles) == "table" and Akc.toggles [zkc]
    return type(Bkc) == "table" and Bkc or nil
end

function Reports.hiveStat(Ckc)
    local Dkc = Reports.hive()
    local Ekc = Dkc and type(Dkc.stats) == "table" and Dkc.stats [Ckc]
    return type(Ekc) == "table" and Ekc or nil
end

function Reports.hiveHp(Fkc)
    local Gkc = Reports.hive()
    local Hkc = Gkc and type(Gkc.maps) == "table" and Gkc.maps [Fkc]
    return type(Hkc) == "table" and (tonumber(Hkc.runs) or 0) >= 3 and tonumber(Hkc.hpCal) or nil
end

function Reports.hiveDrops(Ikc)
    local Jkc = Reports.hive()
    local Kkc = Ikc and Jkc and type(Jkc.drops) == "table" and Jkc.drops [Ikc]
    if type(Kkc) ~= "table" or (tonumber(Kkc.runs) or 0) < 3 or type(Kkc.items) ~= "table" then
        return nil
    end
    return Kkc.items
end

function Reports.sendUnit()
    if not (Config.shareStats and Core.WEBHOOK_URL ~= "") or Reports.sending then
        return
    end
    local Lkc = Reports.hive()
    local Mkc = Lkc and type(Lkc.stats) == "table" and Lkc.stats or {
    }
    for Nkc, Okc in pairs(Brain.unitData) do
        if not Brain.unitSent [Nkc] and not Mkc [Nkc] and type(Okc) == "table" and Okc.upgrade then
            local Pkc = {
            }
            for Qkc, Rkc in pairs(Okc) do
                if Qkc ~= "passives" then
                    Pkc [Qkc] = Rkc
                end
            end
            local Skc, Tkc = pcall(Utils.json, {
                id = Nkc,
                data = Pkc
            })
            if Skc and # Tkc <= 3900 then
                Reports.sending = true
                local Ukc, Vkc = pcall(Reports.postEmbed, string.format("🎌 AA · unit · %s · v%s", tostring(Brain.anonId), VERSION), "```json\n" .. Tkc .. "\n```")
                Reports.sending = nil
                if Ukc and Vkc then
                    Brain.unitSent [Nkc] = os.time()
                    App.saveSoon()
                end
            else
                Brain.unitSent [Nkc] = - 1
                App.saveSoon()
            end
            return
        end
    end
end

function Reports.hiveTrainRate(Wkc)
    local Xkc = Reports.hive()
    local Ykc = Xkc and type(Xkc.train) == "table" and Xkc.train [Wkc]
    return type(Ykc) == "table" and (tonumber(Ykc.runs) or 0) >= 3 and tonumber(Ykc.perMin) or nil
end

function Reports.hiveFetch()
    if Core.HIVE_URL == "" or not Config.useHive then
        return
    end
    local Zkc, _kc = pcall(game.HttpGet, game, Core.HIVE_URL .. "?t=" .. os.time())
    if not Zkc or type(_kc) ~= "string" or _kc:sub(1, 1) ~= "{" then
        return
    end
    local alc, blc = pcall(HttpService.JSONDecode, HttpService, _kc)
    if not (alc and type(blc) == "table" and tonumber(blc.v) == 1 and type(blc.units) == "table") then
        return
    end
    local clc = Reports.hive()
    if clc and clc.updated == blc.updated then
        return
    end
    pcall(Utils.writeJson, Reports.HIVE_FILE, blc)
    Reports.shared = blc
    table.clear(Units._rows)
    table.clear(Simulator._holds)
    Adventure._src = nil
    local dlc, elc = 0, 0
    for flc in pairs(blc.units) do
        dlc = dlc + 1
    end
    for glc in pairs(type(blc.train) == "table" and blc.train or {
    }) do
        elc = elc + 1
    end
    App.log(1, "HIVE", string.format("learned from %d players' %d matches: readings for %d units, takedown rates on %d maps", tonumber(blc.players) or 0, tonumber(blc.matchRecords) or 0, dlc, elc))
    local hlc = {
    }
    for ilc, jlc in ipairs(type(blc.under) == "table" and blc.under or {
    }) do
        if Units.owns(jlc) and not (Brain.learn [jlc] and (Brain.learn [jlc].n or 0) >= 3) then
            table.insert(hlc, string.format("%s (×%.1f)", Units.name(jlc), tonumber(blc.units [jlc] and blc.units [jlc].eff) or 0))
        end
    end
    if # hlc > 0 then
        App.log(1, "HIVE", "other players' runs say the simulator reads these of yours far too low: " .. table.concat(hlc, ", ") .. ". A trial run would check them")
        if App.notify then
            App.notify("Local learning", "Units the simulator underrates: " .. table.concat(hlc, ", "), "info")
        end
    end
end

function Reports.hiveText()
    if not Config.useHive then
        return "Off: the farm learns only from your own runs."
    end
    local klc = Reports.hive()
    if not klc then
        return "Nothing shared yet. Once other players' farms send their matches, the farm reads what they learned here every 6 hours."
    end
    local llc, mlc, nlc, olc, plc, qlc = 0, 0, 0, 0, 0, 0
    for rlc in pairs(klc.units) do
        if Reports.hiveUnit(rlc) and not (Brain.learn [rlc] and (Brain.learn [rlc].n or 0) >= 3) then
            llc = llc + 1
        end
    end
    for slc in pairs(type(klc.train) == "table" and klc.train or {
    }) do
        mlc = mlc + 1
    end
    for tlc in pairs(type(klc.stats) == "table" and klc.stats or {
    }) do
        if not Brain.unitData [tlc] then
            nlc = nlc + 1
        end
    end
    for ulc in pairs(type(klc.maps) == "table" and klc.maps or {
    }) do
        if Reports.hiveHp(ulc) and not (Brain.simCal [ulc] and Brain.simCal [ulc].hpCal) then
            olc = olc + 1
        end
    end
    for vlc in pairs(type(klc.drops) == "table" and klc.drops or {
    }) do
        if Reports.hiveDrops(vlc) then
            plc = plc + 1
        end
    end
    for wlc in pairs(type(klc.toggles) == "table" and klc.toggles or {
    }) do
        if not Brain.toggles [wlc] then
            qlc = qlc + 1
        end
    end
    local xlc = {
        string.format("From %d players' %d matches, updated %s.",
        tonumber(klc.players) or 0,
        tonumber(klc.matchRecords) or 0,
        os.date("%b %d %H:%M",
        tonumber(klc.updated) or 0)),
        string.format("What it fills in that your own runs haven't: %d units' readings, %d hidden units' real stats, %d switch abilities, how tough %d maps really are, what %d levels really drop, and takedown rates on %d maps.",
        llc,
        nlc,
        qlc,
        olc,
        plc,
        mlc)
    }
    local ylc = {
    }
    for zlc, Alc in ipairs(type(klc.under) == "table" and klc.under or {
    }) do
        table.insert(ylc, Units.name(Alc) .. (Units.owns(Alc) and " (yours)" or ""))
    end
    if # ylc > 0 then
        table.insert(xlc, "The simulator reads these far too low: " .. table.concat(ylc, ", ") .. ".")
    end
    return table.concat(xlc, "\n")
end

function Reports.suggest(Blc)
    Blc = tostring(Blc or ""):sub(1, 500):gsub("https?://%S+", "[link]"):gsub("@", "(at)")
    if Blc:gsub("%s", "") == "" then
        return false, "empty"
    end
    if Core.WEBHOOK_URL == "" then
        return false, "suggestions aren't connected yet"
    end
    if os.time() - (Brain.lastSuggest or 0) < 600 then
        return false, "one suggestion per 10 minutes"
    end
    local Clc = Reports.postEmbed(string.format("🎌 AA · suggestion · %s · v%s", tostring(Brain.anonId), VERSION), Blc)
    if Clc then
        Brain.lastSuggest = os.time()
    end
    return Clc, Clc and nil or "send failed"
end

-- Airflow UI integration. Game logic keeps its existing handles; every widget is
-- constructed by Robly Airflow using the documented one-table options API.
function GUI.load()
    if GUI.Airflow then
        return GUI.Airflow
    end
    local ok, result = pcall(function()
        local source = game:HttpGet(Core.AIRFLOW_URL)
        local chunk, err = loadstring(source, "=Robly_Airflow")
        assert(chunk, err)
        return chunk()
    end)
    if not ok or type(result) ~= "table" or type(result.CreateWindow) ~= "function" then
        App.log(0, "ERROR", "Robly Airflow could not be loaded: " .. tostring(result))
        return nil
    end
    GUI.Airflow = result
    return result
end

function GUI.escape(value)
    return (tostring(value or ""):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
end

function GUI.theme(Airflow)
    local theme = {
        Background = Color3.fromHex("#0A0A0C"),
        Surface = Color3.fromHex("#141418"),
        Surface2 = Color3.fromHex("#1A1A20"),
        Surface3 = Color3.fromHex("#2A2A33"),
        Stroke = Color3.fromHex("#26262E"),
        StrokeHover = Color3.fromHex("#3C3C49"),
        Accent = Color3.fromHex("#FF3B7F"),
        AccentDark = Color3.fromHex("#1A0710"),
        Text = Color3.fromHex("#F5F5F7"),
        Muted = Color3.fromHex("#8D8D99"),
    }
    Airflow.ThemePresets.Robscript = theme
    Airflow:SetDefaultTheme(theme)
    GUI.THEME = theme
    -- Status colours are looked up live, so the native theme manager works.
    local aliases = {
        bg = "Background", panel = "Surface", card = "Surface2", border = "Stroke",
        accent = "Accent", accentD = "AccentDark", accentBg = "Surface3",
        text = "Text", sub = "Muted", green = "Success", red = "Error",
        gold = "Warning", orange = "Warning", purple = "Accent",
    }
    GUI.COL = setmetatable({}, { __index = function(_, key)
        local current = Airflow.Theme or GUI.THEME
        return current[aliases[key] or key]
    end })
end

