function GUI.snipeOptions()
    local bmc = {
        {
            text = "Pick a unit",
            value = ""
        }
    }
    local cmc = Brain.snipe or {
    }
    if not GUI.evolvedIds then
        GUI.evolvedIds = {
        }
        for dmc, emc in pairs(Core.Units) do
            if type(emc) == "table" and type(emc.evolve) == "table" and emc.evolve.evolve_unit then
                GUI.evolvedIds [emc.evolve.evolve_unit] = true
            end
        end
    end
    local fmc, gmc = {
    }, {
    }
    local function hmc(imc, jmc, kmc)
        if gmc [imc] or not Core.Units [imc] then
            return
        end
        gmc [imc] = true
        local lmc = FarmHub.snipeHas(imc)
        table.insert(fmc, {
            id = imc,
            text = Units.name(imc) .. jmc .. (lmc and " · owned" or ""),
            key = kmc * 10 + (lmc and 0 or 5),
            name = Units.name(imc)
        })
    end
    if Config.snipeUnit ~= "" then
        hmc(Config.snipeUnit, "", 9)
    end
    for mmc, nmc in pairs(cmc.feat or {
    }) do
        for omc, pmc in ipairs(nmc) do
            hmc(pmc, " · featured on " .. (FarmHub.BANNER_NAME [mmc] or mmc), 3)
        end
    end
    for qmc, rmc in pairs(cmc.seen or {
    }) do
        if type(rmc) == "table" then
            hmc(qmc, string.format(" · seen on %s %s", FarmHub.BANNER_NAME [rmc.banner] or tostring(rmc.banner), os.date("%b %d", tonumber(rmc.at) or os.time())), 2)
        end
    end
    for smc, tmc in pairs(Core.Units) do
        if type(smc) == "string" and type(tmc) == "table" and tmc.rarity == "Mythic" and not tmc.hide_from_banner and not tmc.limited and not GUI.evolvedIds [smc] and not smc:find(":") then
            hmc(smc, "", 1)
        end
    end
    table.sort(fmc, function(umc, vmc)
        if umc.key ~= vmc.key then
            return umc.key > vmc.key
        end
        return umc.name < vmc.name
    end)
    for wmc, xmc in ipairs(fmc) do
        table.insert(bmc, {
            text = xmc.text,
            value = xmc.id
        })
    end
    return bmc
end

function GUI.unitOptions(ymc, zmc)
    local Amc = {
        {
            text = "Pick a unit",
            value = ""
        }
    }
    local Bmc = Core.session()
    if not Bmc then
        return Amc
    end
    local Cmc = {
    }
    for Dmc, Emc in ipairs(Units.equipped()) do
        Cmc [Emc.uuid] = true
    end
    local Fmc = {
    }
    for Gmc, Hmc in pairs(Bmc.profile_data.collection.owned_units) do
        local Imc = Core.Units [Hmc.unit_id]
        if Imc and (Cmc [Gmc] or Hmc._locked or Imc.rarity == "Secret" or Imc.rarity == "Mythic" or Gmc == ymc) then
            local Jmc, Kmc = pcall(Core.USC.calculate_level, Hmc.unit_id, Hmc.xp)
            Kmc = Jmc and tonumber(Kmc) or 0
            table.insert(Fmc, {
                uuid = Gmc,
                u = Hmc,
                lvl = Kmc,
                team = Cmc [Gmc],
                key = (Cmc [Gmc] and 4000 or 0) + (Hmc._locked and 2000 or 0) + (Imc.rarity == "Secret" and 1000 or 0) + Kmc
            })
        end
    end
    table.sort(Fmc, function(Lmc, Mmc)
        if Lmc.key ~= Mmc.key then
            return Lmc.key > Mmc.key
        end
        return Lmc.uuid < Mmc.uuid
    end)
    for Nmc, Omc in ipairs(Fmc) do
        local Pmc, Qmc = true, ""
        if zmc then
            Pmc, Qmc = pcall(zmc, Omc.u)
        end
        if Pmc and (Qmc ~= false or Omc.uuid == ymc) and (# Amc <= 60 or Omc.uuid == ymc) then
            table.insert(Amc, {
                text = string.format("%s · lvl %d%s%s",
                Units.name(Omc.u.unit_id),
                Omc.lvl,
                Omc.team and " · team" or "",
                type(Qmc) == "string" and Qmc or ""),
                value = Omc.uuid
            })
        end
    end
    return Amc
end

