        local Wmc = Tmc and Tmc.collection:get_unit_by_uuid(Vmc.uuid)
        local Xmc, Ymc = pcall(Core.USC.calculate_level, Vmc.from, Wmc and Wmc.xp or 0)
        table.insert(Rmc, {
