function FarmHub.setFocus(cnc)
    Config.evolveUnit = cnc or ""
    Config.autoEvolve = Config.evolveUnit ~= ""
    Config.focusNext = ""
    FarmHub.pickNote.autoEvolve = nil
    FarmHub.last.goals, FarmHub.last.trainScan, Training._at, Modes.lastScored = nil, nil, nil, nil
    local dnc, enc = pcall(Adventure.refresh)
    if not dnc then
        App.log(1, "ERROR", "focus goals: " .. tostring(enc))
    end
    local fnc, gnc = pcall(Strategy.core, true)
    if not fnc then
        App.log(1, "ERROR", "focus core: " .. tostring(gnc))
    end
    App.saveSoon()
end

function FarmHub.focusText()
    if GUI.focusNow() ~= "" then
        return "Your focus. " .. FarmHub.evolveText() .. (Config.focusNext ~= "" and ("\nNext up: " .. Units.name(Config.focusNext) .. ", once this one has evolved.") or "")
    end
    local hnc = Brain.train.on
    local jnc = hnc or Training.target()
    if jnc then
        return string.format("Smart Play is working on %s → %s (%s %s/%s)", Units.name(jnc.id), Units.name(jnc.to), tostring(jnc.what), Utils.fmt((tonumber(jnc.have) or 0) + (tonumber(jnc.got) or 0)), Utils.fmt(tonumber(jnc.need) or 0))
    end
    local knc = (Brain.goals or {
    }) [1]
    if knc then
        return "Smart Play is working on " .. Units.name(knc.from) .. " → " .. Units.name(knc.to)
    end
    return "Smart Play: goals are worked out in the lobby"
end

function GUI.evolveOptions(lnc)
    local mnc = {
        {
            text = "Pick a unit",
            value = ""
        }
    }
    local nnc = Core.session()
    if not nnc then
        return mnc
    end
    local onc = {
    }
    for pnc, qnc in ipairs(Units.equipped()) do
        onc [qnc.uuid] = true
    end
    local rnc = {
    }
    for snc, tnc in pairs(nnc.profile_data.collection.owned_units) do
        local unc = Core.Units [tnc.unit_id]
        if unc and unc.evolve and unc.evolve.evolve_unit and not unc.evolve.hide_from_ui and Core.Units [unc.evolve.evolve_unit] then
            local vnc = (snc == lnc and 1e9 or 0) + (onc [snc] and 1e6 or 0) + (tonumber(tnc.xp) or 0)
            if not rnc [tnc.unit_id] or vnc > rnc [tnc.unit_id].key then
                rnc [tnc.unit_id] = {
                    uuid = snc,
                    id = tnc.unit_id,
                    to = unc.evolve.evolve_unit,
                    key = vnc
                }
            end
        end
    end
    local wnc = {
    }
    for xnc, ync in pairs(rnc) do
        table.insert(wnc, ync)
    end
    table.sort(wnc, function(znc, Anc)
        if znc.key ~= Anc.key then
            return znc.key > Anc.key
        end
        return znc.uuid < Anc.uuid
    end)
    for Bnc, Cnc in ipairs(wnc) do
        local Dnc = nnc.collection:get_unit_by_uuid(Cnc.uuid)
        local Enc, Fnc = pcall(Core.USC.calculate_level, Cnc.id, Dnc and Dnc.xp or 0)
        table.insert(mnc, {
            text = string.format("%s → %s · lvl %d%s",
            Units.name(Cnc.id),
            Units.name(Cnc.to),
            Enc and tonumber(Fnc) or 0,
            onc [Cnc.uuid] and " · team" or ""),
            value = Cnc.uuid
        })
    end
    return mnc
end

function GUI.modeOptions(Gnc)
    local Hnc = {
    }
    local Inc = ({
        raid = "pickRaid",
        story = "pickStory",
        legend = "pickLegend",
        infinite = "pickInfinite",
        portal = "pickPortal"
    }) [Gnc]
    local function Jnc(Knc, Lnc)
        for Mnc, Nnc in ipairs(Utils.list(Knc)) do
            local Onc = Core.Worlds [Nnc]
            for Pnc, Qnc in ipairs(Utils.list(Onc and Onc.levels)) do
                if Modes.open(Qnc.id) then
                    Lnc(Qnc.id, Onc)
                end
            end
        end
    end
    if Gnc == "story" then
        Hnc = {
            {
                text = "🤖 Smart: first clears, then farm runs",
                value = ""
            },
            {
                text = "📈 Progress: the next map you haven't beaten",
                value = "progress"
            }
        }
        Jnc(Core.WLO.WORLD_ORDER, function(Rnc, Snc)
            if not Snc.legend_stage and not Snc.raid_world then
                for Tnc, Unc in ipairs({
                    "Normal",
                    "Hard"
                }) do
                    if Modes.diffOpen(Rnc, Unc) then
                        table.insert(Hnc, {
                            text = Modes.levelName(Rnc) .. " (" .. Unc .. ")",
                            value = "st:" .. Rnc .. ":" .. Unc
                        })
                    end
                end
            end
        end)
    elseif Gnc == "legend" then
        Hnc = {
            {
                text = "🤖 Smart: when it drops what a goal needs",
                value = ""
            },
            {
                text = "📈 Progress: the next legend stage you haven't beaten",
                value = "progress"
            }
        }
        Jnc(Core.WLO.LEGEND_WORLD_ORDER, function(Vnc)
            table.insert(Hnc, {
                text = Modes.levelName(Vnc),
                value = "st:" .. Vnc .. ":Hard"
            })
        end)
    elseif Gnc == "raid" then
        Hnc = {
            {
                text = "🤖 Smart: the raid worth the most",
                value = ""
            }
        }
        Jnc(Core.WLO.RAID_WORLD_ORDER, function(Wnc)
            table.insert(Hnc, {
                text = Modes.levelName(Wnc),
                value = "rd:" .. Wnc
            })
        end)
    elseif Gnc == "infinite" then
        Hnc = {
            {
                text = "🤖 Smart: daily gems and takedowns",
                value = ""
            }
        }
        for Xnc, Ync in ipairs(Modes.infIds()) do
            if Modes.open(Ync) then
                table.insert(Hnc, {
                    text = Modes.levelName(Ync),
                    value = "inf:" .. Ync
                })
            end
        end
    elseif Gnc == "portal" then
        Hnc = {
            {
                text = "🤖 Smart: portals whose map drops what your evolutions need",
                value = "smart"
            }
        }
        local Znc = {
        }
        for _nc, aoc in ipairs(Modes.portalKinds()) do
            local boc = # Modes.portalsHeld(aoc.pid)
            local coc = {
                text = string.format("%s (%s)%s",
                aoc.name,
                tostring(aoc.rarity or "?"),
                boc > 0 and (" · you hold " .. boc) or ""),
                value = aoc.pid
            }
            table.insert(boc > 0 and Hnc or Znc, coc)
        end
        for doc, eoc in ipairs(Znc) do
            table.insert(Hnc, eoc)
        end
    end
    local foc = Inc and Config [Inc] or ""
    local goc = false
    for hoc, ioc in ipairs(Hnc) do
        if ioc.value == foc then
            goc = true
        end
    end
    if not goc then
        table.insert(Hnc, {
            text = "your pick (not open right now)",
            value = foc
        })
    end
    return Hnc
end
GUI.TITLE = "RobScript Team - Anime Adventures"

function GUI.lbTargetOptions()
    local Zoc = {
        {
            text = "Pick a unit",
            value = ""
        }
    }
    local _oc = Core.session()
    if not _oc then
        return Zoc
    end
    local apc = {
    }
    for bpc, cpc in ipairs(Units.equipped()) do
        apc [cpc.uuid] = true
    end
    local dpc = {
    }
    for epc, fpc in pairs(_oc.profile_data.collection.owned_units) do
        local gpc = _oc.collection:get_unit_by_uuid(epc) or fpc
        local hpc = Core.Units [gpc.unit_id]
        if hpc and (hpc.rarity == "Mythic" or hpc.rarity == "Secret" or apc [epc] or epc == Config.fuseUnit) then
            local ipc, jpc = pcall(Core.USC.get_max_limit_break, gpc)
            local kpc = gpc.further_modifiers and gpc.further_modifiers.limit_break and tonumber(gpc.further_modifiers.limit_break.current_limit_break) or 0
            if (ipc and (tonumber(jpc) or 0) > kpc) or epc == Config.fuseUnit then
                local lpc, mpc = pcall(Units.score, gpc)
                local npc, opc = Strategy.level(gpc), Strategy.cap(gpc)
                table.insert(dpc, {
                    uuid = epc,
                    id = gpc.unit_id,
                    lvl = npc,
                    cap = opc,
                    team = apc [epc],
                    sc = lpc and mpc or 0,
                    key = (epc == Config.fuseUnit and 4 or 0) + (apc [epc] and 2 or 0) + (npc >= opc and 1 or 0)
                })
            end
        end
    end
    table.sort(dpc, function(ppc, qpc)
        if ppc.key ~= qpc.key then
            return ppc.key > qpc.key
        end
        if ppc.sc ~= qpc.sc then
            return ppc.sc > qpc.sc
        end
        return ppc.uuid < qpc.uuid
    end)
    for rpc, spc in ipairs(dpc) do
        if rpc > 60 then
            break
        end
        table.insert(Zoc, {
            text = string.format("%s · Lv %d/%d%s%s",
            Units.name(spc.id),
            spc.lvl,
            spc.cap,
            spc.team and " · team" or "",
            spc.lvl >= spc.cap and " · at cap" or ""),
            value = spc.uuid
        })
    end
    return Zoc
end

function GUI.fodderTable(page)
    local group = GUI.block("Units", "Fusion", "Fodder units", "Left")
    local handle = { data = {} }
    local board, selectionFlag
    local summary = group:CreateStatus({ Name = "Fodder", Value = "Farm picks", Style = "Plain" })
    GUI.paragraph(group, "Click a row to select a unit. ★ marks the farm's safe picks; ⚠ marks something worth keeping. Empty selection uses the farm's safe rule. Locked and equipped units never show.")
    local function selected()
        local result = {}
        for _, uuid in ipairs(Config.fuseFodder or {}) do result[uuid] = true end
        return result
    end
    function handle.points()
        local picked, total = selected(), 0
        for _, unit in ipairs(handle.data) do
            if picked[unit.uuid] then total = total + unit.pts end
        end
        return total
    end
    function handle.summary()
        local requirement = Brain.fuseInfo and Brain.fuseInfo.uuid == Config.fuseUnit and tonumber(Brain.fuseInfo.requirement)
        local count, points = #(Config.fuseFodder or {}), handle.points()
        summary:Set(count == 0 and "Farm picks" or string.format("%d selected · %d%s points", count, points, requirement and (" / " .. requirement) or ""))
        summary:SetColor(requirement and points >= requirement and "Success" or "Accent")
    end
    local function render()
        local picked, rows = selected(), {}
        for _, unit in ipairs(handle.data) do
            local details = { unit.rarity, "Lv " .. tostring(unit.lvl) }
            if unit.evolved then table.insert(details, "evolved") end
            if #(unit.flags or {}) > 0 then table.insert(details, "⚠ " .. table.concat(unit.flags, ", ")) end
            table.insert(rows, {
                picked[unit.uuid] and "✓" or "", GUI.escape(unit.name .. (unit.safe and " ★" or "")),
                GUI.escape(table.concat(details, " · ")), unit.pts,
                UUID = unit.uuid, Highlight = picked[unit.uuid] == true,
            })
        end
        board:SetRows(rows)
        handle.summary()
    end
    local function persist()
        Config.fuseArmSig = ""
        App.saveSoon()
        if selectionFlag then selectionFlag:Set(Utils.json(Config.fuseFodder or {}), true) end
        render()
    end
    board = group:CreateTable({
        Name = "Available fodder", MaxRows = 6, Search = true,
        Columns = {
            { Name = "Pick", Width = 40 }, { Name = "Unit", Width = 0.32 },
            { Name = "Details" }, { Name = "Points", Width = 55, Align = "Right" },
        },
        Rows = {},
        Callback = function(row)
            local picked, result = selected(), {}
            for _, uuid in ipairs(Config.fuseFodder or {}) do
                if uuid ~= row.UUID then table.insert(result, uuid) end
            end
            if not picked[row.UUID] then table.insert(result, row.UUID) end
            Config.fuseFodder = result
            persist()
        end,
    })
    local ready, generation = false, 0
    selectionFlag = group:CreateInput({
        Name = "Fodder selection", Visible = false, Flag = "AA/Fuse/FodderUUIDs",
        CurrentValue = Utils.json(Config.fuseFodder or {}),
        Callback = function(text)
            if not ready then return end
            local values = Utils.unjson(text)
            if type(values) ~= "table" then return end
            local ids = {}
            for _, uuid in ipairs(values) do if type(uuid) == "string" then table.insert(ids, uuid) end end
            generation = generation + 1
            local revision = generation
            -- Profile flags load in arbitrary order. Restore the fodder after the
            -- target-unit callback, which intentionally clears a previous pick.
            task.defer(function()
                if not App.alive or revision ~= generation then return end
                Config.fuseFodder = ids
                persist()
            end)
        end,
    })
    ready = true
    function handle.Refresh(data, emptyText)
        handle.data = data or {}
        summary:SetName(#handle.data == 0 and GUI.escape(emptyText or "No eligible units") or "Fodder")
        selectionFlag:Set(Utils.json(Config.fuseFodder or {}), true)
        render()
    end
    group:CreateButtonRow({
        { Name = "Use farm picks", Callback = function()
            task.spawn(function()
                local session = Core.session()
                local unit = session and session.collection:get_unit_by_uuid(Config.fuseUnit)
                if not unit then return end
                local need = Brain.fuseInfo and Brain.fuseInfo.uuid == unit.uuid and tonumber(Brain.fuseInfo.requirement) or 12
                local fuel, ids = FarmHub.fuseFuel(unit, need), {}
                for _, entry in ipairs(fuel) do table.insert(ids, entry.uuid) end
                Config.fuseFodder = ids
                persist()
            end)
        end },
        { Name = "Clear", Callback = function() Config.fuseFodder = {}; persist() end },
        { Name = "Refresh", Callback = function() GUI.fodderSig = nil end },
    })
    return handle
end

function GUI.lbStatus()
    local Rqc = table.concat({
        tostring(Config.fuseUnit),
        table.concat(Config.fuseFodder or {
        },
        ","),
        tostring(Config.autoFuse),
        tostring(FarmHub.pickNote.autoFuse),
        tostring(Brain.fuseInfo and Brain.fuseInfo.uuid),
        tostring(App.where)
    }, "|")
    local Sqc = GUI._lb
    if Sqc and Sqc.key == Rqc and Utils.now() - Sqc.at < 15 then
        return Sqc.v
    end
    local Tqc = GUI.lbStatusNow()
    GUI._lb = {
        key = Rqc,
        at = Utils.now(),
        v = Tqc
    }
    return Tqc
end

function GUI.lbStatusNow()
    local Uqc = GUI.COL or {
    }
    if Config.fuseUnit == "" then
        return {
            icon = "🔥",
            title = "Pick a unit to limit break",
            text = "A limit break raises a unit's level cap (100 → 110). It takes a Divine Wish and fodder units, which are destroyed.",
            sub = "",
            tag = "",
            progress = false,
            color = Uqc.accent
        }
    end
    local Vqc = Core.session()
    local Wqc = Vqc and Vqc.collection:get_unit_by_uuid(Config.fuseUnit)
    if not Wqc then
        return {
            icon = "🔥",
            title = "That unit is gone",
            text = "Pick another one.",
            sub = "",
            tag = "",
            progress = false,
            color = Uqc.red
        }
    end
    if App.where == "lobby" and not (Brain.fuseInfo and Brain.fuseInfo.uuid == Wqc.uuid) and FarmHub.every("lbInfo", 10) then
        task.spawn(function()
            local Xqc, Yqc = App.request("fuseInfo", "request_fusion_information", Wqc.uuid)
            if Xqc and type(Yqc) == "table" then
                Brain.fuseInfo = {
                    requirement = Yqc.requirement,
                    divine_wish = Yqc.divine_wish,
                    allowed = Yqc.allowed,
                    uuid = Wqc.uuid
                }
                GUI._lb = nil
            end
        end)
    end
    local Zqc = Brain.fuseInfo and Brain.fuseInfo.uuid == Wqc.uuid
    local _qc = Zqc and tonumber(Brain.fuseInfo.requirement) or 12
    local arc = Zqc and tonumber(Brain.fuseInfo.divine_wish) or 1
    local brc, crc = Strategy.level(Wqc), Strategy.cap(Wqc)
    local drc
    if # (Config.fuseFodder or {
    }) > 0 then
        _, drc = FarmHub.fodderPicked(Wqc)
    else
        _, drc = FarmHub.fuseFuel(Wqc, _qc)
    end
    local erc = Adventure.have("divine_wish")
    local frc = brc >= crc and erc >= arc and drc >= _qc and not (Zqc and Brain.fuseInfo.allowed == false)
    local hrc = function(grc)
        return grc and "✓" or "✗"
    end
    return {
        icon = "🔥",
        title = Units.name(Wqc.unit_id) .. (Zqc and Brain.fuseInfo.allowed == false and " · can't be limit broken" or ""),
        text = string.format("Level %d/%d %s   ·   Divine Wish %d/%d %s   ·   Fodder %d/%d points %s%s",
        brc,
        crc,
        hrc(brc >= crc),
        erc,
        arc,
        hrc(erc >= arc),
        drc,
        _qc,
        hrc(drc >= _qc),
        Zqc and "" or " (requirement checked in the lobby)"),
        sub = FarmHub.pickNote.autoFuse or (Config.autoFuse and "Auto Limit Break is on: it fuses once everything is ✓, after showing what it uses for 30 s." or "Limit break is off. Review the fodder, then enable it in the target panel."),
        tag = frc and "READY" or "WAITING",
        tagColor = frc and Uqc.green or Uqc.orange,
        progress = math.min(1,
        drc / math.max(1,
        _qc)),
        color = frc and Uqc.green or Uqc.accent
    }
end

function GUI.homeRows()
    local function irc(jrc)
        local krc = tostring(jrc or ""):match("^[^\n]+") or ""
        if # krc > 130 then
            krc = krc:sub(1, 127):gsub("%s+%S*$", "") .. "…"
        end
        return krc
    end
    local function lrc(mrc)
        local nrc, orc = pcall(mrc)
        return nrc and irc(orc) or "…"
    end
    local prc = {
    }
    prc.Playing = Modes.onlyOn() and ("Only " .. Modes.onlyText()) or "Smart: whatever pays best (Farm → Stages)"
    prc.Focus = lrc(FarmHub.focusText)
    prc.Training = Config.trainTakedowns and lrc(Training.text) or "off"
    prc.Snipe = Config.snipeOn and Config.snipeUnit ~= "" and lrc(FarmHub.snipeText) or "off"
    if Config.fuseUnit ~= "" then
        local qrc, rrc = pcall(GUI.lbStatus)
        prc ["Limit Break"] = qrc and irc(rrc.title .. " · " .. tostring(rrc.tag):lower() .. " · " .. (tostring(rrc.text):gsub("%s+·%s+", " · "))) or "…"
    else
        prc ["Limit Break"] = "Choose a target in Units → Fusion"
    end
    prc.Team = Config.team and lrc(Strategy.text) or "off"
    return prc
end
GUI.HOME_KEYS = {
    "Playing",
    "Focus",
    "Training",
    "Snipe",
    "Limit Break",
    "Team"
}

function GUI.build()
    local trc = GUI.load()
    if not trc then
        warn("[AA] Robly Airflow failed to load — running without a window")
        return
    end
    GUI.theme(trc)
    local urc = GUI.window(trc)
    GUI.Win = urc
    local vrc, wrc = GUI.UI, GUI.LIVE
    local function xrc(yrc, zrc)
        Config [yrc] = zrc
        App.saveSoon()
    end
    local function Arc(Brc, Crc, Drc, Erc)
        vrc [Erc] = Brc:Toggle(Crc, Drc, Config [Erc], function(Frc)
            xrc(Erc, Frc)
        end)
    end
    local function Grc(Hrc, Irc, Jrc, Krc, Lrc)
        Lrc.default = Config [Krc]
        vrc [Krc] = Hrc:Slider(Irc, Jrc, Lrc, function(Mrc)
            xrc(Krc, Mrc)
        end)
    end
    local function Nrc(Orc)
        return tostring(math.floor(Orc + 0.5))
    end
    local function Prc(Qrc)
        return Utils.fmt(Qrc)
    end
    local Src = function(Rrc)
        return string.format("%d%%", math.floor(Rrc * 100 + 0.5))
    end
    local function Trc(Urc, Vrc, Wrc)
        pcall(function()
            urc:Notify(Urc, Vrc, 4, Wrc or "default")
        end)
    end
    local function Yrc(Zrc, _rc)
        local asc = pcall(GUI.banner, Zrc, _rc)
        if not asc then
            Zrc:Label(_rc)
        end
    end
    local bsc = urc:Tab("🏠", "Home")
    Yrc(bsc, "Turn it on and watch it work. Every other tab is for when you want to choose something yourself.")
    vrc.master = bsc:Toggle("Auto Farm", "Picks the modes, plays them and runs your picks. Off: it plays nothing, but the summons, fuses and stars you switched on still run in the lobby", Config.master, function(csc)
        xrc("master", csc)
        urc:Status(csc and "▶ Farming" or "⏸ Paused")
