    raid = "👹",
    event = "🃏",
    infinite = "♾️",
    dungeon = "🏰"
}

function GUI.keyName(Guc)
    if Guc == "dc" then
        return "📅 Daily Challenge"
    end
    if Guc == "ch" then
        return "🏆 Challenge"
    end
    if Guc == "dg" then
        return "🏰 Dungeon"
    end
    local Huc, Iuc, Juc = tostring(Guc):match("^(%a+):([^:]+):?(%a*)$")
    if not Iuc then
        return tostring(Guc)
    end
    return (({
        st = "⚔️ ",
        rd = "👹 ",
        ev = "🃏 ",
        inf = "♾️ "
    }) [Huc] or "") .. Modes.levelName(Iuc) .. ((Juc and Juc ~= "") and (" " .. Juc) or "")
end

function GUI.plainMode(Kuc)
    return string.format("%s · %.0f%% win · ≈%.0f gems/min", Kuc.label, (Kuc.p or 0) * 100, Kuc.score or 0)
end

function GUI.upNext(Luc, Muc)
    if not Luc then
        return "deciding…", ""
    end
    if App.where == "match" and Luc.kind == "story" and Luc.first and Luc.key == Match.key then
        local Nuc = "once this act is won. If it's lost, this act again"
        local Ouc, Puc = pcall(Core.PSC.get_next_story_level, Luc.level)
        if Config.onlyStory and Ouc and Puc then
            return Modes.levelName(Puc) .. " (" .. tostring(Luc.diff) .. ")", "The next act, " .. Nuc
        end
        if Muc then
            return GUI.plainMode(Muc), "The next best mode, " .. Nuc
        end
    end
    return GUI.plainMode(Luc), Luc.why or ""
end
GUI.STYLE_NAMES = {
    fast = "fast clear, at the road's start",
    balanced = "spread out along the road",
    box = "kill box, on the road's last stretch"
}

function GUI.simView(Quc)
    if App.where == "match" and Match.ld then
        local Ruc = Match.pred
        local Suc
        if not Ruc then
            Suc = (Match.planning or (Match.laneWant and not Match.laneCut)) and "Simulator: choosing spots…" or "Simulator: no prediction for this run"
        elseif Match.infinite then
            Suc = string.format("Simulator: the base falls at wave %d (%.0f min)", Ruc.wave or 0, (Ruc.t or 0) / 60)
        else
            Suc = string.format("Simulator: %s at wave %d (%.0f min)", Ruc.won and "a win" or "a loss", Ruc.wave or 0, (Ruc.t or 0) / 60)
        end
        local Tuc = {
        }
        if Match.style then
            table.insert(Tuc, "Placement: " .. (GUI.STYLE_NAMES [Match.style] or Match.style) .. (Match.styleWhy and (" (" .. tostring(Match.styleWhy) .. ")") or ""))
        end
        if Match.laneWant then
            table.insert(Tuc, Match.laneCut and string.format("lane %s, the one this portal opened (%d of %d)", Match.laneCut, Match.laneWant, Match.laneTotal or 0) or string.format("waiting for the first enemies to show which lane this portal opened (%d of %d)", Match.laneWant, Match.laneTotal or 0))
        end
        if Match.trainee and Brain.train.on then
            table.insert(Tuc, "training " .. Units.name(Brain.train.on.id))
        end
        local Uuc, Vuc, Wuc = "", nil, "no wave measured yet"
        local Xuc = Match.calRun and Match.calRun.alive or {
        }
        for Yuc = Match.wave(), 1, - 1 do
            local Zuc, _uc = tonumber(Xuc [tostring(Yuc)]), Ruc and Ruc.aliveAt and tonumber(Ruc.aliveAt [Yuc])
            if Zuc and _uc then
                local avc = 1000
                if Zuc < avc and _uc < avc then
                    Uuc, Vuc, Wuc = "ON TRACK", Quc.green, string.format("wave %d started with every enemy before it cleared, as the simulator expected", Yuc)
                elseif _uc < avc then
                    Uuc, Vuc, Wuc = "BEHIND", Quc.red, string.format("wave %d started with %s HP still alive where the simulator expected none", Yuc, Utils.fmt(Zuc))
                elseif Zuc < avc then
                    Uuc, Vuc, Wuc = "AHEAD", Quc.green, string.format("wave %d started with nothing left where the simulator expected %s HP", Yuc, Utils.fmt(_uc))
                else
                    local bvc = Zuc / _uc
                    Uuc = bvc <= 0.8 and "AHEAD" or (bvc <= 1.25 and "ON TRACK" or (bvc <= 2 and "BEHIND" or "FAR BEHIND"))
                    Vuc = bvc <= 1.25 and Quc.green or (bvc <= 2 and Quc.orange or Quc.red)
                    Wuc = string.format("wave %d started with %s HP alive, the simulator expected %s (%s)", Yuc, Utils.fmt(Zuc), Utils.fmt(_uc), bvc <= 0.8 and string.format("%.1f× easier", 1 / bvc) or (bvc <= 1.25 and "close" or string.format("%.1f× harder", bvc)))
                end
                break
            end
        end
        if FarmHub.every("simCardShares", 5) then
            local cvc, dvc = pcall(Match.damageShares)
            local evc = {
            }
            for fvc, gvc in pairs(cvc and type(dvc) == "table" and dvc or {
            }) do
                if gvc >= 0.01 then
                    table.insert(evc, {
                        n = Units.name(fvc):gsub(" %(.+%)",
                        ""),
                        v = gvc
                    })
                end
            end
            table.sort(evc, function(hvc, ivc)
                return hvc.v > ivc.v
            end)
            local jvc = {
            }
            for kvc = 1, math.min(4, # evc) do
                table.insert(jvc, string.format("%s %d%%", evc [kvc].n, math.floor(evc [kvc].v * 100 + 0.5)))
            end
            GUI.simShares = # jvc > 0 and ("damage: " .. table.concat(jvc, ", ")) or nil
        end
        return {
            icon = "🔮",
            title = Suc,
            text = # Tuc > 0 and table.concat(Tuc,
            " · ") or "",
            sub = Wuc .. (GUI.simShares and (" · " .. GUI.simShares) or ""),
            tag = Uuc,
            tagColor = Vuc
        }
    end
    local lvc = Modes.lastScored and Modes.lastScored [1]
    local mvc = lvc and Brain.simRes [lvc.key]
    local nvc = lvc and Brain.simTeam and Brain.simTeam [lvc.key]
    if not lvc then
        return {
            icon = "🔮",
            title = "Simulator",
            text = "waiting for the next pick",
            sub = "",
            tag = ""
        }
    end
    return {
        icon = "🔮",
        title = "Simulator: " .. tostring(lvc.label),
        text = mvc and (tostring(mvc.margin) .. (mvc.playing and (" · " .. tostring(mvc.playing)) or "")) or "no reading yet for this mode",
        sub = nvc and type(nvc.names) == "table" and ("team: " .. table.concat(nvc.names,
        ", ") .. (nvc.why and (" · " .. tostring(nvc.why)) or "")) or "",
        tag = mvc and (mvc.hopeless and "HOPELESS" or string.format("%d%%",
        math.floor((tonumber(lvc.p) or 0) * 100 + 0.5))) or "",
        tagColor = mvc and (mvc.hopeless and Quc.red or ((tonumber(lvc.p) or 0) >= 0.7 and Quc.green or Quc.orange)) or nil
    }
end

function GUI.update()
    local ovc = GUI.COL or {
    }
    local pvc = Core.prof() or {
    }
    if GUI.nowCard then
        local qvc
        if not Config.master then
            qvc = {
                icon = "⏸",
                title = "Paused",
                text = "Turn Auto Farm on to resume",
                sub = "",
                tag = "",
                progress = false,
                color = ovc.sub
            }
        elseif App.where == "match" and Match.ld then
            local rvc = Modes.levelName(Match.ld.id or "?") .. (Match.ld._difficulty and (" (" .. Match.ld._difficulty .. ")") or "")
            local tvc = Match.pressure or 0
            local uvc = (Brain.pending and Brain.pending.key == Match.key and Brain.pending.label) and "launched by the farm" or "playing this match"
            local vvc = Match.depth or {
            }
            local wvc = (vvc.units or 0) > 0 and Utils.clamp(vvc.covEnd or 0.6, 0.1, 1) or 0.6
            local xvc = vvc.leak or tvc >= math.min(Config.dangerReach, wvc * 0.9)
            local yvc = tvc >= math.min(Config.safeReach, wvc * 0.75)
            qvc = {
                icon = GUI.ICONS [Match.kind or ""] or "⚔️",
                title = rvc,
                text = tostring(Status.Economy or uvc),
                sub = string.format("Wave %d/%d · ¥%s · %d enemies · front at %d%% of the road, your units reach %d%% · kills all in %s",
                Match.wave(),
                Match.total or 0,
                Utils.fmt(Match.money()),
                # (Match.enemies or {
                }),
                math.floor(tvc * 100),
                math.floor(((vvc.units or 0) > 0 and vvc.covEnd or 0) * 100),
                (Match.clearSec or 0) >= 999 and "never" or (math.floor(Match.clearSec or 0) .. "s")),
                tag = vvc.leak and "LEAK" or (xvc and "DANGER" or (yvc and "PRESSURE" or "SAFE")),
                tagColor = xvc and ovc.red or (yvc and ovc.orange or ovc.green),
                progress = (Match.total or 0) > 0 and Match.wave() / Match.total or false,
                color = ovc.accent
            }
        else
            qvc = {
                icon = "🏰",
                title = "In the lobby",
                text = tostring(Status.Mode or "planning the next run"),
                sub = tostring(Status.Rewards or ""),
                tag = "",
                progress = false,
                color = ovc.accent
            }
        end
        pcall(GUI.nowCard.Set, qvc)
        pcall(function()
            GUI.Win:Status((qvc.icon or "") .. " " .. tostring(qvc.title), qvc.tagColor or qvc.color)
        end)
    end
    if GUI.simCard then
        local zvc, Avc = pcall(GUI.simView, ovc)
        if zvc and Avc then
            pcall(GUI.simCard.Set, Avc)
        end
    end
    if GUI.nextCard then
        local Bvc = Modes.lastScored and Modes.lastScored [1]
        if not Bvc and Utils.now() - (GUI.pickAt or 0) > 15 then
            GUI.pickAt = Utils.now()
            pcall(Modes.pick)
            Bvc = Modes.lastScored and Modes.lastScored [1]
        end
        local Cvc = Brain.lastResult
        local Dvc = {
        }
        if Cvc then
            if (Cvc.gems or 0) > 0 then
                table.insert(Dvc, Cvc.gems .. " gems")
            end
            if (Cvc.coins or 0) > 0 then
                table.insert(Dvc, Cvc.coins .. " " .. Modes.coinName())
            end
            for Evc, Fvc in pairs(Cvc.items or {
            }) do
                table.insert(Dvc, string.format("%s×%s", (Core.Items [Evc] and Core.Items [Evc].name) or Evc, tostring(Fvc)))
            end
        end
        local Gvc, Hvc = GUI.upNext(Bvc, Modes.lastScored and Modes.lastScored [2])
        pcall(GUI.nextCard.Set, {
            icon = "⏭",
            title = "Up next: " .. Gvc,
            text = Hvc,
            sub = Cvc and ("Last run: " .. Cvc.text .. (# Dvc > 0 and (" · " .. table.concat(Dvc,
            ", ")) or "")) or "",
            tag = Cvc and (Cvc.won and "WON" or "LOST") or "",
            tagColor = Cvc and (Cvc.won and ovc.green or ovc.red) or nil
        })
    end
    if GUI.goals then
        local Ivc = GUI.goals
        pcall(Ivc.Set, "Gems", Utils.fmt(pvc.gem_amount), string.format("gold %s", Utils.fmt(pvc.gold_amount)), nil, nil)
        local Jvc = Brain.live.daily
        local Kvc = Jvc and Jvc.uuid and (Jvc.uuid == pvc.last_completed_daily_challenge_uuid or Jvc.uuid == Jvc.doneUuid)
        pcall(Ivc.Set, "Daily Challenge", Kvc and "done ✓" or (Jvc and "ready" or "…"), Jvc and string.format("worth ≈%s gems", Utils.fmt(Jvc.value or 0)) or "", Kvc and ovc.green or ovc.gold, nil)
        local Lvc = Brain.live.normal
        local Mvc = Lvc and Lvc.uuid and (Lvc.uuid == pvc.last_completed_challenge_uuid or Lvc.uuid == Lvc.doneUuid)
        local Nvc = Lvc and Lvc.expires and math.max(0, math.floor((Lvc.expires - os.time()) / 60)) or 0
        pcall(Ivc.Set, "Challenge", Mvc and "done ✓" or (Lvc and "open" or "…"), Lvc and string.format("new one in %d min", Nvc) or "", Mvc and ovc.green or ovc.gold, nil)
        local Ovc = 0
        for Pvc, Qvc in ipairs(Modes.lastScored or {
        }) do
            if Qvc.first then
                Ovc = Ovc + 1
            end
        end
        pcall(Ivc.Set, "First Clears Left", tostring(Ovc), "acts you can clear for 60 gems now", Ovc > 0 and ovc.purple or ovc.green, nil)
        pcall(Ivc.Set, "Summer Pearls", Utils.fmt(pvc.resources and pvc.resources.SummerPearls or 0), "a Sunny Star costs 150", nil, nil)
        pcall(Ivc.Set, "Record", string.format("%d W · %d L", Brain.totals.wins or 0, Brain.totals.losses or 0), string.format("+%s gems by the farm", Utils.fmt(Brain.totals.gems or 0)), nil, nil)
    end
    if GUI.systems then
        for Rvc, Svc in ipairs(GUI.SYSTEMS) do
            local Tvc = Status [Svc]
            local Uvc = tostring(Tvc or "—")
            pcall(GUI.systems.Set, Svc, Uvc, (Uvc:find("refused") or Uvc:find("error")) and ovc.red or (Tvc and ovc.text or ovc.sub))
        end
    end
    if GUI.rank then
        local Vvc = Modes.lastScored or {
        }
        for Wvc = 1, 6 do
            local Xvc = Vvc [Wvc]
            if Xvc then
                pcall(GUI.rank.Set, "#" .. Wvc, GUI.plainMode(Xvc) .. "\n" .. (Xvc.why or ""), Wvc == 1 and ovc.green or ovc.text)
            else
                pcall(GUI.rank.Set, "#" .. Wvc, Wvc == 1 and "no ranking yet" or "", ovc.sub, Wvc == 1 and "#1" or "")
            end
        end
    end
    if GUI.records then
        local Yvc = {
        }
        for Zvc, _vc in pairs(Brain.modes) do
            if _vc.runs > 0 then
                table.insert(Yvc, {
                    key = Zvc,
                    r = _vc
                })
            end
        end
        table.sort(Yvc, function(awc, bwc)
            return (awc.r.last or 0) > (bwc.r.last or 0)
        end)
        for cwc = 1, 8 do
            local dwc = Yvc [cwc]
            if dwc then
                local ewc = dwc.key == "dc" and "📅 Daily Challenge" or dwc.key == "ch" and "🏆 Challenge" or Modes.levelName((dwc.key:match("^%a+:([^:]+)") or dwc.key)) .. (dwc.key:match(":(%a+)$") and (" " .. dwc.key:match(":(%a+)$")) or "")
                pcall(GUI.records.Set, tostring(cwc), string.format("%d/%d won · %.1f min avg · %d gems", dwc.r.wins, dwc.r.runs, dwc.r.sec / math.max(1, dwc.r.runs) / 60, dwc.r.gems), nil, ewc)
            else
                pcall(GUI.records.Set, tostring(cwc), "", nil, cwc == 1 and "no runs yet" or "")
            end
        end
    end
    if GUI.team then
        local fwc = Units.equipped()
        for gwc = 1, 6 do
            local hwc = fwc [gwc]
