        end
    end
    if GUI.sim then
        local rwc = Modes.lastScored and Modes.lastScored [1]
        local swc = rwc and Brain.simRes [rwc.key]
        pcall(GUI.sim.Set, "Next mode", rwc and (rwc.label .. ": " .. (swc and (swc.playing or swc.margin) or (swc and swc.none and "can't simulate this one yet") or "not simulated yet")) or "—")
