        pcall(GUI.sim.Set, "Best team", uwc and (table.concat(uwc.names or {
        }, ", ") .. (uwc.better and (" → " .. (uwc.won and "wins" or ("reaches wave " .. tostring(uwc.wave)))) or " (your team is already the best the sim found)")) or "—")
