            tostring(Config.fuseUnit)
        }
        for hxc, ixc in ipairs(fxc) do
            table.insert(gxc, ixc.uuid .. ":" .. ixc.pts .. ":" .. # ixc.flags .. (ixc.safe and "s" or ""))
        end
