        if GUI.fodderSig ~= gxc then
            GUI.fodderSig = gxc
            pcall(GUI.fodder.Refresh, fxc, dxc and "Nothing the game would take for this unit. Locked and equipped units never show." or "Pick a unit to limit break above, and the units it could use show here.")
        else
            pcall(GUI.fodder.summary)
        end
    end
    if Swc.hunt and FarmHub.every("huntText", 5) then
        pcall(function()
            Swc.hunt.Set(Hunt.text())
        end)
