    if Swc.skins and FarmHub.every("skinText", 8) then
        pcall(function()
            Swc.skins.Set(Hunt.skinText())
        end)
    end
    if Swc.fusePick and FarmHub.every("fuseText", 8) then
        pcall(function()
            Swc.fusePick.Set(FarmHub.fuseText())
        end)
    end
    if Swc.fuseXpPick and FarmHub.every("fuseXpText", 8) then
        pcall(function()
            Swc.fuseXpPick.Set(FarmHub.fuseXpText())
        end)
    end
    if Swc.focus and FarmHub.every("focusText", 3) then
        pcall(function()
            Swc.focus.Set(FarmHub.focusText())
        end)
    end
    if Swc.teamNext and FarmHub.every("teamText", 3) then
        pcall(function()
            Swc.teamNext.Set(Strategy.text())
        end)
    end
    if GUI.core and FarmHub.every("coreRows", 8) then
        local jxc, kxc = pcall(Strategy.rows)
        for lxc = 1, 8 do
            local mxc = jxc and kxc [lxc]
            if mxc then
                pcall(GUI.core.Set, tostring(lxc), mxc.text, mxc.text:find("next:") and ovc.text or ovc.green, mxc.name)
            else
                pcall(GUI.core.Set, tostring(lxc), "", nil, lxc == 1 and (jxc and "no core units yet" or ("error: " .. tostring(kxc))) or "")
            end
        end
    end
    local nxc = false
    for oxc in pairs(GUI.lists) do
        if GUI.listEmpty [oxc] then
            nxc = true
            break
        end
    end
    if (App.where == "lobby" and FarmHub.every("pickLists", 30)) or (nxc and Core.session() and FarmHub.every("pickListsEarly", 5)) then
        for pxc, qxc in pairs(GUI.lists) do
            if App.where == "lobby" or GUI.listEmpty [pxc] then
                local rxc, sxc = pcall(qxc)
                if rxc then
                    local txc = GUI.sigOf(sxc)
                    if GUI.listSig [pxc] ~= txc then
                        pcall(GUI.UI [pxc .. "Pick"].Refresh, sxc, Config [pxc])
                        if GUI.listEmpty [pxc] and # sxc > 1 then
                            App.log(1, "INFO", string.format("the window opened before the game had your units: %s's list filled in %d s later", pxc, math.floor(Utils.now() - (GUI.listAt or Utils.now()))))
                        end
                    end
                    GUI.listSig [pxc] = txc
                    if Core.session() then
                        GUI.listEmpty [pxc] = nil
                    end
                end
            end
        end
    end
    if Swc.train then
        pcall(Swc.train.Set, Training.text())
    end
    if Swc.community and FarmHub.every("communityText", 30) then
        pcall(Swc.community.Set, Adventure.communityText())
    end
    if Swc.goal and FarmHub.every("goalText", 5) then
        pcall(Swc.goal.Set, Adventure.goalText())
    end
    if Swc.fh and FarmHub.every("fhText", 10) then
        pcall(Swc.fh.Set, Match.fhText())
    end
    if Swc.dungeon and FarmHub.every("dgText", 5) then
        pcall(Swc.dungeon.Set, Dungeon.text())
    end
    if Swc.lb then
        pcall(Swc.lb.Set, Adventure.lbText())
    end
    if GUI.econCard and App.where == "match" then
        pcall(GUI.econCard.Set, {
            icon = "💰",
            title = string.format("¥%s now · farm ¥%s a wave",
            Utils.fmt(Match.money()),
            Utils.fmt(Match.farmNow or 0)),
            text = tostring(Status.Economy or ""),
            sub = string.format("coming yen ≈%s · still to buy ≈%s",
            Utils.fmt(Match.future or 0),
            Utils.fmt(Match.wantLeft or 0))
        })
    end
    local uxc = GUI.LIVE
    if uxc.spend then
        pcall(uxc.spend.Set, Spending.text())
    end
    if uxc.lastMatch then
        local vxc = Brain.lastMatch
        pcall(uxc.lastMatch.Set, vxc and string.format("Last match (%s): ¥%s spent on %d buys · %d refused spots", vxc.label, Utils.fmt(vxc.spent), vxc.actions or 0, vxc.refusals or 0) or "no match yet")
    end
    if uxc.totals then
        pcall(uxc.totals.Set, string.format("matches %d · wins %d · losses %d · gems %s · event coins %s", Brain.totals.matches or 0, Brain.totals.wins or 0, Brain.totals.losses or 0, Utils.fmt(Brain.totals.gems or 0), Utils.fmt(Brain.totals.coins or 0)))
    end
end

function GUI.loop()
    while App.alive do
        pcall(GUI.update)
        task.wait(1)
    end
end
table.insert(App.conns, LocalPlayer.Idled:Connect(function()
    if not Config.antiAfk then
        return
    end
    pcall(function()
        local wxc = game:GetService("VirtualUser")
        wxc:CaptureController()
        wxc:ClickButton2(Vector2.new())
    end)
end))

function App.cleanup()
    for xxc, yxc in ipairs(App.conns) do
        pcall(function()
            yxc:Disconnect()
        end)
    end
    pcall(function()
        GUI.Win:Destroy()
    end)
    pcall(function()
        if Match.probe then
            Match.probe:Destroy()
        end
    end)
    pcall(function()
        if Match.bounds then
            Match.bounds:Destroy()
        end
    end)
end

function App.unload()
    App.alive = false
    App.saveNow()
    pcall(FarmHub.quietFx, true)
    App.cleanup()
    _G.AA_SF = nil
end

function App.restart()
    local zxc, Axc = loadstring(readfile(Core.SELF), "=RobScript_Team_Anime_Adventures")
    assert(zxc, Axc)
    App.unload()
    zxc()
end
